/*A C# program to introduce Binary Tree*/

using System;

/* Class containing left and right child
of current node and key value*/

public class Node
{
    public int key;
    public Node left, right;
    public Node(int item)
    {
        key = item;
        left = right = null;
    }
}

/*Binary Tree*/
public class BinaryTree
{
    Node root;
    BinaryTree(int key)
    {
        root = new Node(key);
    }
    BinaryTree()
    {
        root = null;
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
    }
}

/*C# program to insert element in binary tree*/

using System;
using System.Collections.Generic;
class GFG {

/* A binary tree node has key, pointer to
    left child and a pointer to right child */

    public class Node {
        public int key;
        public Node left, right;

/*        constructor*/

        public Node(int key)
        {
            this.key = key;
            left = null;
            right = null;
        }
    }
    static Node root;

/* Inorder traversal of a binary tree*/

    static void inorder(Node temp)
    {
        if (temp == null)
            return;
        inorder(temp.left);
        Console.Write(temp.key + " ");
        inorder(temp.right);
    }

/*function to insert element in binary tree */

    static void insert(Node temp, int key)
    {
          if (temp == null) {
            root = new Node(key);
            return;
        }
        Queue<Node> q = new Queue<Node>();
        q.Enqueue(temp);

/*        Do level order traversal until we find
        an empty place.*/

        while (q.Count != 0) {
            temp = q.Peek();
            q.Dequeue();
            if (temp.left == null) {
                temp.left = new Node(key);
                break;
            }
            else
                q.Enqueue(temp.left);
            if (temp.right == null) {
                temp.right = new Node(key);
                break;
            }
            else
                q.Enqueue(temp.right);
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        root = new Node(10);
        root.left = new Node(11);
        root.left.left = new Node(7);
        root.right = new Node(9);
        root.right.left = new Node(15);
        root.right.right = new Node(8);
        Console.Write(
            "Inorder traversal before insertion:");
        inorder(root);
        int key = 12;
        insert(root, key);
        Console.Write(
            "\nInorder traversal after insertion:");
        inorder(root);
    }
}

/*C# implementation of tree using array
numbering starting from 0 to n-1.*/

using System;
class Array_imp {
    static int root = 0;
    static String[] str = new String[10];

/*create root*/

    public void Root(String key)
    {
        str[0] = key;
    }

/*create left son of root*/

    public void set_Left(String key, int root)
    {
        int t = (root * 2) + 1;
        if (str[root] == null) {
            Console.Write("Can't set child at {0}, no parent found\n", t);
        }
        else {
            str[t] = key;
        }
    }

/*create right son of root*/

    public void set_Right(String key, int root)
    {
        int t = (root * 2) + 2;
        if (str[root] == null) {
            Console.Write("Can't set child at {0}, no parent found\n", t);
        }
        else {
            str[t] = key;
        }
    }

/*Print tree*/

    public void print_Tree()
    {
        for (int i = 0; i < 10; i++) {
            if (str[i] != null)
                Console.Write(str[i]);
            else
                Console.Write("-");
        }
    }
}

/*Driver Code*/

public class Tree {
    public static void Main(String[] args)
    {
        Array_imp obj = new Array_imp();
        obj.Root("A");
        obj.set_Right("C", 0);
        obj.set_Left("D", 1);
        obj.set_Right("E", 1);
        obj.set_Left("F", 2);
        obj.print_Tree();
    }
}

/*C# program of AVL tree that
handles duplicates*/

using System;
class GFG {

/*    An AVL tree node*/

    class node {
        public int key;
        public node left;
        public node right;
        public int height;
        public int count;
    }

/*    A utility function to get
    height of the tree*/

    static int height(node N)
    {
        if (N == null)
            return 0;
        return N.height;
    }

/*    A utility function to get
    maximum of two integers*/

    static int max(int a, int b)
    {
        return (a > b) ? a : b;
    }

/* Helper function that allocates a 
    new node with the given key and 
    null left and right pointers. */

    static node newNode(int key)
    {
        node node = new node();
        node.key = key;
        node.left = null;
        node.right = null;

/*new node is initially added at leaf*/

node.height = 1; 
        node.count = 1;
        return (node);
    }

/*    A utility function to right
    rotate subtree rooted with y
    See the diagram given above.*/

    static node rightRotate(node y)
    {
        node x = y.left;
        node T2 = x.right;

/*        Perform rotation*/

        x.right = y;
        y.left = T2;

/*        Update heights*/

        y.height = max(height(y.left),
                       height(y.right))
                   + 1;
        x.height = max(height(x.left),
                       height(x.right))
                   + 1;

/*        Return new root*/

        return x;
    }

/*    A utility function to left
    rotate subtree rooted with x
    See the diagram given above.*/

    static node leftRotate(node x)
    {
        node y = x.right;
        node T2 = y.left;

/*        Perform rotation*/

        y.left = x;
        x.right = T2;

/*        Update heights*/

        x.height = max(height(x.left),
                       height(x.right))
                   + 1;
        y.height = max(height(y.left),
                       height(y.right))
                   + 1;

/*        Return new root*/

        return y;
    }

/*    Get Balance factor of node N*/

    static int getBalance(node N)
    {
        if (N == null)
            return 0;
        return height(N.left) - height(N.right);
    }
    static node insert(node node, int key)
    {

/*1. Perform the normal BST rotation */

        if (node == null)
            return (newNode(key));

/*        If key already exists in BST,
        icnrement count and return*/

        if (key == node.key) {
            (node.count)++;
            return node;
        }

/* Otherwise, recur down the tree */

        if (key < node.key)
            node.left = insert(node.left, key);
        else
            node.right = insert(node.right, key);

/* 2. Update height of this 
          ancestor node */

        node.height = max(height(node.left),
                          height(node.right))
                      + 1;

/* 3. Get the balance factor of 
    this ancestor node to check whether 
    this node became unbalanced */

        int balance = getBalance(node);

/*        If this node becomes unbalanced,
        then there are 4 cases
        Left Left Case*/

        if (balance > 1 && key < node.left.key)
            return rightRotate(node);

/*        Right Right Case*/

        if (balance < -1 && key > node.right.key)
            return leftRotate(node);

/*        Left Right Case*/

        if (balance > 1 && key > node.left.key) {
            node.left = leftRotate(node.left);
            return rightRotate(node);
        }

/*        Right Left Case*/

        if (balance < -1 && key < node.right.key) {
            node.right = rightRotate(node.right);
            return leftRotate(node);
        }

/* return the (unchanged)
       node pointer */

        return node;
    }

/* Given a non-empty binary search 
   tree, return the node with minimum 
   key value found in that tree. Note 
   that the entire tree does not 
   need to be searched. */

    static node minValueNode(node node)
    {
        node current = node;

/* loop down to find the
       leftmost leaf */

        while (current.left != null)
            current = current.left;
        return current;
    }
    static node deleteNode(node root, int key)
    {

/*        STEP 1: PERFORM STANDARD BST DELETE*/

        if (root == null)
            return root;

/*        If the key to be deleted is
        smaller than the root's key,
        then it lies in left subtree*/

        if (key < root.key)
            root.left = deleteNode(root.left, key);

/*        If the key to be deleted is
        greater than the root's key,
        then it lies in right subtree*/

        else if (key > root.key)
            root.right = deleteNode(root.right, key);

/*        if key is same as root's key,
        then this is the node to be deleted*/

        else {

/*            If key is present more than
            once, simply decrement
            count and return*/

            if (root.count > 1) {
                (root.count)--;
                return null;
            }

/*            ElSE, delete the node
            node with only one child
            or no child*/

            if ((root.left == null) || (root.right == null)) {
                node temp = root.left != null ? root.left : root.right;

/*                No child case*/

                if (temp == null) {
                    temp = root;
                    root = null;
                }

/*One child case*/

else

/*Copy the contents of the non-empty child*/

root = temp; 
            }
            else {

/*                node with two children: Get
                the inorder successor (smallest
                in the right subtree)*/

                node temp = minValueNode(root.right);

/*                Copy the inorder successor's
                data to this node and update the count*/

                root.key = temp.key;
                root.count = temp.count;
                temp.count = 1;

/*                Delete the inorder successor*/

                root.right = deleteNode(root.right,
                                        temp.key);
            }
        }

/*        If the tree had only one
        node then return*/

        if (root == null)
            return root;

/*        STEP 2: UPDATE HEIGHT OF
        THE CURRENT NODE*/

        root.height = max(height(root.left),
                          height(root.right))
                      + 1;

/*        STEP 3: GET THE BALANCE FACTOR
        OF THIS NODE (to check whether
        this node became unbalanced)*/

        int balance = getBalance(root);

/*        If this node becomes unbalanced,
        then there are 4 cases
        Left Left Case*/

        if (balance > 1 && getBalance(root.left) >= 0)
            return rightRotate(root);

/*        Left Right Case*/

        if (balance > 1 && getBalance(root.left) < 0) {
            root.left = leftRotate(root.left);
            return rightRotate(root);
        }

/*        Right Right Case*/

        if (balance < -1 && getBalance(root.right) <= 0)
            return leftRotate(root);

/*        Right Left Case*/

        if (balance < -1 && getBalance(root.right) > 0) {
            root.right = rightRotate(root.right);
            return leftRotate(root);
        }
        return root;
    }

/*    A utility function to print
    preorder traversal of the tree.
    The function also prints height
    of every node*/

    static void preOrder(node root)
    {
        if (root != null) {
            Console.Write(root.key + "(" + root.count + ") ");
            preOrder(root.left);
            preOrder(root.right);
        }
    }

/*    Driver Code*/

    static public void Main(String[] args)
    {
        node root = null;

/* Coning tree given in 
       the above figure */

        root = insert(root, 9);
        root = insert(root, 5);
        root = insert(root, 10);
        root = insert(root, 5);
        root = insert(root, 9);
        root = insert(root, 7);
        root = insert(root, 17);
        Console.Write("Pre order traversal of "
                      + "the constructed AVL tree is \n");
        preOrder(root);
        deleteNode(root, 9);
        Console.Write("\nPre order traversal after "
                      + "deletion of 9 \n");
        preOrder(root);
    }
}

/*C# program to check if a tree is continuous or not*/

using System;
class solution
{

/* A binary tree node has data, pointer to left child
and a pointer to right child */

class Node
{
    public int data;
    public Node left, right;
};

/* Helper function that allocates a new node with the
given data and null left and right pointers. */

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return(node);
}

/*Function to check tree is continuous or not*/

static Boolean treeContinuous( Node ptr)
{

/*    if next node is empty then return true*/

    if (ptr == null)
        return true;

/*    if current node is leaf node then return true
    because it is end of root to leaf path*/

    if (ptr.left == null && ptr.right == null)
        return true;

/*    If left subtree is empty, then only check right*/

    if (ptr.left == null)
    return (Math.Abs(ptr.data - ptr.right.data) == 1) &&
            treeContinuous(ptr.right);

/*    If right subtree is empty, then only check left*/

    if (ptr.right == null)
    return (Math.Abs(ptr.data - ptr.left.data) == 1) &&
            treeContinuous(ptr.left);

/*    If both left and right subtrees are not empty, check
    everything*/

    return Math.Abs(ptr.data - ptr.left.data)==1 &&
            Math.Abs(ptr.data - ptr.right.data)==1 &&
            treeContinuous(ptr.left) &&
            treeContinuous(ptr.right);
}

/* Driver program to test mirror() */

static public void Main(String []args)
{
    Node root = newNode(3);
    root.left     = newNode(2);
    root.right     = newNode(4);
    root.left.left = newNode(1);
    root.left.right = newNode(3);
    root.right.right = newNode(5);
    if(treeContinuous(root))
    Console.WriteLine( "Yes") ;
    else
    Console.WriteLine( "No");
}
}

/*C# Code to check if the tree is continuos or not*/

using System;
using System.Collections.Generic;
class GFG
{

/*  Node structure*/

  public
    class node
    {
      public
        int val;
      public
        node left;
      public
        node right;
      public node()
      {
        this.val = 0;
        this.left = null;
        this.right = null;  
      }
      public node(int x)
      {
        this.val = x;
        this.left = null;
        this.right = null;
      }
      public node(int x, node left, node right)
      {
        this.val = x;
        this.left = left;
        this.right = right;   
      }
    };

/*  Function to check if the tree is continuos or not*/

  static bool continuous(node root)
  {

/*    If root is Null then tree isn't Continuos*/

    if (root == null)
      return false;
    int flag = 1;
    Queue<node> Q = new Queue<node>();
    Q.Enqueue(root);
    node temp;

/*    BFS Traversal*/

    while (Q.Count != 0)
    {
      temp = Q.Peek();
      Q.Dequeue();

/*      Move to left child*/

      if (temp.left != null)
      {

/*        if difference between parent and child is
        equal to 1 then do continue otherwise make
        flag = 0 and break*/

        if (Math.Abs(temp.left.val - temp.val) == 1)
          Q.Enqueue(temp.left);
        else
        {
          flag = 0;
          break;
        }
      }

/*      Move to right child*/

      if (temp.right != null)
      {

/*        if difference between parent and child is
        equal to 1 then do continue otherwise make
        flag = 0 and break*/

        if (Math.Abs(temp.right.val - temp.val) == 1)
          Q.Enqueue(temp.right);
        else           
        {
          flag = 0;
          break;
        }
      }
    }
    if (flag != 0)
      return true;
    else
      return false;
  }

/*  Driver Code*/

  public static void Main(String[] args)
  {

/*    Constructing the Tree*/

    node root = new node(3);
    root.left = new node(2);
    root.right = new node(4);
    root.left.left = new node(1);
    root.left.right = new node(3);
    root.right.right = new node(5);

/*    Function Call*/

    if (continuous(root))
      Console.Write("True\n");
    else
      Console.Write("False\n");
  }
}

/*C# program to check foldable binary tree*/

using System;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

public class Node {
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree {
    Node root;

/* Returns true if the given tree can be folded */

    bool IsFoldable(Node node)
    {
        if (node == null)
            return true;
        return IsFoldableUtil(node.left, node.right);
    }

/* A utility function that checks if
    trees with roots as n1 and n2
    are mirror of each other */

    bool IsFoldableUtil(Node n1, Node n2)
    {

/* If both left and right subtrees are NULL,
        then return true */

        if (n1 == null && n2 == null)
            return true;

/* If one of the trees is NULL and other is not,
        then return false */

        if (n1 == null || n2 == null)
            return false;

/* Otherwise check if left and right subtrees are
        mirrors of their counterparts */

        return IsFoldableUtil(n1.left, n2.right)
            && IsFoldableUtil(n1.right, n2.left);
    }

/* Driver code */

    public static void Main(String[] args)
    {
        BinaryTree tree = new BinaryTree();

/* The constructed binary tree is
            1
        / \
        2     3
        \ /
            4 5
        */

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.right.left = new Node(4);
        tree.root.left.right = new Node(5);
        if (tree.IsFoldable(tree.root))
            Console.WriteLine("tree is foldable");
        else
            Console.WriteLine("Tree is not foldable");
    }
}

/*C# program to construct an expression tree*/

using System;
using System.Collections;

/*An expression tree node*/

public class Node
{
    public char value;
    public Node left, right;
    public Node(char item)
    {
        value = item;
        left = right = null;
    }
}
class ExpressionTree
{

/*    A utility function to check if 'c'
    is an operator*/

    Boolean isOperator(char c)
    {
        if (c == '+' || c == '-' || c == '*'
            || c == '/' || c == '^')
        {
            return true;
        }
        return false;
    }

/*    Utility function to do inorder traversal*/

    void inorder(Node t)
    {
        if (t != null)
        {
            inorder(t.left);
            Console.Write(t.value + " ");
            inorder(t.right);
        }
    }

/*    Returns root of constructed tree for given
    postfix expression*/

    Node constructTree(char []postfix)
    {
        Stack st = new Stack();
        Node t, t1, t2;

/*        Traverse through every character of
        input expression*/

        for (int i = 0; i < postfix.Length; i++)
        {

/*            If operand, simply Push into stack*/

            if (!isOperator(postfix[i]))
            {
                t = new Node(postfix[i]);
                st.Push(t);
            }

/*operator*/

else 
            {
                t = new Node(postfix[i]);

/*                Pop two top nodes
                Store top
Remove top*/

t1 = (Node)st.Pop();     
                t2 = (Node)st.Pop();

/*                make them children*/

                t.right = t1;
                t.left = t2;

/*                System.out.println(t1 + "" + t2);
                Add this subexpression to stack*/

                st.Push(t);
            }
        }

/*        only element will be root of
        expression tree*/

        t = (Node)st.Peek();
        st.Pop();
        return t;
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        ExpressionTree et = new ExpressionTree();
        String postfix = "ab+ef*g*-";
        char[] charArray = postfix.ToCharArray();
        Node root = et.constructTree(charArray);
        Console.WriteLine("infix expression is");
        et.inorder(root);
    }
}

/*C# program to check is binary
tree is symmetric or not*/

using System;

/*A Binary Tree Node*/

class Node {
    public int key;
    public Node left, right;
    public Node(int item)
    {
        key = item;
        left = right = null;
    }
}
class GFG {
    Node root;

/*    returns true if trees with roots
    as root1 and root2 are mirror*/

    Boolean isMirror(Node node1, Node node2)
    {

/*        if both trees are empty,
        then they are mirror image*/

        if (node1 == null && node2 == null)
            return true;

/*        For two trees to be mirror images,
        the following three conditions must be true
        1 - Their root node's key must be same
        2 - left subtree of left tree and right
        subtree of right tree have to be mirror images
        3 - right subtree of left tree and left subtree
        of right tree have to be mirror images*/

        if (node1 != null && node2 != null
            && node1.key == node2.key)
            return (isMirror(node1.left, node2.right)
                    && isMirror(node1.right, node2.left));

/*        if none of the above conditions
        is true then root1 and root2 are
        mirror images*/

        return false;
    }

/*    returns true if the tree is symmetric
    i.e mirror image of itself*/

    Boolean isSymmetric()
    {

/*        check if tree is mirror of itself*/

        return isMirror(root, root);
    }

/*    Driver Code*/

    static public void Main(String[] args)
    {

/*    Let us construct the Tree shown in the above figure*/

        GFG tree = new GFG();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);
        tree.root.left.right = new Node(4);
        tree.root.right.left = new Node(4);
        tree.root.right.right = new Node(3);
        Boolean output = tree.isSymmetric();
        if (output == true)
            Console.WriteLine("Symmetric");
        else
            Console.WriteLine("Not symmetric");
    }
}

/*C# program for different
tree traversals*/

using System;

/* Class containing left and
right child of current
node and key value*/

class Node {
    public int key;
    public Node left, right;
    public Node(int item)
    {
        key = item;
        left = right = null;
    }
}
class BinaryTree {

/*    Root of Binary Tree*/

    Node root;
    BinaryTree() { root = null; }

/* Given a binary tree, print
       its nodes according to the
       "bottom-up" postorder traversal. */

    void printPostorder(Node node)
    {
        if (node == null)
            return;

/*        first recur on left subtree*/

        printPostorder(node.left);

/*        then recur on right subtree*/

        printPostorder(node.right);

/*        now deal with the node*/

        Console.Write(node.key + " ");
    }

/* Given a binary tree, print
       its nodes in inorder*/

    void printInorder(Node node)
    {
        if (node == null)
            return;

/* first recur on left child */

        printInorder(node.left);

/* then print the data of node */

        Console.Write(node.key + " ");

/* now recur on right child */

        printInorder(node.right);
    }

/* Given a binary tree, print
       its nodes in preorder*/

    void printPreorder(Node node)
    {
        if (node == null)
            return;

/* first print data of node */

        Console.Write(node.key + " ");

/* then recur on left sutree */

        printPreorder(node.left);

/* now recur on right subtree */

        printPreorder(node.right);
    }

/*    Wrappers over above recursive functions*/

    void printPostorder() { printPostorder(root); }
    void printInorder() { printInorder(root); }
    void printPreorder() { printPreorder(root); }

/*    Driver Code*/

    static public void Main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        Console.WriteLine("Preorder traversal "
                          + "of binary tree is ");
        tree.printPreorder();
        Console.WriteLine("\nInorder traversal "
                          + "of binary tree is ");
        tree.printInorder();
        Console.WriteLine("\nPostorder traversal "
                          + "of binary tree is ");
        tree.printPostorder();
    }
}

/*Non-recursive C# program for inorder traversal*/

using System;
using System.Collections.Generic;

/* Class containing left and right child of
current node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/* Class to print the inorder traversal */

public class BinaryTree
{
    public Node root;
    public virtual void inorder()
    {
        if (root == null)
        {
            return;
        }
        Stack<Node> s = new Stack<Node>();
        Node curr = root;

/*        traverse the tree*/

        while (curr != null || s.Count > 0)
        {

/* Reach the left most Node of the
            curr Node */

            while (curr != null)
            {

/* place pointer to a tree node on
                   the stack before traversing
                  the node's left subtree */

                s.Push(curr);
                curr = curr.left;
            }

/* Current must be NULL at this point */

            curr = s.Pop();
            Console.Write(curr.data + " ");

/* we have visited the node and its
               left subtree.  Now, it's right
               subtree's turn */

            curr = curr.right;
        }
    }

/* Driver program to test above functions*/

    public static void Main(string[] args)
    {

/* creating a binary tree and entering
        the nodes */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.inorder();
    }
}

/*C# program to print inorder traversal
without recursion and stack*/

using System;

/* A binary tree tNode has data,
    pointer to left child
    and a pointer to right child */

class BinaryTree {
    tNode root;
    public class tNode {
        public int data;
        public tNode left, right;
        public tNode(int item)
        {
            data = item;
            left = right = null;
        }
    }

/* Function to traverse binary tree without
     recursion and without stack */

    void MorrisTraversal(tNode root)
    {
        tNode current, pre;
        if (root == null)
            return;
        current = root;
        while (current != null)
        {
            if (current.left == null)
            {
                Console.Write(current.data + " ");
                current = current.right;
            }
            else {

/* Find the inorder
                    predecessor of current
                 */

                pre = current.left;
                while (pre.right != null
                       && pre.right != current)
                    pre = pre.right;

/* Make current as right child
                of its inorder predecessor */

                if (pre.right == null)
                {
                    pre.right = current;
                    current = current.left;
                }

/* Revert the changes made in
                if part to restore the original
                tree i.e., fix the right child
                of predecssor*/

                else
                {
                    pre.right = null;
                    Console.Write(current.data + " ");
                    current = current.right;
                }
             } 
        } 
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/* Constructed binary tree is
            1
            / \
            2     3
        / \
        4     5
        */

        BinaryTree tree = new BinaryTree();
        tree.root = new tNode(1);
        tree.root.left = new tNode(2);
        tree.root.right = new tNode(3);
        tree.root.left.left = new tNode(4);
        tree.root.left.right = new tNode(5);
        tree.MorrisTraversal(tree.root);
    }
}

/*C# program to print postorder
traversal from preorder and
inorder traversals*/

using System;
class GFG
{

/*A utility function to search x
in []arr of size n*/

static int search(int []arr,
                  int x, int n)
{
    for (int i = 0; i < n; i++)
        if (arr[i] == x)
            return i;
    return -1;
}

/*Prints postorder traversal from
given inorder and preorder traversals*/

static void printPostOrder(int []in1,
                    int []pre, int n)
{

/*    The first element in pre[] is
    always root, search it in in[]
    to find left and right subtrees*/

    int root = search(in1, pre[0], n);

/*    If left subtree is not empty,
    print left subtree*/

    int []ar;
    if (root != 0)
    {
        ar = new int[n - 1];
        Array.Copy(pre, 1, ar, 0, n - 1);
        printPostOrder(in1, ar, root);
    }

/*    If right subtree is not empty,
    print right subtree*/

    if (root != n - 1)
    {
        ar = new int[n - (root + 1)];
        Array.Copy(in1, root + 1, ar, 0,
                        n - (root + 1));
        int []ar1 = new int[n - (root + 1)];
        Array.Copy(pre, root + 1, ar1, 0,
                         n - (root + 1));
        printPostOrder(ar, ar1, n - root - 1);
    }

/*    Print root*/

    Console.Write(pre[0] + " ");
}

/*Driver code*/

public static void Main(String []args)
{
    int []in1 = { 4, 2, 5, 1, 3, 6 };
    int []pre = { 1, 2, 4, 5, 3, 6 };
    int n = in1.Length;
    Console.WriteLine("Postorder traversal " );
    printPostOrder(in1, pre, n);
}
}

