/*C# program for finding postorder
traversal of BST from preorder traversal*/

using System;
class GFG {
    public class INT {
        public int data;
        public INT(int d) { data = d; }
    }

/*    Function to find postorder traversal from
    preorder traversal.*/

    public static void findPostOrderUtil(int[] pre, int n,
                                         int minval,
                                         int maxval,
                                         INT preIndex)
    {

/*        If entire preorder array is traversed
        then return as no more element is left
        to be added to post order array.*/

        if (preIndex.data == n) {
            return;
        }

/*        If array element does not lie in
        range specified, then it is not
        part of current subtree.*/

        if (pre[preIndex.data] < minval
            || pre[preIndex.data] > maxval) {
            return;
        }

/*        Store current value, to be printed
        later, after printing left and right
        subtrees. Increment preIndex to find
        left and right subtrees, and pass this
        updated value to recursive calls.*/

        int val = pre[preIndex.data];
        preIndex.data++;

/*        All elements with value between
        minval and val lie in left subtree.*/

        findPostOrderUtil(pre, n, minval, val, preIndex);

/*        All elements with value between
        val and maxval lie in right subtree.*/

        findPostOrderUtil(pre, n, val, maxval, preIndex);
        Console.Write(val + " ");
    }

/*    Function to find postorder traversal.*/

    public static void findPostOrder(int[] pre, int n)
    {

/*        To store index of element to be
        traversed next in preorder array.
        This is passed by reference to
        utility function.*/

        INT preIndex = new INT(0);
        findPostOrderUtil(pre, n, int.MinValue,
                          int.MaxValue, preIndex);
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        int[] pre = new int[] { 40, 30, 35, 80, 100 };
        int n = pre.Length;

/*        Calling function*/

        findPostOrder(pre, n);
    }
}

/*C# program to find binary tree 
with given inorder traversal */

using System;
using System.Collections.Generic;

/* Class containing left and right
   child of current node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = null;
        right = null;
    }
}

/* Class to print Level Order Traversal */

class GFG
{
public Node root;

/*A utility function to do
preorder traversal of BST */

public virtual void preOrder(Node node)
{
    if (node != null)
    {
        Console.Write(node.data + " ");
        preOrder(node.left);
        preOrder(node.right);
    }
}

/*Function for constructing all possible
trees with given inorder traversal 
stored in an array from arr[start] to 
arr[end]. This function returns a 
vector of trees. */

public virtual List<Node> getTrees(int[] arr, 
                                   int start, 
                                   int end)
{

/*    List to store all possible trees */

    List<Node> trees = new List<Node>();

/* if start > end then subtree will be 
    empty so returning NULL in the list */

    if (start > end)
    {
        trees.Add(null);
        return trees;
    }

/* Iterating through all values from 
    start to end for constructing left 
    and right subtree recursively */

    for (int i = start; i <= end; i++)
    {

/* Constructing left subtree */

        List<Node> ltrees = getTrees(arr, start, i - 1);

/* Constructing right subtree */

        List<Node> rtrees = getTrees(arr, i + 1, end);

/* Now looping through all left and 
        right subtrees and connecting them 
        to ith root below */

        for (int j = 0; j < ltrees.Count; j++)
        {
            for (int k = 0; k < rtrees.Count; k++)
            {

/*                Making arr[i] as root */

                Node node = new Node(arr[i]);

/*                Connecting left subtree */

                node.left = ltrees[j];

/*                Connecting right subtree */

                node.right = rtrees[k];

/*                Adding this tree to list */

                trees.Add(node);
            }
        }
    }
    return trees;
}

/*Driver Code*/

public static void Main(string[] args)
{
    int[] arr = new int[] {4, 5, 7};
    int n = arr.Length;
    GFG tree = new GFG();
    List<Node> trees = tree.getTrees(arr, 0, n - 1);
    Console.WriteLine("Preorder traversal of different " + 
                                    " binary trees are:");
    for (int i = 0; i < trees.Count; i++)
    {
        tree.preOrder(trees[i]);
        Console.WriteLine("");
    }
}
}

/*C# program to populate inorder traversal of all nodes*/

using System;
class BinaryTree
{

/*    A binary tree node*/

    class Node
    {
       public int data;
       public Node left, right, next;
      public Node(int item)
     {
          data = item;
          left = right = next = null;
      }
    }
    Node root;
    static Node next = null;

/* Set next of p and all descendants of p by traversing them in
       reverse Inorder */

    void populateNext(Node node)
    {

/*        The first visited node will be the rightmost node
        next of the rightmost node will be NULL*/

        if (node != null)
        {

/*            First set the next pointer in right subtree*/

            populateNext(node.right);

/*            Set the next as previously visited node in reverse Inorder*/

            node.next = next;

/*            Change the prev for subsequent node*/

            next = node;

/*            Finally, set the next pointer in left subtree*/

            populateNext(node.left);
        }
    }

/* Constructed binary tree is
            10
           /   \
          8      12
         /
        3    */
     static public void Main(String []args )
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(12);
        tree.root.left.left = new Node(3);

/*        Populates nextRight pointer in all nodes*/

        tree.populateNext(tree.root);

/*        Let us see the populated values*/

        Node ptr = tree.root.left.left;
        while (ptr != null)
        {

/*            -1 is printed if there is no successor*/

            int print = ptr.next != null ? ptr.next.data : -1;
            Console.WriteLine("Next of " + ptr.data + " is: " + print);
            ptr = ptr.next;
        }
    }
}

/*C# program to populate inorder traversal of all nodes*/
using System;
class Node
    {
       public int data;
       public Node left, right, next;

      public Node(int item)
     {
          data = item;
          left = right = next = null;
      }
    }
    Node root;
    static Node next = null;

/*    A wrapper over populateNextRecur*/

    void populateNext(Node node)
    {

/*        The first visited node will be the rightmost node
        next of the rightmost node will be NULL*/

        populateNextRecur(node, next);
    }

/* Set next of all descendants of p by
    traversing them in reverse Inorder */

    void populateNextRecur(Node p, Node next_ref)
    {
        if (p != null)
        {

/*            First set the next pointer in right subtree*/

            populateNextRecur(p.right, next_ref);

/*            Set the next as previously visited node in reverse Inorder*/

            p.next = next_ref;

/*            Change the prev for subsequent node*/

            next_ref = p;

/*            Finally, set the next pointer in right subtree*/

            populateNextRecur(p.left, next_ref);
        }
    }

/*C# program to find inorder
successor of a node */

using System;
class GFG
{

/*A Binary Tree Node */

public class Node
{
    public int data;
    public Node left, right;
}

/*Temporary node for case 2 */

public static Node temp = new Node();

/*Utility function to create 
a new tree node */

public static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*function to find left most
node in a tree */

public static Node leftMostNode(Node node)
{
    while (node != null && 
        node.left != null)
    {
        node = node.left;
    }
    return node;
}

/*function to find right most 
node in a tree */

public static Node rightMostNode(Node node)
{
    while (node != null &&
        node.right != null)
    {
        node = node.right;
    }
    return node;
}

/*recursive function to find the 
Inorder Scuccessor when the right
child of node x is null */

public static Node findInorderRecursive(Node root, 
                                        Node x)
{
    if (root == null)
    {
        return null;
    }
    if (root == x ||
    (temp = findInorderRecursive(root.left, x)) != null || 
    (temp = findInorderRecursive(root.right, x)) != null)
    {
        if (temp != null)
        {
            if (root.left == temp)
            {
                Console.Write("Inorder Successor of " + x.data);
                Console.Write(" is " + root.data + "\n");
                return null;
            }
        }
        return root;
    }
    return null;
}

/*function to find inorder successor 
of a node */

public static void inorderSuccesor(Node root, Node x)
{

/*    Case1: If right child is not null */

    if (x.right != null)
    {
        Node inorderSucc = leftMostNode(x.right);
        Console.Write("Inorder Successor of " + 
                            x.data + " is ");
        Console.Write(inorderSucc.data + "\n");
    }

/*    Case2: If right child is null */

    if (x.right == null)
    {
        int f = 0;
        Node rightMost = rightMostNode(root);

/*        case3: If x is the right most node */

        if (rightMost == x)
        {
            Console.Write("No inorder successor! " + 
                            "Right most node.\n");
        }
        else
        {
            findInorderRecursive(root, x);
        }
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    root.right.right = newNode(6);

/*    Case 1 */

    inorderSuccesor(root, root.right);

/*    case 2 */

    inorderSuccesor(root, root.left.left);

/*    case 3 */

    inorderSuccesor(root, root.right.right);
}
}

