        root.right.left = new Node(24); 
        root.right.right = new Node(32); 
        int N = 6;

/*        prints n-th node found */

        NthPostordernode(root, N);
    }
}

/*C# program to do level order
traversal line by line*/

using System;
using System.Collections;
class GFG 
{

/*A Binary Tree Node*/

public class Node 
{
    public int data;
    public Node left;
    public Node right;
    public Node(int data) 
    {
        this.data = data;
        left = null;
        right = null;
    }
}

/*Prints level order traversal line
by line using two queues.*/

static void levelOrder(Node root) 
{
    if (root == null)
    return;

/* Create an empty queue for
    level order traversal*/

    Queue q = new Queue();

/*    Pushing root node into the queue.*/

    q.Enqueue(root);

/*    Pushing delimiter into the queue.*/

    q.Enqueue(null);

/*    Executing loop till queue becomes
    empty*/

    while (q.Count>0)
    {
        Node curr = (Node)q.Peek();
        q.Dequeue();

/*        condition to check the
        occurence of next level*/

        if (curr == null) 
        {
            if (q.Count > 0)
            {
                q.Enqueue(null);
                 Console.WriteLine();
            }
        } 
        else 
        {

/*            Pushing left child current node*/

            if (curr.left != null)
            q.Enqueue(curr.left);

/*            Pushing right child current node*/

            if (curr.right != null)
            q.Enqueue(curr.right);
            Console.Write(curr.data + " ");
        }
    }
}

/*Driver code*/

static public void Main(String []args) 
{

/*    Let us create binary tree
    shown above*/

    Node root = new Node(1);
    root.left = new Node(2);
    root.right = new Node(3);
    root.left.left = new Node(4);
    root.left.right = new Node(5);
    root.right.right = new Node(6);
    levelOrder(root);
}
}

