/*C# program to print Zig-Zag traversal
in groups of size 2.*/

using System;
using System.Collections.Generic;
public class GFG
{
static readonly int LEFT = 0;
static readonly int RIGHT = 1;
static  int ChangeDirection(int Dir)
{
Dir = 1 - Dir;
return Dir;
}

/*A Binary Tree Node*/

public
 class node
{
    public
 int data;
    public
 node left, right;
};

/*Utility function to create a new tree node*/

static node newNode(int data)
{
    node temp = new node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/* Function to print the level order of
   given binary tree. Direction of printing
   level order traversal of binary tree changes
   after every two levels */

static void modifiedLevelOrder(node root)
{
    if (root == null)
        return ;   
    int dir = LEFT;
    node temp;
    Queue <node > Q = new Queue<node>();
    Stack <node > S = new Stack<node>();
    S.Push(root);

/*    Run this while loop till queue got empty*/

    while (Q.Count!=0 || S.Count!=0)
    {
        while (S.Count!=0)
        {
            temp = S.Peek();
            S.Pop();
            Console.Write(temp.data + " ");
            if (dir == LEFT)
            {
                if (temp.left != null)
                    Q.Enqueue(temp.left);
                if (temp.right != null)
                    Q.Enqueue(temp.right);
            }

/* For printing nodes from right to left,
            push the nodes to stack
             instead of printing them.*/

            else {
                if (temp.right != null)
                    Q.Enqueue(temp.right);
                if (temp.left != null)
                    Q.Enqueue(temp.left);
            }
        }      
        Console.WriteLine();

/*            for printing the nodes in order
            from right to left*/

        while (Q.Count!=0)
        {
            temp = Q.Peek();
            Q.Dequeue();
            Console.Write(temp.data + " ");
            if (dir == LEFT) {
                if (temp.left != null)
                    S.Push(temp.left);
                if (temp.right != null)
                    S.Push(temp.right);
            } else {
                if (temp.right != null)
                    S.Push(temp.right);
                if (temp.left != null)
                    S.Push(temp.left);
            }
        }
        Console.WriteLine();

/*        Change the direction of traversal.*/

        dir = ChangeDirection(dir);
    }
}

