/*A recursive C# program to print
reverse level order traversal */

using System;

/*A binary tree node */

class Node 
{ 
    public int data; 
    public Node left, right; 
    public Node(int item) 
    { 
        data = item; 
        left = right; 
    } 
} 
class BinaryTree 
{ 
Node root;

/* Function to print REVERSE 
level order traversal a tree*/

void reverseLevelOrder(Node node) 
{ 
    int h = height(node); 
    int i; 
    for (i = h; i >= 1; i--) 
    { 
        printGivenLevel(node, i); 
    } 
}

/* Print nodes at a given level */

void printGivenLevel(Node node, int level) 
{ 
    if (node == null) 
        return; 
    if (level == 1) 
        Console.Write(node.data + " "); 
    else if (level > 1) 
    { 
        printGivenLevel(node.left, level - 1); 
        printGivenLevel(node.right, level - 1); 
    } 
}

/* Compute the "height" of a tree -- 
the number of nodes along the longest 
path from the root node down to the 
farthest leaf node.*/

int height(Node node) 
{ 
    if (node == null) 
        return 0; 
    else
    {

/* compute the height of each subtree */

        int lheight = height(node.left); 
        int rheight = height(node.right);

/* use the larger one */

        if (lheight > rheight) 
            return (lheight + 1); 
        else
            return (rheight + 1); 
    } 
}

/*Driver Code*/

static public void Main(String []args) 
{ 
    BinaryTree tree = new BinaryTree();

/*    Let us create trees shown 
    in above diagram */

    tree.root = new Node(1); 
    tree.root.left = new Node(2); 
    tree.root.right = new Node(3); 
    tree.root.left.left = new Node(4); 
    tree.root.left.right = new Node(5); 
    Console.WriteLine("Level Order traversal " + 
                        "of binary tree is : "); 
    tree.reverseLevelOrder(tree.root); 
} 
}

/*A recursive C# program to print reverse 
level order traversal using stack and queue*/

using System.Collections.Generic;
using System;

/* A binary tree node has data,
pointer to left and right children */

public class Node 
{
    public int data;
    public Node left, right;
    public Node(int item) 
    {
        data = item;
        left = right;
    }
}
public class BinaryTree 
{
    Node root;

/* Given a binary tree, print its
    nodes in reverse level order */

    void reverseLevelOrder(Node node) 
    {
        Stack<Node> S = new Stack<Node>();
        Queue<Node> Q = new Queue<Node>();
        Q.Enqueue(node);

/*        Do something like normal level 
        order traversal order.Following
        are the differences with normal 
        level order traversal
        1) Instead of printing a node, we push the node to stack
        2) Right subtree is visited before left subtree*/

        while (Q.Count>0) 
        {

/* Dequeue node and make it root */

            node = Q.Peek();
            Q.Dequeue();
            S.Push(node);

/* Enqueue right child */

            if (node.right != null)

/*                NOTE: RIGHT CHILD IS ENQUEUED BEFORE LEFT*/

                Q.Enqueue(node.right);

/* Enqueue left child */

            if (node.left != null)
                Q.Enqueue(node.left);
        }

/*        Now pop all items from stack
        one by one and print them*/

        while (S.Count>0) 
        {
            node = S.Peek();
            Console.Write(node.data + " ");
            S.Pop();
        }
    }

/*    Driver code*/

    public static void Main() 
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create trees shown in above diagram*/

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        Console.WriteLine("Level Order traversal of binary tree is :");
        tree.reverseLevelOrder(tree.root);
    }
}

/*C# program to Reverse Tree path*/

using System;
using System.Collections.Generic;
class GFG
{

/*A Binary Tree Node*/

public class Node
{
    public int data;
    public Node left, right;
}

/*class for int values*/

public class INT
{
    public int data;
}

/*'data' is input. We need to reverse
path from root to data.
'level' is current level.
'temp' that stores path nodes.
'nextpos' used to pick next item for reversing.*/

public static Node reverseTreePathUtil(Node root, int data,
                                       IDictionary<int, int> temp,
                                       int level, INT nextpos)
{

/*    return null if root null*/

    if (root == null)
    {
        return null;
    }

/*    Final condition
    if the node is found then*/

    if (data == root.data)
    {

/*        store the value in it's level*/

        temp[level] = root.data;

/*        change the root value with the
        current next element of the map*/

        root.data = temp[nextpos.data];

/*        increment in k for the next element*/

        nextpos.data++;
        return root;
    }

/*    store the data in perticular level*/

    temp[level] = root.data;

/*    We go to right only when left does not
    contain given data. This way we make sure
    that correct path node is stored in temp[]*/

    Node left, right = null;
    left = reverseTreePathUtil(root.left, data, temp,
                               level + 1, nextpos);
    if (left == null)
    {
        right = reverseTreePathUtil(root.right, data, temp,
                                    level + 1, nextpos);
    }

/*    If current node is part of the path,
    then do reversing.*/

    if (left != null || right != null)
    {
        root.data = temp[nextpos.data];
        nextpos.data++;
        return (left != null ? left : right);
    }

/*    return null if not element found*/

    return null;
}

/*Reverse Tree path*/

public static void reverseTreePath(Node root,
                                   int data)
{

/*    store per level data*/

    IDictionary<int,
                int> temp = new Dictionary<int,
                                           int>();

/*    it is for replacing the data*/

    INT nextpos = new INT();
    nextpos.data = 0;

/*    reverse tree path*/

    reverseTreePathUtil(root, data,
                        temp, 0, nextpos);
}

/*INORDER*/

public static void inorder(Node root)
{
    if (root != null)
    {
        inorder(root.left);
        Console.Write(root.data + " ");
        inorder(root.right);
    }
}

/*Utility function to create
a new tree node*/

public static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver Code*/

public static void Main(string[] args)
{

/*    Let us create binary tree
    shown in above diagram*/

    Node root = newNode(7);
    root.left = newNode(6);
    root.right = newNode(5);
    root.left.left = newNode(4);
    root.left.right = newNode(3);
    root.right.left = newNode(2);
    root.right.right = newNode(1);

/* 7
        / \
        6     5
    / \     / \
    4 3     2 1         */

    int data = 4;

/*    Reverse Tree Path*/

    reverseTreePath(root, data);

/*    Traverse inorder*/

    inorder(root);
}
}

/*C# program for special level 
order traversal */

using System;
using System.Collections.Generic;

/* Class containing left and right 
child of current node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/* Given a perfect binary tree, 
print its nodes in specific 
level order */
class GFG
{
public Node root;
public virtual void printSpecificLevelOrder(Node node)
{
    if (node == null)
    {
        return;
    }

/*    Let us print root and next level first */

    Console.Write(node.data);

/*    Since it is perfect Binary Tree,
    right is not checked */

    if (node.left != null)
    {
        Console.Write(" " + node.left.data +
                      " " + node.right.data);
    }

/*    Do anything more if there 
    are nodes at next level in 
    given perfect Binary Tree */

    if (node.left.left == null)
    {
        return;
    }

/*    Create a queue and enqueue left
    and right children of root */

    LinkedList<Node> q = new LinkedList<Node>();
    q.AddLast(node.left);
    q.AddLast(node.right);

/*    We process two nodes at a time, 
    so we need two variables to 
    store two front items of queue */

    Node first = null, second = null;

/*    traversal loop */

    while (q.Count > 0)
    {

/*        Pop two items from queue */

        first = q.First.Value;
        q.RemoveFirst();
        second = q.First.Value;
        q.RemoveFirst();

/*        Print children of first and
        second in reverse order */

        Console.Write(" " + first.left.data + 
                      " " + second.right.data);
        Console.Write(" " + first.right.data + 
                      " " + second.left.data);

/*        If first and second have grandchildren, 
        enqueue them in reverse order */

        if (first.left.left != null)
        {
            q.AddLast(first.left);
            q.AddLast(second.right);
            q.AddLast(first.right);
            q.AddLast(second.left);
        }
    }
}

