/*C# program for special order traversal*/

using System;
using System.Collections.Generic;
class GFG
{

/* A binary tree node has data,
pointer to left child and
a pointer to right child */

public class Node
{
    public int data;
    public Node left;
    public Node right;

/* Helper function that allocates
    a new node with the given data and
    null left and right pointers. */

    public Node(int value)
    {
        data = value;
        left = null;
        right = null;
    }
};

/* Given a perfect binary tree,
print its nodes in specific
level order */

static void specific_level_order_traversal(Node root)
{

/*    for level order traversal*/

    Queue <Node> q = new Queue <Node>();

/*    Stack to print reverse*/

    Stack <List<int>> s = new Stack<List<int>>();
    q.Enqueue(root);
    int sz;
    while(q.Count > 0)
    {

/*        vector to store the level*/

        List<int> v = new List<int>();

/*        considering size of the level*/

        sz = q.Count;
        for(int i = 0; i < sz; ++i)
        {
            Node temp = q.Peek();
            q.Dequeue();

/*            push data of the node of a
            particular level to vector*/

            v.Add(temp.data);
            if(temp.left != null)
            q.Enqueue(temp.left);
            if(temp.right != null)
                q.Enqueue(temp.right);
        }

/*        push vector containing a level in Stack*/

        s.Push(v);
    }

/*    print the Stack*/

    while(s.Count > 0)
    {

/*        Finally pop all Nodes from Stack
        and prints them.*/

        List<int> v = s.Peek();
        s.Pop();
        for(int i = 0,
                j = v.Count - 1; i < j; ++i)
        {
            Console.Write(v[i] + " " +
                          v[j] + " ");
            j--;
        }
    }

/*    finally print root;*/

    Console.WriteLine(root.data);
}

/*Driver code*/

public static void Main(String []args)
{
    Node root = new Node(1);
    root.left = new Node(2);
    root.right = new Node(3);
    Console.WriteLine("Specific Level Order traversal" +
                                  " of binary tree is");
    specific_level_order_traversal(root);
}
}

/*C# program to reverse alternate 
levels of perfect binary tree */

using System;

/*A binary tree node */

public class Node
{
    public char data;
    public Node left, right;
    public Node(char item)
    {
        data = item;
        left = right = null;
    }
}

/*class to access index value
by reference */

public class Index
{
    public int index;
}
class GFG
{
public Node root;
public Index index_obj = new Index();

/*function to store alternate
levels in a tree */

public virtual void storeAlternate(Node node, char[] arr, 
                                   Index index, int l)
{

/*    base case */

    if (node == null)
    {
        return;
    }

/*    store elements of left subtree */

    storeAlternate(node.left, arr, index, l + 1);

/*    store this node only if level is odd */

    if (l % 2 != 0)
    {
        arr[index.index] = node.data;
        index.index++;
    }
    storeAlternate(node.right, arr, index, l + 1);
}

/*Function to modify Binary Tree (All odd 
level nodes are updated by taking elements
from array in inorder fashion) */

public virtual void modifyTree(Node node, char[] arr, 
                               Index index, int l)
{

/*    Base case */

    if (node == null)
    {
        return;
    }

/*    Update nodes in left subtree */

    modifyTree(node.left, arr, index, l + 1);

/*    Update this node only if this
    is an odd level node */

    if (l % 2 != 0)
    {
        node.data = arr[index.index];
        (index.index)++;
    }

/*    Update nodes in right subtree */

    modifyTree(node.right, arr, index, l + 1);
}

/*A utility function to reverse an 
array from index 0 to n-1 */

public virtual void reverse(char[] arr, int n)
{
    int l = 0, r = n - 1;
    while (l < r)
    {
        char temp = arr[l];
        arr[l] = arr[r];
        arr[r] = temp;
        l++;
        r--;
    }
}
public virtual void reverseAlternate()
{
    reverseAlternate(root);
}

/*The main function to reverse 
alternate nodes of a binary tree */

public virtual void reverseAlternate(Node node)
{

/*    Create an auxiliary array to 
    store nodes of alternate levels */

    char[] arr = new char[100];

/*    First store nodes of alternate levels */

    storeAlternate(node, arr, index_obj, 0);

/*    index_obj.index = 0; 
    Reverse the array */

    reverse(arr, index_obj.index);

/*    Update tree by taking elements from array */

    index_obj.index = 0;
    modifyTree(node, arr, index_obj, 0);
}
public virtual void printInorder()
{
    printInorder(root);
}

/*A utility function to print indorder 
traversal of a binary tree */

public virtual void printInorder(Node node)
{
    if (node == null)
    {
        return;
    }
    printInorder(node.left);
    Console.Write(node.data + " ");
    printInorder(node.right);
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node('a');
    tree.root.left = new Node('b');
    tree.root.right = new Node('c');
    tree.root.left.left = new Node('d');
    tree.root.left.right = new Node('e');
    tree.root.right.left = new Node('f');
    tree.root.right.right = new Node('g');
    tree.root.left.left.left = new Node('h');
    tree.root.left.left.right = new Node('i');
    tree.root.left.right.left = new Node('j');
    tree.root.left.right.right = new Node('k');
    tree.root.right.left.left = new Node('l');
    tree.root.right.left.right = new Node('m');
    tree.root.right.right.left = new Node('n');
    tree.root.right.right.right = new Node('o');
    Console.WriteLine("Inorder Traversal of given tree");
    tree.printInorder();
    tree.reverseAlternate();
    Console.WriteLine("");
    Console.WriteLine("");
    Console.WriteLine("Inorder Traversal of modified tree");
    tree.printInorder();
}
}

/*C# program to reverse alternate 
levels of a tree */

using System;
class GFG 
{ 
public class Node 
{ 
    public char key; 
    public Node left, right; 
}; 
static void preorder( Node root1, 
                       Node root2, int lvl) 
{

/*    Base cases */

    if (root1 == null || root2==null) 
        return;

/*    Swap subtrees if level is even */

    if (lvl % 2 == 0) 
        { 
            char t = root1.key; 
            root1.key = root2.key; 
            root2.key = t; 
        }

/*    Recur for left and right subtrees 
    (Note : left of root1 
    is passed and right of root2 in
    first call and opposite 
    in second call. */

    preorder(root1.left, root2.right, lvl+1); 
    preorder(root1.right, root2.left, lvl+1); 
}

/*This function calls preorder() for left 
and right children 
of root */

static void reverseAlternate( Node root) 
{ 
    preorder(root.left, root.right, 0); 
}

/*Inorder traversal (used to print initial and 
modified trees) */

static void printInorder( Node root) 
{ 
    if (root == null) 
        return; 
    printInorder(root.left); 
    Console.Write( root.key + " "); 
    printInorder(root.right); 
}

/*A utility function to create a new node */

static Node newNode(int key) 
{ 
    Node temp = new Node(); 
    temp.left = temp.right = null; 
    temp.key = (char)key; 
    return temp; 
}

/*Driver code*/

public static void Main(String []args) 
{ 
    Node root = newNode('a'); 
    root.left = newNode('b'); 
    root.right = newNode('c'); 
    root.left.left = newNode('d'); 
    root.left.right = newNode('e'); 
    root.right.left = newNode('f'); 
    root.right.right = newNode('g'); 
    root.left.left.left = newNode('h'); 
    root.left.left.right = newNode('i'); 
    root.left.right.left = newNode('j'); 
    root.left.right.right = newNode('k'); 
    root.right.left.left = newNode('l'); 
    root.right.left.right = newNode('m'); 
    root.right.right.left = newNode('n'); 
    root.right.right.right = newNode('o'); 
    Console.Write("Inorder Traversal of given tree\n"); 
    printInorder(root); 
    reverseAlternate(root); 
    Console.Write("\n\nInorder Traversal of modified tree\n"); 
    printInorder(root); 
} 
}

/*C# program to implement Morris
preorder traversal */

using System;
public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class GFG
{
public Node root;
public virtual void morrisTraversalPreorder()
{
    morrisTraversalPreorder(root);
}

/*Preorder traversal without 
recursion and without stack */

public virtual void morrisTraversalPreorder(Node node)
{
    while (node != null)
    {

/*        If left child is null, print the 
        current node data. Move to right child. */

        if (node.left == null)
        {
            Console.Write(node.data + " ");
            node = node.right;
        }
        else
        {

/*            Find inorder predecessor */

            Node current = node.left;
            while (current.right != null && 
                   current.right != node)
            {
                current = current.right;
            }

/*            If the right child of inorder predecessor 
            already points to this node */

            if (current.right == node)
            {
                current.right = null;
                node = node.right;
            }

/*            If right child doesn't point to 
            this node, then print this node 
            and make right child point to this node */

            else
            {
                Console.Write(node.data + " ");
                current.right = node;
                node = node.left;
            }
        }
    }
}
public virtual void preorder()
{
    preorder(root);
}

/*Function for Standard preorder traversal */

public virtual void preorder(Node node)
{
    if (node != null)
    {
        Console.Write(node.data + " ");
        preorder(node.left);
        preorder(node.right);
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node(1);
    tree.root.left = new Node(2);
    tree.root.right = new Node(3);
    tree.root.left.left = new Node(4);
    tree.root.left.right = new Node(5);
    tree.root.right.left = new Node(6);
    tree.root.right.right = new Node(7);
    tree.root.left.left.left = new Node(8);
    tree.root.left.left.right = new Node(9);
    tree.root.left.right.left = new Node(10);
    tree.root.left.right.right = new Node(11);
    tree.morrisTraversalPreorder();
    Console.WriteLine("");
    tree.preorder();
}
}

/*C# program to implement iterative
preorder traversal*/

using System;
using System.Collections.Generic;

/*A binary tree node*/

public class Node {
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*    An iterative process to print preorder
    traversal of Binary tree*/
class GFG {
    public Node root;
    public virtual void iterativePreorder()
    {
        iterativePreorder(root);
    }
    public virtual void iterativePreorder(Node node)
    {

/*        Base Case*/

        if (node == null) {
            return;
        }

/*        Create an empty stack and push root to it*/

        Stack<Node> nodeStack = new Stack<Node>();
        nodeStack.Push(root);

/* Pop all items one by one. Do following
       for every popped item
    a) print it
    b) push its right child
    c) push its left child
    Note that right child is pushed first so
    that left is processed first */

        while (nodeStack.Count > 0) {

/*            Pop the top item from stack and print it*/

            Node mynode = nodeStack.Peek();
            Console.Write(mynode.data + " ");
            nodeStack.Pop();

/*            Push right and left children of
            the popped node to stack*/

            if (mynode.right != null) {
                nodeStack.Push(mynode.right);
            }
            if (mynode.left != null) {
                nodeStack.Push(mynode.left);
            }
        }
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        GFG tree = new GFG();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(2);
        tree.iterativePreorder();
    }
}

using System;
using System.Collections.Generic;

/*A binary tree node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree{
Node root;
void preorderIterative()
{
    preorderIterative(root);
}

/*Iterative function to do Preorder
traversal of the tree*/

void preorderIterative(Node node)
{
    if (node == null)
    {
        return;
    }
    Stack<Node> st = new Stack<Node>();

/*    Start from root node (set curr
    node to root node)*/

    Node curr = node;

/*    Run till stack is not empty or
    current is not NULL*/

    while (curr != null || st.Count!=0)
    {

/*        Print left children while exist
        and keep pushing right into the 
        stack.*/

        while (curr != null)
        {
            Console.Write(curr.data + " ");
            if (curr.right != null)
                st.Push(curr.right);
            curr = curr.left;
        }

/*        We reach when curr is NULL, so We
        take out a right child from stack*/

        if (st.Count != 0)
        {
            curr = st.Pop();
        }
    }
}

/*Driver code*/

public static void Main(String []args)
{
    BinaryTree tree = new BinaryTree();
    tree.root = new Node(10);
    tree.root.left = new Node(20);
    tree.root.right = new Node(30);
    tree.root.left.left = new Node(40);
    tree.root.left.left.left = new Node(70);
    tree.root.left.right = new Node(50);
    tree.root.right.left = new Node(60);
    tree.root.left.left.right = new Node(80);
    tree.preorderIterative();
}
}

/*C# program or postorder traversal*/

using System;
using System.Collections.Generic;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

public
  class Node
  {
    public
      int data;
    public
      Node left, right;
    public
      Node(int data)
    {
      this.data = data;
      this.left = this.right = null;       
    }
  };
class GFG
{
  Node root;

/* Helper function that allocates a new node with the
given data and null left and right pointers. */

  void postorder(Node head)
  {
    Node temp = root;   
    HashSet<Node> visited = new HashSet<Node>();
    while ((temp != null  && !visited.Contains(temp)))
    {

/*      Visited left subtree*/

      if (temp.left != null &&
          !visited.Contains(temp.left))
        temp = temp.left;

/*      Visited right subtree*/

      else if (temp.right != null &&
               !visited.Contains(temp.right))
        temp = temp.right;

/*      Print node*/

      else
      {
        Console.Write(temp.data + " ");
        visited.Add(temp);
        temp = head;
      }
    }
  }

/* Driver code*/

  public static void Main(String[] args)
  {
    GFG gfg = new GFG();
    gfg.root = new Node(8);
    gfg.root.left = new Node(3);
    gfg.root.right = new Node(10);
    gfg.root.left.left = new Node(1);
    gfg.root.left.right = new Node(6);
    gfg.root.left.right.left = new Node(4);
    gfg.root.left.right.right = new Node(7);
    gfg.root.right.right = new Node(14);
    gfg.root.right.right.left = new Node(13);
    gfg.postorder(gfg.root);
  }
}

/*C# program or postorder traversal*/

using System;
class GFG
{

/* A binary tree node has data,
    pointer to left child
    and a pointer to right child */

class Node
{
    public int data;
    public Node left, right;
    public bool visited;
}
static void postorder( Node head)
{
    Node temp = head;
    while (temp != null &&
            temp.visited == false)
    {

/*        Visited left subtree*/

        if (temp.left != null &&
            temp.left.visited == false)
            temp = temp.left;

/*        Visited right subtree*/

        else if (temp.right != null &&
                temp.right.visited == false)
            temp = temp.right;

/*        Print node*/

        else
        {
            Console.Write("{0} ", temp.data);
            temp.visited = true;
            temp = head;
        }
    }
}
static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = null;
    node.right = null;
    node.visited = false;
    return (node);
}

