    root.right = newNode(10);
    root.left.left = newNode(1);
    root.left.right = newNode(6);
    root.left.right.left = newNode(4);
    root.left.right.right = newNode(7);
    root.right.right = newNode(14);
    root.right.right.left = newNode(13);
    postorder(root);
}
}

/*C# program to con string from binary tree*/

using System;
using System.Collections;
class GFG
{

/*A binary tree node has data,
pointer to left child and
a pointer to right child*/

public class Node
{
    public int data;
    public Node left, right;
};

/*Helper function that
allocates a new node*/

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
}

/*Iterative function to print diagonal view*/

static void diagonalPrint(Node root)
{

/*    base case*/

    if (root == null)
        return;

/*    inbuilt queue of Treenode*/

    Queue q = new Queue();

/*    Enqueue root*/

    q.Enqueue(root);

/*    Enqueue delimiter*/

    q.Enqueue(null);
    while (q.Count > 0)
    {
        Node temp = (Node) q.Peek();
        q.Dequeue();

/*        if current is delimiter then insert another
        for next diagonal and cout nextline*/

        if (temp == null)
        {

/*            if queue is empty return*/

            if (q.Count == 0)
                return;

/*            output nextline*/

            Console.WriteLine();

/*            Enqueue delimiter again*/

            q.Enqueue(null);
        }
        else
        {
            while (temp != null)
            {
                Console.Write( temp.data + " ");

/*                if left child is present
                Enqueue into queue*/

                if (temp.left != null)
                    q.Enqueue(temp.left);

/*                current equals to right child*/

                temp = temp.right;
            }
        }
    }
}

/*Driver Code*/

public static void Main(String []args)
{
    Node root = newNode(8);
    root.left = newNode(3);
    root.right = newNode(10);
    root.left.left = newNode(1);
    root.left.right = newNode(6);
    root.right.right = newNode(14);
    root.right.right.left = newNode(13);
    root.left.right.left = newNode(4);
    root.left.right.right = newNode(7);
    diagonalPrint(root);
}
}

/*C# program to print boundary traversal
of binary tree*/

using System;

/* A binary tree node has data, 
pointer to left child and a pointer 
to right child */

public class Node {
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class GFG {
    public Node root;

/*    A simple function to print leaf
    nodes of a binary tree*/

    public virtual void printLeaves(Node node)
    {
        if (node == null)
            return;
        printLeaves(node.left);

/*        Print it if it is a leaf node*/

        if (node.left == null && node.right == null) {
            Console.Write(node.data + " ");
        }
        printLeaves(node.right);
    }

/*    A function to print all left boundary
    nodes, except a leaf node. Print the
    nodes in TOP DOWN manner*/

    public virtual void printBoundaryLeft(Node node)
    {
        if (node == null)
            return;
        if (node.left != null) {

/*            to ensure top down order, print the node
            before calling itself for left subtree*/

            Console.Write(node.data + " ");
            printBoundaryLeft(node.left);
        }
        else if (node.right != null) {
            Console.Write(node.data + " ");
            printBoundaryLeft(node.right);
        }

/*        do nothing if it is a leaf node,
        this way we avoid duplicates in output*/

    }

/*    A function to print all right boundary
    nodes, except a leaf node. Print the
    nodes in BOTTOM UP manner*/

    public virtual void printBoundaryRight(Node node)
    {
        if (node == null)
            return;
        if (node.right != null) {

/*            to ensure bottom up order,
            first call for right subtree,
            then print this node*/

            printBoundaryRight(node.right);
            Console.Write(node.data + " ");
        }
        else if (node.left != null) {
            printBoundaryRight(node.left);
            Console.Write(node.data + " ");
        }

/*        do nothing if it is a leaf node,
        this way we avoid duplicates in output*/

    }

/*    A function to do boundary traversal
    of a given binary tree*/

    public virtual void printBoundary(Node node)
    {
        if (node == null)
            return;
        Console.Write(node.data + " ");

/*        Print the left boundary in
        top-down manner.*/

        printBoundaryLeft(node.left);

/*        Print all leaf nodes*/

        printLeaves(node.left);
        printLeaves(node.right);

/*        Print the right boundary in
        bottom-up manner*/

        printBoundaryRight(node.right);
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        GFG tree = new GFG();
        tree.root = new Node(20);
        tree.root.left = new Node(8);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(12);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(14);
        tree.root.right = new Node(22);
        tree.root.right.right = new Node(25);
        tree.printBoundary(tree.root);
    }
}

/*C# program to find density 
of Binary Tree */

using System;

/*A binary tree node */

class Node 
{ 
    public int data; 
    public Node left, right; 
    public Node(int data) 
    { 
        this.data = data; 
        left = right = null; 
    } 
}

/*Class to implement pass
by reference of size */

class Size 
{ 
    public int size = 0; 
} 
class BinaryTree 
{ 
Node root;

/*Function to compute height 
and size of a binary tree */

int heighAndSize(Node node,
                 Size size) 
{ 
    if (node == null) 
        return 0;

/*    compute height of each subtree */

    int l = heighAndSize(node.left, size); 
    int r = heighAndSize(node.right, size);

/*    increase size by 1 */

    size.size++;

/*    return larger of the two */

    return (l > r) ? l + 1 : r + 1; 
}

/*function to calculate density
of a binary tree */

float density(Node root) 
{ 
    Size size = new Size(); 
    if (root == null) 
        return 0;

/*    Finds height and size */

    int _height = heighAndSize(root, size); 
    return (float) size.size / _height; 
}

/*Driver code */

static public void Main(String []args) 
{ 
    BinaryTree tree = new BinaryTree(); 
    tree.root = new Node(1); 
    tree.root.left = new Node(2); 
    tree.root.right = new Node(3); 
    Console.WriteLine("Density of given " + 
                      "Binary Tree is : " + 
                  tree.density(tree.root)); 
} 
}

/*C# program to find height of
full binary tree using preorder*/

using System;
class GFG {

/*    function to return max of left subtree
    height or right subtree height*/

    static int findDepthRec(char[] tree, int n, int index)
    {
        if (index >= n || tree[index] == 'l')
            return 0;

/*        calc height of left subtree (In preorder
        left subtree is processed before right)*/

        index++;
        int left = findDepthRec(tree, n, index);

/*        calc height of right subtree*/

        index++;
        int right = findDepthRec(tree, n, index);
        return Math.Max(left, right) + 1;
    }

/*    Wrapper over findDepthRec()*/

    static int findDepth(char[] tree, int n)
    {
        int index = 0;
        return (findDepthRec(tree, n, index));
    }

/*    Driver program*/

    static public void Main()
    {
        char[] tree = "nlnnlll".ToCharArray();
        int n = tree.Length;
        Console.WriteLine(findDepth(tree, n));
    }
}

/*C# code to modify binary tree for 
traversal using only right pointer*/

using System;
class GFG
{

/*A binary tree node has data, 
left child and right child */

public class Node 
{ 
    public int data; 
    public Node left; 
    public Node right; 
};

/*function that allocates a new node 
with the given data and null left 
and right pointers. */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = null; 
    node.right = null; 
    return (node); 
}

/*Function to modify tree */

static Node modifytree( Node root) 
{ 
    Node right = root.right; 
    Node rightMost = root;

/*    if the left tree exists */

    if (root.left != null) 
    {

/*        get the right-most of the 
        original left subtree */

        rightMost = modifytree(root.left);

/*        set root right to left subtree */

        root.right = root.left; 
        root.left = null; 
    }

/*    if the right subtree does 
    not exists we are done! */

    if (right == null) 
        return rightMost;

/*    set right pointer of right-most 
    of the original left subtree */

    rightMost.right = right;

/*    modify the rightsubtree */

    rightMost = modifytree(right); 
    return rightMost; 
}

/*printing using right pointer only */

static void printpre( Node root) 
{ 
    while (root != null) 
    { 
        Console.Write( root.data + " "); 
        root = root.right; 
    } 
}

