{

/* Constructed binary tree is 
        10 
        / \ 
    8 2 
    / \ 
    3 5 */

    Node root = newNode(10); 
    root.left = newNode(8); 
    root.right = newNode(2); 
    root.left.left = newNode(3); 
    root.left.right = newNode(5); 
    modifytree(root); 
    printpre(root); 
}
}

/*C# code to modify binary tree for 
traversal using only right pointer */

using System; 
using System.Collections;
class GfG 
{

/*A binary tree node has data, 
left child and right child */

public class Node 
{ 
    public int data; 
    public Node left; 
    public Node right; 
}

/*Helper function that allocates a new 
node with the given data and NULL 
left and right pointers. */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = null; 
    node.right = null; 
    return (node); 
}

/*An iterative process to set the right 
pointer of Binary tree */

static void modifytree(Node root) 
{

/*    Base Case */

    if (root == null) 
        return;

/*    Create an empty stack and Push root to it */

    Stack nodeStack = new Stack(); 
    nodeStack.Push(root);

/* Pop all items one by one. 
        Do following for every Popped item 
    a) print it 
    b) Push its right child 
    c) Push its left child 
    Note that right child is Pushed first 
    so that left is processed first */

    Node pre = null; 
    while (nodeStack.Count !=0) 
    {

/*        Pop the top item from stack */

        Node node = (Node)nodeStack.Peek(); 
        nodeStack.Pop();

/*        Push right and left children of 
        the Popped node to stack */

        if (node.right != null) 
            nodeStack.Push(node.right); 
        if (node.left != null) 
            nodeStack.Push(node.left);

/*        check if some previous node exists */

        if (pre != null) 
        {

/*            set the right pointer of 
            previous node to currrent */

            pre.right = node; 
        }

/*        set previous node as current node */

        pre = node; 
    } 
}

/*printing using right pointer only */

static void printpre(Node root) 
{ 
    while (root != null) 
    { 
        Console.Write(root.data + " "); 
        root = root.right; 
    } 
}

/*Driver code */

public static void Main(String []args) 
{

/* Constructed binary tree is 
            10 
        / \ 
        8     2 
    / \     
    3     5 
*/

    Node root = newNode(10); 
    root.left = newNode(8); 
    root.right = newNode(2); 
    root.left.left = newNode(3); 
    root.left.right = newNode(5); 
    modifytree(root); 
    printpre(root); 
}
}

/*C# program to construct a tree using
inorder and preorder traversal*/

using System;

/* A binary tree node has data, pointer
to left child and a pointer to right child */

public class Node {
    public char data;
    public Node left, right;
    public Node(char item)
    {
        data = item;
        left = right = null;
    }
}
class GFG {
    public Node root;
    public static int preIndex = 0;

/* Recursive function to construct binary
of size len from Inorder traversal in[]
and Preorder traversal pre[]. Initial values
of inStrt and inEnd should be 0 and len -1.
The function doesn't do any error checking for
cases where inorder and preorder do not form a tree */

    public virtual Node buildTree(char[] arr, char[] pre,
                                  int inStrt, int inEnd)
    {
        if (inStrt > inEnd) {
            return null;
        }

/* Pick current node from Preorder traversal
     using preIndex and increment preIndex */

        Node tNode = new Node(pre[preIndex++]);

/* If this node has no children then return */

        if (inStrt == inEnd) {
            return tNode;
        }

/* Else find the index of this
       node in Inorder traversal */

        int inIndex = search(arr, inStrt,
                             inEnd, tNode.data);

/* Using index in Inorder traversal,
    construct left and right subtress */

        tNode.left = buildTree(arr, pre, inStrt, inIndex - 1);
        tNode.right = buildTree(arr, pre, inIndex + 1, inEnd);
        return tNode;
    }

/* UTILITY FUNCTIONS */

/* Function to find index of value in arr[start...end]
The function assumes that value is present in in[] */

    public virtual int search(char[] arr, int strt,
                              int end, char value)
    {
        int i;
        for (i = strt; i <= end; i++) {
            if (arr[i] == value) {
                return i;
            }
        }
        return i;
    }

/* This funtcion is here just to test buildTree() */

    public virtual void printInorder(Node node)
    {
        if (node == null) {
            return;
        }

/* first recur on left child */

        printInorder(node.left);

/* then print the data of node */

        Console.Write(node.data + " ");

/* now recur on right child */

        printInorder(node.right);
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        GFG tree = new GFG();
        char[] arr = new char[] { 'D', 'B', 'E', 'A', 'F', 'C' };
