/* C# program to construct tree using inorder
   and preorder traversals */

using System;
using System.Collections.Generic;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

public class Node
{
    public char data;
    public Node left, right;
    public Node(char d)
    {
        data = d;
        left = right = null;
    }
}
public class Tree
{
    public static Node root;

/*    Store indexes of all items so that we
    we can quickly find later*/

    static Dictionary<char,int> mp = new Dictionary<char,int>();
    static int preIndex = 0;

/* Recursive function to construct binary of size
    len from Inorder traversal in[] and Preorder traversal
    pre[]. Initial values of inStrt and inEnd should be
    0 and len -1. The function doesn't do any error
    checking for cases where inorder and preorder
    do not form a tree */

    static Node buildTree(char[] In, char[] pre,
                          int inStrt, int inEnd)
    {
        if(inStrt > inEnd)
        {
            return null;
        }

/* Pick current node from Preorder traversal using preIndex
        and increment preIndex */

        char curr = pre[preIndex++];
        Node tNode;
        tNode = new Node(curr);

/* If this node has no children then return */

        if(inStrt == inEnd)
        {
            return tNode;
        }

/* Else find the index of this node in Inorder traversal */

        int inIndex = mp[curr];

/* Using index in Inorder traversal, construct left and
        right subtress */

        tNode.left = buildTree(In, pre, inStrt, inIndex - 1);
        tNode.right = buildTree(In, pre, inIndex + 1, inEnd);
        return tNode;
    }

/*    This function mainly creates an unordered_map, then
    calls buildTree()*/

    public static Node buldTreeWrap(char[] In, char[] pre, int len)
    {
        for(int i = 0; i < len; i++)
        {
            mp.Add(In[i], i);
        }
        return buildTree(In, pre, 0, len - 1);
    }

/* This funtcion is here just to test buildTree() */

    static void printInorder(Node node)
    {
        if(node == null)
        {
            return;
        }
        printInorder(node.left);
        Console.Write(node.data + " ");
        printInorder(node.right);
    }

/* Driver code */

    static public void Main (){
        char[] In = {'D', 'B', 'E', 'A', 'F', 'C'};
        char[] pre = {'A', 'B', 'D', 'E', 'C', 'F'};
        int len = In.Length;
        Tree.root = buldTreeWrap(In, pre, len);

/* Let us test the built tree by printing
        Insorder traversal */

        Console.WriteLine("Inorder traversal of the constructed tree is");
        printInorder(Tree.root);
    }
}

/*C# program to construct a tree
using inorder and preorder traversal*/

using System;
using System.Collections.Generic;
public class TreeNode
{
    public int val;
    public TreeNode left;
    public TreeNode right;
    public TreeNode(int x) { val = x; }
}
class GFG
{
    static HashSet<TreeNode> set = new HashSet<TreeNode>();
    static Stack<TreeNode> stack = new Stack<TreeNode>();

/*    Function to build tree using given traversal*/

    public TreeNode buildTree(int[] preorder, int[] inorder)
    {
        TreeNode root = null;
        for (int pre = 0, iN = 0; pre < preorder.Length;)
        {
            TreeNode node = null;
            do {
                node = new TreeNode(preorder[pre]);
                if (root == null)
                {
                    root = node;
                }
                if (stack.Count != 0)
                {
                    if (set.Contains(stack.Peek()))
                    {
                        set.Remove(stack.Peek());
                        stack.Pop().right = node;
                    }
                    else
                    {
                        stack.Peek().left = node;
                    }
                }
                stack.Push(node);
            } while (preorder[pre++] != inorder[iN] &&
                     pre < preorder.Length);
            node = null;
            while (stack.Count != 0 && iN < inorder.Length &&
                   stack.Peek().val == inorder[iN])
            {
                node = stack.Pop();
                iN++;
            }
            if (node != null)
            {
                set.Add(node);
                stack.Push(node);
            }
        }
        return root;
    }

/*    Function to print tree in Inorder*/

    void printInorder(TreeNode node)
    {
        if (node == null)
            return;

/* first recur on left child */

        printInorder(node.left);

/* then print the data of node */

        Console.Write(node.val + " ");

/* now recur on right child */

        printInorder(node.right);
    }

/*    Driver Code*/

    public static void Main(String []args)
    {
        GFG tree = new GFG();
        int []iN = new int[] { 9, 8, 4, 2, 10, 5, 10,
                                 1, 6, 3, 13, 12, 7 };
        int []pre = new int[] { 1, 2, 4, 8, 9, 5, 10,
                                 10, 3, 6, 7, 12, 13 };
        int len = iN.Length;
        TreeNode root = tree.buildTree(pre, iN);
        tree.printInorder(root);
    }
}

/*C# program to construct binary tree from
given array in level order fashion*/

using System;
public class Tree
{
    Node root;

/*    Tree Node*/

    public class Node 
    {
        public int data;
        public Node left, right;
        public Node(int data)
        {
            this.data = data;
            this.left = null;
            this.right = null;
        }
    }

/*    Function to insert nodes in level order*/

    public Node insertLevelOrder(int[] arr,
                            Node root, int i)
    {

/*        Base case for recursion*/

        if (i < arr.Length) 
        {
            Node temp = new Node(arr[i]);
            root = temp;

/*            insert left child*/

            root.left = insertLevelOrder(arr, 
                            root.left, 2 * i + 1);

/*            insert right child*/

            root.right = insertLevelOrder(arr, 
                            root.right, 2 * i + 2);
        }
        return root;
    }

/*    Function to print tree
    nodes in InOrder fashion*/

    public void inOrder(Node root)
    {
        if (root != null) 
        {
            inOrder(root.left);
            Console.Write(root.data + " ");
            inOrder(root.right);
        }
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        Tree t2 = new Tree();
        int []arr = { 1, 2, 3, 4, 5, 6, 6, 6, 6 };
        t2.root = t2.insertLevelOrder(arr, t2.root, 0);
        t2.inOrder(t2.root);
    }
}

/*C# program for construction
of full binary tree*/

using System;
class GFG
{
public static int preindex;

/* A binary tree node has data, pointer to left child
and a pointer to right child */

public class node
{
    public int data;
    public node left, right;
    public node(int data)
    {
        this.data = data;
    }
}

/*A recursive function to construct Full
from pre[] and post[]. preIndex is used
to keep track of index in pre[]. l is
low index and h is high index for the
current subarray in post[]*/

public static node constructTreeUtil(int[] pre, int[] post,
                                     int l, int h, int size)
{

/*    Base case*/

    if (preindex >= size || l > h)
    {
        return null;
    }

/*    The first node in preorder traversal is
    root. So take the node at preIndex from
    preorder and make it root, and increment
    preIndex*/

    node root = new node(pre[preindex]);
    preindex++;

/*    If the current subarry has only one
    element, no need to recur or
    preIndex > size after incrementing*/

    if (l == h || preindex >= size)
    {
        return root;
    }
    int i;

/*    Search the next element
    of pre[] in post[]*/

    for (i = l; i <= h; i++)
    {
        if (post[i] == pre[preindex])
        {
            break;
        }
    }

/*    Use the index of element found
    in postorder to divide postorder
    array in two parts. Left subtree
    and right subtree*/

    if (i <= h)
    {
        root.left = constructTreeUtil(pre, post,
                                      l, i, size);
        root.right = constructTreeUtil(pre, post,
                                       i + 1, h, size);
    }
    return root;
}

/*The main function to construct Full
Binary Tree from given preorder and
postorder traversals. This function
mainly uses constructTreeUtil()*/

public static node constructTree(int[] pre,
                                 int[] post, int size)
{
    preindex = 0;
    return constructTreeUtil(pre, post, 0, size - 1, size);
}

/*A utility function to print inorder traversal of a Binary Tree*/

public static void printInorder(node root)
{
    if (root == null)
    {
        return;
    }
    printInorder(root.left);
    Console.Write(root.data + " ");
    printInorder(root.right);
}

/*Driver Code*/

public static void Main(string[] args)
{
    int[] pre = new int[] {1, 2, 4, 8, 9, 5, 3, 6, 7};
    int[] post = new int[] {8, 9, 4, 5, 2, 6, 7, 3, 1};
    int size = pre.Length;
    node root = constructTree(pre, post, size);
    Console.WriteLine("Inorder traversal of " +
                      "the constructed tree:");
    printInorder(root);
}
}

/*C# program to construct full binary tree 
using its preorder traversal and preorder 
traversal of its mirror tree */

using System;
class GFG
{

/*A Binary Tree Node */

public class Node 
{ 
    public int data; 
    public Node left, right; 
}; 
public class INT
{
    public int a;
    public INT(int a){this.a=a;}
}

/*Utility function to create a new tree node */

static Node newNode(int data) 
{ 
    Node temp = new Node(); 
    temp.data = data; 
    temp.left = temp.right = null; 
    return temp; 
}

/*A utility function to print inorder traversal 
of a Binary Tree */

static void printInorder(Node node) 
{ 
    if (node == null) 
        return; 
    printInorder(node.left); 
    Console.Write("{0} ", node.data); 
    printInorder(node.right); 
}

/*A recursive function to con Full binary tree 
from pre[] and preM[]. preIndex is used to keep 
track of index in pre[]. l is low index and h is high 
index for the current subarray in preM[] */

static Node conBinaryTreeUtil(int []pre, int []preM, 
                    INT preIndex, int l, int h, int size) 
{

/*    Base case */

    if (preIndex.a >= size || l > h) 
        return null;

/*    The first node in preorder traversal is root. 
    So take the node at preIndex from preorder and 
    make it root, and increment preIndex */

    Node root = newNode(pre[preIndex.a]); 
        ++(preIndex.a);

/*    If the current subarry has only one element, 
    no need to recur */

    if (l == h) 
        return root;

/*    Search the next element of pre[] in preM[] */

    int i; 
    for (i = l; i <= h; ++i) 
        if (pre[preIndex.a] == preM[i]) 
            break;

/*    con left and right subtrees recursively */

    if (i <= h) 
    { 
        root.left = conBinaryTreeUtil (pre, preM, 
                                    preIndex, i, h, size); 
        root.right = conBinaryTreeUtil (pre, preM, 
                                preIndex, l + 1, i - 1, size); 
    }

/*    return root */

    return root;     
}

/*function to con full binary tree 
using its preorder traversal and preorder 
traversal of its mirror tree */

static void conBinaryTree(Node root,int []pre, 
                        int []preMirror, int size) 
{ 
    INT preIndex = new INT(0); 
    int preMIndex = 0; 
    root = conBinaryTreeUtil(pre,preMirror, 
                            preIndex, 0, size - 1, size); 
    printInorder(root); 
}

/*Driver code*/

public static void Main(String []args)
{ 
    int []preOrder = {1,2,4,5,3,6,7}; 
    int []preOrderMirror = {1,3,7,6,2,5,4}; 
    int size = preOrder.Length; 
    Node root = new Node(); 
    conBinaryTree(root,preOrder,preOrderMirror,size); 
} 
}

/*C# program to construct a binary 
tree from preorder traversal */

using System;

/*A Binary Tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class Index
{
    public int index = 0;
}
class GFG
{
public Node root;
public Index myindex = new Index();

/* A recursive function to create a 
Binary Tree from given pre[] preLN[] arrays. 
The function returns root of tree. index_ptr 
is used to update index values in recursive 
calls. index must be initially passed as 0 */

public virtual Node constructTreeUtil(int[] pre, char[] preLN, 
                                      Index index_ptr, int n,
                                      Node temp)
{

/*    store the current value of index in pre[] */

    int index = index_ptr.index;

/*    Base Case: All nodes are constructed */

    if (index == n)
    {
        return null;
    }

/*    Allocate memory for this node 
    and increment index for 
    subsequent recursive calls */

    temp = new Node(pre[index]);
    (index_ptr.index)++;

/*    If this is an internal node, 
    construct left and right subtrees 
    and link the subtrees */

    if (preLN[index] == 'N')
    {
        temp.left = constructTreeUtil(pre, preLN, index_ptr,
                                      n, temp.left);
        temp.right = constructTreeUtil(pre, preLN, index_ptr,
                                       n, temp.right);
    }
    return temp;
}

/*A wrapper over constructTreeUtil() */

public virtual Node constructTree(int[] pre, char[] preLN, 
                                  int n, Node node)
{

/*    Initialize index as 0. Value of 
    index is used in recursion to 
    maintain the current index in 
    pre[] and preLN[] arrays. */

    int index = 0;
    return constructTreeUtil(pre, preLN, 
                             myindex, n, node);
}

