{
    GFG tree = new GFG();
    int[] pre = new int[]{10, 30, 20, 5, 15};
    char[] preLN = new char[]{'N', 'N', 'L', 'L', 'L'};
    int n = pre.Length;
    Node mynode = tree.constructTree(pre, preLN, 
                                     n, tree.root);
    Console.WriteLine("Following is Inorder Traversal of the" + 
                                  "Constructed Binary Tree: ");
