/*C# program to construct a binary
tree from parent array */

using System;

/*A binary tree node */

public class Node
{
    public int key;
    public Node left, right;
    public Node(int key)
    {
        this.key = key;
        left = right = null;
    }
}
class GFG
{
public Node root;

/*Creates a node with key as 'i'. 
If i is root, then it changes 
root. If parent of i is not created,
then it creates parent first */

public virtual void createNode(int[] parent, 
                               int i, Node[] created)
{

/*    If this node is already created */

    if (created[i] != null)
    {
        return;
    }

/*    Create a new node and set created[i] */

    created[i] = new Node(i);

/*    If 'i' is root, change root
    pointer and return */

    if (parent[i] == -1)
    {
        root = created[i];
        return;
    }

/*    If parent is not created, then
    create parent first */

    if (created[parent[i]] == null)
    {
        createNode(parent, parent[i], created);
    }

/*    Find parent pointer */

    Node p = created[parent[i]];

/*    If this is first child of parent */

    if (p.left == null)
    {
        p.left = created[i];
    }

/*If second child*/

else 
    {
        p.right = created[i];
    }
}

/* Creates tree from parent[0..n-1] 
and returns root of the created tree */

public virtual Node createTree(int[] parent, int n)
{

/*    Create an array created[] to 
    keep track of created nodes, 
    initialize all entries as NULL */

    Node[] created = new Node[n];
    for (int i = 0; i < n; i++)
    {
        created[i] = null;
    }
    for (int i = 0; i < n; i++)
    {
        createNode(parent, i, created);
    }
    return root;
}

/*For adding new line in a program */

public virtual void newLine()
{
    Console.WriteLine("");
}

/*Utility function to do inorder traversal */

public virtual void inorder(Node node)
{
    if (node != null)
    {
        inorder(node.left);
        Console.Write(node.key + " ");
        inorder(node.right);
    }
}

/*Driver Code */

public static void Main(string[] args)
{
    GFG tree = new GFG();
    int[] parent = new int[]{-1, 0, 0, 1, 1, 3, 5};
    int n = parent.Length;
    Node node = tree.createTree(parent, n);
    Console.WriteLine("Inorder traversal of " + 
                          "constructed tree ");
    tree.inorder(node);
    tree.newLine();
}
}

/*C# program to construct a tree using
inorder and postorder traversals*/

using System;

/* A binary tree node has data, pointer
to left child and a pointer to right child */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}

/*Class Index created to implement
pass by reference of Index*/

public class Index
{
    public int index;
}
class GFG
{

/* Recursive function to construct binary
of size n from Inorder traversal in[] and
Postrder traversal post[]. Initial values
of inStrt and inEnd should be 0 and n -1.
The function doesn't do any error checking
for cases where inorder and postorder do
not form a tree */

public virtual Node buildUtil(int[] @in, int[] post,
                              int inStrt, int inEnd,
                              Index pIndex)
{

/*    Base case*/

    if (inStrt > inEnd)
    {
        return null;
    }

/* Pick current node from Postrder traversal
    using postIndex and decrement postIndex */

    Node node = new Node(post[pIndex.index]);
    (pIndex.index)--;

/* If this node has no children
    then return */

    if (inStrt == inEnd)
    {
        return node;
    }

/* Else find the index of this node
    in Inorder traversal */

    int iIndex = search(@in, inStrt, inEnd, node.data);

/* Using index in Inorder traversal,
    construct left and right subtress */

    node.right = buildUtil(@in, post, iIndex + 1,
                                inEnd, pIndex);
    node.left = buildUtil(@in, post, inStrt,
                               iIndex - 1, pIndex);
    return node;
}

/*This function mainly initializes
index of root and calls buildUtil()*/

public virtual Node buildTree(int[] @in,
                              int[] post, int n)
{
    Index pIndex = new Index();
    pIndex.index = n - 1;
    return buildUtil(@in, post, 0, n - 1, pIndex);
}

/* Function to find index of value in
arr[start...end]. The function assumes
that value is postsent in in[] */

public virtual int search(int[] arr, int strt,
                          int end, int value)
{
    int i;
    for (i = strt; i <= end; i++)
    {
        if (arr[i] == value)
        {
            break;
        }
    }
    return i;
}

/* This funtcion is here just to test */

public virtual void preOrder(Node node)
{
    if (node == null)
    {
        return;
    }
    Console.Write(node.data + " ");
    preOrder(node.left);
    preOrder(node.right);
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    int[] @in = new int[] {4, 8, 2, 5, 1, 6, 3, 7};
    int[] post = new int[] {8, 4, 5, 2, 6, 7, 3, 1};
    int n = @in.Length;
    Node root = tree.buildTree(@in, post, n);
    Console.WriteLine("Preorder of the constructed tree : ");
    tree.preOrder(root);
}
}

