/*Index in postorder*/

index = len - 1; 
    return buildUtil(init, post, 0, len - 1 );
  }

/* Helper function that allocates a new node */

  static Node newNode(int data)
  {
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
  }

/* This funtcion is here just to test */

  static void preOrder(Node node)
  {
    if (node == null)
      return;
    Console.Write( node.data + " ");
    preOrder(node.left);
    preOrder(node.right);
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    int []init = { 4, 8, 2, 5, 1, 6, 3, 7 };
    int []post = { 8, 4, 5, 2, 6, 7, 3, 1 };
    int n = init.Length;
    Node root = buildTree(init, post, n);
    Console.Write("Preorder of the constructed tree : \n");
    preOrder(root);
  }
}

/*C# program for above approach*/

using System;
using System.Collections.Generic;
class GFG
{

/*  Node class*/

  public
    class Node
    {
      public
        int data;
      public
        Node left, right;

/*      Constructor*/

      public
        Node(int x)
      {
        data = x;
        left = right = null;
      }
    }

/*  Tree building function*/

  static Node buildTree(int []init, int []post,
                        int n)
  {

/*    Create Stack of type Node**/

    Stack<Node> st = new Stack<Node>();

/*    Create HashSet of type Node**/

    HashSet<Node> s = new HashSet<Node>();

/*    Initialise postIndex with n - 1*/

    int postIndex = n - 1;

/*    Initialise root with null*/

    Node root = null;
    for(int p = n - 1, i = n - 1; p >= 0;)
    {

/*      Initialise node with NULL*/

      Node node = null;

/*      Run do-while loop*/

      do
      {

/*        Initialise node with
        new Node(post[p]);*/

        node = new Node(post[p]);

/*        Check is root is
        equal to NULL*/

        if (root == null)
        {
          root = node;
        }

/*        If size of set
        is greater than 0*/

        if (st.Count > 0)
        {

/*          If st.Peek() is present in the
          set s*/

          if (s.Contains(st.Peek()))
          {
            s.Remove(st.Peek());
            st.Peek().left = node;
            st.Pop();
          }
          else
          {
            st.Peek().right = node;
          }
        }
        st.Push(node);
      }while (post[p--] != init[i] && p >= 0);
      node = null;

/*      If the stack is not empty and
      st.top().data is equal to in[i]*/

      while (st.Count > 0 && i >= 0 &&
             st.Peek().data == init[i])
      {
        node = st.Peek();

/*        Pop elements from stack*/

        st.Pop();
        i--;
      }

/*      If node not equal to NULL*/

      if (node != null)
      {
        s.Add(node);
        st.Push(node);
      }
    }

/*    Return root*/

    return root;
  }

/*  For print preOrder Traversal*/

  static void preOrder(Node node)
  {
    if (node == null)
      return;
    Console.Write(node.data + " ");
    preOrder(node.left);
    preOrder(node.right);
  }

/*  Driver Code*/

  public static void Main(String[] args)
  {
    int []init = { 4, 8, 2, 5, 1, 6, 3, 7 };
    int []post = { 8, 4, 5, 2, 6, 7, 3, 1 };
    int n = init.Length;

/*    Function Call*/

    Node root = buildTree(init, post, n);
    Console.Write(
      "Preorder of the constructed tree : \n");

/*    Function Call for preOrder*/

    preOrder(root);
  }
}

/*C# program to create a tree with left
child right sibling representation.*/

using System;
class GFG
{

/*Creating new Node*/

public class NodeTemp
{
    public int data;
    public NodeTemp next, child;
    public NodeTemp(int data)
    {
        this.data = data;
        next = child = null;
    }
}

/*Adds a sibling to a list with
starting with n*/

public static NodeTemp addSibling(NodeTemp node,
                                  int data)
{
    if (node == null)
    {
        return null;
    }
    while (node.next != null)
    {
        node = node.next;
    }
    return (node.next = new NodeTemp(data));
}

/*Add child Node to a Node*/

public static NodeTemp addChild(NodeTemp node,
                                int data)
{
    if (node == null)
    {
        return null;
    }

/*    Check if child is not empty.*/

    if (node.child != null)
    {
        return (addSibling(node.child,data));
    }
    else
    {
        return (node.child = new NodeTemp(data));
    }
}

/*Traverses tree in depth first order*/

public static void traverseTree(NodeTemp root)
{
    if (root == null)
    {
        return;
    }
    while (root != null)
    {
        Console.Write(root.data + " ");
        if (root.child != null)
        {
            traverseTree(root.child);
        }
        root = root.next;
    }
}

