    NodeTemp n6 = addChild(n5, 7);
    NodeTemp n7 = addChild(n5, 8);
    NodeTemp n8 = addChild(n5, 9);
    traverseTree(root);
}
}

/*C# program to create a tree with left child
right sibling representation.*/

using System;
using System.Collections.Generic;
class GFG
{
  public
    class Node
    {
      public
        int data;
      public
        Node next;
      public
        Node child;
    };

/*  Creating new Node*/

  static Node newNode(int data)
  {
    Node newNode = new Node();
    newNode.next = newNode.child = null;
    newNode.data = data;
    return newNode;
  }

/*  Adds a sibling to a list with starting with n*/

  static Node addSibling(Node n, int data)
  {
    if (n == null)
      return null;
    while (n.next != null)
      n = n.next;
    return (n.next = newNode(data));
  }

/*  Add child Node to a Node*/

  static Node addChild(Node n, int data)
  {
    if (n == null)
      return null;

/*    Check if child list is not empty.*/

    if (n.child != null)
      return addSibling(n.child, data);
    else
      return (n.child = newNode(data));
  }

/*  Traverses tree in level order*/

  static void traverseTree(Node root)
  {

/*    Corner cases*/

    if (root == null)
      return;
    Console.Write(root.data + " ");
    if (root.child == null)
      return;

/*    Create a queue and enque root*/

    Queue<Node> q = new Queue<Node>();
    Node curr = root.child;
    q.Enqueue(curr);
    while (q.Count != 0)
    {

/*      Take out an item from the queue*/

      curr = q.Peek();
      q.Dequeue();

/*      Print next level of taken out item and enque
      next level's children*/

      while (curr != null)
      {
        Console.Write(curr.data + " ");
        if (curr.child != null)
        {
          q.Enqueue(curr.child);
        }
        curr = curr.next;
      }
    }
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    Node root = newNode(10);
    Node n1 = addChild(root, 2);
    Node n2 = addChild(root, 3);
    Node n3 = addChild(root, 4);
    Node n4 = addChild(n3, 6);
    Node n5 = addChild(root, 5);
    Node n6 = addChild(n5, 7);
    Node n7 = addChild(n5, 8);
    Node n8 = addChild(n5, 9);
    traverseTree(root);
  }
}

/*C# program to construct tree from given Prufer Code*/

using System;
class GFG {

/*    Prints edges of tree represented by give Prufer code*/

    static void printTreeEdges(int[] prufer, int m)
    {
        int vertices = m + 2;
        int[] vertex_set = new int[vertices];

/*        Initialize the array of vertices*/

        for (int i = 0; i < vertices; i++)
            vertex_set[i] = 0;

/*        Number of occurrences of vertex in code*/

        for (int i = 0; i < vertices - 2; i++)
            vertex_set[prufer[i] - 1] += 1;
        Console.Write("\nThe edge set E(G) is :\n");

/*        Find the smallest label not present in
        prufer[].*/

        int j = 0;
        for (int i = 0; i < vertices - 2; i++) {
            for (j = 0; j < vertices; j++) {

/*                If j+1 is not present in prufer set*/

                if (vertex_set[j] == 0) {

/*                    Remove from Prufer set and print
                    pair.*/

                    vertex_set[j] = -1;
                    Console.Write("(" + (j + 1) + ", "
                                  + prufer[i] + ") ");
                    vertex_set[prufer[i] - 1]--;
                    break;
                }
            }
        }
        j = 0;

/*        For the last element*/

        for (int i = 0; i < vertices; i++) {
            if (vertex_set[i] == 0 && j == 0) {
                Console.Write("(" + (i + 1) + ", ");
                j++;
            }
            else if (vertex_set[i] == 0 && j == 1)
                Console.Write((i + 1) + ")\n");
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int[] prufer = { 4, 1, 3, 4 };
        int n = prufer.Length;
        printTreeEdges(prufer, n);
    }
}

/*C# program to build full k-ary tree from 
its preorder traversal and to print the 
postorder traversal of the tree. */

using System;
using System.Collections.Generic;
class GFG 
{

/*Structure of a node of an n-ary tree */

class Node 
{ 
    public int key; 
    public List<Node> child; 
};

/*Utility function to create a new tree 
node with k children */

static Node newNode(int value) 
{ 
    Node nNode = new Node(); 
    nNode.key = value; 
    nNode.child= new List<Node>(); 
    return nNode; 
} 
static int ind;

/*Function to build full k-ary tree */

static Node BuildKaryTree(int []A, int n, 
                          int k, int h) 
{

/*    For null tree */

    if (n <= 0) 
        return null; 
    Node nNode = newNode(A[ind]); 
    if (nNode == null) 
    { 
        Console.WriteLine("Memory error" ); 
        return null; 
    }

/*    For adding k children to a node */

    for (int i = 0; i < k; i++) 
    {

/*        Check if ind is in range of array 
        Check if height of the tree is greater than 1 */

        if (ind < n - 1 && h > 1) 
        { 
            ind++;

/*            Recursively add each child */

            nNode.child.Add(BuildKaryTree(A, n, k, h - 1)); 
        } 
        else
        { 
            nNode.child.Add(null); 
        } 
    } 
    return nNode; 
}

/*Function to find the height of the tree */

static Node BuildKaryTree_1(int[] A, int n, int k, int iN) 
{ 
    int height = (int)Math.Ceiling(Math.Log((double)n * (k - 1) + 1) / 
                                   Math.Log((double)k)); 
    ind = iN; 
    return BuildKaryTree(A, n, k, height); 
}

/*Function to print postorder traversal of the tree */

static void postord(Node root, int k) 
{ 
    if (root == null) 
        return; 
    for (int i = 0; i < k; i++) 
        postord(root.child[i], k); 
    Console.Write(root.key + " "); 
}

/*Driver Code */

public static void Main(String []args) 
{ 
    int ind = 0; 
    int k = 3, n = 10; 
    int []preorder = { 1, 2, 5, 6, 7, 3, 8, 9, 10, 4 }; 
    Node root = BuildKaryTree_1(preorder, n, k, ind); 
    Console.WriteLine("Postorder traversal of " + 
                      "constructed full k-ary tree is: "); 
    postord(root, k); 
    Console.WriteLine(); 
} 
}

/* C# program to cona binary tree from
   the given String */

using System;
using System.Collections.Generic;
public class GFG
{

/* A binary tree node has data, pointer to left
   child and a pointer to right child */

  public
 class Node
  {
    public
 int data;
    public
 Node left, right;
  };

/* Helper function that allocates a new node */

  static Node newNode(int data)
  {
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
  }

/* This funtcion is here just to test  */

  static void preOrder(Node node)
  {
    if (node == null)
      return;
    Console.Write("{0} ", node.data);
    preOrder(node.left);
    preOrder(node.right);
  }

/*  function to return the index of close parenthesis*/

  static int findIndex(String str, int si, int ei)
  {
    if (si > ei)
      return -1;

/*    Inbuilt stack*/

    Stack<char> s = new Stack<char>();
    for (int i = si; i <= ei; i++)
    {

/*      if open parenthesis, push it*/

      if (str[i] == '(')
        s.Push(str[i]);

/*      if close parenthesis*/

      else if (str[i] == ')')
      {
        if (s.Peek() == '(')
        {
          s.Pop();

/*          if stack is empty, this is
          the required index*/

          if (s.Count==0)
            return i;
        }
      }
    }

/*    if not found return -1*/

    return -1;
  }

/*  function to contree from String*/

  static Node treeFromString(String str, int si, int ei)
  {

/*    Base case*/

    if (si > ei)
      return null;

/*    new root*/

    Node root = newNode(str[si] - '0');
    int index = -1;

/*    if next char is '(' find the index of
    its complement ')'*/

    if (si + 1 <= ei && str[si+1] == '(')
      index = findIndex(str, si + 1, ei);

/*    if index found*/

    if (index != -1)
    {

/*      call for left subtree*/

      root.left = treeFromString(str, si + 2, index - 1);

/*      call for right subtree*/

      root.right
        = treeFromString(str, index + 2, ei - 1);
    }
    return root;
  }

/*  Driver Code*/

  public static void Main(String[] args)
  {
    String str = "4(2(3)(1))(6(5))";
    Node root = treeFromString(str, 0, str.Length - 1);
    preOrder(root);
  }
}

/*C# program to convert binary tree to double linked list*/
using System;

/* A binary tree node has data, and left and right pointers */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root;

/* This is the core function to convert Tree to list. This function
       follows steps 1 and 2 of the above algorithm */

    public virtual Node bintree2listUtil(Node node)
    {

/*        Base case*/

        if (node == null)
        {
            return node;
        }

/*        Convert the left subtree and link to root*/

        if (node.left != null)
        {

/*            Convert the left subtree*/

            Node left = bintree2listUtil(node.left);

/*            Find inorder predecessor. After this loop, left
            will point to the inorder predecessor*/

            for (; left.right != null; left = left.right)
            {
                ;
            }

/*            Make root as next of the predecessor*/

            left.right = node;

/*            Make predecssor as previous of root*/

            node.left = left;
        }

/*        Convert the right subtree and link to root*/

        if (node.right != null)
        {

/*            Convert the right subtree*/

            Node right = bintree2listUtil(node.right);

/*            Find inorder successor. After this loop, right
            will point to the inorder successor*/

            for (; right.left != null; right = right.left)
            {
                ;
            }

/*            Make root as previous of successor*/

            right.left = node;

/*            Make successor as next of root*/

            node.right = right;
        }
        return node;
    }

/*    The main function that first calls bintree2listUtil(), then follows
    step 3 of the above algorithm*/

    public virtual Node bintree2list(Node node)
    {

/*        Base case*/

        if (node == null)
        {
            return node;
        }

/*        Convert to DLL using bintree2listUtil()*/

        node = bintree2listUtil(node);

/*        bintree2listUtil() returns root node of the converted
        DLL.  We need pointer to the leftmost node which is
        head of the constructed DLL, so move to the leftmost node*/

        while (node.left != null)
        {
            node = node.left;
        }
        return node;
    }

/* Function to print nodes in a given doubly linked list */

    public virtual void printList(Node node)
    {
        while (node != null)
        {
            Console.Write(node.data + " ");
            node = node.right;
        }
    }

/* Driver program to test above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create the tree shown in above diagram*/

        tree.root = new Node(10);
        tree.root.left = new Node(12);
        tree.root.right = new Node(15);
        tree.root.left.left = new Node(25);
        tree.root.left.right = new Node(30);
        tree.root.right.left = new Node(36);

/*        Convert to DLL*/

        Node head = tree.bintree2list(tree.root);

/*        Print the converted list*/

        tree.printList(head);
    }
}

/*C# program to convert BTT to DLL using
simple inorder traversal*/

using System;
class GFG
{

/*A tree node*/

public class node
{
    public int data;
    public node left, right;
    public node(int data)
    {
        this.data = data;
    }
}
public static node prev;

/*Standard Inorder traversal of tree*/

public static void inorder(node root)
{
    if (root == null)
    {
        return;
    }
    inorder(root.left);
    Console.Write(root.data + " ");
    inorder(root.right);
}

/*Changes left pointers to work as previous
pointers in converted DLL The function
simply does inorder traversal of Binary
Tree and updates left pointer using
previously visited node*/

public static void fixPrevptr(node root)
{
    if (root == null)
    {
        return;
    }
    fixPrevptr(root.left);
    root.left = prev;
    prev = root;
    fixPrevptr(root.right);
}

/*Changes right pointers to work
as next pointers in converted DLL*/

public static node fixNextptr(node root)
{

/*    Find the right most node in
    BT or last node in DLL*/

    while (root.right != null)
    {
        root = root.right;
    }

/*    Start from the rightmost node, traverse
    back using left pointers. While traversing,
    change right pointer of nodes*/

    while (root != null && root.left != null)
    {
        node left = root.left;
        left.right = root;
        root = root.left;
    }

/*    The leftmost node is head of
    linked list, return it*/

    return root;
}

/*The main function that converts
BST to DLL and returns head of DLL*/

public static node BTTtoDLL(node root)
{
    prev = null;

/*    Set the previous pointer*/

    fixPrevptr(root);

/*    Set the next pointer and
    return head of DLL*/

    return fixNextptr(root);
}

/*Traverses the DLL from left tor right*/

public static void printlist(node root)
{
    while (root != null)
    {
        Console.Write(root.data + " ");
        root = root.right;
    }
}

/*Driver code*/

public static void Main()
{

/*    Let us create the tree
    shown in above diagram*/

    node root = new node(10);
    root.left = new node(12);
    root.right = new node(15);
    root.left.left = new node(25);
    root.left.right = new node(30);
    root.right.left = new node(36);
    Console.WriteLine("Inorder Tree Traversal");
    inorder(root);
    node head = BTTtoDLL(root);
    Console.WriteLine("\nDLL Traversal");
    printlist(head);
}
}

/*A C# program for in-place conversion
of Binary Tree to DLL*/

using System;

/*A binary tree node has data, left
pointers and right pointers*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}
class GFG
{
public Node root;

/*head --> Pointer to head node of
created doubly linked list*/

public Node head;

/*A simple recursive function to
convert a given Binary tree
to Doubly Linked List
root --> Root of Binary Tree*/

public virtual void BinaryTree2DoubleLinkedList(Node root)
{

/*    Base case*/

    if (root == null)
    {
        return;
    }

/*Initialize previously visited node
as NULL. This is static so that the
same value is accessible in all
recursive calls*/

public static Node prev = null;

/*    Recursively convert left subtree*/

    BinaryTree2DoubleLinkedList(root.left);

/*    Now convert this node*/

    if (prev == null)
    {
        head = root;
    }
    else
    {
        root.left = prev;
        prev.right = root;
    }
    prev = root;

/*    Finally convert right subtree*/

    BinaryTree2DoubleLinkedList(root.right);
}

/* Function to print nodes in a
   given doubly linked list */

public virtual void printList(Node node)
{
    while (node != null)
    {
        Console.Write(node.data + " ");
        node = node.right;
    }
}

/*Driver Code*/

public static void Main(string[] args)
{

/*    Let us create the tree as
    shown in above diagram*/

    GFG tree = new GFG();
    tree.root = new Node(10);
    tree.root.left = new Node(12);
    tree.root.right = new Node(15);
    tree.root.left.left = new Node(25);
    tree.root.left.right = new Node(30);
    tree.root.right.left = new Node(36);

/*    convert to DLL*/

    tree.BinaryTree2DoubleLinkedList(tree.root);

/*    Print the converted List*/

    tree.printList(tree.head);
}
}

/*C# program to convert an arbitrary 
binary tree to a tree that holds 
children sum property */

using System;

/*A binary tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class GFG
{
public Node root;

/* This function changes a tree to 
hold children sum property */

public virtual void convertTree(Node node)
{
    int left_data = 0, right_data = 0, diff;

/* If tree is empty or it's a leaf 
    node then return true */

    if (node == null || (node.left == null && 
                         node.right == null))
    {
        return;
    }
    else
    {

/* convert left and right subtrees */

        convertTree(node.left);
        convertTree(node.right);

/* If left child is not present then 
        0 is used as data of left child */

        if (node.left != null)
        {
            left_data = node.left.data;
        }

/* If right child is not present then 
        0 is used as data of right child */

        if (node.right != null)
        {
            right_data = node.right.data;
        }

/* get the diff of node's data 
           and children sum */

        diff = left_data + right_data - node.data;

/* If node's children sum is greater 
           than the node's data */

        if (diff > 0)
        {
            node.data = node.data + diff;
        }

/* THIS IS TRICKY --> If node's data is 
        greater than children sum, then increment
        subtree by diff */

        if (diff < 0)
        {

/*            -diff is used to make diff positive */

            increment(node, -diff);
        }
    }
}

/* This function is used to increment 
subtree by diff */

public virtual void increment(Node node, int diff)
{

/* IF left child is not NULL then 
    increment it */

    if (node.left != null)
    {
        node.left.data = node.left.data + diff;

/*        Recursively call to fix the 
        descendants of node->left */

        increment(node.left, diff);
    }

/*Else increment right child*/

else if (node.right != null) 
    {
        node.right.data = node.right.data + diff;

/*        Recursively call to fix the 
        descendants of node->right */

        increment(node.right, diff);
    }
}

/* Given a binary tree, printInorder() 
prints out its inorder traversal*/

public virtual void printInorder(Node node)
{
    if (node == null)
    {
        return;
    }

/* first recur on left child */

    printInorder(node.left);

/* then print the data of node */

    Console.Write(node.data + " ");

/* now recur on right child */

    printInorder(node.right);
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node(50);
    tree.root.left = new Node(7);
    tree.root.right = new Node(2);
    tree.root.left.left = new Node(3);
    tree.root.left.right = new Node(5);
    tree.root.right.left = new Node(1);
    tree.root.right.right = new Node(30);
    Console.WriteLine("Inorder traversal " + 
                  "before conversion is :");
    tree.printInorder(tree.root);
    tree.convertTree(tree.root);
    Console.WriteLine("");
    Console.WriteLine("Inorder traversal " + 
                   "after conversion is :");
    tree.printInorder(tree.root);
}
}

/*C# program to convert left-right to 
down-right representation of binary tree */

using System;
class GFG
{

/*A Binary Tree Node */

public class node
{
    public int key;
    public node left, right;
    public node(int key)
    {
        this.key = key;
        this.left = null;
        this.right = null;
    }
}

/*An Iterative level order traversal 
based function to convert left-right 
to down-right representation. */

public static void convert(node root)
{

/*    Base Case */

    if (root == null)
    {
        return;
    }

/*    Recursively convert left 
    an right subtrees */

    convert(root.left);
    convert(root.right);

/*    If left child is NULL, make right 
    child as left as it is the first child. */

    if (root.left == null)
    {
        root.left = root.right;
    }

/*    If left child is NOT NULL, then make 
    right child as right of left child */

    else
    {
        root.left.right = root.right;
    }

/*    Set root's right as NULL */

    root.right = null;
}

/*A utility function to traverse a 
tree stored in down-right form. */

public static void downRightTraversal(node root)
{
    if (root != null)
    {
        Console.Write(root.key + " ");
        downRightTraversal(root.right);
        downRightTraversal(root.left);
    }
}

/*Utility function to create 
a new tree node */

public static node newNode(int key)
{
    node temp = new node(0);
    temp.key = key;
    temp.left = null;
    temp.right = null;
    return temp;
}

/*Driver Code */

public static void Main(string[] args)
{

/*    Let us create binary tree 
    shown in above diagram */

/* 
        1 
        / \ 
        2 3 
            / \ 
            4 5 
        / / \ 
        6 7 8 
    */

    node root = new node(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.right.left = newNode(4);
    root.right.right = newNode(5);
    root.right.left.left = newNode(6);
    root.right.right.left = newNode(7);
    root.right.right.right = newNode(8);
    convert(root);
    Console.WriteLine("Traversal of the tree " + 
                      "converted to down-right form");
    downRightTraversal(root);
}
}

/*C# program to convert a tree 
into its sum tree */

using System;

/*A binary tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class GFG
{
public Node root;

/*Convert a given tree to a tree where 
every node contains sum of values of 
nodes in left and right subtrees in 
the original tree */

public virtual int toSumTree(Node node)
{

/*    Base case */

    if (node == null)
    {
        return 0;
    }

/*    Store the old value */

    int old_val = node.data;

/*    Recursively call for left and 
    right subtrees and store the sum 
    as new value of this node */

    node.data = toSumTree(node.left) + 
                toSumTree(node.right);

/*    Return the sum of values of nodes 
    in left and right subtrees old_value 
    of this node */

    return node.data + old_val;
}

/*A utility function to print
inorder traversal of a Binary Tree */

public virtual void printInorder(Node node)
{
    if (node == null)
    {
        return;
    }
    printInorder(node.left);
    Console.Write(node.data + " ");
    printInorder(node.right);
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();

/* Constructing tree given in
       the above figure */

    tree.root = new Node(10);
    tree.root.left = new Node(-2);
    tree.root.right = new Node(6);
    tree.root.left.left = new Node(8);
    tree.root.left.right = new Node(-4);
    tree.root.right.left = new Node(7);
    tree.root.right.right = new Node(5);
    tree.toSumTree(tree.root);

/*    Print inorder traversal of the 
    converted tree to test result of toSumTree() */

    Console.WriteLine("Inorder Traversal of " + 
                     "the resultant tree is:");
    tree.printInorder(tree.root);
}
}

/*C# program to store sum of nodes in left  
subtree in every node */

using System;
class GfG 
{

/*A tree node */

class node 
{ 
    public int data; 
    public node left, right; 
}

/*Function to modify a Binary Tree so 
that every node stores sum of values 
in its left child including its own value */

static int updatetree(node root) 
{

/*    Base cases */

    if (root == null) 
        return 0; 
    if (root.left == null && root.right == null) 
        return root.data;

/*    Update left and right subtrees */

    int leftsum = updatetree(root.left); 
    int rightsum = updatetree(root.right);

/*    Add leftsum to current node */

    root.data += leftsum;

/*    Return sum of values under root */

    return root.data + rightsum; 
}

/*Utility function to do inorder traversal */

static void inorder(node node) 
{ 
    if (node == null) 
        return; 
    inorder(node.left); 
    Console.Write(node.data + " "); 
    inorder(node.right); 
}

/*Utility function to create a new node */

static node newNode(int data) 
{ 
    node node = new node(); 
    node.data = data; 
    node.left = null; 
    node.right = null; 
    return(node); 
}

