{

/* Let us construct below tree 
                1 
            / \ 
            2 3 
            / \ \ 
            4 5 6 */

    node root = newNode(1); 
    root.left = newNode(2); 
    root.right = newNode(3); 
    root.left.left = newNode(4); 
    root.left.right = newNode(5); 
    root.right.right = newNode(6); 
    updatetree(root); 
    Console.WriteLine("Inorder traversal of the modified tree is"); 
    inorder(root); 
} 
}

/*C# program to convert binary 
tree into its mirror */

using System;

/*Class containing left and right 
child of current node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/* Change a tree so that the roles of the left and 
    right pointers are swapped at every node.
So the tree...
    4
    / \
    2 5
    / \
1 3
is changed to...
    4
    / \
    5 2
        / \
    3 1
*/

class GFG
{
public Node root;
public virtual void mirror()
{
    root = mirror(root);
}
public virtual Node mirror(Node node)
{
    if (node == null)
    {
        return node;
    }

/* do the subtrees */

    Node left = mirror(node.left);
    Node right = mirror(node.right);

/* swap the left and right pointers */

    node.left = right;
    node.right = left;
    return node;
}
public virtual void inOrder()
{
    inOrder(root);
}

/* Helper function to test mirror(). 
Given a binary search tree, print out its 
data elements in increasing sorted order.*/

public virtual void inOrder(Node node)
{
    if (node == null)
    {
        return;
    }
    inOrder(node.left);
    Console.Write(node.data + " ");
    inOrder(node.right);
}

/* testing for example nodes */

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node(1);
    tree.root.left = new Node(2);
    tree.root.right = new Node(3);
    tree.root.left.left = new Node(4);
    tree.root.left.right = new Node(5);

/* print inorder traversal of the input tree */

    Console.WriteLine("Inorder traversal " + 
                      "of input tree is :");
    tree.inOrder();
    Console.WriteLine("");

/* convert tree to its mirror */

    tree.mirror();

/* print inorder traversal of the minor tree */

    Console.WriteLine("Inorder traversal " + 
                    "of binary tree is : ");
    tree.inOrder();
}
}

/*C# Iterative Java program to convert a Binary
Tree to its mirror*/

using System.Collections.Generic;
using System;
class GFG
{

/* A binary tree node has data, pointer to
left child and a pointer to right child */

public class Node
{
    public int data;
    public Node left;
    public Node right;
};

/* Helper function that allocates a new node
with the given data and null left and right
pointers. */

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return(node);
}

/* Change a tree so that the roles of the left and
    right pointers are swapped at every node.
So the tree...
    4
    / \
    2 5
    / \
1 3
is changed to...
    4
    / \
    5 2
        / \
    3 1
*/

static void mirror(Node root)
{
    if (root == null)
        return;
    Queue<Node> q = new Queue<Node>(); 
    q.Enqueue(root);

/*    Do BFS. While doing BFS, keep swapping
    left and right children*/

    while (q.Count > 0)
    {

/*        pop top node from queue*/

        Node curr = q.Peek();
        q.Dequeue();

/*        swap left child with right child*/

        Node temp = curr.left;
        curr.left = curr.right;
        curr.right = temp;;

/*        push left and right children*/

        if (curr.left != null)
            q.Enqueue(curr.left);
        if (curr.right != null)
            q.Enqueue(curr.right);
    }
}

/* Helper function to print Inorder traversal.*/

static void inOrder( Node node)
{
    if (node == null)
        return;
    inOrder(node.left);
    Console.Write( node.data + " ");
    inOrder(node.right);
}

/* Driver code */

public static void Main(String []args)
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);

/* Print inorder traversal of the input tree */

    Console.Write( "\n Inorder traversal of the"
            +" coned tree is \n");
    inOrder(root);

/* Convert tree to its mirror */

    mirror(root);

/* Print inorder traversal of the mirror tree */

    Console.Write( "\n Inorder traversal of the "+
        "mirror tree is \n");
    inOrder(root);
}
}

/* C# program to convert Binary Tree into Doubly Linked List 
where the nodes are represented spirally */

using System;
using System.Collections.Generic;

/*A binary tree node*/

public class Node 
{
    public int data;
    public Node left, right;
    public Node(int data) 
    {
        this.data = data;
        left = right = null;
    }
}
public class BinaryTree 
{
    Node root;
    Node head;

/* Given a reference to a node,
    inserts the node on the front of the list. */

    void push(Node node) 
    {

/*        Make right of given node as head and left as
        NULL*/

        node.right = head;
        node.left = null;

/*        change left of head node to given node*/

        if (head != null) 
            head.left = node;

/*        move the head to point to the given node*/

        head = node;
    }

/*    Function to prints contents of DLL*/

    void printList(Node node) 
    {
        while (node != null) 
        {
            Console.Write(node.data + " ");
            node = node.right;
        }
    }

/* Function to print corner node at each level */

    void spiralLevelOrder(Node root) 
    {

/*        Base Case*/

        if (root == null)
            return;

/*        Create an empty deque for doing spiral
        level order traversal and enqueue root*/

        LinkedList<Node> q = new LinkedList<Node>();
        q.AddFirst(root);

/*        create a stack to store Binary Tree nodes
        to insert into DLL later*/

        Stack<Node> stk = new Stack<Node>();
        int level = 0;
        while (q.Count != 0) 
        {

/*            nodeCount indicates number of Nodes
            at current level.*/

            int nodeCount = q.Count;

/*            Dequeue all Nodes of current level and
            Enqueue all Nodes of next level
odd level*/

if ((level & 1) % 2 != 0) 
            {
                while (nodeCount > 0) 
                {

/*                    dequeue node from front & push it to
                    stack*/

                    Node node = q.First.Value;
                    q.RemoveFirst();
                    stk.Push(node);

/*                    insert its left and right children
                    in the back of the deque*/

                    if (node.left != null)
                        q.AddLast(node.left);
                    if (node.right != null)
                        q.AddLast(node.right);
                    nodeCount--;
                }
            }

/*even level*/

else 
            {
                while (nodeCount > 0) 
                {

/*                    dequeue node from the back & push it
                    to stack*/

                    Node node = q.Last.Value;
                    q.RemoveLast();
                    stk.Push(node);

/*                    inserts its right and left children
                    in the front of the deque*/

                    if (node.right != null)
                        q.AddFirst(node.right);
                    if (node.left != null)
                        q.AddFirst(node.left);
                    nodeCount--;
                }
            }
            level++;
        }

/*        pop all nodes from stack and
        push them in the beginning of the list*/

        while (stk.Count != 0) 
        {
            push(stk.Peek());
            stk.Pop();
        }
        Console.WriteLine("Created DLL is : ");
        printList(head);
    }

/*    Driver program to test above functions*/

    public static void Main(String[] args) 
    {

/*        Let us create binary tree as shown in above diagram*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        tree.root.left.left.left = new Node(8);
        tree.root.left.left.right = new Node(9);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(11);

/*        tree.root.right.left.left = new Node(12);*/

        tree.root.right.left.right = new Node(13);
        tree.root.right.right.left = new Node(14);

/*        tree.root.right.right.right = new Node(15);*/

        tree.spiralLevelOrder(tree.root);
    }
}

/*C# program to find maximum number
to be removed to convert a tree into
forest containing trees of even number of nodes*/

using System;
using System.Collections.Generic;
class GFG
{
    static int N = 12, ans;
    static List<List<int>> tree = new List<List<int>>();

/*    Return the number of nodes of
    subtree having node as a root.*/

    static int dfs(int []visit, int node)
    {
        int num = 0, temp = 0;

/*        Mark node as visited.*/

        visit[node] = 1;

/*        Traverse the adjacency list to
        find non-visited node.*/

        for (int i = 0; i < tree[node].Count; i++)
        {
            if (visit[tree[node][i]] == 0)
            {

/*                Finding number of nodes of the
                subtree of a subtree.*/

                temp = dfs(visit, tree[node][i]);

/*                If nodes are even, increment number of
                edges to removed.
                Else leave the node as child of subtree.*/

                if(temp % 2 != 0)
                    num += temp;
                else
                    ans++;
            }
        }
        return num + 1;
    }

/*    Return the maximum number of edge
    to remove to make forest.*/

    static int minEdge(int n)
    {
        int []visit = new int[n + 2];
        ans = 0;
        dfs(visit, 1);
        return ans;
    }

/*    Driver Code*/

    public static void Main(String []args)
    {
        int n = 10;
        for(int i = 0; i < n + 2;i++)
        tree.Add(new List<int>());
        tree[1].Add(3);
        tree[3].Add(1);
        tree[1].Add(6);
        tree[6].Add(1);
        tree[1].Add(2);
        tree[2].Add(1);
        tree[3].Add(4);
        tree[4].Add(3);
        tree[6].Add(8);
        tree[8].Add(6);
        tree[2].Add(7);
        tree[7].Add(2);
        tree[2].Add(5);
        tree[5].Add(2);
        tree[4].Add(9);
        tree[9].Add(4);
        tree[4].Add(10);
        tree[10].Add(4);
        Console.WriteLine(minEdge(n));
    }
}

/*C# code to convert a given binary tree 
to a tree that holds logical AND property.*/

using System;
class GfG 
{

/*Structure of binary tree */

class Node 
{ 
    public int data; 
    public Node left; 
    public Node right; 
}

/*function to create a new node */

static Node newNode(int key) 
{ 
    Node node = new Node(); 
    node.data= key; 
    node.left = null; 
    node.right = null; 
    return node; 
}

/*Convert the given tree to a tree where 
each node is logical AND of its children 
The main idea is to do Postorder traversal */

static void convertTree(Node root) 
{ 
    if (root == null) 
        return;

/* first recur on left child */

    convertTree(root.left);

/* then recur on right child */

    convertTree(root.right); 
    if (root.left != null && root.right != null) 
        root.data = (root.left.data) & (root.right.data); 
} 
static void printInorder(Node root) 
{ 
    if (root == null) 
        return;

/* first recur on left child */

    printInorder(root.left);

/* then print the data of node */

    Console.Write(root.data + " ");

/* now recur on right child */

    printInorder(root.right); 
}

/*Driver code*/

public static void Main() 
{

/* Create following Binary Tree 
            1 
        / \ 
        1 0 
        / \ / \ 
        0 1 1 1 
            */

    Node root=newNode(0); 
    root.left=newNode(1); 
    root.right=newNode(0); 
    root.left.left=newNode(0); 
    root.left.right=newNode(1); 
    root.right.left=newNode(1); 
    root.right.right=newNode(1); 
