    printInorder(root); 
    convertTree(root); 
    Console.WriteLine();
    Console.Write("Inorder traversal after conversion "); 
    printInorder(root); 
}
}

/*C# program to convert a ternary 
expreesion to a tree. */

using System;

/*Class to represent Tree node */

public class Node
{
    public char data;
    public Node left, right;
    public Node(char item)
    {
        data = item;
        left = null;
        right = null;
    }
}

/*Class to convert a ternary 
expression to a Tree */

public class BinaryTree
{

/*    Function to convert Ternary Expression 
    to a Binary Tree. It return the root of tree */

    public virtual Node convertExpression(char[] expression,
                                          int i)
    {

/*        Base case */

        if (i >= expression.Length)
        {
            return null;
        }

/*        store current character of 
        expression_string [ 'a' to 'z'] */

        Node root = new Node(expression[i]);

/*        Move ahead in str */

        ++i;

/*        if current character of ternary expression 
        is '?' then we add next character as a 
        left child of current node */

        if (i < expression.Length && expression[i] == '?')
        {
            root.left = convertExpression(expression, i + 1);
        }

/*        else we have to add it as a right child 
        of current node expression.at(0) == ':' */

        else if (i < expression.Length)
        {
            root.right = convertExpression(expression, i + 1);
        }
        return root;
    }

/*    function print tree */

    public virtual void printTree(Node root)
    {
        if (root == null)
        {
            return;
        }
        Console.Write(root.data + " ");
        printTree(root.left);
        printTree(root.right);
    }

/*Driver Code*/

public static void Main(string[] args)
{
    string exp = "a?b?c:d:e";
    BinaryTree tree = new BinaryTree();
    char[] expression = exp.ToCharArray();
    Node root = tree.convertExpression(expression, 0);
    tree.printTree(root);
}
}

/*C# program to flip a binary tree*/

using System;
using System.Collections.Generic;
public class FlipTree
{

/* A binary tree node structure */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
    }
};

/*    method to flip the binary tree*/

    public static Node flipBinaryTree(Node root)
    {
        if (root == null)
            return root;
        if (root.left == null && root.right ==null)
            return root;

/*        recursively call the same method*/

        Node flippedRoot = flipBinaryTree(root.left);

/*        rearranging main root Node after returning
        from recursive call*/

        root.left.left = root.right;
        root.left.right = root;
        root.left = root.right = null;
        return flippedRoot;
    }

/*    Iterative method to do level order traversal
    line by line*/

    public static void printLevelOrder(Node root)
    {

/*        Base Case*/

        if(root == null)
            return ;

/*        Create an empty queue for level order traversal*/

        Queue<Node> q = new Queue<Node>();

/*        Enqueue Root and initialize height*/

        q.Enqueue(root);
        while(true)
        {

/*            nodeCount (queue size) indicates number
            of nodes at current lelvel.*/

            int nodeCount = q.Count;
            if (nodeCount == 0)
                break;

/*            Dequeue all nodes of current level and
            Enqueue all nodes of next level*/

            while (nodeCount > 0)
            {
                Node node = q.Dequeue();
                Console.Write(node.data+" ");
                if (node.left != null)
                    q.Enqueue(node.left);
                if (node.right != null)
                    q.Enqueue(node.right);
                nodeCount--;
            }
            Console.WriteLine();
        }
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(1);
        root.right.left = new Node(4);
        root.right.right = new Node(5);
        Console.WriteLine("Level order traversal of given tree");
        printLevelOrder(root);
        root = flipBinaryTree(root);
        Console.WriteLine("Level order traversal of flipped tree");
        printLevelOrder(root);
    }
}

/*C# program to flip a binary tree*/

using System;
using System.Collections.Generic;
class GFG
{

/*A binary tree node*/

public class Node
{
    public int data;
    public Node left, right;
}

/*Utility function to create
a new Binary Tree Node*/

public static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*method to flip the binary tree*/

public static Node flipBinaryTree(Node root)
{

/*    Initialization of pointers*/

    Node curr = root;
    Node next = null;
    Node temp = null;
    Node prev = null;

/*    Iterate through all left nodes*/

    while (curr != null)
    {
        next = curr.left;

/*        Swapping nodes now, need
        temp to keep the previous
        right child
        Making prev's right
        as curr's left child*/

        curr.left = temp;

/*        Storing curr's right child*/

        temp = curr.right;

/*        Making prev as curr's
        right child*/

        curr.right = prev;
        prev = curr;
        curr = next;
    }
    return prev;
}

/*Iterative method to do level
order traversal line by line*/

public static void printLevelOrder(Node root)
{

/*    Base Case*/

    if (root == null)
    {
        return;
    }

/*    Create an empty queue for
    level order traversal*/

    LinkedList<Node> q = new LinkedList<Node>();

/*    Enqueue Root and
    initialize height*/

    q.AddLast(root);
    while (true)
    {

/*        nodeCount (queue size)
        indicates number of nodes
        at current lelvel.*/

        int nodeCount = q.Count;
        if (nodeCount == 0)
        {
            break;
        }

/*        Dequeue all nodes of current
        level and Enqueue all nodes
        of next level*/

        while (nodeCount > 0)
        {
            Node node = q.First.Value;
            Console.Write(node.data + " ");
            q.RemoveFirst();
            if (node.left != null)
            {
                q.AddLast(node.left);
            }
            if (node.right != null)
            {
                q.AddLast(node.right);
            }
            nodeCount--;
        }
        Console.WriteLine();
    }
}

/*Driver code*/

public static void Main(string[] args)
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.right.left = newNode(4);
    root.right.right = newNode(5);
    Console.Write("Level order traversal " +
                         "of given tree\n");
    printLevelOrder(root);
    root = flipBinaryTree(root);
    Console.Write("\nLevel order traversal " +
                     "of the flipped tree\n");
    printLevelOrder(root);
}
}

/*C# program to check children sum property */

using System;

/* A binary tree node has data, pointer 
to left child and a pointer to right child */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
class GFG
{
public Node root;

/* returns 1 if children sum property holds 
for the given node and both of its children*/

public virtual int isSumProperty(Node node)
{

/* left_data is left child data and 
    right_data is for right child data*/

    int left_data = 0, right_data = 0;

/* If node is NULL or it's a leaf 
    node then return true */

    if (node == null || (node.left == null && 
                         node.right == null))
    {
        return 1;
    }
    else
    {

/* If left child is not present 
        then 0 is used as data of left child */

        if (node.left != null)
        {
            left_data = node.left.data;
        }

/* If right child is not present then 
        0 is used as data of right child */

        if (node.right != null)
        {
            right_data = node.right.data;
        }

/* if the node and both of its children 
        satisfy the property return 1 else 0*/

        if ((node.data == left_data + right_data) && 
                  (isSumProperty(node.left) != 0) && 
                   isSumProperty(node.right) != 0)
        {
            return 1;
        }
        else
        {
            return 0;
        }
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node(10);
    tree.root.left = new Node(8);
    tree.root.right = new Node(2);
    tree.root.left.left = new Node(3);
    tree.root.left.right = new Node(5);
    tree.root.right.right = new Node(2);
    if (tree.isSumProperty(tree.root) != 0)
    {
        Console.WriteLine("The given tree satisfies" + 
                            " children sum property");
    }
    else
    {
        Console.WriteLine("The given tree does not" + 
                   " satisfy children sum property");
    }
}
}

/*C# program to find sum of covered 
and uncovered nodes of a binary tree */

using System;

/* A binary tree node has key, pointer
to left child and a pointer to right child */

public class Node
{
    public int key;
    public Node left, right;
    public Node(int key)
    {
        this.key = key;
        left = right = null;
    }
}
class GFG
{
public Node root;

/* Utility function to calculate 
sum of all node of tree */

public virtual int sum(Node t)
{
    if (t == null)
    {
        return 0;
    }
    return t.key + sum(t.left) + 
                   sum(t.right);
}

/* Recursive function to calculate 
sum of left boundary elements */

public virtual int uncoveredSumLeft(Node t)
{

/* If left node, then just return
       its key value */

    if (t.left == null && t.right == null)
    {
        return t.key;
    }

/* If left is available then go
       left otherwise go right */

    if (t.left != null)
    {
        return t.key + uncoveredSumLeft(t.left);
    }
    else
    {
        return t.key + uncoveredSumLeft(t.right);
    }
}

/* Recursive function to calculate 
   sum of right boundary elements */

public virtual int uncoveredSumRight(Node t)
{

/* If left node, then just return 
       its key value */

    if (t.left == null && t.right == null)
    {
        return t.key;
    }

/* If right is available then go
       right otherwise go left */

    if (t.right != null)
    {
        return t.key + uncoveredSumRight(t.right);
    }
    else
    {
        return t.key + uncoveredSumRight(t.left);
    }
}

/*Returns sum of uncovered elements */

public virtual int uncoverSum(Node t)
{

/* Initializing with 0 in case we 
    don't have left or right boundary */

    int lb = 0, rb = 0;
    if (t.left != null)
    {
        lb = uncoveredSumLeft(t.left);
    }
    if (t.right != null)
    {
        rb = uncoveredSumRight(t.right);
    }

/* returning sum of root node, 
    left boundary and right boundary*/

    return t.key + lb + rb;
}

/*Returns true if sum of covered 
and uncovered elements is same. */

public virtual bool isSumSame(Node root)
{

/*    Sum of uncovered elements */

    int sumUC = uncoverSum(root);

/*    Sum of all elements */

    int sumT = sum(root);

/*    Check if sum of covered and
    uncovered is same */

    return (sumUC == (sumT - sumUC));
}

/* Helper function to print inorder 
traversal of binary tree */

public virtual void inorder(Node root)
{
    if (root != null)
    {
        inorder(root.left);
        Console.Write(root.key + " ");
        inorder(root.right);
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();

/*    Making above given diagram's binary tree */

    tree.root = new Node(8);
    tree.root.left = new Node(3);
    tree.root.left.left = new Node(1);
    tree.root.left.right = new Node(6);
    tree.root.left.right.left = new Node(4);
    tree.root.left.right.right = new Node(7);
    tree.root.right = new Node(10);
    tree.root.right.right = new Node(14);
    tree.root.right.right.left = new Node(13);
    if (tree.isSumSame(tree.root))
    {
        Console.WriteLine("Sum of covered and " +
                            "uncovered is same");
    }
    else
    {
        Console.WriteLine("Sum of covered and " + 
                        "uncovered is not same");
    }
}
}

/*C# program to check if two binary 
tree are cousins */

using System;

/*A Binary Tree Node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class GFG
{
public Node root;

/*Recursive function to check if 
two Nodes are siblings */

public virtual bool isSibling(Node node, 
                              Node a, Node b)
{

/*    Base case */

    if (node == null)
    {
        return false;
    }
    return ((node.left == a && node.right == b) || 
            (node.left == b && node.right == a) || 
                     isSibling(node.left, a, b) || 
                     isSibling(node.right, a, b));
}

/*Recursive function to find level 
of Node 'ptr' in a binary tree */

public virtual int level(Node node, Node ptr, int lev)
{

/*    base cases */

    if (node == null)
    {
        return 0;
    }
    if (node == ptr)
    {
        return lev;
    }

/*    Return level if Node is present 
    in left subtree */

    int l = level(node.left, ptr, lev + 1);
    if (l != 0)
    {
        return l;
    }

/*    Else search in right subtree */

    return level(node.right, ptr, lev + 1);
}

/*Returns 1 if a and b are cousins, 
otherwise 0 */

public virtual bool isCousin(Node node, 
                             Node a, Node b)
{

/*    1. The two Nodes should be on the 
          same level in the binary tree. 
    2. The two Nodes should not be siblings 
    (means that they should not have the 
      same parent Node). */

    return ((level(node, a, 1) == level(node, b, 1)) && 
                            (!isSibling(node, a, b)));
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node(1);
    tree.root.left = new Node(2);
    tree.root.right = new Node(3);
    tree.root.left.left = new Node(4);
    tree.root.left.right = new Node(5);
    tree.root.left.right.right = new Node(15);
    tree.root.right.left = new Node(6);
    tree.root.right.right = new Node(7);
    tree.root.right.left.right = new Node(8);
    Node Node1, Node2;
    Node1 = tree.root.left.left;
    Node2 = tree.root.right.right;
    if (tree.isCousin(tree.root, Node1, Node2))
    {
        Console.WriteLine("Yes");
    }
    else
    {
        Console.WriteLine("No");
    }
}
}

/*C# program to check if all leaves
are at same level*/

using System;

/*A binary tree node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class Leaf
{
    public int leaflevel = 0;
}
class GFG
{
public Node root;
public Leaf mylevel = new Leaf();

/* Recursive function which checks
whether all leaves are at same level */

public virtual bool checkUtil(Node node, int level,
                              Leaf leafLevel)
{

/*    Base case*/

    if (node == null)
    {
        return true;
    }

/*    If a leaf node is encountered*/

    if (node.left == null && node.right == null)
    {

/*        When a leaf node is found first time*/

        if (leafLevel.leaflevel == 0)
        {

/*            Set first found leaf's level*/

            leafLevel.leaflevel = level;
            return true;
        }

/*        If this is not first leaf node,
        compare its level with first leaf's level*/

        return (level == leafLevel.leaflevel);
    }

/*    If this node is not leaf, recursively
    check left and right subtrees*/

    return checkUtil(node.left, level + 1, leafLevel) &&
           checkUtil(node.right, level + 1, leafLevel);
}

/* The main function to check if all leafs
are at same level. It mainly uses checkUtil() */

public virtual bool check(Node node)
{
    int level = 0;
    return checkUtil(node, level, mylevel);
}

/*Driver Code*/

public static void Main(string[] args)
{

/*    Let us create the tree as shown in the example*/

    GFG tree = new GFG();
    tree.root = new Node(12);
    tree.root.left = new Node(5);
    tree.root.left.left = new Node(3);
    tree.root.left.right = new Node(9);
    tree.root.left.left.left = new Node(1);
    tree.root.left.right.left = new Node(1);
    if (tree.check(tree.root))
    {
        Console.WriteLine("Leaves are at same level");
    }
    else
    {
        Console.WriteLine("Leaves are not at same level");
    }
}
}

/*C# program to check if all leaf nodes are at
same level of binary tree*/

using System;
using System.Collections.Generic;

/*User defined node class*/

public class Node
{
    public int data;
    public Node left, right;

/*    Constructor to create a new tree node*/

    public Node(int key)
    {
        int data = key;
        left = right = null;
    }
}
public class GFG
{

/*    return true if all leaf nodes are
    at same level, else false*/

    static bool checkLevelLeafNode(Node root)
    {
            if (root == null)
                return true;

/*            create a queue for level order traversal*/

            Queue<Node> q = new Queue<Node>();
            q.Enqueue(root);
            int result = int.MaxValue;
            int level = 0;

/*            traverse until the queue is empty*/

            while (q.Count != 0)
            {
                    int size = q.Count;
                    level++;

/*                    traverse for complete level*/

                    while (size > 0)
                    {
                        Node temp = q.Dequeue();

/*                        check for left child*/

                        if (temp.left != null)
                        {
                            q.Enqueue(temp.left);

/*                            if its leaf node*/

                            if (temp.left.left != null &&
                                temp.left.right != null)
                            {

/*                                if it's first leaf node, then update result*/

                                if (result == int.MaxValue)
                                    result = level;

/*                                if it's not first leaf node, then compare
                                the level with level of previous leaf node.*/

                                else if (result != level)
                                    return false;
                            }
                        }

/*                        check for right child*/

                        if (temp.right != null)
                        {
                            q.Enqueue(temp.right);

/*                            if its leaf node*/

                            if (temp.right.left != null &&
                                temp.right.right != null)
                            {

/*                                if it's first leaf node, then update result*/

                                if (result == int.MaxValue)
                                    result = level;

/*                                if it's not first leaf node, then compare
                                the level with level of previous leaf node.*/

                                else if (result != level)
                                    return false;
                            }
                        }
                        size--;
                    }
            }
            return true;
    }

/*    Driver code*/

    public static void Main(String []args)
    {

/*        construct a tree*/

        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.right = new Node(4);
        root.right.left = new Node(5);
        root.right.right = new Node(6);
        bool result = checkLevelLeafNode(root);
        if (result == true)
            Console.WriteLine("All leaf nodes are at same level");
        else
            Console.WriteLine("Leaf nodes not at same level");
    }
}

/*C# program to check if there exist
an edge whose removal creates two
trees of same size*/

using System;
public class Node
{
    public int key;
    public Node left, right;
    public Node(int key)
    {
        this.key = key;
        left = right = null;
    }
}
class GFG
{
public Node root;

/*To calculate size of tree with given root*/

public virtual int count(Node node)
{
    if (node == null)
    {
        return 0;
    }
    return count(node.left) +
           count(node.right) + 1;
}

/*This function returns true if there
is an edge whose removal can divide
the tree in two halves n is size of tree*/

public virtual bool checkRec(Node node, int n)
{

/*    Base cases*/

    if (node == null)
    {
        return false;
    }

/*    Check for root*/

    if (count(node) == n - count(node))
    {
        return true;
    }

/*    Check for rest of the nodes*/

    return checkRec(node.left, n) ||
           checkRec(node.right, n);
}

/*This function mainly uses checkRec()*/

public virtual bool check(Node node)
{

/*    Count total nodes in given tree*/

    int n = count(node);

/*    Now recursively check all nodes*/

    return checkRec(node, n);
}

/*Driver code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node(5);
    tree.root.left = new Node(1);
    tree.root.right = new Node(6);
    tree.root.left.left = new Node(3);
    tree.root.right.left = new Node(7);
    tree.root.right.right = new Node(4);
    if (tree.check(tree.root) == true)
    {
        Console.WriteLine("YES");
    }
    else
    {
        Console.WriteLine("NO");
    }
}
}

/*C# program to check if there exist an edge whose
removal creates two trees of same size*/

using System;
public class Node
{
    public int key;
    public Node left, right;
    public Node(int key)
    {
        this.key = key;
        left = right = null;
    }
}
public class Res
{
    public bool res = false;
}
public class BinaryTree
{
    public Node root;

/*    To calculate size of tree with given root*/

    public virtual int count(Node node)
    {
        if (node == null)
        {
            return 0;
        }
        return count(node.left) + count(node.right) + 1;
    }

/*    This function returns size of tree rooted with given
    root. It also set "res" as true if there is an edge
    whose removal divides tree in two halves.
    n is size of tree*/

    public virtual int checkRec(Node root, int n, Res res)
    {

/*        Base case*/

        if (root == null)
        {
            return 0;
        }

/*        Compute sizes of left and right children*/

        int c = checkRec(root.left, n, res) + 1 + checkRec(root.right, n, res);

/*        If required property is true for current node
        set "res" as true*/

        if (c == n - c)
        {
            res.res = true;
        }

/*        Return size*/

        return c;
    }

/*    This function mainly uses checkRec()*/

    public virtual bool check(Node root)
    {

/*        Count total nodes in given tree*/

        int n = count(root);

/*        Initialize result and recursively check all nodes*/

        Res res = new Res();
        checkRec(root, n, res);
        return res.res;
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(5);
        tree.root.left = new Node(1);
        tree.root.right = new Node(6);
        tree.root.left.left = new Node(3);
        tree.root.right.left = new Node(7);
        tree.root.right.right = new Node(4);
        if (tree.check(tree.root) == true)
        {
            Console.WriteLine("YES");
        }
        else
        {
            Console.WriteLine("NO");
        }
    }
}

/* C# program to check if all three given
traversals are of the same tree */

using System;
public class GfG
{
    static int preIndex = 0;

/*    A Binary Tree Node*/

    class Node
    {
        public int data;
        public Node left, right;
    }

/*    Utility function to create a new tree node*/

    static Node newNode(int data)
    {
        Node temp = new Node();
        temp.data = data;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/* Function to find index of
    value in arr[start...end]
    The function assumes that
    value is present in in[] */

    static int search(int []arr, int strt,
                        int end, int value)
    {
        for (int i = strt; i <= end; i++)
        {
            if(arr[i] == value)
                return i;
        }
        return -1;
    }

/* Recursive function to construct
    binary tree of size len from Inorder
    traversal in[] and Preorder traversal
    pre[]. Initial values of inStrt and
    inEnd should be 0 and len -1. The
    function doesn't do any error checking for
    cases where inorder and preorder do not form a
    tree */

    static Node buildTree(int []In, int []pre,
                            int inStrt, int inEnd)
    {
        if(inStrt > inEnd)
            return null;

/* Pick current node from Preorder traversal
        using preIndex and increment preIndex */

        Node tNode = newNode(pre[preIndex++]);

/* If this node has no children then return */

        if (inStrt == inEnd)
            return tNode;

/* Else find the index of this node in
        Inorder traversal */

        int inIndex = search(In, inStrt, inEnd, tNode.data);

/* Using index in Inorder traversal,
        construct left and right subtress */

        tNode.left = buildTree(In, pre, inStrt, inIndex - 1);
        tNode.right = buildTree(In, pre, inIndex + 1, inEnd);
        return tNode;
    }

/* function to compare Postorder traversal
    on constructed tree and given Postorder */

    static int checkPostorder(Node node, int []postOrder, int index)
    {
        if (node == null)
            return index;

/* first recur on left child */

        index = checkPostorder(node.left,postOrder,index);

/* now recur on right child */

        index = checkPostorder(node.right,postOrder,index);

/* Compare if data at current index in
        both Postorder traversals are same */

        if (node.data == postOrder[index])
            index++;
        else
            return -1;
        return index;
    }

/*    Driver code*/

    public static void Main()
    {
        int []inOrder = {4, 2, 5, 1, 3};
        int []preOrder = {1, 2, 4, 5, 3};
        int []postOrder = {4, 5, 2, 3, 1};
        int len = inOrder.Length;

/*        build tree from given
        Inorder and Preorder traversals*/

        Node root = buildTree(inOrder, preOrder, 0, len - 1);

/*        compare postorder traversal on constructed
        tree with given Postorder traversal*/

        int index = checkPostorder(root, postOrder, 0);

/*        If both postorder traversals are same*/

        if (index == len)
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*C# program to check if a given tree 
is Binary Heap or not */

using System;
class GFG
{

/*Returns true if given level 
order traversal is Min Heap. */

public static bool isMinHeap(int[] level)
{
    int n = level.Length - 1;

/*    First non leaf node is at
    index (n/2-1). Check whether 
    each parent is greater than child */

    for (int i = (n / 2 - 1) ; i >= 0 ; i--)
    {

/*        Left child will be at index 2*i+1 
        Right child will be at index 2*i+2 */

        if (level[i] > level[2 * i + 1])
        {
            return false;
        }
        if (2 * i + 2 < n)
        {

/*            If parent is greater than right child */

            if (level[i] > level[2 * i + 2])
            {
            return false;
            }
        }
    }
    return true;
}

/*Driver code */

public static void Main(string[] args)
{
    int[] level = new int[]{10, 15, 14, 25, 30};
    if (isMinHeap(level))
    {
        Console.WriteLine("True");
    }
    else
    {
        Console.WriteLine("False");
    }
}
}

/*C# program to check if two Leaf Traversal
of Two Binary Trees is same or not*/

using System;
using System.Collections.Generic;

/*Binary Tree node*/

public class Node {
    public int data;
    public Node left, right;
    public Node(int x)
    {
        data = x;
        left = right = null;
    }

/*checks if a given node is leaf or not.*/

    public virtual bool Leaf
    {
        get { 
          return (left == null && right == null); 
        }
    }
}
class GFG {

/*    Returns true of leaf traversal of
    two trees is same, else false*/

    public static bool isSame(Node root1, Node root2)
    {

/*        Create empty stacks. These stacks
        are going to be used for iterative
        traversals.*/

        Stack<Node> s1 = new Stack<Node>();
        Stack<Node> s2 = new Stack<Node>();
        s1.Push(root1);
        s2.Push(root2);

/*        Loop until either of two stacks
        is not empty*/

        while (s1.Count > 0 || s2.Count > 0)
        {

/*            If one of the stacks is empty means other
            stack has extra leaves so return false*/

            if (s1.Count == 0 || s2.Count == 0)
            {
                return false;
            }
            Node temp1 = s1.Pop();
            while (temp1 != null && !temp1.Leaf) 
            {

/*                Push right and left children of temp1.
                Note that right child is inserted
                before left*/

                if (temp1.right != null) 
                {
                    s1.Push(temp1.right);
                }
                if (temp1.left != null) 
                {
                    s1.Push(temp1.left);
                }
                temp1 = s1.Pop();
            }

/*            same for tree2*/

            Node temp2 = s2.Pop();
            while (temp2 != null && !temp2.Leaf) 
            {
                if (temp2.right != null) 
                {
                    s2.Push(temp2.right);
                }
                if (temp2.left != null) 
                {
                    s2.Push(temp2.left);
                }
                temp2 = s2.Pop();
            }

/*            If one is null and other is not,
            then return false*/

            if (temp1 == null && temp2 != null) 
            {
                return false;
            }
            if (temp1 != null && temp2 == null) 
            {
                return false;
            }

/*            If both are not null and data
            is not same return false*/

            if (temp1 != null && temp2 != null) 
            {
                if (temp1.data != temp2.data) 
                {
                    return false;
                }
            }
        }

/*        If control reaches this point,
        all leaves are matched*/

        return true;
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {

/*        Let us create trees in above example 1*/

        Node root1 = new Node(1);
        root1.left = new Node(2);
        root1.right = new Node(3);
        root1.left.left = new Node(4);
        root1.right.left = new Node(6);
        root1.right.right = new Node(7);
        Node root2 = new Node(0);
        root2.left = new Node(1);
        root2.right = new Node(5);
        root2.left.right = new Node(4);
        root2.right.left = new Node(6);
        root2.right.right = new Node(7);
        if (isSame(root1, root2)) {
            Console.WriteLine("Same");
        }
        else {
            Console.WriteLine("Not Same");
