/*C# implementation to check whether a binary 
tree is a full binary tree or not*/

using System;
using System.Collections.Generic;
class GfG 
{

/*structure of a node of binary tree */

public class Node 
{ 
    public int data; 
    public Node left, right; 
}

/*function to get a new node */

static Node getNode(int data) 
{

/*    allocate space */

    Node newNode = new Node();

/*    put in the data */

    newNode.data = data; 
    newNode.left = null;
    newNode.right = null; 
    return newNode; 
}

/*function to check whether a binary tree 
is a full binary tree or not */

static bool isFullBinaryTree(Node root) 
{

/*    if tree is empty */

    if (root == null) 
        return true;

/*    queue used for level order traversal */

    Queue<Node> q = new Queue<Node> ();

/*    push 'root' to 'q' */

    q.Enqueue(root);

/*    traverse all the nodes of the binary tree 
    level by level until queue is empty */

    while (q.Count!=0) {

/*        get the pointer to 'node' at front 
        of queue */

        Node node = q.Peek(); 
        q.Dequeue();

/*        if it is a leaf node then continue */

        if (node.left == null && node.right == null) 
            continue;

/*        if either of the child is not null and the 
        other one is null, then binary tree is not 
        a full binary tee */

        if (node.left == null || node.right == null) 
            return false;

/*        push left and right childs of 'node' 
        on to the queue 'q' */

        q.Enqueue(node.left); 
        q.Enqueue(node.right); 
    }

/*    binary tree is a full binary tee */

    return true; 
}

/*Driver code */

public static void Main(String[] args) 
{ 
    Node root = getNode(1); 
    root.left = getNode(2); 
    root.right = getNode(3); 
    root.left.left = getNode(4); 
    root.left.right = getNode(5); 
    if (isFullBinaryTree(root)) 
        Console.WriteLine("Yes"); 
    else
        Console.WriteLine("No"); 
} 
}

/*C# Program to check if a given Binary
Tree is balanced like a Red-Black Tree */

using System;

/* utility that allocates a new Node with the given key  */

class GFG
{
public class Node
{
    public int key;
    public Node left, right;
    public Node(int key)
    {
        left = null;
        right = null;
        this.key = key;
    }
}
public class INT
{
    public int d;
    public INT()
    {
        d = 0;
    }
}

/*Returns returns tree if the Binary 
tree is balanced like a Red-Black
tree. This function also sets value
in maxh and minh (passed by reference).
maxh and minh are set as maximum and 
minimum heights of root.*/

static bool isBalancedUtil(Node root,
                        INT maxh, INT minh)
{

/*    Base case*/

    if (root == null)
    {
        maxh.d = minh.d = 0;
        return true;
    }

/*    To store max and min heights of left subtree*/

    INT lmxh = new INT(), lmnh = new INT();

/*    To store max and min heights of right subtree*/

    INT rmxh = new INT(), rmnh = new INT();

/*    Check if left subtree is balanced, 
    also set lmxh and lmnh*/

    if (isBalancedUtil(root.left, lmxh, lmnh) == false)
        return false;

/*    Check if right subtree is balanced,
    also set rmxh and rmnh*/

    if (isBalancedUtil(root.right, rmxh, rmnh) == false)
        return false;

/*    Set the max and min heights 
    of this node for the parent call*/

    maxh.d = Math.Max(lmxh.d, rmxh.d) + 1;
    minh.d = Math.Min(lmnh.d, rmnh.d) + 1;

/*    See if this node is balanced*/

    if (maxh.d <= 2 * minh.d)
        return true;
    return false;
}

/*A wrapper over isBalancedUtil()*/

static bool isBalanced(Node root)
{
    INT maxh = new INT(), minh = new INT();
    return isBalancedUtil(root, maxh, minh);
}

/*Driver code*/

public static void Main(String []args)
{
    Node root = new Node(10);
    root.left = new Node(5);
    root.right = new Node(100);
    root.right.left = new Node(50);
    root.right.right = new Node(150);
    root.right.left.left = new Node(40);
    Console.WriteLine(isBalanced(root) ? 
            "Balanced" : "Not Balanced");
}
}

/*C# Program to check duplicates 
in Binary Tree */

using System;
using System.Collections;
using System.Collections.Generic; 
class CheckDuplicateValues
{

/*    Function that used HashSet to 
    find presence of duplicate nodes*/

    public static Boolean checkDupUtil(Node root, HashSet<int> s) 
    {

/*        If tree is empty, there are no 
        duplicates. */

        if (root == null) 
            return false;

/*        If current node's data is already present. */

        if (s.Contains(root.data)) 
            return true;

/*        Insert current node */

        s.Add(root.data);

/*        Recursively check in left and right 
        subtrees. */

        return checkDupUtil(root.left, s) || 
                checkDupUtil(root.right, s); 
    }

/*    To check if tree has duplicates */

    public static Boolean checkDup(Node root) 
    { 
        HashSet<int> s = new HashSet<int>();
        return checkDupUtil(root, s); 
    } 
    public static void Main(String []args) 
    {
        Node root = new Node(1); 
        root.left = new Node(2); 
        root.right = new Node(2); 
        root.left.left = new Node(3); 
        if (checkDup(root)) 
            Console.Write("Yes"); 
        else
            Console.Write("No"); 
    }
}

