/*C# program to find if there is a duplicate
sub-tree of size 2 or more.*/

using System;
using System.Collections.Generic;
class GFG
{
    static char MARKER = '$';

/*A binary tree Node has data,
pointer to left child
and a pointer to right child*/

public class Node
{
    public int data;
    public Node left,right;
    public Node(int data)
    {
        this.data = data;
    }
};

/*    This function returns empty string if tree
    contains a duplicate subtree of size 2 or more.*/

    public static String dupSubUtil(Node root,
                    HashSet<String> subtrees)
    {
        String s = "";

/*        If current node is NULL, return marker*/

        if (root == null)
            return s + MARKER;

/*        If left subtree has a duplicate subtree.*/

        String lStr = dupSubUtil(root.left,subtrees);
        if (lStr.Equals(s))
            return s;

/*        Do same for right subtree*/

        String rStr = dupSubUtil(root.right,subtrees);
        if (rStr.Equals(s))
            return s;

/*        Serialize current subtree*/

        s = s + root.data + lStr + rStr;

/*        If current subtree already exists in hash
        table. [Note that size of a serialized tree
        with single node is 3 as it has two marker
        nodes.*/

        if (s.Length > 3 && subtrees.Contains(s))
            return "";
        subtrees.Add(s);
        return s;
    }

/*    Function to find if the Binary Tree contains
    duplicate subtrees of size 2 or more*/

    public static String dupSub(Node root)
    {
        HashSet<String> subtrees = new HashSet<String>();
        return dupSubUtil(root,subtrees);
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        Node root = new Node('A');
        root.left = new Node('B');
        root.right = new Node('C');
        root.left.left = new Node('D');
        root.left.right = new Node('E');
        root.right.right = new Node('B');
        root.right.right.right = new Node('E');
        root.right.right.left= new Node('D');
        String str = dupSub(root);
        if(str.Equals(""))
            Console.Write(" Yes ");
        else
            Console.Write(" No ");
    }
}

/*c# program to see if two trees
are mirror of each other*/

using System;

/*A binary tree node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node a, b;

/* Given two trees, return true if they are
    mirror of each other */

    public virtual bool areMirror(Node a, Node b)
    {

/* Base case : Both empty */

        if (a == null && b == null)
        {
            return true;
        }

/*        If only one is empty*/

        if (a == null || b == null)
        {
            return false;
        }

/* Both non-empty, compare them recursively
        Note that in recursive calls, we pass left
        of one tree and right of other tree */

        return a.data == b.data && areMirror(a.left, b.right)
                            && areMirror(a.right, b.left);
    }

/*    Driver code to test above methods*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        Node a = new Node(1);
        Node b = new Node(1);
        a.left = new Node(2);
        a.right = new Node(3);
        a.left.left = new Node(4);
        a.left.right = new Node(5);
        b.left = new Node(3);
        b.right = new Node(2);
        b.right.left = new Node(5);
        b.right.right = new Node(4);
        if (tree.areMirror(a, b) == true)
        {
            Console.WriteLine("Yes");
        }
        else
        {
            Console.WriteLine("No");
        }
    }
}

/*C# implementation to check whether the two 
binary tress are mirrors of each other or not*/

using System;
using System.Collections.Generic;
class GfG 
{

/*    structure of a node in binary tree */

    public class Node 
    { 
        public int data; 
        public Node left, right; 
    }

/*    Utility function to create and return 
    a new node for a binary tree */

    static Node newNode(int data) 
    { 
        Node temp = new Node(); 
        temp.data = data; 
        temp.left = null;
        temp.right = null; 
        return temp; 
    }

/*    function to check whether the two binary trees 
    are mirrors of each other or not */

    static String areMirrors(Node root1, Node root2) 
    { 
        Stack<Node> st1 = new Stack<Node> ();
        Stack<Node> st2 = new Stack<Node> (); 
        while (true) 
        {

/*            iterative inorder traversal of 1st tree and 
            reverse inoder traversal of 2nd tree */

            while (root1 != null && root2 != null) 
            {

/*                if the corresponding nodes in the two traversal 
                have different data values, then they are not 
                mirrors of each other. */

                if (root1.data != root2.data) 
                    return "No"; 
                st1.Push(root1); 
                st2.Push(root2); 
                root1 = root1.left; 
                root2 = root2.right;     
            }

/*            if at any point one root becomes null and 
            the other root is not null, then they are 
            not mirrors. This condition verifies that 
            structures of tree are mirrors of each other. */

            if (!(root1 == null && root2 == null)) 
                return "No"; 
            if (st1.Count != 0 && st2.Count != 0) 
            { 
                root1 = st1.Peek(); 
                root2 = st2.Peek(); 
                st1.Pop(); 
                st2.Pop();

/* we have visited the node and its left subtree. 
                Now, it's right subtree's turn */

                root1 = root1.right;

/* we have visited the node and its right subtree. 
                Now, it's left subtree's turn */

                root2 = root2.left; 
            }

/*            both the trees have been completely traversed */

            else
                break; 
        }

/*        tress are mirrors of each other */

        return "Yes"; 
    }

/*    Driver program to test above */

    public static void Main(String[] args) 
    {

/*        1st binary tree formation */

        Node root1 = newNode(1);

/*         1         */

        root1.left = newNode(3);

/*     / \     */

        root1.right = newNode(2);

/*     3     2     */

        root1.right.left = newNode(5);

/*         / \     */

        root1.right.right = newNode(4);

/*        2nd binary tree formation     */

        Node root2 = newNode(1);

/*         1         */

        root2.left = newNode(2);

/*     / \     */

        root2.right = newNode(3);

/*     2     3     */

        root2.left.left = newNode(4);

/* / \         */

        root2.left.right = newNode(5);

/* 4 5         */

        Console.WriteLine(areMirrors(root1, root2)); 
    }
}

/*C# program to see if two trees are identical */
using System;

/*A binary tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root1, root2;

/* Given two trees, return true if they are 
       structurally identical */

    public virtual bool identicalTrees(Node a, Node b)
    {

/*1. both empty */

        if (a == null && b == null)
        {
            return true;
        }

/* 2. both non-empty -> compare them */

        if (a != null && b != null)
        {
            return (a.data == b.data && identicalTrees(a.left, b.left) && identicalTrees(a.right, b.right));
        }

/* 3. one empty, one not -> false */

        return false;
    }

/* Driver program to test identicalTrees() function */

    public static void Main(string[] args)
    {
