        tree.root2.left = new Node(2);
        tree.root2.right = new Node(3);
        tree.root2.left.left = new Node(4);
        tree.root2.left.right = new Node(5);
        if (tree.identicalTrees(tree.root1, tree.root2))
        {
            Console.WriteLine("Both trees are identical");
        }
        else
        {
            Console.WriteLine("Trees are not identical");
        }
    }
}

/* Iterative C# program to check if two */

using System;
using System.Collections.Generic;
class GfG 
{

/*A Binary Tree Node */

class Node 
{ 
    public int data; 
    public Node left, right; 
}

/*Iterative method to find height of Binary Tree */

static bool areIdentical(Node root1, Node root2) 
{

/*    Return true if both trees are empty */

    if (root1 == null && root2 == null) 
        return true;

/*    Return false if one is empty and other is not */

    if (root1 == null || root2 == null) 
        return false;

/*    Create an empty queues for 
    simultaneous traversals */

    Queue<Node> q1 = new Queue<Node> (); 
    Queue<Node> q2 = new Queue<Node> ();

/*    Enqueue Roots of trees in respective queues */

    q1.Enqueue(root1); 
    q2.Enqueue(root2); 
    while (q1.Count != 0 && q2.Count != 0) 
    {

/*        Get front nodes and compare them */

        Node n1 = q1.Peek(); 
        Node n2 = q2.Peek(); 
        if (n1.data != n2.data) 
        return false;

/*        Remove front nodes from queues */

        q1.Dequeue(); 
        q2.Dequeue();

/* Enqueue left children of both nodes */

        if (n1.left != null && n2.left != null) 
        { 
            q1.Enqueue(n1.left); 
            q2.Enqueue(n2.left); 
        }

/*        If one left child is empty and other is not */

        else if (n1.left != null || n2.left != null) 
            return false;

/*        Right child code (Similar to left child code) */

        if (n1.right != null && n2.right != null) 
        { 
            q1.Enqueue(n1.right); 
            q2.Enqueue(n2.right); 
        } 
        else if (n1.right != null || n2.right != null) 
            return false; 
    } 
    return true; 
}

/*Utility function to create a new tree node */

static Node newNode(int data) 
{ 
    Node temp = new Node(); 
    temp.data = data; 
    temp.left = null; 
    temp.right = null; 
    return temp; 
}

/*Driver code */

public static void Main(String[] args) 
{ 
    Node root1 = newNode(1); 
    root1.left = newNode(2); 
    root1.right = newNode(3); 
    root1.left.left = newNode(4); 
    root1.left.right = newNode(5); 
    Node root2 = newNode(1); 
    root2.left = newNode(2); 
    root2.right = newNode(3); 
    root2.left.left = newNode(4); 
    root2.left.right = newNode(5); 
    if(areIdentical(root1, root2) == true) 
    Console.WriteLine("Yes"); 
    else
    Console.WriteLine("No"); 
} 
}

/*C# program to see if there
is a root to leaf path 
with given sequence. */

using System;
public class CheckForPath 
{

/* A binary tree node has data, 
pointer to left child and a
pointer to right child */

public class Node 
{ 
    public int data; 
    public Node left, right; 
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
};

/*    function to check given sequence
    of root to leaf path exist 
    in tree or not. 
    index represents current element
    in sequence of rooth to 
    leaf path */

    public static bool existPath(Node root,
                        int []arr, int index)
    {

/*        If root is NULL, then there
        must not be any element 
        in array. */

        if(root == null)
        {
            return arr.Length == 0;
        }

/*        If this node is a leaf and matches with last entry 
        of array. */

        if((root.left == null && root.right == null) && 
                                (root.data == arr[index] &&
                                root.data == arr[arr.Length - 1]))
        {
            return true;
        }

/*        If current node is equal to arr[index] this means 
        that till this level path has been matched and 
        remaining path can be either in left subtree or 
        right subtree. */

        return (index < arr.Length && (root.data == arr[index] && 
                       (existPath(root.left,arr,index + 1) || 
                        existPath(root.right, arr, index + 1))));
    }

/*    Driver code*/

    public static void Main() 
    {

/*        arr[] is sequence of root to leaf path */

        int []arr = {5, 8, 6, 7}; 
        Node root=new Node(5);
        root.left=new Node(3);
        root.right=new Node(8);
        root.left.left = new Node(2); 
        root.left.right = new Node(4); 
        root.left.left.left = new Node(1); 
        root.right.left = new Node(6); 
        root.right.left.right = new Node(7); 
        if(existPath(root, arr, 0))
        {
            Console.Write("Path Exists");
        }
        else
        {
            Console.Write("Path does not Exist");
        }
    } 
}

/*C# program to print cousins of a node */

using System;
public class GfG 
{

/*A Binary Tree Node */

class Node 
{ 
    public int data; 
    public Node left, right; 
}

/*A utility function to create  
a new Binary Tree Node */

static Node newNode(int item) 
{ 
    Node temp = new Node(); 
    temp.data = item; 
    temp.left = null;
    temp.right = null; 
    return temp; 
}

/* It returns level of the node
if it is present in tree,
 otherwise returns 0.*/

static int getLevel(Node root,
            Node node, int level) 
{

/*    base cases */

    if (root == null) 
        return 0; 
    if (root == node) 
        return level;

/*    If node is present in left subtree */

    int downlevel = getLevel(root.left, node, level + 1); 
    if (downlevel != 0) 
        return downlevel;

/*    If node is not present in left subtree */

    return getLevel(root.right, node, level + 1); 
}

/* Print nodes at a given level 
such that sibling of node is
 not printed if it exists */

static void printGivenLevel(Node root,
                    Node node, int level) 
{

/*    Base cases */

    if (root == null || level < 2) 
        return;

/*    If current node is parent of a node with 
    given level */

    if (level == 2) 
    { 
        if (root.left == node || root.right == node) 
            return; 
        if (root.left != null) 
            Console.Write(root.left.data + " "); 
        if (root.right != null) 
            Console.Write(root.right.data + " "); 
    }

/*    Recur for left and right subtrees */

    else if (level > 2) 
    { 
        printGivenLevel(root.left, node, level - 1); 
        printGivenLevel(root.right, node, level - 1); 
    } 
}

/*This function prints cousins of a given node */

static void printCousins(Node root, Node node) 
{

/*    Get level of given node */

    int level = getLevel(root, node, 1);

/*    Print nodes of given level. */

    printGivenLevel(root, node, level); 
}

/*Driver code */

public static void Main(String[] args) 
{ 
    Node root = newNode(1); 
    root.left = newNode(2); 
    root.right = newNode(3); 
