    root.right.left = newNode(6); 
    root.right.right = newNode(7); 
    root.right.left.right = newNode(8); 
    printCousins(root, root.left.right); 
} 
}

/*C# program to print all root to leaf paths */

using System;

/* A binary tree node has data, pointer to left child 
   and a pointer to right child */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
     public Node root;

/* Given a binary tree, print out all of its root-to-leaf 
       paths, one per line. Uses a recursive helper to do the work.*/

    public virtual void printPaths(Node node)
    {
        int[] path = new int[1000];
        printPathsRecur(node, path, 0);
    }

/* Recursive helper function -- given a node, and an array containing 
       the path from the root node up to but not including this node, 
       print out all the root-leaf paths. */

    public virtual void printPathsRecur(Node node, int[] path, int pathLen)
    {
        if (node == null)
        {
            return;
        }

/* append this node to the path array */

        path[pathLen] = node.data;
        pathLen++;

/* it's a leaf, so print the path that led to here */

        if (node.left == null && node.right == null)
        {
            printArray(path, pathLen);
        }
        else
        {

/* otherwise try both subtrees */

            printPathsRecur(node.left, path, pathLen);
            printPathsRecur(node.right, path, pathLen);
        }
    }

/* Utility that prints out an array on a line */

    public virtual void printArray(int[] ints, int len)
    {
        int i;
        for (i = 0; i < len; i++)
        {
            Console.Write(ints[i] + " ");
        }
        Console.WriteLine("");
    }

/* Driver program to test all above functions */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);

/* Print all root-to-leaf paths of the input tree */

        tree.printPaths(tree.root);
    }
}

/*C# program to print the longest leaf to leaf
path*/

using System;

/*Tree node structure used in the program*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int val)
    {
        data = val;
        left = right = null;
    }
}
public class GFG
{
    static int ans, lh, rh, f;
    static Node k;
    public static Node Root;

/*    Function to find height of a tree*/

    static int height(Node root)
    {
        if (root == null)
            return 0;
        int left_height = height(root.left);
        int right_height = height(root.right);

/*        update the answer, because diameter of a
        tree is nothing but maximum value of
        (left_height + right_height + 1) for each node*/

        if (ans < 1 + left_height + right_height)
        {
            ans = 1 + left_height + right_height;

/*            save the root, this will help us finding the
              left and the right part of the diameter*/

            k = root;

/*            save the height of left & right subtree as well.*/

            lh = left_height;
            rh = right_height;
        }
        return 1 + Math.Max(left_height, right_height);
    }

/*    prints the root to leaf path*/

    static void printArray(int[] ints, int len)
    {
        int i;

/*        print left part of the path in reverse order*/

        if(f == 0)
        {
            for(i = len - 1; i >= 0; i--)
            {
                Console.Write(ints[i] + " ");
            }
        }
        else if(f == 1)
        {
            for (i = 0; i < len; i++)
            {
                Console.Write(ints[i] + " ");  
            }
        }
    }

/*    this function finds out all the root to leaf paths*/

    static void printPathsRecur(Node node, int[] path,int pathLen, int max)
    {
        if (node == null)
            return;

/*        append this node to the path array*/

        path[pathLen] = node.data;
        pathLen++;

/*        If it's a leaf, so print the path that led to here*/

        if (node.left == null && node.right == null)
        {

/*            print only one path which is equal to the
            height of the tree.*/

            if (pathLen == max && (f == 0 || f == 1))
            {
                printArray(path, pathLen);
                f = 2;
            }
        }
        else
        {

/*            otherwise try both subtrees*/

        printPathsRecur(node.left, path, pathLen, max);
        printPathsRecur(node.right, path, pathLen, max);
        }
    }

/*    Computes the diameter of a binary tree with given root.*/

    static void diameter(Node root)
    {
        if (root == null)
            return;

/*        lh will store height of left subtree
        rh will store height of right subtree*/

        ans = Int32.MinValue;
        lh = 0;
        rh = 0;

/*        f is a flag whose value helps in printing
        left & right part of the diameter only once*/

        f = 0;
        int height_of_tree= height(root);
        int[] lPath = new int[100];
        int pathlen = 0 * height_of_tree;

/*        print the left part of the diameter*/

        printPathsRecur(k.left, lPath, pathlen, lh);
        Console.Write(k.data+" ");
        int[] rPath = new int[100];
        f = 1;

/*        print the right part of the diameter*/

        printPathsRecur(k.right, rPath, pathlen, rh);
    }

/*    Driver code*/

    static public void Main (){

/*        Enter the binary tree ...
                   1
                 /   \    
                2     3
              /   \  
             4     5
              \   / \
               8 6   7
              /
             9*/

        GFG.Root = new Node(1);
        GFG.Root.left = new Node(2);
        GFG.Root.right = new Node(3);
        GFG.Root.left.left = new Node(4);
        GFG.Root.left.right = new Node(5);
        GFG.Root.left.right.left = new Node(6);
        GFG.Root.left.right.right = new Node(7);
        GFG.Root.left.left.right = new Node(8);
        GFG.Root.left.left.right.left = new Node(9);
        diameter(Root);
    }
}

/*C# program to Print root to leaf path WITHOUT 
using recursion */

using System;
using System.Collections.Generic;
public class PrintPath 
{

/* A binary tree node */

public class Node 
{ 
    public int data; 
    public Node left, right; 
    public Node(int data)
    {
        left = right = null;
        this.data = data;
    }
};

/* Function to print root to leaf path for a leaf 
    using parent nodes stored in map */

    public static void printTopToBottomPath(Node curr, 
                        Dictionary<Node,Node> parent) 
    { 
        Stack<Node> stk = new Stack<Node>() ;

/*        start from leaf node and keep on pushing 
        nodes into stack till root node is reached */

        while (curr != null) 
        { 
            stk.Push(curr); 
            curr = parent[curr]; 
        }

/*        Start popping nodes from stack and print them */

        while (stk.Count != 0) 
        { 
            curr = stk.Pop(); 
            Console.Write(curr.data + " ");
        } 
        Console.WriteLine();
    }

/* An iterative function to do preorder traversal 
    of binary tree and print root to leaf path 
    without using recursion */

    public static void printRootToLeaf(Node root) 
    {

/*        Corner Case */

        if (root == null) 
            return;

/*        Create an empty stack and push root to it */

        Stack<Node> nodeStack = new Stack<Node>();
        nodeStack.Push(root);

/*        Create a map to store parent  
        pointers of binary tree nodes */

        Dictionary<Node,Node> parent = new Dictionary<Node,Node>();

/*        parent of root is NULL */

        parent.Add(root, null);

/* Pop all items one by one. Do following for 
        every popped item 
            a) push its right child and set its parent 
            pointer 
            b) push its left child and set its parent 
            pointer 
        Note that right child is pushed first so that 
        left is processed first */

        while (nodeStack.Count != 0) 
        {

/*            Pop the top item from stack */

            Node current = nodeStack.Pop();

/*            If leaf node encountered, print Top To 
            Bottom path */

            if (current.left == null && current.right == null) 
                printTopToBottomPath(current, parent);

/*            Push right & left children of the popped node 
            to stack. Also set their parent pointer in 
            the map */

            if (current.right != null) 
            { 
                parent.Add(current.right,current);
                nodeStack.Push(current.right); 
            } 
            if (current.left != null) 
            { 
                parent.Add(current.left,current);
                nodeStack.Push(current.left); 
            } 
        } 
    }

/*    Driver code*/

    public static void Main(String []args) 
    {

/* Constructed binary tree is
         10
        /  \
       8    2
      / \   /
     3     5 2     */

        Node root = new Node(10);
        root.left = new Node(8); 
        root.right = new Node(2); 
        root.left.left = new Node(3); 
        root.left.right = new Node(5); 
        root.right.left = new Node(2); 
        printRootToLeaf(root); 
    }
}

/*C# program to print all root to leaf
paths with there relative position*/

using System;
using System.Collections.Generic;
public
  class Graph
  {
    static readonly int MAX_PATH_SIZE = 1000;

/*    tree structure*/

    public
      class Node
      {
        public
          char data;
        public
          Node left, right;
      };

/*    Function create new node*/

    static Node newNode(char data)
    {
      Node temp = new Node();
      temp.data = data;
      temp.left = temp.right = null;
      return temp;
    }

/*    Store path information*/

    public
      class PATH
      {
        public int Hd;
        public char key;
        public PATH(int Hd, char key)
        {
          this.Hd = Hd;
          this.key = key;
        }
        public PATH()
        {}
      };

/*    Prints given root to leaf path with underscores*/

    static void printPath(List<PATH> path, int size)
    {

/*      Find the minimum horizontal distance value
      in current root to leaf path*/

      int minimum_Hd = int.MaxValue;
      PATH p;

/*      Find minimum horizontal distance*/

      for(int it = 0; it < size; it++)
      {
        p = path[it];
        minimum_Hd = Math.Min(minimum_Hd, p.Hd);
      }

/*      Print the root to leaf path with "_"
      that indicate the related position*/

      for(int it = 0; it < size; it++)
      {

/*        Current tree node*/

        p = path[it];
        int noOfUnderScores = Math.Abs(
          p.Hd - minimum_Hd);

/*        Print underscore*/

        for(int i = 0; i < noOfUnderScores; i++)
          Console.Write("_");

/*        Print current key*/

        Console.WriteLine(p.key);
      }
      Console.WriteLine("==============================");
    }

/*    A utility function print all path from root to leaf
    working of this function is similar to function of
    "Print_vertical_order" : Print paths of binary tree
    in vertical order
www.geeksforgeeks.org/print-binary-tree-vertical-order-set-2/
https:*/

    static void printAllPathsUtil(Node root,
                                  List<PATH> AllPath,
                                  int HD, int order)
    {

/*      Base case*/

      if (root == null)
        return;

/*      Leaf node*/

      if (root.left == null && root.right == null)
      {

/*        Add leaf node and then print path*/

        AllPath[order] = new  PATH(HD, root.data);
        printPath(AllPath, order + 1);
        return;
      }

/*      Store current path information*/

      AllPath[order]= new PATH(HD, root.data);

/*  Call left sub_tree*/

      printAllPathsUtil(root.left, AllPath,
                        HD - 1, order + 1);

/*      Call left sub_tree*/

      printAllPathsUtil(root.right, AllPath,
                        HD + 1, order + 1);
    }
    static void printAllPaths(Node root)
    {

/*      Base case*/

      if (root == null)
        return;
      List<PATH> Allpaths = new List<PATH>();
      for(int i = 0; i < MAX_PATH_SIZE; i++)
      {
        Allpaths.Add(new PATH());
      }
      printAllPathsUtil(root, Allpaths, 0, 0);
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
      Node root = newNode('A');
      root.left = newNode('B');
      root.right = newNode('C');
      root.left.left = newNode('D');
      root.left.right = newNode('E');
      root.right.left = newNode('F');
      root.right.right = newNode('G');
      printAllPaths(root);
    }
  }

