        tree.root.left.right = new Node(12);
        tree.root.left.left = new Node(5);
        tree.root.right.left = new Node(23);
        tree.root.right.right = new Node(52);
        tree.root.left.right.right = new Node(12);
        tree.root.right.right.left = new Node(50);
        Console.WriteLine("The sum of leaves is " + tree.leftLeavesSum(tree.root));
    }
}

/*C# program to find sum of all left leaves*/

using System;
using System.Collections.Generic;
class GFG
{

/*  A binary tree node*/

  public
    class Node
    {
      public
        int key;
      public
        Node left, right;

/*      A constructor to create a new Node*/

      public
        Node(int key_)
      {
        this.key = key_;
        this.left = null;
        this.right = null;
      }
    };

/*  Return the sum of left leaf nodes*/

  static int sumOfLeftLeaves(Node root)
  {
    if(root == null)
      return 0;

/*    Using a stack_ for Depth-First
    Traversal of the tree*/

    Stack<Node> stack_ = new Stack<Node>();
    stack_.Push(root);

/*    sum holds the sum of all the left leaves*/

    int sum = 0;
    while(stack_.Count > 0)
    {
      Node currentNode = stack_.Peek();
      stack_.Pop();
      if (currentNode.left != null)
      {
        stack_.Push(currentNode.left);

/*        Check if currentNode's left
        child is a leaf node*/

        if(currentNode.left.left == null &&
           currentNode.left.right == null)
        {

/*          if currentNode is a leaf,
          add its data to the sum*/

          sum = sum + currentNode.left.key ;
        }
      }
      if (currentNode.right != null)
        stack_.Push(currentNode.right);
    }      
    return sum;
  }

/*  Driver Code*/

  public static void Main(String[] args)
  {
    Node root = new Node(20);
    root.left= new Node(9);
    root.right = new Node(49);
    root.right.left = new Node(23);
    root.right.right= new Node(52);
    root.right.right.left = new Node(50);
    root.left.left = new Node(5);
    root.left.right = new Node(12);
    root.left.right.right = new Node(12);
    Console.Write("Sum of left leaves is "
                  + sumOfLeftLeaves(root) +"\n");
  }
}

/*C# program to find sum of all left leaves*/

using System;
using System.Collections.Generic;
public class GFG
{

/*  A binary tree node*/

  public
    class Node
    {
      public int key;
      public
        Node left,
      right;

/*      constructor to create a new Node*/

      public
        Node(int key_)
      {
        key = key_;
        left = null;
        right = null;
      }
    };
  public
    class pair {
      public
        Node first;
      public
        bool second;
      public pair(Node first, bool second)
      {
        this.first = first;
        this.second = second;
      }
    }

/*  Return the sum of left leaf nodes*/

  static int sumOfLeftLeaves(Node root)
  {
    if (root == null)
      return 0;

/*    A queue of pairs to do bfs traversal
    and keep track if the node is a left
    or right child if bool value
    is true then it is a left child.*/

    Queue<pair> q = new Queue<pair>();
    q.Enqueue(new pair(root, false));
    int sum = 0;

/*    do bfs traversal*/

    while (q.Count != 0)
    {
      Node temp = q.Peek().first;
      bool is_left_child = q.Peek().second;
      q.Dequeue();

/*      if temp is a leaf node and
      left child of its parent*/

      if (is_left_child)
        sum = sum + temp.key;
      if (temp.left != null && temp.right != null
          && is_left_child)
        sum = sum - temp.key;

/*      if it is not leaf then
      push its children nodes
      into queue*/

      if (temp.left != null)
      {

/*        bool value is true
        here because it is left
        child of its parent*/

        q.Enqueue(new pair(temp.left, true));
      }
      if (temp.right != null)
      {

/*        bool value is false
        here because it is
        right child of its parent*/

        q.Enqueue(new pair(temp.right, false));
      }
    }
    return sum;
  }

/*  Driver Code*/

  public static void Main(String[] args)
  {
    Node root = new Node(20);
    root.left = new Node(9);
    root.right = new Node(49);
    root.right.left = new Node(23);
    root.right.right = new Node(52);
    root.right.right.left = new Node(50);
    root.left.left = new Node(5);
    root.left.right = new Node(12);
    root.left.right.right = new Node(12);
    Console.Write("Sum of left leaves is "
                  + sumOfLeftLeaves(root) + "\n");
  }
}

/*C# program to implement 
the above approach*/
using System;
using System.Collections.Generic;
public class GFG
{

/*function to find sum of 
all of the nodes of given
perfect binary tree */

public static int sumNodes(int l)
{

/*    no of leaf nodes */

    int leafNodeCount = (int)Math.Pow(2, l - 1);

/*    list of vector to store 
    nodes of all of the levels */

    List<List<int>> vec = new List<List<int>>();

/*    initialize*/

    for (int i = 1; i <= l; i++)
    {
    vec.Add(new List<int>());
    }

/*    store the nodes of last level 
    i.e., the leaf nodes */

    for (int i = 1; i <= leafNodeCount; i++)
    {
        vec[l - 1].Add(i);
    }

/*    store nodes of rest of 
    the level by moving in 
    bottom-up manner */

    for (int i = l - 2; i >= 0; i--)
    {
        int k = 0;

/*        loop to calculate values 
        of parent nodes from the
        children nodes of lower level */

        while (k < vec[i + 1].Count - 1)
        {

/*            store the value of parent
            node as sum of children nodes */

            vec[i].Add(vec[i + 1][k] + vec[i + 1][k + 1]);
            k += 2;
        }
    }
    int sum = 0;

/*    traverse the list of vector 
    and calculate the sum */

    for (int i = 0; i < l; i++)
    {
        for (int j = 0; j < vec[i].Count; j++)
        {
            sum += vec[i][j];
        }
    }
    return sum;
}

/*Driver Code */

public static void Main(string[] args)
{
    int l = 3;
    Console.WriteLine(sumNodes(l));
}
}

/*C# code to find sum of all nodes
of the given perfect binary tree*/

using System;
using System.Collections.Generic;
class GFG {

/*    function to find sum of
    all of the nodes of given
    perfect binary tree*/

    static double sumNodes(int l)
    {

/*        no of leaf nodes*/

        double leafNodeCount = Math.Pow(2, l - 1);
        double sumLastLevel = 0;

/*        sum of nodes at last level*/

        sumLastLevel = (leafNodeCount *
               (leafNodeCount + 1)) / 2;

/*        sum of all nodes*/

        double sum = sumLastLevel * l;
        return sum;
    }

/*    Driver Code*/

    public static void Main()
    {
        int l = 3;
        Console.Write(sumNodes(l));
    }
}

/*C# Program to calculate the
sum of diagonal nodes.*/

using System;
using System.Collections.Generic;
public class GFG
{

/*Node Structure*/

public
 class Node
{
    public
 int data;
    public
 Node left, right;
};

/*to map the node with level - index*/

static Dictionary<int, int> grid = new Dictionary<int, int>();

/*Function to create new node*/

static Node newNode(int data)
{
    Node Node = new Node();
    Node.data = data;
    Node.left = Node.right = null;
    return Node;
}

/*recursvise function to calculate sum of elements
where level - index is same.*/

static void addConsideringGrid(Node root, int level, int index)
{

/*    if there is no child then return*/

    if (root == null)
        return;

/*    add the element in the group of node
    whose level - index is equal*/

    if(grid.ContainsKey(level - index))
    grid[level - index] = grid[level - index] + (root.data);
    else
        grid.Add(level-index, root.data);

/*    left child call*/

    addConsideringGrid(root.left, level + 1, index - 1);

/*    right child call*/

    addConsideringGrid(root.right, level + 1, index + 1);
}
static List<int> diagonalSum(Node root)
{
    grid.Clear();

/*    Function call*/

    addConsideringGrid(root, 0, 0);
    List<int> ans = new List<int>();

/*    for different values of level - index
    add te sum of those node to answer*/

    foreach (KeyValuePair<int,int> x in grid)
    {
        ans.Add(x.Value);
    }
    return ans;
}

/*Driver code*/

public static void Main(String[] args)
{

/*    build binary tree*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(9);
    root.left.right = newNode(6);
    root.right.left = newNode(4);
    root.right.right = newNode(5);
    root.right.left.right = newNode(7);
    root.right.left.left = newNode(12);
    root.left.right.left = newNode(11);
    root.left.left.right = newNode(10);

/*    Function Call*/

    List<int> v = diagonalSum(root);

/*    print the daigonal sums*/

    for (int i = 0; i < v.Count; i++)
        Console.Write(v[i] + " ");
  }
}

/*C# program to find if there is a pair in any root
to leaf path with sum equals to root's key.*/

using System;
using System.Collections.Generic;
class GFG
{

/* A binary tree node has data,
pointer to left child and
a pointer to right child */

public class Node
{
    public int data;
    public Node left, right;
};

/* utility that allocates a new node with the
given data and null left and right pointers. */

static Node newnode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
}

/*Function to print root to leaf path
which satisfies the condition*/

static bool printPathUtil(Node node,
                          HashSet<int> s,
                          int root_data)
{

/*    Base condition*/

    if (node == null)
        return false;

/*    Check if current node makes a pair
    with any of the existing elements in set.*/

    int rem = root_data - node.data;
    if (s.Contains(rem))
        return true;

/*    Insert current node in set*/

    s.Add(node.data);

/*    If result returned by either left or
    right child is true, return true.*/

    bool res = printPathUtil(node.left, s, root_data) ||
               printPathUtil(node.right, s, root_data);

/*    Remove current node from hash table*/

    s.Remove(node.data);
    return res;
}

/*A wrapper over printPathUtil()*/

static bool isPathSum(Node root)
{

/*    create an empty hash table*/

    HashSet<int> s = new HashSet<int>();

/*    Recursively check in left and right subtrees.*/

    return printPathUtil(root.left, s, root.data) ||
           printPathUtil(root.right, s, root.data);
}

/*Driver code*/

public static void Main(String[] args)
{
    Node root = newnode(8);
    root.left = newnode(5);
    root.right = newnode(4);
    root.left.left = newnode(9);
    root.left.right = newnode(7);
    root.left.right.left = newnode(1);
    root.left.right.right = newnode(12);
    root.left.right.right.right = newnode(2);
    root.right.right = newnode(11);
    root.right.right.left = newnode(3);
    Console.Write(isPathSum(root) == true ?
                                    "Yes" : "No");
}
}

/*c# implementation to find the sum of nodes 
on the longest path from root to leaf node */
using System;
public class GFG
{

/*    Node of a binary tree */

    public class Node
    {
        public int data;
        public Node left, right;
        public Node(int data)
        {
            this.data = data;
            left = null;
            right = null;
        }
    }
    public static int maxLen;
    public static int maxSum;

/*    function to find the sum of nodes on the 
    longest path from root to leaf node */

    public static void sumOfLongRootToLeafPath(Node root, int sum, int len)
    {

/*        if true, then we have traversed a 
        root to leaf path */

        if (root == null)
        {

/*            update maximum length and maximum sum 
            according to the given conditions */

            if (maxLen < len)
            {
                maxLen = len;
                maxSum = sum;
            }
            else if (maxLen == len && maxSum < sum)
            {
                maxSum = sum;
            }
            return;
        }

/*        recur for left subtree */

        sumOfLongRootToLeafPath(root.left, sum + root.data, len + 1);

/*    recur for right subtree*/

        sumOfLongRootToLeafPath(root.right, sum + root.data, len + 1);
    }

/*    utility function to find the sum of nodes on 
    the longest path from root to leaf node */

    public static int sumOfLongRootToLeafPathUtil(Node root)
    {

/*        if tree is NULL, then sum is 0 */

        if (root == null)
        {
            return 0;
        }
        maxSum = int.MinValue;
        maxLen = 0;

/*        finding the maximum sum 'maxSum' for the 
        maximum length root to leaf path */

        sumOfLongRootToLeafPath(root, 0, 0);

/*        required maximum sum */

        return maxSum;
    }

/*    Driver program to test above */

    public static void Main(string[] args)
    {

/*        binary tree formation 
        4*/

Node root = new Node(4);

/*       / \*/

root.left = new Node(2);

/*      2   5*/

root.right = new Node(5);

/*     / \ / \*/

root.left.left = new Node(7);

/*    7  1 2  3*/

root.left.right = new Node(1);

/*      /*/

root.right.left = new Node(2);

/*     6*/

root.right.right = new Node(3); 
        root.left.right.left = new Node(6);
        Console.WriteLine("Sum = " + sumOfLongRootToLeafPathUtil(root));
    }
}

