/*C# program to find maximum path sum between two leaves
of a binary tree*/

using System;

/*A binary tree node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*An object of Res is passed around so that the
same value can be used by multiple recursive calls.*/

public class Res
{
    public int val;
}
public class BinaryTree
{
    public static Node root;

/*    A utility function to find the maximum sum between any
    two leaves.This function calculates two values:
    1) Maximum path sum between two leaves which is stored
        in res.
    2) The maximum root to leaf path sum which is returned.
    If one side of root is empty, then it returns INT_MIN*/

    public virtual int maxPathSumUtil(Node node, Res res)
    {

/*        Base cases*/

        if (node == null)
        {
            return 0;
        }
        if (node.left == null && node.right == null)
        {
            return node.data;
        }

/*        Find maximum sum in left and right subtree. Also
        find maximum root to leaf sums in left and right
        subtrees and store them in ls and rs*/

        int ls = maxPathSumUtil(node.left, res);
        int rs = maxPathSumUtil(node.right, res);

/*        If both left and right children exist*/

        if (node.left != null && node.right != null)
        {

/*            Update result if needed*/

            res.val = Math.Max(res.val, ls + rs + node.data);

/*            Return maxium possible value for root being
            on one side*/

            return Math.Max(ls, rs) + node.data;
        }

/*        If any of the two children is empty, return
        root sum for root being on one side*/

        return (node.left == null) ? rs + node.data : ls + node.data;
    }

/*    The main function which returns sum of the maximum
    sum path between two leaves. This function mainly
    uses maxPathSumUtil()*/

    public virtual int maxPathSum(Node node)
    {
        Res res = new Res();
        res.val = int.MinValue;
        maxPathSumUtil(root, res);
        return res.val;
    }

/*    Driver program to test above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        BinaryTree.root = new Node(-15);
        BinaryTree.root.left = new Node(5);
        BinaryTree.root.right = new Node(6);
        BinaryTree.root.left.left = new Node(-8);
        BinaryTree.root.left.right = new Node(1);
        BinaryTree.root.left.left.left = new Node(2);
        BinaryTree.root.left.left.right = new Node(6);
        BinaryTree.root.right.left = new Node(3);
        BinaryTree.root.right.right = new Node(9);
        BinaryTree.root.right.right.right = new Node(0);
        BinaryTree.root.right.right.right.left = new Node(4);
        BinaryTree.root.right.right.right.right = new Node(-1);
        BinaryTree.root.right.right.right.right.left = new Node(10);
        Console.WriteLine("Max pathSum of the given binary tree is " + tree.maxPathSum(root));
    }
}

/*C# program to find maximum sum leaf to root
path in Binary Tree*/
using System;

/*A Binary Tree node*/

public class Node {
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*A wrapper class is used so that max_no
can be updated among function calls.*/

public class Maximum {
    public int max_no = int.MinValue;
}
public class BinaryTree {
    public Node root;
    public Maximum max = new Maximum();
    public Node target_leaf = null;

/*    A utility function that prints all nodes on the
    path from root to target_leaf*/

    public virtual bool printPath(Node node, Node target_leaf)
    {

/*        base case*/

        if (node == null) {
            return false;
        }

/*        return true if this node is the target_leaf or
        target leaf is present in one of its descendants*/

        if (node == target_leaf || printPath(node.left, target_leaf)
            || printPath(node.right, target_leaf)) {
            Console.Write(node.data + " ");
            return true;
        }
        return false;
    }

/*    This function Sets the target_leaf_ref to refer
    the leaf node of the maximum path sum. Also,
    returns the max_sum using max_sum_ref*/

    public virtual void getTargetLeaf(Node node, Maximum max_sum_ref,
                                      int curr_sum)
    {
        if (node == null) {
            return;
        }

/*        Update current sum to hold sum of nodes on
        path from root to this node*/

        curr_sum = curr_sum + node.data;

/*        If this is a leaf node and path to this node
        has maximum sum so far, the n make this node
        target_leaf*/

        if (node.left == null && node.right == null) {
            if (curr_sum > max_sum_ref.max_no) {
                max_sum_ref.max_no = curr_sum;
                target_leaf = node;
            }
        }

/*        If this is not a leaf node, then recur down
        to find the target_leaf*/

        getTargetLeaf(node.left, max_sum_ref, curr_sum);
        getTargetLeaf(node.right, max_sum_ref, curr_sum);
    }

/*    Returns the maximum sum and prints the nodes on
    max sum path*/

    public virtual int maxSumPath()
    {

/*        base case*/

        if (root == null) {
            return 0;
        }

/*        find the target leaf and maximum sum*/

        getTargetLeaf(root, max, 0);

/*        print the path from root to the target leaf*/

        printPath(root, target_leaf);

/*return maximum sum*/

return max.max_no; 
    }

/*    driver function to test the above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(-2);
        tree.root.right = new Node(7);
        tree.root.left.left = new Node(8);
        tree.root.left.right = new Node(-4);
        Console.WriteLine("Following are the nodes "
                          + "on maximum sum path");
        int sum = tree.maxSumPath();
        Console.WriteLine("");
        Console.WriteLine("Sum of nodes is : " + sum);
    }
}

/*C# program to find maximum sum from a subset of
nodes of binary tree*/

using System;
using System.Collections.Generic;
public class FindSumOfNotAdjacentNodes
{

/* A binary tree node structure */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data=data;
        left=right=null;
    }
};

/*    method returns maximum sum
    possible from subtrees rooted
    at grandChildrens of node 'node'*/

    public static int sumOfGrandChildren(Node node,
                            Dictionary<Node,int> mp)
    {
        int sum = 0;

/*        call for children of left
        child only if it is not NULL*/

        if (node.left != null)
            sum += getMaxSumUtil(node.left.left, mp) +
                getMaxSumUtil(node.left.right, mp);

/*        call for children of right
        child only if it is not NULL*/

        if (node.right != null)
            sum += getMaxSumUtil(node.right.left, mp) +
                getMaxSumUtil(node.right.right, mp);
        return sum;
    }

/*    Utility method to return maximum
    sum rooted at node 'node'*/

    public static int getMaxSumUtil(Node node,
                        Dictionary<Node,int> mp)
    {
        if (node == null)
            return 0;

/*        If node is already processed then
        return calculated value from map*/

        if(mp.ContainsKey(node))
            return mp[node];

/*        take current node value and
        call for all grand children*/

        int incl = node.data + sumOfGrandChildren(node, mp);

/*        don't take current node value and
        call for all children*/

        int excl = getMaxSumUtil(node.left, mp) +
                getMaxSumUtil(node.right, mp);

/*        choose maximum from both above
        calls and store that in map*/

        mp.Add(node,Math.Max(incl, excl));
        return mp[node];
    }

/*    Returns maximum sum from subset of nodes
    of binary tree under given constraints*/

    public static int getMaxSum(Node node)
    {
        if (node == null)
            return 0;
        Dictionary<Node,int> mp=new Dictionary<Node,int>();
        return getMaxSumUtil(node, mp);
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.right.left = new Node(4);
        root.right.right = new Node(5);
        root.left.left = new Node(1);    
        Console.Write(getMaxSum(root));
    }
}

/*C# program to find maximum sum in Binary Tree
such that no two nodes are adjacent.*/

using System;
public class FindSumOfNotAdjacentNodes
{

/* A binary tree node structure */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
};

/*maxSumHelper function */

    public static Pair maxSumHelper(Node root)
    {
        Pair sum;
        if (root == null)
        {
            sum=new Pair(0, 0);
            return sum;
        }
        Pair sum1 = maxSumHelper(root.left);
        Pair sum2 = maxSumHelper(root.right);
        Pair sum3 = new Pair(0,0);

/*        This node is included (Left and
        right children are not included)*/

        sum3.first = sum1.second + sum2.second + root.data;

/*        This node is excluded (Either left
        or right child is included)*/

        sum3.second = Math.Max(sum1.first, sum1.second) +
                    Math.Max(sum2.first, sum2.second);
        return sum3;
    }

/*    Returns maximum sum from subset of nodes
    of binary tree under given constraints*/

    public static int maxSum(Node root)
    {
        Pair res=maxSumHelper(root);
        return Math.Max(res.first, res.second);
    }

/*    Driver code*/

    public static void Main()
    {
        Node root = new Node(10);
        root.left = new Node(1);
        root.left.left = new Node(2);
        root.left.left.left = new Node(1);
        root.left.right = new Node(3);
        root.left.right.left = new Node(4);
        root.left.right.right = new Node(5);
        Console.Write(maxSum(root));
    }
}

/* Pair class */

public class Pair
{
    public int first,second;
    public Pair(int first,int second)
    {
        this.first = first;
        this.second = second;
    }
}

/*C# code for max sum with adjacent levels
not allowed*/

using System;
class GFG
{

/*    Tree node class for Binary Tree
    representation*/

    public class Node
    {
        public int data;
        public Node left, right;
        public Node(int item)
        {
            data = item;
            left = right = null;
        }
    }

/*    Recursive function to find the maximum
    sum returned for a root node and its
    grandchildren*/

    public static int getSumAlternate(Node root)
    {
        if (root == null)
            return 0;
        int sum = root.data;
        if (root.left != null)
        {
            sum += getSum(root.left.left);
            sum += getSum(root.left.right);
        }
        if (root.right != null)
        {
            sum += getSum(root.right.left);
            sum += getSum(root.right.right);
        }
        return sum;
    }

/*    Returns maximum sum with adjacent
    levels not allowed. This function
    mainly uses getSumAlternate()*/

    public static int getSum(Node root)
    {
        if (root == null)
            return 0;

/*        We compute sum of alternate levels
        starting first level and from second
        level.
        And return maximum of two values.*/

        return Math.Max(getSumAlternate(root),
                        (getSumAlternate(root.left) +
                        getSumAlternate(root.right)));
    }

/*    Driver code*/

    public static void Main()
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.right.left = new Node(4);
        root.right.left.right = new Node(5);
        root.right.left.right.left = new Node(6);
        Console.WriteLine(getSum(root));
    }
}

/*C# program to print all paths with sum k. */

using System;
using System.Collections.Generic;
class GFG
{

/*utility function to print contents of 
a vector from index i to it's end */

static void printList(List<int> v, int i) 
{ 
    for (int j = i; j < v.Count; j++) 
        Console.Write(v[j] + " "); 
        Console.WriteLine(); 
}

/*binary tree node */

public class Node 
{ 
    public int data; 
    public Node left,right; 
    public Node(int x) 
    { 
        data = x; 
        left = right = null; 
    } 
}; 
static List<int> path = new List<int>();

/*This function prints all paths that have sum k */

static void printKPathUtil(Node root, int k) 
{

/*    empty node */

    if (root == null) 
        return;

/*    add current node to the path */

    path.Add(root.data);

/*    check if there's any k sum path 
    in the left sub-tree. */

    printKPathUtil(root.left, k);

/*    check if there's any k sum path 
    in the right sub-tree. */

    printKPathUtil(root.right, k);

/*    check if there's any k sum path that 
    terminates at this node 
    Traverse the entire path as 
    there can be negative elements too */

    int f = 0; 
    for (int j = path.Count - 1; j >= 0; j--) 
    { 
        f += path[j];

/*        If path sum is k, print the path */

        if (f == k) 
            printList(path, j); 
    }

/*    Remove the current element from the path */

    path.RemoveAt(path.Count - 1); 
}

/*A wrapper over printKPathUtil() */

static void printKPath(Node root, int k) 
{ 
    path = new List<int>();
    printKPathUtil(root, k); 
}

/*Driver code */

public static void Main(String []args)
{ 
    Node root = new Node(1); 
    root.left = new Node(3); 
    root.left.left = new Node(2); 
    root.left.right = new Node(1); 
    root.left.right.left = new Node(1); 
    root.right = new Node(-1); 
    root.right.left = new Node(4); 
    root.right.left.left = new Node(1); 
    root.right.left.right = new Node(2); 
    root.right.right = new Node(5); 
    root.right.right.right = new Node(2); 
    int k = 5; 
    printKPath(root, k); 
}
}

/*C# program to find sum of heights of all
nodes in a binary tree*/

using System;
class GfG
{

/* A binary tree Node has data, pointer to
    left child and a pointer to right child */

public class Node
{
    public int data;
    public Node left;
    public Node right;
}

/* Compute the "maxHeight" of a particular Node*/

static int getHeight(Node Node)
{
    if (Node == null)
        return 0;
    else
    {

/* compute the height of each subtree */

        int lHeight = getHeight(Node.left);
        int rHeight = getHeight(Node.right);

/* use the larger one */

        if (lHeight > rHeight)
            return (lHeight + 1);
        else
            return (rHeight + 1);
    }
}

/* Helper function that allocates a new Node with the
given data and NULL left and right pointers. */

static Node newNode(int data)
{
    Node Node = new Node();
    Node.data = data;
    Node.left = null;
    Node.right = null;
    return (Node);
}

/* Function to sum of heights of individual Nodes
Uses Inorder traversal */

static int getTotalHeight( Node root)
{
    if (root == null)
        return 0;
    return getTotalHeight(root.left) +
                    getHeight(root) +
                    getTotalHeight(root.right);
}

/*Driver code*/

public static void Main(String []args)
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    Console.Write("Sum of heights of all Nodes = " + getTotalHeight(root));
}
}

/*C# program to find sum of heights of
all nodes in a binary tree*/

using System;
using System.Collections.Generic;
class GFG
{

/* A binary tree Node has data, pointer to
    left child and a pointer to right child */

    class Node
    {
        public int data;
        public Node left;
        public Node right;
    };
    static int sum;

/* Helper function that allocates
    a new Node with the given data and
    null left and right pointers. */

    static Node newNode(int data)
    {
        Node Node = new Node();
        Node.data = data;
        Node.left = null;
        Node.right = null;
        return (Node);
    }

/* Function to sum of heights of
    individual Nodes Uses Inorder traversal */

    static int getTotalHeightUtil(Node root)
    {
        if (root == null)
        {
            return 0;
        }
        int lh = getTotalHeightUtil(root.left);
        int rh = getTotalHeightUtil(root.right);
        int h = Math.Max(lh, rh) + 1;
        sum = sum + h;
        return h;
    }
    static int getTotalHeight(Node root)
    {
        sum = 0;
        getTotalHeightUtil(root);
        return sum;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node root = newNode(1);
        root.left = newNode(2);
        root.right = newNode(3);
        root.left.left = newNode(4);
        root.left.right = newNode(5);
        Console.Write("Sum of heights of all Nodes = {0}",
                                    getTotalHeight(root));
    }
}

/*c# program to find if
there is a subtree with
given sum*/
using System;
public class GFG
{

/*structure of a node
of binary tree*/

public class Node
{
    public int data;
    public Node left, right;
}
public class INT
{
    public int v;
    public INT(int a)
    {
        v = a;
    }
}

/*function to get a new node*/

public static Node getNode(int data)
{

/*    allocate space*/

    Node newNode = new Node();

/*    put in the data*/

    newNode.data = data;
    newNode.left = newNode.right = null;
    return newNode;
}

/*function to count subtress that
sum up to a given value x*/

public static int countSubtreesWithSumX(Node root,
                                    INT count, int x)
{

/*    if tree is empty*/

    if (root == null)
    {
        return 0;
    }

/*    sum of nodes in the left subtree*/

    int ls = countSubtreesWithSumX(root.left, count, x);

/*    sum of nodes in the right subtree*/

    int rs = countSubtreesWithSumX(root.right, count, x);

/*    sum of nodes in the subtree
    rooted with 'root.data'*/

    int sum = ls + rs + root.data;

/*    if true*/

    if (sum == x)
    {
        count.v++;
    }

/*    return subtree's nodes sum*/

    return sum;
}

/*utility function to
count subtress that
sum up to a given value x*/

public static int countSubtreesWithSumXUtil(Node root, int x)
{

/*    if tree is empty*/

    if (root == null)
    {
        return 0;
    }
    INT count = new INT(0);

/*    sum of nodes in the left subtree*/

    int ls = countSubtreesWithSumX(root.left, count, x);

/*    sum of nodes in the right subtree*/

    int rs = countSubtreesWithSumX(root.right, count, x);

/*    if tree's nodes sum == x*/

    if ((ls + rs + root.data) == x)
    {
        count.v++;
    }

/*    required count of subtrees*/

    return count.v;
}

/*Driver Code*/

public static void Main(string[] args)
{

/* binary tree creation    
                5
            / \
        -10     3
        / \ / \
        9 8 -4 7
    */

    Node root = getNode(5);
    root.left = getNode(-10);
    root.right = getNode(3);
    root.left.left = getNode(9);
    root.left.right = getNode(8);
    root.right.left = getNode(-4);
    root.right.right = getNode(7);
    int x = 7;
    Console.WriteLine("Count = " + countSubtreesWithSumXUtil(root, x));
}
}

/*C# program to find if
there is a subtree with
given sum*/

using System;

/*Node class to
create new node*/

public class Node
{
  public int data;
  public Node left;
  public Node right;
  public Node(int data)
  {
    this.data = data;
  }
}
class GFG{
static int count = 0;
static Node ptr;

/*Utility function to count subtress
that sum up to a given value x*/

int countSubtreesWithSumXUtil(Node root,
                              int x)
{
  int l = 0, r = 0;
  if(root == null) return 0;
  l += countSubtreesWithSumXUtil(root.left, x);
  r += countSubtreesWithSumXUtil(root.right, x);
  if(l + r + root.data == x) count++;
  if(ptr != root) return l + root.data + r;
  return count;
}

/*Driver Code*/

public static void Main(string[] args)
{

/* binary tree creation
            5
        / \
        -10 3
        / \ / \
