  root.left = new Node(-10);
  root.right = new Node(3);
  root.left.left = new Node(9);
  root.left.right = new Node(8);
  root.right.left = new Node(-4);
  root.right.right = new Node(7);
  int x = 7;
  ptr = root;
  Console.Write("Count = " +
          new GFG().countSubtreesWithSumXUtil(root, x));
}
}

/*C# code to find the sum of the nodes
which are present at the maximum depth.*/

using System;
class GFG
{
static int sum = 0, max_level = int.MinValue;
public class Node
{
    public int d;
    public Node l;
    public Node r;
};

/*Function to return a new node*/

static Node createNode(int d)
{
    Node node;
    node = new Node();
    node.d = d;
    node.l = null;
    node.r = null;
    return node;
}

/*Function to find the sum of the node
which are present at the maximum depth.
While traversing the nodes compare the level
of the node with max_level
(Maximum level till the current node).
If the current level exceeds the maximum level,
update the max_level as current level.
If the max level and current level are same,
add the root data to current sum.*/

static void sumOfNodesAtMaxDepth(Node ro,int level)
{
    if(ro == null)
    return;
    if(level > max_level)
    {
        sum = ro . d;
        max_level = level;
    }
    else if(level == max_level)
    {
        sum = sum + ro . d;
    }
    sumOfNodesAtMaxDepth(ro . l, level + 1);
    sumOfNodesAtMaxDepth(ro . r, level + 1);
}

/*Driver Code*/

public static void Main(String[] args)
{
    Node root;
    root = createNode(1);
    root.l = createNode(2);
    root.r = createNode(3);
    root.l.l = createNode(4);
    root.l.r = createNode(5);
    root.r.l = createNode(6);
    root.r.r = createNode(7);
    sumOfNodesAtMaxDepth(root, 0);
    Console.WriteLine(sum);
}
}

/*C# code for sum of nodes
at maximum depth*/

using System;

/*    Constructor*/
public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        this.left = null;
        this.right = null;
    }
}
public class GfG
{

/*    function to find the sum of nodes at
    maximum depth arguments are node and
    max, where max is to match the depth
    of node at every call to node, if
    max will be equal to 1, means
    we are at deepest node.*/

    public static int sumMaxLevelRec(Node node, int max)
    {

/*        base case*/

        if (node == null)
        {
            return 0;
        }

/*        max == 1 to track the node
        at deepest level*/

        if (max == 1)
        {
            return node.data;
        }

/*        recursive call to left and right nodes*/

        return sumMaxLevelRec(node.left, max - 1)
                + sumMaxLevelRec(node.right, max - 1);
    }

/*    maxDepth function to find the
    max depth of the tree*/

    public static int maxDepth(Node node)
    {

/*        base case*/

        if (node == null)
        {
            return 0;
        }

/*        either leftDepth of rightDepth is
        greater add 1 to include height
        of node at which call is*/

        return 1 + Math.Max(maxDepth(node.left),
                            maxDepth(node.right));
    }

/*        call to function to calculate
        max depth*/
    public static int sumMaxLevel(Node root)
    {
        int MaxDepth = maxDepth(root);
        return sumMaxLevelRec(root, MaxDepth);
    }

/*    Driver code*/

    public static void Main(string[] args)
    {

/*     1
            / \
            2 3
            / \ / \
            4 5 6 7     */

/*        Constructing tree*/

        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.right.left = new Node(6);
        root.right.right = new Node(7);

/*        call to calculate required sum*/

        Console.WriteLine(sumMaxLevel(root));
    }
}

/*C# program to find 
difference between 
sums of odd level 
and even level nodes 
of binary tree*/

using System;
using System.Collections.Generic;

/*User defined node class*/

public class Node
{
    public int data;
    public Node left, right;

/*    Constructor to create a new tree node*/

    public Node(int key) 
    {
        data = key;
        left = right = null;
    }
}
public class GFG 
{

/*    return difference of 
    sums of odd level and even level */

    static int evenOddLevelDifference(Node root)
    {
            if (root == null)
                return 0;

/*            create a queue for 
            level order traversal*/

            Queue<Node> q = new Queue<Node>();
            q.Enqueue(root);
            int level = 0; 
            int evenSum = 0, oddSum = 0;

/*            traverse until the 
            queue is empty*/

            while (q.Count != 0) 
            {
                int size = q.Count;
                level++;

/*                traverse for complete level */

                while (size > 0)
                {
                        Node temp = q.Dequeue();

/*                        check if level no. 
                        is even or odd and 
                        accordingly update 
                        the evenSum or oddSum */

                        if (level % 2 == 0)
                            evenSum += temp.data;
                        else
                            oddSum += temp.data;

/*                        check for left child */

                        if (temp.left != null)
                            q.Enqueue(temp.left);

/*                        check for right child */

                        if (temp.right != null)
                            q.Enqueue(temp.right);
                        size--;
                }
            }
            return (oddSum - evenSum); 
    }

/*    Driver code*/

    public static void Main(String []args)
    {

/*            construct a tree*/

            Node root = new Node(5);
            root.left = new Node(2);
            root.right = new Node(6);
            root.left.left = new Node(1);
            root.left.right = new Node(4);
            root.left.right.left = new Node(3);
            root.right.right = new Node(8);
            root.right.right.right = new Node(9);
            root.right.right.left = new Node(7);
            Console.WriteLine("diffence between sums is " + 
                                evenOddLevelDifference(root));
    }
}

/*A recursive C# program to find 
difference between sum of nodes at 
odd level and sum at even level */using System;

/*A binary tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right;
    }
}
public class BinaryTree
{

/*    The main function that return difference
    between odd and even level nodes */

    public Node root;
    public virtual int getLevelDiff(Node node)
    {

/*        Base case */

        if (node == null)
        {
            return 0;
        }

/*        Difference for root is root's 
        data - difference for left subtree
          - difference for right subtree */

        return node.data - getLevelDiff(node.left)
                        - getLevelDiff(node.right);
    }

/*    Driver program to test above functions */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(5);
        tree.root.left = new Node(2);
        tree.root.right = new Node(6);
        tree.root.left.left = new Node(1);
        tree.root.left.right = new Node(4);
        tree.root.left.right.left = new Node(3);
        tree.root.right.right = new Node(8);
        tree.root.right.right.right = new Node(9);
        tree.root.right.right.left = new Node(7);
        Console.WriteLine(tree.getLevelDiff(tree.root)
                        + " is the required difference");
    }
}

/*C# implementation to find maximum spiral sum*/

using System;
using System.Collections.Generic;
public class MaxSpiralSum 
{

/* A binary tree node has data,
pointer to left child and
a pointer to right child */

public class Node 
{ 
    public int data ; 
    public Node left, right ; 
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
};

/*    function to find the maximum
    sum contiguous subarray. 
    implements kadane's algorithm */

    static int maxSum(List<int> arr) 
    {

/*        to store the maximum value that is ending 
        up to the current index */

        int max_ending_here = int.MinValue;

/*        to store the maximum value encountered so far */

        int max_so_far = int.MinValue;

/*        traverse the array elements */

        for (int i = 0; i < arr.Count; i++) 
        {

/*            if max_ending_here < 0, then it could 
            not possibly contribute to the maximum 
            sum further */

            if (max_ending_here < 0) 
                max_ending_here = arr[i];

/*            else add the value arr[i]
            to max_ending_here */

            else
                max_ending_here +=arr[i];

/*            update max_so_far */

            max_so_far = Math.Max(max_so_far, max_ending_here); 
        }

/*        required maxium sum
        contiguous subarray value */

        return max_so_far; 
    }

/*    Function to find maximum spiral sum */

    public static int maxSpiralSum(Node root) 
    {

/*        if tree is empty */

        if (root == null) 
            return 0;

/*        Create two stacks to store alternate levels 
For levels from right to left */

Stack<Node> s1 = new Stack<Node>();

/*For levels from left to right */

Stack<Node> s2 = new Stack<Node>();

/*        ArrayList to store spiral order traversal 
        of the binary tree */

        List<int> arr=new List<int>();

/*        Push first level to first stack 's1' */

        s1.Push(root);

/*        traversing tree in spiral form until 
        there are elements in any one of the 
        stacks */

        while (s1.Count != 0 || s2.Count != 0) 
        {

/*            traverse current level from s1 and 
            push nodes of next level to s2 */

            while (s1.Count != 0) 
            { 
                Node temp = s1.Pop();

/*                push temp-data to 'arr' */

                arr.Add(temp.data);

/*                Note that right is pushed before left */

                if (temp.right != null) 
                    s2.Push(temp.right); 
                if (temp.left != null) 
                    s2.Push(temp.left); 
            }

/*            traverse current level from s2 and 
            push nodes of next level to s1 */

            while (s2.Count != 0) 
            { 
                Node temp = s2.Pop();

/*                push temp-data to 'arr' */

                arr.Add(temp.data);

/*                Note that left is pushed before right */

                if (temp.left != null) 
                    s1.Push(temp.left); 
                if (temp.right != null) 
                    s1.Push(temp.right); 
            } 
        }

/*        required maximum spiral sum */

        return maxSum(arr); 
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        Node root = new Node(-2); 
        root.left = new Node(-3); 
        root.right = new Node(4); 
        root.left.left = new Node(5); 
        root.left.right = new Node(1); 
        root.right.left = new Node(-2); 
        root.right.right = new Node(-1); 
        root.left.left.left = new Node(-3); 
        root.right.right.right = new Node(2); 
        Console.Write("Maximum Spiral Sum = " + 
                      maxSpiralSum(root));
    }
}

/*C# program to find sum of 
all leaf nodes of binary tree */
using System;
public class GFG
{

/*    user define class node */

    public class Node
    {
        public int data;
        public Node left, right;

/*        constructor */

        public Node(int data)
        {
            this.data = data;
            left = null;
            right = null;
        }
    }
    public static int sum;

/*    utility function which calculates 
    sum of all leaf nodes */

    public static void leafSum(Node root)
    {
        if (root == null)
        {
            return;
        }

/*        add root data to sum if  
        root is a leaf node */

        if (root.left == null && root.right == null)
        {
            sum += root.data;
        }

/*        propagate recursively in left 
        and right subtree */

        leafSum(root.left);
        leafSum(root.right);
    }

/*    driver program */

    public static void Main(string[] args)
    {

/*        construct binary tree */

        Node root = new Node(1);
        root.left = new Node(2);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.right = new Node(3);
        root.right.right = new Node(7);
        root.right.left = new Node(6);
        root.right.left.right = new Node(8);

/*        variable to store sum of leaf nodes */

        sum = 0;
        leafSum(root);
        Console.WriteLine(sum);
    }
}

/*C# implementation to find the sum of
leaf nodes at minimum level*/

using System;
using System.Collections.Generic;
class GFG 
{

/*structure of a node of binary tree*/

class Node 
{
    public int data;
    public Node left, right;
};

/*function to get a new node*/

static Node getNode(int data)
{

/*    allocate space*/

    Node newNode = new Node();

/*    put in the data*/

    newNode.data = data;
    newNode.left = newNode.right = null;
    return newNode;
}

/*function to find the sum of
leaf nodes at minimum level*/

static int sumOfLeafNodesAtMinLevel(Node root)
{

/*    if tree is empty*/

    if (root == null)
        return 0;

/*    if there is only one node*/

    if (root.left == null &&
        root.right == null)
        return root.data;

/*    queue used for level order traversal*/

    Queue<Node> q = new Queue<Node>();
    int sum = 0; 
    bool f = false;

/*    push root node in the queue 'q'*/

    q.Enqueue(root);
    while (f == false)
    {

/*        count number of nodes in the
        current level*/

        int nc = q.Count;

/*        traverse the current level nodes*/

        while (nc-- >0)
        {

/*            get front element from 'q'*/

            Node top = q.Peek();
            q.Dequeue();

/*            if it is a leaf node*/

            if (top.left == null && 
                top.right == null) 
            {

/*                accumulate data to 'sum'*/

                sum += top.data;

/*                set flag 'f' to 1, to signify 
                minimum level for leaf nodes 
                has been encountered*/

                f = true;
            }
            else
            {

/*                if top's left and right child 
                exists, then push them to 'q'*/

                if (top.left != null)
                    q.Enqueue(top.left);
                if (top.right != null)
                    q.Enqueue(top.right);
            }
        }
    }

/*    required sum*/

    return sum;
}

/*Driver Code*/

public static void Main(String[] args)
{

/*    binary tree creation*/

    Node root = getNode(1);
    root.left = getNode(2);
    root.right = getNode(3);
    root.left.left = getNode(4);
    root.left.right = getNode(5);
    root.right.left = getNode(6);
    root.right.right = getNode(7);
    root.left.right.left = getNode(8);
    root.right.left.right = getNode(9);
    Console.WriteLine("Sum = " + 
            sumOfLeafNodesAtMinLevel(root));
    }
}

/*C# program to print to print root to
leaf path sum equal to a given number*/

using System;

/* A binary tree node has data, pointer
to left child and a pointer to right child */

public class Node {
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class GFG {
    public Node root;

/*
    Given a tree and a sum, return true if
    there is a path from the root down to a
    leaf, such that adding up all the values
    along the path equals the given sum.
    Strategy: subtract the node value from the
    sum when recurring down, and check to see
    if the sum is 0 when you run out of tree.
    */

    public virtual bool haspathSum(Node node, int sum)
    {
        if (node == null) {
            return (sum == 0);
        }
        else {
            bool ans = false;
            int subsum = sum - node.data;
            if (subsum == 0 && node.left == null
                && node.right == null) {
                return true;
            }
            if (node.left != null) {
                ans = ans || haspathSum(node.left, subsum);
            }
            if (node.right != null) {
                ans = ans || haspathSum(node.right, subsum);
            }
            return ans;
        }
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        int sum = 21;

/* Constructed binary tree is
            10
            / \
        8     2
        / \ /
        3 5 2
        */

        GFG tree = new GFG();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(2);
        if (tree.haspathSum(tree.root, sum)) {
            Console.WriteLine("There is a root to leaf "
                              + "path with sum " + sum);
        }
        else {
            Console.WriteLine("There is no root to leaf "
                              + "path with sum " + sum);
        }
    }
}

/*c# program to find sum of all numbers 
that are formed from root to leaf paths */

using System;
public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class GFG
{
public Node root;

/*Returns sum of all root to leaf paths. 
The first parameter is root of current 
subtree, the second parameter is value 
of the number formed by nodes from root
to this node */

public virtual int treePathsSumUtil(Node node,
                                    int val)
{

/*    Base case */

    if (node == null)
    {
        return 0;
    }

/*    Update val */

    val = (val * 10 + node.data);

/*    if current node is leaf, return 
    the current value of val */

    if (node.left == null && node.right == null)
    {
        return val;
    }

/*    recur sum of values for left and right subtree */

    return treePathsSumUtil(node.left, val) +
           treePathsSumUtil(node.right, val);
}

/*A wrapper function over treePathsSumUtil() */

public virtual int treePathsSum(Node node)
{

/*    Pass the initial value as 0 as 
    there is nothing above root */

    return treePathsSumUtil(node, 0);
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = new Node(6);
    tree.root.left = new Node(3);
    tree.root.right = new Node(5);
    tree.root.right.right = new Node(4);
    tree.root.left.left = new Node(2);
    tree.root.left.right = new Node(5);
    tree.root.left.right.right = new Node(4);
    tree.root.left.right.left = new Node(7);
    Console.Write("Sum of all paths is " + 
                   tree.treePathsSum(tree.root));
}
}

/*C# program to Merge Two Binary Trees*/

using System;

/* A binary tree node has data, pointer
to left child and a pointer to right child */

public class Node
{
public int data;
public Node left, right;
public Node(int data, Node left,
                      Node right)
{
    this.data = data;
    this.left = left;
    this.right = right;
}

/* Helper method that allocates a new
node with the given data and NULL left
and right pointers. */

public static Node newNode(int data)
{
    return new Node(data, null, null);
}

/* Given a binary tree, print its
   nodes in inorder*/

public static void inorder(Node node)
{
    if (node == null)
    {
        return;
    }

/* first recur on left child */

    inorder(node.left);

/* then print the data of node */

    Console.Write("{0:D} ", node.data);

/* now recur on right child */

    inorder(node.right);
}

/* Method to merge given two binary trees*/

public static Node MergeTrees(Node t1, Node t2)
{
    if (t1 == null)
    {
        return t2;
    }
    if (t2 == null)
    {
        return t1;
    }
    t1.data += t2.data;
    t1.left = MergeTrees(t1.left, t2.left);
    t1.right = MergeTrees(t1.right, t2.right);
    return t1;
}

/*Driver Code*/

public static void Main(string[] args)
{

/* Let us construct the first Binary Tree
            1
        / \
        2     3
        / \     \
        4 5     6
    */

    Node root1 = newNode(1);
    root1.left = newNode(2);
    root1.right = newNode(3);
    root1.left.left = newNode(4);
    root1.left.right = newNode(5);
    root1.right.right = newNode(6);

/* Let us construct the second Binary Tree
            4
        / \
        1     7
        /     / \
    3     2 6 */

    Node root2 = newNode(4);
    root2.left = newNode(1);
    root2.right = newNode(7);
    root2.left.left = newNode(3);
    root2.right.left = newNode(2);
    root2.right.right = newNode(6);
    Node root3 = MergeTrees(root1, root2);
    Console.Write("The Merged Binary Tree is:\n");
    inorder(root3);
}
}

/*C# program to Merge Two Binary Trees*/

using System;
using System.Collections.Generic;
class GFG{

/*A binary tree node has data, pointer
to left child and a pointer to right
child*/

public class Node
{
    public int data;
    public Node left, right;
};

/*Structure to store node pair onto stack*/

public class snode
{
    public Node l, r;
};

/*Helper function that allocates a new
node with the given data and null
left and right pointers.*/

static Node newNode(int data)
{
    Node new_node = new Node();
    new_node.data = data;
    new_node.left = new_node.right = null;
    return new_node;
}

/*Given a binary tree, print its
nodes in inorder*/

static void inorder(Node  node)
{
    if (node == null)
        return;

/*    First recur on left child*/

    inorder(node.left);

/*    Then print the data of node*/

    Console.Write(node.data + " ");

/*    Now recur on right child*/

    inorder(node.right);
}

/*Function to merge given two binary trees*/

static Node MergeTrees(Node t1, Node t2)
{
    if ( t1 == null)
        return t2;
    if ( t2 == null)
        return t1;
    Stack<snode> s = new Stack<snode>();
    snode temp = new snode();
    temp.l = t1;
    temp.r = t2;
    s.Push(temp);
    snode n;
    while (s.Count != 0)
    {
        n = s.Peek();
        s.Pop();
        if (n.l == null|| n.r == null)
            continue;
        n.l.data += n.r.data;
        if (n.l.left == null)
            n.l.left = n.r.left;
        else
        {
            snode t = new snode();
            t.l = n.l.left;
            t.r = n.r.left;
            s.Push(t);
        }
        if (n.l.right == null)
            n.l.right = n.r.right;
        else
        {
            snode t = new snode();
            t.l = n.l.right;
            t.r = n.r.right;
            s.Push(t);
        }
    }
    return t1;
}

/*Driver code*/

public static void Main(String[] args)
{

/* Let us conthe first Binary Tree
            1
          /   \
         2     3
        / \     \
       4   5     6
    */

    Node root1 = newNode(1);
    root1.left = newNode(2);
    root1.right = newNode(3);
    root1.left.left = newNode(4);
    root1.left.right = newNode(5);
    root1.right.right = newNode(6);

/* Let us conthe second Binary Tree
           4
         /   \
        1     7
       /     /  \
      3     2    6   */

    Node root2 = newNode(4);
    root2.left = newNode(1);
    root2.right = newNode(7);
    root2.left.left = newNode(3);
    root2.right.left = newNode(2);
    root2.right.right = newNode(6);
    Node root3 = MergeTrees(root1, root2);
    Console.Write("The Merged Binary Tree is:\n");
    inorder(root3);
}
}

/*C# Find root of tree where children
sum for every node id is given.*/

using System;
class GFG
{
    public class pair
    {
        public int first, second;
        public pair(int first, int second)
        {
            this.first = first;
            this.second = second;
        }
    }
    static int findRoot(pair []arr, int n)
    {

/*        Every node appears once as an id, and
        every node except for the root appears
        once in a sum. So if we subtract all
        the sums from all the ids, we're left
        with the root id.*/

        int root = 0;
        for (int i = 0; i < n; i++)
        {
            root += (arr[i].first - arr[i].second);
        }
        return root;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        pair []arr = {new pair(1, 5), new pair(2, 0),
                    new pair(3, 0), new pair(4, 0),
                    new pair(5, 5), new pair(6, 5)};
        int n = arr.Length;
        Console.Write("{0}\n", findRoot(arr, n));
    }
}

/*C# implementation to find lowest common
ancestor of n1 and n2 using one traversal
of binary tree*/

using System;

/*Class containing left and right
child of current node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class BinaryTree{

/*Root of the Binary Tree*/

Node root;
Node findLCA(int n1, int n2)
{
    return findLCA(root, n1, n2);
}

/*This function returns pointer to LCA
of two given values n1 and n2. This
function assumes that n1 and n2 are
present in Binary Tree*/

Node findLCA(Node node, int n1, int n2)
{

/*    Base case*/

    if (node == null)
        return null;

/*    If either n1 or n2 matches with
    root's key, report the presence
    by returning root (Note that if
    a key is ancestor of other,
    then the ancestor key becomes LCA*/

    if (node.data == n1 || node.data == n2)
        return node;

/*    Look for keys in left and right subtrees*/

    Node left_lca = findLCA(node.left, n1, n2);
    Node right_lca = findLCA(node.right, n1, n2);

/*    If both of the above calls return Non-NULL,
    then one key is present in once subtree
    and other is present in other, So this
    node is the LCA*/

    if (left_lca != null && right_lca != null)
        return node;

/*    Otherwise check if left subtree or
    right subtree is LCA*/

    return (left_lca != null) ? left_lca : right_lca;
}

/*Driver code*/

public static void Main(string []args)
{
    BinaryTree tree = new BinaryTree();
    tree.root = new Node(1);
    tree.root.left = new Node(2);
    tree.root.right = new Node(3);
    tree.root.left.left = new Node(4);
    tree.root.left.right = new Node(5);
    tree.root.right.left = new Node(6);
    tree.root.right.right = new Node(7);
    Console.WriteLine("LCA(4, 5) = " +
                      tree.findLCA(4, 5).data);
    Console.WriteLine("LCA(4, 6) = " +
                      tree.findLCA(4, 6).data);
    Console.WriteLine("LCA(3, 4) = " +
                      tree.findLCA(3, 4).data);
    Console.WriteLine("LCA(2, 4) = " +
                      tree.findLCA(2, 4).data);
}
}

/*c# implementation to find lowest common ancestor of
n1 and n2 using one traversal of binary tree
It also handles cases even when n1 and n2 are not there in Tree*/

using System;

/* Class containing left and right child of current node and key */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{

/*    Root of the Binary Tree*/

    public Node root;
    public static bool v1 = false, v2 = false;

/*    This function returns pointer to LCA of two given
    values n1 and n2.
    v1 is set as true by this function if n1 is found
    v2 is set as true by this function if n2 is found*/

    public virtual Node findLCAUtil(Node node, int n1, int n2)
    {

/*        Base case*/

        if (node == null)
        {
            return null;
        }

/*        Store result in temp, in case of key match so that we can search for other key also.*/

        Node temp = null;

/*        If either n1 or n2 matches with root's key, report the presence
        by setting v1 or v2 as true and return root (Note that if a key
        is ancestor of other, then the ancestor key becomes LCA)*/

        if (node.data == n1)
        {
            v1 = true;
            temp = node;
        }
        if (node.data == n2)
        {
            v2 = true;
            temp = node;
        }

/*        Look for keys in left and right subtrees*/

        Node left_lca = findLCAUtil(node.left, n1, n2);
        Node right_lca = findLCAUtil(node.right, n1, n2);
        if (temp != null)
        {
            return temp;
        }

/*        If both of the above calls return Non-NULL, then one key
        is present in once subtree and other is present in other,
        So this node is the LCA*/

        if (left_lca != null && right_lca != null)
        {
            return node;
        }

/*        Otherwise check if left subtree or right subtree is LCA*/

        return (left_lca != null) ? left_lca : right_lca;
    }

/*    Finds lca of n1 and n2 under the subtree rooted with 'node'*/

    public virtual Node findLCA(int n1, int n2)
    {

/*        Initialize n1 and n2 as not visited*/

        v1 = false;
        v2 = false;

/*        Find lca of n1 and n2 using the technique discussed above*/

        Node lca = findLCAUtil(root, n1, n2);

/*        Return LCA only if both n1 and n2 are present in tree*/

        if (v1 && v2)
        {
            return lca;
        }

/*        Else return NULL*/

        return null;
    }

/* Driver program to test above functions */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        Node lca = tree.findLCA(4, 5);
        if (lca != null)
        {
            Console.WriteLine("LCA(4, 5) = " + lca.data);
        }
        else
        {
            Console.WriteLine("Keys are not present");
        }
        lca = tree.findLCA(4, 10);
        if (lca != null)
        {
            Console.WriteLine("LCA(4, 10) = " + lca.data);
        }
        else
        {
            Console.WriteLine("Keys are not present");
        }
    }
}

/*C# program to find lowest common ancestor using parent pointer*/

/*A tree node*/

using System;
using System.Collections;
using System.Collections.Generic; 
public class Node 
{
    public int key;
    public Node left, right, parent;
    public Node(int key) 
    {
        this.key = key;
        left = right = parent = null;
    }
}
class BinaryTree 
{
    Node root, n1, n2, lca;

/* A utility function to insert a new node with
    given key in Binary Search Tree */

    Node insert(Node node, int key) 
    {

/* If the tree is empty, return a new node */

        if (node == null)
            return new Node(key);

/* Otherwise, recur down the tree */

        if (key < node.key) 
        {
            node.left = insert(node.left, key);
            node.left.parent = node;
        }
        else if (key > node.key) 
        {
            node.right = insert(node.right, key);
            node.right.parent = node;
        }

/* return the (unchanged) node pointer */

        return node;
    }

/*    To find LCA of nodes n1 and n2 in Binary Tree*/

    Node LCA(Node n1, Node n2) 
    {

/*        Creata a map to store ancestors of n1*/

        Dictionary<Node, Boolean> ancestors = new Dictionary<Node, Boolean>();

/*        Insert n1 and all its ancestors in map*/

        while (n1 != null) 
        {
            ancestors.Add(n1,true);
            n1 = n1.parent;
        }

/*        Check if n2 or any of its ancestors is in
        map.*/

        while (n2 != null) 
        {
            if (ancestors.ContainsKey(n2))
                return n2;
            n2 = n2.parent;
        }
        return null;
    }

/*    Driver code*/

    public static void Main(String []args) 
    {
        BinaryTree tree = new BinaryTree();
        tree.root = tree.insert(tree.root, 20);
        tree.root = tree.insert(tree.root, 8);
        tree.root = tree.insert(tree.root, 22);
        tree.root = tree.insert(tree.root, 4);
        tree.root = tree.insert(tree.root, 12);
        tree.root = tree.insert(tree.root, 10);
        tree.root = tree.insert(tree.root, 14);
        tree.n1 = tree.root.left.right.left;
        tree.n2 = tree.root.left;
        tree.lca = tree.LCA(tree.n1, tree.n2);
        Console.WriteLine("LCA of " + tree.n1.key + " and " + tree.n2.key
                + " is " + tree.lca.key);
    }
}

/*C# program to find lowest common 
ancestor using parent pointer */

using System;

/*A tree node */

public class Node
{
    public int key;
    public Node left, right, parent;
    public Node(int key)
    {
        this.key = key;
        left = right = parent = null;
    }
}
class GFG
{
public Node root, n1, n2, lca;

/* A utility function to insert a new
 node with given key in Binary Search Tree */

public virtual Node insert(Node node, int key)
{

/* If the tree is empty, return 
       a new node */

    if (node == null)
    {
        return new Node(key);
    }

/* Otherwise, recur down the tree */

    if (key < node.key)
    {
        node.left = insert(node.left, key);
        node.left.parent = node;
    }
    else if (key > node.key)
    {
        node.right = insert(node.right, key);
        node.right.parent = node;
    }

/* return the (unchanged) node pointer */

    return node;
}

/*A utility function to find depth of a 
node (distance of it from root) */

public virtual int depth(Node node)
{
    int d = -1;
    while (node != null)
    {
        ++d;
        node = node.parent;
    }
    return d;
}

/*To find LCA of nodes n1 and n2 
in Binary Tree */

public virtual Node LCA(Node n1, Node n2)
{

/*    Find depths of two nodes 
    and differences */

    int d1 = depth(n1), d2 = depth(n2);
    int diff = d1 - d2;

/*    If n2 is deeper, swap n1 and n2 */

    if (diff < 0)
    {
        Node temp = n1;
        n1 = n2;
        n2 = temp;
        diff = -diff;
    }

/*    Move n1 up until it reaches 
    the same level as n2 */

    while (diff-- != 0)
    {
        n1 = n1.parent;
    }

/*    Now n1 and n2 are at same levels */

    while (n1 != null && n2 != null)
    {
        if (n1 == n2)
        {
            return n1;
        }
        n1 = n1.parent;
        n2 = n2.parent;
    }
    return null;
}

/*Driver Code*/

public static void Main(string[] args)
{
    GFG tree = new GFG();
    tree.root = tree.insert(tree.root, 20);
    tree.root = tree.insert(tree.root, 8);
    tree.root = tree.insert(tree.root, 22);
    tree.root = tree.insert(tree.root, 4);
    tree.root = tree.insert(tree.root, 12);
    tree.root = tree.insert(tree.root, 10);
    tree.root = tree.insert(tree.root, 14);
    tree.n1 = tree.root.left.right.left;
    tree.n2 = tree.root.right;
    tree.lca = tree.LCA(tree.n1, tree.n2);
    Console.WriteLine("LCA of " + tree.n1.key +
                      " and " + tree.n2.key + 
                      " is " + tree.lca.key);
}
}

/*C# code to find LCA of given
two nodes in a tree*/

using System;
using System.Collections.Generic;
public class GFG
{
  static int maxn = 100005;
  static  int left(int i)
  {
    return  (2 * i + 1);
  }
  static  int right(int i) { return 2 * i + 2;}

/*  the graph*/

  static List<int> []g = new List<int>[maxn];

/*  level of each node*/

  static int []level = new int[maxn];
  static List<int> e = new List<int>();
  static List<int> l= new List<int>();
  static int []h = new int[maxn];

/*  the segment tree*/

  static int []st;

/*  adding edges to the graph(tree)*/

  static void add_edge(int u, int v)
  {
    g[u].Add(v);
    g[v].Add(u);
  }

/*  assigning level to nodes*/

  static void leveling(int src)
  {
    for (int i = 0; i < (g[src].Count); i++)
    {
      int des = g[src][i];
      if (level[des] != 0)
      {
        level[des] = level[src] + 1;
        leveling(des);
      }
    }
  }
  static bool []visited = new bool[maxn];

/*  storing the dfs traversal
  in the array e*/

  static void dfs(int src)
  {
    e.Add(src);
    visited[src] = true;
    for (int i = 0; i < (g[src]).Count; i++)
    {
      int des = g[src][i];
      if (!visited[des])
      {
        dfs(des);
        e.Add(src);
      }
    }
  }

/*  making the array l*/

  static void setting_l(int n)
  {
    for (int i = 0; i < e.Count; i++)
      l.Add(level[e[i]]);
  }

/*  making the array h*/

  static void setting_h(int n)
  {
    for (int i = 0; i <= n; i++)
      h[i] = -1;
    for (int i = 0; i < e.Count; i++)
    {

/*      if is already stored*/

      if (h[e[i]] == -1)
        h[e[i]] = i;
    }
  }

/*  Range minimum query to return the index
  of minimum in the subarray L[qs:qe]*/

  static int RMQ(int ss, int se, int qs, int qe, int i)
  {
    if (ss > se)
      return -1;

/*    out of range*/

    if (se < qs || qe < ss)
      return -1;

/*    in the range*/

    if (qs <= ss && se <= qe)
      return st[i];
    int mid = (ss + se)/2 ;
    int sti = RMQ(ss, mid, qs, qe, left(i));
    int en = RMQ(mid + 1, se, qs, qe, right(i));
    if (sti != -1 && en != -1)
    {
      if (l[sti] < l[en])
        return sti;
      return en;
    } else if (sti != -1)
      return sti-2;
    else if (en != -1)
      return en-1;
    return 0;
  }

/*  constructs the segment tree*/

  static void SegmentTreeConstruction(int ss,
                                      int se, int i)
  {
    if (ss > se)
      return;

/*leaf*/

if (ss == se) 
    {
      st[i] = ss;
      return;
    }
    int mid = (ss + se) /2;
    SegmentTreeConstruction(ss, mid, left(i));
    SegmentTreeConstruction(mid + 1, se, right(i));
    if (l[st[left(i)]] < l[st[right(i)]])
      st[i] = st[left(i)];
    else
      st[i] = st[right(i)];
  }

/*  Function to get LCA*/

  static int LCA(int x, int y)
  {
    if (h[x] > h[y])
    {
      int t = x;
      x = y;
      y = t;
    }
    return e[RMQ(0, l.Count - 1, h[x], h[y], 0)];
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    st = new int[5 * maxn];

/*    n=number of nodes in the tree
    q=number of queries to answer*/

    int n = 15;
    for (int i = 0; i < g.Length; i++)
      g[i] = new List<int>();

/*    making the tree*/

/*
                   1
                 / | \
                2  3  4
                   |   \
                   5    6
                 / |  \
               8   7    9 (right of 5)
                 / | \   | \
               10 11 12 13 14
                      |
                      15
  */

    add_edge(1, 2);
    add_edge(1, 3);
    add_edge(1, 4);
    add_edge(3, 5);
    add_edge(4, 6);
    add_edge(5, 7);
    add_edge(5, 8);
    add_edge(5, 9);
    add_edge(7, 10);
    add_edge(7, 11);
    add_edge(7, 12);
    add_edge(9, 13);
    add_edge(9, 14);
    add_edge(12, 15);
    level[1] = 1;
    leveling(1);
    dfs(1);
    setting_l(n);
    setting_h(n);
    SegmentTreeConstruction(0, l.Count - 1, 0);
    Console.Write(LCA(10, 15) +"\n");
    Console.Write(LCA(11, 14) +"\n");
  }
}

/*C# Program to find common nodes for given two nodes */
using System;

/*Class to represent Tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = null;
        right = null;
    }
}

/*Class to count full nodes of Tree */

public class BinaryTree
{
    public static Node root;

/*Utility function to find the LCA of two given values 
n1 and n2. */

public static Node findLCA(Node root, int n1, int n2)
{

/*    Base case */

    if (root == null)
    {
        return null;
    }

/*    If either n1 or n2 matches with root's key, 
    report the presence by returning root (Note 
    that if a key is ancestor of other, then the 
    ancestor key becomes LCA */

    if (root.data == n1 || root.data == n2)
    {
        return root;
    }

/*    Look for keys in left and right subtrees */

    Node left_lca = findLCA(root.left, n1, n2);
    Node right_lca = findLCA(root.right, n1, n2);

/*    If both of the above calls return Non-NULL, then 
    one key is present in once subtree and other is 
    present in other, So this node is the LCA */

    if (left_lca != null && right_lca != null)
    {
        return root;
    }

/*    Otherwise check if left subtree or right 
    subtree is LCA */

    return (left_lca != null) ? left_lca : right_lca;
}

/*Utility Function to print all ancestors of LCA */

public static bool printAncestors(Node root, int target)
{

/* base cases */

    if (root == null)
    {
        return false;
    }
    if (root.data == target)
    {
        Console.Write(root.data + " ");
        return true;
    }

/* If target is present in either left or right 
    subtree of this node, then print this node */

    if (printAncestors(root.left, target) 
    || printAncestors(root.right, target))
    {
        Console.Write(root.data + " ");
        return true;
    }

/* Else return false */

    return false;
}

/*Function to find nodes common to given two nodes */

public static bool findCommonNodes(Node root, 
                            int first, int second)
{
    Node LCA = findLCA(root, first, second);
    if (LCA == null)
    {
        return false;
    }
    printAncestors(root, LCA.data);
    return true;
}

/*Driver program to test above functions */

    public static void Main(string[] args)
    {

/*Let us create Binary Tree shown in 
        above example */

        BinaryTree tree = new BinaryTree();
        BinaryTree.root = new Node(1);
        BinaryTree.root.left = new Node(2);
        BinaryTree.root.right = new Node(3);
        BinaryTree.root.left.left = new Node(4);
        BinaryTree.root.left.right = new Node(5);
        BinaryTree.root.right.left = new Node(6);
        BinaryTree.root.right.right = new Node(7);
        BinaryTree.root.left.left.left = new Node(8);
        BinaryTree.root.right.left.left = new Node(9);
        BinaryTree.root.right.left.right = new Node(10);
if (findCommonNodes(root, 9, 7) == false)
{
    Console.WriteLine("No Common nodes");
}
    }
}

/*C# program to find LCA of u and
v by reducing problem to RMQ*/

using System;

/*A binary tree node*/

class Node
{
    public Node left, right;
    public int data;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
class St_class
{
    public int st;
    public int []stt = new int[10000];
}
public class BinaryTree
{
    Node root;

/*v is the highest value of node in our tree*/

static int v = 9;

/*for euler tour sequence*/

int []euler = new int[2 * v - 1];

/*level of nodes in tour sequence*/

int []level = new int[2 * v - 1];

/*to store 1st occurrence of nodes*/

int []f_occur = new int[2 * v - 1];

/*variable to fill euler and level arrays*/

int fill; 
    St_class sc = new St_class();

/*    log base 2 of x*/

    int Log2(int x)
    {
        int ans = 0;
        int y = x >>= 1;
        while (y-- != 0)
            ans++;
        return ans;
    }
    int swap(int a, int b)
    {
        return a;
    }

/* A recursive function to get
    the minimum value in a given range
    of array indexes. The following
    are parameters for this function.
    st --> Pointer to segment tree
    index --> Index of current node
    in the segment tree. Initially
    0 is passed as root is always at index 0
    ss & se --> Starting and ending
    indexes of the segment represented
    by current node, i.e., st[index]
    qs & qe --> Starting and ending
    indexes of query range */

    int RMQUtil(int index, int ss, int se,
                    int qs, int qe, St_class st)
    {

/*        If segment of this node is a part
        of given range, then return
        the min of the segment*/

        if (qs <= ss && qe >= se)
            return st.stt[index];

/*        If segment of this node is
        outside the given range*/

        else if (se < qs || ss > qe)
            return -1;

/*        If a part of this segment
        overlaps with the given range*/

        int mid = (ss + se) / 2;
        int q1 = RMQUtil(2 * index + 1,
                        ss, mid, qs, qe, st);
        int q2 = RMQUtil(2 * index + 2,
                        mid + 1, se, qs, qe, st);
        if (q1 == -1)
            return q2;
        else if (q2 == -1)
            return q1;
        return (level[q1] < level[q2]) ? q1 : q2;
    }

/*    Return minimum of elements in
    range from index qs (query start) to
    qe (query end). It mainly uses RMQUtil()*/

    int RMQ(St_class st, int n, int qs, int qe)
    {

/*        Check for erroneous input values*/

        if (qs < 0 || qe > n - 1 || qs > qe)
        {
            Console.WriteLine("Invalid input");
            return -1;
        }
        return RMQUtil(0, 0, n - 1, qs, qe, st);
    }

/*    A recursive function that constructs
    Segment Tree for array[ss..se].
    si is index of current node in segment tree st*/

    void constructSTUtil(int si, int ss, int se,
                        int []arr, St_class st)
    {

/*        If there is one element in array,
        store it in current node of
        segment tree and return*/

        if (ss == se)
            st.stt[si] = ss;
        else
        {

/*            If there are more than one elements,
            then recur for left and right subtrees
            and store the minimum of two values in this node*/

            int mid = (ss + se) / 2;
            constructSTUtil(si * 2 + 1, ss, mid, arr, st);
            constructSTUtil(si * 2 + 2, mid + 1, se, arr, st);
            if (arr[st.stt[2 * si + 1]] < arr[st.stt[2 * si + 2]])
                st.stt[si] = st.stt[2 * si + 1];
            else
                st.stt[si] = st.stt[2 * si + 2];
        }
    }

/* Function to construct segment tree
    from given array. This function
    allocates memory for segment tree
    and calls constructSTUtil() to
    fill the allocated memory */

    int constructST(int []arr, int n)
    {

/*        Allocate memory for segment tree
        Height of segment tree*/

        int x = Log2(n) + 1;

/*        Maximum size of segment tree
2*pow(2,x) -1*/

int max_size = 2 * (1 << x) - 1; 
        sc.stt = new int[max_size];

/*        Fill the allocated memory st*/

        constructSTUtil(0, 0, n - 1, arr, sc);

/*        Return the constructed segment tree*/

        return sc.st;
    }

/*    Recursive version of the Euler tour of T*/

    void eulerTour(Node node, int l)
    {

/* if the passed node exists */

        if (node != null)
        {

/*insert in euler array*/

euler[fill] = node.data;

/*insert l in level array*/

level[fill] = l;

/*increment index*/

fill++;

/* if unvisited, mark first occurrence */

            if (f_occur[node.data] == -1)
                f_occur[node.data] = fill - 1;

/* tour left subtree if exists,
                and remark euler and level
                arrays for parent on return */

            if (node.left != null)
            {
                eulerTour(node.left, l + 1);
                euler[fill] = node.data;
                level[fill] = l;
                fill++;
            }

/* tour right subtree if exists, and remark euler
            and level arrays for parent on return */

            if (node.right != null)
            {
                eulerTour(node.right, l + 1);
                euler[fill] = node.data;
                level[fill] = l;
                fill++;
            }
        }
    }

/*    returns LCA of node n1 and n2
    assuming they are present in tree*/

    int findLCA(Node node, int u, int v)
    {

/* Mark all nodes unvisited. Note
         that the size of firstOccurrence
         is 1 as node values which
         vary from 1 to 9 are used as indexes */

        for(int i = 0; i < f_occur.Length; i++)
            f_occur[i] = -1;

/* To start filling euler and
        level arrays from index 0 */

        fill = 0;

/* Start Euler tour with
        root node on level 0 */

        eulerTour(root, 0);

/* construct segment tree on level array */

        sc.st = constructST(level, 2 * v - 1);

/* If v before u in Euler tour.
        For RMQ to work, first parameter
        'u' must be smaller than
         second 'v' */

        if (f_occur[u] > f_occur[v])
            u = swap(u, u = v);

/*        Starting and ending indexes of query range*/

        int qs = f_occur[u];
        int qe = f_occur[v];

/*        query for index of LCA in tour*/

        int index = RMQ(sc, 2 * v - 1, qs, qe);

/* return LCA node */

        return euler[index];
    }

/*    Driver program to test above functions*/

    public static void Main(String []args)
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create the Binary Tree
        as shown in the diagram.*/

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);
        tree.root.left.right.left = new Node(8);
        tree.root.left.right.right = new Node(9);
        int u = 4, v = 9;
        Console.WriteLine("The LCA of node " + u + " and " + v + " is "
                + tree.findLCA(tree.root, u, v));
    }
}

/* C# program to find maximum difference between node
   and its ancestor */
using System;

/*A binary tree node has key, pointer to left 
and right child */

public class Node
{
    public int key;
    public Node left, right;
    public Node(int key)
    {
        this.key = key;
        left = right = null;
    }
}

/* Class Res created to implement pass by reference
   of 'res' variable */

public class Res
{
    public int r = int.MinValue;
}
public class BinaryTree
{
    public Node root;

/* Recursive function to calculate maximum ancestor-node
       difference in  binary tree. It updates value at 'res'
       to store the result.  The returned value of this function
       is minimum value in subtree rooted with 't' */

    public virtual int maxDiffUtil(Node t, Res res)
    {

/* Returning Maximum int value if node is not
           there (one child case)  */

        if (t == null)
        {
            return int.MaxValue;
        }

/* If leaf node then just return node's value  */

        if (t.left == null && t.right == null)
        {
            return t.key;
        }

/* Recursively calling left and right subtree
           for minimum value  */

        int val = Math.Min(maxDiffUtil(t.left, res), maxDiffUtil(t.right, res));

/* Updating res if (node value - minimum value
           from subtree) is bigger than res  */

        res.r = Math.Max(res.r, t.key - val);

/* Returning minimum value got so far */

        return Math.Min(val, t.key);
    }

/* This function mainly calls maxDiffUtil() */

    public virtual int maxDiff(Node root)
    {

/*        Initialising result with minimum int value*/

        Res res = new Res();
        maxDiffUtil(root, res);
        return res.r;
    }

/* Helper function to print inorder traversal of
       binary tree   */

    public virtual void inorder(Node root)
    {
        if (root != null)
        {
            inorder(root.left);
            Console.Write(root.key + "");
            inorder(root.right);
        }
    }

/*    Driver program to test the above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/*        Making above given diagram's binary tree*/

        tree.root = new Node(8);
        tree.root.left = new Node(3);
        tree.root.left.left = new Node(1);
        tree.root.left.right = new Node(6);
        tree.root.left.right.left = new Node(4);
        tree.root.left.right.right = new Node(7);
        tree.root.right = new Node(10);
        tree.root.right.right = new Node(14);
        tree.root.right.right.left = new Node(13);
        Console.WriteLine("Maximum difference between a node and" + " its ancestor is : " + tree.maxDiff(tree.root));
    }
}

/*C# implementation to print the path common to the
two paths from the root to the two given nodes*/

using System;
using System.Collections.Generic;
public class PrintCommonPath
{

/*    Initialize n1 and n2 as not visited*/

    static Boolean v1 = false, v2 = false;

/* Class containing left and right child of current
node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*    This function returns pointer to LCA of two given
    values n1 and n2. This function assumes that n1 and
    n2 are present in Binary Tree*/

    static Node findLCAUtil(Node node, int n1, int n2)
    {

/*        Base case*/

        if (node == null)
            return null;

/*        Store result in temp, in case of key
        match so that we can search for other key also.*/

        Node temp=null;

/*        If either n1 or n2 matches with root's key, report the presence
        by setting v1 or v2 as true and return root (Note that if a key
        is ancestor of other, then the ancestor key becomes LCA)*/

        if (node.data == n1)
        {
            v1 = true;
            temp = node;
        }
        if (node.data == n2)
        {
            v2 = true;
            temp = node;
        }

/*        Look for keys in left and right subtrees*/

        Node left_lca = findLCAUtil(node.left, n1, n2);
        Node right_lca = findLCAUtil(node.right, n1, n2);
        if (temp != null)
            return temp;

/*        If both of the above calls return Non-NULL, then one key
        is present in once subtree and other is present in other,
        So this node is the LCA*/

        if (left_lca != null && right_lca != null)
            return node;

/*        Otherwise check if left subtree or right subtree is LCA*/

        return (left_lca != null) ? left_lca : right_lca;
    }

/*    Returns true if key k is present in tree rooted with root*/

    static Boolean find(Node root, int k)
    {

/*        Base Case*/

        if (root == null)
            return false;

/*        If key k is present at root, or in left subtree
        or right subtree, return true*/

        if (root.data == k || find(root.left, k) || find(root.right, k))
            return true;

/*        Else return false*/

        return false;
    }

/*    This function returns LCA of n1 and n2 only if both n1 and n2
    are present in tree, otherwise returns null*/

    static Node findLCA(Node root, int n1, int n2)
    {

/*        Find lca of n1 and n2*/

        Node lca = findLCAUtil(root, n1, n2);

/*        Return LCA only if both n1 and n2 are present in tree*/

        if (v1 && v2 || v1 && find(lca, n2) || v2 && find(lca, n1))
            return lca;

/*        Else return null*/

        return null;
    }

/*    function returns true if
    there is a path from root to
    the given node. It also populates
    'arr' with the given path*/

    static Boolean hasPath(Node root, List<int> arr, int x)
    {

/*        if root is null
        there is no path*/

        if (root == null)
            return false;

/*        push the node's value in 'arr'*/

        arr.Add(root.data);

/*        if it is the required node
        return true*/

        if (root.data == x)    
            return true;

/*        else check whether there the required node lies in the
        left subtree or right subtree of the current node*/

        if (hasPath(root.left, arr, x) ||
            hasPath(root.right, arr, x))
            return true;

/*        required node does not lie either in the
        left or right subtree of the current node
        Thus, remove current node's value from 'arr'
        and then return false;    */

        arr.Remove(arr.Count-1);
        return false;            
    }

/*    function to print the path common
    to the two paths from the root
    to the two given nodes if the nodes
    lie in the binary tree*/

    static void printCommonPath(Node root, int n1, int n2)
    {

/*        ArrayList to store the common path*/

        List<int> arr = new List<int>();

/*        LCA of node n1 and n2*/

        Node lca = findLCA(root, n1, n2);

/*        if LCA of both n1 and n2 exists*/

        if (lca!=null)
        {

/*            then print the path from root to
            LCA node*/

            if (hasPath(root, arr, lca.data))
            {
                for (int i=0; i<arr.Count-1; i++)    
                    Console.Write(arr[i]+"->");
                    Console.Write(arr[arr.Count - 1]);    
            }    
        }

/*        LCA is not present in the binary tree
        either n1 or n2 or both are not present*/

        else
            Console.Write("No Common Path");
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.right.left = new Node(6);
        root.right.right = new Node(7);
        root.left.right.left = new Node(8);
        root.right.left.right = new Node(9);
        int n1 = 4, n2 = 8;
        printCommonPath(root, n1, n2);
        }
}

/*C# program to query whether two node has
ancestor-descendant relationship or not*/

using System;
using System.Collections;
class GFG{

/*Utility dfs method to assign in and out time
to each node*/

static void dfs(ArrayList []g, int u, int parent,
                int []timeIn, int []timeOut,
                ref int cnt)
{

/*    Assign In-time to node u*/

    timeIn[u] = cnt++;

/*    Call dfs over all neighbors except parent*/

    for(int i = 0; i < g[u].Count; i++)
    {
        int v = (int)g[u][i];
        if (v != parent)
            dfs(g, v, u, timeIn, timeOut, ref cnt);
    }

/*    Assign Out-time to node u*/

    timeOut[u] = cnt++;
}

/*Method to preprocess all nodes for assigning time*/

static void preProcess(int [,]edges, int V,
                       int []timeIn, int []timeOut)
{
    ArrayList []g = new ArrayList[V];
    for(int i = 0; i < V; i++)
    {
        g[i] = new ArrayList();
    }

/*    Construct array of vector data structure
    for tree*/

    for(int i = 0; i < V - 1; i++)
    {
        int u = edges[i, 0];
        int v = edges[i, 1];
        g[u].Add(v);
        g[v].Add(u);
    }
    int cnt = 0;

/*    Call dfs method from root*/

    dfs(g, 0, -1, timeIn, timeOut, ref cnt);
}

/*Method returns "yes" if u is a ancestor
node of v*/

static string isAncestor(int u, int v, int []timeIn,
                                       int []timeOut)
{
    bool b = (timeIn[u] <= timeIn[v] &&
             timeOut[v] <= timeOut[u]);
    return (b ? "yes" : "no");
}

/*Driver code   */

static void Main()
{
    int [,]edges = { { 0, 1 },
                     { 0, 2 },
                     { 1, 3 },
                     { 1, 4 },
                     { 2, 5 },
                     { 4, 6 },
                     { 5, 7 } };
    int E = edges.GetLength(0);
    int V = E + 1;
    int []timeIn = new int[V];
    int []timeOut = new int[V];
    preProcess(edges, V, timeIn, timeOut);
    int u = 1;
    int v = 6;
    Console.Write(isAncestor(u, v, timeIn,
                             timeOut) + "\n");
    u = 1;
    v = 7;
    Console.Write(isAncestor(u, v, timeIn,
                             timeOut) + "\n");
}
}

/*C# implementation to print the path from root 
to a given node in a binary tree */

using System;
using System.Collections;
using System.Collections.Generic;
class PrintPath 
{

/*A node of binary tree */

public class Node 
{ 
    public int data; 
    public Node left, right; 
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}

/*    Returns true if there is a path from root 
    to the given node. It also populates 
    'arr' with the given path */

    public static Boolean hasPath(Node root,
                        List<int> arr, int x) 
    {

/*        if root is NULL 
        there is no path */

        if (root == null) 
            return false;

/*        push the node's value in 'arr' */

        arr.Add(root.data);

/*        if it is the required node 
        return true */

        if (root.data == x)     
            return true;

/*        else check whether the required node lies 
        in the left subtree or right subtree of 
        the current node */

        if (hasPath(root.left, arr, x) || 
            hasPath(root.right, arr, x)) 
            return true;

/*        required node does not lie either in the 
        left or right subtree of the current node 
        Thus, remove current node's value from 
        'arr'and then return false     */

        arr.RemoveAt(arr.Count - 1); 
        return false;             
    }

/*    function to print the path from root to the 
    given node if the node lies in the binary tree */

    public static void printPath(Node root, int x) 
    {

/*        List to store the path */

        List<int> arr = new List<int>();

/*        if required node 'x' is present 
        then print the path */

        if (hasPath(root, arr, x)) 
        { 
            for (int i = 0; i < arr.Count - 1; i++)     
                Console.Write(arr[i]+"->");
            Console.Write(arr[arr.Count - 1]); 
        }

/*        'x' is not present in the binary tree */

        else
            Console.Write("No Path"); 
    }

/*    Driver code*/

    public static void Main(String []args) 
    {

/*    binary tree formation*/

        Node root = new Node(1);
        root.left = new Node(2); 
        root.right = new Node(3); 
        root.left.left = new Node(4); 
        root.left.right = new Node(5); 
        root.right.left = new Node(6); 
        root.right.right = new Node(7); 
        int x=5;
        printPath(root, x);
    }
}

/*C# program to print ancestors of given node */

using System;

/* A binary tree node has data, pointer to left child 
and a pointer to right child */

public class Node
{
    public int data;
    public Node left, right, nextRight;
    public Node(int item)
    {
        data = item;
        left = right = nextRight = null;
    }
}
public class BinaryTree
{
    public Node root;

/* If target is present in tree, then prints the ancestors 
    and returns true, otherwise returns false. */

    public virtual bool printAncestors(Node node, int target)
    {

/* base cases */

        if (node == null)
        {
            return false;
        }
        if (node.data == target)
        {
            return true;
        }

/* If target is present in either left or right subtree 
        of this node, then print this node */

        if (printAncestors(node.left, target) 
        || printAncestors(node.right, target))
        {
            Console.Write(node.data + " ");
            return true;
        }

/* Else return false */

        return false;
    }

/* Driver program to test above functions */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/* Construct the following binary tree 
                1 
                / \ 
            2     3 
            / \ 
            4 5 
            / 
        7 
        */

        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.left.left.left = new Node(7);
        tree.printAncestors(tree.root, 7);
    }
}

/*C# program to calculate Kth ancestor of given node */

using System;
class GFG
{

/*A Binary Tree Node*/

public class Node
{
    public int data;
    public Node left, right;
};

/*temporary node to keep track of Node returned
from previous recursive call during backtrack*/

static Node temp = null;
static int k;

/*recursive function to calculate Kth ancestor*/

static Node kthAncestorDFS(Node root, int node )
{

/*    Base case*/

    if (root == null)
        return null;
    if (root.data == node||
    (temp = kthAncestorDFS(root.left,node)) != null ||
    (temp = kthAncestorDFS(root.right,node)) != null)
    { 
        if (k > 0)     
            k--;
        else if (k == 0)
        {

/*            print the kth ancestor*/

            Console.Write("Kth ancestor is: "+root.data);

/*            return null to stop further backtracking*/

            return null;
        }

/*        return current node to previous call*/

        return root;
    }
    return null;
}

/*Utility function to create a new tree node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver code*/

public static void Main(String []args)
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    k = 2;
    int node = 5;

/*    print kth ancestor of given node*/

    Node parent = kthAncestorDFS(root,node);

/*    check if parent is not null, it means
    there is no Kth ancestor of the node*/

    if (parent != null)
        Console.WriteLine("-1");
}
}

/*C# program to demonstrate Succinct
Tree Encoding and decoding*/

using System;
using System.Collections.Generic;
class GFG{

/*  A Binary Tree Node*/

  public
    class Node
    {
      public
        int key;
      public
        Node left, right;
    };

/*  Utility function to create new Node*/

  static Node newNode(int key)
  {
    Node temp = new Node();
    temp.key  = key;
    temp.left  = temp.right = null;
    return (temp);
  }
  static List<Boolean> struc;
  static List<int> data;
  static Node root;

/*  This function fills lists 'struc' and
  'data'. 'struc' list stores structure
  information. 'data' list stores tree data*/

  static void EncodeSuccinct(Node root)
  {

/*    If root is null, put 0 in
    structure array and return*/

    if (root == null)
    {
      struc.Add(false);
      return;
    }

/*    Else place 1 in structure array,
    key in 'data' array and recur
    for left and right children*/

    struc.Add(true);
    data.Add(root.key);
    EncodeSuccinct(root.left);
    EncodeSuccinct(root.right);
  }

/*  Constructs tree from 'struc' and 'data'*/

  static Node DecodeSuccinct()
  {
    if (struc.Count <= 0)
      return null;

/*    Remove one item from structure list*/

    bool b = struc[0];
    struc.RemoveAt(0);

/*    If removed bit is 1,*/

    if (b == true)
    {

/*      Remove an item from data list*/

      int key = data[0];
      data.Remove(0);

/*      Create a tree node with the
      removed data*/

      Node root = newNode(key);

/*      And recur to create left and
      right subtrees*/

      root.left = DecodeSuccinct();
      root.right = DecodeSuccinct();
      return root;
    }
    return null;
  }

/*  A utility function to print tree*/

  static void preorder(Node root)
  {
    if (root != null)
    {
      Console.Write("key: "+ root.key);
      if (root.left != null)
        Console.Write(" | left child: " + 
                      root.left.key);
      if (root.right != null)
        Console.Write(" | right child: " + 
                      root.right.key);
      Console.WriteLine();
      preorder(root.left);
      preorder(root.right);
    }
  }

/*  Driver code*/

  public static void Main(String[] args)
  {

/*    Let us conthe Tree shown in
    the above figure*/

    Node root = newNode(10);
    root.left = newNode(20);
    root.right = newNode(30);
    root.left.left = newNode(40);
    root.left.right = newNode(50);
    root.right.right = newNode(70);
    Console.Write("Given Tree\n");
    preorder(root);
    struc = new List<Boolean>();
    data = new List<int>();
    EncodeSuccinct(root);
    Console.Write("\nEncoded Tree\n");
    Console.Write("Structure List\n");

/*Structure iterator*/

    foreach(bool  si in struc)
    {
      if (si == true)
        Console.Write(1 + " ");
      else
        Console.Write(0 + " ");
    }
    Console.Write("\nData List\n");

/*Data iterator*/

    foreach(int di in data)
      Console.Write(di + " ");
    Node newroot = DecodeSuccinct();
    Console.Write("\n\nPreorder traversal" +
                  "of decoded tree\n");                    
    preorder(newroot);
  }
}

/*C# program to demonstrate Range Update 
and Point Queries Without using BIT */

using System;
class GfG 
{

/*Updates such that getElement() 
gets an increased value when
queried from l to r. */

static void update(int []arr, int l, 
                    int r, int val) 
{ 
    arr[l] += val; 
    if(r + 1 < arr.Length) 
    arr[r + 1] -= val; 
}

/*Get the element indexed at i */

static int getElement(int []arr, int i) 
{

/*    To get ith element sum of all the elements 
    from 0 to i need to be computed */

    int res = 0; 
    for (int j = 0 ; j <= i; j++) 
        res += arr[j]; 
    return res; 
}

/*Driver code */

public static void Main(String[] args) 
{ 
    int []arr = {0, 0, 0, 0, 0}; 
    int n = arr.Length; 
    int l = 2, r = 4, val = 2; 
    update(arr, l, r, val);

/*    Find the element at Index 4 */

    int index = 4; 
    Console.WriteLine("Element at index " + 
                        index + " is " +
                        getElement(arr, index)); 
    l = 0; 
    r = 3; 
    val = 4; 
    update(arr,l,r,val);

/*    Find the element at Index 3 */

    index = 3; 
    Console.WriteLine("Element at index " + 
                            index + " is " +
                            getElement(arr, index)); 
} 
}

/* C# code to demonstrate Range Update and 
* Point Queries on a Binary Index Tree. 
* This method only works when all array 
* values are initially 0.*/
using System;
public class GFG
{

/*    Max tree size */

    public const int MAX = 1000;
    public static int[] BITree = new int[MAX];

/*    Updates a node in Binary Index 
    Tree (BITree) at given index 
    in BITree. The given value 'val' 
    is added to BITree[i] and 
    all of its ancestors in tree. */

    public static void updateBIT(int n, int index, int val)
    {

/*        index in BITree[] is 1  
        more than the index in arr[] */

        index = index + 1;

/*        Traverse all ancestors  
        and add 'val' */

        while (index <= n)
        {

/*            Add 'val' to current  
            node of BITree */

            BITree[index] += val;

/*            Update index to that  
            of parent in update View */

            index += index & (-index);
        }
    }

/*    Constructs Binary Indexed Tree  
    for given array of size n. */

    public static void constructBITree(int[] arr, int n)
    {

/*        Initialize BITree[] as 0 */

        for (int i = 1; i <= n; i++)
        {
            BITree[i] = 0;
        }

/*        Store the actual values  
        in BITree[] using update() */

        for (int i = 0; i < n; i++)
        {
            updateBIT(n, i, arr[i]);
        }

    }

/*    SERVES THE PURPOSE OF getElement() 
    Returns sum of arr[0..index]. This  
    function assumes that the array is 
    preprocessed and partial sums of 
    array elements are stored in BITree[] */

    public static int getSum(int index)
    {

/*Initialize result*/

int sum = 0;

/*        index in BITree[] is 1 more  
        than the index in arr[] */

        index = index + 1;

/*        Traverse ancestors 
        of BITree[index] */

        while (index > 0)
        {

/*            Add current element  
            of BITree to sum */

            sum += BITree[index];

/*            Move index to parent  
            node in getSum View */

            index -= index & (-index);
        }

/*        Return the sum */

        return sum;
    }

/*    Updates such that getElement()  
    gets an increased value when  
    queried from l to r. */

    public static void update(int l, int r, int n, int val)
    {

/*        Increase value at  
        'l' by 'val' */

        updateBIT(n, l, val);

/*        Decrease value at 
        'r+1' by 'val' */

        updateBIT(n, r + 1, -val);
    }

/*    Driver Code */

    public static void Main(string[] args)
    {
        int[] arr = new int[] {0, 0, 0, 0, 0};
        int n = arr.Length;
        constructBITree(arr,n);

/*        Add 2 to all the 
        element from [2,4] */

        int l = 2, r = 4, val = 2;
        update(l, r, n, val);

/*    Find the element at Index 4*/

        int index = 4;
        Console.WriteLine("Element at index " + index + " is " + getSum(index));

/*        Add 2 to all the  
        element from [0,3] */

        l = 0;
        r = 3;
        val = 4;
        update(l, r, n, val);

/*        Find the element 
        at Index 3 */

        index = 3;
        Console.WriteLine("Element at index " + index + " is " + getSum(index));
    }
}

/*C# program to create a custom tree 
from a given set of links.The main class that represents tree 
and has main method*/

using System;
class Tree
{
    public TreeNode root;

/* Returns an array of trees from links input.  
    Links are assumed to be Strings of the form 
    "<s> <e>" where <s> and <e> are starting and 
    ending points for the link. The returned array is
    of size 26 and has non-null values at indexes 
    corresponding to roots of trees in output */

    public Tree[] buildFromLinks(String [] links) 
    {

/*        Create two arrays for nodes and forest*/

        TreeNode[] nodes = new TreeNode[26]; 
        Tree[] forest = new Tree[26];

/*        Process each link */

        foreach (String link in links) 
        {
            char []sep = {' ',' '};

/*            Find the two ends of current link*/

            String[] ends = link.Split(sep);

/*Start node*/

int start = (int) (ends[0][0] - 'a');

/*End node             */

int end = (int) (ends[1][0] - 'a');

/*            If start of link not seen before, 
            add it two both arrays*/

            if (nodes[start] == null) 
            {             
                nodes[start] = new TreeNode((char) (start + 'a'));

/*                Note that it may be removed later when 
                this character is last character of a link. 
                For example, let we first see a--->b, 
                then c--->a. We first add 'a' to array 
                of trees and when we see link c--->a,
                we remove it from trees array.*/

                forest[start] = new Tree(nodes[start]);                                         
            }

/*            If end of link is not seen before, 
            add it to the nodes array*/

            if (nodes[end] == null)                             
                nodes[end] = new TreeNode((char) (end + 'a'));

/*            If end of link is seen before, 
            remove it from forest if it exists there.*/

            else forest[end] = null;

/*            Establish Parent-Child Relationship
            between Start and End*/

            nodes[start].addChild(nodes[end], end);
        }     
        return forest;
    }

/*    Constructor */

    public Tree(TreeNode root) { this.root = root; } 
    public static void printForest(String[] links)
    {
        Tree t = new Tree(new TreeNode('\0'));
        foreach (Tree t1 in t.buildFromLinks(links)) 
        {
            if (t1 != null) 
            { 
                t1.root.printTreeIdented("");
                Console.WriteLine("");
            } 
        }
    }

/*    Driver Code*/

    public static void Main(String[] args) {
        String [] links1 = {"a b", "b c", "b d", "a e"};
        Console.WriteLine("------------ Forest 1 ----------------");
        printForest(links1);     
        String [] links2 = {"a b", "a g", "b c", "c d", "d e",
                            "c f", "z y", "y x", "x w"};
        Console.WriteLine("------------ Forest 2 ----------------");
        printForest(links2);     
    }
}

/*Class to represent a tree node*/

public class TreeNode 
{ 
    TreeNode []children;
    char c;

/*    Adds a child 'n' to this node*/

    public void addChild(TreeNode n, int index) 
    { 
        this.children[index] = n;
    }

/*    Constructor*/

    public TreeNode(char c)
    { 
        this.c = c; this.children = new TreeNode[26];
    }

/*    Recursive method to print indented tree
    rooted with this node.*/

    public void printTreeIdented(String indent) 
    {     
        Console.WriteLine(indent + "-->" + c);
        foreach (TreeNode child in children)
        {
            if (child != null) 
                child.printTreeIdented(indent + " |");
        }     
    } 
}

/*An iterative C# program to solve tree isomorphism problem */
using System;

/* A binary tree node has data, pointer to left and right children */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right;
    }
}
public class BinaryTree
{
    public Node root1, root2;

/* Given a binary tree, print its nodes in reverse level order */

    public virtual bool isIsomorphic(Node n1, Node n2)
    {

/*        Both roots are NULL, trees isomorphic by definition */

        if (n1 == null && n2 == null)
        {
            return true;
        }

/*        Exactly one of the n1 and n2 is NULL, trees not isomorphic */

        if (n1 == null || n2 == null)
        {
            return false;
        }
        if (n1.data != n2.data)
        {
            return false;
        }

/*        There are two possible cases for n1 and n2 to be isomorphic 
        Case 1: The subtrees rooted at these nodes have NOT been 
        "Flipped". 
        Both of these subtrees have to be isomorphic. 
        Case 2: The subtrees rooted at these nodes have been "Flipped" */

        return (isIsomorphic(n1.left, n2.left)
        && isIsomorphic(n1.right, n2.right)) 
        || (isIsomorphic(n1.left, n2.right)
        && isIsomorphic(n1.right, n2.left));
    }

/*    Driver program to test above functions */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create trees shown in above diagram */

        tree.root1 = new Node(1);
        tree.root1.left = new Node(2);
        tree.root1.right = new Node(3);
        tree.root1.left.left = new Node(4);
        tree.root1.left.right = new Node(5);
        tree.root1.right.left = new Node(6);
        tree.root1.left.right.left = new Node(7);
        tree.root1.left.right.right = new Node(8);
        tree.root2 = new Node(1);
        tree.root2.left = new Node(3);
        tree.root2.right = new Node(2);
        tree.root2.right.left = new Node(4);
        tree.root2.right.right = new Node(5);
        tree.root2.left.right = new Node(6);
        tree.root2.right.right.left = new Node(8);
        tree.root2.right.right.right = new Node(7);
        if (tree.isIsomorphic(tree.root1, tree.root2) == true)
        {
            Console.WriteLine("Yes");
        }
        else
        {
            Console.WriteLine("No");
        }
    }
}

/*C# program to count number of ways
to color a N node skewed tree with
k colors such that parent and
children  have different colors*/

using System;
class GFG {

/*    fast_way is recursive
    method to calculate power*/

    static int fastPow(int N, int K)
    {
        if (K == 0)
            return 1;
        int temp = fastPow(N, K / 2);
        if (K % 2 == 0)
            return temp * temp;
        else
            return N * temp * temp;
    }
    static int countWays(int N, int K)
    {
        return K * fastPow(K - 1, N - 1);
    }

/*    Driver code*/

    public static void Main()
    {
        int N = 3, K = 3;
        Console.WriteLine(countWays(N, K));
    }
}

/*C# code to delete all leaves with given 
value.*/

using System;
class GfG 
{

/*    A binary tree node */

    class Node 
    { 
        public int data; 
        public Node left, right; 
    }

/*    A utility function to allocate a new node */

    static Node newNode(int data) 
    { 
        Node newNode = new Node(); 
        newNode.data = data; 
        newNode.left = null;
        newNode.right = null; 
        return (newNode); 
    }

/*deleteleaves()*/

    static Node deleteLeaves(Node root, int x) 
    { 
        if (root == null) 
            return null; 
        root.left = deleteLeaves(root.left, x); 
        root.right = deleteLeaves(root.right, x); 
        if (root.data == x && 
            root.left == null && 
            root.right == null) 
        { 
            return null; 
        } 
        return root; 
    }

/*inorder()*/

    static void inorder(Node root) 
    { 
        if (root == null) 
            return; 
        inorder(root.left); 
        Console.Write(root.data + " "); 
        inorder(root.right); 
    }

/*    Driver code */

    public static void Main(String[] args) 
    { 
        Node root = newNode(10); 
        root.left = newNode(3); 
        root.right = newNode(10); 
        root.left.left = newNode(3); 
        root.left.right = newNode(1); 
        root.right.right = newNode(3); 
        root.right.right.left = newNode(3); 
        root.right.right.right = newNode(3); 
        deleteLeaves(root, 3); 
        Console.Write("Inorder traversal after deletion : "); 
        inorder(root); 
    }
}

/* Non-recursive program to delete the entire binary tree */

using System;
using System.Collections.Generic;

/*A binary tree node*/

public class Node 
{
    public int data;
    public Node left, right;
    public Node(int data) 
    {
        this.data = data;
        left = right = null;
    }
}
public class BinaryTree 
{
    Node root;

/* Non-recursive function to
    delete an entire binary tree. */

    void _deleteTree() 
    {

/*        Base Case*/

        if (root == null)
            return;

/*        Create an empty queue for level order traversal*/

        Queue<Node> q = new Queue<Node>();

/*        Do level order traversal starting from root*/

        q.Enqueue(root);
        while (q.Count != 0) 
        {
            Node node = q.Peek();
            q.Dequeue();
            if (node.left != null)
                q.Enqueue(node.left);
            if (node.right != null)
                q.Enqueue(node.right);
        }
    }

/* Deletes a tree and sets the root as NULL */

