/*C# programn to calculate
Size of a tree*/

using System;
using System.Collections.Generic;

/*Node Structure*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*return size of tree*/

public class BinaryTree
{
    Node root;
    public int size()
    {

/*    if tree is empty it will
    return 0*/

        if (root == null)
            return 0;

/*        Using level order Traversal.*/

        Queue<Node> q = new Queue<Node>();
        q.Enqueue(root);
        int count = 1; 
        while (q.Count != 0)
        {
            Node tmp = q.Dequeue();

/*            when the queue is empty:
            the poll() method returns null.*/

            if (tmp != null)
            {
                if (tmp.left != null)
                {

/*                    Increment count*/

                    count++;

/*                    Enqueue left child */

                    q.Enqueue(tmp.left);
                }
                if (tmp.right != null)
                {

/*                    Increment count*/

                    count++;

/*            Enqueue right child */


                    q.Enqueue(tmp.right);
                }
            }
        }
        return count;
    }

/*    Driver code*/

    public static void Main(String []args)
    {

/* creating a binary tree and entering 
        the nodes */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        Console.WriteLine("The size of binary tree" + 
                        " is : " + tree.size());
    }
}

/*C# program to find height of tree*/

using System;

/*A binary tree node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    Node root;

/* Compute the "maxDepth" of a tree -- the number of
    nodes along the longest path from the root node
    down to the farthest leaf node.*/

    int maxDepth(Node node)
    {
        if (node == null)
            return 0;
        else
        {

/* compute the depth of each subtree */

            int lDepth = maxDepth(node.left);
            int rDepth = maxDepth(node.right);

/* use the larger one */

            if (lDepth > rDepth)
                return (lDepth + 1);
            else
                return (rDepth + 1);
        }
    }

/* Driver code */

    public static void Main(String[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        Console.WriteLine("Height of tree is : " +
                                    tree.maxDepth(tree.root));
    }
}

/* C# Program to find height of the tree considering 
only even level leaves. */

using System;
class GfG
{

/* A binary tree node has data, pointer to 
    left child and a pointer to right child */

    class Node
    { 
        public int data; 
        public Node left; 
        public Node right; 
    } 
    static int heightOfTreeUtil(Node root,
                               bool isEven) 
    {

/*        Base Case */

        if (root == null) 
            return 0; 
        if (root.left == null && 
            root.right == null)
        { 
            if (isEven == true) 
                return 1; 
            else
                return 0; 
        }

/*left stores the result of left subtree, 
        and right stores the result of right subtree*/

        int left = heightOfTreeUtil(root.left, !isEven); 
        int right = heightOfTreeUtil(root.right, !isEven);

/*If both left and right returns 0, it means 
        there is no valid path till leaf node*/

        if (left == 0 && right == 0) 
            return 0; 
        return (1 + Math.Max(left, right)); 
    }

/* Helper function that allocates a new node with the 
    given data and NULL left and right pointers. */

    static Node newNode(int data) 
    { 
        Node node = new Node(); 
        node.data = data; 
        node.left = null; 
        node.right = null; 
        return (node); 
    } 
    static int heightOfTree(Node root) 
    { 
        return heightOfTreeUtil(root, false); 
    }

/* Driver code*/

    public static void Main(String[] args) 
    {

/*        Let us create binary tree
        shown in above diagram */

        Node root = newNode(1); 
        root.left = newNode(2); 
        root.right = newNode(3); 
        root.left.left = newNode(4); 
        root.left.right = newNode(5); 
        root.left.right.left = newNode(6); 
        Console.WriteLine("Height of tree is " +
                            heightOfTree(root)); 
    } 
}

/*C# program to find height using parent array*/

using System;
public class BinaryTree
{

/*    This function fills depth of i'th element in parent[].  The depth is
    filled in depth[i].*/

    public virtual void fillDepth(int[] parent, int i, int[] depth)
    {

/*        If depth[i] is already filled*/

        if (depth[i] != 0)
        {
            return;
        }

/*        If node at index i is root*/

        if (parent[i] == -1)
        {
            depth[i] = 1;
            return;
        }

/*        If depth of parent is not evaluated before, then evaluate
        depth of parent first*/

        if (depth[parent[i]] == 0)
        {
            fillDepth(parent, parent[i], depth);
        }

/*        Depth of this node is depth of parent plus 1*/

        depth[i] = depth[parent[i]] + 1;
    }

/*    This function returns height of binary tree represented by
    parent array*/

    public virtual int findHeight(int[] parent, int n)
    {

/*        Create an array to store depth of all nodes/ and
        initialize depth of every node as 0 (an invalid
        value). Depth of root is 1*/

        int[] depth = new int[n];
        for (int i = 0; i < n; i++)
        {
            depth[i] = 0;
        }

/*        fill depth of all nodes*/

        for (int i = 0; i < n; i++)
        {
            fillDepth(parent, i, depth);
        }

/*        The height of binary tree is maximum of all depths.
        Find the maximum value in depth[] and assign it to ht.*/

        int ht = depth[0];
        for (int i = 1; i < n; i++)
        {
            if (ht < depth[i])
            {
                ht = depth[i];
            }
        }
        return ht;
    }

/*    Driver program to test above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/*        int parent[] = {1, 5, 5, 2, 2, -1, 3};*/

        int[] parent = new int[]{-1, 0, 0, 1, 1, 3, 5};
        int n = parent.Length;
        Console.WriteLine("Height is  " + tree.findHeight(parent, n));
    }
}

/* C# program to determine if binary tree is
height balanced or not */

using System;

/* A binary tree node has data, pointer to left child,
and a pointer to right child */

public class Node {
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
public class BinaryTree {
    public Node root;

/* Returns true if binary tree with root as
    root is height-balanced */

    public virtual bool isBalanced(Node node)
    {

/*for height of left subtree*/

int lh;

/*for height of right subtree*/

int rh;

/* If tree is empty then return true */

        if (node == null) {
            return true;
        }

/* Get the height of left and right sub trees */

        lh = height(node.left);
        rh = height(node.right);
        if (Math.Abs(lh - rh) <= 1 && isBalanced(node.left)
            && isBalanced(node.right)) {
            return true;
        }

/* If we reach here then tree is not height-balanced */

        return false;
    }

/* The function Compute the "height" of a tree. Height is the
        number of nodes along the longest path from the root node
        down to the farthest leaf node.*/

    public virtual int height(Node node)
    {

/* base case tree is empty */

        if (node == null) {
            return 0;
        }

/* If tree is not empty then height = 1 + max of left
        height and right heights */

        return 1 + Math.Max(height(node.left), height(node.right));
    }

/*Driver code*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.left.left.left = new Node(8);
        if (tree.isBalanced(tree.root)) {
            Console.WriteLine("Tree is balanced");
        }
        else {
            Console.WriteLine("Tree is not balanced");
        }
    }
}

/*C# implementation to calculate height of a special tree
whose leaf nodes forms a circular doubly linked list*/

using System;

/*User defined node class*/

public class Node {
    public int data;
    public Node left, right;

/*    Constructor to create a new tree node*/

    public Node(int key)
    {
        data = key;
        left = right = null;
    }
}
public class GFG {

/*    function to check if given node is a leaf node or
    node*/

    static bool isLeaf(Node node)
    {

/*        If given node's left's right is pointing to given
        node and its right's left is pointing to the node
        itself then it's a leaf*/

        return (node.left != null && node.left.right == node
                && node.right != null
                && node.right.left == node);
    }

/* Compute the height of a tree -- the number of
    Nodes along the longest path from the root node
    down to the farthest leaf node.*/

    static int maxDepth(Node node)
    {

/*        if node is NULL, return 0*/

        if (node == null)
            return 0;

/*        if node is a leaf node, return 1*/

        if (isLeaf(node))
            return 1;

/*        compute the depth of each subtree and take
        maximum*/

        return 1
            + Math.Max(maxDepth(node.left),
                       maxDepth(node.right));
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.left.left.left = new Node(6);

/*        Given tree contains 3 leaf nodes*/

        Node L1 = root.left.left.left;
        Node L2 = root.left.right;
        Node L3 = root.right;

/*        create circular doubly linked list out of
        leaf nodes of the tree
        set next pointer of linked list*/

        L1.right = L2;
        L2.right = L3;
        L3.right = L1;

/*        set prev pointer of linked list*/

        L3.left = L2;
        L2.left = L1;
        L1.left = L3;

/*        calculate height of the tree*/

        Console.WriteLine("Height of tree is "
                          + maxDepth(root));
    }
}

/*Recursive optimized C# program to find the diameter of
a Binary Tree*/

/*Class containing left and right child of current
node and key value*/

using System;
namespace Tree
{
  class Tree<T>
    {
        public Tree(T value)
        {
            this.value = value;
        }
        public T value { get; set; }
        public Tree<T> left { get; set; }
        public Tree<T> right { get; set; }
    }

/*Class to print the Diameter*/

    public class TreeDiameter
    {
        Tree<int> root;

/*        The function Compute the "height" of a tree. Height
        is the number of nodes along the longest path from the
        root node down to the farthest leaf node.*/

        int Height(Tree<int> node)
        {

/*    base case tree is empty*/

            if (node == null) return 0;

/*    If tree is not empty then height = 1 + max of left
    height and right heights*/

            return 1 + Math.Max(Height(node.left),
                                Height(node.right));
        }

/*Function to get diameter of a binary tree*/

        int Diameter(Tree<int> root)
        {

/*    base case where tree is empty*/

            if (root == null) return 0;

/*            get the height of left and right sub-trees*/

            int lHeight = Height(root.left);
            int rHeight = Height(root.right);

/*            get the diameter of left and right sub-trees*/

            int lDiameter = Diameter(root.left);
            int rDiameter = Diameter(root.right);

/*            Return max of following three
          1) Diameter of left subtree
          2) Diameter of right subtree
          3) Height of left subtree + height of right subtree + 1        */

            return Math.Max(lHeight + rHeight + 1,
                            Math.Max(lDiameter, rDiameter));
        }

/*        A wrapper over diameter(Node root)*/

        int Diameter() { return Diameter(root); }

/*        Driver Code*/

        public static void Main(string[] args)
        {

/*            creating a binary tree and entering the nodes*/

            TreeDiameter tree = new TreeDiameter();
            tree.root = new Tree<int>(1);
            tree.root.left = new Tree<int>(2);
            tree.root.right = new Tree<int>(3);
            tree.root.left.left = new Tree<int>(4);
            tree.root.left.right = new Tree<int>(5);

/*    Function Call*/

            Console.WriteLine($"The diameter of given binary tree is : {tree.Diameter()}");
        }
    }
}

/*Recursive C# program to find the diameter of a
Binary Tree*/

using System;
using System.Collections.Generic;

/*Class containing left and right child of current
node and key value*/

class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*A utility class to pass heigh object*/

class Height {
    public int h;
}

/*Class to print the Diameter*/

class BinaryTree {
    public Node root;

/*    define height =0 globally and  call
    diameterOpt(root,height) from main*/

    public int diameterOpt(Node root, Height height)
    {

/*        lh --> Height of left subtree
        rh --> Height of right subtree*/

        Height lh = new Height(), rh = new Height();

/*    base condition- when binary tree is empty*/

        if (root == null) {
            height.h = 0;

/*diameter is also 0*/

return 0; 
        }

/*        ldiameter  --> diameter of left subtree
        rdiameter  --> Diameter of right subtree
        Get the heights of left and right subtrees in lh and rh And store the returned values in ldiameter
                and ldiameter */

        int ldiameter = diameterOpt(root.left, lh);
        int rdiameter = diameterOpt(root.right, rh);

/*        Height of current node is max of heights of left
        and right subtrees plus 1*/

        height.h = Math.Max(lh.h, rh.h) + 1;
        return Math.Max(lh.h + rh.h + 1,
                        Math.Max(ldiameter, rdiameter));
    }

/*    A wrapper over diameter(Node root)*/

    public int diameter()
    {
        Height height = new Height();
        return diameterOpt(root, height);
    }

/*    The function Compute the "height" of a tree. Height
    is
      the number f nodes along the longest path from the
      root node down to the farthest leaf node.*/

    public int height(Node node)
    {

/*        base case tree is empty*/

        if (node == null)
            return 0;

/*        If tree is not empty then height = 1 + max of
        left height and right heights*/

        return (1
                + Math.Max(height(node.left),
                           height(node.right)));
    }

/*    Driver Code*/

    static void Main()
    {

/*        creating a binary tree and entering the nodes*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);

/*        Function Call*/

        Console.Write("The diameter of given binary tree is : " + tree.diameter());
    }
}

/*Simple C# program to find diameter
of a binary tree.*/

using System;
class GfG
{

/* Tree node structure used in the program */

class Node
{
    public int data;
    public Node left, right;
}
class A
{
    public int ans = int.MinValue;
}

/* Function to find height of a tree */

static int height(Node root, A a)
{
    if (root == null)
        return 0;
    int left_height = height(root.left, a);
    int right_height = height(root.right, a);

/*    update the answer, because diameter of a
    tree is nothing but maximum value of
    (left_height + right_height + 1) for each node*/

    a.ans = Math.Max(a.ans, 1 + left_height +
                    right_height);
    return 1 + Math.Max(left_height, right_height);
}

/* Computes the diameter of binary
tree with given root. */

static int diameter(Node root)
{
    if (root == null)
        return 0;

/*    This will store the final answer*/

    A a = new A();
    int height_of_tree = height(root, a);
    return a.ans;
}

/*A utility function to
create a new Binary Tree Node*/

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = null;
    node.right = null;
    return (node);
}

/*Driver code*/

public static void Main()
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    Console.WriteLine("Diameter is " + diameter(root));
}
}

/*C# program to construct tree for 
given count width and height.*/

using System;
class GfG
{

/*    Function to construct the tree*/

    static void constructTree(int n, int d, int h)
    {
        if (d == 1)
        {

/*            Special case when d == 2,
            only one edge*/

            if (n == 2 && h == 1)
            {
                Console.WriteLine("1 2");
                return;
            }

/*            Tree is not possible*/

            Console.WriteLine("-1");
            return;
        }
        if (d > 2 * h)
        {
            Console.WriteLine("-1");
            return;
        }

/*        Satisfy the height condition
        by add edges up to h*/

        for (int i = 1; i <= h; i++)
            Console.WriteLine(i + " " + (i + 1));
        if (d > h)
        {

/*            Add d - h edges from 1 to
            satisfy diameter condition*/

            Console.WriteLine("1" + " " + (h + 2));
            for (int i = h + 2; i <= d; i++)
            {
                Console.WriteLine(i + " " + (i + 1));
            }
        }

/*        Remaining edges at vertex 1 or 2(d == h)*/

        for (int i = d + 1; i < n; i++)
        {
            int k = 1;
            if (d == h)
                k = 2;
            Console.WriteLine(k + " " + (i + 1));
        }
    }

