    }
}

/*C# program to find deepest right leaf
node of binary tree*/

using System;
using System.Collections.Generic; 
class GFG
{

/*tree node*/

public class Node 
{
    public int data;
    public Node left, right;
};

/*returns a new tree Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*return the deepest right leaf node
of binary tree*/

static Node getDeepestRightLeafNode(Node root)
{
    if (root == null)
        return null;

/*    Create a queue for level order traversal*/

    Queue<Node> q = new Queue<Node>();
    q.Enqueue(root);
    Node result = null;

/*    Traverse until the queue is empty*/

    while (q.Count!=0) 
    {
        Node temp = q.Peek();
        q.Dequeue();
        if (temp.left != null)
        {
            q.Enqueue(temp.left);
        }

/*        Since we go level by level, the last 
        stored right leaf node is deepest one */

        if (temp.right != null)
        {
            q.Enqueue(temp.right);
            if (temp.right.left == null && temp.right.right == null)
                result = temp.right;
        }
    }
    return result;
}

/*Driver code*/

public static void Main(String[] args) 
{

/*    construct a tree*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.right = newNode(4);
    root.right.left = newNode(5);
    root.right.right = newNode(6);
    root.right.left.right = newNode(7);
    root.right.right.right = newNode(8);
    root.right.left.right.left = newNode(9);
    root.right.right.right.right = newNode(10);
    Node result = getDeepestRightLeafNode(root);
    if (result != null)
        Console.WriteLine("Deepest Right Leaf Node :: "
            + result.data);
    else
        Console.WriteLine("No result, right leaf not found\n");
}
}

/*C# program to find depth of the deepest 
odd level node */

using System;
class GfG 
{

/*    A Tree node */

    class Node 
    { 
        public int key; 
        public Node left, right; 
    }

/*    Utility function to create a new node */

    static Node newNode(int key) 
    { 
        Node temp = new Node(); 
        temp.key = key; 
        temp.left = null;
        temp.right = null; 
        return (temp); 
    }

/*    Utility function which 
    returns whether the current node 
    is a leaf or not */

    static bool isleaf(Node curr_node) 
    { 
        return (curr_node.left == null && 
                curr_node.right == null); 
    }

/*    function to return the longest 
    odd level depth if it exists 
    otherwise 0 */

    static int deepestOddLevelDepthUtil(Node curr_node,
                                        int curr_level) 
    {

/*        Base case 
        return from here */

        if ( curr_node == null) 
            return 0;

/*        increment current level */

        curr_level += 1;

/*        if curr_level is odd 
        and its a leaf node */

        if ( curr_level % 2 != 0 && isleaf(curr_node)) 
            return curr_level; 
        return Math.Max(deepestOddLevelDepthUtil(curr_node.left,curr_level), 
                    deepestOddLevelDepthUtil(curr_node.right,curr_level)); 
    }

/*    A wrapper over deepestOddLevelDepth() */

    static int deepestOddLevelDepth(Node curr_node) 
    { 
        return deepestOddLevelDepthUtil(curr_node, 0); 
    } 
    public static void Main(String[] args) 
    {

/* 10 
        / \ 
        28 13 
                / \ 
            14 15 
                    / \ 
                    23 24 
        Let us create Binary Tree shown in above example */

        Node root = newNode(10); 
        root.left = newNode(28); 
        root.right = newNode(13); 
        root.right.left = newNode(14); 
        root.right.right = newNode(15); 
        root.right.right.left = newNode(23); 
        root.right.right.right = newNode(24); 
        Console.WriteLine(deepestOddLevelDepth(root)); 
    }
}

/*C# program to find depth of deepest odd level node */
using System;

/*A binary tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root;

/*    A recursive function to find depth of the deepest odd level leaf */

    public virtual int depthOfOddLeafUtil(Node node, int level)
    {

/*        Base Case */

        if (node == null)
        {
            return 0;
        }

/*        If this node is a leaf and its level is odd, return its level */

        if (node.left == null && node.right == null && (level & 1) != 0)
        {
            return level;
        }

/*        If not leaf, return the maximum value from left and right subtrees */

        return Math.Max(depthOfOddLeafUtil(node.left, level + 1),
                        depthOfOddLeafUtil(node.right, level + 1));
    }

/* Main function which calculates the depth of deepest odd level leaf. 
    This function mainly uses depthOfOddLeafUtil() */

    public virtual int depthOfOddLeaf(Node node)
    {
        int level = 1, depth = 0;
        return depthOfOddLeafUtil(node, level);
    }

/*Driver Code*/

    public static void Main(string[] args)
    {
        int k = 45;
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.right.left = new Node(5);
        tree.root.right.right = new Node(6);
        tree.root.right.left.right = new Node(7);
        tree.root.right.right.right = new Node(8);
