/*C# program to find depth of the deepest
odd level leaf node of binary tree*/

using System;
using System.Collections.Generic;
class GFG 
{

/*tree node*/

public class Node 
{
    public int data;
    public Node left, right;
};

/*returns a new tree Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*return max odd number depth of leaf node*/

static int maxOddLevelDepth(Node root)
{
    if (root == null)
        return 0;

/*    create a queue for level order 
    traversal*/

    Queue<Node> q = new Queue<Node>();
    q.Enqueue(root);
    int result = int.MaxValue;
    int level = 0;

/*    traverse until the queue is empty*/

    while (q.Count != 0) 
    {
        int size = q.Count;
        level += 1;

/*        traverse for complete level*/

        while(size > 0)
        {
            Node temp = q.Peek();
            q.Dequeue();

/*            check if the node is leaf node and 
            level is odd if level is odd,
            then update result*/

            if(temp.left == null && 
               temp.right == null &&
              (level % 2 != 0))
            {
                result = level;
            }

/*            check for left child*/

            if (temp.left != null) 
            {
                q.Enqueue(temp.left);
            }

/*            check for right child*/

            if (temp.right != null)
            {
                q.Enqueue(temp.right);
            }
            size -= 1;
        } 
    }
    return result;
}

/*Driver Code*/

public static void Main(String[] args)
{

/*    construct a tree*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.right.left = newNode(5);
    root.right.right = newNode(6);
    root.right.left.right = newNode(7);
    root.right.right.right = newNode(8);
    root.right.left.right.left = newNode(9);
    root.right.right.right.right = newNode(10);
    root.right.right.right.right.left = newNode(11);
    int result = maxOddLevelDepth(root);
    if (result == int.MaxValue)
        Console.WriteLine("No leaf node at odd level");
    else
    {
        Console.Write(result);
        Console.WriteLine(" is the required depth ");
    }
}
}

/*C# program to find value of the deepest node
in a given binary tree*/

using System;
class GFG
{

/*    A tree node*/

    public class Node
    {
        public int data;
        public Node left, right;
        public Node(int key)
        {
            data = key;
            left = null;
            right = null;
        }
    }
    static int maxLevel = -1;
    static int res = -1;

/*    maxLevel : keeps track of maximum level seen so far.
    res : Value of deepest node so far.
    level : Level of root*/

    static void find(Node root, int level)
    {
        if (root != null)
        {
            find(root.left, ++level);

/*            Update level and resue*/

            if (level > maxLevel)
            {
                res = root.data;
                maxLevel = level;
            }
            find(root.right, level);
        }
    }

/*    Returns value of deepest node*/

    static int deepestNode(Node root)
    {

/*        Initialze result and max level*/

        int res = -1;
        int maxLevel = -1;

/*        Updates value "res" and "maxLevel"
        Note that res and maxLen are passed
        by reference.*/

        find(root, 0);
        return res;
    }

