/*C# program to find deepest left leaf
node of binary tree*/

using System;
using System.Collections.Generic;
class GFG 
{

/*tree node*/

class Node
{
    public int data;
    public Node left, right;
};

/*returns a new tree Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*return the deepest left leaf node
of binary tree*/

static Node getDeepestLeftLeafNode(Node root)
{
    if (root == null)
        return null;

/*    create a queue for level order traversal*/

    Queue<Node> q = new Queue<Node>();
    q.Enqueue(root);
    Node result = null;

/*    traverse until the queue is empty*/

    while (q.Count != 0) 
    {
        Node temp = q.Peek();
        q.Dequeue();

/*        Since we go level by level, the last 
        stored left leaf node is deepest one,*/

        if (temp.left != null) 
        {
            q.Enqueue(temp.left);
            if (temp.left.left == null &&
                temp.left.right == null)
                result = temp.left;
        }
        if (temp.right != null)
            q.Enqueue(temp.right);
    }
    return result;
}

/*Driver Code*/

public static void Main(String[] args)
{

/*    construct a tree*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.right.left = newNode(5);
    root.right.right = newNode(6);
    root.right.left.right = newNode(7);
    root.right.right.right = newNode(8);
    root.right.left.right.left = newNode(9);
    root.right.right.right.right = newNode(10);
    Node result = getDeepestLeftLeafNode(root);
    if (result != null)
        Console.WriteLine("Deepest Left Leaf Node :: " + 
                                           result.data);
    else
        Console.WriteLine("No result, " + 
                  "left leaf not found");
    }
}

/*A C# program to find 
the deepest left leaf 
in a binary tree */

using System;

/*A Binary Tree node */

public class Node
{
    public int data;
    public Node left, right;

/*    Constructor */

    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}

/*Class to evaluate pass 
by reference */

public class Level
{

/*    maxlevel: gives the 
    value of level of 
    maximum left leaf */

    public int maxlevel = 0;
}
public class BinaryTree
{
    public Node root;

/*    Node to store resultant 
    node after left traversal */

    public Node result;

/*    A utility function to 
    find deepest leaf node. 
    lvl: level of current node. 
    isLeft: A bool indicate 
    that this node is left child */

    public virtual void deepestLeftLeafUtil(Node node, int lvl, 
                                        Level level, bool isLeft)
    {

/*        Base case */

        if (node == null)
        {
            return;
        }

/*        Update result if this node 
        is left leaf and its level 
        is more than the maxl level 
        of the current result */

        if (isLeft != false && node.left == null && node.right == null
                            && lvl > level.maxlevel)
        {
            result = node;
            level.maxlevel = lvl;
        }

/*        Recur for left and right subtrees */

        deepestLeftLeafUtil(node.left, lvl + 1, level, true);
        deepestLeftLeafUtil(node.right, lvl + 1, level, false);
    }

/*    A wrapper over deepestLeftLeafUtil(). */

    public virtual void deepestLeftLeaf(Node node)
    {
        Level level = new Level();
        deepestLeftLeafUtil(node, 0, level, false);
    }

/*    Driver program to test above functions */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.right.left = new Node(5);
