        {
            Console.WriteLine("The deepest left child is " + tree.result.data);
        }
        else
        {
            Console.WriteLine("There is no left leaf in the given tree");
        }
    }
}

/* C# implementation to find minimum depth
   of a given Binary tree */

using System;

/* Class containing left and right child of current
node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{

/*    Root of the Binary Tree*/

    public Node root;
    public virtual int minimumDepth()
    {
        return minimumDepth(root);
    }

/* Function to calculate the minimum depth of the tree */

    public virtual int minimumDepth(Node root)
    {

/*        Corner case. Should never be hit unless the code is
        called on root = NULL*/

        if (root == null)
        {
            return 0;
        }

/*        Base case : Leaf Node. This accounts for height = 1.*/

        if (root.left == null && root.right == null)
        {
            return 1;
        }

/*        If left subtree is NULL, recur for right subtree*/

        if (root.left == null)
        {
            return minimumDepth(root.right) + 1;
        }

/*        If right subtree is NULL, recur for left subtree*/

        if (root.right == null)
        {
            return minimumDepth(root.left) + 1;
        }
        return Math.Min(minimumDepth(root.left), minimumDepth(root.right)) + 1;
    }

/* Driver program to test above functions */

    public static void Main(string[] args)
    {

/*    Let us construct the Tree shown in the above figure*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        Console.WriteLine("The minimum depth of binary tree is : " + tree.minimumDepth());
    }
}

/*C# program to find minimum depth
of a given Binary Tree*/

using System;
using System.Collections.Generic;
class GFG
{

/*A binary Tree node*/

public class Node
{
    public int data;
    public Node left, right;
}

/*A queue item (Stores pointer to
node and an integer)*/

public class qItem
{
    public Node node;
    public int depth;
    public qItem(Node node, int depth)
    {
        this.node = node;
        this.depth = depth;
    }
}

/*Iterative method to find
minimum depth of Binary Tree*/

static int minDepth(Node root)
{

/*    Corner Case*/

    if (root == null)
        return 0;

/*    Create an empty queue for
    level order traversal*/

    Queue<qItem> q = new Queue<qItem>();

/*    Enqueue Root and initialize depth as 1*/

    qItem qi = new qItem(root, 1);
    q.Enqueue(qi);

/*    Do level order traversal*/

    while (q.Count != 0)
    {

/*        Remove the front queue item*/

        qi = q.Peek();
        q.Dequeue();

/*        Get details of the remove item*/

        Node node = qi.node;
        int depth = qi.depth;

/*        If this is the first leaf node
        seen so far.
        Then return its depth as answer*/

        if (node.left == null &&
            node.right == null)
            return depth;

/*        If left subtree is not null,
        add it to queue*/

        if (node.left != null)
        {
            qi.node = node.left;
            qi.depth = depth + 1;
            q.Enqueue(qi);
        }

/*        If right subtree is not null,
        add it to queue*/

        if (node.right != null)
        {
            qi.node = node.right;
            qi.depth = depth + 1;
            q.Enqueue(qi);
        }
    }
    return 0;
}

/*Utility function to create a new tree Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver Code*/

public static void Main(String[] args)
{

/*    Let us create binary tree
    shown in above diagram*/

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    Console.WriteLine(minDepth(root));
}
}

/* C# implementation to find minimum depth
of a given Binary tree */

using System;

/* Class containing left and
right child of current
Node and key value*/

public class Node {
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class MinimumTreeHeight {

/*    Root of the Binary Tree*/

    Node root;
    int minimumDepth() { return minimumDepth(root, 0); }

/* Function to calculate the
    minimum depth of the tree */

    int minimumDepth(Node root, int level)
    {
        if (root == null)
            return level;
        level++;
        return Math.Min(minimumDepth(root.left, level),
                        minimumDepth(root.right, level));
    }

/* Driver code */

    public static void Main(String[] args)
    {
        MinimumTreeHeight tree = new MinimumTreeHeight();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        Console.WriteLine("The minimum depth of "
                          + "binary tree is : "
                          + tree.minimumDepth());
    }
}

