            int rHeight = height(node.right);

/* use the larger one */

            return (lHeight > rHeight) ? (lHeight + 1)
                                       : (rHeight + 1);
        }
    }

/*    Return the maximum value from count array*/

    int getMax(int[] arr, int n)
    {
        int max = arr[0];
        int i;
        for (i = 0; i < n; i++) 
        {
            if (arr[i] > max)
                max = arr[i];
        }
        return max;
    }

/* Driver program to test above functions */

    public static void Main(String[] args)
    {

/*
        Constructed bunary tree is:
              1
            /  \
           2    3
          / \    \
         4   5    8
                 / \
                6   7 */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.right = new Node(8);
        tree.root.right.right.left = new Node(6);
        tree.root.right.right.right = new Node(7);
        Console.WriteLine("Maximum width is "
                          + tree.getMaxWidth(tree.root));
    }
}

/*C# program to print vertical width
of a tree*/

using System;
class GFG
{

/*A Binary Tree Node*/

public class Node
{
    public int data;
    public Node left, right;
};
static int maximum = 0, minimum = 0;

/*get vertical width*/

static void lengthUtil(Node root,
                        int curr)
{
    if (root == null)
        return;

/*    traverse left*/

    lengthUtil(root.left, curr - 1);

/*    if curr is decrease then get
    value in minimum*/

    if (minimum > curr)
        minimum = curr;

/*    if curr is increase then get
    value in maximum*/

    if (maximum < curr)
        maximum = curr;

/*    traverse right*/

    lengthUtil(root.right, curr + 1);
}
static int getLength(Node root)
{
    maximum = 0; minimum = 0;
    lengthUtil(root, 0);

/*    1 is added to include root in the width*/

    return (Math.Abs(minimum) + maximum) + 1;
}

/*Utility function to create a new tree node*/

static Node newNode(int data)
{
    Node curr = new Node();
    curr.data = data;
    curr.left = curr.right = null;
    return curr;
}

/*Driver Code*/

public static void Main(String[] args) 
{
    Node root = newNode(7);
    root.left = newNode(6);
    root.right = newNode(5);
    root.left.left = newNode(4);
    root.left.right = newNode(3);
    root.right.left = newNode(2);
    root.right.right = newNode(1);
    Console.WriteLine(getLength(root));
}
}

/*C# code to find the vertical width 
of a binary tree*/

using System;
using System.Collections.Generic;

/* A binary tree node has data, 
pointer to left child and a 
pointer to right child */

public class Node 
{ 
    public int data; 
    public Node left, right; 
    public Node(int item) 
    { 
        data = item; 
        left = right = null; 
    } 
} 
public class BinaryTree 
{ 
    Node root;

/*    Function to fill hd in set. */

    void fillSet(Node root, HashSet<int> set, int hd)
    {
        if(root == null) return;
        fillSet(root.left, set, hd - 1);
        set.Add(hd);
        fillSet(root.right, set, hd + 1);
    }
    int verticalWidth(Node root)
    {
        HashSet<int> set = new HashSet<int>();

/*        Third parameter is horizontal distance */

        fillSet(root,set, 0);
        return set.Count;
    }

