/*C# program to determine whether 
binary tree is level sorted or not. */

using System;
using System.Collections.Generic; 
class GFG 
{

/*Structure of a tree node. */

public class Node
{ 
    public int key; 
    public Node left, right; 
}

/*Function to create new tree node. */

static Node newNode(int key) 
{ 
    Node temp = new Node(); 
    temp.key = key; 
    temp.left = null;
    temp.right = null; 
    return temp; 
}

/*Function to determine if 
given binary tree is level sorted 
or not. */

static int isSorted(Node root) 
{

/*    to store maximum value of previous 
    level. */

    int prevMax = int.MinValue;

/*    to store minimum value of current 
    level. */

    int minval;

/*    to store maximum value of current 
    level. */

    int maxval;

/*    to store number of nodes in current 
    level. */

    int levelSize;

/*    queue to perform level order traversal. */

    Queue<Node> q = new Queue<Node> (); 
    q.Enqueue(root); 
    while (q.Count != 0) 
    {

/*        find number of nodes in current 
        level. */

        levelSize = q.Count; 
        minval = int.MaxValue; 
        maxval = int.MinValue;

/*        traverse current level and find 
        minimum and maximum value of 
        this level. */

        while (levelSize > 0)
        { 
            root = q.Peek(); 
            q.Dequeue(); 
            levelSize--; 
            minval = Math.Min(minval, root.key); 
            maxval = Math.Max(maxval, root.key); 
            if (root.left != null) 
                q.Enqueue(root.left); 
            if (root.right != null) 
                q.Enqueue(root.right); 
        }

/*        if minimum value of this level 
        is not greater than maximum 
        value of previous level then 
        given tree is not level sorted. */

        if (minval <= prevMax) 
            return 0;

/*        maximum value of this level is 
        previous maximum value for 
        next level. */

        prevMax = maxval; 
    } 
    return 1; 
}

/*Driver Code*/

public static void Main(String[] args) 
{

/* 
            1 
        / 
        4 
        \ 
            6 
        / \ 
        8 9 
        /     \ 
        12     10 
    */

    Node root = newNode(1); 
    root.left = newNode(4); 
    root.left.right = newNode(6); 
    root.left.right.left = newNode(8); 
    root.left.right.right = newNode(9); 
    root.left.right.left.left = newNode(12); 
    root.left.right.right.right = newNode(10); 
    if (isSorted(root) == 1) 
        Console.WriteLine("Sorted"); 
    else
        Console.WriteLine("Not sorted"); 
}
}

/*C# program to print Bottom View of Binary Tree*/

using System;
using System.Collections;
using System.Collections.Generic;

/*Tree node class*/

class Node
{

/*    Data of the node*/

    public int data;

/*    Horizontal distance of the node*/

    public int hd;

/*    left and right references*/

    public Node left, right;

/*    Constructor of tree node*/

    public Node(int key)
    {
        data = key;
        hd = 1000000;
        left = right = null;
    }
}

/*Tree class*/

class Tree
{

/*    Root node of tree*/

    Node root;

/*    Default constructor*/

    public Tree(){}

/*    Parameterized tree constructor*/

    public Tree(Node node)
    {
        root = node;
    }

/*    Method that prints the bottom view.*/

    public void bottomView()
    {
        if (root == null)
            return;

/*        Initialize a variable 'hd' with
        0 for the root element.*/

        int hd = 0;

/*        TreeMap which stores key value
        pair sorted on key value*/

        SortedDictionary<int,
                         int> map = new SortedDictionary<int,
                                                         int>();

/*        Queue to store tree nodes in level order
        traversal*/

        Queue queue = new Queue();

/*        Assign initialized horizontal distance
        value to root node and add it to the queue.*/

        root.hd = hd;

/*In STL, push() is used enqueue an item*/

        queue.Enqueue(root);

/*        Loop until the queue is empty
        (standard level order loop)*/

        while (queue.Count != 0)
        {
            Node temp = (Node) queue.Dequeue();

/*            Extract the horizontal distance value
            from the dequeued tree node.*/

            hd = temp.hd;

/*            Put the dequeued tree node to TreeMap
            having key as horizontal distance.
            Every time we find a node having same
            horizontal distance we need to replace
            the data in the map.*/

            map[hd] = temp.data;

/*            If the dequeued node has a left child
            add it to the queue with a horizontal
            distance hd-1.*/

            if (temp.left != null)
            {
                temp.left.hd = hd - 1;
                queue.Enqueue(temp.left);
            }

/*            If the dequeued node has a right
            child add it to the queue with a
            horizontal distance hd+1.*/

            if (temp.right != null)
            {
                temp.right.hd = hd + 1;
                queue.Enqueue(temp.right);
            }
        }

/*        Traverse the map elements using the iterator.*/

        foreach(int i in map.Values)
        {
            Console.Write(i + " ");
        }
    }
}
public class BottomView{

/*Driver code*/

public static void Main(string[] args)
{
    Node root = new Node(20);
    root.left = new Node(8);
    root.right = new Node(22);
    root.left.left = new Node(5);
    root.left.right = new Node(3);
    root.right.left = new Node(4);
    root.right.right = new Node(25);
    root.left.right.left = new Node(10);
    root.left.right.right = new Node(14);
    Tree tree = new Tree(root);
    Console.WriteLine("Bottom view of the " +
                      "given binary tree:");
    tree.bottomView();
}
}

/*C# implementation to find leaf count of a given Binary tree */

using System;

/* Class containing left and right child of current  
 node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{

/*    Root of the Binary Tree */

    public Node root;

/* Function to get the count of leaf nodes in a binary tree*/

    public virtual int LeafCount
    {
        get
        {
            return getLeafCount(root);
        }
    }
    public virtual int getLeafCount(Node node)
    {
        if (node == null)
        {
            return 0;
        }
        if (node.left == null && node.right == null)
        {
            return 1;
        }
        else
        {
            return getLeafCount(node.left) + getLeafCount(node.right);
        }
    }

