            root.left = newNode(2);
            root.right = newNode(3);
            root.left.left = newNode(4);
            root.left.right = newNode(5);

/* get leaf count of the above created tree */

            Console.WriteLine(getLeafCount(root));
        }
    }
}

/*C# Program for above approach*/

using System;

/*Node class*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
public class BinaryTree{
public static Node root;

/*Program to count leaves*/

static int countLeaves(Node node)
{

/*    If the node itself is "null"
    return 0, as there
    are no leaves*/

    if (node == null)
    {
        return 0;
    }

/*    It the node is a leaf then
    both right and left
    children will be "null"*/

    if (node.left == null &&
        node.right == null)
    {
        return 1;
    }

/*    Now we count the leaves in
    the left and right
    subtrees and return the sum*/

    return countLeaves(node.left) +
           countLeaves(node.right);
}

/*Driver Code*/

static public void Main()
{
    BinaryTree.root = new Node(1);
    BinaryTree.root.left = new Node(2);
    BinaryTree.root.right = new Node(3);
    BinaryTree.root.left.left = new Node(4);
    BinaryTree.root.left.right = new Node(5);

/*    Get leaf count of the above created tree*/

    Console.WriteLine(countLeaves(root));
}
}

/*C# program to count total number of 
non-leaf nodes in a binary tree*/

using System;
class GfG 
{

/* A binary tree node has data, pointer to 
    left child and a pointer to right child */

    class Node { 
        public int data; 
        public Node left; 
        public Node right; 
    }

/* Helper function that allocates a new node with the 
    given data and NULL left and right pointers. */

    static Node newNode(int data) 
    { 
        Node node = new Node(); 
        node.data = data; 
        node.left = null;
        node.right = null; 
        return (node); 
    }

/* Computes the number of non-leaf nodes in a tree. */

    static int countNonleaf(Node root) 
    {

/*        Base cases. */

        if (root == null || (root.left == null && 
                            root.right == null)) 
            return 0;

/*        If root is Not NULL and its one of its 
        child is also not NULL */

        return 1 + countNonleaf(root.left) + 
                    countNonleaf(root.right); 
    }

