/*Connect nodes at same level using level order 
traversal. */

using System;
using System.Collections.Generic;
public class Connect_node_same_level 
{

/*    Node class */

    class Node
    { 
        public int data; 
        public Node left, right, nextRight; 
        public Node(int data)
        { 
            this.data = data; 
            left = null; 
            right = null; 
            nextRight = null; 
        } 
    };

/*    Sets nextRight of all nodes of a tree */

    static void connect(Node root) 
    { 
        Queue<Node> q = new Queue<Node>(); 
        q.Enqueue(root);

/*        null marker to represent end of current level */

        q.Enqueue(null);

/*        Do Level order of tree using NULL markers */

        while (q.Count!=0)
        { 
            Node p = q.Peek(); 
            q.Dequeue(); 
            if (p != null)
            {

/*                next element in queue represents next 
                node at current Level */

                p.nextRight = q.Peek();

/*                push left and right children of current 
                node */

                if (p.left != null) 
                    q.Enqueue(p.left); 
                if (p.right != null) 
                    q.Enqueue(p.right); 
            }

/*            if queue is not empty, push NULL to mark 
            nodes at this level are visited */

            else if (q.Count!=0) 
                q.Enqueue(null); 
        } 
    }

/* Driver code*/

    public static void Main() 
    {

/* Constructed binary tree is 
                10 
                / \ 
            8 2 
            /     \ 
        3     90 
        */

        Node root = new Node(10); 
        root.left = new Node(8); 
        root.right = new Node(2); 
        root.left.left = new Node(3); 
        root.right.right = new Node(90);

/*        Populates nextRight pointer in all nodes */

        connect(root);

/*        Let us check the values of nextRight pointers */

        Console.WriteLine("Following are populated nextRight pointers in \n" + 
    "the tree (-1 is printed if there is no nextRight)"); 
        Console.WriteLine("nextRight of "+ root.data +" is "+ 
        ((root.nextRight != null) ? root.nextRight.data : -1)); 
        Console.WriteLine("nextRight of "+ root.left.data+" is "+ 
        ((root.left.nextRight != null) ? root.left.nextRight.data : -1)); 
        Console.WriteLine("nextRight of "+ root.right.data+" is "+ 
        ((root.right.nextRight != null) ? root.right.nextRight.data : -1)); 
        Console.WriteLine("nextRight of "+ root.left.left.data+" is "+ 
        ((root.left.left.nextRight != null) ? root.left.left.nextRight.data : -1)); 
        Console.WriteLine("nextRight of "+ root.right.right.data+" is "+ 
        ((root.right.right.nextRight != null) ? root.right.right.nextRight.data : -1)); 
    } 
}

/*Iterative c# program to connect nodes at same level 
using constant extra space */
using System;

/*A binary tree node */

public class Node
{
    public int data;
    public Node left, right, nextRight;
    public Node(int item)
    {
        data = item;
        left = right = nextRight = null;
    }
}
public class BinaryTree
{
    public Node root;

/* This function returns the leftmost child of nodes at the same level 
       as p. This function is used to getNExt right of p's right child 
       If right child of is NULL then this can also be used for the  
       left child */

    public virtual Node getNextRight(Node p)
    {
        Node temp = p.nextRight;

/* Traverse nodes at p's level and find and return 
           the first node's first child */

        while (temp != null)
        {
            if (temp.left != null)
            {
                return temp.left;
            }
            if (temp.right != null)
            {
                return temp.right;
            }
            temp = temp.nextRight;
        }

/*        If all the nodes at p's level are leaf nodes then return NULL */

        return null;
    }

/* Sets nextRight of all nodes of a tree with root as p */

    public virtual void connect(Node p)
    {
        Node temp = null;
        if (p == null)
        {
            return;
        }

/*        Set nextRight for root */

        p.nextRight = null;

/*        set nextRight of all levels one by one */

        while (p != null)
        {
            Node q = p;

/* Connect all childrem nodes of p and children nodes of all other 
               nodes at same level as p */

            while (q != null)
            {

/*                Set the nextRight pointer for p's left child */

                if (q.left != null)
                {

/*                    If q has right child, then right child is nextRight of 
                    p and we also need to set nextRight of right child */

                    if (q.right != null)
                    {
                        q.left.nextRight = q.right;
                    }
                    else
                    {
                        q.left.nextRight = getNextRight(q);
                    }
                }
                if (q.right != null)
                {
                    q.right.nextRight = getNextRight(q);
                }

/*                Set nextRight for other nodes in pre order fashion */

                q = q.nextRight;
            }

/*            start from the first node of next level */

            if (p.left != null)
            {
                p = p.left;
            }
            else if (p.right != null)
            {
                p = p.right;
            }
            else
            {
                p = getNextRight(p);
            }
        }
    }

/* Driver program to test above functions */

    public static void Main(string[] args)
    {

/* Constructed binary tree is 
                 10 
               /   \ 
             8      2 
           /         \ 
         3            90 
        */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);
        tree.root.right.right = new Node(90);

/*        Populates nextRight pointer in all nodes */

        tree.connect(tree.root);

/*        Let us check the values of nextRight pointers */

        int a = tree.root.nextRight != null ? tree.root.nextRight.data : -1;
        int b = tree.root.left.nextRight != null ? tree.root.left.nextRight.data : -1;
        int c = tree.root.right.nextRight != null ? tree.root.right.nextRight.data : -1;
        int d = tree.root.left.left.nextRight != null ? tree.root.left.left.nextRight.data : -1;
        int e = tree.root.right.right.nextRight != null ? tree.root.right.right.nextRight.data : -1;
        Console.WriteLine("Following are populated nextRight pointers in " + " the tree(-1 is printed if there is no nextRight)");
        Console.WriteLine("nextRight of " + tree.root.data + " is " + a);
        Console.WriteLine("nextRight of " + tree.root.left.data + " is " + b);
        Console.WriteLine("nextRight of " + tree.root.right.data + " is " + c);
        Console.WriteLine("nextRight of " + tree.root.left.left.data + " is " + d);
        Console.WriteLine("nextRight of " + tree.root.right.right.data + " is " + e);
    }
}

/*C# program to connect nodes 
at same level */

using System;
using System.Collections.Generic;
class Node
{
    public int data;
    public Node left, right, nextRight;
    public Node(int item)
    {
        data = item;
        left = right = nextRight = null;
    }
}
public class BinaryTree
{
    Node root;
    void connect(Node p)
    {

/*        initialize queue to hold nodes at same level */

        Queue<Node> q = new Queue<Node>();

/*adding nodes to tehe queue */

q.Enqueue(root);

/*initializing prev to null */

Node temp = null; 
        while (q.Count > 0)
        {
            int n = q.Count;
            for (int i = 0; i < n; i++)
            {
                Node prev = temp;
                temp = q.Dequeue();

/*                i > 0 because when i is 0 prev points 
                the last node of previous level, 
                so we skip it */

                if (i > 0)
                    prev.nextRight = temp;
                if (temp.left != null)
                    q.Enqueue(temp.left);
                if (temp.right != null)
                    q.Enqueue(temp.right);
            }

/*            pointing last node of the nth level to null */

            temp.nextRight = null;
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        BinaryTree tree = new BinaryTree();

/* Constructed binary tree is 
            10 
            / \ 
