/*C# program to connect nodes at same level using extended
pre-order traversal*/
using System;

/*A binary tree node*/

public class Node {
    public int data;
    public Node left, right, nextRight;
    public Node(int item)
    {
        data = item;
        left = right = nextRight = null;
    }
}
public class BinaryTree {
    public Node root;

/*    Sets the nextRight of root and calls connectRecur()
    for other nodes*/

    public virtual void connect(Node p)
    {

/*        Set the nextRight for root*/

        p.nextRight = null;

/*        Set the next right for rest of the nodes (other
        than root)*/

        connectRecur(p);
    }

/* Set next right of all descendents of p. 
       Assumption:  p is a compete binary tree */

    public virtual void connectRecur(Node p)
    {

/*        Base case*/

        if (p == null) {
            return;
        }

/*        Set the nextRight pointer for p's left child*/

        if (p.left != null) {
            p.left.nextRight = p.right;
        }

/*        Set the nextRight pointer for p's right child
        p->nextRight will be NULL if p is the right most child
        at its level*/

        if (p.right != null) {
            p.right.nextRight = (p.nextRight != null) ? p.nextRight.left : null;
        }

/*        Set nextRight for other nodes in pre order fashion*/

        connectRecur(p.left);
        connectRecur(p.right);
    }

/*    Driver program to test above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/* Constructed binary tree is 
             10 
            /  \ 
          8     2 
         / 
        3 
        */

        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.right = new Node(2);
        tree.root.left.left = new Node(3);

/*        Populates nextRight pointer in all nodes*/

        tree.connect(tree.root);

/*        Let us check the values of nextRight pointers*/

        Console.WriteLine("Following are populated nextRight pointers in "
                          + "the tree"
                          + "(-1 is printed if there is no nextRight)");
        int a = tree.root.nextRight != null ? tree.root.nextRight.data : -1;
        Console.WriteLine("nextRight of " + tree.root.data + " is " + a);
        int b = tree.root.left.nextRight != null ? tree.root.left.nextRight.data : -1;
        Console.WriteLine("nextRight of " + tree.root.left.data + " is " + b);
        int c = tree.root.right.nextRight != null ? tree.root.right.nextRight.data : -1;
        Console.WriteLine("nextRight of " + tree.root.right.data + " is " + c);
        int d = tree.root.left.left.nextRight != null ? tree.root.left.left.nextRight.data : -1;
        Console.WriteLine("nextRight of " + tree.root.left.left.data + " is " + d);
    }
}

/*C# implementation to find the level  
having maximum number of Nodes  */
using System;
using System.Collections.Generic;
public class GfG
{

/* A binary tree Node has data, pointer  
to left child and a pointer to right  
child */

public class Node
{
    public int data;
    public Node left;
    public Node right;
}

/* Helper function that allocates a new node with the  
given data and NULL left and right pointers. */

public static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = null;
    node.right = null;
    return (node);
}

/*function to find the level  
having maximum number of Nodes  */

public static int maxNodeLevel(Node root)
{
    if (root == null)
    {
        return -1;
    }
    LinkedList<Node> q = new LinkedList<Node> ();
    q.AddLast(root);

/*    Current level  */

    int level = 0;

/*    Maximum Nodes at same level  */

    int max = int.MinValue;

/*    Level having maximum Nodes  */

    int level_no = 0;
    while (true)
    {

/*        Count Nodes in a level  */

        int NodeCount = q.Count;
        if (NodeCount == 0)
        {
            break;
        }

/*        If it is maximum till now  
        Update level_no to current level  */

        if (NodeCount > max)
        {
            max = NodeCount;
            level_no = level;
        }

/*        Pop complete current level  */

        while (NodeCount > 0)
        {
            Node Node = q.First.Value;
            q.RemoveFirst();
            if (Node.left != null)
            {
                q.AddLast(Node.left);
            }
            if (Node.right != null)
            {
                q.AddLast(Node.right);
            }
            NodeCount--;
        }

/*        Increment for next level  */

        level++;
    }
    return level_no;
}

/*Driver program to test above  */

public static void Main(string[] args)
{

/*    binary tree formation  
  2*/

Node root = newNode(2);

/*  / \*/

root.left = newNode(1);

/*  1   3*/

root.right = newNode(3);

/*/ \ \*/

root.left.left = newNode(4);

/*4    6 8*/

root.left.right = newNode(6);

/*    /*/

root.right.right = newNode(8);

/*     5*/

root.left.right.left = newNode(5);

Console.WriteLine("Level having maximum number of Nodes : " + maxNodeLevel(root));
}
}

/*C# implementation to print largest
value in each level of Binary Tree*/

using System;
using System.Collections.Generic;
class GfG
{

/*    structure of a node of binary tree*/

    class Node 
    {
        public int data;
        public Node left = null;
        public Node right = null;
    }

/*    function to get a new node*/

    static Node newNode(int val)
    {

/*        allocate space*/

        Node temp = new Node();

/*        put in the data*/

        temp.data = val;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    function to print largest value
    in each level of Binary Tree*/

    static void largestValueInEachLevel(Node root)
    {

/*        if tree is empty*/

        if (root == null)
            return;
        Queue<Node> q = new Queue<Node>();
        int nc, max;

/*        push root to the queue 'q'*/

        q.Enqueue(root);
        while (true) 
        {

/*            node count for the current level*/

            nc = q.Count;

/*            if true then all the nodes of
            the tree have been traversed*/

            if (nc == 0)
                break;

/*            maximum element for the current
            level*/

            max = int.MinValue;
            while (nc != 0) 
            {

/*                get the front element from 'q'*/

                Node front = q.Peek();

/*                remove front element from 'q'*/

                q.Dequeue();

/*                if true, then update 'max'*/

                if (max < front.data)
                    max = front.data;

/*                if left child exists*/

                if (front.left != null)
                    q.Enqueue(front.left);

/*                if right child exists*/

                if (front.right != null)
                    q.Enqueue(front.right);
                nc--;
            }

/*            print maximum element of
            current level*/

            Console.Write(max + " ");
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/* Construct a Binary Tree
            4
        / \
        9 2
        / \ \
        3 5 7 */

        Node root = null;
        root = newNode(4);
        root.left = newNode(9);
        root.right = newNode(2);
        root.left.left = newNode(3);
        root.left.right = newNode(5);
        root.right.right = newNode(7);

/*        Function call*/

        largestValueInEachLevel(root);
    }
}

/*C# program to print smallest element
in each level of binary tree.*/

using System;
class GFG
{
static int INT_MAX = (int) 10e6;

/*A Binary Tree Node*/

public class Node
{
    public int data;
    public Node left, right;
};

/*return height of tree*/

static int heightoftree(Node root)
{
    if (root == null)
        return 0;
    int left = heightoftree(root.left);
    int right = heightoftree(root.right);
    return ((left > right ? left : right) + 1);
}

/*Inorder Traversal
Search minimum element in each level and
store it into vector array.*/

static void printPerLevelMinimum(Node root,
                                 int []res,
                                 int level)
{
    if (root != null)
    {
        printPerLevelMinimum(root.left,
                             res, level + 1);
        if (root.data < res[level])
            res[level] = root.data;
        printPerLevelMinimum(root.right,
                             res, level + 1);
    }
}
static void perLevelMinimumUtility(Node root)
{

/*    height of tree for the size of
    vector array*/

    int n = heightoftree(root), i;

/*    vector for store all minimum of
    every level*/

    int []res = new int[n];
    for (i = 0; i < n; i++)
        res[i] = INT_MAX;

/*    save every level minimum using
    inorder traversal*/

    printPerLevelMinimum(root, res, 0);

/*    print every level minimum*/

    Console.Write("Every level minimum is\n");
    for (i = 0; i < n; i++)
    {
        Console.Write("level " + i +
                      " min is = " +
                     res[i] + "\n");
    }
}

/*Utility function to create a new tree node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver Code*/

public static void Main(String[] args)
{

/*    Let us create binary tree shown
    in above diagram*/

    Node root = newNode(7);
    root.left = newNode(6);
    root.right = newNode(5);
    root.left.left = newNode(4);
    root.left.right = newNode(3);
    root.right.left = newNode(2);
    root.right.right = newNode(1);

/*     7
        / \
        6     5
    / \     / \
    4 3 2 1         */

    perLevelMinimumUtility(root);
}
}

/*C# program to print minimum element
in each level of binary tree.*/

using System;
using System.Collections.Generic;
class GFG
{

/*A Binary Tree Node*/

class Node
{
    public int data;
    public Node left, right;
};

/*return height of tree*/

static int heightoftree(Node root)
{
    if (root == null)
        return 0;
    int left = heightoftree(root.left);
    int right = heightoftree(root.right);
    return ((left > right ? left : right) + 1);
}

/*Iterative method to find every level
minimum element of Binary Tree*/

static void printPerLevelMinimum(Node root)
{

/*    Base Case*/

    if (root == null)
        return;

/*    Create an empty queue for
    level order traversal*/

    Queue<Node> q = new Queue<Node>();

/*    push the root for Change the level*/

    q.Enqueue(root);

/*    for go level by level*/

    q.Enqueue(null);
    int min = int.MaxValue;

/*    for check the level*/

    int level = 0;
    while (q.Count != 0)
    {

/*        Get top of queue*/

        Node node = q.Peek();
        q.Dequeue();

/*        if node == null (Means this is
        boundary between two levels)*/

        if (node == null)
        {
            Console.Write("level " + level +
                          " min is = " + min + "\n");

/*            here queue is empty represent
            no element in the actual
            queue*/

            if (q.Count == 0)
                break;
            q.Enqueue(null);

/*            increment level*/

            level++;

/*            Reset min for next level
            minimum value*/

            min = int.MaxValue;
            continue;
        }

/*        get Minimum in every level*/

        if (min > node.data)
            min = node.data;

/* Enqueue left child */

        if (node.left != null)
        {
            q.Enqueue(node.left);
        }

/*Enqueue right child */

        if (node.right != null)
        {
            q.Enqueue(node.right);
        }
    }
}

/*Utility function to create a
new tree node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver code*/

public static void Main(String[] args)
{

/*    Let us create binary tree shown
    in above diagram*/

    Node root = newNode(7);
    root.left = newNode(6);
    root.right = newNode(5);
    root.left.left = newNode(4);
    root.left.right = newNode(3);
    root.right.left = newNode(2);
    root.right.right = newNode(1);

/* 7
        / \
    6 5
    / \ / \
    4 3 2 1     */

    Console.Write("Every Level minimum is" + "\n");
    printPerLevelMinimum(root);
}
}

/*C# program to Get Level of a node in a Binary Tree*/

using System;

/* A tree node structure */

public class Node {
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
public class BinaryTree {
    public Node root;

/* Helper function for getLevel().
       It returns level of
       the data if data is present in tree,
      otherwise returns
    0.*/

    public virtual int getLevelUtil(Node node, int data,
                                    int level)
    {
        if (node == null)
        {
            return 0;
        }
        if (node.data == data)
        {
            return level;
        }
        int downlevel
            = getLevelUtil(node.left, data, level + 1);
        if (downlevel != 0)
        {
            return downlevel;
        }
        downlevel
            = getLevelUtil(node.right, data, level + 1);
        return downlevel;
    }

/* Returns level of given data value */

    public virtual int getLevel(Node node, int data)
    {
        return getLevelUtil(node, data, 1);
    }

/* Driver code */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/* Constructing tree given in the above figure */

        tree.root = new Node(3);
        tree.root.left = new Node(2);
        tree.root.right = new Node(5);
        tree.root.left.left = new Node(1);
        tree.root.left.right = new Node(4);
        for (int x = 1; x <= 5; x++)
        {
            int level = tree.getLevel(tree.root, x);
            if (level != 0)
            {
                Console.WriteLine(
                    "Level of " + x + " is "
                    + tree.getLevel(tree.root, x));
            }
            else
            {
                Console.WriteLine(
                    x + " is not present in tree");
            }
        }
    }
}

/*C# program to print level of given node 
in binary tree iterative approach */

using System;
using System.Collections;
using System.Collections.Generic;
class GFG 
{

/*    node of binary tree*/

    public class node 
    {
        public int data;
        public node left, right;
        public node(int data)
        {
            this.data = data;
            this.left = this.right = null;
        }
    }

/*    utility function to return level of given node*/

    static int getLevel(node root, int data)
    {
        Queue<node> q = new Queue<node>();
        int level = 1;
        q.Enqueue(root);

/*        extra NULL is pushed to keep track
        of all the nodes to be pushed before
        level is incremented by 1*/

        q.Enqueue(null);
        while (q.Count > 0)
        {
            node temp = q.Dequeue();
            if (temp == null)
            {
                if (q.Count > 0) 
                {
                    q.Enqueue(null);
                }
                level += 1;
            } 
            else
            {
                if (temp.data == data) 
                {
                    return level;
                }
                if (temp.left != null) 
                {
                    q.Enqueue(temp.left);
                }
                if (temp.right != null) 
                {
                    q.Enqueue(temp.right);
                }
            }
        }
        return 0;
    }

/*    Driver Code*/

    public static void Main(String []args)
    {

/*        create a binary tree*/

        node root = new node(20);
        root.left = new node(10);
        root.right = new node(30);
        root.left.left = new node(5);
        root.left.right = new node(15);
        root.left.right.left = new node(12);
        root.right.left = new node(25);
        root.right.right = new node(40);

/*        return level of node*/

        int level = getLevel(root, 30);
        if (level != 0)
            Console.WriteLine("level of node 30 is " + level);
        else
            Console.WriteLine("node 30 not found");
        level = getLevel(root, 12);
        if (level != 0)
            Console.WriteLine("level of node 12 is " + level);
        else
            Console.WriteLine("node 12 not found");
        level = getLevel(root, 25);
        if (level != 0)
            Console.WriteLine("level of node 25 is " + level);
        else
            Console.WriteLine("node 25 not found");
        level = getLevel(root, 27);
        if (level != 0)
            Console.WriteLine("level of node 27 is " + level);
        else
            Console.WriteLine("node 27 not found");
    }
}

/*C# program to find the 
mirror Node in Binary tree*/

using System;
class GfG 
{

/* A binary tree Node has data, 
        pointer to left child and a
        pointer to right child */

    class Node 
    { 
        public int key; 
        public Node left, right; 
    }

/*    create new Node and initialize it */

    static Node newNode(int key) 
    { 
        Node n = new Node(); 
            n.key = key; 
            n.left = null; 
            n.right = null; 
            return n; 
    }

/*    recursive function to find mirror of Node */

    static int findMirrorRec(int target, Node left,
                                        Node right) 
    {

/* if any of the Node is none then Node itself 
        and decendent have no mirror, so return 
        none, no need to further explore! */

        if (left==null || right==null) 
            return 0;

/* if left Node is target Node, then return 
        right's key (that is mirror) and vice 
        versa */

        if (left.key == target) 
            return right.key; 
        if (right.key == target) 
            return left.key;

/*        first recur external Nodes */

        int mirror_val = findMirrorRec(target, 
                        left.left, right.right); 
        if (mirror_val != 0) 
            return mirror_val;

/*        if no mirror found, recur internal Nodes */

        return findMirrorRec(target, 
                left.right, right.left); 
    }

/*    interface for mirror search */

    static int findMirror(Node root, int target) 
    { 
        if (root == null) 
            return 0; 
        if (root.key == target) 
            return target; 
        return findMirrorRec(target,
                root.left, root.right); 
    }

/*    Driver code*/

    public static void Main(String[] args) 
    { 
        Node root = newNode(1); 
        root.left = newNode(2); 
        root.left.left = newNode(4); 
        root.left.left.right = newNode(7); 
        root.right = newNode(3); 
        root.right.left    = newNode(5); 
        root.right.right = newNode(6); 
        root.right.left.left = newNode(8); 
        root.right.left.right = newNode(9);

/*        target Node whose mirror have to be searched */

        int target = root.left.left.key; 
        int mirror = findMirror(root, target); 
        if (mirror != 0) 
            Console.WriteLine("Mirror of Node " + 
                                target + " is Node " +
                                            mirror);
        else
            Console.WriteLine("Mirror of Node " + target +
                                            " is null ");
    } 
}

/*C# program to find the largest subtree
having identical left and right subtree*/

using System;
class GFG{

/*A binary tree node has data, pointer to
left child and a pointer to right child*/

public class Node
{
    public int data;
    public Node left, right;
};

/*Helper function that allocates a new node
with the given data and null left and
right pointers.*/

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return(node);
}
static int maxSize;
static Node maxNode;
public class pair
{
    public int first;
    public string second;
    public pair(int a, string b)
    {
        first = a;
        second = b;
    }
}

/*Sets maxSize to size of largest subtree with
identical left and right. maxSize is set with
size of the maximum sized subtree. It returns
size of subtree rooted with current node. This
size is used to keep track of maximum size.*/

static pair largestSubtreeUtil(Node root, string str)
{
    if (root == null)
        return new pair(0, str);

/*    String to store structure of left and
    right subtrees*/

    string left = "", right = "";

/*    Traverse left subtree and finds its size*/

    pair ls1 = largestSubtreeUtil(root.left, left);
    left = ls1.second;
    int ls = ls1.first;

/*    Traverse right subtree and finds its size*/

    pair rs1 = largestSubtreeUtil(root.right, right);
    right = rs1.second;
    int rs = rs1.first;

/*    If left and right subtrees are similar
    update maximum subtree if needed (Note
    that left subtree may have a bigger
    value than right and vice versa)*/

    int size = ls + rs + 1;
    if (left.Equals(right))
    {
        if (size > maxSize)
        {
            maxSize = size;
            maxNode = root;
        }
    }

/*    Append left subtree data*/

    str += "|" + left + "|";

/*    Append current node data*/

    str += "|" + root.data + "|";

/*    Append right subtree data*/

    str += "|" + right + "|";
    return new pair(size, str);
}

/*Function to find the largest subtree
having identical left and right subtree*/

static int largestSubtree(Node node)
{
    maxSize = 0;
    largestSubtreeUtil(node, "");
    return maxSize;
}

/*Driver code*/

public static void Main(string []args)
{

/* Let us construct the following Tree
              50
            /     \
           10     60
           / \     / \
          5  20 70  70
               / \  / \
              65 80 65 80
    */

    Node root = newNode(50);
    root.left = newNode(10);
    root.right = newNode(60);
    root.left.left = newNode(5);
    root.left.right = newNode(20);
    root.right.left = newNode(70);
    root.right.left.left = newNode(65);
    root.right.left.right = newNode(80);
    root.right.right = newNode(70);
    root.right.right.left = newNode(65);
    root.right.right.right = newNode(80);
    maxNode = null;
    maxSize = largestSubtree(root);
    Console.Write("Largest Subtree is rooted at node " +
                  maxNode.data + "\nand its size is " +
                  maxSize);
}
}

/*C# program to find count of single valued subtrees*/
using System;

/* Class containing left and right child of current 
 node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class Count
{
    public int count = 0;
}
public class BinaryTree
{
    public Node root;
    public Count ct = new Count();

/*    This function increments count by number of single 
    valued subtrees under root. It returns true if subtree 
    under root is Singly, else false.*/

    public virtual bool countSingleRec(Node node, Count c)
    {

/*        Return false to indicate NULL*/

        if (node == null)
        {
            return true;
        }

/*        Recursively count in left and right subtrees also*/

        bool left = countSingleRec(node.left, c);
        bool right = countSingleRec(node.right, c);

/*        If any of the subtrees is not singly, then this
        cannot be singly.*/

        if (left == false || right == false)
        {
            return false;
        }

/*        If left subtree is singly and non-empty, but data
        doesn't match*/

        if (node.left != null && node.data != node.left.data)
        {
            return false;
        }

/*        Same for right subtree*/

        if (node.right != null && node.data != node.right.data)
        {
            return false;
        }

/*        If none of the above conditions is true, then
        tree rooted under root is single valued, increment
        count and return true.*/

        c.count++;
        return true;
    }

/*    This function mainly calls countSingleRec()
    after initializing count as 0*/

    public virtual int countSingle()
    {
        return countSingle(root);
    }
    public virtual int countSingle(Node node)
    {

/*        Recursive function to count*/

        countSingleRec(node, ct);
        return ct.count;
    }

/*    Driver program to test above functions*/

    public static void Main(string[] args)
    {

/* Let us construct the below tree
                5
              /   \
            4      5
          /  \      \
         4    4      5 */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(5);
        tree.root.left = new Node(4);
        tree.root.right = new Node(5);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(4);
        tree.root.right.right = new Node(5);
        Console.WriteLine("The count of single valued sub trees is : " + tree.countSingle());
    }
}

/*C# program to find closest leaf to given node x in a tree*/

using System;

/*A binary tree node*/

public class Node
{
    public int key;
    public Node left, right;
    public Node(int key)
    {
        this.key = key;
        left = right = null;
    }
}

public class Distance
{
    public int minDis = int.MaxValue;
}
public class BinaryTree
{
    public Node root;

/*    This function finds closest leaf to root.  This distance
    is stored at *minDist.*/

    public virtual void findLeafDown(Node root, int lev, Distance minDist)
    {

/*        base case*/

        if (root == null)
        {
            return;
        }

/*        If this is a leaf node, then check if it is closer
        than the closest so far*/

        if (root.left == null && root.right == null)
        {
            if (lev < (minDist.minDis))
            {
                minDist.minDis = lev;
            }
            return;
        }

/*        Recur for left and right subtrees*/

        findLeafDown(root.left, lev + 1, minDist);
        findLeafDown(root.right, lev + 1, minDist);
    }

/*    This function finds if there is closer leaf to x through 
    parent node.*/

    public virtual int findThroughParent(Node root, Node x, Distance minDist)
    {

/*        Base cases*/

        if (root == null)
        {
            return -1;
        }
        if (root == x)
        {
            return 0;
        }

/*        Search x in left subtree of root*/

        int l = findThroughParent(root.left, x, minDist);

/*        If left subtree has x*/

        if (l != -1)
        {

/*            Find closest leaf in right subtree*/

            findLeafDown(root.right, l + 2, minDist);
            return l + 1;
        }

/*        Search x in right subtree of root*/

        int r = findThroughParent(root.right, x, minDist);

/*        If right subtree has x*/

        if (r != -1)
        {

/*            Find closest leaf in left subtree*/

            findLeafDown(root.left, r + 2, minDist);
            return r + 1;
        }
        return -1;
    }

/*    Returns minimum distance of a leaf from given node x*/

    public virtual int minimumDistance(Node root, Node x)
    {

/*        Initialize result (minimum distance from a leaf)*/

        Distance d = new Distance();

/*        Find closest leaf down to x*/

        findLeafDown(x, 0, d);

/*        See if there is a closer leaf through parent*/

        findThroughParent(root, x, d);
        return d.minDis;
    }

/*    Driver program*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();

/*        Let us create Binary Tree shown in above example*/

        tree.root = new Node(1);
        tree.root.left = new Node(12);
        tree.root.right = new Node(13);
        tree.root.right.left = new Node(14);
        tree.root.right.right = new Node(15);
        tree.root.right.left.left = new Node(21);
        tree.root.right.left.right = new Node(22);
        tree.root.right.right.left = new Node(23);
        tree.root.right.right.right = new Node(24);
        tree.root.right.left.left.left = new Node(1);
        tree.root.right.left.left.right = new Node(2);
        tree.root.right.left.right.left = new Node(3);
        tree.root.right.left.right.right = new Node(4);
        tree.root.right.right.left.left = new Node(5);
        tree.root.right.right.left.right = new Node(6);
        tree.root.right.right.right.left = new Node(7);
        tree.root.right.right.right.right = new Node(8);
        Node x = tree.root.right;
        Console.WriteLine("The closest leaf to node with value " + x.key + " is at a distance of " + tree.minimumDistance(tree.root, x));
    }
}

/*C# program to find closest leaf of a given key in Binary Tree */

using System;

/* Class containing left and right child of current  
   node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root;

/*    A utility function to find minimum of x and y */

    public virtual int getMin(int x, int y)
    {
        return (x < y) ? x : y;
    }

/*    A utility function to find distance of closest leaf of the tree 
    rooted under given root */

    public virtual int closestDown(Node node)
    {

/*        Base cases */

        if (node == null)
        {
            return int.MaxValue;
        }
        if (node.left == null && node.right == null)
        {
            return 0;
        }

/*        Return minimum of left and right, plus one */

        return 1 + getMin(closestDown(node.left), closestDown(node.right));
    }

/*    Returns distance of the cloest leaf to a given key 'k'.  The array 
    ancestors is used to keep track of ancestors of current node and 
    'index' is used to keep track of curremt index in 'ancestors[]' */

    public virtual int findClosestUtil(Node node, char k, Node[] ancestors, int index)
    {

/*        Base case */

        if (node == null)
        {
            return int.MaxValue;
        }

/*        If key found */

        if ((char)node.data == k)
        {

/*              Find the cloest leaf under the subtree rooted with given key */

            int res = closestDown(node);

/*            Traverse all ancestors and update result if any parent node 
            gives smaller distance */

            for (int i = index - 1; i >= 0; i--)
            {
                res = getMin(res, index - i + closestDown(ancestors[i]));
            }
            return res;
        }

/*        If key node found, store current node and recur for left and 
        right childrens */

        ancestors[index] = node;
        return getMin(findClosestUtil(node.left, k, ancestors, index + 1), findClosestUtil(node.right, k, ancestors, index + 1));
    }

/*    The main function that returns distance of the closest key to 'k'. It 
    mainly uses recursive function findClosestUtil() to find the closes 
    distance. */

    public virtual int findClosest(Node node, char k)
    {

/*        Create an array to store ancestors 
        Assumptiom: Maximum height of tree is 100 */

        Node[] ancestors = new Node[100];
        return findClosestUtil(node, k, ancestors, 0);
    }

/*    Driver program to test for above functions */

    public static void Main(string[] args)
    {

/*    Let us construct the BST shown in the above figure*/

        BinaryTree tree = new BinaryTree();
        tree.root = new Node('A');
        tree.root.left = new Node('B');
        tree.root.right = new Node('C');
        tree.root.right.left = new Node('E');
        tree.root.right.right = new Node('F');
        tree.root.right.left.left = new Node('G');
        tree.root.right.left.left.left = new Node('I');
        tree.root.right.left.left.right = new Node('J');
        tree.root.right.right.right = new Node('H');
        tree.root.right.right.right.left = new Node('H');
        char k = 'H';
        Console.WriteLine("Distance of the closest key from " + k + " is " + tree.findClosest(tree.root, k));
        k = 'C';
        Console.WriteLine("Distance of the closest key from " + k + " is " + tree.findClosest(tree.root, k));
        k = 'E';
        Console.WriteLine("Distance of the closest key from " + k + " is " + tree.findClosest(tree.root, k));
        k = 'B';
        Console.WriteLine("Distance of the closest key from " + k + " is " + tree.findClosest(tree.root, k));
    }
}

/*Iterative level order traversal
based method to search in Binary Tree */

using System;
using System.Collections.Generic; 
class GFG
{

/* A binary tree node has data,
left child and right child */

public class node 
{ 
    public int data; 
    public node left; 
    public node right;

/* Constructor that allocates a new node 
    with the given data and null left and
    right pointers. */

    public node(int data)
    {
        this.data = data;
        this.left = null;
        this.right = null;
    }
};

/*An iterative process to search
an element x in a given binary tree */

static Boolean iterativeSearch(node root,
                               int x) 
{

/*    Base Case */

    if (root == null) 
        return false;

/*    Create an empty queue for 
    level order traversal */

    Queue<node > q = new Queue<node>();

/*    Enqueue Root and initialize height */

    q.Enqueue(root);

/*    Queue based level order traversal */

    while (q.Count > 0) 
    {

/*        See if current node is same as x */

        node node = q.Peek(); 
        if (node.data == x) 
            return true;

/*        Remove current node and 
        enqueue its children */

        q.Dequeue(); 
        if (node.left != null) 
            q.Enqueue(node.left); 
        if (node.right != null) 
            q.Enqueue(node.right); 
    } 
    return false; 
}

/*Driver code */

public static void Main(String []ags)
{ 
    node root = new node(2); 
    root.left = new node(7); 
    root.right = new node(5); 
    root.left.right = new node(6); 
    root.left.right.left = new node(1); 
    root.left.right.right = new node(11); 
    root.right.right = new node(9); 
    root.right.right.left = new node(4); 
    Console.WriteLine((iterativeSearch(root, 6) ? 
                                      "Found\n" : 
                                   "Not Found")); 
    Console.Write((iterativeSearch(root, 12) ? 
                                   "Found\n" :
                              "Not Found\n")); 
}
}

/*An iterative method to search an item in Binary Tree*/

using System;
using System.Collections.Generic;
class GFG
{

/* A binary tree node has data, 
left child and right child */

class node
{
    public int data;
    public node left, right;
};

/* Helper function that allocates a 
new node with the given data and 
null left and right pointers.*/

static node newNode(int data)
{
    node node = new node();
    node.data = data;
    node.left = node.right = null;
    return(node);
}

/*iterative process to search 
an element x in a given binary tree*/

static bool iterativeSearch(node root, int x)
{

/*    Base Case*/

    if (root == null)
        return false;

/*    Create an empty stack and.Push root to it*/

    Stack<node> nodeStack = new Stack<node>();
    nodeStack.Push(root);

/*    Do iterative preorder traversal to search x*/

    while (nodeStack.Count != 0)
    {

/*        See the top item from stack and 
        check if it is same as x*/

        node node = nodeStack.Peek();
        if (node.data == x)
            return true;
        nodeStack.Pop();

/*        Push right and left children 
        of the.Popped node to stack*/

        if (node.right != null)
            nodeStack.Push(node.right);
        if (node.left != null)
            nodeStack.Push(node.left);
    }
    return false;
}

/*Driver Code*/

public static void Main(String[] args)
{
    node root = newNode(2);
    root.left = newNode(7);
    root.right = newNode(5);
    root.left.right = newNode(6);
    root.left.right.left = newNode(1);
    root.left.right.right = newNode(11);
    root.right.right = newNode(9);
    root.right.right.left = newNode(4);
    if(iterativeSearch(root, 6))
        Console.WriteLine("Found");
    else
        Console.WriteLine("Not Found");
    if(iterativeSearch(root, 12))
        Console.WriteLine("Found");
    else
        Console.WriteLine("Not Found");
}
}

/*C# program to remove half nodes*/

using System;

/*Binary tree node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

/*For inorder traversal*/

public class BinaryTree
{
    public Node root;
    public virtual void printInorder(Node node)
    {
        if (node != null)
        {
            printInorder(node.left);
            Console.Write(node.data + " ");
            printInorder(node.right);
        }
    }

/*    Removes all nodes with only one child and returns
    new root (note that root may change)*/

    public virtual Node RemoveHalfNodes(Node node)
    {
        if (node == null)
        {
            return null;
        }
        node.left = RemoveHalfNodes(node.left);
        node.right = RemoveHalfNodes(node.right);
        if (node.left == null && node.right == null)
        {
            return node;
        }

/* if current nodes is a half node with left
         child NULL left, then it's right child is
         returned and replaces it in the given tree */

        if (node.left == null)
        {
            Node new_root = node.right;
            return new_root;
        }

/* if current nodes is a half node with right
           child NULL right, then it's right child is
           returned and replaces it in the given tree  */

        if (node.right == null)
        {
            Node new_root = node.left;
            return new_root;
        }
        return node;
    }

/*    Driver program*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        Node NewRoot = null;
        tree.root = new Node(2);
        tree.root.left = new Node(7);
        tree.root.right = new Node(5);
        tree.root.left.right = new Node(6);
        tree.root.left.right.left = new Node(1);
        tree.root.left.right.right = new Node(11);
        tree.root.right.right = new Node(9);
        tree.root.right.right.left = new Node(4);
        Console.WriteLine("the inorder traversal of tree is ");
        tree.printInorder(tree.root);
        NewRoot = tree.RemoveHalfNodes(tree.root);
        Console.Write("\nInorder traversal of the modified tree \n");
        tree.printInorder(NewRoot);
    }
}

/*C# program swap nodes */

using System;
class GFG 
{

/*A Binary Tree Node */

public class Node 
{ 
    public int data; 
    public Node left, right; 
};

/*function to create a new tree node */

static Node newNode(int data) 
{ 
    Node temp = new Node(); 
    temp.data = data; 
    temp.left = temp.right = null; 
    return temp; 
}

/*A utility function swap left- node & right node of tree 
of every k'th level */

static void swapEveryKLevelUtil( Node root, int level, int k) 
{

/*    base case */

    if (root == null || 
            (root.left == null && root.right==null) ) 
        return ;

/*    if current level + 1 is present in swap vector 
    then we swap left & right node */

    if ( (level + 1) % k == 0) 
        { 
            Node temp=root.left; 
            root.left=root.right; 
            root.right=temp; 
        }

/*    Recur for left and right subtrees */

    swapEveryKLevelUtil(root.left, level+1, k); 
    swapEveryKLevelUtil(root.right, level+1, k); 
}

/*This function mainly calls recursive function 
swapEveryKLevelUtil() */

static void swapEveryKLevel(Node root, int k) 
{

/*    call swapEveryKLevelUtil function with 
    initial level as 1. */

    swapEveryKLevelUtil(root, 1, k); 
}

/*Utility method for inorder tree traversal */

static void inorder(Node root) 
{ 
    if (root == null) 
        return; 
    inorder(root.left); 
    Console.Write(root.data + " "); 
    inorder(root.right); 
}

/*Driver Code */

public static void Main(String []args) 
{

/* 1 
        / \ 
    2 3 
    / / \ 
    4 7 8 */

    Node root = newNode(1); 
    root.left = newNode(2); 
    root.right = newNode(3); 
    root.left.left = newNode(4); 
    root.right.right = newNode(8); 
    root.right.left = newNode(7); 
    int k = 2; 
    Console.WriteLine("Before swap node :"); 
    inorder(root); 
    swapEveryKLevel(root, k); 
    Console.WriteLine("\nAfter swap Node :" ); 
    inorder(root); 
} 
}

/*C# program to count root to leaf
paths of different lengths.*/

using System;
using System.Collections.Generic;
class GFG
{

/*  A binary tree node*/

  public
    class Node
    {
      public
        int data;
      public
        Node left,
      right;
    };

/*  Utility that allocates a new node
  with the given data and null left
  and right pointers.*/

  static Node newnode(int data)
  {
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
  }

/*  Function to store counts of different
  root to leaf path lengths in hash map m.*/

  static void pathCountUtil(Node node,
                            Dictionary<int, int> m,
                            int path_len)
  {

/*    Base condition*/

    if (node == null)
      return;

/*    If leaf node reached, increment count
    of path length of this root to leaf path.*/

    if (node.left == null && node.right == null)
    {
      if (!m.ContainsKey(path_len))
        m.Add(path_len, 1);
      else
        m[path_len] = m[path_len] + 1;
      return;
    }

/*    Recursively call for left and right
    subtrees with path lengths more than 1.*/

    pathCountUtil(node.right, m, path_len + 1);
    pathCountUtil(node.left, m, path_len + 1);
  }

/*  A wrapper over pathCountUtil()*/

  static void pathCounts(Node root)
  {

/*    Create an empty hash table*/

    Dictionary<int, int> m = new Dictionary<int, int>();

/*    Recursively check in left and right subtrees.*/

    pathCountUtil(root, m, 1);

/*    Print all path lenghts and their counts.*/

    foreach(KeyValuePair<int, int> entry in m)
    {
      Console.WriteLine(entry.Value
                        + " paths have length "
                        + entry.Key);
    }
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    Node root = newnode(8);
    root.left = newnode(5);
    root.right = newnode(4);
    root.left.left = newnode(9);
    root.left.right = newnode(7);
    root.right.right = newnode(11);
    root.right.right.left = newnode(3);
    pathCounts(root);
  }
}

/*C# Program to find Maximum Consecutive 
Path Length in a Binary Tree*/

using System;
class GfG 
{

/*    To represent a node of a Binary Tree */

    class Node 
    { 
        public Node left, right; 
        public int val; 
    }

/*    Create a new Node and return its address */

    static Node newNode(int val) 
    { 
        Node temp = new Node(); 
        temp.val = val; 
        temp.left = null;
        temp.right = null; 
        return temp; 
    }

/*    Returns the maximum consecutive Path Length */

    static int maxPathLenUtil(Node root, 
                int prev_val, int prev_len) 
    { 
        if (root == null) 
            return prev_len;

/*        Get the value of Current Node 
        The value of the current node will be 
        prev Node for its left and right children */

        int cur_val = root.val;

/*        If current node has to be a part of the 
        consecutive path then it should be 1 greater 
        than the value of the previous node */

        if (cur_val == prev_val+1) 
        {

/*            a) Find the length of the Left Path 
            b) Find the length of the Right Path 
            Return the maximum of Left path and Right path */

            return Math.Max(maxPathLenUtil(root.left, cur_val, prev_len+1), 
                    maxPathLenUtil(root.right, cur_val, prev_len+1)); 
        }

/*        Find length of the maximum path under subtree rooted with this 
        node (The path may or may not include this node) */

        int newPathLen = Math.Max(maxPathLenUtil(root.left, cur_val, 1), 
                            maxPathLenUtil(root.right, cur_val, 1));

/*        Take the maximum previous path and path under subtree rooted 
        with this node. */

        return Math.Max(prev_len, newPathLen); 
    }

/*    A wrapper over maxPathLenUtil(). */

    static int maxConsecutivePathLength(Node root) 
    {

/*        Return 0 if root is NULL */

        if (root == null) 
            return 0;

/*        Else compute Maximum Consecutive Increasing Path 
        Length using maxPathLenUtil. */

        return maxPathLenUtil(root, root.val - 1, 0); 
    }

/*    Driver code*/

    public static void Main(String[] args) 
    { 
        Node root = newNode(10); 
        root.left = newNode(11); 
        root.right = newNode(9); 
        root.left.left = newNode(13); 
        root.left.right = newNode(12); 
        root.right.left = newNode(13); 
        root.right.right = newNode(8); 
        Console.WriteLine("Maximum Consecutive" +
                        " Increasing Path Length is "+
                            maxConsecutivePathLength(root)); 
    } 
}

/*C# program to find the length of longest
path with same values in a binary tree.*/

using System;
class GFG
{
static int ans;

/* A binary tree node has data, pointer to
left child and a pointer to right child */

public class Node 
{
    public int val;
    public Node left, right;
};

/* Function to print the longest path
of same values */

static int length(Node node) 
{
    if (node == null)
        return 0;

/*    Recursive calls to check for subtrees*/

    int left = length(node.left);
    int right = length(node.right);

/*    Variables to store maximum lengths
    in two directions*/

    int Leftmax = 0, Rightmax = 0;

/*    If curr node and it's left child
    has same value*/

    if (node.left != null &&
        node.left.val == node.val) 
        Leftmax += left + 1;

/*    If curr node and it's right child
    has same value*/

    if (node.right != null && 
        node.right.val == node.val) 
        Rightmax += right + 1;
    ans = Math.Max(ans, Leftmax + Rightmax);
    return Math.Max(Leftmax, Rightmax);
}

/*Function to find length of
longest same value path*/

static int longestSameValuePath(Node root) 
{
    ans = 0;
    length(root);
    return ans;
}

/* Helper function that allocates a
new node with the given data and
null left and right pointers. */

static Node newNode(int data) 
{
    Node temp = new Node();
    temp.val = data;
    temp.left = temp.right = null;
    return temp;
}

/*Driver code*/

public static void Main(String[] args) 
{

/* Let us cona Binary Tree
            4
        / \
        4 4
        / \ \
        4 9 5 */

    Node root = null;
    root = newNode(4);
    root.left = newNode(4);
    root.right = newNode(4);
    root.left.left = newNode(4);
    root.left.right = newNode(9);
    root.right.right = newNode(5);
    Console.Write(longestSameValuePath(root));
}
}

/*C# program to remove nodes on root to leaf paths of length < k */
using System;

/* Class containing left and right child of current  
   node and key value*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root;

/*    Utility method that actually removes the nodes which are not 
    on the pathLen >= k. This method can change the root as well. */

    public virtual Node removeShortPathNodesUtil(Node node, int level, int k)
    {

/*        Base condition */

        if (node == null)
        {
            return null;
        }

/*        Traverse the tree in postorder fashion so that if a leaf 
        node path length is shorter than k, then that node and 
        all of its descendants till the node which are not 
        on some other path are removed. */

        node.left = removeShortPathNodesUtil(node.left, level + 1, k);
        node.right = removeShortPathNodesUtil(node.right, level + 1, k);

/*        If root is a leaf node and it's level is less than k then 
        remove this node. 
        This goes up and check for the ancestor nodes also for the 
        same condition till it finds a node which is a part of other 
        path(s) too. */

        if (node.left == null && node.right == null && level < k)
        {
            return null;
        }

/*        Return root; */

        return node;
    }

/*    Method which calls the utitlity method to remove the short path 
    nodes. */

    public virtual Node removeShortPathNodes(Node node, int k)
    {
        int pathLen = 0;
        return removeShortPathNodesUtil(node, 1, k);
    }

/*    Method to print the tree in inorder fashion. */

    public virtual void printInorder(Node node)
    {
        if (node != null)
        {
            printInorder(node.left);
            Console.Write(node.data + " ");
            printInorder(node.right);
        }
    }

/*    Driver program to test for samples */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        int k = 4;
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.left.left.left = new Node(7);
        tree.root.right.right = new Node(6);
        tree.root.right.right.left = new Node(8);
        Console.WriteLine("The inorder traversal of original tree is : ");
        tree.printInorder(tree.root);
        Node res = tree.removeShortPathNodes(tree.root, k);
        Console.WriteLine("");
        Console.WriteLine("The inorder traversal of modified tree is : ");
        tree.printInorder(res);
    }
}

/*C# program to find longest consecutive 
sequence in binary tree */

using System;

/* A binary tree node has data, pointer to left
   child and a pointer to right child */

class Node 
{ 
    public int data; 
    public Node left, right; 
    public Node(int item) 
    { 
        data = item; 
        left = right = null; 
    } 
} 
class Result 
{ 
    public int res = 0; 
} 
class GFG 
{ 
    Node root;

/*    Utility method to return length of longest 
    consecutive sequence of tree */

    private void longestConsecutiveUtil(Node root, int curlength, 
                                        int expected, Result res) 
    { 
        if (root == null) 
            return;

/*        if root data has one more than its parent 
        then increase current length */

        if (root.data == expected) 
            curlength++; 
        else
            curlength = 1;

/*        update the maximum by current length */

        res.res = Math.Max(res.res, curlength);

/*        recursively call left and right subtree with 
        expected value 1 more than root data */

        longestConsecutiveUtil(root.left, curlength, 
                               root.data + 1, res); 
        longestConsecutiveUtil(root.right, curlength, 
                               root.data + 1, res); 
    }

/*    method returns length of longest consecutive 
    sequence rooted at node root */

    int longestConsecutive(Node root) 
    { 
        if (root == null) 
            return 0; 
        Result res = new Result();

/*        call utility method with current length 0 */

        longestConsecutiveUtil(root, 0, root.data, res); 
        return res.res; 
    }

/*    Driver code */

    public static void Main(String []args) 
    { 
        GFG tree = new GFG(); 
        tree.root = new Node(6); 
        tree.root.right = new Node(9); 
        tree.root.right.left = new Node(7); 
        tree.root.right.right = new Node(10); 
        tree.root.right.right.right = new Node(11); 
        Console.WriteLine(tree.longestConsecutive(tree.root)); 
    } 
}

/*C# program to find path length
having maximum number of bends*/

using System;
public class GFG
{

/*  structure node*/

  public
    class Node
    {
      public
        int key;
      public
        Node left;
      public
        Node right;
    };

/*  Utility function to create a new node*/

  static Node newNode(int key)
  {
    Node node = new Node();
    node.left = null;
    node.right = null;
    node.key = key;
    return node;
  }

/* Recursive function to calculate the path
length having maximum number of bends.
The following are parameters for this function.
node -. pointer to the current node
dir -. determines whether the current node
is left or right child of it's parent node
bends -. number of bends so far in the
current path.
maxBends -. maximum number of bends in a
path from root to leaf
soFar -. length of the current path so
far traversed
len -. length of the path having maximum
number of bends
*/

  static int maxBends;
  static int len;
  static void findMaxBendsUtil(Node node,
                               char dir, int bends,
                               int soFar)
  {

/*    Base Case*/

    if (node == null)
      return;

/*    Leaf node*/

    if (node.left == null && node.right == null)
    {
      if (bends > maxBends)
      {
        maxBends = bends;
        len = soFar;
      }
    }

/*    Recurring for both left and right child*/

    else
    {
      if (dir == 'l')
      {
        findMaxBendsUtil(node.left, dir,
                         bends,
                         soFar + 1);
        findMaxBendsUtil(node.right, 'r',
                         bends + 1,
                         soFar + 1);
      }
      else
      {
        findMaxBendsUtil(node.right, dir,
                         bends,
                         soFar + 1);
        findMaxBendsUtil(node.left, 'l',
                         bends + 1,
                         soFar + 1);
      }
    }
  }

/*  Helper function to call findMaxBendsUtil()*/

  static int findMaxBends(Node node)
  {
    if (node == null)
      return 0;
    len = 0;
    maxBends = -1;
    int bends = 0;

/*    Call for left subtree of the root*/

    if (node.left != null)
      findMaxBendsUtil(node.left, 'l',
                       bends, 1);

/*    Call for right subtree of the root*/

    if (node.right != null)
      findMaxBendsUtil(node.right, 'r', bends,
                       1);

/*    Include the root node as well in the path length*/

    len++;
    return len;
  }

/*  Driver code*/

  public static void Main(String[] args)
  {

/* Constructed binary tree is
      10
      / \
     8    2
    / \  /
    3  5 2
          \
           1
          /
         9
    */

    Node root = newNode(10);
    root.left = newNode(8);
    root.right = newNode(2);
    root.left.left = newNode(3);
    root.left.right = newNode(5);
    root.right.left = newNode(2);
    root.right.left.right = newNode(1);
    root.right.left.right.left = newNode(9);
    Console.Write(findMaxBends(root) - 1);
  }
}

/*A C# Program to count number of turns
in a Binary Tree.*/

using System;
public class Turns_to_reach_another_node
{
    public static int Count;

/*    A Binary Tree Node*/

    public class Node
    {
        public Node left, right;
        public int key;

/*        Constructor*/

        public Node(int key)
        {
            this.key = key;
            left = null;
            right = null;
        }
    }

/*    Utility function to find the LCA of
    two given values n1 and n2.*/

    public static Node findLCA(Node root, int n1, int n2)
    {

/*        Base case*/

        if (root == null)
        {
            return null;
        }

/*        If either n1 or n2 matches with
        root's key, report the presence by
        returning root (Note that if a key
        is ancestor of other, then the
        ancestor key becomes LCA*/

        if (root.key == n1 || root.key == n2)
        {
            return root;
        }

/*        Look for keys in left and right subtrees*/

        Node left_lca = findLCA(root.left, n1, n2);
        Node right_lca = findLCA(root.right, n1, n2);

/*        If both of the above calls return
        Non-NULL, then one key is present
        in once subtree and other is present
        in other, So this node is the LCA*/

        if (left_lca != null && right_lca != null)
        {
            return root;
        }

/*        Otherwise check if left subtree or right
        subtree is LCA*/

        return (left_lca != null) ? left_lca : right_lca;
    }

/*    function count number of turn need to reach
    given node from it's LCA we have two way to*/

    public static bool CountTurn(Node root, int key, bool turn)
    {
        if (root == null)
        {
            return false;
        }

/*        if found the key value in tree*/

        if (root.key == key)
        {
            return true;
        }

/*        Case 1:*/

        if (turn == true)
        {
            if (CountTurn(root.left, key, turn))
            {
                return true;
            }
            if (CountTurn(root.right, key, !turn))
            {
                Count += 1;
                return true;
            }
        }

/*Case 2:*/

else 
        {
            if (CountTurn(root.right, key, turn))
            {
                return true;
            }
            if (CountTurn(root.left, key, !turn))
            {
                Count += 1;
                return true;
            }
        }
        return false;
    }

/*    Function to find nodes common to given two nodes*/

    public static int NumberOfTurn(Node root, int first, int second)
    {
        Node LCA = findLCA(root, first, second);

/*        there is no path between these two node*/

        if (LCA == null)
        {
            return -1;
        }
        Count = 0;

/*        case 1:*/

        if (LCA.key != first && LCA.key != second)
        {

/*            count number of turns needs to reached
            the second node from LCA*/

            if (CountTurn(LCA.right, second, false)
                || CountTurn(LCA.left, second, true))
            {
                ;
            }

/*            count number of turns needs to reached
            the first node from LCA*/

            if (CountTurn(LCA.left, first, true)
                || CountTurn(LCA.right, first, false))
            {
                ;
            }
            return Count + 1;
        }

/*        case 2:*/

        if (LCA.key == first)
        {

/*            count number of turns needs to reached
            the second node from LCA*/

            CountTurn(LCA.right, second, false);
            CountTurn(LCA.left, second, true);
            return Count;
        }
        else
        {

/*            count number of turns needs to reached
            the first node from LCA1*/

            CountTurn(LCA.right, first, false);
            CountTurn(LCA.left, first, true);
            return Count;
        }
    }

/*    Driver program to test above functions*/

    public static void Main(string[] args)
    {

/*        Let us create binary tree given in the above
        example*/

        Node root = new Node(1);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(4);
        root.left.right = new Node(5);
        root.right.left = new Node(6);
        root.right.right = new Node(7);
        root.left.left.left = new Node(8);
        root.right.left.left = new Node(9);
        root.right.left.right = new Node(10);
        int turn = 0;
        if ((turn = NumberOfTurn(root, 5, 10)) != 0)
        {
            Console.WriteLine(turn);
        }
        else
        {
            Console.WriteLine("Not Possible");
        }
    }
}

/*C# implementation to create odd and even loops
in a binary tree*/

using System;
using System.Collections.Generic;
class GFG
{

/*  structure of a node*/

  public
    class Node
    {
      public
        int data;
      public
        Node left, right, abtr;
    };

/*  Utility function to create a new node*/

  static Node newNode(int data)
  {
    Node node = new Node();
    node.data = data;
    node.left = node.right = node.abtr = null;
    return node;
  }
  static List<Node> even_ptrs = new List<Node>();
  static List<Node> odd_ptrs = new List<Node>();

/*  preorder traversal to place the node pointer
  in the respective even_ptrs or odd_ptrs list*/

  static void preorderTraversal(Node root)
  {
    if (root == null)
      return;

/*    place node ptr in even_ptrs list if
    node contains even number */

    if (root.data % 2 == 0)   
      (even_ptrs).Add(root);

/*    else place node ptr in odd_ptrs list*/

    else
      (odd_ptrs).Add(root);
    preorderTraversal(root.left);
    preorderTraversal(root.right);
  }

/*  function to create the even and odd loops*/

  static void createLoops(Node root)
  {
    preorderTraversal(root);  
    int i;

/*    forming even loop*/

    for (i = 1; i < even_ptrs.Count; i++)
      even_ptrs[i - 1].abtr = even_ptrs[i];

/*    for the last element*/

    even_ptrs[i - 1].abtr = even_ptrs[0];

/*    Similarly forming odd loop*/

    for (i = 1; i < odd_ptrs.Count; i++)
      odd_ptrs[i - 1].abtr = odd_ptrs[i];
    odd_ptrs[i - 1].abtr = odd_ptrs[0];
  }

/*  traversing the loop from any random
  node in the loop*/

  static void traverseLoop(Node start)
  {
    Node curr = start;
    do
    {
      Console.Write(curr.data + " ");
      curr = curr.abtr;
    } while (curr != start);
  }

/*  Driver code*/

  public static void Main(String[] args)
  {

/*    Binary tree formation*/

    Node root = null;
    root = newNode(1);                 
    root.left = newNode(2);            
    root.right = newNode(3);           
    root.left.left = newNode(4);   
    root.left.right = newNode(5);    
    root.right.left = newNode(6);
    root.right.right = newNode(7);  
    createLoops(root);

/*    traversing odd loop from any
    random odd node*/

    Console.Write("Odd nodes: ");
    traverseLoop(root.right);  
    Console.Write( "\nEven nodes: ");

/*    traversing even loop from any
    random even node*/

    traverseLoop(root.left);   
  }
}

/*C# program to find first leaves that are 
not same. */

using System;
using System.Collections.Generic;
class GfG 
{

/*    Tree node */

    public class Node 
    { 
        public int data; 
        public Node left, right; 
    }

/*    Utility method to create a new node */

    static Node newNode(int x) 
    { 
        Node temp = new Node(); 
        temp.data = x; 
        temp.left = null;
        temp.right = null; 
        return temp; 
    } 
    static bool isLeaf(Node t) 
    { 
        return ((t.left == null) && (t.right == null)); 
    }

/*    Prints the first non-matching leaf node in 
    two trees if it exists, else prints nothing. */

    static void findFirstUnmatch(Node root1, Node root2) 
    {

/*        If any of the tree is empty */

        if (root1 == null || root2 == null) 
        return;

/*        Create two stacks for preorder traversals */

        Stack<Node> s1 = new Stack<Node> ();
        Stack<Node> s2 = new Stack<Node> (); 
        s1.Push(root1); 
        s2.Push(root2); 
        while (s1.Count != 0 || s2.Count != 0) 
        {

/*            If traversal of one tree is over 
            and other tree still has nodes. */

            if (s1.Count == 0 || s2.Count == 0 ) 
            return;

/*            Do iterative traversal of first tree 
            and find first lead node in it as "temp1" */

            Node temp1 = s1.Peek(); 
            s1.Pop(); 
            while (temp1 != null && isLeaf(temp1) != true) 
            {

/*                pushing right childfirst so that 
                left child comes first while popping. */

                s1.Push(temp1.right); 
                s1.Push(temp1.left); 
                temp1 = s1.Peek(); 
                s1.Pop(); 
            }

/*            Do iterative traversal of second tree 
            and find first lead node in it as "temp2" */

            Node temp2 = s2.Peek(); 
            s2.Pop(); 
            while (temp2 != null && isLeaf(temp2) != true) 
            { 
                s2.Push(temp2.right); 
                s2.Push(temp2.left); 
                temp2 = s2.Peek(); 
                s2.Pop(); 
            }

/*            If we found leaves in both trees */

            if (temp1 != null && temp2 != null ) 
            { 
                if (temp1.data != temp2.data ) 
                { 
                    Console.WriteLine(temp1.data + " " + temp2.data); 
                    return; 
                } 
            } 
        } 
    }

/*    Driver code */

    public static void Main(String[] args) 
    { 
        Node root1 = newNode(5); 
        root1.left = newNode(2); 
        root1.right = newNode(7); 
        root1.left.left = newNode(10); 
        root1.left.right = newNode(11); 
        Node root2 = newNode(6); 
        root2.left = newNode(10); 
        root2.right = newNode(15); 
        findFirstUnmatch(root1,root2); 
    } 
}

/*C# program to print maximum element 
in left node.*/

using System;
class GfG 
{

/*    A Binary Tree Node */

    class Node 
    { 
        public int data; 
        public Node left, right; 
    }

/*    Get max of left element using 
    Inorder traversal */

    static int maxOfLeftElement(Node root) 
    { 
        int res = int.MinValue; 
        if (root == null) 
            return res; 
        if (root.left != null) 
            res = root.left.data;

/*        Return maximum of three values 
        1) Recursive max in left subtree 
        2) Value in left node 
        3) Recursive max in right subtree */

        return Math.Max(maxOfLeftElement(root.left),
        Math.Max(res, maxOfLeftElement(root.right))); 
    }

/*    Utility function to create a new tree node */

    static Node newNode(int data) 
    { 
        Node temp = new Node(); 
        temp.data = data; 
        temp.left = null;
        temp.right = null; 
        return temp; 
    }

/*    Driver code */

    public static void Main(String[] args) 
    {

/*        Let us create binary tree
        shown in above diagram */

        Node root = newNode(7); 
        root.left = newNode(6); 
        root.right = newNode(5); 
        root.left.left = newNode(4); 
        root.left.right = newNode(3); 
        root.right.left = newNode(2); 
        root.right.right = newNode(1);

/* 7 
            / \ 
            6 5 
        / \ / \ 
        4 3 2 1         */

        Console.WriteLine(maxOfLeftElement(root)); 
    }
}

/*C# program to find a number in minimum steps*/

using System;
using System.Collections.Generic;
public
class GFG
{
  static readonly int InF = 99999;

/*  To represent data of a node in tree*/

  public
 class number
  {
    public
 int no;
    public
 int level;
    public
 number() {}
    public
 number(int n, int l)
    {
      this.no = n;
      this.level = l;
    }
  };

/*  Prints level of node n*/

  static void findnthnumber(int n)
  {

/*    Create a queue and insert root*/

    Queue<number> q = new Queue<number>();
    number r = new number(0, 1);
    q.Enqueue(r);

/*    Do level order traversal*/

    while (q.Count != 0)
    {

/*      Remove a node from queue*/

      number temp = q.Peek();
      q.Dequeue();

/*      To astatic void infinite loop*/

      if (temp.no >= InF || temp.no <= -InF)
        break;

/*      Check if dequeued number is same as n*/

      if (temp.no == n)
      {
        Console.Write("Found number n at level "
                         + (temp.level - 1));
        break;
      }

/*      Insert children of dequeued node to queue*/

      q.Enqueue(new number(temp.no + temp.level, temp.level + 1));
      q.Enqueue(new number(temp.no - temp.level, temp.level + 1));
    }
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    findnthnumber(13);
  }
}

/*C# program to Find a
number in minimum steps*/

using System;
using System.Collections.Generic;
public class GFG
{
  static List<int> find(int n)
  {

/*    Steps sequence*/

    List<int> ans = new List<int>();

/*    Current sum*/

    int sum = 0;
    int i = 1;

/*    Sign of the number*/

    int sign = (n >= 0 ? 1 : -1);
    n = Math.Abs(n);

/*    Basic steps required to get
    sum >= required value.*/

    for (; sum < n;)
    {
      ans.Add(sign * i);
      sum += i;
      i++;
    }

/*    If we have reached ahead to destination.*/

    if (sum > sign * n)
    {

/*If the last step was an odd number,
         then it has following mechanism for
         negating a particular number and
         decreasing the sum to required number
         Also note that it may require
         1 more step in order to reach the sum. */

      if (i % 2 != 0)
      {
        sum -= n;
        if (sum % 2 != 0)
        {
          ans.Add(sign * i);
          sum += i;
          i++;
        }
        int a = ans[((sum / 2) - 1)];
        ans.RemoveAt((sum / 2) - 1);
        ans.Insert(((sum / 2) - 1), a*(-1));
      }
      else
      {

/* If the current time instance is even
            and sum is odd than it takes
            2 more steps and few
            negations in previous elements
            to reach there. */

        sum -= n;
        if (sum % 2 != 0)
        {
          sum--;
          ans.Add(sign * i);
          ans.Add(sign * -1 * (i + 1));
        }
        ans.Insert((sum / 2) - 1, ans[(sum / 2) - 1] * -1);
      }
    }
    return ans;
  }

/*  Driver Program*/

  public static void Main(String[] args)
  {
    int n = 20;
    if (n == 0)
      Console.Write("Minimum number of Steps: 0\nStep sequence:\n0");
    else
    {
      List<int> a = find(n);
      Console.Write("Minimum number of Steps: " + 
                    a.Count+ "\nStep sequence:\n");
      foreach (int i in a)
        Console.Write(i + " ");
    }
  }
}

/*C# program to conFactor Tree for
a given number*/

using System;
using System.Collections.Generic;
public class GFG
{

/*  Tree node*/

  public
    class Node
    {
      public
        Node left, right;
      public
        int key;
    };
  static Node root;

/*  Utility function to create a new tree Node*/

  static Node newNode(int key)
  {
    Node temp = new Node();
    temp.key = key;
    temp.left = temp.right = null;
    return temp;
  }

/*  Constructs factor tree for given value and stores
  root of tree at given reference.*/

  static Node createFactorTree(Node node_ref, int v)
  {
    (node_ref) = newNode(v);

/*    the number is factorized*/

    for (int i = 2 ; i < v/2 ; i++)
    {
      if (v % i != 0)
        continue;

/*      If we found a factor, we conleft
      and right subtrees and return. Since we
      traverse factors starting from smaller
      to greater, left child will always have
      smaller factor*/

      node_ref.left = createFactorTree(((node_ref).left), i);
      node_ref.right =  createFactorTree(((node_ref).right), v/i);
      return node_ref;
    }
    return node_ref;
  }

/*  Iterative method to find the height of Binary Tree*/

  static void printLevelOrder(Node root)
  {

/*    Base Case*/

    if (root == null)  return;
    Queue<Node > q = new Queue<Node>();
    q.Enqueue(root);
    while (q.Count != 0)
    {

/*      Print front of queue and remove
      it from queue*/

      Node node = q.Peek();
      Console.Write(node.key + " ");
      q.Dequeue();
      if (node.left != null)
        q.Enqueue(node.left);
      if (node.right != null)
        q.Enqueue(node.right);
    }
  }

/*  Driver program*/

  public static void Main(String[] args)
  {

/*    int val = 48;sample value*/

    root = null;
    root = createFactorTree(root, val);
    Console.WriteLine("Level order traversal of "+
                      "constructed factor tree");
    printLevelOrder(root);
  }
}

/*C# program to find number of 
full binary tree such that each
node is product of its children.*/

using System;
class GFG
{

/*    Return the number of all possible full binary
    tree with given product property.*/

    static int numoffbt(int []arr, int n)
    {

/*        Finding the minimum and maximum values in
        given array.*/

        int maxvalue = -2147483647, minvalue = 2147483647;
        for (int i = 0; i < n; i++)
        {
            maxvalue = Math.Max(maxvalue, arr[i]);
            minvalue = Math.Min(minvalue, arr[i]);
        }
        int []mark=new int[maxvalue + 2];
        int []value=new int[maxvalue + 2];
        for(int i = 0;i < maxvalue + 2; i++)
            {
                mark[i]=0;
                value[i]=0;
            }

/*        Marking the presence of each array element
        and initialising the number of possible
        full binary tree for each integer equal
        to 1 because single node will also
        contribute as a full binary tree.*/

        for (int i = 0; i < n; i++)
        {
            mark[arr[i]] = 1;
            value[arr[i]] = 1;
        }

/*        From minimum value to maximum value of array
        finding the number of all possible Full
        Binary Trees.*/

        int ans = 0;
        for (int i = minvalue; i <= maxvalue; i++)
        {

/*            Find if value present in the array*/

            if (mark[i] != 0)
            {

/*                For each multiple of i, less than
                equal to maximum value of array*/

                for (int j = i + i;
                     j <= maxvalue && j/i <= i; j += i)
                {

/*                    If multiple is not present in the
                    array then continue.*/

                    if (mark[j] == 0)
                        continue;

/*                    Finding the number of possible Full
                    binary trees for multiple j by
                    multiplying number of possible Full
                    binary tree from the number i and
                    number of possible Full binary tree
                    from i/j.*/

                    value[j] = value[j] + (value[i] * value[j/i]);

/*                    Condition for possiblity when left
                    chid became right child and vice versa.*/

                    if (i != j/i)
                        value[j] = value[j] + (value[i] * value[j/i]);
                }
            }
            ans += value[i];
        }
        return ans;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = { 2, 3, 4, 6 };
        int n = arr.Length;
        Console.Write(numoffbt(arr, n));
    }
}

/*C# implementation to find number of 
subtrees having odd count of even numbers */

using System;
class GFG 
{

/* A binary tree Node */

public class Node 
{ 
    public int data; 
    public Node left, right; 
}

/* Helper function that allocates 
a new Node with the given data and
NULL left and right pointers. */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = null;
    node.right = null; 
    return(node); 
}

public class P
{
    public int pcount = 0;
}

/*Returns count of subtrees 
having odd count of even numbers*/


static int countRec(Node root, P p) 
{

/*    base condition */

    if (root == null) 
        return 0;

/*    count even nodes in left subtree */

    int c = countRec(root.left, p);

/*    Add even nodes in right subtree */

    c += countRec(root.right, p);

/*    Check if root data is an even number */

    if (root.data % 2 == 0) 
        c += 1;

/*    if total count of even numbers 
    for the subtree is odd */

    if (c % 2 != 0) 
        (p.pcount)++;

/*    Total count of even nodes of the subtree */

    return c; 
}

/*A wrapper over countRec() */

static int countSubtrees(Node root) 
{ 
    P p = new P(); 
    countRec(root, p); 
    return p.pcount; 
}

/*Driver Code*/

public static void Main(String[] args) 
{

/*    binary tree formation */

    Node root = newNode(2);

/*         2         */

    root.left     = newNode(1);

/*     /     \     */

    root.right     = newNode(3);

/*     1     3     */

    root.left.left = newNode(4);

/* / \     / \ */

    root.left.right = newNode(10);

/* 4 10 8     5 */

    root.right.left = newNode(8);

/*     /             */

    root.right.right = newNode(5);

/*     6             */

    root.left.right.left = newNode(6); 
    Console.WriteLine("Count = " + 
                       countSubtrees(root)); 
} 
}

/*C# program to find distance of a given
node from root.*/

using System;
class GfG
{

/*    A Binary Tree Node*/

    class Node
    {
        public int data;
        public Node left, right;
    }

/*    A utility function to create 
    a new Binary Tree Node*/

    static Node newNode(int item)
    {
        Node temp = new Node();
        temp.data = item;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    Returns -1 if x doesn't exist in tree. Else
    returns distance of x from root*/

    static int findDistance(Node root, int x)
    {

/*        Base case*/

        if (root == null)
        return -1;

/*        Initialize distance*/

        int dist = -1;

/*        Check if x is present at root or in left
        subtree or right subtree.*/

        if ((root.data == x) ||
            (dist = findDistance(root.left, x)) >= 0 ||
            (dist = findDistance(root.right, x)) >= 0)
            return dist + 1;
        return dist;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node root = newNode(5);
        root.left = newNode(10);
        root.right = newNode(15);
        root.left.left = newNode(20);
        root.left.right = newNode(25);
        root.left.right.right = newNode(45);
        root.right.left = newNode(30);
        root.right.right = newNode(35);
        Console.WriteLine(findDistance(root, 45));
    }
}

/*C# program to print right sibling of a node*/

using System;
public class Right_Sibling {

/*    A Binary Tree Node*/

    public class Node {
        public int data;
        public Node left, right, parent;

/*        Constructor*/

        public Node(int data, Node parent)
        {
            this.data = data;
            left = null;
            right = null;
            this.parent = parent;
        }
    }

/*    Method to find right sibling*/

    public static Node findRightSibling(Node node, int level)
    {
        if (node == null || node.parent == null) {
            return null;
        }

/*        GET Parent pointer whose right child is not
        a parent or itself of this node. There might
        be case when parent has no right child, but,
        current node is left child of the parent
        (second condition is for that).*/

        while (node.parent.right == node
               || (node.parent.right == null
                   && node.parent.left == node)) {
            if (node.parent == null
                || node.parent.parent == null) {
                return null;
            }
            node = node.parent;
            level--;
        }

/*        Move to the required child, where right sibling
        can be present*/

        node = node.parent.right;

/*        find right sibling in the given subtree(from current
        node), when level will be 0*/

        while (level < 0) {

/*            Iterate through subtree*/

            if (node.left != null) {
                node = node.left;
            }
            else if (node.right != null) {
                node = node.right;
            }
            else {

/*                if no child are there, we cannot have right
                sibling in this path*/

                break;
            }
            level++;
        }
        if (level == 0) {
            return node;
        }

/*        This is the case when we reach 9 node in the tree,
        where we need to again recursively find the right
        sibling*/

        return findRightSibling(node, level);
    }

/*    Driver Program to test above functions*/

    public static void Main(string[] args)
    {
        Node root = new Node(1, null);
        root.left = new Node(2, root);
        root.right = new Node(3, root);
        root.left.left = new Node(4, root.left);
        root.left.right = new Node(6, root.left);
        root.left.left.left = new Node(7, root.left.left);
        root.left.left.left.left = new Node(10, root.left.left.left);
        root.left.right.right = new Node(9, root.left.right);
        root.right.right = new Node(5, root.right);
        root.right.right.right = new Node(8, root.right.right);
        root.right.right.right.right = new Node(12, root.right.right.right);

/*        passing 10*/

        Console.WriteLine(findRightSibling(root.left.left.left.left, 0).data);
    }
}

/* C# program to find next right of a given key
using preorder traversal */

using System;
class GfG
{
public class V
{
    public int value_level = 0;
}

/*A Binary Tree Node*/

public class Node
{
    public Node left, right;
    public int key;
}

/*Utility function to create a new tree node*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.key = key;
    temp.left = null;
    temp.right = null;
    return temp;
}

/*Function to find next node for given node
in same level in a binary tree by using
pre-order traversal*/

static Node nextRightNode(Node root, int k,
                            int level, V value)
{

/*    return null if tree is empty*/

    if (root == null)
        return null;

/*    if desired node is found, set
    value_level to current level*/

    if (root.key == k)
    {
        value.value_level = level;
        return null;
    }

/*    if value_level is already set, then current
    node is the next right node*/

    else if (value.value_level != 0)
    {
        if (level == value.value_level)
            return root;
    }

/*    recurse for left subtree by increasing level by 1*/

    Node leftNode = nextRightNode(root.left,
                            k, level + 1, value);

/*    if node is found in left subtree, return it*/

    if (leftNode != null)
        return leftNode;

/*    recurse for right subtree by
    increasing level by 1*/

    return nextRightNode(root.right, k,
                       level + 1, value);
}

/*Function to find next node of given node in the
same level in given binary tree*/

static Node nextRightNodeUtil(Node root, int k)
{
    V v = new V();
    return nextRightNode(root, k, 1, v);
}

/*A utility function to test above functions*/

static void test(Node root, int k)
{
    Node nr = nextRightNodeUtil(root, k);
    if (nr != null)
        Console.WriteLine("Next Right of " +
                            k + " is "+ nr.key);
    else
        Console.WriteLine("No next right node" +
                            " found for " + k);
}

/*Driver main*/

public static void Main(String[] args)
{

/*    Let us create binary tree given in the
    above example*/

    Node root = newNode(10);
    root.left = newNode(2);
    root.right = newNode(6);
    root.right.right = newNode(5);
    root.left.left = newNode(8);
    root.left.right = newNode(4);
    test(root, 10);
    test(root, 2);
    test(root, 6);
    test(root, 5);
    test(root, 8);
    test(root, 4);
}
}

/*C# program to find largest three elements
in a binary tree.*/

using System;
class GFG
{
public class Node
{
    public int data;
    public Node left;
    public Node right;
};
static int first, second, third;

/* Helper function that allocates
a new Node with the given data and
null left and right pointers. */

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = null;
    node.right = null;
    return (node);
}

/*function to find three largest element*/

static void threelargest(Node root)
{
    if (root == null)
        return;

/*    if data is greater than first large number
    update the top three list*/

    if (root.data > first)
    {
        third = second;
        second = first;
        first = root.data;
    }

/*    if data is greater than second large number
    and not equal to first update the bottom
    two list*/

    else if (root.data > second &&
             root.data != first)
    {
        third = second;
        second = root.data;
    }

/*    if data is greater than third large number
    and not equal to first & second update the
    third highest list*/

    else if (root.data > third &&
             root.data != first &&
             root.data != second)
        third = root.data;
    threelargest(root.left);
    threelargest(root.right);
}

/*Driver Code*/

public static void Main(String[] args)
{
    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    root.right.left = newNode(4);
    root.right.right = newNode(5);
    first = 0; second = 0; third = 0;
    threelargest(root);
    Console.WriteLine("three largest elements are " +
                       first + " " + second + " " + third);
}
}

/*C# code to Find maximum (or minimum) in
Binary Tree*/

using System;

/*A binary tree node*/

public class Node {
    public int data;
    public Node left, right;

/* Constructor that allocates a new
    node with the given data and NULL
    left and right pointers. */

    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}
public class BinaryTree {
    public Node root;

/*    Returns the max value in a binary tree*/

    public static int findMax(Node node)
    {

/*    Base case*/

        if (node == null) {
            return int.MinValue;
        }

/*    Return maximum of 3 values:
    1) Root's data 2) Max in Left Subtree
    3) Max in right subtree*/

        int res = node.data;
        int lres = findMax(node.left);
        int rres = findMax(node.right);
        if (lres > res) {
            res = lres;
        }
        if (rres > res) {
            res = rres;
        }
        return res;
    }

/* Driver code */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(2);
        tree.root.left = new Node(7);
        tree.root.right = new Node(5);
        tree.root.left.right = new Node(6);
        tree.root.left.right.left = new Node(1);
        tree.root.left.right.right = new Node(11);
        tree.root.right.right = new Node(9);
        tree.root.right.right.left = new Node(4);

/*        Function call*/

        Console.WriteLine("Maximum element is "
                          + BinaryTree.findMax(tree.root));
    }
}

/*C# program to extract leaf
nodes from binary tree
using double linked list*/

using System;

/*A binay tree node*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        right = left = null;
    }
}

/*Binary Tree class */


public class BinaryTree
{
    Node root;
    Node head; 
    Node prev;

/*    The main function that links
    the list list to be traversed*/

    public Node extractLeafList(Node root)
    {
        if (root == null)
            return null;
        if (root.left == null && root.right == null)
        {
            if (head == null)
            {
                head = root;
                prev = root;
            }
            else
            {
                prev.right = root;
                root.left = prev;
                prev = root;
            }
            return null;
        }
        root.left = extractLeafList(root.left);
        root.right = extractLeafList(root.right);
        return root;
    }

/*Utility function for printing tree in In-Order.*/

    void inorder(Node node)
    {
        if (node == null)
            return;
        inorder(node.left);
        Console.Write(node.data + " ");
        inorder(node.right);
    }

/*    Prints the DLL in both forward
    and reverse directions.*/

    public void printDLL(Node head)
    {
        Node last = null;
        while (head != null)
        {
            Console.Write(head.data + " ");
            last = head;
            head = head.right;
        }
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.right = new Node(6);
        tree.root.left.left.left = new Node(7);
        tree.root.left.left.right = new Node(8);
        tree.root.right.right.left = new Node(9);
        tree.root.right.right.right = new Node(10);
        Console.WriteLine("Inorder traversal of given tree is : ");
        tree.inorder(tree.root);
        tree.extractLeafList(tree.root);
        Console.WriteLine("");
        Console.WriteLine("Extracted double link list is : ");
        tree.printDLL(tree.head);
        Console.WriteLine("");
        Console.WriteLine("Inorder traversal of modified tree is : ");
        tree.inorder(tree.root);
    }
}

/*C# program to find minimum number of
iterations to pass information from
root to all nodes in an n-ary tree*/

using System;
using System.Collections.Generic;
class GFG
{

/*  No. of nodes*/

  public int N;

/*  Adjacency list containing
  list of children*/

  static List<List<int>> adj;
  public GFG(int N)
  {
    this.N = N;
    adj = new List<List<int>>(N);
    for (int i = 0; i < N; i++)
      adj.Add(new List<int>());
  }

/*  function to add a child w to v*/

  void addChild(int v, int w)
  {
    adj[v].Add(w);
  }

/*  Main function to find the
  minimum iterations*/

  private int getMinIteration()
  {

/*    Base case : if height = 0 or 1;*/

    if (N == 0 || N == 1)
      return 0;
    int[] mintItr = new int[N];

/*    Start Post Order Traversal from Root*/

    getMinIterUtil(0, mintItr);
    return mintItr[0];
  }

/* A recursive function to used by getMinIter().
    This function mainly does postorder traversal
    and get minimum iteration of all children
    of parent node, sort them in decreasing order
    and then get minimum iteration of parent node
    1. Get minItr(B) of all children (B) of a node (A)
    2. Sort all minItr(B) in descending order
    3. Get minItr of A based on all minItr(B)
        minItr(A) = child(A) -->> child(A)
        is children count of node A
        For children B from i = 0 to child(A)
                minItr(A) = max (minItr(A),
                                 minItr(B) + i + 1)
    Base cases would be:
    If node is leaf, minItr = 0
    If node's height is 1, minItr = children count
    */

  private void getMinIterUtil(int u, int[] minItr)
  {

/*    Base case : Leaf node*/

    if (adj[u].Count == 0)
      return;
    minItr[u] = adj[u].Count;
    int[] minItrTemp = new int[minItr[u]];
    int k = 0;
    foreach (int itr in adj[u])
    {
      int currentChild = (int) itr;
      getMinIterUtil(currentChild, minItr);
      minItrTemp[k++] = minItr[currentChild];
    }
    Array.Sort(minItrTemp);
    for(int i =0, j = minItrTemp.Length-1; i<j;i++,j--){
      int temp = minItrTemp[i];
      minItrTemp[i] = minItrTemp[j];
      minItrTemp[j] = temp;
    }
    for (k = 0; k < adj[u].Count; k++)
    {
      int temp = minItrTemp[k] + k + 1;
      minItr[u] = Math.Max(minItr[u], temp);
    }
  }

/*  Driver Code*/

  public static void Main(String []args)
  {

/*    TestCase1*/

    GFG testCase1 = new GFG(17);
    testCase1.addChild(0, 1);
    testCase1.addChild(0, 2);
    testCase1.addChild(0, 3);
    testCase1.addChild(0, 4);
    testCase1.addChild(0, 5);
    testCase1.addChild(0, 6);
    testCase1.addChild(1, 7);
    testCase1.addChild(1, 8);
    testCase1.addChild(1, 9);
    testCase1.addChild(4, 10);
    testCase1.addChild(4, 11);
    testCase1.addChild(6, 12);
    testCase1.addChild(7, 13);
    testCase1.addChild(7, 14);
    testCase1.addChild(10, 15);
    testCase1.addChild(11, 16);
    Console.WriteLine("TestCase 1 - Minimum Iteration: " +
                      testCase1.getMinIteration());

/*    TestCase2*/

    GFG testCase2 = new GFG(3);
    testCase2.addChild(0, 1);
    testCase2.addChild(0, 2);
    Console.WriteLine("TestCase 2 - Minimum Iteration: " +
                      testCase2.getMinIteration());

/*    TestCase3*/

    GFG testCase3 = new GFG(1);
    Console.WriteLine("TestCase 3 - Minimum Iteration: " +
                      testCase3.getMinIteration());

/*    TestCase4*/

    GFG testCase4 = new GFG(6);
    testCase4.addChild(0, 1);
    testCase4.addChild(1, 2);
    testCase4.addChild(2, 3);
    testCase4.addChild(3, 4);
    testCase4.addChild(4, 5);
