/*C# code to demonstrate Graph representation
using LinkedList in C#*/

using System;
using System.Collections.Generic;
class Graph
{

/*    A utility function to add an edge in an
    undirected graph*/

    static void addEdge(LinkedList<int>[] adj,
                        int u, int v)
    {
        adj[u].AddLast(v);
        adj[v].AddLast(u);
    }

/*    A utility function to print the adjacency list
    representation of graph*/

    static void printGraph( LinkedList<int>[]  adj)
    {
        for (int i = 0; i < adj.Length; i++)
        {
            Console.WriteLine("\nAdjacency list of vertex " + i);
            Console.Write("head");
            foreach (var item in adj[i])
            {
                Console.Write(" -> " + item);
            }
            Console.WriteLine();
        }
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {

/*        Creating a graph with 5 vertices*/

        int V = 5;
        LinkedList<int>[] adj = new LinkedList<int>[V];
        for (int i = 0; i < V; i++)
            adj[i] = new LinkedList<int>();

/*        Adding edges one by one*/

        addEdge(adj, 0, 1);
        addEdge(adj, 0, 4);
        addEdge(adj, 1, 2);
        addEdge(adj, 1, 3);
        addEdge(adj, 1, 4);
        addEdge(adj, 2, 3);
        addEdge(adj, 3, 4);
        printGraph(adj);
        Console.ReadKey();
    }
}

/*C# program to find K-Cores of a graph*/

using System;
using System.Collections.Generic;
class GFG{

/*This class represents a undirected
graph using adjacency list
representation*/

public class Graph
{

/*    No. of vertices*/

    int V;

/*    Pointer to an array containing
    adjacency lists*/

    List<int>[] adj;
    public Graph(int V)
    {
        this.V = V;
        this.adj = new List<int>[V];
        for(int i = 0; i < V; i++)
            adj[i] = new List<int>();
    }

/*    Function to add an edge to graph*/

    public void addEdge(int u, int v)
    {
        this.adj[u].Add(v);
        this.adj[v].Add(u);
    }

/*    A recursive function to print DFS
    starting from v. It returns true
    if degree of v after processing
    is less than k else false
    It also updates degree of adjacent
    if degree of v is less than k. And
    if degree of a processed adjacent
    becomes less than k, then it reduces
    of degree of v also,*/

    bool DFSUtil(int v, bool[] visited,
                 int[] vDegree, int k)
    {

/*        Mark the current node as
        visited and print it*/

        visited[v] = true;

/*        Recur for all the vertices
        adjacent to this vertex*/

        foreach (int i in adj[v])
        {

/*            Degree of v is less than k,
            then degree of adjacent
            must be reduced*/

            if (vDegree[v] < k)
                vDegree[i]--;

/*            If adjacent is not
            processed, process it*/

            if (!visited[i])
            {

/*                If degree of adjacent after
                processing becomes less than
                k, then reduce degree of v also.*/

                DFSUtil(i, visited, vDegree, k);
            }
        }

/*        Return true if degree of
        v is less than k*/

        return (vDegree[v] < k);
    }

/*    Prints k cores of an undirected graph*/

    public void printKCores(int k)
    {

/*        INITIALIZATION
        Mark all the vertices as not
        visited and not processed.*/

        bool[] visited = new bool[V];
        bool[] processed = new bool[V];
        int mindeg = int.MaxValue;
        int startvertex = 0;

/*        Store degrees of all vertices*/

        int[] vDegree = new int[V];
        for(int i = 0; i < V; i++)
        {
            vDegree[i] = adj[i].Count;
            if (vDegree[i] < mindeg)
            {
                mindeg = vDegree[i];
                startvertex = i;
            }
        }
        DFSUtil(startvertex, visited, vDegree, k);

/*        DFS traversal to update degrees of all
        vertices.*/

        for(int i = 0; i < V; i++)
            if (!visited[i])
                DFSUtil(i, visited, vDegree, k);

/*        PRINTING K CORES*/

        Console.WriteLine("K-Cores : ");
        for(int v = 0; v < V; v++)
        {

/*            Only considering those vertices
            which have degree >= K after BFS*/

            if (vDegree[v] >= k)
            {
                Console.Write("\n " + v);

/*                Traverse adjacency list of v
                and print only those adjacent
                which have vDegree >= k after
                BFS.*/

                foreach(int i in adj[v])
                    if (vDegree[i] >= k)
                        Console.Write(" -> " + i);
            }
        }
    }
}

/*Driver Code*/

public static void Main(String[] args)
{

/*    Create a graph given in the
    above diagram*/

    int k = 3;
    Graph g1 = new Graph(9);
    g1.addEdge(0, 1);
    g1.addEdge(0, 2);
    g1.addEdge(1, 2);
    g1.addEdge(1, 5);
    g1.addEdge(2, 3);
    g1.addEdge(2, 4);
    g1.addEdge(2, 5);
    g1.addEdge(2, 6);
    g1.addEdge(3, 4);
    g1.addEdge(3, 6);
    g1.addEdge(3, 7);
    g1.addEdge(4, 6);
    g1.addEdge(4, 7);
    g1.addEdge(5, 6);
    g1.addEdge(5, 8);
    g1.addEdge(6, 7);
    g1.addEdge(6, 8);
    g1.printKCores(k);
    Console.WriteLine();
    Graph g2 = new Graph(13);
    g2.addEdge(0, 1);
    g2.addEdge(0, 2);
    g2.addEdge(0, 3);
    g2.addEdge(1, 4);
    g2.addEdge(1, 5);
    g2.addEdge(1, 6);
    g2.addEdge(2, 7);
    g2.addEdge(2, 8);
    g2.addEdge(2, 9);
    g2.addEdge(3, 10);
    g2.addEdge(3, 11);
    g2.addEdge(3, 12);
    g2.printKCores(k);
}
}

/*C# Program to determine level of each node 
and print level */

using System;
using System.Collections.Generic;
class GFG
{

/*function to determine level of each node starting 
from x using BFS */

static void printLevels(List<List<int>> graph, 
                                  int V, int x) 
{

/*    array to store level of each node */

    int []level = new int[V]; 
    Boolean []marked = new Boolean[V];

/*    create a queue */

    Queue<int> que = new Queue<int>();

/*    enqueue element x */

    que.Enqueue(x);

/*    initialize level of source node to 0 */

    level[x] = 0;

/*    marked it as visited */

    marked[x] = true;

/*    do until queue is empty */

    while (que.Count > 0) 
    {

/*        get the first element of queue */

        x = que.Peek();

/*        dequeue element */

        que.Dequeue();

/*        traverse neighbors of node x */

        for (int i = 0; i < graph[x].Count; i++) 
        {

/*            b is neighbor of node x */

            int b = graph[x][i];

/*            if b is not marked already */

            if (!marked[b])
            {

/*                enqueue b in queue */

                que.Enqueue(b);

/*                level of b is level of x + 1 */

                level[b] = level[x] + 1;

/*                mark b */

                marked[b] = true; 
            } 
        } 
    }

/*    display all nodes and their levels */

    Console.WriteLine("Nodes" + " " + "Level"); 
    for (int i = 0; i < V; i++) 
        Console.WriteLine(" " + i +" --> " + level[i]); 
}

/*Driver Code */

public static void Main(String []args)
{

/*    adjacency graph for tree */

    int V = 8; 
    List<List<int>> graph = new List<List<int>>(); 
    for(int i = 0; i < V + 1; i++)
        graph.Add(new List<int>());
    graph[0].Add(1); 
    graph[0].Add(2); 
    graph[1].Add(3); 
    graph[1].Add(4); 
    graph[1].Add(5); 
    graph[2].Add(5); 
    graph[2].Add(6); 
    graph[6].Add(7);

/*    call levels function with source as 0 */

    printLevels(graph, V, 0); 
} 
}

/*C# code to form binary palindrome*/

using System;
using System.Collections.Generic;
class GFG
{

/*function to apply DFS*/

static void dfs(int parent, int []ans, 
                List<int> []connectchars)
{

/*    set the parent marked*/

    ans[parent] = 1;

/*    if the node has not been visited set it and
    its children marked*/

    for (int i = 0; i < connectchars[parent].Count; i++) 
    {
        if (ans[connectchars[parent][i]] != 1)
            dfs(connectchars[parent][i], ans, connectchars);
    }
}
static void printBinaryPalindrome(int n, int k)
{
    int []arr = new int[n];
    int []ans = new int[n];

/*    link which digits must be equal*/

    List<int> []connectchars = new List<int>[k];
    for (int i = 0; i < k; i++)
        connectchars[i] = new List<int>();
    for (int i = 0; i < n; i++)
        arr[i] = i % k;

/*    connect the two indices*/

    for (int i = 0; i < n / 2; i++) 
    {
        connectchars[arr[i]].Add(arr[n - i - 1]);
        connectchars[arr[n - i - 1]].Add(arr[i]);
    }

/*    set everything connected to 
    first character as 1*/

    dfs(0, ans, connectchars);
    for (int i = 0; i < n; i++)
        Console.Write(ans[arr[i]]);
}

/*Driver code*/

public static void Main(String[] args)
{
    int n = 10, k = 4;
    printBinaryPalindrome(n, k);
}
}

/*C# Code For DFS for a n-ary tree (acyclic graph) 
represented as adjacency list */

using System;
using System.Collections.Generic;
public class GFG {

/*    DFS on tree */

    public static void dfs(List<int> []list, 
                            int node, int arrival) 
    {

/*        Printing traversed node */

        Console.WriteLine(node);

/*        Traversing adjacent edges */

        for (int i = 0; i < list[node].Count; i++) {

/*            Not traversing the parent node */

            if (list[node][i] != arrival) 
                dfs(list, list[node][i], node); 
        } 
    }

