    static int fib(int n)
    {
        if (n <= 1)
            return n;
        return fib(n - 1) + fib(n - 2);
    }

/*    function for finding number of
    vertices in fibonacci cube graph*/

    static int findVertices (int n)
    {

/*        return fibonacci number for
        f(n + 2)*/

        return fib(n + 2);
    }

