        Console.Write(findVertices(n));
    }
}

/*C# program to generate a graph for a
given fixed degrees*/

using System;
class GFG
{

/*A function to print the adjacency matrix.*/

static void printMat(int []degseq, int n)
{

/*    n is number of vertices*/

    int [,]mat = new int[n, n];
    for (int i = 0; i < n; i++) 
    {
        for (int j = i + 1; j < n; j++)
        {

/*            For each pair of vertex decrement
            the degree of both vertex.*/

            if (degseq[i] > 0 && degseq[j] > 0) 
            {
                degseq[i]--;
                degseq[j]--;
                mat[i, j] = 1;
                mat[j, i] = 1;
            }
        }
    }

/*    Print the result in specified format*/

    Console.Write("\n" + setw(3) + "     ");
    for (int i = 0; i < n; i++)
        Console.Write(setw(3) + "(" + i + ")");
    Console.Write("\n\n");
    for (int i = 0; i < n; i++)
    {
        Console.Write(setw(4) + "(" + i + ")");
        for (int j = 0; j < n; j++)
            Console.Write(setw(5) + mat[i, j]);
        Console.Write("\n");
    }
}
static String setw(int n)
{
    String space = "";
    while(n-- > 0)
        space += " ";
    return space;
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []degseq = { 2, 2, 1, 1, 1 };
    int n = degseq.Length;
    printMat(degseq, n);
}
}

/*C# program to find whether a universal sink 
exists in a directed graph */

using System;
using System.Collections.Generic;
class graph 
{ 
    int vertices, itr; 
    int[,] adjacency_matrix;

/*    constructor to initialize number of vertices and 
    size of adjacency matrix */

    public graph(int vertices) 
    { 
        this.vertices = vertices; 
        adjacency_matrix = new int[vertices, vertices]; 
    } 
    public void insert(int source, int destination) 
    {

/*        make adjacency_matrix[i,j] = 1 if there is 
        an edge from i to j */

        adjacency_matrix = 1; 
    } 
    public bool issink(int i) 
    { 
        for (int j = 0 ; j < vertices ; j++) 
        {

/*            if any element in the row i is 1, it means 
            that there is an edge emanating from the 
            vertex, which means it cannot be a sink */

            if (adjacency_matrix[i, j] == 1) 
                return false;

/*            if any element other than i in the column 
            i is 0, it means that there is no edge from 
            that vertex to the vertex we are testing 
            and hence it cannot be a sink */

            if (adjacency_matrix[j, i] == 0 && j != i) 
                return false; 
        }

/*        if none of the checks fails, return true */

        return true; 
    }

/*    we will eliminate n-1 non sink vertices so that 
    we have to check for only one vertex instead of 
    all n vertices */

    public int eliminate() 
    { 
        int i = 0, j = 0; 
        while (i < vertices && j < vertices) 
        {

/*            If the index is 1, increment the row we are 
            checking by 1 
            else increment the column */

            if (adjacency_matrix[i, j] == 1) 
                i = i + 1; 
            else
                j = j + 1; 
        }

/*        If i exceeds the number of vertices, it 
        means that there is no valid vertex in 
        the given vertices that can be a sink */

        if (i > vertices) 
            return -1; 
        else if (!issink(i)) 
            return -1; 
        else return i; 
    } 
}

/*Driver Code*/
public class Sink 
{ 
    public static void Main(String[] args)
    { 
        int number_of_vertices = 6; 
        graph g = new graph(number_of_vertices);

/*    input set 1 
        g.insert(1, 6); 
        g.insert(2, 6); 
        g.insert(3, 6); 
        g.insert(4, 6); 
        g.insert(5, 6); 
        input set 2 */

        g.insert(1, 6); 
        g.insert(2, 3); 
        g.insert(2, 4); 
        g.insert(4, 3); 
        g.insert(5, 3); 
        int vertex = g.eliminate();

/*        returns 0 based indexing of vertex. returns 
        -1 if no sink exits. 
        returns the vertex number-1 if sink is found */

        if (vertex >= 0) 
            Console.WriteLine("Sink found at vertex "
                                    + (vertex + 1)); 
        else
            Console.WriteLine("No Sink"); 
    } 
}

/*C# program to count number if sink nodes*/

using System;
class GFG
{

/*Return the number of Sink NOdes.*/

static int countSink(int n, int m, 
                     int []edgeFrom,
                     int []edgeTo)
{

/*    Array for marking the non-sink node.*/

    int []mark = new int[n + 1];

/*    Marking the non-sink node.*/

    for (int i = 0; i < m; i++)
        mark[edgeFrom[i]] = 1;

/*    Counting the sink nodes.*/

    int count = 0;
    for (int i = 1; i <= n ; i++)
        if (mark[i] == 0)
            count++;
    return count;
}

/*Driver Code*/

public static void Main(String[] args)
{
    int n = 4, m = 2;
    int []edgeFrom = { 2, 4 };
    int []edgeTo = { 3, 3 };
    Console.WriteLine(countSink(n, m, 
                      edgeFrom, edgeTo));
}
}

/*C# program to find size of 
subset of graph vertex such that 
each vertex has more than 1 color edges */

using System;
using System.Collections.Generic; 
class GFG 
{

/*    Number of vertices */

    static int N = 6;

/*    function to calculate max subset size */

    static int subsetGraph(int [,]C)
    {

/*        set for number of vertices */

        HashSet<int> vertices = new HashSet<int>();
        for (int i = 0; i < N; ++i) 
        {
            vertices.Add(i);
        }

/*        loop for deletion of vertex from set */

        while (vertices.Count != 0)
        {

/*            if subset has only 1 vertex return 0 */

            if (vertices.Count == 1)
            {
                return 1;
            }

/*            for each vertex iterate and keep removing 
            a vertix while we find a vertex with all 
            edges of same color. */

            Boolean someone_removed = false;
            foreach (int x in vertices) 
            {

/*                note down different color values 
                for each vertex */

                HashSet<int> values = new HashSet<int>();
                foreach (int y in vertices) 
                {
                    if (y != x) 
                    {
                        values.Add(C[x, y]);
                    }
                }

/*                if only one color is found 
                erase that vertex (bad vertex) */

                if (values.Count == 1) 
                {
                    vertices.Remove(x);
                    someone_removed = true;
                    break;
                }
            }

/*            If no vertex was removed in the 
            above loop. */

            if (!someone_removed) 
            {
                break;
            }
        }
        return (vertices.Count);
    }

/*    Driver code */

    public static void Main(String[] args)
    {
        int [,]C = {{0, 9, 2, 4, 7, 8},
                    {9, 0, 9, 9, 7, 9},
                    {2, 9, 0, 3, 7, 6},
                    {4, 9, 3, 0, 7, 1},
                    {7, 7, 7, 7, 0, 7},
                    {8, 9, 6, 1, 7, 0}};
        Console.WriteLine(subsetGraph(C));
    }
}

/*C# program to count number of edge in 
undirected graph*/

using System;
using System.Collections.Generic;

/*Adjacency list representation of graph*/

class Graph 
{
    public int V;
    public List<int>[] adj;
    public Graph(int V)
    {
        this.V = V;
        this.adj = new List<int>[V];
        for (int i = 0; i < V; i++)
            adj[i] = new List<int>();
    }

/*    add edge to graph*/

    public void addEdge(int u, int v)
    {
        adj[u].Add(v);
        adj[v].Add(u);
    }

/*    Returns count of edge in undirected graph*/

    public int countEdges()
    {
        int sum = 0;

/*        traverse all vertex*/

        for (int i = 0; i < V; i++)

/*            add all edge that are linked to the
            current vertex*/

            sum += adj[i].Count;

/*        The count of edge is always even because in
        undirected graph every edge is connected
        twice between two vertices*/

        return sum / 2;
    }
}
class GFG 
{

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int V = 9;
        Graph g = new Graph(V);

/*        making above uhown graph*/

        g.addEdge(0, 1);
        g.addEdge(0, 7);
        g.addEdge(1, 2);
        g.addEdge(1, 7);
        g.addEdge(2, 3);
        g.addEdge(2, 8);
        g.addEdge(2, 5);
        g.addEdge(3, 4);
        g.addEdge(3, 5);
        g.addEdge(4, 5);
        g.addEdge(5, 6);
        g.addEdge(6, 7);
        g.addEdge(6, 8);
        g.addEdge(7, 8);
        Console.WriteLine(g.countEdges());
    }
}

/*C# program to check whether input 
degree sequence is graph or tree */

using System;
class GFG 
{

/*    Function returns true for tree 
    false for graph */

    static bool check(int[] degree, int n)
    {

/*        Find sum of all degrees */

        int deg_sum = 0;
        for (int i = 0; i < n; i++) 
        {
            deg_sum += degree[i];
        }

/*        Graph is tree if sum is 
        equal to 2(n-1) */

        return (2 * (n - 1) == deg_sum);
    }

/*    Driver code */

    public static void Main()
    {
        int n = 5;
        int[] degree = {2, 3, 1, 1, 1};
        if (check(degree, n))
        {
            Console.WriteLine("Tree");
        } 
        else
        {
            Console.WriteLine("Graph");
        }
    }
}

/*A C# program to find size of minimum vertex
cover using Binary Search*/

using System;
class GFG
{
static readonly int maxn = 25;

/*Global array to store the graph
Note: since the array is global, all the
elements are 0 initially*/

static bool [,]gr = new bool[maxn, maxn];

/*Returns true if there is a possible subset
of size 'k' that can be a vertex cover*/

static bool isCover(int V, int k, int E)
{

/*    Set has first 'k' bits high initially*/

    int set = (1 << k) - 1;
    int limit = (1 << V);

/*    to mark the edges covered in each subset
    of size 'k'*/

    bool [,]vis = new bool[maxn, maxn];;
    while (set < limit)
    {

/*        Reset visited array for every subset
        of vertices*/

        for(int i = 0; i < maxn; i++)
        {
            for(int j = 0; j < maxn; j++)
            {
                vis[i, j] = false;
            }
        }

/*        set counter for number of edges covered
        from this subset of vertices to zero*/

        int cnt = 0;

/*        selected vertex cover is the indices
        where 'set' has its bit high*/

        for (int j = 1, v = 1 ; j < limit ; j = j << 1, v++)
        {
            if ((set & j) != 0)
            {

/*                Mark all edges emerging out of this
                vertex visited*/

                for (int co = 1 ; co <= V ; co++)
                {
                    if (gr[v, co] && !vis[v, co])
                    {
                        vis[v, co] = true;
                        vis[co, v] = true;
                        cnt++;
                    }
                }
            }
        }

/*        If the current subset covers all the edges*/

        if (cnt == E)
            return true;

/*        Generate previous combination with k bits high
        set & -set = (1 << last bit high in set)*/

        int cO = set & -set;
        int rO = set + cO;
        set = (((rO^set) >> 2) / cO) | rO;
    }
    return false;
}

/*Returns answer to graph stored in gr[,]*/

static int findMinCover(int n, int m)
{

/*    Binary search the answer*/

    int left = 1, right = n;
    while (right > left)
    {
        int mid = (left + right) >> 1;
        if (isCover(n, mid, m) == false)
            left = mid + 1;
        else
            right = mid;
    }

/*    at the end of while loop both left and
    right will be equal,/ as when they are
    not, the while loop won't exit the minimum
    size vertex cover = left = right*/

    return left;
}

/*Inserts an edge in the graph*/

static void insertEdge(int u, int v)
{
    gr[u, v] = true;

/*Undirected graph*/

gr[v, u] = true; 
}

/*Driver code*/

public static void Main(String[] args)
{

/*
            6
        /
        1 ----- 5 vertex cover = {1, 2}
        /|\
        3 | \
        \ | \
        2 4 */

    int V = 6, E = 6;
    insertEdge(1, 2);
    insertEdge(2, 3);
    insertEdge(1, 3);
    insertEdge(1, 4);
    insertEdge(1, 5);
    insertEdge(1, 6);
    Console.Write("Minimum size of a vertex cover = "
        + findMinCover(V, E) +"\n");

/*    Let us create another graph*/

    for(int i = 0; i < maxn; i++)
    {
        for(int j = 0; j < maxn; j++)
        {
            gr[i,j] = false;
        }
    }

/*
        2 ---- 4 ---- 6
        /|     |
        1 |     | vertex cover = {2, 3, 4}
        \ |     |
        3 ---- 5 */

    V = 6;
    E = 7;
    insertEdge(1, 2);
    insertEdge(1, 3);
    insertEdge(2, 3);
    insertEdge(2, 4);
    insertEdge(3, 5);
    insertEdge(4, 5);
    insertEdge(4, 6);
    Console.Write("Minimum size of a vertex cover = "
        + findMinCover(V, E) +"\n");
}
}

/*C# program to find the sum of dependencies*/

using System;
using System.Collections;
class GFG{

/*To add an edge*/

static void addEdge(ArrayList []adj, int u,
                                     int v)
{
    adj[u].Add(v);
}

/*Find the sum of all dependencies*/

static int findSum(ArrayList []adj, int V)
{
    int sum = 0;

/*    Just find the size at each 
    vector's index*/

    for(int u = 0; u < V; u++)
        sum += adj[u].Count;
    return sum;
}

