                  findSum(adj, V));
}
}

/*Recursive C# program to count number of nodes in
a linked list*/

using System;

/* Linked list Node*/

public class Node
{
    public int data;
    public Node next;
    public Node(int d)
    {
        data = d; next = null;
    }
}

/*Linked List class*/

public class LinkedList
{

/*head of list*/

Node head;

/* Inserts a new Node at front of the list. */

    public void push(int new_data)
    {

/* 1 & 2: Allocate the Node &
                Put in the data*/

        Node new_node = new Node(new_data);

/* 3. Make next of new Node as head */

        new_node.next = head;

/* 4. Move the head to point to new Node */

        head = new_node;
    }

/* Returns count of nodes in linked list */

    public int getCountRec(Node node)
    {

/*        Base case*/

        if (node == null)
            return 0;

/*        Count is this node plus rest of the list*/

        return 1 + getCountRec(node.next);
    }

/* Wrapper over getCountRec() */

    public int getCount()
    {
        return getCountRec(head);
    }

/* Driver program to test above functions. Ideally
    this function should be in a separate user class.
    It is kept here to keep code compact */

    public static void Main(String[] args)
    {

/* Start with the empty list */

        LinkedList llist = new LinkedList();
        llist.push(1);
        llist.push(3);
        llist.push(1);
        llist.push(2);
        llist.push(1);
        Console.WriteLine("Count of nodes is " +
                        llist.getCount());
    }
}

/*C# program to count occurrences in
a linked list using recursion*/

using System;

/*Represents node of a linkedlist*/

public class Node {
    public int data;
    public Node next;
    public Node(int val)
    {
        data = val;
        next = null;
    }
}
class GFG {

/*    global variable for counting frequeancy of
    given element k*/

    static int frequency = 0;

/* Given a reference (pointer to pointer) to the head
    of a list and an int, push a new node on the front
    of the list. */

    static Node push(Node head, int new_data)
    {

/*        allocate node*/

        Node new_node = new Node(new_data);

/*        link the old list off the new node*/

        new_node.next = head;

/*        move the head to point to the new node*/

        head = new_node;
        return head;
    }

/* Counts the no. of occurrences of a node
    (search_for) in a linked list (head)*/

    static int count(Node head, int key)
    {
        if (head == null)
            return frequency;
        if (head.data == key)
            frequency++;
        return count(head.next, key);
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {

/*        Start with the empty list*/

        Node head = null;

/* Use push() to construct below list
        1->2->1->3->1 */

        head = push(head, 1);
        head = push(head, 3);
        head = push(head, 1);
        head = push(head, 2);
        head = push(head, 1);

/* Check the count function */

        Console.Write("count of 1 is " + count(head, 1));
    }
}

/*C# program to detect loop in a linked list*/

using System;
class GFG{

/*Link list node*/

class Node
{
    public int data;
    public Node next;
    public int flag;
};
static Node push(Node head_ref, int new_data)
{

/*    Allocate node*/

    Node new_node = new Node();

/*    Put in the data*/

    new_node.data = new_data;
    new_node.flag = 0;

/*    Link the old list off the new node*/

    new_node.next = head_ref;

/*    Move the head to point to the new node*/

    head_ref = new_node;
    return head_ref;
}

/*Returns true if there is a loop in linked
list else returns false.*/

static bool detectLoop(Node h)
{
    while (h != null)
    {

/*        If this node is already traverse
        it means there is a cycle
        (Because you we encountering the
        node for the second time).*/

        if (h.flag == 1)
            return true;

/*        If we are seeing the node for
        the first time, mark its flag as 1*/

        h.flag = 1;
        h = h.next;
    }
    return false;
}

/*Driver code*/

public static void Main(string[] args)
{

/*    Start with the empty list*/

    Node head = null;
    head = push(head, 20);
    head = push(head, 4);
    head = push(head, 15);
    head = push(head, 10);

/*    Create a loop for testing*/

    head.next.next.next.next = head;
    if (detectLoop(head))
        Console.Write("Loop found");
    else
        Console.Write("No Loop");
}
}

/*C# program to detect loop in a linked list*/

using System;
public class LinkedList {

/*head of list*/

Node head;

/* Linked list Node*/

    public class Node {
        public int data;
        public Node next;
        public Node(int d)
        {
            data = d;
            next = null;
        }
    }

/* Inserts a new Node at front of the list. */

    public void push(int new_data)
    {

/* 1 & 2: Allocate the Node &
                Put in the data*/

        Node new_node = new Node(new_data);

/* 3. Make next of new Node as head */

        new_node.next = head;

/* 4. Move the head to point to new Node */

        head = new_node;
    }
    Boolean detectLoop()
    {
        Node slow_p = head, fast_p = head;
        while (slow_p != null && fast_p != null
               && fast_p.next != null) {
            slow_p = slow_p.next;
            fast_p = fast_p.next.next;
            if (slow_p == fast_p) {
                return true;
            }
        }
        return false;
    }

/* Driver code */

    public static void Main(String[] args)
    {

/* Start with the empty list */

        LinkedList llist = new LinkedList();
        llist.push(20);
        llist.push(4);
        llist.push(15);
        llist.push(10);

/*Create loop for testing */

        llist.head.next.next.next.next = llist.head;
        Boolean found = llist.detectLoop();
        if (found) {
            Console.WriteLine("Loop Found");
        }
        else {
            Console.WriteLine("No Loop");
        }
    }
}

/*C# program to return first node of loop*/

using System;
public class GFG {
    public class Node {
        public int key;
        public Node next;
    };
    static Node newNode(int key)
    {
        Node temp = new Node();
        temp.key = key;
        temp.next = null;
        return temp;
    }

/*    A utility function to print a linked list*/

    static void printList(Node head)
    {
        while (head != null) {
            Console.Write(head.key + " ");
            head = head.next;
        }
        Console.WriteLine();
    }

/*    Function to detect first node of loop
    in a linked list that may contain loop*/

    static Boolean detectLoop(Node head)
    {

/*        Create a temporary node*/

        Node temp = new Node();
        while (head != null) {

/*            This condition is for the case
            when there is no loop*/

            if (head.next == null) {
                return false;
            }

/*            Check if next is already
            pointing to temp*/

            if (head.next == temp) {
                return true;
            }

/*            Store the pointer to the next node
            in order to get to it in the next step*/

            Node nex = head.next;

/*            Make next point to temp*/

            head.next = temp;

/*            Get to the next node in the list*/

            head = nex;
        }
        return false;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node head = newNode(1);
        head.next = newNode(2);
        head.next.next = newNode(3);
        head.next.next.next = newNode(4);
        head.next.next.next.next = newNode(5);

/*        Create a loop for testing(5 is pointing to 3)*/

        head.next.next.next.next.next = head.next.next;
        Boolean found = detectLoop(head);
        if (found) {
            Console.WriteLine("Loop Found");
        }
        else {
            Console.WriteLine("No Loop");
        }
    }
}

/*C# program to return first node of loop*/

using System;
public class GFG
{
  public
    class Node
    {
      public
        int key;
      public
        Node next;
    };
  static Node newNode(int key)
  {
    Node temp = new Node();
    temp.key = key;
    temp.next = null;
    return temp;
  }

/*  A utility function to print a linked list*/

  static void printList(Node head)
  {
    while (head != null)
    {
      Console.Write(head.key + " ");
      head = head.next;
    }
    Console.WriteLine();
  }

/*returns distance between first and last node every time
 * last node moves forwars*/

  static int distance(Node first, Node last)
  {

/*counts no of nodes between first and last*/

    int counter = 0;
    Node curr;
    curr = first;
    while (curr != last)
    {
      counter += 1;
      curr = curr.next;
    }
    return counter + 1;
  }

/*  Function to detect first node of loop
  in a linked list that may contain loop*/

  static bool detectLoop(Node head)
  {

/*    Create a temporary node*/

    Node temp = new Node();
    Node first, last;

/*first always points to head*/

    first = head;

/*last pointer initially points to head*/

    last = head;

/*current_length stores no of nodes between current
     * position of first and last*/

    int current_length = 0;

/*current_length stores no of nodes between previous
     * position of first and last*/

    int prev_length = -1;
    while (current_length > prev_length && last != null)
    {

/*      set prev_length to current length then update the
      current length*/

      prev_length = current_length;

/*      distance is calculated*/

      current_length = distance(first, last);

/*      last node points the next node*/

      last = last.next;
    }
    if (last == null)
    {
      return false;
    }
    else
    {
      return true;
    }
  }

/* Driver program to test above function*/

  public static void Main(String[] args)
  {
    Node head = newNode(1);
    head.next = newNode(2);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    head.next.next.next.next = newNode(5);

/* Create a loop for testing(5 is pointing to 3) */

    head.next.next.next.next.next = head.next.next;
    bool found = detectLoop(head);
    if (found)
      Console.Write("Loop Found");
    else
      Console.Write("No Loop Found");
  }
}

/* C# program to check if linked list is palindrome */

using System;
class LinkedList {

/* Linked list Node*/

    public class Node {
        public char data;
        public Node next;
        public Node(char d)
        {
            data = d;
            next = null;
        }
    }

/*head of list*/

Node head; 
    Node slow_ptr, fast_ptr, second_half;

/* Function to check if given linked list is
       palindrome or not */

    Boolean isPalindrome(Node head)
    {
        slow_ptr = head;
        fast_ptr = head;
        Node prev_of_slow_ptr = head;

/*To handle odd size list*/

Node midnode = null;

/*initialize result*/

Boolean res = true; 
        if (head != null && head.next != null) {

/* Get the middle of the list. Move slow_ptr by 1
               and fast_ptrr by 2, slow_ptr will have the middle
               node */

            while (fast_ptr != null && fast_ptr.next != null) {
                fast_ptr = fast_ptr.next.next;

/*We need previous of the slow_ptr for
                  linked lists  with odd elements */

                prev_of_slow_ptr = slow_ptr;
                slow_ptr = slow_ptr.next;
            }

/* fast_ptr would become NULL when there are even elements
               in the list and not NULL for odd elements. We need to skip 
               the middle node for odd case and store it somewhere so that
               we can restore the original list */

            if (fast_ptr != null) {
                midnode = slow_ptr;
                slow_ptr = slow_ptr.next;
            }

/*            Now reverse the second half and compare it with first half*/

            second_half = slow_ptr;

/*NULL terminate first half*/

prev_of_slow_ptr.next = null;

/*Reverse the second half*/

reverse();

/*compare*/

res = compareLists(head, second_half);

/* Construct the original list back */

/*Reverse the second half again*/

reverse(); 
            if (midnode != null) {

/*                If there was a mid node (odd size case) which
                was not part of either first half or second half.*/

                prev_of_slow_ptr.next = midnode;
                midnode.next = second_half;
            }
            else
                prev_of_slow_ptr.next = second_half;
        }
        return res;
    }

/* Function to reverse the linked list  Note that this
       function may change the head */

    void reverse()
    {
        Node prev = null;
        Node current = second_half;
        Node next;
        while (current != null) {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }
        second_half = prev;
    }

/* Function to check if two input lists have same data*/

    Boolean compareLists(Node head1, Node head2)
    {
        Node temp1 = head1;
        Node temp2 = head2;
        while (temp1 != null && temp2 != null) {
            if (temp1.data == temp2.data) {
                temp1 = temp1.next;
                temp2 = temp2.next;
            }
            else
                return false;
        }

/* Both are empty reurn 1*/

        if (temp1 == null && temp2 == null)
            return true;

/* Will reach here when one is NULL
           and other is not */

        return false;
    }

/* Push a node to linked list. Note that this function
       changes the head */

    public void push(char new_data)
    {

/* Allocate the Node &
           Put in the data */

        Node new_node = new Node(new_data);

/* link the old list off the new one */

        new_node.next = head;

/* Move the head to point to new Node */

        head = new_node;
    }

/*    A utility function to print a given linked list*/

    void printList(Node ptr)
    {
        while (ptr != null) {
            Console.Write(ptr.data + "->");
            ptr = ptr.next;
        }
        Console.WriteLine("NULL");
    }

/* Driver program to test the above functions */

    public static void Main(String[] args)
    {

/* Start with the empty list */

        LinkedList llist = new LinkedList();
        char[] str = { 'a', 'b', 'a', 'c', 'a', 'b', 'a' };
        for (int i = 0; i < 7; i++) {
            llist.push(str[i]);
            llist.printList(llist.head);
            if (llist.isPalindrome(llist.head) != false) {
                Console.WriteLine("Is Palindrome");
                Console.WriteLine("");
            }
            else {
                Console.WriteLine("Not Palindrome");
                Console.WriteLine("");
            }
        }
    }
}

/*C# program for the above approach*/

using System;
using System.Collections.Generic;
public class Node
{
    public int data;
    public Node next;
    public Node()
    {
        data = 0;
        next = null;
    }
}
public class GFG
{

/* Function to insert a node at
   the beginging of the linked
 * list */

    static Node push(Node head_ref, int new_data)
    {

/* allocate node */

        Node new_node = new Node();

/* put in the data */

        new_node.data = new_data;

/* link the old list off
        the new node */

        new_node.next = (head_ref);

/* move the head to point
        to the new node */

        head_ref = new_node;
        return head_ref;
    }

/* Function to print nodes
    in a given linked list */

    static void printList(Node node)
    {
        while (node != null)
        {
            Console.Write(node.data + " ");
            node = node.next;
        }
    }

/*    Function to remove duplicates*/

    static void removeDuplicates(Node head)
    {
        Dictionary<int, bool> track = new Dictionary<int, bool>();
        Node temp = head;
        while(temp != null)
        {
            if(!track.ContainsKey(temp.data))
            {
                Console.Write(temp.data + " ");
                track.Add(temp.data , true);
            }
            temp = temp.next;
        }
    }

/*    Driver Code*/

    static public void Main ()
    {
        Node head = null;

/* Created linked list will be
        11->11->11->13->13->20 */

        head = push(head, 20);
        head = push(head, 13);
        head = push(head, 13);
        head = push(head, 11);
        head = push(head, 11);
        head = push(head, 11);
        Console.Write("Linked list before duplicate removal ");
        printList(head);
        Console.Write("\nLinked list after duplicate removal  ");
        removeDuplicates(head);
    }
}

/*C# program to swap two given
nodes of a linked list*/

using System;
class Node {
    public int data;
    public Node next;
    public Node(int d)
    {
        data = d;
        next = null;
    }
}
public class LinkedList {

/*head of list*/

Node head;

/* Function to swap Nodes x and y in
    linked list by changing links */

    public void swapNodes(int x, int y)
    {

/*        Nothing to do if x and y are same*/

        if (x == y)
            return;

/*        Search for x (keep track of prevX and CurrX)*/

        Node prevX = null, currX = head;
        while (currX != null && currX.data != x) {
            prevX = currX;
            currX = currX.next;
        }

/*        Search for y (keep track of prevY and currY)*/

        Node prevY = null, currY = head;
        while (currY != null && currY.data != y) {
            prevY = currY;
            currY = currY.next;
        }

/*        If either x or y is not present, nothing to do*/

        if (currX == null || currY == null)
            return;

/*        If x is not head of linked list*/

        if (prevX != null)
            prevX.next = currY;

/*make y the new head*/

else 
            head = currY;

/*        If y is not head of linked list*/

        if (prevY != null)
            prevY.next = currX;

/*make x the new head*/

else 
            head = currX;

/*        Swap next pointers*/

        Node temp = currX.next;
        currX.next = currY.next;
        currY.next = temp;
    }

/* Function to add Node at beginning of list. */

    public void push(int new_data)
    {

/* 1. alloc the Node and put the data */

        Node new_Node = new Node(new_data);

/* 2. Make next of new Node as head */

        new_Node.next = head;

/* 3. Move the head to point to new Node */

        head = new_Node;
    }

/* This function prints contents of linked list
    starting from the given Node */

    public void printList()
    {
        Node tNode = head;
        while (tNode != null) {
            Console.Write(tNode.data + " ");
            tNode = tNode.next;
        }
    }

/* Driver code */

    public static void Main(String[] args)
    {
        LinkedList llist = new LinkedList();

/* The constructed linked list is:
            1->2->3->4->5->6->7 */

        llist.push(7);
        llist.push(6);
        llist.push(5);
        llist.push(4);
        llist.push(3);
        llist.push(2);
        llist.push(1);
        Console.Write(
            "\n Linked list before calling swapNodes() ");
        llist.printList();
        llist.swapNodes(4, 3);
        Console.Write(
            "\n Linked list after calling swapNodes() ");
        llist.printList();
    }
}

/*C# program to get intersection point of two linked list*/

using System;
using System.Collections.Generic; 
public class Node 
{
    public int data;
    public Node next;
    public Node(int d)
    {
        data = d;
        next = null;
    }
}
public class LinkedListIntersect
{
    public static void Main(String[] args)
    {

/*        list 1*/

        Node n1 = new Node(1);
        n1.next = new Node(2);
        n1.next.next = new Node(3);
        n1.next.next.next = new Node(4);
        n1.next.next.next.next = new Node(5);
        n1.next.next.next.next.next = new Node(6);
        n1.next.next.next.next.next.next = new Node(7);

/*        list 2*/

        Node n2 = new Node(10);
        n2.next = new Node(9);
        n2.next.next = new Node(8);
        n2.next.next.next = n1.next.next.next;
        Print(n1);
        Print(n2);
        Console.WriteLine(MegeNode(n1, n2).data);
    }

/*    function to print the list*/

    public static void Print(Node n)
    {
        Node cur = n;
        while (cur != null) 
        {
            Console.Write(cur.data + " ");
            cur = cur.next;
        }
        Console.WriteLine();
    }

/*    function to find the intersection of two node*/

    public static Node MegeNode(Node n1, Node n2)
    {

/*        define hashset*/

        HashSet<Node> hs = new HashSet<Node>();
        while (n1 != null) 
        {
            hs.Add(n1);
            n1 = n1.next;
        }
        while (n2 != null)
        {
            if (hs.Contains(n2)) 
            {
                return n2;
            }
            n2 = n2.next;
        }
        return null;
    }
}

/*C# program to check if
linked list is circular*/

using System;
public class GFG
{

/* Link list Node */

public class Node
{
    public int data;
    public Node next;
}

/*This function returns true if given linked
list is circular, else false. */

static bool isCircular( Node head)
{

/*    An empty linked list is circular*/

    if (head == null)
    return true;

/*    Next of head*/

    Node node = head.next;

/*    This loop would stop in both cases (1) If
    Circular (2) Not circular*/

    while (node != null && node != head)
    node = node.next;

/*    If loop stopped because of circular
    condition*/

    return (node == head);
}

/*Utility function to create a new node.*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.next = null;
    return temp;
}

/* Driver code*/

public static void Main(String []args)
{

/* Start with the empty list */

    Node head = newNode(1);
    head.next = newNode(2);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    Console.Write(isCircular(head)? "Yes\n" :
                    "No\n" );

/*    Making linked list circular*/

    head.next.next.next.next = head;
    Console.Write(isCircular(head)? "Yes\n" :
                    "No\n" );
}
}

/*C# Code to find the last man Standing*/

using System;
public class GFG {

/*    Node class to store data*/

    class Node
    {
        public int data ;
        public Node next;
        public Node( int data )
        {
            this.data = data;
        }
    }

/* Function to find the only person left
    after one in every m-th node is killed
    in a circle of n nodes */

    static void getJosephusPosition(int m, int n)
    {

/*        Create a circular linked list of
        size N.*/

        Node head = new Node(1);
        Node prev = head;
        for(int i = 2; i <= n; i++)
        {
            prev.next = new Node(i);
            prev = prev.next;
        }

/*        Connect last node to first*/

        prev.next = head;

/* while only one node is left in the
        linked list*/

        Node ptr1 = head, ptr2 = head;
        while(ptr1.next != ptr1)
        {

/*            Find m-th node*/

            int count = 1;
            while(count != m)
            {
                ptr2 = ptr1;
                ptr1 = ptr1.next;
                count++;
            }

/* Remove the m-th node */

            ptr2.next = ptr1.next;
            ptr1 = ptr2.next;
        }
        Console.WriteLine ("Last person left standing " +
                "(Josephus Position) is " + ptr1.data);
    }

/* Driver program to test above functions */

     static public void Main(String []args)
    {
        int n = 14, m = 2;
        getJosephusPosition(m, n);
    }
}

/*C# program to swap kth node from the beginning with
kth node from the end*/

/*A Linked List node*/

using System;
public class Node {
    public int data;
    public Node next;
    public Node(int d)
    {
        data = d;
        next = null;
    }
}
public class LinkedList {
    Node head;

/* Utility function to insert
    a node at the beginning */

    void push(int new_data)
    {
        Node new_node = new Node(new_data);
        new_node.next = head;
        head = new_node;
    }

/* Utility function for displaying linked list */

    void printList()
    {
        Node node = head;
        while (node != null) {
            Console.Write(node.data + " ");
            node = node.next;
        }
        Console.WriteLine("");
    }

/* Utility function for calculating
    length of linked list */

    int countNodes()
    {
        int count = 0;
        Node s = head;
        while (s != null) {
            count++;
            s = s.next;
        }
        return count;
    }

/* Function for swapping kth nodes from
    both ends of linked list */

    void swapKth(int k)
    {

/*        Count nodes in linked list*/

        int n = countNodes();

/*        Check if k is valid*/

        if (n < k)
            return;

/*        If x (kth node from start) and y(kth node from end)
        are same*/

        if (2 * k - 1 == n)
            return;

/*        Find the kth node from beginning of linked list.
        We also find previous of kth node because we need
        to update next pointer of the previous.*/

        Node x = head;
        Node x_prev = null;
        for (int i = 1; i < k; i++) {
            x_prev = x;
            x = x.next;
        }

/*        Similarly, find the kth node from end and its
        previous. kth node from end is (n-k+1)th node
        from beginning*/

        Node y = head;
        Node y_prev = null;
        for (int i = 1; i < n - k + 1; i++) {
            y_prev = y;
            y = y.next;
        }

/*        If x_prev exists, then new next of it will be y.
        Consider the case when y->next is x, in this case,
        x_prev and y are same. So the statement
        "x_prev->next = y" creates a self loop. This self
        loop will be broken when we change y->next.*/

        if (x_prev != null)
            x_prev.next = y;

/*        Same thing applies to y_prev*/

        if (y_prev != null)
            y_prev.next = x;

/*        Swap next pointers of x and y. These statements
        also break self loop if x->next is y or y->next
        is x*/

        Node temp = x.next;
        x.next = y.next;
        y.next = temp;

/*        Change head pointers when k is 1 or n*/

        if (k == 1)
            head = y;
        if (k == n)
            head = x;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        LinkedList llist = new LinkedList();
        for (int i = 8; i >= 1; i--)
            llist.push(i);
        Console.Write("Original linked list: ");
        llist.printList();
        Console.WriteLine("");
        for (int i = 1; i < 9; i++) {
            llist.swapKth(i);
            Console.WriteLine("Modified List for k = " + i);
            llist.printList();
            Console.WriteLine("");
        }
    }
}

/*C# program to find a
pair with given sum x.*/

using System;
class GFG
{

/*    structure of node of
    doubly linked list*/

    class Node
    {
        public int data;
        public Node next, prev;
    };

/*    Function to find pair whose
    sum equal to given value x.*/

    static void pairSum( Node head, int x)
    {

/*        Set two pointers, first
        to the beginning of DLL
        and second to the end of DLL.*/

        Node first = head;
        Node second = head;
        while (second.next != null)
            second = second.next;

/*        To track if we find a pair or not*/

        bool found = false;

/*        The loop terminates when 
        they cross each other (second.next
        == first), or they become same
        (first == second)*/

        while (first != second && second.next != first)
        {

/*            pair found*/

            if ((first.data + second.data) == x)
            {
                found = true;
                Console.WriteLine( "(" + first.data +
                                    ", "+ second.data + ")" );

/*                move first in forward direction*/

                first = first.next;

/*                move second in backward direction*/

                second = second.prev;
            }
            else
            {
                if ((first.data + second.data) < x)
                    first = first.next;
                else
                    second = second.prev;
            }
        }

/*        if pair is not present*/

        if (found == false)
            Console.WriteLine("No pair found");
    }

/*    A utility function to insert
    a new node at the beginning
    of doubly linked list*/

    static Node insert(Node head, int data)
    {
        Node temp = new Node();
        temp.data = data;
        temp.next = temp.prev = null;
        if (head == null)
            (head) = temp;
        else
        {
            temp.next = head;
            (head).prev = temp;
            (head) = temp;
        }
        return temp;
    }

/*    Driver Code*/

    public static void Main(String []args)
    {
        Node head = null;
        head = insert(head, 9);
        head = insert(head, 8);
        head = insert(head, 6);
        head = insert(head, 5);
        head = insert(head, 4);
        head = insert(head, 2);
        head = insert(head, 1);
        int x = 7;
        pairSum(head, x);
    }
}

/*C# implementation to count triplets
in a sorted doubly linked list
whose sum is equal to a given value 'x'*/

using System;
class GFG
{

/*structure of node of doubly linked list*/

class Node
{
    public int data;
    public Node next, prev;
};

/*function to count pairs whose sum equal to given 'value'*/

static int countPairs(Node first, Node second, int value)
{
    int count = 0;

/*    The loop terminates when either of two pointers
    become null, or they cross each other (second.next
    == first), or they become same (first == second)*/

    while (first != null && second != null &&
        first != second && second.next != first) {

/*        pair found*/

        if ((first.data + second.data) == value) {

/*            increment count*/

            count++;

/*            move first in forward direction*/

            first = first.next;

/*            move second in backward direction*/

            second = second.prev;
        }

/*        if sum is greater than 'value'
        move second in backward direction*/

        else if ((first.data + second.data) > value)
            second = second.prev;

/*        else move first in forward direction*/

        else
            first = first.next;
    }

/*    required count of pairs*/

    return count;
}

/*function to count triplets in a sorted doubly linked list
whose sum is equal to a given value 'x'*/

static int countTriplets(Node head, int x)
{

/*    if list is empty*/

    if (head == null)
        return 0;
    Node current, first, last;
    int count = 0;

/*    get pointer to the last node of
    the doubly linked list*/

    last = head;
    while (last.next != null)
        last = last.next;

/*    traversing the doubly linked list*/

    for (current = head; current != null; current = current.next) {

/*        for each current node*/

        first = current.next;

/*        count pairs with sum(x - current.data) in the range
        first to last and add it to the 'count' of triplets*/

        count += countPairs(first, last, x - current.data);
    }

/*    required count of triplets*/

    return count;
}

/*A utility function to insert a new node at the
beginning of doubly linked list*/

static Node insert(Node head, int data)
{

/*    allocate node*/

    Node temp = new Node();

/*    put in the data*/

    temp.data = data;
    temp.next = temp.prev = null;
    if ((head) == null)
        (head) = temp;
    else {
        temp.next = head;
        (head).prev = temp;
        (head) = temp;
    }
    return head;
}

/*Driver program to test above*/

public static void Main(String[] args)
{

/*    start with an empty doubly linked list*/

    Node head = null;

/*    insert values in sorted order*/

    head = insert(head, 9);
    head = insert(head, 8);
    head = insert(head, 6);
    head = insert(head, 5);
    head = insert(head, 4);
    head = insert(head, 2);
    head = insert(head, 1);
    int x = 17;
    Console.Write("Count = "
        + countTriplets(head, x));
}
}

/*C# implementation to remove duplicates
from an unsorted doubly linked list*/

using System;
class GFG
{

/*a node of the doubly linked list*/

public class Node
{
    public int data;
    public Node next;
    public Node prev;
}

/*Function to delete a node in a Doubly Linked List.
head_ref -. pointer to head node pointer.
del -. pointer to node to be deleted.*/

static Node deleteNode(Node head_ref, Node del)
{

/*    base case*/

    if (head_ref == null || del == null)
        return head_ref;

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del.next;

/*    Change next only if node to be deleted
    is NOT the last node*/

    if (del.next != null)
        del.next.prev = del.prev;

/*    Change prev only if node to be deleted
    is NOT the first node*/

    if (del.prev != null)
        del.prev.next = del.next;
    return head_ref;
}

/*function to remove duplicates from
an unsorted doubly linked list*/

static Node removeDuplicates(Node head_ref)
{

/*    if DLL is empty or if it contains only
    a single node*/

    if ((head_ref) == null ||
        (head_ref).next == null)
        return head_ref;;
    Node ptr1, ptr2;

/*    pick elements one by one*/

    for (ptr1 = head_ref;
        ptr1 != null; ptr1 = ptr1.next)
    {
        ptr2 = ptr1.next;

/*        Compare the picked element with the
        rest of the elements*/

        while (ptr2 != null)
        {

/*            if duplicate, then delete it*/

            if (ptr1.data == ptr2.data)
            {

/*                store pointer to the node next to 'ptr2'*/

                Node next = ptr2.next;

/*                delete node pointed to by 'ptr2'*/

                head_ref = deleteNode(head_ref, ptr2);

/*                update 'ptr2'*/

                ptr2 = next;
            }

/*            else simply move to the next node*/

            else
                ptr2 = ptr2.next;
        }
    }
    return head_ref;
}

/*Function to insert a node at the beginning
of the Doubly Linked List*/

static Node push(Node head_ref, int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    since we are adding at the beginning,
    prev is always null*/

    new_node.prev = null;

/*    link the old list off the new node*/

    new_node.next = (head_ref);

/*    change prev of head node to new node*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*Function to print nodes in a
given doubly linked list*/

static void printList( Node head)
{

/*    if list is empty*/

    if (head == null)
        Console.Write("Doubly Linked list empty");
    while (head != null)
    {
        Console.Write( head.data + " ");
        head = head.next;
    }
}

/*Driver Code*/

public static void Main(String []args)
{
    Node head = null;

/*    Create the doubly linked list:
    8<->4<->4<->6<->4<->8<->4<->10<->12<->12*/

    head = push(head, 12);
    head = push(head, 12);
    head = push(head, 10);
    head = push(head, 4);
    head = push(head, 8);
    head = push(head, 4);
    head = push(head, 6);
    head = push(head, 4);
    head = push(head, 4);
    head = push(head, 8);
    Console.Write("Original Doubly linked list:\n");
    printList(head);

/* remove duplicate nodes */

    head=removeDuplicates(head);
    Console.Write("\nDoubly linked list after" +
                     " removing duplicates:\n");
    printList(head);
}
}

/*C# mplementation to remove duplicates
from an unsorted doubly linked list*/

using System;
using System.Collections.Generic;
class GFG
{

/*a node of the doubly linked list*/

public class Node
{
    public int data;
    public Node next;
    public Node prev;
};

/*Function to delete a node in a Doubly Linked List.
head_ref --> pointer to head node pointer.
del --> pointer to node to be deleted.*/

static Node deleteNode(Node head_ref, Node del)
{

/*    base case*/

    if (head_ref == null || del == null)
        return null;

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del.next;

/*    Change next only if node to be deleted
    is NOT the last node*/

    if (del.next != null)
        del.next.prev = del.prev;

/*    Change prev only if node to be deleted
    is NOT the first node*/

    if (del.prev != null)
        del.prev.next = del.next;
    return head_ref;
}

/*function to remove duplicates from
an unsorted doubly linked list*/

static Node removeDuplicates(Node head_ref)
{

/*    if doubly linked list is empty*/

    if ((head_ref) == null)
        return null;

/*    unordered_set 'us' implemented as hash table*/

    HashSet<int> us = new HashSet<int>();
    Node current = head_ref, next;

/*    traverse up to the end of the list*/

    while (current != null)
    {

/*        if current data is seen before*/

        if (us.Contains(current.data))
        {

/*            store pointer to the node next to
            'current' node*/

            next = current.next;

/*            delete the node pointed to by 'current'*/

            head_ref = deleteNode(head_ref, current);

/*            update 'current'*/

            current = next;
        }
        else
        {

/*            insert the current data in 'us'*/

            us.Add(current.data);

/*            move to the next node*/

            current = current.next;
        }
    }
    return head_ref;
}

/*Function to insert a node at the
beginning of the Doubly Linked List*/

static Node push(Node head_ref,
                 int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    since we are adding at the beginning,
    prev is always null*/

    new_node.prev = null;

/*    link the old list off the new node*/

    new_node.next = (head_ref);

/*    change prev of head node to new node*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*Function to print nodes in a
given doubly linked list*/

static void printList(Node head)
{

/*    if list is empty*/

    if (head == null)
        Console.Write("Doubly Linked list empty");
    while (head != null)
    {
        Console.Write(head.data + " ");
        head = head.next;
    }
}

/*Driver Code*/

public static void Main(String[] args)
{
    Node head = null;

/*    Create the doubly linked list:
    8<->4<->4<->6<->4<->8<->4<->10<->12<->12*/

    head = push(head, 12);
    head = push(head, 12);
    head = push(head, 10);
    head = push(head, 4);
    head = push(head, 8);
    head = push(head, 4);
    head = push(head, 6);
    head = push(head, 4);
    head = push(head, 4);
    head = push(head, 8);
    Console.WriteLine("Original Doubly linked list:");
    printList(head);

/* remove duplicate nodes */

    head = removeDuplicates(head);
    Console.WriteLine("\nDoubly linked list after " +
                             "removing duplicates:");
    printList(head);
}
}

/*C# implementation to sort the
biotonic doubly linked list*/

using System;
class GFG
{

/*a node of the doubly linked list*/

public class Node
{
    public int data;
    public Node next;
    public Node prev;
}

/*Function to reverse a Doubly Linked List*/

static Node reverse( Node head_ref)
{
    Node temp = null;
    Node current = head_ref;

/*    swap next and prev for all nodes
    of doubly linked list*/

    while (current != null)
    {
        temp = current.prev;
        current.prev = current.next;
        current.next = temp;
        current = current.prev;
    }

/*    Before changing head, check for the cases
    like empty list and list with only one node*/

    if (temp != null)
        head_ref = temp.prev;
        return head_ref;
}

/*Function to merge two sorted doubly linked lists*/

static Node merge(Node first, Node second)
{

/*    If first linked list is empty*/

    if (first == null)
        return second;

/*    If second linked list is empty*/

    if (second == null)
        return first;

/*    Pick the smaller value*/

    if (first.data < second.data)
    {
        first.next = merge(first.next, second);
        first.next.prev = first;
        first.prev = null;
        return first;
    }
    else
    {
        second.next = merge(first, second.next);
        second.next.prev = second;
        second.prev = null;
        return second;
    }
}

/*function to sort a biotonic doubly linked list*/

static Node sort(Node head)
{

/*    if list is empty or if it contains
    a single node only*/

    if (head == null || head.next == null)
        return head;
    Node current = head.next;
    while (current != null)
    {

/*        if true, then 'current' is the first node
        which is smaller than its previous node*/

        if (current.data < current.prev.data)
            break;

/*        move to the next node*/

        current = current.next;
    }

/*    if true, then list is already sorted*/

    if (current == null)
        return head;

/*    spilt into two lists, one starting with 'head'
    and other starting with 'current'*/

    current.prev.next = null;
    current.prev = null;

/*    reverse the list starting with 'current'*/

    current = reverse(current);

/*    merge the two lists and return the
    final merged doubly linked list*/

    return merge(head, current);
}

/*Function to insert a node at the beginning
of the Doubly Linked List*/

static Node push( Node head_ref, int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    since we are adding at the beginning,
    prev is always null*/

    new_node.prev = null;

/*    link the old list off the new node*/

    new_node.next = (head_ref);

/*    change prev of head node to new node*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*Function to print nodes in a given doubly
linked list*/

static void printList( Node head)
{

/*    if list is empty*/

    if (head == null)
        Console.WriteLine("Doubly Linked list empty");
    while (head != null)
    {
        Console.Write(head.data + " ");
        head = head.next;
    }
}

/*Driver Code*/

public static void Main(String []args)
{
    Node head = null;

/*    Create the doubly linked list:
    2<.5<.7<.12<.10<.6<.4<.1*/

    head = push(head, 1);
    head = push(head, 4);
    head = push(head, 6);
    head = push(head, 10);
    head = push(head, 12);
    head = push(head, 7);
    head = push(head, 5);
    head = push(head, 2);
    Console.WriteLine("Original Doubly linked list:n");
    printList(head);

/*    sort the biotonic DLL*/

    head = sort(head);
    Console.WriteLine("\nDoubly linked list after sorting:n");
    printList(head);
}
}

/* C# program to insetail nodes in doubly
linked list such that list remains in
ascending order on printing from left
to right */

using System;

/*A linked list node*/

public class Node
{
    public int info;
    public Node prev, next;
}
class GFG
{
    static Node head, tail;

/*    Function to insetail new node*/

    static void nodeInsetail(int key)
    {
        Node p = new Node();
        p.info = key;
        p.next = null;

/*        If first node to be insetailed in doubly
        linked list*/

        if (head == null)
        {
            head = p;
            tail = p;
            head.prev = null;
            return;
        }

/*        If node to be insetailed has value less
        than first node*/

        if (p.info < head.info)
        {
            p.prev = null;
            head.prev = p;
            p.next = head;
            head = p;
            return;
        }

/*        If node to be insetailed has value more
        than last node*/

        if (p.info > tail.info)
        {
            p.prev = tail;
            tail.next = p;
            tail = p;
            return;
        }

/*        Find the node before which we need to
        insert p.*/

        Node temp = head.next;
        while (temp.info < p.info)
            temp = temp.next;

/*        Insert new node before temp*/

        (temp.prev).next = p;
        p.prev = temp.prev;
        temp.prev = p;
        p.next = temp;
    }

/*    Function to print nodes in from left to right*/

    static void printList(Node temp)
    {
        while (temp != null)
        {
            Console.Write(temp.info + " ");
            temp = temp.next;
        }
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        head = tail = null;
        nodeInsetail(30);
        nodeInsetail(50);
        nodeInsetail(90);
        nodeInsetail(10);
        nodeInsetail(40);
        nodeInsetail(110);
        nodeInsetail(60);
        nodeInsetail(95);
        nodeInsetail(23);
        Console.WriteLine("Doubly linked list on printing from left to right");
        printList(head);
    }
}

/*C# program to illustrate inserting a Node in
a Cicular Doubly Linked list in begging, end
and middle*/

using System;
using System.Collections.Generic;
class GFG
{
static Node start;

/*Structure of a Node*/

public class Node
{
    public int data;
    public Node next;
    public Node prev;
};

/*Function to insert at the end*/

static void insertEnd(int value)
{
    Node new_node;

/*    If the list is empty, create a single node
    circular and doubly list*/

    if (start == null)
    {
        new_node = new Node();
        new_node.data = value;
        new_node.next = new_node.prev = new_node;
        start = new_node;
        return;
    }

/*    If list is not empty*/

/* Find last node */

    Node last = (start).prev;

/*    Create Node dynamically*/

    new_node = new Node();
    new_node.data = value;

/*    Start is going to be next of new_node*/

    new_node.next = start;

/*    Make new node previous of start*/

    (start).prev = new_node;

/*    Make last preivous of new node*/

    new_node.prev = last;

/*    Make new node next of old last*/

    last.next = new_node;
}

/*Function to insert Node at the beginning
of the List,*/

static void insertBegin(int value)
{

/*    Pointer points to last Node*/

    Node last = (start).prev;
    Node new_node = new Node();

/*Inserting the data*/

new_node.data = value;

/*    setting up previous and next of new node*/

    new_node.next = start;
    new_node.prev = last;

/*    Update next and previous pointers of start
    and last.*/

    last.next = (start).prev = new_node;

/*    Update start pointer*/

    start = new_node;
}

/*Function to insert node with value as value1.
The new node is inserted after the node with
with value2*/

static void insertAfter(int value1, int value2)
{
    Node new_node = new Node();

/*Inserting the data*/

new_node.data = value1;

/*    Find node having value2 and next node of it*/

    Node temp = start;
    while (temp.data != value2)
        temp = temp.next;
    Node next = temp.next;

/*    insert new_node between temp and next.*/

    temp.next = new_node;
    new_node.prev = temp;
    new_node.next = next;
    next.prev = new_node;
}
static void display()
{
    Node temp = start;
    Console.Write("\nTraversal in forward direction \n");
    while (temp.next != start)
    {
        Console.Write("{0} ", temp.data);
        temp = temp.next;
    }
    Console.Write("{0} ", temp.data);
    Console.Write("\nTraversal in reverse direction \n");
    Node last = start.prev;
    temp = last;
    while (temp.prev != last)
    {
        Console.Write("{0} ", temp.data);
        temp = temp.prev;
    }
    Console.Write("{0} ", temp.data);
}

/* Driver code*/

public static void Main(String[] args)
{

/* Start with the empty list */

    Node start = null;

/*    Insert 5. So linked list becomes 5.null*/

    insertEnd(5);

/*    Insert 4 at the beginning. So linked
    list becomes 4.5*/

    insertBegin(4);

/*    Insert 7 at the end. So linked list
    becomes 4.5.7*/

    insertEnd(7);

/*    Insert 8 at the end. So linked list
    becomes 4.5.7.8*/

    insertEnd(8);

/*    Insert 6, after 5. So linked list
    becomes 4.5.6.7.8*/

    insertAfter(6, 5);
    Console.Write("Created circular doubly linked list is: ");
    display();
}
}

/*C# program to print reverse of list*/

using System;

/*Represents node of a linkedlist*/

public class Node {
      public int data;
      public Node next;
      public Node(int val)
      {
          data = val;
          next = null;
      }
}
public class GFG
{

/* Function to reverse the linked list */

   static void printReverse(Node head, int n)
   {
          int j = 0;
          Node current = head;
          while (current != null) {

/*             For each node, print proper number 
             of spaces before printing it */

             for (int i = 0; i < 2 * (n - j); i++)
                  Console.Write(" ");

/*             use of carriage return to move back 
             and print.*/

             Console.Write("\r" + current.data);
             current = current.next;
             j++; 
          }
   }

/* Function to push a node */

   static Node push(Node head, int data) 
   {
          Node new_node = new Node(data);
          new_node.next = head;
          head = new_node;
          return head;
   }

/* Function to print linked list and find its 
   length */

   static int printList(Node head)
   {

/*          i for finding length of list */

          int i = 0;
          Node temp = head;
          while (temp != null)
          {
                 Console.Write(temp.data + " ");
                 temp = temp.next;
                 i++;
          }
          return i;
   }

/*   Driver code*/

   public static void Main(String []args)
   {

/* Start with the empty list */

      Node head = null;

/*      list nodes are as 6 5 4 3 2 1*/

      head = push(head, 1);
      head = push(head, 2);
      head = push(head, 3);
      head = push(head, 4);
      head = push(head, 5);
      head = push(head, 6);
      Console.WriteLine("Given linked list: ");

/*      printlist print the list and 
      return the size of list */

      int n = printList(head);

/*      print reverse list with help 
      of carriage return function*/

      Console.WriteLine("Reversed Linked list: ");
      printReverse(head, n); 
      Console.WriteLine();
   }
}

