node of a linked list */

static int printsqrtn(Node head) 
{ 
    Node sqrtn = null; 
    int i = 1, j = 1;

/*    Traverse the list */

    while (head != null) 
    {

/*        check if j = sqrt(i) */

        if (i == j * j) 
        {

/*            for first node */

            if (sqrtn == null) 
                sqrtn = head; 
            else
                sqrtn = sqrtn.next;

/*            increment j if j = sqrt(i) */

            j++; 
        } 
        i++; 
        head=head.next; 
    }

/*    return node's data */

    return sqrtn.data; 
} 
