/*C# program to find fractional node in
a linked list*/

using System;
public class FractionalNodell
{

/* Linked list node */

    public class Node
    {
        public int data;
        public Node next;

/*        Constructor*/

        public Node (int data)
        {
            this.data = data;
        }
    }

/* Function to find fractional node in the
    linked list */

    static Node fractionalNodes(Node head, int k)
    {

/*        Corner cases*/

        if (k <= 0 || head == null)
            return null;
        Node fractionalNode = null;

/*        Traverse the given list*/

        int i = 0;
        for (Node temp = head; temp != null;
                        temp = temp.next)
        {

/*            For every k nodes, we move
            fractionalNode one step ahead.*/

            if (i % k == 0)
            {

/*                First time we see a multiple of k*/

                if (fractionalNode == null)
                    fractionalNode = head;
                else
                    fractionalNode = fractionalNode.next;
            }
            i++;
        }
        return fractionalNode;
    }

/*    A utility function to print a linked list*/

    static void printList(Node node)
    {
        while (node != null)
        {
            Console.Write(node.data+" ");
            node = node.next;
        }
        Console.WriteLine();
    }

/* Driver code */

    public static void Main(String[] args) 
    {
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);
        head.next.next.next.next = new Node(5);
        int k =2;
        Console.Write("List is ");
        printList(head);
        Node answer = fractionalNodes(head, k);
        Console.WriteLine("Fractional node is "+
                                    answer.data);
    }
}

/*C# program to find modular node in a linked list*/

using System;
class GFG 
{

/*    A Linkedlist node */

    public class Node
    { 
        public int data; 
        public Node next; 
        public Node(int data)
        { 
            this.data = data; 
        } 
    }

/*    Function to find modular node in the linked list */

    static Node modularNode(Node head, int k) 
    {

/*        Corner cases */

        if (k <= 0 || head == null) 
            return null;

/*        Traverse the given list */

        int i = 1; 
        Node modularNode = null; 
        for (Node temp = head; temp != null; temp = temp.next)
        { 
            if (i % k == 0) 
                modularNode = temp; 
            i++; 
        } 
        return modularNode; 
    }

/*    Driver code  */

    public static void Main(String[] args) 
    { 
        Node head = new Node(1); 
        head.next = new Node(2); 
        head.next.next = new Node(3); 
        head.next.next.next = new Node(4); 
        head.next.next.next.next = new Node(5); 
        int k = 2; 
        Node answer = modularNode(head, k); 
        Console.Write("Modular node is "); 
        if (answer != null) 
            Console.WriteLine(answer.data); 
        else
            Console.WriteLine("null"); 
    } 
}

/* C# program to arrange consonants and
vowels nodes in a linked list */

using System;
class GfG
{

/* A linked list node */

    public class Node
    {
        public char data;
        public Node next;
    }

/* Function to add new node to the List */

    static Node newNode(char key)
    {
        Node temp = new Node();
        temp.data = key;
        temp.next = null;
        return temp;
    }

/*    utility function to print linked list*/

    static void printlist(Node head)
    {
        if (head == null)
        {
            Console.WriteLine("Empty List");
            return;
        }
        while (head != null)
        {
            Console.Write(head.data +" ");
            if (head.next != null)
                Console.Write("-> ");
            head = head.next;
        }
        Console.WriteLine();
    }

/*    utility function for checking vowel*/

    static bool isVowel(char x)
    {
        return (x == 'a' || x == 'e' || x == 'i' ||
                x == 'o' || x == 'u');
    }

/* function to arrange consonants and
    vowels nodes */

    static Node arrange(Node head)
    {
        Node newHead = head;

/*        for keep track of vowel*/

        Node latestVowel;
        Node curr = head;

/*        list is empty*/

        if (head == null)
            return null;

/*        We need to discover the first vowel
        in the list. It is going to be the
        returned head, and also the initial
        latestVowel.*/

        if (isVowel(head.data) == true)

/*            first element is a vowel. It will
            also be the new head and the initial
            latestVowel;*/

            latestVowel = head;
        else
        {

/*            First element is not a vowel. Iterate
            through the list until we find a vowel.
            Note that curr points to the element
            *before* the element with the vowel.*/

            while (curr.next != null &&
                !isVowel(curr.next.data))
                curr = curr.next;

/*            This is an edge case where there are
            only consonants in the list.*/

            if (curr.next == null)
                return head;

/*            Set the initial latestVowel and the
            new head to the vowel item that we found.
            Relink the chain of consonants after
            that vowel item:
            old_head_consonant->consonant1->consonant2->
            vowel->rest_of_list becomes
            vowel->old_head_consonant->consonant1->
            consonant2->rest_of_list*/

            latestVowel = newHead = curr.next;
            curr.next = curr.next.next;
            latestVowel.next = head;
        }

/*        Now traverse the list. Curr is always the item
        *before* the one we are checking, so that we
        can use it to re-link.*/

        while (curr != null && curr.next != null)
        {
            if (isVowel(curr.next.data) == true)
            {

/*                The next discovered item is a vowel*/

                if (curr == latestVowel)
                {

/*                    If it comes directly after the
                    previous vowel, we don't need to
                    move items around, just mark the
                    new latestVowel and advance curr.*/

                    latestVowel = curr = curr.next;
                }
                else
                {

/*                    But if it comes after an intervening
                    chain of consonants, we need to chain
                    the newly discovered vowel right after
                    the old vowel. Curr is not changed as
                    after the re-linking it will have a
                    new next, that has not been checked yet,
                    and we always keep curr at one before
                    the next to check.*/

                    Node temp = latestVowel.next;

/*                    Chain in new vowel*/

                    latestVowel.next = curr.next;

/*                    Advance latestVowel*/

                    latestVowel = latestVowel.next;

/*                    Remove found vowel from previous place*/

                    curr.next = curr.next.next;

/*                    Re-link chain of consonants after latestVowel*/

                    latestVowel.next = temp;
                }
            }
            else
            {

/*                No vowel in the next element, advance curr.*/

                curr = curr.next;
            }
        }
        return newHead;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node head = newNode('a');
        head.next = newNode('b');
        head.next.next = newNode('c');
        head.next.next.next = newNode('e');
        head.next.next.next.next = newNode('d');
        head.next.next.next.next.next = newNode('o');
        head.next.next.next.next.next.next = newNode('x');
        head.next.next.next.next.next.next.next = newNode('i');
        Console.WriteLine("Linked list before : ");
        printlist(head);
        head = arrange(head);
        Console.WriteLine("Linked list after :");
        printlist(head);
    }
}

/*C# implementation to modify the
contents of the linked list*/

using System;
class GFG
{

/* Linked list node */

public class Node
{
    public int data;
    public Node next;
};

/* Function to insert a node at
the beginning of the linked list */

static Node push(Node head_ref,
                  int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list at the end
    of the new node */

    new_node.next = head_ref;

/* move the head to point to the new node */

    head_ref = new_node;
    return head_ref;
}
static Node front, back;

/* Split the nodes of the given list
into front and back halves,
and return the two lists
using the reference parameters.
Uses the fast/slow pointer strategy. */

static void frontAndBackSplit( Node head)
{
    Node slow, fast;
    slow = head;
    fast = head.next;

/* Advance 'fast' two nodes, and
    advance 'slow' one node */

    while (fast != null)
    {
        fast = fast.next;
        if (fast != null)
        {
            slow = slow.next;
            fast = fast.next;
        }
    }

/* 'slow' is before the midpoint in the list,
        so split it in two at that point. */

    front = head;
    back = slow.next;
    slow.next = null;
}

/* Function to reverse the linked list */

static Node reverseList(Node head_ref)
{
    Node current, prev, next;
    current = head_ref;
    prev = null;
    while (current != null)
    {
        next = current.next;
        current.next = prev;
        prev = current;
        current = next;
    }
    head_ref = prev;
    return head_ref;
}

/*perfrom the required subtraction operation
on the 1st half of the linked list*/

static void modifyTheContentsOf1stHalf()
{
    Node front1 = front, back1 = back;

/*    traversing both the lists simultaneously*/

    while (back1 != null)
    {

/*        subtraction operation and node data
        modification*/

        front1.data = front1.data - back1.data;
        front1 = front1.next;
        back1 = back1.next;
    }
}

/*function to concatenate the 2nd(back) list
at the end of the 1st(front) list and
returns the head of the new list*/

static Node concatFrontAndBackList(Node front,
                                   Node back)
{
    Node head = front;
    if(front == null)
        return back;
    while (front.next != null)
        front = front.next;
    front.next = back;
    return head;
}

/*function to modify the contents of
the linked list*/

static Node modifyTheList(Node head)
{

/*    if list is empty or contains
    only single node*/

    if (head == null || head.next == null)
        return head;
    front = null; back = null;

/*    split the list into two halves
    front and back lists*/

    frontAndBackSplit(head);

/*    reverse the 2nd(back) list*/

    back = reverseList(back);

/*    modify the contents of 1st half*/

    modifyTheContentsOf1stHalf();

/*    agains reverse the 2nd(back) list*/

    back = reverseList(back);

/*    concatenating the 2nd list back to the
    end of the 1st list*/

    head = concatFrontAndBackList(front, back);

/*    pointer to the modified list*/

    return head;
}

/*function to print the linked list*/

static void printList( Node head)
{
    if (head == null)
        return;
    while (head.next != null)
    {
        Console.Write(head.data + " -> ");
        head = head.next;
    }
    Console.WriteLine(head.data );
}

/*Driver Code*/

public static void Main()
{
    Node head = null;

/*    creating the linked list*/

    head = push(head, 10);
    head = push(head, 7);
    head = push(head, 12);
    head = push(head, 8);
    head = push(head, 9);
    head = push(head, 2);

/*    modify the linked list*/

    head = modifyTheList(head);

/*    print the modified linked list*/

    Console.WriteLine( "Modified List:" );
    printList(head);
}
}

/*C# implementation to modify the
contents of the linked list*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Linked list node*/

    public class Node
    {
        public int data;
        public Node next;
    };

/*    Function to insert a node at the
    beginning of the linked list*/

    static Node push(Node head_ref, int new_data)
    {

/*        allocate node*/

        Node new_node = new Node();

/*        put in the data*/

        new_node.data = new_data;

/*        link the old list at the end of the new node*/

        new_node.next = head_ref;

/*        move the head to point to the new node*/

        head_ref = new_node;
        return head_ref;
    }

/*    function to print the linked list*/

    static void printList(Node head)
    {
        if (head == null)
        {
            return;
        }
        while (head.next != null)
        {
            Console.Write(head.data + "->");
            head = head.next;
        }
        Console.Write(head.data + "\n");
    }

/*    Function to middle node of list.*/

    static Node find_mid(Node head)
    {
        Node temp = head, slow = head, fast = head;
        while (fast != null && fast.next != null)
        {

/*            Advance 'fast' two nodes, and
            advance 'slow' one node*/

            slow = slow.next;
            fast = fast.next.next;
        }

/*        If number of nodes are odd then update slow
        by slow.next;*/

        if (fast != null)
        {
            slow = slow.next;
        }
        return slow;
    }

/*    function to modify the contents of the linked list.*/

    static void modifyTheList(Node head, Node slow)
    {

/*        Create Stack.*/

        Stack<int> s = new Stack<int>();
        Node temp = head;
        while (slow != null)
        {
            s.Push(slow.data);
            slow = slow.next;
        }

/*        Traverse the list by using temp until stack is empty.*/

        while (s.Count != 0)
        {
            temp.data = temp.data - s.Peek();
            temp = temp.next;
            s.Pop();
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node head = null, mid;

/*        creating the linked list*/

        head = push(head, 10);
        head = push(head, 7);
        head = push(head, 12);
        head = push(head, 8);
        head = push(head, 9);
        head = push(head, 2);

/*        Call Function to Find the starting
        point of second half of list.*/

        mid = find_mid(head);

/*        Call function to modify
        the contents of the linked list.*/

        modifyTheList(head, mid);

/*        print the modified linked list*/

        Console.Write("Modified List:" + "\n");
        printList(head);
    }
}

/*Construct a BST from given pre-order traversal
for example if the given traversal is {10, 5, 1, 7, 40, 50},
then the output should be the root of the following tree.
     10
   /   \
  5     40
 /  \      \
1    7      50 */

using System;
public class Node {
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        this.left = this.right = null;
    }
}
public class CreateBSTFromPreorder {
    private static Node node;

/*    This will create the BST*/

    public static Node createNode(Node node, int data)
    {
        if (node == null)
            node = new Node(data);
        if (node.data > data)
            node.left = createNode(node.left, data);
        if (node.data < data)
            node.right = createNode(node.right, data);
        return node;
    }

/*    A wrapper function of createNode*/

    public static void create(int data)
    {
        node = createNode(node, data);
    }

/*    A function to print BST in inorder*/

    public static void inorderRec(Node root)
    {
        if (root != null) {
            inorderRec(root.left);
            Console.WriteLine(root.data);
            inorderRec(root.right);
        }
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] nodeData = { 10, 5, 1, 7, 40, 50 };
        for (int i = 0; i < nodeData.Length; i++) {
            create(nodeData[i]);
        }
        inorderRec(node);
    }
}

/*C# implementation to construct a BST
from its level order traversal*/

using System;
class GFG
{

/*node of a BST*/

public class Node
{
    public int data;
    public Node left, right;
};

/*function to get a new node*/

static Node getNode(int data)
{

/*    Allocate memory*/

    Node newNode = new Node();

/*    put in the data */

    newNode.data = data;
    newNode.left = newNode.right = null; 
    return newNode;
}

/*function to construct a BST from
its level order traversal*/

static Node LevelOrder(Node root, 
                       int data) 
{
    if(root == null)
    { 
        root = getNode(data);
        return root;
    }
    if(data <= root.data)
        root.left = LevelOrder(root.left, data);
    else
        root.right = LevelOrder(root.right, data);
    return root;     
}
static Node constructBst(int []arr, int n)
{
    if(n == 0) return null;
    Node root = null;
    for(int i = 0; i < n; i++)
    root = LevelOrder(root, arr[i]);
    return root;
}

/*function to print the inorder traversal*/

static void inorderTraversal(Node root)
{
    if (root == null)
        return;
    inorderTraversal(root.left);
    Console.Write( root.data + " ");
    inorderTraversal(root.right); 
}

/*Driver code*/

public static void Main(String []args)
{
    int []arr = {7, 4, 12, 3, 
                 6, 8, 1, 5, 10};
    int n = arr.Length;
    Node root = constructBst(arr, n);
    Console.Write("Inorder Traversal: ");
    inorderTraversal(root);
}
}

/*C# program to Check given array
can represent BST or not*/

using System;
class GFG 
{

/*    structure for Binary Node*/

    public class Node 
    {
        public int key;
        public Node right, left;
    };
    static Node newNode(int num) 
    {
        Node temp = new Node();
        temp.key = num;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    To create a Tree with n levels. We always
    insert new node to left if it is less than
    previous value.*/

    static Node createNLevelTree(int []arr, int n) 
    {
        Node root = newNode(arr[0]);
        Node temp = root;
        for (int i = 1; i < n; i++)
        {
            if (temp.key > arr[i]) 
            {
                temp.left = newNode(arr[i]);
                temp = temp.left;
            } 
            else
            {
                temp.right = newNode(arr[i]);
                temp = temp.right;
            }
        }
        return root;
    }

/*    Please refer below post for details of this
    function.
www.geeksforgeeks.org/a-program-to-check-if-a-binary-tree-is-bst-or-not/
https:*/

    static bool isBST(Node root, int min, int max) 
    {
        if (root == null) 
        {
            return true;
        }
        if (root.key < min || root.key > max) 
        {
            return false;
        }

/*        Allow only distinct values*/

        return (isBST(root.left, min,
                (root.key) - 1) && 
                isBST(root.right,
                (root.key) + 1, max));
    }

/*    Returns tree if given array of size n can
    represent a BST of n levels.*/

    static bool canRepresentNLevelBST(int []arr, int n) 
    {
        Node root = createNLevelTree(arr, n);
        return isBST(root, int.MinValue, int.MaxValue);
    }

/*    Driver code*/

    public static void Main(String[] args) 
    {
        int []arr = {512, 330, 78, 11, 8};
        int n = arr.Length;
        if (canRepresentNLevelBST(arr, n)) 
        {
            Console.WriteLine("Yes");
        } 
        else
        {
            Console.WriteLine("No");
        }
    }
}

/*C#  program to Check given array  
can represent BST or not  */

using System;
public class Solution
{

/*Driver code  */

public static void Main(string[] args)
{
    int[] arr = new int[] {5123, 3300, 783, 1111, 890};
    int n = arr.Length;
    int max = int.MaxValue;
    int min = int.MinValue;
    bool flag = true;
    for (int i = 1; i < n; i++)
    {

/*        This element can be inserted to the right  
        of the previous element, only if it is greater  
        than the previous element and in the range.  */

        if (arr[i] > arr[i - 1] && arr[i] > min && arr[i] < max)
        {

/*            max remains same, update min  */

            min = arr[i - 1];
        }

/*        This element can be inserted to the left  
        of the previous element, only if it is lesser  
        than the previous element and in the range.  */

        else if (arr[i] < arr[i - 1] && arr[i] > min && arr[i] < max)
        {

/*            min remains same, update max  */

            max = arr[i - 1];
        }
        else
        {
            flag = false;
            break;
        }
    }
    if (flag)
    {
        Console.WriteLine("Yes");
    }
    else
    {

/*        if the loop completed successfully without encountering else condition  */

        Console.WriteLine("No");
    }
}
}

/*C# program to convert a left unbalanced BST to a balanced BST */
using System;
using System.Collections.Generic;

/* A binary tree node has data, pointer to left child 
   and a pointer to right child */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root;

/* This function traverse the skewed binary tree and 
       stores its nodes pointers in vector nodes[] */

    public virtual void storeBSTNodes(Node root, List<Node> nodes)
    {

/*        Base case */

        if (root == null)
        {
            return;
        }

/*        Store nodes in Inorder (which is sorted 
        order for BST) */

        storeBSTNodes(root.left, nodes);
        nodes.Add(root);
        storeBSTNodes(root.right, nodes);
    }

/* Recursive function to construct binary tree */

    public virtual Node buildTreeUtil(List<Node> nodes, int start, int end)
    {

/*        base case */

        if (start > end)
        {
            return null;
        }

/* Get the middle element and make it root */

        int mid = (start + end) / 2;
        Node node = nodes[mid];

/* Using index in Inorder traversal, construct 
           left and right subtress */

        node.left = buildTreeUtil(nodes, start, mid - 1);
        node.right = buildTreeUtil(nodes, mid + 1, end);
        return node;
    }

/*    This functions converts an unbalanced BST to 
    a balanced BST */

    public virtual Node buildTree(Node root)
    {

/*        Store nodes of given BST in sorted order */

        List<Node> nodes = new List<Node>();
        storeBSTNodes(root, nodes);

/*        Constucts BST from nodes[] */

        int n = nodes.Count;
        return buildTreeUtil(nodes, 0, n - 1);
    }

/* Function to do preorder traversal of tree */

    public virtual void preOrder(Node node)
    {
        if (node == null)
        {
            return;
        }
        Console.Write(node.data + " ");
        preOrder(node.left);
        preOrder(node.right);
    }

/*    Driver program to test the above functions */

    public static void Main(string[] args)
    {

/* Constructed skewed binary tree is 
                10 
               / 
              8 
             / 
            7 
           / 
          6 
         / 
        5   */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(10);
        tree.root.left = new Node(8);
        tree.root.left.left = new Node(7);
        tree.root.left.left.left = new Node(6);
        tree.root.left.left.left.left = new Node(5);
        tree.root = tree.buildTree(tree.root);
        Console.WriteLine("Preorder traversal of balanced BST is :");
        tree.preOrder(tree.root);
    }
}

/*C# program to find minimum value node in Binary Search Tree */
using System;

/*A binary tree node */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
public class BinaryTree
{
    public static Node head;

/* Given a binary search tree and a number,  
     inserts a new node with the given number in  
     the correct place in the tree. Returns the new  
     root pointer which the caller should then use  
     (the standard trick to avoid using reference  
     parameters). */

    public virtual Node insert(Node node, int data)
    {

/* 1. If the tree is empty, return a new,      
         single node */

        if (node == null)
        {
            return (new Node(data));
        }
        else
        {

/* 2. Otherwise, recur down the tree */

            if (data <= node.data)
            {
                node.left = insert(node.left, data);
            }
            else
            {
                node.right = insert(node.right, data);
            }

/* return the (unchanged) node pointer */

            return node;
        }
    }

/* Given a non-empty binary search tree,   
     return the minimum data value found in that  
     tree. Note that the entire tree does not need  
     to be searched. */

    public virtual int minvalue(Node node)
    {
        Node current = node;

/* loop down to find the leftmost leaf */

        while (current.left != null)
        {
            current = current.left;
        }
        return (current.data);
    }

/*    Driver program to test above functions */

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        Node root = null;
        root = tree.insert(root, 4);
        tree.insert(root, 2);
        tree.insert(root, 1);
        tree.insert(root, 3);
        tree.insert(root, 6);
        tree.insert(root, 5);
        Console.WriteLine("Minimum value of BST is " + tree.minvalue(root));
    }
}

/*C# implementation to check if the given array 
can represent Level Order Traversal of Binary 
Search Tree */

using System;
using System.Collections.Generic;
class GFG
{

/*to store details of a node like
node's data, 'min' and 'max' to obtain the
range of values where node's left and 
right child's should lie*/

public class NodeDetails
{
    public int data;
    public int min, max;
};

/*function to check if the given array 
can represent Level Order Traversal 
of Binary Search Tree*/

static Boolean levelOrderIsOfBST(int []arr, int n)
{

/*    if tree is empty*/

    if (n == 0)
        return true;

/*    queue to store NodeDetails*/

    Queue<NodeDetails> q = new Queue<NodeDetails>();

/*    index variable to access array elements*/

    int i = 0;

/*    node details for the 
    root of the BST*/

    NodeDetails newNode=new NodeDetails();
    newNode.data = arr[i++];
    newNode.min = int.MinValue;
    newNode.max = int.MaxValue;
    q.Enqueue(newNode);

/*    until there are no more elements 
    in arr[] or queue is not empty*/

    while (i != n && q.Count > 0)     
    {

/*        extracting NodeDetails of a
        node from the queue*/

        NodeDetails temp = q.Peek();
        q.Dequeue();
        newNode = new NodeDetails();

/*        check whether there are more elements 
        in the arr[] and arr[i] can be left child 
        of 'temp.data' or not */

        if (i < n && (arr[i] < (int)temp.data && 
                    arr[i] > (int)temp.min))
        {

/*            Create NodeDetails for newNode 
and add it to the queue*/

            newNode.data = arr[i++];
            newNode.min = temp.min;
            newNode.max = temp.data;
            q.Enqueue(newNode);             
        }
        newNode=new NodeDetails();

/*        check whether there are more elements 
        in the arr[] and arr[i] can be right child 
        of 'temp.data' or not */

        if (i < n && (arr[i] > (int)temp.data && 
                    arr[i] < (int)temp.max))
        {

/*            Create NodeDetails for newNode 
and add it to the queue*/

            newNode.data = arr[i++];
            newNode.min = temp.data;
            newNode.max = temp.max;
            q.Enqueue(newNode);         
        }     
    }

/*    given array represents level
    order traversal of BST*/

    if (i == n)
        return true;

/*    given array do not represent 
    level order traversal of BST */

    return false;     
}

/*Driver code*/

public static void Main(String []args)
{
    int []arr = {7, 4, 12, 3, 6, 8, 1, 5, 10}; 
    int n = arr.Length; 
    if (levelOrderIsOfBST(arr, n))
        Console.Write( "Yes");
    else
        Console.Write( "No");     
}
}

/*Recursive C#  program to print lca of two nodes 
A binary tree node */
using System;
public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root;

/* Function to find LCA of n1 and n2. The function assumes that both 
       n1 and n2 are present in BST */

    public virtual Node lca(Node node, int n1, int n2)
    {
        if (node == null)
        {
            return null;
        }

/*        If both n1 and n2 are smaller than root, then LCA lies in left */

        if (node.data > n1 && node.data > n2)
        {
            return lca(node.left, n1, n2);
        }

/*        If both n1 and n2 are greater than root, then LCA lies in right */

        if (node.data < n1 && node.data < n2)
        {
            return lca(node.right, n1, n2);
        }
        return node;
    }

/* Driver program to test lca() */

    public static void Main(string[] args)
    {

/*        Let us construct the BST shown in the above figure */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(20);
        tree.root.left = new Node(8);
        tree.root.right = new Node(22);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(12);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(14);
        int n1 = 10, n2 = 14;
        Node t = tree.lca(tree.root, n1, n2);
        Console.WriteLine("LCA of " + n1 + " and " + n2 + " is " + t.data);
        n1 = 14;
        n2 = 8;
        t = tree.lca(tree.root, n1, n2);
        Console.WriteLine("LCA of " + n1 + " and " + n2 + " is " + t.data);
        n1 = 10;
        n2 = 22;
        t = tree.lca(tree.root, n1, n2);
        Console.WriteLine("LCA of " + n1 + " and " + n2 + " is " + t.data);
    }
}

/*Recursive C# program to print lca of two nodes 
A binary tree node */
using System;
public class Node
{
    public int data;
    public Node left, right;
    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}
public class BinaryTree
{
    public Node root;

/* Function to find LCA of n1 and n2.
The function assumes that both 
n1 and n2 are present in BST */

public virtual Node lca(Node root, int n1, int n2) 
{ 
    while (root != null) 
    {

/*        If both n1 and n2 are smaller than
        root, then LCA lies in left */

        if (root.data > n1 && root.data > n2) 
        root = root.left;

/*        If both n1 and n2 are greater than 
        root, then LCA lies in right */

        else if (root.data < n1 && root.data < n2) 
        root = root.right; 
        else break; 
    } 
    return root; 
}

/* Driver program to test lca() */

    public static void Main(string[] args)
    {

/*        Let us construct the BST shown in the above figure */

        BinaryTree tree = new BinaryTree();
        tree.root = new Node(20);
        tree.root.left = new Node(8);
        tree.root.right = new Node(22);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(12);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(14);
        int n1 = 10, n2 = 14;
        Node t = tree.lca(tree.root, n1, n2);
        Console.WriteLine(
            "LCA of " + n1 + " and " + n2
            + " is " + t.data);
        n1 = 14;
        n2 = 8;
        t = tree.lca(tree.root, n1, n2);
        Console.WriteLine(
            "LCA of " + n1 + " and " + n2
            + " is " + t.data);
        n1 = 10;
        n2 = 22;
        t = tree.lca(tree.root, n1, n2);
        Console.WriteLine(
            "LCA of " + n1 + " and " + n2 
            + " is " + t.data);
    }
}

/*C# program to check if a given tree is BST.*/

using System;
class GFG
{

/*A binary tree node has data, pointer to
left child && a pointer to right child /*/

public class Node
{
    public int data;
    public Node left, right;
};

/*Returns true if given tree is BST.*/

static Boolean isBST(Node root, Node l, Node r)
{

/*    Base condition*/

    if (root == null)
        return true;

/*    if left node exist then check it has
    correct data or not i.e. left node's data
    should be less than root's data*/

    if (l != null && root.data <= l.data)
        return false;

/*    if right node exist then check it has
    correct data or not i.e. right node's data
    should be greater than root's data*/

    if (r != null && root.data >= r.data)
        return false;

/*    check recursively for every node.*/

    return isBST(root.left, l, root) &&
        isBST(root.right, root, r);
}

/*Helper function that allocates a new node with the
given data && null left && right pointers. /*/

static Node newNode(int data)
{
    Node node = new Node();
    node.data = data;
    node.left = node.right = null;
    return (node);
}

/*Driver code*/

public static void Main(String []args)
{
    Node root = newNode(3);
    root.left = newNode(2);
    root.right = newNode(5);
    root.left.left = newNode(1);
    root.left.right = newNode(4);
    if (isBST(root,null,null))
        Console.Write("Is BST");
    else
        Console.Write("Not a BST");
}
}

/*C# program to check if a given tree is BST.*/

using System;
public class GFG
{

/* A binary tree node has data, pointer to
left child and a pointer to right child */

public class Node
{
    public int data;
    public Node left, right;
    public Node(int data)
    {
        this.data = data;
        left = right = null;
    }
};
static Node prev;
static Boolean isBSTUtil(Node root)
{

/*    traverse the tree in inorder fashion and
    keep track of prev node*/

    if (root != null)
    {
        if (!isBSTUtil(root.left))
        return false;

/*        Allows only distinct valued nodes*/

        if (prev != null &&
            root.data <= prev.data)
        return false;
        prev = root;
        return isBSTUtil(root.right);
    }
    return true;
}
static Boolean isBST(Node root)
{
    return isBSTUtil(root);
}

/*Driver Code*/

public static void Main(String[] args)
{
    Node root = new Node(3);
    root.left = new Node(2);
    root.right = new Node(5);
    root.left.left = new Node(1);
    root.left.right = new Node(4);
    if (isBST(root))
        Console.WriteLine("Is BST");
    else
        Console.WriteLine("Not a BST");
}
}

/*A simple inorder traversal
based C# program to find
k-th smallest element in a BST.*/

using System;

/*A BST node*/

class Node{
public int data;
public Node left, right;
public Node(int x)
{
  data = x;
  left = right = null;
}
}
class GFG{
static int count = 0;

/*Recursive function to 
insert an key into BST*/

public static Node insert(Node root,
                          int x)
{
  if (root == null)
    return new Node(x);
  if (x < root.data)
    root.left = insert(root.left, x);
  else if (x > root.data)
    root.right = insert(root.right, x);
  return root;
}

/*Function to find k'th largest
element in BST. Here count
denotes the number of nodes
processed so far*/

public static Node kthSmallest(Node root,
                               int k)
{

/*  base case*/

  if (root == null)
    return null;

/*  search in left subtree*/

  Node left = kthSmallest(root.left, k);

/*  if k'th smallest is found
  in left subtree, return it*/

  if (left != null)
    return left;

/*  if current element is
  k'th smallest, return it*/

  count++;
  if (count == k)
    return root;

/*  else search in right subtree*/

  return kthSmallest(root.right, k);
}

/*Function to find k'th largest
element in BST*/

public static void printKthSmallest(Node root,
                                    int k)
{

/*  Maintain an index to
  count number of nodes
  processed so far*/

  count = 0;
  Node res = kthSmallest(root, k);
  if (res == null)
    Console.WriteLine("There are less " +
                      "than k nodes in the BST");
  else
    Console.WriteLine("K-th Smallest" +
                      " Element is " + res.data);
}

/*Driver code*/

public static void Main(String[] args)
{
  Node root = null;
  int []keys = {20, 8, 22, 4,
                12, 10, 14};
  foreach (int x in keys)
    root = insert(root, x);
  int k = 3;
  printKthSmallest(root, k);
}
}

/*A simple inorder traversal based C# program
to find k-th smallest element in a BST.*/

using System;

/*A BST node*/

public class Node
{
    public int data;
    public Node left, right;
    public int lCount;
    public Node(int x)
    {
        data = x;
        left = right = null;
        lCount = 0;
    }
}
class GFG{

/*Recursive function to insert an key into BST*/

public static Node insert(Node root, int x)
{
    if (root == null)
        return new Node(x);

/*    If a node is inserted in left subtree,
    then lCount of this node is increased.
    For simplicity, we are assuming that
    all keys (tried to be inserted) are
    distinct.*/

    if (x < root.data)
    {
        root.left = insert(root.left, x);
        root.lCount++;
    }
    else if (x > root.data)
        root.right = insert(root.right, x);
    return root;
}

/*Function to find k'th largest element
in BST. Here count denotes the number
of nodes processed so far*/

public static Node kthSmallest(Node root, int k)
{

/*    Base case*/

    if (root == null)
        return null;
    int count = root.lCount + 1;
    if (count == k)
        return root;
    if (count > k)
        return kthSmallest(root.left, k);

/*    Else search in right subtree*/

    return kthSmallest(root.right, k - count);
}

/*Driver Code*/

public static void Main(String[] args)
{
    Node root = null;
    int[] keys = { 20, 8, 22, 4, 12, 10, 14 };
    foreach(int x in keys)
        root = insert(root, x);
    int k = 4;
    Node res = kthSmallest(root, k);
    if (res == null)
        Console.WriteLine("There are less " +
                          "than k nodes in the BST");
    else
        Console.WriteLine("K-th Smallest" +
                          " Element is " + res.data);
}
}

/*Check if each internal node of BST has only one child*/

using System;
public class BinaryTree
{
  bool hasOnlyOneChild(int[] pre, int size)
  {
    int nextDiff, lastDiff;
    for (int i = 0; i < size - 1; i++)
    {
      nextDiff = pre[i] - pre[i + 1];
      lastDiff = pre[i] - pre[size - 1];
      if (nextDiff * lastDiff < 0)
      {
        return false;
      };
    }
    return true;
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    BinaryTree tree = new BinaryTree();
    int []pre = new int[]{8, 3, 5, 7, 6};
    int size = pre.Length;
    if (tree.hasOnlyOneChild(pre, size) == true)
    {
      Console.WriteLine("Yes");
    }
    else
    {
      Console.WriteLine("No");
    }
  }
}

/*Check if each internal node of BST has only one child*/

using System;
public class BinaryTree
{
  bool hasOnlyOneChild(int []pre, int size)
  {

/*    Initialize min and max using last two elements*/

    int min, max;
    if (pre[size - 1] > pre[size - 2]) {
      max = pre[size - 1];
      min = pre[size - 2];
    } else {
      max = pre[size - 2];
      min = pre[size - 1];
    }

/*    Every element must be either smaller than min or
    greater than max*/

    for (int i = size - 3; i >= 0; i--) {
      if (pre[i] < min) {
        min = pre[i];
      } else if (pre[i] > max) {
        max = pre[i];
      } else {
        return false;
      }
    }
    return true;
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    BinaryTree tree = new BinaryTree();
    int []pre = new int[]{8, 3, 5, 7, 6};
    int size = pre.Length;
    if (tree.hasOnlyOneChild(pre, size) == true)
    {
      Console.WriteLine("Yes");
    }
    else
    {
      Console.WriteLine("No");
    }
  }
}

/*C# Program for finding K-th largest Node using O(1)
extra memory and reverse Morris traversal.*/

using System;
using System.Collections.Generic;
class GfG
{

/*Node structure*/

public class Node
{
    public int data;
    public Node left, right;
}

/*helper function to create a new Node*/

static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.right = null;
    temp.left = null;
    return temp;
}
static Node KthLargestUsingMorrisTraversal(Node root, int k)
{
    Node curr = root;
    Node Klargest = null;

/*    count variable to keep count of visited Nodes*/

    int count = 0;
    while (curr != null)
    {

/*        if right child is NULL*/

        if (curr.right == null)
        {

/*            first increment count and check if count = k*/

            if (++count == k)
                Klargest = curr;

/*            otherwise move to the left child*/

            curr = curr.left;
        }
        else
        {

/*            find inorder successor of current Node*/

            Node succ = curr.right;
            while (succ.left != null && succ.left != curr)
                succ = succ.left;
            if (succ.left == null)
            {

/*                set left child of successor to the
                current Node*/

                succ.left = curr;

/*                move current to its right*/

                curr = curr.right;
            }

/*            restoring the tree back to original binary
            search tree removing threaded links*/

            else
            {
                succ.left = null;
                if (++count == k)
                    Klargest = curr;

/*                move current to its left child*/

                curr = curr.left;
            }
        }
    }
    return Klargest;
}

/*Driver code*/

public static void Main(String[] args)
{

/* Constructed binary tree is
        4
        / \
    2 7
    / \ / \
    1 3 6 10 */

    Node root = newNode(4);
    root.left = newNode(2);
    root.right = newNode(7);
    root.left.left = newNode(1);
    root.left.right = newNode(3);
    root.right.left = newNode(6);
    root.right.right = newNode(10);
    Console.Write("Finding K-th largest Node in BST : " +
                    KthLargestUsingMorrisTraversal(root, 2).data);
}
}

/*C# program to find k'th largest element in BST*/

using System;
class GfG
{

/*A BST node*/

public class Node
{
    public int key;
    public Node left, right;
}

/*A function to find*/

static int KSmallestUsingMorris(Node root, int k)
{

/*    Count to iterate over elements till we
    get the kth smallest number*/

    int count = 0;

/*store the Kth smallest*/

int ksmall = int.MinValue;

/*to store the current node*/

Node curr = root; 
    while (curr != null)
    {

/*        Like Morris traversal if current does
        not have left child rather than printing
        as we did in inorder, we will just
        increment the count as the number will
        be in an increasing order*/

        if (curr.left == null)
        {
            count++;

/*            if count is equal to K then we found the
            kth smallest, so store it in ksmall*/

            if (count==k)
                ksmall = curr.key;

/*            go to current's right child*/

            curr = curr.right;
        }
        else
        {

/*            we create links to Inorder Successor and
            count using these links*/

            Node pre = curr.left;
            while (pre.right != null && pre.right != curr)
                pre = pre.right;

/*            building links*/

            if (pre.right == null)
            {

/*                link made to Inorder Successor*/

                pre.right = curr;
                curr = curr.left;
            }

/*            While breaking the links in so made temporary
            threaded tree we will check for the K smallest
            condition*/

            else
            {

/*                Revert the changes made in if part (break link
                from the Inorder Successor)*/

                pre.right = null;
                count++;

/*                If count is equal to K then we found
                the kth smallest and so store it in ksmall*/

                if (count == k)
                    ksmall = curr.key;
                curr = curr.right;
            }
        }
    }

/*return the found value*/

return ksmall; 
}

/*A utility function to create a new BST node*/

static Node newNode(int item)
{
    Node temp = new Node();
    temp.key = item;
    temp.left = null;
    temp.right = null;
    return temp;
}

/* A utility function to insert a new node with given key in BST */

static Node insert(Node node, int key)
{

/* If the tree is empty, return a new node */

    if (node == null) return newNode(key);

/* Otherwise, recur down the tree */

    if (key < node.key)
        node.left = insert(node.left, key);
    else if (key > node.key)
        node.right = insert(node.right, key);

/* return the (unchanged) node pointer */

    return node;
}

/*Driver Program to test above functions*/

public static void Main(String[] args)
{

/* Let us create following BST
            50
        /     \
        30     70
        / \ / \
    20 40 60 80 */

    Node root = null;
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 20);
    insert(root, 40);
    insert(root, 70);
    insert(root, 60);
    insert(root, 80);
    for (int k = 1; k <= 7; k++)
    Console.Write(KSmallestUsingMorris(root, k) + " ");
}
}

/*C# program to find if given array 
exists as a subsequece in BST */

using System;
class GFG 
{

/*A binary Tree node */

public class Node 
{ 
    public int data; 
    public Node left, right; 
};

/*structure of int class */

public class INT 
{ 
    public int a; 
}

/*A utility function to create a new BST node 
with key as given num */

static Node newNode(int num) 
{ 
    Node temp = new Node(); 
    temp.data = num; 
    temp.left = temp.right = null; 
    return temp; 
}

/*A utility function to insert a given key to BST */

static Node insert( Node root, int key) 
{ 
    if (root == null) 
        return newNode(key); 
    if (root.data > key) 
        root.left = insert(root.left, key); 
    else
        root.right = insert(root.right, key); 
    return root; 
}

/*function to check if given sorted 
sub-sequence exist in BST index -. 
iterator for given sorted sub-sequence 
seq[] -. given sorted sub-sequence */

static void seqExistUtil( Node ptr, int []seq, INT index) 
{ 
    if (ptr == null) 
        return;

/*    We traverse left subtree 
    first in Inorder */

    seqExistUtil(ptr.left, seq, index);

/*    If current node matches 
    with se[index] then move 
    forward in sub-sequence */

    if (ptr.data == seq[index.a]) 
        index.a++;

/*    We traverse left subtree 
    in the end in Inorder */

    seqExistUtil(ptr.right, seq, index); 
}

/*A wrapper over seqExistUtil. 
It returns true if seq[0..n-1] 
exists in tree. */

static bool seqExist( Node root, int []seq, int n) 
{

/*    Initialize index in seq[] */

    INT index = new INT(); 
    index.a = 0;

/*    Do an inorder traversal and find if all 
    elements of seq[] were present */

    seqExistUtil(root, seq, index);

/*    index would become n if all 
    elements of seq[] were present */

    return (index.a == n); 
}

/*Driver code */

public static void Main(String []args) 
{ 
    Node root = null; 
    root = insert(root, 8); 
    root = insert(root, 10); 
    root = insert(root, 3); 
    root = insert(root, 6); 
    root = insert(root, 1); 
    root = insert(root, 4); 
    root = insert(root, 7); 
    root = insert(root, 14); 
    root = insert(root, 13); 
    int []seq = {4, 6, 8, 14}; 
    int n = seq.Length; 
    if(seqExist(root, seq, n)) 
        Console.WriteLine("Yes"); 
    else
        Console.WriteLine("No"); 
} 
}

/*C# program to check if a given
array is sorted or not.*/

using System;
class GFG
{

/*Function that returns true if
array is Inorder traversal of
any Binary Search Tree or not.*/

static bool isInorder(int[] arr, int n)
{

/*    Array has one or no element*/

    if (n == 0 || n == 1)
    {
        return true;
    }

/*    Unsorted pair found*/

    for (int i = 1; i < n; i++)
    {
        if (arr[i - 1] > arr[i])
        {
            return false;
        }
    }

/*    No unsorted pair found*/

    return true;
}

/*Driver code*/

public static void Main()
{
    int []arr = {19, 23, 25, 30, 45};
    int n = arr.Length;
    if (isInorder(arr, n))
    {
        Console.Write("Yes");
    }
    else
    {
        Console.Write("Non");
    }
}
}

/*C# program to check if two BSTs contains
same set of elements*/

using System;
using System.Collections.Generic;
class GFG
{

/*BST Node*/

class Node
{
    public int data;
    public Node left;
    public Node right;
};

/*Utility function to create new Node*/

static Node newNode(int val)
{
    Node temp = new Node();
    temp.data = val;
    temp.left = temp.right = null;
    return temp;
}

/*function to insert elements of the
tree to map m*/

static void insertToHash(Node root,
                         HashSet<int> s)
{
    if (root == null)
        return;
    insertToHash(root.left, s);
    s.Add(root.data);
    insertToHash(root.right, s);
}

/*function to check if the two BSTs contain
same set of elements*/

static bool checkBSTs(Node root1, Node root2)
{

/*    Base cases*/

    if (root1 != null && root2 != null)
        return true;
    if ((root1 == null && root2 != null) ||
        (root1 != null && root2 == null))
        return false;

/*    Create two hash sets and store
    elements both BSTs in them.*/

    HashSet<int> s1 = new HashSet<int>();
    HashSet<int> s2 = new HashSet<int>();
    insertToHash(root1, s1);
    insertToHash(root2, s2);

/*    Return true if both hash sets
    contain same elements.*/

    return (s1.Equals(s2));
}

/*Driver Code*/

public static void Main(String[] args)
{

/*    First BST*/

    Node root1 = newNode(15);
    root1.left = newNode(10);
    root1.right = newNode(20);
    root1.left.left = newNode(5);
    root1.left.right = newNode(12);
    root1.right.right = newNode(25);

/*    Second BST*/

    Node root2 = newNode(15);
    root2.left = newNode(12);
    root2.right = newNode(20);
    root2.left.left = newNode(5);
    root2.left.left.right = newNode(10);
    root2.right.right = newNode(25);

/*    check if two BSTs have same set of elements*/

    if (checkBSTs(root1, root2))
        Console.Write("YES");
    else
        Console.Write("NO");
}    
}

