/*C# code to find the largest value
smaller than or equal to N*/

using System;
class GFG
{

/*Node structure*/

    class Node
    {
        public int key;
        public Node left, right;
    }

/*    To create new BST Node*/

    static Node newNode(int item)
    {
        Node temp = new Node();
        temp.key = item;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    To insert a new node in BST*/

    static Node insert(Node node, int key)
    {

/*        if tree is empty return new node*/

        if (node == null)
            return newNode(key);

/*        if key is less then or greater then
        node value then recur down the tree*/

        if (key < node.key)
            node.left = insert(node.left, key);
        else if (key > node.key)
            node.right = insert(node.right, key);

/*        return the (unchanged) node pointer*/

        return node;
    }

/*    function to find max value less then N*/

    static int findMaxforN(Node root, int N)
    {

/*        Base cases*/

        if (root == null)
            return -1;
        if (root.key == N)
            return N;

/*        If root's value is smaller,
        try in right subtree*/

        else if (root.key < N)
        {
            int k = findMaxforN(root.right, N);
            if (k == -1)
                return root.key;
            else
                return k;
        }

/*        If root's key is greater, return
        value from left subtree.*/

        else if (root.key > N)
            return findMaxforN(root.left, N);
        return -1;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int N = 4;

/*creating following BST
                    5
                / \
                2 12
            / \ / \
            1 3 9 21
                        / \
                        19 25 */

        Node root = null;
        root = insert(root, 25);
        insert(root, 2);
        insert(root, 1);
        insert(root, 3);
        insert(root, 12);
        insert(root, 9);
        insert(root, 21);
        insert(root, 19);
        insert(root, 25);
        Console.WriteLine(findMaxforN(root, N));
    }
}

/*C# program to find distance between
two nodes in BST*/

using System;
class GfG
{
public class Node
{
    public Node left, right;
    public int key;
}
static Node newNode(int key)
{
    Node ptr = new Node();
    ptr.key = key;
    ptr.left = null;
    ptr.right = null;
    return ptr;
}

/*Standard BST insert function*/

static Node insert(Node root, int key)
{
    if (root == null)
        root = newNode(key);
    else if (root.key > key)
        root.left = insert(root.left, key);
    else if (root.key < key)
        root.right = insert(root.right, key);
    return root;
}

/*This function returns distance of x from
root. This function assumes that x exists
in BST and BST is not NULL.*/

static int distanceFromRoot(Node root, int x)
{
    if (root.key == x)
        return 0;
    else if (root.key > x)
        return 1 + distanceFromRoot(root.left, x);
    return 1 + distanceFromRoot(root.right, x);
}

/*Returns minimum distance beween a and b.
This function assumes that a and b exist
in BST.*/

static int distanceBetween2(Node root, int a, int b)
{
    if (root == null)
        return 0;

/*    Both keys lie in left*/

    if (root.key > a && root.key > b)
        return distanceBetween2(root.left, a, b);

/*    Both keys lie in right
same path*/

if (root.key < a && root.key < b) 
        return distanceBetween2(root.right, a, b);

/*    Lie in opposite directions (Root is
    LCA of two nodes)*/

    if (root.key >= a && root.key <= b)
        return distanceFromRoot(root, a) +
                distanceFromRoot(root, b);
    return 0;
}

/*This function make sure that a is smaller
than b before making a call to findDistWrapper()*/

static int findDistWrapper(Node root, int a, int b)
{
    int temp = 0;
if (a > b)
    {
    temp = a;
    a = b;
    b = temp;
    }
return distanceBetween2(root, a, b);
}

/*Driver code*/

public static void Main(String[] args)
{
    Node root = null;
    root = insert(root, 20);
    insert(root, 10);
    insert(root, 5);
    insert(root, 15);
    insert(root, 30);
    insert(root, 25);
    insert(root, 35);
    Console.WriteLine(findDistWrapper(root, 5, 35));
}
}

/*C# code to print BST keys in given Range in
constant space using Morris traversal.*/

using System;
public class GfG
{
public class node
{
    public int data;
    public node left, right;
}

/*Function to print the keys in range*/

static void RangeTraversal(node root, int n1, int n2)
{
    if (root == null)
        return;
    node curr = root;
    while (curr != null)
    {
        if (curr.left == null)
        {

/*            check if current node
            lies between n1 and n2*/

            if (curr.data <= n2 && curr.data >= n1)
            {
                Console.Write(curr.data + " ");
            }
            curr = curr.right;
        }
        else
        {
            node pre = curr.left;

/*            finding the inorder predecessor-
            inorder predecessor is the right
            most in left subtree or the left
            child, i.e in BST it is the
            maximum(right most) in left subtree.*/

            while (pre.right != null && pre.right != curr)
                pre = pre.right;
            if (pre.right == null)
            {
                pre.right = curr;
                curr = curr.left;
            }
            else
            {
                pre.right = null;

/*                check if current node lies
                between n1 and n2*/

                if (curr.data <= n2 && curr.data >= n1)
                {
                    Console.Write(curr.data + " ");
                }
                curr = curr.right;
            }
        }
    }
}

/*Helper function to create a new node*/

static node newNode(int data)
{
    node temp = new node();
    temp.data = data;
    temp.right = null;
    temp.left = null;
    return temp;
}

/*Driver Code*/

public static void Main(String[] args)
{

/* Constructed binary tree is
        4
        / \
    2 7
    / \ / \
    1 3 6 10
*/

    node root = newNode(4);
    root.left = newNode(2);
    root.right = newNode(7);
    root.left.left = newNode(1);
    root.left.right = newNode(3);
    root.right.left = newNode(6);
    root.right.right = newNode(10);
    RangeTraversal(root, 4, 12);
}
}

/*C# program to count subtrees
that lie in a given range*/

using System;
class GfG {

/*    A BST node*/

    public class node {
        public int data;
        public node left, right;
    };

/*    int class*/

    public class INT {
        public int a;
    }

/*    A utility function to check if data of root is
    in range from low to high*/

    static bool inRange(node root, int low, int high)
    {
        return root.data >= low && root.data <= high;
    }

/*    A recursive function to get count
    of nodes whose subtree is in range
    from low to hgih. This function returns
    true if nodes in subtree rooted under
    'root' are in range.*/

    static bool getCountUtil(node root, int low,
                             int high, INT count)
    {

/*        Base case*/

        if (root == null)
            return true;

/*        Recur for left and right subtrees*/

        bool l = getCountUtil(root.left,
                              low, high, count);
        bool r = getCountUtil(root.right,
                              low, high, count);

/*        If both left and right subtrees are
        in range and current node is also in
        range, then increment count and return true*/

        if (l && r && inRange(root, low, high)) {
            ++count.a;
            return true;
        }
        return false;
    }

/*    A wrapper over getCountUtil().
    This function initializes count as 0
    and calls getCountUtil()*/

    static INT getCount(node root, int low, int high)
    {
        INT count = new INT();
        count.a = 0;
        getCountUtil(root, low, high, count);
        return count;
    }

/*    Utility function to create new node*/

    static node newNode(int data)
    {
        node temp = new node();
        temp.data = data;
        temp.left = temp.right = null;
        return (temp);
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/*        Let us con the BST shown in the above figure*/

        node root = newNode(10);
        root.left = newNode(5);
        root.right = newNode(50);
        root.left.left = newNode(1);
        root.right.left = newNode(40);
        root.right.right = newNode(100);

/* Let us construct BST shown in above example
        10
        / \
    5 50
    / / \
    1 40 100 */

        int l = 5;
        int h = 45;
        Console.WriteLine("Count of subtrees in [" + l + ", "
                          + h + "] is " + getCount(root, l, h).a);
    }
}

/*C# program to delete leaf Node from
binary search tree.*/

using System;
class GfG {
    class Node {
        public int data;
        public Node left;
        public Node right;
    }

/*    Create a newNode in binary search tree.*/

    static Node newNode(int data)
    {
        Node temp = new Node();
        temp.data = data;
        temp.left = null;
        temp.right = null;
        return temp;
    }

/*    Insert a Node in binary search tree.*/

    static Node insert(Node root, int data)
    {
        if (root == null)
            return newNode(data);
        if (data < root.data)
            root.left = insert(root.left, data);
        else if (data > root.data)
            root.right = insert(root.right, data);
        return root;
    }

/*    Function for inorder traversal in a BST.*/

    static void inorder(Node root)
    {
        if (root != null) {
            inorder(root.left);
            Console.Write(root.data + " ");
            inorder(root.right);
        }
    }

/*    Delete leaf nodes from binary search tree.*/

    static Node leafDelete(Node root)
    {
        if (root == null) {
            return null;
        }
        if (root.left == null && root.right == null) {
            return null;
        }

/*        Else recursively delete in
        left and right subtrees.*/

        root.left = leafDelete(root.left);
        root.right = leafDelete(root.right);
        return root;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node root = null;
        root = insert(root, 20);
        insert(root, 10);
        insert(root, 5);
        insert(root, 15);
        insert(root, 30);
        insert(root, 25);
        insert(root, 35);
        Console.WriteLine("Inorder before Deleting"
                          + "the leaf Node. ");
        inorder(root);
        Console.WriteLine();
        leafDelete(root);
        Console.WriteLine("INorder after Deleting"
                          + "the leaf Node. ");
        inorder(root);
    }
}

/*C# program to find Sum Of All Elements smaller
than or equal to Kth Smallest Element In BST*/

using System;
public class GFG
{

/* Binary tree Node */

  public class Node
  {
    public int data;
    public Node left,  right;
  };

/*  utility function new Node of BST*/

  static Node createNode(int data)
  {
    Node  new_Node = new Node();
    new_Node.left = null;
    new_Node.right = null;
    new_Node.data = data;
    return new_Node;
  }

/*  A utility function to insert a new Node
    with given key in BST and also maintain lcount ,Sum*/

  static Node  insert(Node root, int key)
  {

/*    If the tree is empty, return a new Node*/

    if (root == null)
      return createNode(key);

/*    Otherwise, recur down the tree*/

    if (root.data > key)
      root.left = insert(root.left, key);
    else if (root.data < key)
      root.right = insert(root.right, key);

/*    return the (unchanged) Node pointer*/

    return root;
  }
  static int count = 0;

/*  function return sum of all element smaller than
  and equal to Kth smallest element*/

  static int ksmallestElementSumRec(Node root, int k)
  {

/*    Base cases*/

    if (root == null)
      return 0;
    if (count > k)
      return 0;

/*    Compute sum of elements in left subtree*/

    int res = ksmallestElementSumRec(root.left, k);
    if (count >= k)
      return res;

/*    Add root's data*/

    res += root.data;

/*    Add current Node*/

    count++;
    if (count >= k)
      return res;

/*    If count is less than k, return right subtree Nodes*/

    return res + ksmallestElementSumRec(root.right, k);
  }

/*  Wrapper over ksmallestElementSumRec()*/

  static int ksmallestElementSum(Node root, int k)
  {
    int res = ksmallestElementSumRec(root, k);
    return res;
  }

/* Driver program to test above functions */

  public static void Main(String[] args)
  {

/*    20
        /    \
       8     22
     /   \
    4     12
         /   \
        10    14
          */

    Node root = null;
    root = insert(root, 20);
    root = insert(root, 8);
    root = insert(root, 4);
    root = insert(root, 12);
    root = insert(root, 10);
    root = insert(root, 14);
    root = insert(root, 22);
    int k = 3;
    int count = ksmallestElementSum(root, k);
    Console.WriteLine(count);
  }
}

/*C# program to find Sum Of All Elements smaller
than or equal t Kth Smallest Element In BST*/

using System;
public class GFG
{

/* Binary tree Node */

public class Node
{
   public int data;
   public int lCount;
   public int Sum ;
   public Node left;
   public Node right;
};

/*utility function new Node of BST*/

static Node createNode(int data)
{
    Node  new_Node = new Node();
    new_Node.left = null;
    new_Node.right = null;
    new_Node.data = data;
    new_Node.lCount = 0 ;
    new_Node.Sum = 0;
    return new_Node;
}

/*A utility function to insert a new Node with
given key in BST and also maintain lcount ,Sum*/

static Node  insert(Node root, int key)
{

/*    If the tree is empty, return a new Node*/

    if (root == null)
        return createNode(key);

/*    Otherwise, recur down the tree*/

    if (root.data > key)
    {

/*        increment lCount of current Node*/

        root.lCount++;

/*        increment current Node sum by adding
        key into it*/

        root.Sum += key;
        root.left = insert(root.left , key);
    }
    else if (root.data < key )
        root.right = insert (root.right , key );

/*    return the (unchanged) Node pointer*/

    return root;
}
static int temp_sum;

/*function return sum of all element smaller than and equal
to Kth smallest element*/

static void ksmallestElementSumRec(Node root, int k )
{
    if (root == null)
        return ;

/*    if we fount k smallest element then break the function*/

    if ((root.lCount + 1) == k)
    {
        temp_sum += root.data + root.Sum ;
        return ;
    }
    else if (k > root.lCount)
    {

/*        store sum of all element smaller than current root ;*/

        temp_sum += root.data + root.Sum;

/*        decremented k and call right sub-tree*/

        k = k -( root.lCount + 1);
        ksmallestElementSumRec(root.right , k );
    }

/*call left sub-tree*/

else 
        ksmallestElementSumRec(root.left , k );
}

/*Wrapper over ksmallestElementSumRec()*/

static void ksmallestElementSum(Node root, int k)
{
    temp_sum = 0;
    ksmallestElementSumRec(root, k);
}

/* Driver program to test above functions */

public static void Main(String[] args)
{

/*    20
        /    \
       8     22
     /   \
    4     12
         /   \
        10    14
          */

    Node root = null;
    root = insert(root, 20);
    root = insert(root, 8);
    root = insert(root, 4);
    root = insert(root, 12);
    root = insert(root, 10);
    root = insert(root, 14);
    root = insert(root, 22);
    int k = 3;
     ksmallestElementSum(root, k);
     Console.WriteLine(temp_sum);
}
}

/*C# program to find minimum
value node in Binary Search Tree*/

using System;

/*A binary tree node*/

public
  class Node
  {
    public
      int data;
    public
      Node left, right, parent;
    public
      Node(int d)
    {
      data = d;
      left = right = parent = null;
    }
  }
public class BinaryTree
{
  static Node head;

/* Given a binary search tree and a number,
     inserts a new node with the given number in
     the correct place in the tree. Returns the new
     root pointer which the caller should then use
     (the standard trick to avoid using reference
     parameters). */

  Node insert(Node node, int data)
  {

/* 1. If the tree is empty, return a new,    
         single node */

    if (node == null)
    {
      return (new Node(data));
    }
    else
    {
      Node temp = null;

/* 2. Otherwise, recur down the tree */

      if (data <= node.data)
      {
        temp = insert(node.left, data);
        node.left = temp;
        temp.parent = node;
      }
      else
      {
        temp = insert(node.right, data);
        node.right = temp;
        temp.parent = node;
      }

/* return the (unchanged) node pointer */

      return node;
    }
  }
  Node inOrderSuccessor(Node root, Node n)
  {

/*    step 1 of the above algorithm*/

    if (n.right != null)
    {
      return minValue(n.right);
    }

/*    step 2 of the above algorithm*/

    Node p = n.parent;
    while (p != null && n == p.right)
    {
      n = p;
      p = p.parent;
    }
    return p;
  }

/* Given a non-empty binary search
       tree, return the minimum data 
       value found in that tree. Note that
       the entire tree does not need
       to be searched. */

  Node minValue(Node node)
  {
    Node current = node;

/* loop down to find the leftmost leaf */

    while (current.left != null)
    {
      current = current.left;
    }
    return current;
  }

/*  Driver program to test above functions*/

  public static void Main(String[] args)
  {
    BinaryTree tree = new BinaryTree();
    Node root = null, temp = null, suc = null, min = null;
    root = tree.insert(root, 20);
    root = tree.insert(root, 8);
    root = tree.insert(root, 22);
    root = tree.insert(root, 4);
    root = tree.insert(root, 12);
    root = tree.insert(root, 10);
    root = tree.insert(root, 14);
    temp = root.left.right.right;
    suc = tree.inOrderSuccessor(root, temp);
    if (suc != null) {
      Console.WriteLine(
        "Inorder successor of "
        + temp.data + " is " + suc.data);
    }
    else {
      Console.WriteLine(
        "Inorder successor does not exist");
    }
  }
}

