/*C# program to find predecessor
and successor in a BST*/

using System;
class GFG
{

/*BST Node*/

class Node
{
    public int key;
    public Node left, right;
};
static Node pre;
static Node suc;

/*Function that finds predecessor
and successor of key in BST.*/

static void findPreSuc(Node root, int key)
{
    if (root == null)
        return;

/*    Search for given key in BST.*/

    while (root != null)
    {

/*        If root is given key.*/

        if (root.key == key)
        {

/*            the minimum value in right subtree
            is predecessor.*/

            if (root.right != null)
            {
                suc = root.right;
                while (suc.left != null)
                    suc = suc.left;
            }

/*            the maximum value in left subtree
            is successor.*/

            if (root.left != null)
            {
                pre = root.left;
                while (pre.right != null)
                    pre = pre.right;
            }
            return;
        }

/*        If key is greater than root, then
        key lies in right subtree. Root
        could be predecessor if left
        subtree of key is null.*/

        else if (root.key < key)
        {
            pre = root;
            root = root.right;
        }

/*        If key is smaller than root, then
        key lies in left subtree. Root
        could be successor if right
        subtree of key is null.*/

        else
        {
            suc = root;
            root = root.left;
        }
    }
}

/*A utility function to create a new BST node*/

static Node newNode(int item)
{
    Node temp = new Node();
    temp.key = item;
    temp.left = temp.right = null;
    return temp;
}

/*A utility function to insert
a new node with given key in BST*/

static Node insert(Node node, int key)
{
    if (node == null)
        return newNode(key);
    if (key < node.key)
        node.left = insert(node.left, key);
    else
        node.right = insert(node.right, key);
    return node;
}

/*Driver Code*/

public static void Main(String[] args)
{

/*Key to be searched in BST*/

int key = 65;

/* Let us create following BST
                50
                / \
            / \
            30     70
            / \     / \
            / \ / \
        20 40 60 80
    */

    Node root = null;
    root = insert(root, 50);
    insert(root, 30);
    insert(root, 20);
    insert(root, 40);
    insert(root, 70);
    insert(root, 60);
    insert(root, 80);
    findPreSuc(root, key);
    if (pre != null)
        Console.WriteLine("Predecessor is " +
                                    pre.key);
    else
        Console.Write("-1");
    if (suc != null)
        Console.Write("Successor is " + suc.key);
    else
        Console.Write("-1");
    }
}

/*A C# program to check if there
is a triplet with sum equal to 0 in
a given BST*/

using System;
public class GFG
{

/*  A BST node has key, and left and right pointers*/

  public class node
  {
    public int key;
    public  node left;
    public  node right;
  };
  static node head;
  static node tail;

/*  A function to convert given BST to Doubly
  Linked List. left pointer is used
  as previous pointer and right pointer
  is used as next pointer. The function
  sets *head to point to first and *tail
  to point to last node of converted DLL*/

  static void convertBSTtoDLL(node root)
  {

/*    Base case*/

    if (root == null)
      return;

/*    First convert the left subtree*/

    if (root.left != null)
      convertBSTtoDLL(root.left);

/*    Then change left of current root
    as last node of left subtree*/

    root.left = tail;

/*    If tail is not null, then set right
    of tail as root, else current
    node is head*/

    if (tail != null)
      (tail).right = root;
    else
      head = root;

/*    Update tail*/

    tail = root;

/*    Finally, convert right subtree*/

    if (root.right != null)
      convertBSTtoDLL(root.right);
  }

/*  This function returns true if there
  is pair in DLL with sum equal to given
  sum. The algorithm is similar to hasArrayTwoCandidates()
tinyurl.com/dy6palr
in method 1 of http:*/

  static bool isPresentInDLL(node head, node tail, int sum)
  {
    while (head != tail)
    {
      int curr = head.key + tail.key;
      if (curr == sum)
        return true;
      else if (curr > sum)
        tail = tail.left;
      else
        head = head.right;
    }
    return false;
  }

/*  The main function that returns
  true if there is a 0 sum triplet in
  BST otherwise returns false*/

  static bool isTripletPresent(node root)
  {

/*    Check if the given BST is empty*/

    if (root == null)
      return false;

/*    Convert given BST to doubly linked list. head and tail store the
    pointers to first and last nodes in DLLL*/

    head = null;
    tail = null;
    convertBSTtoDLL(root);

/*    Now iterate through every node and
    find if there is a pair with sum
    equal to -1 * heaf.key where head is current node*/

    while ((head.right != tail) && (head.key < 0))
    {

/*      If there is a pair with sum
      equal to -1*head.key, then return
      true else move forward*/

      if (isPresentInDLL(head.right, tail, -1*head.key))
        return true;
      else
        head = head.right;
    }

/*    If we reach here, then
    there was no 0 sum triplet*/

    return false;
  }

/*  A utility function to create
  a new BST node with key as given num*/

  static node newNode(int num)
  {
    node temp = new node();
    temp.key = num;
    temp.left = temp.right = null;
    return temp;
  }

/*  A utility function to insert a given key to BST*/

  static node insert(node root, int key)
  {
    if (root == null)
      return newNode(key);
    if (root.key > key)
      root.left = insert(root.left, key);
    else
      root.right = insert(root.right, key);
    return root;
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    node root = null;
    root = insert(root, 6);
    root = insert(root, -13);
    root = insert(root, 14);
    root = insert(root, -8);
    root = insert(root, 15);
    root = insert(root, 13);
    root = insert(root, 7);
    if (isTripletPresent(root))
      Console.Write("Present");
    else
      Console.Write("Not Present");
  }
}

/*C# code to find a pair with given sum
in a Balanced BST*/

using System;
using System.Collections.Generic;

/*A binary tree node*/

public class Node {
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
public class BinarySearchTree {

/*    Root of BST*/

    Node root;

/*    Constructor*/

    BinarySearchTree()
    {
        root = null;
    }

/*    Inorder traversal of the tree*/

    void inorder()
    {
        inorderUtil(this.root);
    }

/*    Utility function for inorder traversal of the tree*/

    void inorderUtil(Node node)
    {
        if (node == null)
            return;
        inorderUtil(node.left);
        Console.Write(node.data + " ");
        inorderUtil(node.right);
    }

/*    This method mainly calls insertRec()*/

    void insert(int key)
    {
        root = insertRec(root, key);
    }

/* A recursive function to insert a new key in BST */

    Node insertRec(Node root, int data)
    {

/* If the tree is empty, return a new node */

        if (root == null) {
            root = new Node(data);
            return root;
        }

/* Otherwise, recur down the tree */

        if (data < root.data)
            root.left = insertRec(root.left, data);
        else if (data > root.data)
            root.right = insertRec(root.right, data);
        return root;
    }

/*    Method that adds values of given BST into ArrayList
    and hence returns the ArrayList*/

    List<int> treeToList(Node node, List<int> list)
    {

/*        Base Case*/

        if (node == null)
            return list;
        treeToList(node.left, list);
        list.Add(node.data);
        treeToList(node.right, list);
        return list;
    }

/*    method that checks if there is a pair present*/

    bool isPairPresent(Node node, int target)
    {

/*        This list a1 is passed as an argument
        in treeToList method
        which is later on filled by the values of BST*/

        List<int> a1 = new List<int>();

/*        a2 list contains all the values of BST
        returned by treeToList method*/

        List<int> a2 = treeToList(node, a1);

/*Starting index of a2*/

int start = 0;

/*Ending index of a2*/

int end = a2.Count - 1; 
        while (start < end) {

/*Target Found!*/

if (a2[start] + a2[end] == target) 
            {
                Console.WriteLine("Pair Found: " + a2[start] + " + " + a2[end] + " "
                                  + "= " + target);
                return true;
            }

/*decrements end*/

if (a2[start] + a2[end] > target) 
            {
                end--;
            }

/*increments start*/

if (a2[start] + a2[end] < target) 
            {
                start++;
            }
        }
        Console.WriteLine("No such values are found!");
        return false;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        BinarySearchTree tree = new BinarySearchTree();

/*
                15
                /     \
            10     20
            / \     / \
            8 12 16 25 */

        tree.insert(15);
        tree.insert(10);
        tree.insert(20);
        tree.insert(8);
        tree.insert(12);
        tree.insert(16);
        tree.insert(25);
        tree.isPairPresent(tree.root, 33);
    }
}

/* In a balanced binary search tree
isPairPresent two element which sums to
a given value time O(n) space O(logn) */

using System;
using System.Collections.Generic;
public class GFG
{
static readonly int MAX_SIZE= 100;

/*A BST node*/

public
 class node
{
    public
 int val;
    public
 node left, right;
};

/*Stack type*/

public
 class Stack
{
    public
 int size;
    public
 int top;
    public
 node []array;
};

/*A utility function to create a stack of given size*/

static Stack createStack(int size)
{
    Stack stack = new Stack();
    stack.size = size;
    stack.top = -1;
    stack.array = new node[stack.size];
    return stack;
}

/*BASIC OPERATIONS OF STACK*/

static int isFull(Stack stack)
{
    return (stack.top - 1 == stack.size) ? 1 : 0 ;
}
static int isEmpty(Stack stack)
{
    return stack.top == -1?1:0;
}
static void push(Stack stack, node node)
{
    if (isFull(stack)==1)
        return;
    stack.array[++stack.top] = node;
}
static node pop(Stack stack)
{
    if (isEmpty(stack) == 1)
        return null;
    return stack.array[stack.top--];
}

/*Returns true if a pair with target
sum exists in BST, otherwise false*/

static bool isPairPresent(node root, int target)
{

/*    Create two stacks. s1 is used for
    normal inorder traversal and s2 is
    used for reverse inorder traversal*/

    Stack s1 = createStack(MAX_SIZE);
    Stack s2 = createStack(MAX_SIZE);

/*    Note the sizes of stacks is MAX_SIZE,
    we can find the tree size and fix stack size
    as O(Logn) for balanced trees like AVL and Red Black
    tree. We have used MAX_SIZE to keep the code simple
    done1, val1 and curr1 are used for
    normal inorder traversal using s1
    done2, val2 and curr2 are used for
    reverse inorder traversal using s2*/

    bool done1 = false, done2 = false;
    int val1 = 0, val2 = 0;
    node curr1 = root, curr2 = root;

/*    The loop will break when we either
  find a pair or one of the two
    traversals is complete*/

    while (true)
    {

/*        Find next node in normal Inorder
        traversal. See following post
www.geeksforgeeks.org/inorder-tree-traversal-without-recursion/
https:*/

        while (done1 == false)
        {
            if (curr1 != null)
            {
                push(s1, curr1);
                curr1 = curr1.left;
            }
            else
            {
                if (isEmpty(s1) == 1)
                    done1 = true;
                else
                {
                    curr1 = pop(s1);
                    val1 = curr1.val;
                    curr1 = curr1.right;
                    done1 = true;
                }
            }
        }

/*        Find next node in REVERSE Inorder traversal. The only
        difference between above and below loop is, in below loop
        right subtree is traversed before left subtree*/

        while (done2 == false)
        {
            if (curr2 != null)
            {
                push(s2, curr2);
                curr2 = curr2.right;
            }
            else {
                if (isEmpty(s2) == 1)
                    done2 = true;
                else {
                    curr2 = pop(s2);
                    val2 = curr2.val;
                    curr2 = curr2.left;
                    done2 = true;
                }
            }
        }

/*        If we find a pair, then print the pair and return. The first
        condition makes sure that two same values are not added*/

        if ((val1 != val2) && (val1 + val2) == target)
        {
            Console.Write("Pair Found: " +
                             val1+ "+ " +
                             val2+ " = " + 
                             target +"\n");
            return true;
        }

/*        If sum of current values is smaller,
        then move to next node in
        normal inorder traversal*/

        else if ((val1 + val2) < target)
            done1 = false;

/*        If sum of current values is greater,
        then move to next node in
        reverse inorder traversal*/

        else if ((val1 + val2) > target)
            done2 = false;

/*        If any of the inorder traversals is
        over, then there is no pair
        so return false*/

        if (val1 >= val2)
            return false;
    }
}

/*A utility function to create BST node*/

static node NewNode(int val)
{
    node tmp = new node();
    tmp.val = val;
    tmp.right = tmp.left = null;
    return tmp;
}

