/*C# program to find a pair with
given sum using hashing*/

using System;
using System.Collections.Generic;
class GFG {
    class Node {
        public int data;
        public Node left, right;
    };
    static Node NewNode(int data)
    {
        Node temp = new Node();
        temp.data = data;
        temp.left = null;
        temp.right = null;
        return temp;
    }
    static Node insert(Node root, int key)
    {
        if (root == null)
            return NewNode(key);
        if (key < root.data)
            root.left = insert(root.left, key);
        else
            root.right = insert(root.right, key);
        return root;
    }
    static bool findpairUtil(Node root, int sum,
                             HashSet<int> set)
    {
        if (root == null)
            return false;
        if (findpairUtil(root.left, sum, set))
            return true;
        if (set.Contains(sum - root.data)) {
            Console.WriteLine("Pair is found ("
                              + (sum - root.data) + ", "
                              + root.data + ")");
            return true;
        }
        else
            set.Add(root.data);
        return findpairUtil(root.right, sum, set);
    }
    static void findPair(Node root, int sum)
    {
        HashSet<int> set = new HashSet<int>();
        if (!findpairUtil(root, sum, set))
            Console.Write("Pairs do not exit"
                          + "\n");
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node root = null;
        root = insert(root, 15);
        root = insert(root, 10);
        root = insert(root, 20);
        root = insert(root, 8);
        root = insert(root, 12);
        root = insert(root, 16);
        root = insert(root, 25);
        root = insert(root, 10);
        int sum = 33;
        findPair(root, sum);
    }
}

/*C# program to find maximum element in the path
between two Nodes of Binary Search Tree.*/

public class Solution
{
public class Node
{
     public Node left, right;
    public int data;
}

/*Create and return a pointer of new Node.*/

public static Node createNode(int x)
{
    Node p = new Node();
    p.data = x;
    p.left = p.right = null;
    return p;
}

/*Insert a new Node in Binary Search Tree.*/

public static void insertNode(Node root, int x)
{
    Node p = root, q = null;
    while (p != null)
    {
        q = p;
        if (p.data < x)
        {
            p = p.right;
        }
        else
        {
            p = p.left;
        }
    }
    if (q == null)
    {
        p = createNode(x);
    }
    else
    {
        if (q.data < x)
        {
            q.right = createNode(x);
        }
        else
        {
            q.left = createNode(x);
        }
    }
}

/*Return the maximum element between a Node
and its given ancestor.*/

public static int maxelpath(Node q, int x)
{
    Node p = q;
    int mx = -1;

/*    Traversing the path between ansector and
    Node and finding maximum element.*/

    while (p.data != x)
    {
        if (p.data > x)
        {
            mx = Math.Max(mx, p.data);
            p = p.left;
        }
        else
        {
            mx = Math.Max(mx, p.data);
            p = p.right;
        }
    }
    return Math.Max(mx, x);
}

/*Return maximum element in the path between
two given Node of BST.*/

public static int maximumElement(Node root, int x, int y)
{
    Node p = root;

/*    Finding the LCA of Node x and Node y*/

    while ((x < p.data && y < p.data) || (x > p.data && y > p.data))
    {

/*        Checking if both the Node lie on the
        left side of the parent p.*/

        if (x < p.data && y < p.data)
        {
            p = p.left;
        }

/*        Checking if both the Node lie on the
        right side of the parent p.*/

        else if (x > p.data && y > p.data)
        {
            p = p.right;
        }
    }

/*    Return the maximum of maximum elements occur
    in path from ancestor to both Node.*/

    return Math.Max(maxelpath(p, x), maxelpath(p, y));
}

/*Driver Code*/

public static void Main(string[] args)
{
    int[] arr = new int[] {18, 36, 9, 6, 12, 10, 1, 8};
    int a = 1, b = 10;
    int n = arr.Length;

/*    Creating the root of Binary Search Tree*/

     Node root = createNode(arr[0]);

/*    Inserting Nodes in Binary Search Tree*/

    for (int i = 1; i < n; i++)
    {
        insertNode(root, arr[i]);
    }
    Console.WriteLine(maximumElement(root, a, b));
}
}

/*C# program to find pairs with given sum such 
that one element of pair exists in one BST and 
other in other BST. */

using System;
using System.Collections.Generic;
public class solution
{

/*A binary Tree node */

public class Node
{
    public int data;
     public Node left, right;
}

/*A utility function to create a new BST node 
with key as given num */

public static Node newNode(int num)
{
     Node temp = new Node();
    temp.data = num;
    temp.left = temp.right = null;
    return temp;
}

/*A utility function to insert a given key to BST */

public static Node insert(Node root, int key)
{
    if (root == null)
    {
        return newNode(key);
    }
    if (root.data > key)
    {
        root.left = insert(root.left, key);
    }
    else
    {
        root.right = insert(root.right, key);
    }
    return root;
}

/*store storeInorder traversal in auxiliary array */

public static void storeInorder(Node ptr, List<int> vect)
{
    if (ptr == null)
    {
        return;
    }
    storeInorder(ptr.left, vect);
    vect.Add(ptr.data);
    storeInorder(ptr.right, vect);
}

/*Function to find pair for given sum in different bst 
vect1.get()  -. stores storeInorder traversal of first bst 
vect2.get()  -. stores storeInorder traversal of second bst */

public static void pairSumUtil(List<int> vect1, List<int> vect2, int sum)
{

/*    Initialize two indexes to two different corners 
    of two Vectors. */

    int left = 0;
    int right = vect2.Count - 1;

/*    find pair by moving two corners. */

    while (left < vect1.Count && right >= 0)
    {

/*        If we found a pair */

        if (vect1[left] + vect2[right] == sum)
        {
            Console.Write("(" + vect1[left] + ", " + vect2[right] + "), ");
            left++;
            right--;
        }

/*        If sum is more, move to higher value in 
        first Vector. */

        else if (vect1[left] + vect2[right] < sum)
        {
            left++;
        }

/*        If sum is less, move to lower value in 
        second Vector. */

        else
        {
            right--;
        }
    }
}

/*Prints all pairs with given "sum" such that one 
element of pair is in tree with root1 and other 
node is in tree with root2. */

public static void pairSum(Node root1, Node root2, int sum)
{

/*    Store inorder traversals of two BSTs in two 
    Vectors. */

    List<int> vect1 = new List<int>(), vect2 = new List<int>();
    storeInorder(root1, vect1);
    storeInorder(root2, vect2);

/*    Now the problem reduces to finding a pair 
    with given sum such that one element is in 
    vect1 and other is in vect2. */

    pairSumUtil(vect1, vect2, sum);
}

/*Driver program to run the case */

public static void Main(string[] args)
{

/*    first BST */

     Node root1 = null;
    root1 = insert(root1, 8);
    root1 = insert(root1, 10);
    root1 = insert(root1, 3);
    root1 = insert(root1, 6);
    root1 = insert(root1, 1);
    root1 = insert(root1, 5);
    root1 = insert(root1, 7);
    root1 = insert(root1, 14);
    root1 = insert(root1, 13);

/*    second BST */

     Node root2 = null;
    root2 = insert(root2, 5);
    root2 = insert(root2, 18);
    root2 = insert(root2, 2);
    root2 = insert(root2, 1);
    root2 = insert(root2, 3);
    root2 = insert(root2, 4);
    int sum = 10;
    pairSum(root1, root2, sum);
}
}

/*Recursive C# program to find key closest to k 
in given Binary Search Tree. */
using System;

 public class solution
 {
     public static int min_diff, min_diff_key;

/*  A binary tree node has key, pointer to left child 
and a pointer to right child */

public class Node
{
    public int key;
     public Node left, right;
}

/*  Utility that allocates a new node with the 
  given key and null left and right pointers.  */

public static Node newnode(int key)
 {
     Node node = new Node();
    node.key = key;
    node.left = node.right = null;
    return (node);
 }

/*Function to find node with minimum absolute 
difference with given K 
min_diff   -. minimum difference till now 
min_diff_key  -. node having minimum absolute 
                   difference with K */

public static void maxDiffUtil(Node ptr, int k)
{
    if (ptr == null)
    {
        return;
    }

/*    If k itself is present */

    if (ptr.key == k)
    {
        min_diff_key = k;
        return;
    }

/*    update min_diff and min_diff_key by checking 
    current node value */

    if (min_diff > Math.Abs(ptr.key - k))
    {
        min_diff = Math.Abs(ptr.key - k);
        min_diff_key = ptr.key;
    }

/*    if k is less than ptr.key then move in 
    left subtree else in right subtree */

    if (k < ptr.key)
    {
        maxDiffUtil(ptr.left, k);
    }
    else
    {
        maxDiffUtil(ptr.right, k);
    }
}

/*Wrapper over maxDiffUtil() */

public static int maxDiff(Node root, int k)
{

/*    Initialize minimum difference */

    min_diff = 999999999;
    min_diff_key = -1;

/*    Find value of min_diff_key (Closest key 
    in tree with k) */

    maxDiffUtil(root, k);
    return min_diff_key;
}

/*Driver program to run the case */

public static void Main(string[] args)
{
     Node root = newnode(9);
    root.left = newnode(4);
    root.right = newnode(17);
    root.left.left = newnode(3);
    root.left.right = newnode(6);
    root.left.right.left = newnode(5);
    root.left.right.right = newnode(7);
    root.right.right = newnode(22);
    root.right.right.left = newnode(20);
    int k = 18;
    Console.WriteLine(maxDiff(root, k));
}
 }

/*C# program to implement insert 
operation in Red Black Tree. */

using System;
class node 
{ 
    public node left, right; 
    public int data;

/*    red ==> true, black ==> false */

    public Boolean color; 
    public node(int data) 
    { 
        this.data = data; 
        left = null; 
        right = null;

/*        New Node which is created 
        is always red in color. */

        color = true; 
    } 
} 
public class LLRBTREE 
{ 
private static node root = null;

/*utility function to rotate
node anticlockwise. */

node rotateLeft(node myNode) 
{ 
    Console.Write("left rotation!!\n"); 
    node child = myNode.right; 
    node childLeft = child.left; 
    child.left = myNode; 
    myNode.right = childLeft; 
    return child; 
}

/*utility function to rotate
node clockwise. */

node rotateRight(node myNode) 
{ 
    Console.Write("right rotation\n"); 
    node child = myNode.left; 
    node childRight = child.right; 
    child.right = myNode; 
    myNode.left = childRight; 
    return child; 
}

/*utility function to check whether 
node is red in color or not. */

Boolean isRed(node myNode) 
{ 
    if (myNode == null) 
        return false; 
    return (myNode.color == true); 
}

/*utility function to swap 
color of two nodes. */

void swapColors(node node1, node node2) 
{ 
    Boolean temp = node1.color; 
    node1.color = node2.color; 
    node2.color = temp; 
}

/*insertion into Left
Leaning Red Black Tree. */

node insert(node myNode, int data) 
{

/*    Normal insertion code for 
    any Binary Search tree. */

    if (myNode == null) 
        return new node(data); 
    if (data < myNode.data) 
        myNode.left = insert(myNode.left, data); 
    else if (data > myNode.data) 
        myNode.right = insert(myNode.right, data); 
    else
        return myNode;

/*    case 1. 
    when right child is Red
    but left child is 
    Black or doesn't exist. */

    if (isRed(myNode.right) && 
        !isRed(myNode.left)) 
    {

/*        left rotate the node to make 
        it into valid structure. */

        myNode = rotateLeft(myNode);

/*        swap the colors as the child 
        node should always be red */

        swapColors(myNode, myNode.left); 
    }

/*    case 2 
    when left child as well as 
    left grand child in Red */

    if (isRed(myNode.left) && 
        isRed(myNode.left.left)) 
    {

/*        right rotate the current node 
        to make it into a valid structure. */

        myNode = rotateRight(myNode); 
        swapColors(myNode, myNode.right); 
    }

/*    case 3 
    when both left and right 
    child are Red in color. */

    if (isRed(myNode.left) && 
        isRed(myNode.right)) 
    {

/*        invert the color of node as well 
        it's left and right child. */

        myNode.color = !myNode.color;

/*        change the color to black. */

        myNode.left.color = false; 
        myNode.right.color = false; 
    } 
    return myNode; 
}

/*Inorder traversal */

void inorder(node node) 
{ 
    if (node != null) 
    { 
        inorder(node.left); 
        Console.Write(node.data + " "); 
        inorder(node.right); 
    } 
}

/*Driver Code*/

static public void Main(String []args)
{

/* LLRB tree made after all insertions are made.

    1. Nodes which have double INCOMING edge means
       that they are RED in color.
    2. Nodes which have single INCOMING edge means
       that they are BLACK in color.

        root
         |
         40
       //  \
      20    50
     /  \
   10    30
        //
       25    */
LLRBTREE node = new LLRBTREE(); 
root = node.insert(root, 10);

/*to make sure that root  
remains black is color */

root.color = false; 
root = node.insert(root, 20); 
root.color = false; 
root = node.insert(root, 30); 
root.color = false; 
root = node.insert(root, 40); 
root.color = false; 
root = node.insert(root, 50); 
root.color = false; 
root = node.insert(root, 25); 
root.color = false;

/*display the tree through 
inorder traversal. */

node.inorder(root); 
} 
}

public class Node
{
   public int data;
   public Node left, right;
   public bool rightThread; 
}

/*C# program Insertion in Threaded Binary Search Tree. */

public class solution
{
public class Node
{
     public Node left, right;
    public int info;

/*    True if left pointer points to predecessor 
    in Inorder Traversal */

    public bool lthread;

/*    True if right pointer points to successor 
    in Inorder Traversal */

    public bool rthread;
}

/*Insert a Node in Binary Threaded Tree */

public static Node insert(Node root, int ikey)
{

/*    Searching for a Node with given value */

    Node ptr = root;

/*Parent of key to be inserted*/

Node par = null; 
    while (ptr != null)
    {

/*        If key already exists, return */

        if (ikey == (ptr.info))
        {
            Console.Write("Duplicate Key !\n");
            return root;
        }

/*Update parent pointer*/

par = ptr;

/*        Moving on left subtree. */

        if (ikey < ptr.info)
        {
            if (ptr.lthread == false)
            {
                ptr = ptr.left;
            }
            else
            {
                break;
            }
        }

/*        Moving on right subtree. */

        else
        {
            if (ptr.rthread == false)
            {
                ptr = ptr.right;
            }
            else
            {
                break;
            }
        }
    }

/*    Create a new node */

    Node tmp = new Node();
    tmp.info = ikey;
    tmp.lthread = true;
    tmp.rthread = true;
    if (par == null)
    {
        root = tmp;
        tmp.left = null;
        tmp.right = null;
    }
    else if (ikey < (par.info))
    {
        tmp.left = par.left;
        tmp.right = par;
        par.lthread = false;
        par.left = tmp;
    }
    else
    {
        tmp.left = par;
        tmp.right = par.right;
        par.rthread = false;
        par.right = tmp;
    }
    return root;
}

/*Returns inorder successor using rthread */

public static Node inorderSuccessor(Node ptr)
{

/*    If rthread is set, we can quickly find */

    if (ptr.rthread == true)
    {
        return ptr.right;
    }

/*    Else return leftmost child of right subtree */

    ptr = ptr.right;
    while (ptr.lthread == false)
    {
        ptr = ptr.left;
    }
    return ptr;
}

/*Printing the threaded tree */

public static void inorder(Node root)
{
    if (root == null)
    {
        Console.Write("Tree is empty");
    }

/*    Reach leftmost node */

     Node ptr = root;
    while (ptr.lthread == false)
    {
        ptr = ptr.left;
    }

/*    One by one print successors */

    while (ptr != null)
    {
        Console.Write("{0:D} ",ptr.info);
        ptr = inorderSuccessor(ptr);
    }
}

/*Driver Program */

public static void Main(string[] args)
{
     Node root = null;
    root = insert(root, 20);
    root = insert(root, 10);
    root = insert(root, 30);
    root = insert(root, 5);
    root = insert(root, 16);
    root = insert(root, 14);
    root = insert(root, 17);
    root = insert(root, 13);
    inorder(root);
}
}

public
  class Node
  {
    public
      Node left,
    right;
    public
      int info;

/*    True if left pointer points to predecessor
    in Inorder Traversal*/

    public
      bool lthread;

/*    True if right pointer points to predecessor
    in Inorder Traversal*/

    public
      bool rthread;
  };

/*Complete C# program to demonstrate deletion
in threaded BST*/

using System;
class GFG {
    public class Node {
        public Node left, right;
        public int info;

/*        True if left pointer points to predecessor
        in Inorder Traversal*/

        public bool lthread;

/*        True if right pointer points to predecessor
        in Inorder Traversal*/

        public bool rthread;
    };

/*    Insert a Node in Binary Threaded Tree*/

    static Node insert(Node root, int ikey)
    {

/*        Searching for a Node with given value*/

        Node ptr = root;

/*Parent of key to be inserted*/

Node par = null; 
        while (ptr != null) {

/*            If key already exists, return*/

            if (ikey == (ptr.info)) {
                Console.Write("Duplicate Key !\n");
                return root;
            }

/*Update parent pointer*/

par = ptr;

/*            Moving on left subtree.*/

            if (ikey < ptr.info) {
                if (ptr.lthread == false)
                    ptr = ptr.left;
                else
                    break;
            }

/*            Moving on right subtree.*/

            else {
                if (ptr.rthread == false)
                    ptr = ptr.right;
                else
                    break;
            }
        }

/*        Create a new Node*/

        Node tmp = new Node();
        tmp.info = ikey;
        tmp.lthread = true;
        tmp.rthread = true;
        if (par == null) {
            root = tmp;
            tmp.left = null;
            tmp.right = null;
        }
        else if (ikey < (par.info)) {
            tmp.left = par.left;
            tmp.right = par;
            par.lthread = false;
            par.left = tmp;
        }
        else {
            tmp.left = par;
            tmp.right = par.right;
            par.rthread = false;
            par.right = tmp;
        }
        return root;
    }

/*    Returns inorder successor using left
    and right children (Used in deletion)*/

    static Node inSucc(Node ptr)
    {
        if (ptr.rthread == true)
            return ptr.right;
        ptr = ptr.right;
        while (ptr.lthread == false)
            ptr = ptr.left;
        return ptr;
    }

/*    Returns inorder successor using rthread
    (Used in inorder)*/

    static Node inorderSuccessor(Node ptr)
    {

/*        If rthread is set, we can quickly find*/

        if (ptr.rthread == true)
            return ptr.right;

/*        Else return leftmost child of right subtree*/

        ptr = ptr.right;
        while (ptr.lthread == false)
            ptr = ptr.left;
        return ptr;
    }

/*    Printing the threaded tree*/

    static void inorder(Node root)
    {
        if (root == null)
            Console.Write("Tree is empty");

/*        Reach leftmost Node*/

        Node ptr = root;
        while (ptr.lthread == false)
            ptr = ptr.left;

/*        One by one print successors*/

        while (ptr != null) {
            Console.Write("{0} ", ptr.info);
            ptr = inorderSuccessor(ptr);
        }
    }
    static Node inPred(Node ptr)
    {
        if (ptr.lthread == true)
            return ptr.left;
        ptr = ptr.left;
        while (ptr.rthread == false)
            ptr = ptr.right;
        return ptr;
    }

/*    Here 'par' is pointer to parent Node and 'ptr' is
    pointer to current Node.*/

    static Node caseA(Node root, Node par,
                      Node ptr)
    {

/*        If Node to be deleted is root*/

        if (par == null)
            root = null;

/*        If Node to be deleted is left
        of its parent*/

        else if (ptr == par.left) {
            par.lthread = true;
            par.left = ptr.left;
        }
        else {
            par.rthread = true;
            par.right = ptr.right;
        }
        return root;
    }

/*    Here 'par' is pointer to parent Node and 'ptr' is
    pointer to current Node.*/

    static Node caseB(Node root, Node par,
                      Node ptr)
    {
        Node child;

/*        Initialize child Node to be deleted has
        left child.*/

        if (ptr.lthread == false)
            child = ptr.left;

/*        Node to be deleted has right child.*/

        else
            child = ptr.right;

/*        Node to be deleted is root Node.*/

        if (par == null)
            root = child;

/*        Node is left child of its parent.*/

        else if (ptr == par.left)
            par.left = child;
        else
            par.right = child;

/*        Find successor and predecessor*/

        Node s = inSucc(ptr);
        Node p = inPred(ptr);

/*        If ptr has left subtree.*/

        if (ptr.lthread == false)
            p.right = s;

/*        If ptr has right subtree.*/

        else {
            if (ptr.rthread == false)
                s.left = p;
        }
        return root;
    }

/*    Here 'par' is pointer to parent Node and 'ptr' is
    pointer to current Node.*/

    static Node caseC(Node root, Node par,
                      Node ptr)
    {

/*        Find inorder successor and its parent.*/

        Node parsucc = ptr;
        Node succ = ptr.right;

/*        Find leftmost child of successor*/

        while (succ.lthread == false) {
            parsucc = succ;
            succ = succ.left;
        }
        ptr.info = succ.info;
        if (succ.lthread == true && succ.rthread == true)
            root = caseA(root, parsucc, succ);
        else
            root = caseB(root, parsucc, succ);
        return root;
    }

/*    Deletes a key from threaded BST with given root and
    returns new root of BST.*/

    static Node delThreadedBST(Node root, int dkey)
    {

/*        Initialize parent as null and ptrent
        Node as root.*/

        Node par = null, ptr = root;

/*        Set true if key is found*/

        int found = 0;

/*        Search key in BST : find Node and its
        parent.*/

        while (ptr != null) {
            if (dkey == ptr.info) {
                found = 1;
                break;
            }
            par = ptr;
            if (dkey < ptr.info) {
                if (ptr.lthread == false)
                    ptr = ptr.left;
                else
                    break;
            }
            else {
                if (ptr.rthread == false)
                    ptr = ptr.right;
                else
                    break;
            }
        }
        if (found == 0)
            Console.Write("dkey not present in tree\n");

/*        Two Children*/

        else if (ptr.lthread == false && ptr.rthread == false)
            root = caseC(root, par, ptr);

/*        Only Left Child*/

        else if (ptr.lthread == false)
            root = caseB(root, par, ptr);

/*        Only Right Child*/

        else if (ptr.rthread == false)
            root = caseB(root, par, ptr);

/*        No child*/

        else
            root = caseA(root, par, ptr);
        return root;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node root = null;
        root = insert(root, 20);
        root = insert(root, 10);
        root = insert(root, 30);
        root = insert(root, 5);
        root = insert(root, 16);
        root = insert(root, 14);
        root = insert(root, 17);
        root = insert(root, 13);
        root = delThreadedBST(root, 20);
        inorder(root);
    }
}

/* C# program to convert a Binary Tree to 
    Threaded Tree */using System;
public class solution
{

/* structure of a node in threaded binary tree */

public class Node
{
    public int key;
    public Node left, right;

/*    Used to indicate whether the right pointer 
    is a normal right pointer or a pointer 
    to inorder successor. */

    public bool isThreaded;
}

/*Converts tree with given root to threaded 
binary tree. 
This function returns rightmost child of 
root. */

public static Node createThreaded(Node root)
{

/*    Base cases : Tree is empty or has single 
                  node */

    if (root == null)
    {
        return null;
    }
    if (root.left == null && root.right == null)
    {
        return root;
    }

/*    Find predecessor if it exists */

    if (root.left != null)
    {

/*        Find predecessor of root (Rightmost 
        child in left subtree) */

        Node l = createThreaded(root.left);

/*        Link a thread from predecessor to 
        root. */

        l.right = root;
        l.isThreaded = true;
    }

/*    If current node is rightmost child */

    if (root.right == null)
    {
        return root;
    }

/*    Recur for right subtree. */

    return createThreaded(root.right);
}

/*A utility function to find leftmost node 
in a binary tree rooted with 'root'. 
This function is used in inOrder() */

public static Node leftMost(Node root)
{
    while (root != null && root.left != null)
    {
        root = root.left;
    }
    return root;
}

/*Function to do inorder traversal of a threadded 
binary tree */

public static void inOrder(Node root)
{
    if (root == null)
    {
        return;
    }

/*    Find the leftmost node in Binary Tree */

    Node cur = leftMost(root);
    while (cur != null)
    {
        Console.Write(cur.key + " ");

/*        If this Node is a thread Node, then go to 
        inorder successor */

        if (cur.isThreaded)
        {
            cur = cur.right;
        }

/*Else go to the leftmost child in right subtree*/

else 
        {
            cur = leftMost(cur.right);
        }
    }
}

/*A utility function to create a new node */

public static Node newNode(int key)
{
    Node temp = new Node();
    temp.left = temp.right = null;
    temp.key = key;
    return temp;
}

/*Driver program to test above functions */

public static void Main(string[] args)
{

/*       1 
            / \ 
           2   3 
          / \ / \ 
         4  5 6  7   */

    Node root = newNode(1);
    root.left = newNode(2);
    root.right = newNode(3);
    root.left.left = newNode(4);
    root.left.right = newNode(5);
    root.right.left = newNode(6);
    root.right.right = newNode(7);
    createThreaded(root);
    Console.WriteLine("Inorder traversal of created " + "threaded tree is\n");
    inOrder(root);
}
}

/*C# program to print inorder traversal
of a Binary Search Tree without
recursion and stack*/

using System;

/*BST node*/

class Node
{
    public int key;
    public Node left, right, parent;
    public Node(int key)
    {
        this.key = key;
        left = right = parent = null;
    }
}
class BinaryTree
{
Node root;

/* A utility function to insert a
new node with given key in BST */

Node insert(Node node, int key)
{

/* If the tree is empty,
       return a new node */

    if (node == null)
        return new Node(key);

/* Otherwise, recur down the tree */

    if (key < node.key)
    {
        node.left = insert(node.left, key);
        node.left.parent = node;
    }
    else if (key > node.key)
    {
        node.right = insert(node.right, key);
        node.right.parent = node;
    }

/* return the (unchanged) node pointer */

    return node;
}

/*Function to print inorder traversal
using parent pointer*/

void inorder(Node root)
{
    Boolean leftdone = false;

/*    Start traversal from root*/

    while (root != null)
    {

/*        If left child is not traversed,
        find the leftmost child*/

        if (!leftdone)
        {
            while (root.left != null)
            {
                root = root.left;
            }
        }

/*        Print root's data*/

        Console.Write(root.key + " ");

/*        Mark left as done*/

        leftdone = true;

/*        If right child exists*/

        if (root.right != null)
        {
            leftdone = false;
            root = root.right;
        }

/*        If right child doesn't exist,
        move to parent*/

        else if (root.parent != null)
        {

/*            If this node is right child
            of its parent, visit parent's
            parent first*/

            while (root.parent != null &&
                   root == root.parent.right)
                root = root.parent;
            if (root.parent == null)
                break;
            root = root.parent;
        }
        else
            break;
    }
}

/*Driver Code*/

static public void Main(String[] args)
{
    BinaryTree tree = new BinaryTree();
    tree.root = tree.insert(tree.root, 24);
    tree.root = tree.insert(tree.root, 27);
    tree.root = tree.insert(tree.root, 29);
    tree.root = tree.insert(tree.root, 34);
    tree.root = tree.insert(tree.root, 14);
    tree.root = tree.insert(tree.root, 4);
    tree.root = tree.insert(tree.root, 10);
    tree.root = tree.insert(tree.root, 22);
    tree.root = tree.insert(tree.root, 13);
    tree.root = tree.insert(tree.root, 3);
    tree.root = tree.insert(tree.root, 2);
    tree.root = tree.insert(tree.root, 6);
    Console.WriteLine("Inorder traversal is ");
    tree.inorder(tree.root);
}
}

