/*C# program to find ceil of a given value in BST*/
using System;

/* A binary tree node has key, left child and right child */

public class Node {
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
public class BinaryTree {
    public static Node root;

/*    Function to find ceil of a given input in BST. If input is more
    than the max key in BST, return -1*/

    public virtual int Ceil(Node node, int input)
    {

/*        Base case*/

        if (node == null) {
            return -1;
        }

/*        We found equal key*/

        if (node.data == input) {
            return node.data;
        }

/*        If root's key is smaller, ceil must be in right subtree*/

        if (node.data < input) {
            return Ceil(node.right, input);
        }

/*        Else, either left subtree or root has the ceil value*/

        int ceil = Ceil(node.left, input);
        return (ceil >= input) ? ceil : node.data;
    }

/*    Driver program to test the above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        BinaryTree.root = new Node(8);
        BinaryTree.root.left = new Node(4);
        BinaryTree.root.right = new Node(12);
        BinaryTree.root.left.left = new Node(2);
        BinaryTree.root.left.right = new Node(6);
        BinaryTree.root.right.left = new Node(10);
        BinaryTree.root.right.right = new Node(14);
        for (int i = 0; i < 16; i++) {
            Console.WriteLine(i + " " + tree.Ceil(root, i));
        }
    }
}

/*C# program to find floor and ceil
of a given key in BST*/

using System;

/*A binary tree node has key,
left child and right child*/

public class Node
{
    public int data;
    public Node left, right;
    public Node(int d)
    {
        data = d;
        left = right = null;
    }
}
public class BinaryTree{
public static Node root;
int floor;
int ceil;

/*Helper function to find floor and
ceil of a given key in BST*/

public int floorCeilBSTHelper(Node root, int key)
{
    while (root != null)
    {
        if (root.data == key)
        {
            ceil = root.data;
            floor = root.data;
            return 0;
        }
        if (key > root.data)
        {
            floor = root.data;
            root = root.right;
        }
        else   
        {
            ceil = root.data;
            root = root.left;
        }
    }
    return 0;
}

/*Display the floor and ceil of a
given key in BST. If key is less
than the min key in BST, floor
will be -1; If key is more than
the max key in BST, ceil will be -1;*/

public void floorCeilBST(Node root, int key)
{

/*    Variables 'floor' and 'ceil'
    are passed by reference*/

    floor = -1;
    ceil = -1;
    floorCeilBSTHelper(root, key);
    Console.WriteLine(key + " " + floor +
                            " " + ceil);
}

/*Driver code*/

static public void Main()
{
    BinaryTree tree = new BinaryTree();
    BinaryTree.root = new Node(8);
    BinaryTree.root.left = new Node(4);
    BinaryTree.root.right = new Node(12);
    BinaryTree.root.left.left = new Node(2);
    BinaryTree.root.left.right = new Node(6);
    BinaryTree.root.right.left = new Node(10);
    BinaryTree.root.right.right = new Node(14);
    for(int i = 0; i < 16; i++)
    {
        tree.floorCeilBST(BinaryTree.root, i);
    }
}
}

/*C# program to implement basic operations
(search, insert and delete) on a BST that
handles duplicates by storing count with
every node*/

using System;
class GFG
{
public class node
{
    public int key;
    public int count;
    public node left, right;
};

/*A utility function to create
a new BST node*/

static node newNode(int item)
{
    node temp = new node();
    temp.key = item;
    temp.left = temp.right = null;
    temp.count = 1;
    return temp;
}

/*A utility function to do inorder
traversal of BST*/

static void inorder(node root)
{
    if (root != null)
    {
        inorder(root.left);
        Console.Write(root.key + "(" +
                      root.count + ") ");
        inorder(root.right);
    }
}

/* A utility function to insert a new
node with given key in BST */

static node insert(node node, int key)
{

/* If the tree is empty,
    return a new node */

    if (node == null) return newNode(key);

/*    If key already exists in BST,
    increment count and return*/

    if (key == node.key)
    {
        (node.count)++;
        return node;
    }

/* Otherwise, recur down the tree */

    if (key < node.key)
        node.left = insert(node.left, key);
    else
        node.right = insert(node.right, key);

/* return the (unchanged) node pointer */

    return node;
}

/* Given a non-empty binary search tree,
return the node with minimum key value
found in that tree. Note that the entire tree
does not need to be searched. */

static node minValueNode(node node)
{
    node current = node;

/* loop down to find the leftmost leaf */

    while (current.left != null)
        current = current.left;
    return current;
}

/* Given a binary search tree and a key,
this function deletes a given key and
returns root of modified tree */

static node deleteNode(node root, int key)
{

/*    base case*/

    if (root == null) return root;

/*    If the key to be deleted is smaller than the
    root's key, then it lies in left subtree*/

    if (key < root.key)
        root.left = deleteNode(root.left, key);

/*    If the key to be deleted is greater than
    the root's key, then it lies in right subtree*/

    else if (key > root.key)
        root.right = deleteNode(root.right, key);

/*    if key is same as root's key*/

    else
    {

/*        If key is present more than once,
        simply decrement count and return*/

        if (root.count > 1)
        {
            (root.count)--;
            return root;
        }

/*        ElSE, delete the node
        node with only one child or no child*/

        node temp = null;
        if (root.left == null)
        {
            temp = root.right;
            root = null;
            return temp;
        }
        else if (root.right == null)
        {
            temp = root.left;
            root = null;
            return temp;
        }

/*        node with two children: Get the inorder
        successor (smallest in the right subtree)*/

        temp = minValueNode(root.right);

/*        Copy the inorder successor's
        content to this node*/

        root.key = temp.key;

/*        Delete the inorder successor*/

        root.right = deleteNode(root.right,
                                temp.key);
    }
    return root;
}

/*Driver Code*/

public static void Main(String[] args)
{

/* Let us create following BST
            12(3)
        /     \
    10(2)     20(1)
    / \
    9(1) 11(1) */

    node root = null;
    root = insert(root, 12);
    root = insert(root, 10);
    root = insert(root, 20);
    root = insert(root, 9);
    root = insert(root, 11);
    root = insert(root, 10);
    root = insert(root, 12);
    root = insert(root, 12);
    Console.Write("Inorder traversal of " +
                  "the given tree " + "\n");
    inorder(root);
    Console.Write("\nDelete 20\n");
    root = deleteNode(root, 20);
    Console.Write("Inorder traversal of " +
                  "the modified tree \n");
    inorder(root);
    Console.Write("\nDelete 12\n");
    root = deleteNode(root, 12);
    Console.Write("Inorder traversal of " +
                  "the modified tree \n");
    inorder(root);
    Console.Write("\nDelete 9\n");
    root = deleteNode(root, 9);
    Console.Write("Inorder traversal of " +
                  "the modified tree \n");
    inorder(root);
}
}

/*C# program to demonstrate decrease
key operation on binary search tree*/

using System;
class GFG
{
public class node
{
    public int key;
    public node left, right;
}
static node root = null;

/*A utility function to
create a new BST node*/

static node newNode(int item)
{
    node temp = new node();
    temp.key = item;
    temp.left = null;
    temp.right = null;
    return temp;
}

/*A utility function to
do inorder traversal of BST*/

static void inorder(node root)
{
    if (root != null)
    {
        inorder(root.left);
        Console.Write(root.key + " ");
        inorder(root.right);
    }
}

/* A utility function to insert
a new node with given key in BST */

static node insert(node node, int key)
{

/* If the tree is empty, return a new node */

    if (node == null) return newNode(key);

/* Otherwise, recur down the tree */

    if (key < node.key)
        node.left = insert(node.left, key);
    else
        node.right = insert(node.right, key);

/* return the (unchanged) node pointer */

    return node;
}

/* Given a non-empty binary search tree,
return the node with minimum key value
found in that tree. Note that the entire
tree does not need to be searched. */

static node minValueNode(node Node)
{
    node current = Node;

/* loop down to find the leftmost leaf */

    while (current.left != null)
        current = current.left;
    return current;
}

/* Given a binary search tree and
a key, this function deletes the key
and returns the new root */

static node deleteNode(node root, int key)
{
    node temp = null;

/*    base case*/

    if (root == null) return root;

/*    If the key to be deleted is
    smaller than the root's key,
    then it lies in left subtree*/

    if (key < root.key)
        root.left = deleteNode(root.left, key);

/*    If the key to be deleted is
    greater than the root's key,
    then it lies in right subtree*/

    else if (key > root.key)
        root.right = deleteNode(root.right, key);

/*    if key is same as root's
    key, then This is the node
    to be deleted*/

    else
    {

/*        node with only one child or no child*/

        if (root.left == null)
        {
            temp = root.right;
            return temp;
        }
        else if (root.right == null)
        {
            temp = root.left;
            return temp;
        }

/*        node with two children: Get
        the inorder successor (smallest
        in the right subtree)*/

        temp = minValueNode(root.right);

/*        Copy the inorder successor's
        content to this node*/

        root.key = temp.key;

/*        Delete the inorder successor*/

        root.right = deleteNode(root.right,
                                 temp.key);
    }
    return root;
}

/*Function to decrease a key
value in Binary Search Tree*/

static node changeKey(node root, int oldVal,
                                 int newVal)
{

/*    First delete old key value*/

    root = deleteNode(root, oldVal);

/*    Then insert new key value*/

    root = insert(root, newVal);

/*    Return new root*/

    return root;
}

/*Driver code*/

public static void Main(String[] args)
{

/* Let us create following BST
            50
        / \
        30 70
        / \ / \
    20 40 60 80 */

    root = insert(root, 50);
    root = insert(root, 30);
    root = insert(root, 20);
    root = insert(root, 40);
    root = insert(root, 70);
    root = insert(root, 60);
    root = insert(root, 80);
    Console.WriteLine("Inorder traversal " +
                      "of the given tree ");
    inorder(root);
    root = changeKey(root, 40, 10);

/* BST is modified to
            50
        / \
        30 70
        / / \
    20 60 80
    /
    10 */

    Console.WriteLine("\nInorder traversal " +
                      "of the modified tree");
    inorder(root);
}
}

/*C# program of iterative traversal based method to 
find common elements in two BSTs. */
using System;
using System.Collections.Generic;
public class GfG
{

/*A BST node */

public class Node
{
    public int key;
    public Node left, right;
}

/*A utility function to create a new node */

public static Node newNode(int ele)
{
    Node temp = new Node();
    temp.key = ele;
    temp.left = null;
    temp.right = null;
    return temp;
}

/*Function two print common elements in given two trees */

public static void printCommon(Node root1, Node root2)
{

/*    Create two stacks for two inorder traversals*/

    Stack<Node> s1 = new Stack<Node> ();
    Stack<Node> s2 = new Stack<Node> ();
    while (true)
    {

/*        push the Nodes of first tree in stack s1 */

        if (root1 != null)
        {
            s1.Push(root1);
            root1 = root1.left;
        }

/*        push the Nodes of second tree in stack s2 */

        else if (root2 != null)
        {
            s2.Push(root2);
            root2 = root2.left;
        }

/*        Both root1 and root2 are NULL here */

        else if (s1.Count > 0 && s2.Count > 0)
        {
            root1 = s1.Peek();
            root2 = s2.Peek();

/*            If current keys in two trees are same */

            if (root1.key == root2.key)
            {
                Console.Write(root1.key + " ");
                s1.Pop();
                s2.Pop();

/*                move to the inorder successor */

                root1 = root1.right;
                root2 = root2.right;
            }
            else if (root1.key < root2.key)
            {

/*                If Node of first tree is smaller, than that of 
                second tree, then its obvious that the inorder 
                successors of current Node can have same value 
                as that of the second tree Node. Thus, we pop 
                from s2 */

                s1.Pop();
                root1 = root1.right;

/*                root2 is set to NULL, because we need 
                new Nodes of tree 1 */

                root2 = null;
            }
            else if (root1.key > root2.key)
            {
                s2.Pop();
                root2 = root2.right;
                root1 = null;
            }
        }

/*        Both roots and both stacks are empty */

        else
        {
            break;
        }
    }
}

/*A utility function to do inorder traversal */

public static void inorder(Node root)
{
    if (root != null)
    {
        inorder(root.left);
        Console.Write(root.key + " ");
        inorder(root.right);
    }
}

/* A utility function to insert a new Node with given key in BST */

public static Node insert(Node node, int key)
{

/* If the tree is empty, return a new Node */

    if (node == null)
    {
        return newNode(key);
    }

/* Otherwise, recur down the tree */

    if (key < node.key)
    {
        node.left = insert(node.left, key);
    }
    else if (key > node.key)
    {
        node.right = insert(node.right, key);
    }

/* return the (unchanged) Node pointer */

    return node;
}

/*Driver program */

public static void Main(string[] args)
{

/*    Create first tree as shown in example */

    Node root1 = null;
    root1 = insert(root1, 5);
    root1 = insert(root1, 1);
    root1 = insert(root1, 10);
    root1 = insert(root1, 0);
    root1 = insert(root1, 4);
    root1 = insert(root1, 7);
    root1 = insert(root1, 9);

/*    Create second tree as shown in example */

    Node root2 = null;
    root2 = insert(root2, 10);
    root2 = insert(root2, 7);
    root2 = insert(root2, 20);
    root2 = insert(root2, 4);
    root2 = insert(root2, 9);
    Console.Write("Tree 1 : " + "\n"); 
    inorder(root1); 
    Console.WriteLine(); 
    Console.Write("Tree 2 : " + "\n"); 
    inorder(root2); 
    Console.WriteLine(); 
    Console.Write("Common Nodes: " + "\n"); 
    printCommon(root1, root2);
}
}

/*C# program to print leaf node from
preorder of binary search tree.*/

using System;
class GFG
{

/*Binary Search*/

static int binarySearch(int []inorder, int l, 
                        int r, int d)
{
    int mid = (l + r) >> 1;
    if (inorder[mid] == d)
        return mid;
    else if (inorder[mid] > d)
        return binarySearch(inorder, l,
                            mid - 1, d);
    else
        return binarySearch(inorder, 
                            mid + 1, r, d);
}

/*Point to the index in preorder.*/

static int ind;

/*Function to print Leaf Nodes by 
doing preorder traversal of tree
using preorder and inorder arrays.*/

static void leafNodesRec(int []preorder, 
                        int []inorder,
                        int l, int r, int n)
{

/*    If l == r, therefore no right or left subtree.
    So, it must be leaf Node, print it.*/

    if(l == r)
    {
        Console.Write("{0} ", inorder[l]);
        ind = ind + 1;
        return;
    }

/*    If array is out of bound, return.*/

    if (l < 0 || l > r || r >= n)
        return;

/*    Finding the index of preorder element
    in inorder array using binary search.*/

    int loc = binarySearch(inorder, l, r, 
                        preorder[ind]);

/*    Incrementing the index.*/

    ind = ind + 1;

/*    Finding on the left subtree.*/

    leafNodesRec(preorder, inorder,
                    l, loc - 1, n);

/*    Finding on the right subtree.*/

    leafNodesRec(preorder, inorder, 
                    loc + 1, r, n);
}

/*Finds leaf nodes from given preorder traversal.*/

static void leafNodes(int []preorder, int n)
{

/*    To store inorder traversal*/

    int []inorder = new int[n];

/*    Copy the preorder into another array.*/

    for (int i = 0; i < n; i++)
        inorder[i] = preorder[i];

/*    Finding the inorder by sorting the array.*/

    Array.Sort(inorder);

/*    Print the Leaf Nodes.*/

    leafNodesRec(preorder, inorder, 0, n - 1, n);
}

/*Driver Code*/

public static void Main(String []args)
{
    int []preorder = { 890, 325, 290, 530, 965 };
    int n = preorder.Length;
    leafNodes(preorder, n);
}
}

/*Stack based C# program to print leaf nodes  
from preorder traversal. */

using System;
using System.Collections.Generic;
public class GfG
{

/*Print the leaf node from the given preorder of BST.  */

public static void leafNode(int[] preorder, int n)
{
    Stack<int> s = new Stack<int> ();
    for (int i = 0, j = 1; j < n; i++, j++)
    {
        bool found = false;
        if (preorder[i] > preorder[j])
        {
            s.Push(preorder[i]);
        }
        else
        {
            while (s.Count > 0)
            {
                if (preorder[j] > s.Peek())
                {
                    s.Pop();
                    found = true;
                }
                else
                {
                    break;
                }
            }
        }
        if (found)
        {
            Console.Write(preorder[i] + " ");
        }
    }

/*    Since rightmost element is always leaf node.  */

    Console.WriteLine(preorder[n - 1]);
}

/*Driver code  */

public static void Main(string[] args)
{
    int[] preorder = new int[] {890, 325, 290, 530, 965};
    int n = preorder.Length;
    leafNode(preorder, n);
}
}

/*Recursive C# program to find leaf
nodes from given preorder traversal*/

using System;
class GFG
{
    static int i = 0;

/*    Print the leaf node from
    the given preorder of BST.*/

    static bool isLeaf(int []pre, int n,
                        int min, int max)
    {
        if (i >= n)
        {
            return false;
        }
        if (pre[i] > min && pre[i] < max)
        {
            i++;
            bool left = isLeaf(pre, n, min, pre[i - 1]);
            bool right = isLeaf(pre, n, pre[i - 1], max);
            if (!left && !right)
            {
                Console.Write(pre[i - 1] + " ");
            }
            return true;
        }
        return false;
    }
    static void printLeaves(int []preorder, int n)
    {
        isLeaf(preorder, n, int.MinValue, int.MaxValue);
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []preorder = {890, 325, 290, 530, 965};
        int n = preorder.Length;
        printLeaves(preorder, n);
    }
}

/*C# program to demonstrate insert operation
in binary search tree with parent pointer*/

using System;
class GfG
{

/*Node structure*/

    class Node
    {
        public int key;
        public Node left, right, parent;
    }

/*    A utility function to create a new BST Node*/

    static Node newNode(int item)
    {
        Node temp = new Node();
        temp.key = item;
        temp.left = null;
        temp.right = null;
        temp.parent = null;
        return temp;
    }

/*    A utility function to do
    inorder traversal of BST*/

    static void inorder(Node root)
    {
        if (root != null)
        {
            inorder(root.left);
            Console.Write("Node : "+ root.key + " , ");
            if (root.parent == null)
            Console.WriteLine("Parent : NULL");
            else
            Console.WriteLine("Parent : " +
                                root.parent.key);
            inorder(root.right);
        }
    }

/* A utility function to insert a new Node with
    given key in BST */

    static Node insert(Node node, int key)
    {

/* If the tree is empty, return a new Node */

        if (node == null) return newNode(key);

/* Otherwise, recur down the tree */

        if (key < node.key)
        {
            Node lchild = insert(node.left, key);
            node.left = lchild;

/*            Set parent of root of left subtree*/

            lchild.parent = node;
        }
        else if (key > node.key)
        {
            Node rchild = insert(node.right, key);
            node.right = rchild;

/*            Set parent of root of right subtree*/

            rchild.parent = node;
        }

/* return the (unchanged) Node pointer */

        return node;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/* Let us create following BST
                50
            / \
            30 70
            / \ / \
        20 40 60 80 */

        Node root = null;
        root = insert(root, 50);
        insert(root, 30);
        insert(root, 20);
        insert(root, 40);
        insert(root, 70);
        insert(root, 60);
        insert(root, 80);

/*        print iNoder traversal of the BST*/

        inorder(root);
    }
}

/*C# program to find number
of pairs and minimal
possible value*/

using System;
class GFG
{

/*function for finding
pairs and min value*/

static void pairs(int []arr,
                  int n, int k)
{

/*    initialize
    smallest and count*/

    int smallest = 0;
    int count = 0;

/*    iterate over all pairs*/

    for (int i = 0; i < n; i++)
        for(int j = i + 1; j < n; j++)
        {

/*            is abs value is smaller
            than smallest update
            smallest and reset
            count to 1*/

            if (Math.Abs(arr[i] +
                arr[j] - k) < smallest )
            {
                smallest = Math.Abs(arr[i] +
                                    arr[j] - k);
                count = 1;
            }

/*            if abs value is equal
            to smallest increment
            count value*/

            else if (Math.Abs(arr[i] +
                              arr[j] - k) ==
                                smallest)
                count++;
        }

/*    print result*/

    Console.WriteLine("Minimal Value = " +
                                smallest);
    Console.WriteLine("Total Pairs = " +
                                 count);
}

/*Driver Code*/

public static void Main()
{
    int []arr = {3, 5, 7,
                 5, 1, 9, 9};
    int k = 12;
    int n = arr.Length;
    pairs(arr, n, k);
}
}

/*C# program to find rank of an
element in a stream.*/

using System;
class GFG
{
public class Node
{
    public int data;
    public Node left, right;
    public int leftSize;
}
static Node newNode(int data)
{
    Node temp = new Node();
    temp.data = data;
    temp.left = null;
    temp.right = null;
    temp.leftSize = 0;
    return temp;
}

/*Inserting a new Node.*/

static Node insert(Node root, int data)
{
    if (root == null)
        return newNode(data);

/*    Updating size of left subtree.*/

    if (data <= root.data)
    {
        root.left = insert(root.left, data);
        root.leftSize++;
    }
    else
        root.right = insert(root.right, data);
    return root;
}

/*Function to get Rank of a Node x.*/

static int getRank(Node root, int x)
{

/*    Step 1.*/

    if (root.data == x)
        return root.leftSize;

/*    Step 2.*/

    if (x < root.data)
    {
        if (root.left == null)
            return -1;
        else
            return getRank(root.left, x);
    }

/*    Step 3.*/

    else
    {
        if (root.right == null)
            return -1;
        else
        {
            int rightSize = getRank(root.right, x);
              if(rightSize == -1) return -1;
            return root.leftSize + 1 + rightSize;
        }
    }
}

/*Driver code*/

public static void Main(String[] args)
{
    int []arr = { 5, 1, 4, 4, 5, 9, 7, 13, 3 };
    int n = arr.Length;
    int x = 4;
    Node root = null;
    for (int i = 0; i < n; i++)
        root = insert(root, arr[i]);
    Console.WriteLine("Rank of " + x +
                      " in stream is : " +
                      getRank(root, x));
    x = 13;
    Console.WriteLine("Rank of " + x +
                      " in stream is : " +
                      getRank(root, x));
}
}

