/*Program to check matrix
is scalar matrix or not.*/

using System;
class GFG {
    static int N = 4;

/*    Function to check matrix
    is scalar matrix or not.*/

    static bool isScalarMatrix(int [,]mat)
    {

/*        Check all elements
        except main diagonal are
        zero or not.*/

        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if ((i != j) && (mat[i,j] != 0))
                    return false;

/*        Check all diagonal elements
        are same or not.*/

        for (int i = 0; i < N - 1; i++)
            if (mat[i, i] != mat[i + 1, i + 1])
                return false;
        return true;
    }

