        if (isScalarMatrix(mat))
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*C# implementation to sort the
matrix row-wise and column-wise*/

using System;
class GFG
{

/*    function to sort each
    row of the matrix*/

    static void sortByRow(int [,]mat,
                          int n)
    {

/*    sorting row number 'i'*/

    for (int i = 0; i < n ; i++)
        {
        for(int j = 0;
                j < n - 1; j++)
        {
            if(mat[i, j] > mat[i, j + 1])
            {
                var temp = mat[i, j];
                mat[i, j] = mat[i, j + 1];
                mat[i, j + 1] = temp;
            }
        }
        }
    }

/*    function to find transpose
    of the matrix*/

    static void transpose(int [,]mat,
                          int n)
    {
        for (int i = 0; i < n; i++)
            for (int j = i + 1;
                     j < n; j++)
                {

/*                    swapping element at
                    index (i, j) by
                    element at index (j, i)*/

                    var temp = mat[i, j];
                    mat[i, j] = mat[j, i];
                    mat[j, i] = temp;
                }
    }

/*    function to sort
    the matrix row-wise
    and column-wise*/

    static void sortMatRowAndColWise(int [,]mat,
                                     int n)
    {

/*        sort rows of mat[,]*/

        sortByRow(mat, n);

/*        get transpose of mat[,]*/

        transpose(mat, n);

/*        again sort rows of mat[,]*/

        sortByRow(mat, n);

/*        again get transpose of mat[,]*/

        transpose(mat, n);
    }

/*    function to print the matrix*/

    static void printMat(int [,]mat, int n)
    {
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
                Console.Write(mat[i, j] + " ");
            Console.Write("\n");
        }
    }

/*    Driver code*/

    public static void Main ()
    {
        int [,]mat = {{4, 1, 3},
                      {9, 6, 8},
                      {5, 2, 7}};
        int n = 3;
        Console.Write("Original Matrix:\n");
        printMat(mat, n);
        sortMatRowAndColWise(mat, n);
        Console.Write("\nMatrix After Sorting:\n");
        printMat(mat, n);
    }
}

/*C# program to print Magic square
of Doubly even order*/

using System;
class GFG
{

/*Function for calculating Magic square*/

public static void doublyEven(int n)
{
    int[,] arr = new int[n,n];
    int i, j;

/*    filling matrix with its count
    value starting from 1;*/

    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            arr[i, j] = (n * i) + j + 1;
        }
    }

/*    change value of Array elements
    at fix location as per rule
    (n*n+1)-arr[i][j]
    Top Left corner of Matrix
    (order (n/4)*(n/4))*/

    for (i = 0; i < n / 4; i++)
    {
        for (j = 0; j < n / 4; j++)
        {
            arr[i, j] = (n * n + 1) - arr[i, j];
        }
    }

/*    Top Right corner of Matrix
    (order (n/4)*(n/4))*/

    for (i = 0; i < n / 4; i++)
    {
        for (j = 3 * (n / 4); j < n; j++)
        {
            arr[i, j] = (n * n + 1) - arr[i, j];
        }
    }

/*    Bottom Left corner of Matrix
    (order (n/4)*(n/4))*/

    for (i = 3 * n / 4; i < n; i++)
    {
        for (j = 0; j < n / 4; j++)
        {
            arr[i, j] = (n * n + 1) - arr[i, j];
        }
    }

/*    Bottom Right corner of Matrix
    (order (n/4)*(n/4))*/

    for (i = 3 * n / 4; i < n; i++)
    {
        for (j = 3 * n / 4; j < n; j++)
        {
            arr[i, j] = (n * n + 1) - arr[i, j];
        }
    }

/*    Centre of Matrix (order (n/2)*(n/2))*/

    for (i = n / 4; i < 3 * n / 4; i++)
    {
        for (j = n / 4; j < 3 * n / 4; j++)
        {
            arr[i, j] = (n * n + 1) - arr[i, j];
        }
    }

/*    Printing the magic-square*/

    for (i = 0; i < n; i++)
    {
        for (j = 0; j < n; j++)
        {
            Console.Write(arr[i, j] + " " + " ");
        }
        Console.WriteLine();
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    int n = 8;

/*    Function call*/

    doublyEven(n);
}
}

/*C# program to check whether a given
matrix is magic matrix or not*/

using System;
class GFG
{
    static int N = 3;

/*    Returns true if mat[][] is magic
    square, else returns false.*/

    static bool isMagicSquare(int[,] mat)
    {

/*        calculate the sum of
        the prime diagonal*/

        int sum = 0, sum2 = 0;
        for (int i = 0; i < N; i++)
            sum = sum + mat[i, i];

/*        the secondary diagonal*/

        for (int i = 0; i < N; i++)
            sum2 = sum2 + mat[i, N-1-i];
        if(sum!=sum2)
            return false;

/*        For sums of Rows*/

        for (int i = 0; i < N; i++) {
            int rowSum = 0;
            for (int j = 0; j < N; j++)
                rowSum += mat[i, j];

/*            check if every row sum is
            equal to prime diagonal sum*/

            if (rowSum != sum)
                return false;
        }

/*        For sums of Columns*/

        for (int i = 0; i < N; i++)
        {
            int colSum = 0;
            for (int j = 0; j < N; j++)
                colSum += mat[j,i];

/*            check if every column sum is
            equal to prime diagonal sum*/

            if (sum != colSum)
                return false;
        }
        return true;
    }

/*    Driver Code*/

    public static void Main()
    {
        int[,] mat =new int [,] {{ 2, 7, 6 },
                                 { 9, 5, 1 },
                                 { 4, 3, 8 }};
        if (isMagicSquare(mat))
            Console.WriteLine("Magic Square");
        else
            Console.WriteLine("Not a magic" +
                              " Square");
    }
}

/*C# code to find the Kronecker Product of
two matrices and stores it as matrix C*/

using System;
class GFG {

/*    rowa and cola are no of rows
    and columns of matrix A
    rowb and colb are no of rows
      and columns of matrix B*/

    static int cola = 2, rowa = 3;
    static int colb = 3, rowb = 2;

/*    Function to computes the Kronecker
    Product of two matrices*/

    static void Kroneckerproduct(int [,]A, int [,]B)
    {
        int [,]C= new int[rowa * rowb,
                          cola * colb];

/*        i loops till rowa*/

        for (int i = 0; i < rowa; i++)
        {

/*            k loops till rowb*/

            for (int k = 0; k < rowb; k++)
            {

/*                j loops till cola*/

                for (int j = 0; j < cola; j++)
                {

/*                    l loops till colb*/

                    for (int l = 0; l < colb; l++)
                    {

/*                        Each element of matrix A is
                        multiplied by whole Matrix B
                        resp and stored as Matrix C*/

                        C[i + l + 1, j + k + 1] = A[i, j] *
                                                  B[k, l];
                        Console.Write( C[i + l + 1,
                                       j + k + 1] + " ");
                    }
                }
                Console.WriteLine();
            }
        }
    }

/*    Driver Code*/

    public static void Main ()
    {
        int [,]A = {{1, 2},
                   {3, 4},
                   {1, 0}};
        int [,]B = {{0, 5, 2},
                   {6, 7, 3}};
        Kroneckerproduct(A, B);
    }
}

/*C# implementation to count
sub-matrices having sum
divisible by the value 'k'*/

using System;
class GFG
{

/*    function to count all
    sub-arrays divisible by k*/

    static int subCount(int []arr,
                        int n, int k)
    {

/*        create auxiliary hash
        array to count frequency
        of remainders*/

        int []mod = new int[k];

/*        Traverse original array
        and compute cumulative
        sum take remainder of
        this current cumulative
        sum and increase count
        by 1 for this remainder
        in mod[] array*/

        int cumSum = 0;
        for (int i = 0; i < n; i++)
        {
            cumSum += arr[i];

/*            as the sum can be negative,
            taking modulo twice*/

            mod[((cumSum % k) + k) % k]++;
        }

/*        Initialize result*/

        int result = 0;

/*        Traverse mod[]*/

        for (int i = 0; i < k; i++)

/*            If there are more than
            one prefix subarrays
            with a particular mod value.*/

            if (mod[i] > 1)
                result += (mod[i] *
                          (mod[i] - 1)) / 2;

/*        add the subarrays starting
        from the arr[i] which are
        divisible by k itself*/

        result += mod[0];
        return result;
    }

/*    function to count all
    sub-matrices having sum
    divisible by the value 'k'*/

    static int countSubmatrix(int [,]mat,
                              int n, int k)
    {

/*        Variable to store
        the final output*/

        int tot_count = 0;
        int left, right, i;
        int []temp = new int[n];

/*        Set the left column*/

        for (left = 0; left < n; left++)
        {

/*            Set the right column
            for the left column
            set by outer loop*/

            for (right = left; right < n; right++)
            {

/*                Calculate sum between
                current left and right
                for every row 'i'*/

                for (i = 0; i < n; ++i)
                    temp[i] += mat[i, right];

/*                Count number of subarrays
                in temp[] having sum
                divisible by 'k' and then
                add it to 'tot_count'*/

                tot_count += subCount(temp, n, k);
            }
        }

/*        required count of
        sub-matrices having
        sum divisible by 'k'*/

        return tot_count - 3;
    }

/*    Driver code*/

    static void Main()
    {
        int [,]mat = new int[,]{{5, -1, 6},
                                {-2, 3, 8},
                                {7, 4, -9}};
        int n = 3, k = 4;
        Console.Write("\nCount = " +
        countSubmatrix(mat, n, k));
    }
}

/*C# Program to Find minimum
number of operation required
such that sum of elements on
each row and column becomes same*/

using System;
class GFG {

/*    Function to find minimum
    operation required
    to make sum of each row
    and column equals*/

    static int findMinOpeartion(int [,]matrix,
                                        int n)
    {

/*        Initialize the sumRow[]
        and sumCol[] array to 0*/

        int[] sumRow = new int[n];
        int[] sumCol = new int[n];

/*        Calculate sumRow[] and
        sumCol[] array*/

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
            {
                sumRow[i] += matrix[i,j];
                sumCol[j] += matrix[i,j];
            }

/*        Find maximum sum value
        in either row or in column*/

        int maxSum = 0;
        for (int i = 0; i < n; ++i)
        {
            maxSum = Math.Max(maxSum, sumRow[i]);
            maxSum = Math.Max(maxSum, sumCol[i]);
        }
        int count = 0;
        for (int i = 0, j = 0; i < n && j < n;)
        {

/*            Find minimum increment
            required in either row
            or column*/

            int diff = Math.Min(maxSum - sumRow[i],
                        maxSum - sumCol[j]);

/*            Add difference in
            corresponding cell,
            sumRow[] and sumCol[]
            array*/

            matrix[i,j] += diff;
            sumRow[i] += diff;
            sumCol[j] += diff;

/*            Update the count
            variable*/

            count += diff;

/*            If ith row satisfied,
            increment ith value
            for next iteration*/

            if (sumRow[i] == maxSum)
                ++i;

/*            If jth column satisfied,
            increment jth value for
            next iteration*/

            if (sumCol[j] == maxSum)
                ++j;
        }
        return count;
    }

/*    Utility function to
    print matrix*/

    static void printMatrix(int [,]matrix,
                                    int n)
    {
        for (int i = 0; i < n; ++i)
        {
            for (int j = 0; j < n; ++j)
                Console.Write(matrix[i,j] +
                                        " ");
            Console.WriteLine();
        }
    }

/* Driver program */

    public static void Main()
    {
        int [,]matrix = {{1, 2},
                        {3, 4}};
        Console.WriteLine(findMinOpeartion(matrix, 2));
        printMatrix(matrix, 2);
    }
}

/*C# program to find the
frequency of k in matrix
in matrix where m(i, j)=i+j*/

using System;
public class GfG{
    public static int find(int n, int k)
    {
        if (n + 1 >= k)
            return (k - 1);
        else
            return (2 * n + 1 - k);
    }

/*    Driver function*/

    public static void Main()
    {
        int n = 4, k = 7;
        int freq = find(n, k);
        if (freq < 0)
            Console.WriteLine(" element"
            + " not exist ");
        else
            Console.WriteLine(" Frequency"
            + " of " + k + " is " +
            freq );
    }
}

/*C# program to print given
number of 1's, 2's, 3's ....k's
in zig-zag way.*/

using System;
public class GfG{

/*    function that prints given number of 1's,
    2's, 3's ....k's in zig-zag way.*/

    public static void ZigZag(int rows,
                            int columns,
                            int []numbers)
    {
        int k = 0;

/*        two-dimensional array to store numbers.*/

        int[,] arr = new int[rows,columns];
        for (int i = 0; i < rows; i++)
        {

/*            for even row.*/

            if (i % 2 == 0)
            {

/*                for each column.*/

                for (int j = 0; j < columns &&
                        numbers[k] > 0; j++)
                {

/*                    storing element.*/

                    arr[i,j] = k + 1;

/*                    decrement element at
                kth index.*/

                    numbers[k]--;

/*                    if array contains zero
                    then increment index to
                    make this next index*/

                    if (numbers[k] == 0)
                        k++;
                }
            }

/*            for odd row.*/

            else
            {

/*                for each column.*/

                for (int j = columns - 1; j >= 0 &&
                    numbers[k] > 0; j--)
                {

/*                    storing element.*/

                    arr[i,j] = k + 1;

/*                    decrement element
                    at kth index.*/

                    numbers[k]--;

/*                    if array contains zero then
                    increment index to make this
                    next index.*/

                    if (numbers[k] == 0)
                        k++;
                }
            }
        }

/*        printing the stored elements.*/

        for (int i = 0;i < rows; i++)
        {
            for (int j = 0; j < columns; j++)
            Console.Write(arr[i, j] + " ");
            Console.WriteLine();
        }
    }

/*    Driver function*/

    public static void Main()
    {
        int rows = 4;
        int columns = 5;
        int []Numbers = new int[]{3, 4, 2,
                                2, 3, 1, 5};
        ZigZag(rows, columns, Numbers);
    }
}

/*C# program to find number of cells a
queen can move with obstacles on the
chessborad*/

using System;
class GFG {

/*    Return the number of position a Queen
    can move.*/

    static int numberofPosition(int n, int k, int x,
                int y, int []obstPosx, int []obstPosy)
    {

/*        d11, d12, d21, d22 are for diagnoal distances.
        r1, r2 are for vertical distance.
        c1, c2 are for horizontal distance.*/

        int d11, d12, d21, d22, r1, r2, c1, c2;

/*        Initialise the distance to end of the board.*/

        d11 = Math.Min( x-1, y-1 );
        d12 = Math.Min( n-x, n-y );
        d21 = Math.Min( n-x, y-1 );
        d22 = Math.Min( x-1, n-y );
        r1 = y-1;
        r2 = n-y;
        c1 = x-1;
        c2 = n-x;

/*        For each obstacle find the Minimum distance.
        If obstacle is present in any direction,
        distance will be updated.*/

        for (int i = 0; i < k; i++)
        {
            if ( x > obstPosx[i] && y > obstPosy[i] &&
                    x-obstPosx[i] == y-obstPosy[i] )
                d11 = Math.Min(d11, x-obstPosx[i]-1);
            if ( obstPosx[i] > x && obstPosy[i] > y &&
                    obstPosx[i]-x == obstPosy[i]-y )
                d12 = Math.Min( d12, obstPosx[i]-x-1);
            if ( obstPosx[i] > x && y > obstPosy[i] &&
                    obstPosx[i]-x == y-obstPosy[i] )
                d21 = Math.Min(d21, obstPosx[i]-x-1);
            if ( x > obstPosx[i] && obstPosy[i] > y &&
                        x-obstPosx[i] == obstPosy[i]-y)
                d22 = Math.Min(d22, x-obstPosx[i]-1);
            if ( x == obstPosx[i] && obstPosy[i] < y )
                r1 = Math.Min(r1, y-obstPosy[i]-1);
            if ( x == obstPosx[i] && obstPosy[i] > y )
                r2 = Math.Min(r2, obstPosy[i]-y-1);
            if ( y == obstPosy[i] && obstPosx[i] < x )
                c1 = Math.Min(c1, x-obstPosx[i]-1);
            if ( y == obstPosy[i] && obstPosx[i] > x )
                c2 = Math.Min(c2, obstPosx[i]-x-1);
        }
        return d11 + d12 + d21 + d22 + r1 + r2 + c1 + c2;
    }

/*    Driver code*/

    public static void Main ()
    {

/*Chessboard size*/

int n = 8;

/*number of obstacles*/

int k = 1;

/*Queen x position*/

int Qposx = 4;

/*Queen y position*/

int Qposy = 4;

/*x position of obstacles*/

int []obstPosx = { 3 };

/*y position of obstacles*/

int []obstPosy = { 5 }; 
        Console.WriteLine(numberofPosition(n, k, Qposx,
                            Qposy, obstPosx, obstPosy));
    }
}

/*C# program to find out the
maximum product in the matrix
which four elements are adjacent
to each other in one direction*/

using System;
public class GFG {
    static int n = 5;

/*    Function to find max product*/

    static int FindMaxProduct(int[, ] arr, int n)
    {
        int max = 0, result;

/*        iterate the rows*/

        for (int i = 0; i < n; i++) {

/*            iterate the columns*/

            for (int j = 0; j < n; j++) {

/*                check the maximum product
                in horizontal row.*/

                if ((j - 3) >= 0) {
                    result = arr[i, j] * arr[i, j - 1]
                             * arr[i, j - 2]
                             * arr[i, j - 3];
                    if (max < result)
                        max = result;
                }

/*                check the maximum product
                in vertical row.*/

                if ((i - 3) >= 0) {
                    result = arr[i, j] * arr[i - 1, j]
                             * arr[i - 2, j]
                             * arr[i - 3, j];
                    if (max < result)
                        max = result;
                }

/*                check the maximum product in
                diagonal going through down - right*/

                if ((i - 3) >= 0 && (j - 3) >= 0) {
                    result = arr[i, j] * arr[i - 1, j - 1]
                             * arr[i - 2, j - 2]
                             * arr[i - 3, j - 3];
                    if (max < result)
                        max = result;
                }

/*                check the maximum product in
                diagonal going through up - right*/

                if ((i - 3) >= 0 && (j - 1) <= 0) {
                    result = arr[i, j] * arr[i - 1, j + 1]
                             * arr[i - 2, j + 2]
                             * arr[i - 3, j + 3];
                    if (max < result)
                        max = result;
                }
            }
        }
        return max;
    }

/*    Driver Code*/

    static public void Main()
    {
        int[, ] arr = { { 1, 2, 3, 4, 5 },
                        { 6, 7, 8, 9, 1 },
                        { 2, 3, 4, 5, 6 },
                        { 7, 8, 9, 1, 0 },
                        { 9, 6, 4, 2, 3 } };
        Console.Write(FindMaxProduct(arr, n));
    }
}

/*C# implementation of the above approach*/

using System;
class GFG{
public static int maxPro(int[,] a, int n,
                         int m, int k)
{
    int maxi = 1, mp = 1;
    for(int i = 0; i < n; ++i)
    {

/*        Window Product for each row.*/

        int wp = 1;
        for(int l = 0; l < k; ++l)
        {
            wp *= a[i, l];
        }

/*        Maximum window product for each row*/

        mp = wp;
        for(int j = k; j < m; ++j)
        {
            wp = wp * a[i, j] / a[i, j - k];

/*            Global maximum
            window product*/

            maxi = Math.Max(maxi,
                   Math.Max(mp, wp));
        }
    }
    return maxi;
}

/*Driver Code*/

static public void Main()
{
    int n = 6, m = 5, k = 4;
    int[,] a = {{ 1, 2, 3, 4, 5 }, { 6, 7, 8, 9, 1 },
                { 2, 3, 4, 5, 6 }, { 7, 8, 9, 1, 0 },
                { 9, 6, 4, 2, 3 }, { 1, 1, 2, 1, 1 }};

/*    Function call*/

    int maxpro = maxPro(a, n, m, k);
    Console.WriteLine(maxpro);
}
}

/*C# Program to find minimum flip
required to make Binary Matrix
symmetric along main diagonal*/

using System;
class GFG {

/*    Return the minimum flip required
    to make Binary Matrix symmetric
    along main diagonal.*/

    static int minimumflip(int [,]mat, int n)
    {
        int [,]transpose = new int[n,n];

/*        finding the transpose of the matrix*/

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                transpose[i,j] = mat[j,i];

/*        Finding the number of position
        where element are not same.*/

        int flip = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (transpose[i,j] != mat[i,j])
                    flip++;
        return flip / 2;
    }

/* Driver program to test above function */

    public static void Main()
    {
        int n = 3;
        int [,]mat = {{ 0, 0, 1 },
                      { 1, 1, 1 },
                      { 1, 0, 0 }};
        Console.WriteLine(minimumflip(mat, n));
    }
}

/*C# Program to find minimum flip
required to make Binary Matrix
symmetric along main diagonal*/

using System;
class GFG {

/*    Return the minimum flip required
    to make Binary Matrix symmetric
    along main diagonal.*/

    static int minimumflip(int [,]mat, int n)
    {

/*        Comparing elements across diagonal*/

        int flip = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < i; j++)
                if (mat[i,j] != mat[j,i])
                    flip++;
        return flip;
    }

/* Driver program to test above function */

    public static void Main()
    {
        int n = 3;
        int [,]mat = {{ 0, 0, 1 },
                      { 1, 1, 1 },
                      { 1, 0, 0 }};
    Console.WriteLine(minimumflip(mat, n));
    }
}

