/*C# program for subtraction of matrices*/

using System;
class GFG
{
static int N = 4;

/*This function subtracts B[][]
from A[][], and stores
the result in C[][]*/

public static void subtract(int[][] A,
                            int[][] B,
                            int[, ] C)
{
    int i, j;
    for (i = 0; i < N; i++)
    {
        for (j = 0; j < N; j++)
        {
            C[i, j] = A[i][j] - B[i][j];
        }
    }
}

/*Driver code*/

public static void Main(string[] args)
{
    int[][] A = new int[][]
    {
        new int[] {1, 1, 1, 1},
        new int[] {2, 2, 2, 2},
        new int[] {3, 3, 3, 3},
        new int[] {4, 4, 4, 4}
    };
    int[][] B = new int[][]
    {
        new int[] {1, 1, 1, 1},
        new int[] {2, 2, 2, 2},
        new int[] {3, 3, 3, 3},
        new int[] {4, 4, 4, 4}
    };
    int[, ] C = new int[N, N];
    int i, j;
    subtract(A, B, C);
    Console.Write("Result matrix is \n");
    for (i = 0; i < N; i++)
    {
        for (j = 0; j < N; j++)
        {
            Console.Write(C[i, j] + " ");
        }
        Console.Write("\n");
    }
}
}

/*A Memoization based program to find maximum collection
using two traversals of a grid*/

using System;
class GFG
{
static readonly int R = 5;
static readonly int C = 4;

/*checks whether a given input is valid or not*/

static bool isValid(int x, int y1, int y2)
{
    return (x >= 0 && x < R && y1 >=0 &&
            y1 < C && y2 >=0 && y2 < C);
}

/*Driver function to collect Math.max value*/

static int getMaxUtil(int [,]arr, int [,,]mem,
                        int x, int y1, int y2)
{

/*---------- BASE CASES -----------*/

/*    if P1 or P2 is at an invalid cell*/

    if (!isValid(x, y1, y2)) return int.MinValue;

/*    if both traversals reach their destinations*/

    if (x == R-1 && y1 == 0 && y2 == C-1)
    return (y1 == y2)? arr[x, y1]: arr[x, y1] + arr[x, y2];

/*    If both traversals are at last
    row but not at their destination*/

    if (x == R-1) return int.MinValue;

/*    If subproblem is already solved*/

    if (mem[x, y1, y2] != -1) return mem[x, y1, y2];

/*    Initialize answer for this subproblem*/

    int ans = int.MinValue;

/*    this variable is used to store
    gain of current cell(s)*/

    int temp = (y1 == y2)? arr[x, y1]:
                arr[x, y1] + arr[x, y2];

/* Recur for all possible cases, then store
    and return the one with max value */

    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1, y2-1));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1, y2+1));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1, y2));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1-1, y2));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1-1, y2-1));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1-1, y2+1));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1+1, y2));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1+1, y2-1));
    ans = Math.Max(ans, temp +
            getMaxUtil(arr, mem, x+1, y1+1, y2+1));
    return (mem[x, y1, y2] = ans);
}

/*This is mainly a wrapper over recursive
function getMaxUtil(). This function
creates a table for memoization and
calls getMaxUtil()*/

static int geMaxCollection(int [,]arr)
{

/*    Create a memoization table and
    initialize all entries as -1*/

    int [,,]mem = new int[R, C, C];
    for(int i = 0; i < R; i++)
    {
        for(int j = 0; j < C; j++)
        {
            for(int l = 0; l < C; l++)
            mem[i, j, l]=-1;
        }
    }

/*    Calculation maximum value using memoization
    based function getMaxUtil()*/

    return getMaxUtil(arr, mem, 0, 0, C-1);
}

/*Driver code*/

public static void Main(String[] args)
{
    int [,]arr = {{3, 6, 8, 2},
                    {5, 2, 4, 3},
                    {1, 1, 20, 10},
                    {1, 1, 20, 10},
                    {1, 1, 20, 10},
                    };
    Console.Write("Maximum collection is " +
                            geMaxCollection(arr));
    }
}

/*A Naive Recursive c# program to
count paths with exactly 'k' coins*/

using System;
public class GFG
{
    public const int R = 3;
    public const int C = 3;

/*Recursive function to count paths with sum k from
(0, 0) to (m, n)*/

    public static int pathCountRec(int[][] mat, int m, int n, int k)
    {

/*        Base cases*/

        if (m < 0 || n < 0)
        {
            return 0;
        }
        if (m == 0 && n == 0 && (k == mat[m][n]))
        {
            return 1;
        }

/*        (m, n) can be reached either through (m-1, n) or
        through (m, n-1)*/

        return pathCountRec(mat, m - 1, n, k - mat[m][n])
                + pathCountRec(mat, m, n - 1, k - mat[m][n]);
    }

/*A wrapper over pathCountRec()*/

    public static int pathCount(int[][] mat, int k)
    {
        return pathCountRec(mat, R - 1, C - 1, k);
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        int k = 12;
        int[][] mat = new int[][]
        {
            new int[] {1, 2, 3},
            new int[] {4, 6, 5},
            new int[] {3, 2, 1}
        };
        Console.WriteLine(pathCount(mat, k));
    }
}

/*A Dynamic Programming based C# program
to count paths with exactly 'k' coins*/

using System;
class GFG
{
    static readonly int R = 3;
    static readonly int C = 3;
    static readonly int MAX_K = 100;
    static int [,,]dp = new int[R, C, MAX_K];
    static int pathCountDPRecDP(int [,]mat, int m,
                                int n, int k)
    {

/*        Base cases*/

        if (m < 0 || n < 0) return 0;
        if (m == 0 && n == 0)
            return (k == mat[m, n] ? 1 : 0);

/*        If this subproblem is already solved*/

        if (dp[m, n, k] != -1) return dp[m, n, k];

/*        (m, n) can be reached either through (m-1, n) or
        through (m, n-1)*/

        dp[m, n, k] = pathCountDPRecDP(mat, m - 1, n, k - mat[m, n]) +
                      pathCountDPRecDP(mat, m, n - 1, k - mat[m, n]);
        return dp[m, n, k];
    }

/*    This function mainly initializes [,]dp[] and
    calls pathCountDPRecDP()*/

    static int pathCountDP(int [,]mat, int k)
    {
        for(int i = 0; i < R; i++)
            for(int j = 0; j < C; j++)
                for(int l = 0; l < MAX_K; l++)
                dp[i, j, l] = -1;
        return pathCountDPRecDP(mat, R - 1, C - 1, k);
    }

/*    Driver Code*/

    public static void Main(String []args)
    {
        int k = 12;
        int[,] mat = { {1, 2, 3},
                       {4, 6, 5},
                       {3, 2, 1}};
        Console.WriteLine(pathCountDP(mat, k));
    }
}

/*C# program to find the longest consecutive path*/

using System;
class GFG {

/*    tool matrices to recur for adjacent cells.*/

    static int []x = {0, 1, 1, -1, 1, 0, -1, -1};
    static int []y = {1, 0, 1, 1, -1, -1, 0, -1};
    static int R = 3;
    static int C = 3;

/*    dp[i][j] Stores length of longest
    consecutive path starting at arr[i][j].*/

    static int [,]dp = new int[R,C];

/*    check whether mat[i][j] is a valid
    cell or not.*/

    static bool isvalid(int i, int j)
    {
        if (i < 0 || j < 0 || i >= R || j >= C)
            return false;
        return true;
    }

/*    Check whether current character is
    adjacent to previous character
    (character processed in parent call)
    or not.*/

    static bool isadjacent(char prev, char curr)
    {
        return ((curr - prev) == 1);
    }

/*    i, j are the indices of the current
    cell and prev is the character processed
    in the parent call.. also mat[i][j]
    is our current character.*/

    static int getLenUtil(char [,]mat, int i,
                                int j, char prev)
    {

/*        If this cell is not valid or current
        character is not adjacent to previous
        one (e.g. d is not adjacent to b )
        or if this cell is already included
        in the path than return 0.*/

        if (!isvalid(i, j) || !isadjacent(prev,
                                       mat[i,j]))
            return 0;

/*        If this subproblem is already solved,
        return the answer*/

        if (dp[i,j] != -1)
            return dp[i,j];

/*Initialize answer*/

int ans = 0;

/*        recur for paths with different adjacent
        cells and store the length of
        longest path.*/

        for (int k = 0; k < 8; k++)
        ans = Math.Max(ans, 1 + getLenUtil(mat,
                   i + x[k], j + y[k], mat[i,j]));

/*        save the answer and return*/

        return dp[i,j] = ans;
    }

/*    Returns length of the longest path
    with all characters consecutive to
    each other. This function first
    initializes dp array that is used
    to store results of subproblems,
    then it calls recursive DFS based
    function getLenUtil() to find max
    length path*/

    static int getLen(char [,]mat, char s)
    {
        for(int i = 0; i < R; ++i)
            for(int j = 0; j < C; ++j)
                dp[i,j] = -1;
        int ans = 0;
        for (int i=0; i<R; i++)
        {
            for (int j=0; j<C; j++)
            {

/*                check for each possible
                starting point*/

                if (mat[i,j] == s) {

/*                    recur for all eight
                    adjacent cells*/

                    for (int k = 0; k < 8; k++)
                        ans = Math.Max(ans, 1 +
                             getLenUtil(mat, i +
                             x[k], j + y[k], s));
                }
            }
        }
        return ans;
    }

/*    Driver code`*/

    public static void Main()
    {
        char [,]mat = { {'a','c','d'},
                        { 'h','b','a'},
                        { 'i','g','f'}};
        Console.WriteLine(getLen(mat, 'a') );
        Console.WriteLine(getLen(mat, 'e') );
        Console.WriteLine(getLen(mat, 'b') );
        Console.WriteLine(getLen(mat, 'f') );
    }
}

/*C# program to find the longest path
in a matrix with given constraints*/

using System;
class GFG {
    public static int n = 3;

/*    Function that returns length of
    the longest path beginning with mat[i][j]
    This function mainly uses lookup
    table dp[n][n]*/

    public static int findLongestFromACell(int i, int j,
                                           int[][] mat,
                                           int[][] dp)
    {

/*        Base case*/

        if (i < 0 || i >= n || j < 0 || j >= n) {
            return 0;
        }

/*        If this subproblem is
        already solved*/

        if (dp[i][j] != -1) {
            return dp[i][j];
        }

/*        To store the path lengths in all the four directions*/

        int x = int.MinValue, y = int.MinValue, z = int.MinValue, w = int.MinValue;

/*        Since all numbers are unique and
        in range from 1 to n*n, there is
        atmost one possible direction
        from any cell*/

        if (j < n - 1 && ((mat[i][j] + 1) == mat[i][j + 1])) {
            x = dp[i][j] = 1 + findLongestFromACell(i, j + 1, mat, dp);
        }
        if (j > 0 && (mat[i][j] + 1 == mat[i][j - 1])) {
            y = dp[i][j] = 1 + findLongestFromACell(i, j - 1, mat, dp);
        }
        if (i > 0 && (mat[i][j] + 1 == mat[i - 1][j])) {
            z = dp[i][j] = 1 + findLongestFromACell(i - 1, j, mat, dp);
        }
        if (i < n - 1 && (mat[i][j] + 1 == mat[i + 1][j])) {
            w = dp[i][j] = 1 + findLongestFromACell(i + 1, j, mat, dp);
        }

/*        If none of the adjacent fours is one greater we will take 1
        otherwise we will pick maximum from all the four directions*/

        dp[i][j] = Math.Max(x, Math.Max(y, Math.Max(z, Math.Max(w, 1))));
        return dp[i][j];
    }

/*    Function that returns length of the
    longest path beginning with any cell*/

    public static int finLongestOverAll(int[][] mat)
    {

/*        Initialize result*/

        int result = 1;

/*        Create a lookup table and fill
        all entries in it as -1*/

        int[][] dp = RectangularArrays.ReturnRectangularIntArray(n, n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[i][j] = -1;
            }
        }

/*        Compute longest path beginning
        from all cells*/

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (dp[i][j] == -1) {
                    findLongestFromACell(i, j, mat, dp);
                }

/*                Update result if needed*/

                result = Math.Max(result, dp[i][j]);
            }
        }
        return result;
    }

public static class RectangularArrays {
        public static int[][] ReturnRectangularIntArray(int size1,
                                                        int size2)
        {
            int[][] newArray = new int[size1][];
            for (int array1 = 0;
                 array1 < size1; array1++) {
                newArray[array1] = new int[size2];
            }
            return newArray;
        }
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        int[][] mat = new int[][] {
            new int[] { 1, 2, 9 },
            new int[] { 5, 3, 8 },
            new int[] { 4, 6, 7 }
        };
        Console.WriteLine("Length of the longest path is " + finLongestOverAll(mat));
    }
}

/*C# program Minimum Initial Points
to Reach Destination*/

using System;
class GFG {
    static int minInitialPoints(int [,]points, 
                                 int R, int C)
    {

/*        dp[i][j] represents the 
        minimum initial points 
        player should have so 
        that when starts with 
        cell(i, j) successfully
        reaches the destination
        cell(m-1, n-1)*/

        int [,]dp = new int[R,C];
        int m = R, n = C;

/*        Base case*/

        dp[m - 1,n - 1] = points[m - 1, n - 1] > 0 ? 1:
                     Math.Abs(points[m - 1,n - 1]) + 1;

/*        Fill last row and last 
        column as base to fill
        entire table*/

        for (int i = m-2; i >= 0; i--)
            dp[i, n - 1] = Math.Max(dp[i + 1, n - 1] - 
                                points[i, n - 1], 1);
        for (int j = n - 2; j >= 0; j--)
            dp[m - 1, j] = Math.Max(dp[m - 1, j + 1] - 
                                points[m - 1, j], 1);

/*        fill the table in 
        bottom-up fashion*/

        for(int i = m - 2; i >= 0; i--)
        {
            for (int j = n - 2; j >= 0; j--)
            {
                int min_points_on_exit = Math.Min(dp[i + 1, j], 
                                                  dp[i, j + 1]);
                dp[i, j] = Math.Max(min_points_on_exit - 
                                      points[i, j], 1);
            }
        }
        return dp[0, 0];
    }

/*    Driver Code*/

    public static void Main ()
    {
        int [,]points = {{-2,-3,3},
                         {-5,-10,1},
                           {10,30,-5}};
        int R = 3,C = 3;
        Console.Write("Minimum Initial Points Required: "+
                           minInitialPoints(points, R, C));
    }
}

/*C# program to implement Queue using 
two stacks with costly enQueue()*/

using System;
using System.Collections;
class GFG 
{ 
public class Queue 
{ 
    public Stack s1 = new Stack(); 
    public Stack s2 = new Stack(); 
    public void enQueue(int x) 
    {

/*        Move all elements from s1 to s2 */

        while (s1.Count > 0) 
        { 
            s2.Push(s1.Pop()); 
            s1.Pop(); 
         }

/*        Push item into s1 */

        s1.Push(x);

/*        Push everything back to s1 */

        while (s2.Count > 0) 
        { 
            s1.Push(s2.Pop()); 
            s2.Pop();

        } 
    }

/*    Dequeue an item from the queue */

    public int deQueue() 
    {

/*        if first stack is empty */

        if (s1.Count == 0) 
        { 
            Console.WriteLine("Q is Empty"); 
        }

/*        Return top of s1 */

        int x = (int)s1.Peek(); 
        s1.Pop(); 
        return x; 
    } 
};

/*Driver code */

public static void Main() 
{ 
    Queue q = new Queue(); 
    q.enQueue(1); 
    q.enQueue(2); 
    q.enQueue(3); 
    Console.Write(q.deQueue()+" "); 
    Console.Write(q.deQueue()+" "); 
    Console.Write(q.deQueue()); 
} 
}

/*C# program to find infix for
a given postfix.*/

using System;
using System.Collections;
class GFG
{
static Boolean isOperand(char x)
{
    return (x >= 'a' && x <= 'z') ||
            (x >= 'A' && x <= 'Z');
}

/*Get Infix for a given postfix
expression*/

static String getInfix(String exp)
{
    Stack s = new Stack();
    for (int i = 0; i < exp.Length; i++)
    {

/*        Push operands*/

        if (isOperand(exp[i]))
        {
            s.Push(exp[i] + "");
        }

/*        We assume that input is
        a valid postfix and expect
        an operator.*/

        else
        {
            String op1 = (String) s.Peek();
            s.Pop();
            String op2 = (String) s.Peek();
            s.Pop();
            s.Push("(" + op2 + exp[i] +
                    op1 + ")");
        }
    }

/*    There must be a single element
    in stack now which is the required
    infix.*/

    return (String)s.Peek();
}

/*Driver code*/

public static void Main(String []args)
{
    String exp = "ab*c+";
    Console.WriteLine( getInfix(exp));
}
}

/*C# implementation for brute force method
to calculate stock span values*/

using System;
class GFG {

/*    method to calculate stock span values*/

    static void calculateSpan(int[] price,
                              int n, int[] S)
    {

/*        Span value of first day is always 1*/

        S[0] = 1;

/*        Calculate span value of remaining
        days by linearly checking previous
        days*/

        for (int i = 1; i < n; i++) {

/*Initialize span value*/

S[i] = 1;

/*            Traverse left while the next
            element on left is smaller
            than price[i]*/

            for (int j = i - 1; (j >= 0) && (price[i] >= price[j]); j--)
                S[i]++;
        }
    }

/*    A utility function to print elements
    of array*/

    static void printArray(int[] arr)
    {
        string result = string.Join(" ", arr);
        Console.WriteLine(result);
    }

/*    Driver function*/

    public static void Main()
    {
        int[] price = { 10, 4, 5, 90, 120, 80 };
        int n = price.Length;
        int[] S = new int[n];

/*        Fill the span values in array S[]*/

        calculateSpan(price, n, S);

/*        print the calculated span values*/

        printArray(S);
    }
}

/*C# linear time solution for
stock span problem*/

using System;
using System.Collections;
class GFG {

/*    a linear time solution for
    stock span problem A stack
    based efficient method to calculate
    stock span values*/

    static void calculateSpan(int[] price, int n, int[] S)
    {

/*        Create a stack and Push
        index of first element to it*/

        Stack st = new Stack();
        st.Push(0);

/*        Span value of first
        element is always 1*/

        S[0] = 1;

/*        Calculate span values
        for rest of the elements*/

        for (int i = 1; i < n; i++) {

/*            Pop elements from stack
            while stack is not empty
            and top of stack is smaller
            than price[i]*/

            while (st.Count > 0 && price[(int)st.Peek()] <= price[i])
                st.Pop();

/*            If stack becomes empty, then price[i] is
            greater than all elements on left of it, i.e.,
            price[0], price[1], ..price[i-1]. Else price[i]
            is greater than elements after top of stack*/

            S[i] = (st.Count == 0) ? (i + 1) : (i - (int)st.Peek());

/*            Push this element to stack*/

            st.Push(i);
        }
    }

/*    A utility function to print elements of array*/

    static void printArray(int[] arr)
    {
        for (int i = 0; i < arr.Length; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver method*/

    public static void Main(String[] args)
    {
        int[] price = { 10, 4, 5, 90, 120, 80 };
        int n = price.Length;
        int[] S = new int[n];

/*        Fill the span values in array S[]*/

        calculateSpan(price, n, S);

/*        print the calculated span values*/

        printArray(S);
    }
}

/*C# program for a linear time
solution for stock span problem
without using stack*/

using System;
public class GFG {

/*    An efficient method to calculate
    stock span values implementing the
    same idea without using stack*/

    static void calculateSpan(int[] A,
                              int n, int[] ans)
    {

/*        Span value of first element is always 1*/

        ans[0] = 1;

/*        Calculate span values for rest of the elements*/

        for (int i = 1; i < n; i++) {
            int counter = 1;
            while ((i - counter) >= 0 && A[i] >= A[i - counter]) {
                counter += ans[i - counter];
            }
            ans[i] = counter;
        }
    }

/*    A utility function to print elements of array*/

    static void printArray(int[] arr, int n)
    {
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int[] price = { 10, 4, 5, 90, 120, 80 };
        int n = price.Length;
        int[] S = new int[n];

/*        Fill the span values in array S[]*/

        calculateSpan(price, n, S);

/*        print the calculated span values*/

        printArray(S, n);
    }
}

/*Simple C# program to print next
greater elements in a given array*/

using System;
class GFG
{

/* prints element and NGE pair for
    all elements of arr[] of size n */

    static void printNGE(int []arr, int n)
    {
        int next, i, j;
        for (i = 0; i < n; i++)
        {
            next = -1;
            for (j = i + 1; j < n; j++)
            {
                if (arr[i] < arr[j])
                {
                    next = arr[j];
                    break;
                }
            }
            Console.WriteLine(arr[i] + " -- " + next);
        }
    }

