towerOfHanoi(n, 'A', 'C', 'B');  
    }
}

/*C# program using Naive approach to find
maximum of minimum of all windows of
different sizes*/

using System;
class GFG{
    static int []arr = {10, 20, 30, 50, 10, 70, 30};
    static void printMaxOfMin(int n)
    {

/*        Consider all windows of different
        sizes starting from size 1*/

        for (int k = 1; k <= n; k++)
        {

/*            Initialize max of min for
            current window size k*/

            int maxOfMin = int.MinValue;

/*            Traverse through all windows
            of current size k*/

            for (int i = 0; i <= n - k; i++)
            {

/*                Find minimum of current window*/

                int min = arr[i];
                for (int j = 1; j < k; j++)
                {
                    if (arr[i + j] < min)
                        min = arr[i + j];
                }

/*                Update maxOfMin if required*/

                if (min > maxOfMin)
                    maxOfMin = min;
            }

/*            Print max of min for current window size*/

            Console.Write(maxOfMin + " ");
        }
    }

/*    Driver Code*/

    public static void Main()
    {
        printMaxOfMin(arr.Length);
    }
}

/*An efficient C# program to find maximum
of all minimums of windows of different size*/

using System;
using System.Collections.Generic;
class GFG
{
public static int[] arr = new int[] {10, 20, 30, 50,
                                     10, 70, 30};
public static void printMaxOfMin(int n)
{

/*    Used to find previous and next smaller*/

    Stack<int> s = new Stack<int>();

/*    Arrays to store previous
    and next smaller*/

    int[] left = new int[n + 1];
    int[] right = new int[n + 1];

/*    Initialize elements of left[]
    and right[]*/

    for (int i = 0; i < n; i++)
    {
        left[i] = -1;
        right[i] = n;
    }

/*    Fill elements of left[] using logic discussed on
www.geeksforgeeks.org/next-greater-element/
https:*/

    for (int i = 0; i < n; i++)
    {
        while (s.Count > 0 &&
               arr[s.Peek()] >= arr[i])
        {
            s.Pop();
        }
        if (s.Count > 0)
        {
            left[i] = s.Peek();
        }
        s.Push(i);
    }

/*    Empty the stack as stack is going
    to be used for right[]*/

    while (s.Count > 0)
    {
        s.Pop();
    }

/*    Fill elements of right[] using
    same logic*/

    for (int i = n - 1 ; i >= 0 ; i--)
    {
        while (s.Count > 0 &&
               arr[s.Peek()] >= arr[i])
        {
            s.Pop();
        }
        if (s.Count > 0)
        {
            right[i] = s.Peek();
        }
        s.Push(i);
    }

/*    Create and initialize answer array*/

    int[] ans = new int[n + 1];
    for (int i = 0; i <= n; i++)
    {
        ans[i] = 0;
    }

/*    Fill answer array by comparing
    minimums of all lengths computed
    using left[] and right[]*/

    for (int i = 0; i < n; i++)
    {

/*        length of the interval*/

        int len = right[i] - left[i] - 1;

/*        arr[i] is a possible answer for
        this length 'len' interval, check x
        if arr[i] is more than max for 'len'*/

        ans[len] = Math.Max(ans[len], arr[i]);
    }

/*    Some entries in ans[] may not be
    filled yet. Fill them by taking
    values from right side of ans[]*/

    for (int i = n - 1; i >= 1; i--)
    {
        ans[i] = Math.Max(ans[i], ans[i + 1]);
    }

/*    Print the result*/

    for (int i = 1; i <= n; i++)
    {
        Console.Write(ans[i] + " ");
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    printMaxOfMin(arr.Length);
}
}

/*C# program to find length of
the longest valid substring*/

using System;
using System.Collections.Generic;
class GFG {

/*    method to get length of
    the longest valid*/

    public static int findMaxLen(string str)
    {
        int n = str.Length;

/*        Create a stack and push -1 as
        initial index to it.*/

        Stack<int> stk = new Stack<int>();
        stk.Push(-1);

/*        Initialize result*/

        int result = 0;

/*        Traverse all characters of
        given string*/

        for (int i = 0; i < n; i++)
        {

/*            If opening bracket, push
            index of it*/

            if (str[i] == '(') {
                stk.Push(i);
            }

/*If closing bracket,i.e.,str[i] = ')'*/

else 
            {

/*                Pop the previous opening
                bracket's index*/

                if (stk.Count > 0)
                    stk.Pop();

/*                Check if this length formed
                with base of current valid
                substring is more than max
                so far*/

                if (stk.Count > 0)
                {
                    result
                        = Math.Max(result,
                                   i - stk.Peek());
                }

/*                If stack is empty. push current
                index as base for next valid
                substring (if any)*/

                else {
                    stk.Push(i);
                }
            }
        }
        return result;
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        string str = "((()()";

/*        Function call*/

        Console.WriteLine(findMaxLen(str));
        str = "()(()))))";

/*        Function call*/

        Console.WriteLine(findMaxLen(str));
    }
}

/*C# program to find length of the longest valid
subString*/

using System;
public class GFG {
    static int findMaxLen(String s) {
        if (s.Length <= 1)
            return 0;

/*        Initialize curMax to zero*/

        int curMax = 0;
        int[] longest = new int[s.Length];

/*        Iterate over the String starting from second index*/

        for (int i = 1; i < s.Length; i++) {
            if (s[i] == ')' && i - longest[i - 1] - 1 >= 0 && s[i - longest[i - 1] - 1] == '(') {
                longest[i] = longest[i - 1] + 2 + ((i - longest[i - 1] - 2 >= 0) ? longest[i - longest[i - 1] - 2] : 0);
                curMax = Math.Max(longest[i], curMax);
            }
        }
        return curMax;
    }

/*    Driver code*/

    public static void Main(String[] args) {
        String str = "((()()";

/*        Function call*/

        Console.Write(findMaxLen(str) + "\n");
        str = "()(()))))";

/*        Function call*/

        Console.Write(findMaxLen(str) + "\n");
    }
}

/*C# program to implement the above approach*/

using System;
public class GFG {

/*  Function to return the length
  of the longest valid substring*/

  public static int solve(String s, int n)
  {

/*    Variables for left and right
    counter maxlength to store
    the maximum length found so far*/

    int left = 0, right = 0;
    int maxlength = 0;

/*    Iterating the string from left to right*/

    for (int i = 0; i < n; i++) {

/*      If "(" is encountered, then
      left counter is incremented
      else right counter is incremented*/

      if (s[i] == '(')
        left++;
      else
        right++;

/*      Whenever left is equal to right,
      it signifies that the subsequence
      is valid and*/

      if (left == right)
        maxlength = Math.Max(maxlength,
                             2 * right);

/*      Reseting the counters when the
      subsequence becomes invalid*/

      else if (right > left)
        left = right = 0;
    }
    left = right = 0;

/*    Iterating the string from right to left*/

    for (int i = n - 1; i >= 0; i--) {

/*      If "(" is encountered, then
      left counter is incremented
      else right counter is incremented*/

      if (s[i] == '(')
        left++;
      else
        right++;

/*      Whenever left is equal to right,
      it signifies that the subsequence
      is valid and*/

      if (left == right)
        maxlength = Math.Max(maxlength,
                             2 * left);

/*      Reseting the counters when the
      subsequence becomes invalid*/

      else if (left > right)
        left = right = 0;
    }
    return maxlength;
  }

/*  Driver code*/

  public static void Main(String []args)
  {

/*    Function call*/

    Console.Write(solve("((()()()()(((())", 16));
  }
}

/* C# Program to check whether valid
expression is redundant or not*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Function to check redundant brackets in a
    balanced expression*/

    static bool checkRedundancy(String s)
    {

/*        create a stack of characters*/

        Stack<char> st = new Stack<char>();
        char[] str = s.ToCharArray();

/*        Iterate through the given expression*/

        foreach (char ch in str)
        {

/*            if current character is close parenthesis ')'*/

            if (ch == ')')
            {
                char top = st.Peek();
                st.Pop();

/*                If immediate pop have open parenthesis '('
                duplicate brackets found*/

                bool flag = true;
                while (top != '(')
                {

/*                    Check for operators in expression*/

                    if (top == '+' || top == '-'
                            || top == '*' || top == '/')
                    {
                        flag = false;
                    }

/*                    Fetch top element of stack*/

                    top = st.Peek();
                    st.Pop();
                }

/*                If operators not found*/

                if (flag == true)
                {
                    return true;
                }
            }
            else
            {

/*push open parenthesis '(',*/

st.Push(ch);

/*operators and operands to stack*/

}         
        }
        return false;
    }

/*    Function to check redundant brackets*/

    static void findRedundant(String str)
    {
        bool ans = checkRedundancy(str);
        if (ans == true)
        {
            Console.WriteLine("Yes");
        }
        else
        {
            Console.WriteLine("No");
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        String str = "((a+b))";
        findRedundant(str);
        str = "(a+(b)/c)";
        findRedundant(str);
        str = "(a+b*(c-d))";
        findRedundant(str);
    }
}

/*C# program to check if two expressions
evaluate to same.*/

using System;
using System.Collections.Generic;
public class GFG
{
  static readonly int MAX_CHAR = 26;

/*  Return local sign of the operand. For example,
  in the expr a-b-(c), local signs of the operands
  are +a, -b, +c*/

  static bool adjSign(String s, int i)
  {
    if (i == 0)
      return true;
    if (s[i-1] == '-')
      return false;
    return true;
  }

/*  Evaluate expressions into the count vector of
  the 26 alphabets.If add is true, then add count
  to the count vector of the alphabets, else remove
  count from the count vector.*/

  static void eval(String s, int[] v, bool add)
  {

/*    stack stores the global sign
    for operands.*/

    Stack<Boolean> stk = new Stack<Boolean>();
    stk.Push(true);

/*    + means true
    global sign is positive initially*/

    int i = 0;
    while (i < s.Length)
    {
      if (s[i] == '+' || s[i] == '-')
      {
        i++;
        continue;
      }
      if (s[i] == '(')
      {

/*        global sign for the bracket is
        pushed to the stack*/

        if (adjSign(s, i))
          stk.Push(stk.Peek());
        else
          stk.Push(!stk.Peek());
      }

/*      global sign is popped out which
      was pushed in for the last bracket*/

      else if (s[i] == ')')
        stk.Pop();
      else
      {

/*        global sign is positive (we use different
        values in two calls of functions so that
        we finally check if all vector elements
        are 0.*/

        if (stk.Peek())
          v[s[i] - 'a'] += (adjSign(s, i) ?
                            add ? 1 : -1 : add ? -1 : 1);

/*        global sign is negative here*/

        else
          v[s[i] - 'a'] += (adjSign(s, i) ?
                            add ? -1 : 1 : add ? 1 : -1);
      }
      i++;
    }
  }

/*  Returns true if expr1 and expr2 represent
  same expressions*/

  static bool areSame(String expr1, String expr2)
  {

/*    Create a vector for all operands and
    initialize the vector as 0.*/

    int[] v = new int[MAX_CHAR];

/*    Put signs of all operands in expr1*/

    eval(expr1, v, true);

/*    Subtract signs of operands in expr2*/

    eval(expr2, v, false);

/*    If expressions are same, vector must
    be 0.*/

    for (int i = 0; i < MAX_CHAR; i++)
      if (v[i] != 0)
        return false;
    return true;
  }

/*  Driver Code*/

  public static void Main(String[] args)
  {
    String expr1 = "-(a+b+c)", expr2 = "-a-b-c";
    if (areSame(expr1, expr2))
      Console.WriteLine("Yes");
    else
      Console.WriteLine("No");
  }
}

/*C# program to find index of closing 
bracket for given opening bracket. */

using System;
using System.Collections;
public class GFG {

/*Function to find index of closing 
bracket for given opening bracket. */

    static void test(String expression, int index) { 
        int i;

/*        If index given is invalid and is 
        not an opening bracket. */

        if (expression[index] != '[') { 
            Console.Write(expression + ", "
                    + index + ": -1\n"); 
            return; 
        }

/*        Stack to store opening brackets. */

        Stack st = new Stack();

/*        Traverse through string starting from 
        given index. */

        for (i = index; i < expression.Length; i++) {

/*            If current character is an 
            opening bracket push it in stack. */

            if (expression[i] == '[') { 
                st.Push((int) expression[i]); 
}

/*If current character is a closing  bracket, pop from stack. If stack 
            is empty, then this closing 
            bracket is required bracket. */

            else if (expression[i] == ']') { 
                st.Pop(); 
                if (st.Count==0) { 
                    Console.Write(expression + ", "
                            + index + ": " + i + "\n"); 
                    return; 
                } 
            } 
        }

/*        If no matching closing bracket 
        is found. */

        Console.Write(expression + ", "
                + index + ": -1\n"); 
    }

/*Driver Code */

    public static void Main() {

/*should be 8 */

test("[ABC[23]][89]", 0);

/*should be 7 */

test("[ABC[23]][89]", 4);

/*should be 12 */

test("[ABC[23]][89]", 9);

/*No matching bracket */

test("[ABC[23]][89]", 1); 
    } 
}

/*C# program to print minimum number that can be formed
from a given sequence of Is and Ds*/

using System;
class GFG
{

/*    Prints the minimum number that can be formed from
    input sequence of I's and D's*/

    static void PrintMinNumberForPattern(String arr)
    {

/*        Initialize current_max (to make sure that
        we don't use repeated character*/

        int curr_max = 0;

/*        Initialize last_entry (Keeps track for
        last printed digit)*/

        int last_entry = 0;
        int j;

/*        Iterate over input array*/

        for (int i = 0; i < arr.Length; i++)
        {

/*            Initialize 'noOfNextD' to get count of
            next D's available*/

            int noOfNextD = 0;
            switch (arr[i])
            {
                case 'I':

/*                    If letter is 'I'
                    Calculate number of next consecutive D's
                    available*/

                    j = i + 1;
                    while (j < arr.Length && arr[j] == 'D')
                    {
                        noOfNextD++;
                        j++;
                    }
                    if (i == 0)
                    {
                        curr_max = noOfNextD + 2;

/*                        If 'I' is first letter, print incremented
                        sequence from 1*/

                        Console.Write(" " + ++last_entry);
                        Console.Write(" " + curr_max);

/*                        Set max digit reached*/

                        last_entry = curr_max;
                    }
                    else
                    {

/*                        If not first letter
                        Get next digit to print*/

                        curr_max = curr_max + noOfNextD + 1;

/*                        Print digit for I*/

                        last_entry = curr_max;
                        Console.Write(" " + last_entry);
                    }

/*                    For all next consecutive 'D' print
                    decremented sequence*/

                    for (int k = 0; k < noOfNextD; k++)
                    {
                        Console.Write(" " + --last_entry);
                        i++;
                    }
                    break;

/*                If letter is 'D'*/

                case 'D':
                    if (i == 0)
                    {

/*                        If 'D' is first letter in sequence
                        Find number of Next D's available*/

                        j = i + 1;
                        while (j < arr.Length&&arr[j] == 'D')
                        {
                            noOfNextD++;
                            j++;
                        }

/*                        Calculate first digit to print based on
                        number of consecutive D's*/

                        curr_max = noOfNextD + 2;

/*                        Print twice for the first time*/

                        Console.Write(" " + curr_max + " " + (curr_max - 1));

/*                        Store last entry*/

                        last_entry = curr_max - 1;
                    }
                    else
                    {

/*                        If current 'D' is not first letter
                        Decrement last_entry*/

                        Console.Write(" " + (last_entry - 1));
                        last_entry--;
                    }
                    break;
            }
        }
        Console.WriteLine();
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        PrintMinNumberForPattern("IDID");
        PrintMinNumberForPattern("I");
        PrintMinNumberForPattern("DD");
        PrintMinNumberForPattern("II");
        PrintMinNumberForPattern("DIDI");
        PrintMinNumberForPattern("IIDDD");
        PrintMinNumberForPattern("DDIDDIID");
    }
}

/*C# program to print minimum number that can be formed
from a given sequence of Is and Ds*/

using System;
using System.Collections.Generic;
class GFG
{
static void printLeast(String arr)
{

/*    min_avail represents the minimum number which is
    still available for inserting in the output vector.
    pos_of_I keeps track of the most recent index
    where 'I' was encountered w.r.t the output vector*/

    int min_avail = 1, pos_of_I = 0;

/*    vector to store the output*/

    List<int> al = new List<int>();

/*    cover the base cases*/

    if (arr[0] == 'I')
    {
        al.Add(1);
        al.Add(2);
        min_avail = 3;
        pos_of_I = 1;
    }
    else
    {
        al.Add(2);
        al.Add(1);
        min_avail = 3;
        pos_of_I = 0;
    }

/*    Traverse rest of the input*/

    for (int i = 1; i < arr.Length; i++)
    {
        if (arr[i] == 'I')
        {
            al.Add(min_avail);
            min_avail++;
            pos_of_I = i + 1;
        }
        else
        {
            al.Add(al[i]);
            for (int j = pos_of_I; j <= i; j++)
                al[j] = al[j] + 1;
            min_avail++;
        }
    }

/*    print the number*/

    for (int i = 0; i < al.Count; i++)
        Console.Write(al[i] + " ");
    Console.WriteLine();
}

/*Driver code*/

public static void Main(String []args)
{
    printLeast("IDID");
    printLeast("I");
    printLeast("DD");
    printLeast("II");
    printLeast("DIDI");
    printLeast("IIDDD");
    printLeast("DDIDDIID");
}
}

/*C# program to print minimum number that can be formed
from a given sequence of Is and Ds*/

using System;
using System.Collections;
public class GFG {

/*Function to decode the given sequence to construct
minimum number without repeated digits*/

    static void PrintMinNumberForPattern(String seq) {

/*        result store output string*/

        String result = "";

/*        create an empty stack of integers*/

        Stack stk = new Stack();

/*        run n+1 times where n is length of input sequence*/

        for (int i = 0; i <= seq.Length; i++) {

/*            push number i+1 into the stack*/

            stk.Push(i + 1);

/*            if all characters of the input sequence are
            processed or current character is 'I'
            (increasing)*/

            if (i == seq.Length || seq[i] == 'I') {

/*                run till stack is empty*/

                while (stk.Count!=0) {

/*                    remove top element from the stack and
                    add it to solution*/

                    result += String.Join("",stk.Peek());
                    result += " ";
                    stk.Pop();
                }
            }
        }
        Console.WriteLine(result);
    }

/*main function*/

    public static void Main() {
        PrintMinNumberForPattern("IDID");
        PrintMinNumberForPattern("I");
        PrintMinNumberForPattern("DD");
        PrintMinNumberForPattern("II");
        PrintMinNumberForPattern("DIDI");
        PrintMinNumberForPattern("IIDDD");
        PrintMinNumberForPattern("DDIDDIID");
    }
}

/*C# program of above approach*/

using System;
class GFG
{

/*Returns minimum number made from given
sequence without repeating digits*/

static String getMinNumberForPattern(String seq)
{
    int n = seq.Length;
    if (n >= 9)
        return "-1";
    char []result = new char[n + 1];
    int count = 1;

/*    The loop runs for each input character
    as well as one additional time for
    assigning rank to each remaining characters*/

    for (int i = 0; i <= n; i++)
    {
        if (i == n || seq[i] == 'I')
        {
            for (int j = i - 1; j >= -1; j--)
            {
                result[j + 1] = (char) ((int) '0' + count++);
                if (j >= 0 && seq[j] == 'I')
                    break;
            }
        }
    }
    return new String(result);
}

/*Driver Code*/

public static void Main()
{
    String []inputs = { "IDID", "I", "DD", "II",
                        "DIDI", "IIDDD", "DDIDDIID" };
    foreach(String input in inputs)
    {
        Console.WriteLine(getMinNumberForPattern(input));
    }
}
}

/*C# program to find duplicate parenthesis 
in a balanced expression */

using System;
using System.Collections.Generic;
class GFG 
{

/*Function to find duplicate parenthesis  
in a balanced expression */

static Boolean findDuplicateparenthesis(String s) 
{

/*    create a stack of characters */

    Stack<char> Stack = new Stack<char>();

/*    Iterate through the given expression */

    char[] str = s.ToCharArray();
    foreach (char ch in str) 
    {

/*        if current character is 
        close parenthesis ')' */

        if (ch == ')') 
        {

/*            pop character from the stack */

            char top = Stack.Peek();
            Stack.Pop();

/*            stores the number of characters between
            a closing and opening parenthesis 
            if this count is less than or equal to 1 
            then the brackets are redundant else not */

            int elementsInside = 0;
            while (top != '(') 
            {
                elementsInside++;
                top = Stack.Peek();
                Stack.Pop();
            }
            if (elementsInside < 1) 
            {
                return true;
            }
        }

/*        push open parenthesis '(', 
        operators and operands to stack */

        else 
        {
            Stack.Push(ch);
        }
    }

/*    No duplicates found */

    return false;
}

/*Driver code */

public static void Main(String[] args)
{

/*    input balanced expression */

    String str = "(((a+(b))+(c+d)))";
    if (findDuplicateparenthesis(str))
    {
        Console.WriteLine("Duplicate Found ");
    } 
    else 
    {
        Console.WriteLine("No Duplicates Found ");
    }
}
}

/*C# Program to find Right smaller element of next
greater element*/

using System;
using System.Collections.Generic;
public class GFG {

/*    function find Next greater element*/

    public static void nextGreater(int []arr, int []next, char order)
    {

/*        create empty stack*/

        Stack<int> stack=new Stack<int>();

/*        Traverse all array elements in reverse order
        order == 'G' we compute next greater elements of
                     every element
        order == 'S' we compute right smaller element of
                     every element*/

        for (int i=arr.Length-1; i>=0; i--)
        {

/*            Keep removing top element from S while the top
            element is smaller then or equal to arr[i] (if Key is G)
            element is greater then or equal to arr[i] (if order is S)*/

            while (stack.Count!=0 && ((order=='G')? arr[stack.Peek()] <= arr[i]:arr[stack.Peek()] >= arr[i]))
                stack.Pop();

/*            store the next greater element of current element*/

            if (stack.Count!=0)
                next[i] = stack.Peek();

/*            If all elements in S were smaller than arr[i]*/

            else
                next[i] = -1;

/*            Push this element*/

            stack.Push(i);
        }
    }

/*    Function to find Right smaller element of next greater
    element*/

    public static void nextSmallerOfNextGreater(int []arr)
    {

/*stores indexes of next greater elements*/

int []NG=new int[arr.Length];

/*stores indexes of right smaller elements*/

int []RS=new int[arr.Length];

/*        Find next greater element
        Here G indicate next greater element*/

        nextGreater(arr, NG, 'G');

/*        Find right smaller element
        using same function nextGreater()
        Here S indicate right smaller elements*/

        nextGreater(arr, RS, 'S');

/*        If NG[i] == -1 then there is no smaller element
        on right side. We can find Right smaller of next
        greater by arr[RS[NG[i]]]*/

        for (int i=0; i< arr.Length; i++)
        {
            if (NG[i] != -1 && RS[NG[i]] != -1)
                Console.Write(arr[RS[NG[i]]]+" ");
            else
                Console.Write("-1 ");
        }
    }

/*    Driver code*/

    public static void Main() {
        int []arr = {5, 1, 9, 2, 5, 1, 7};
        nextSmallerOfNextGreater(arr);
    }
}

/*C# program to count the number less than N,
whose all permutation is greater than
or equal to the number.*/

using System;
using System.Collections.Generic;
class GFG {

/*    Return the count of the number
    having all permutation greater than
    or equal to the number.*/

    static int countNumber(int n)
    {
        int result = 0;

/*        Pushing 1 to 9 because all number from 1
        to 9 have this property.*/

        Stack<int> s = new Stack<int>();
        for (int i = 1; i <= 9; i++)
        {
            if (i <= n)
            {
                s.Push(i);
                result++;
            }

/*            take a number from stack and add
            a digit smaller than last digit
            of it.*/

            while (s.Count != 0)
            {
                int tp = s.Peek();
                s.Pop();
                for (int j = tp % 10; j <= 9; j++)
                {
                    int x = tp * 10 + j;
                    if (x <= n) {
                        s.Push(x);
                        result++;
                    }
                }
            }
        }
        return result;
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int n = 15;
        Console.WriteLine(countNumber(n));
    }
}

/*C# program to remove consecutive same words */

using System;
using System.Collections.Generic;
class GFG
{

/*Method to find the size of 
manipulated sequence */

public static int removeConsecutiveSame(List<string> v)
{
    int n = v.Count;

/*    Start traversing the sequence */

    for (int i = 0; i < n - 1;)
    {

/*        Compare the current string with 
        next one Erase both if equal */

        if (v[i].Equals(v[i + 1]))
        {

/*            Erase function delete the element and 
            also shifts other element that's why 
            i is not updated */

            v.RemoveAt(i);
            v.RemoveAt(i);

/*            Update i, as to check from 
            previous element again */

            if (i > 0)
            {
                i--;
            }

/*            Reduce sequence size */

            n = n - 2;
        }

/*        Increment i, if not equal */

        else
        {
            i++;
        }
    }

/*    Return modified size */

    return v.Count;
}

/*Driver Code */

public static void Main(string[] args)
{
    List<string> v = new List<string>();
    v.Add("tom");
    v.Add("jerry");
    v.Add("jerry");
    v.Add("tom");
    Console.WriteLine(removeConsecutiveSame(v));
}
}

/*C# implementation of above method */

using System;
using System.Collections.Generic;
class GFG
{

/*Method to find the size of 
manipulated sequence */

public static int removeConsecutiveSame(List<string> v)
{
    Stack<string> st = new Stack<string>();

/*    Start traversing the sequence */

    for (int i = 0; i < v.Count; i++)
    {

/*        Push the current string if 
        the stack is empty */

        if (st.Count == 0)
        {
            st.Push(v[i]);
        }
        else
        {
            string str = st.Peek();

/*            compare the current string with  
            stack top if equal, pop the top */

            if (str.Equals(v[i]))
            {
                st.Pop();
            }

/*            Otherwise push the current 
            string */

            else
            {
                st.Push(v[i]);
            }
        }
    }

/*    Return stack size */

    return st.Count;
}

/*Driver Code */

public static void Main(string[] args)
{
    List<string> v = new List<string>();
    v.Add("ab");
    v.Add("aa");
    v.Add("aa");
    v.Add("bcd");
    v.Add("ab");
    Console.WriteLine(removeConsecutiveSame(v));
}
}

/*C# program to decode a string recursively 
encoded as count followed substring */

using System;
using System.Collections.Generic;
class GFG
{

/*Returns decoded string for 'str' */

public static string decode(string str)
{
    Stack<int> integerstack = new Stack<int>();
    Stack<char> stringstack = new Stack<char>();
    string temp = "", result = "";

/*    Traversing the string */

    for (int i = 0; i < str.Length; i++)
    {
        int count = 0;

/*        If number, convert it into number 
        and push it into integerstack. */

        if (char.IsDigit(str[i]))
        {
            while (char.IsDigit(str[i]))
            {
                count = count * 10 + str[i] - '0';
                i++;
            }
            i--;
            integerstack.Push(count);
        }

/*        If closing bracket ']', pop elemment 
        until '[' opening bracket is not found 
        in the character stack. */

        else if (str[i] == ']')
        {
            temp = "";
            count = 0;
            if (integerstack.Count > 0)
            {
                count = integerstack.Peek();
                integerstack.Pop();
            }
            while (stringstack.Count > 0 && 
                   stringstack.Peek() != '[')
            {
                temp = stringstack.Peek() + temp;
                stringstack.Pop();
            }
            if (stringstack.Count > 0 && 
                stringstack.Peek() == '[')
            {
                stringstack.Pop();
            }

/*            Repeating the popped string 'temo' 
            count number of times. */

            for (int j = 0; j < count; j++)
            {
                result = result + temp;
            }

/*            Push it in the character stack. */

            for (int j = 0; j < result.Length; j++)
            {
                stringstack.Push(result[j]);
            }
            result = "";
        }

/*        If '[' opening bracket, push it 
        into character stack. */

        else if (str[i] == '[')
        {
            if (char.IsDigit(str[i - 1]))
            {
                stringstack.Push(str[i]);
            }
            else
            {
                stringstack.Push(str[i]);
                integerstack.Push(1);
            }
        }
        else
        {
            stringstack.Push(str[i]);
        }
    }

/*    Pop all the elmenet, make a 
    string and return. */

    while (stringstack.Count > 0)
    {
        result = stringstack.Peek() + result;
        stringstack.Pop();
    }
    return result;
}

/*Driver Code */

public static void Main(string[] args)
{
    string str = "3[b2[ca]]";
    Console.WriteLine(decode(str));
}
}

/*C# program to print all 
ancestors of a given key */

using System;
using System.Collections.Generic;
class GfG 
{

/*Structure for a tree node */

public class Node
{ 
    public int data; 
    public Node left, right; 
}

/*A utility function to 
create a new tree node */

static Node newNode(int data) 
{ 
    Node node = new Node(); 
    node.data = data; 
    node.left = null;
    node.right = null; 
    return node; 
}

/*Iterative Function to print 
all ancestors of a given key */

static void printAncestors(Node root, int key) 
{ 
    if (root == null) 
        return;

/*    Create a stack to hold ancestors */

    Stack<Node> st = new Stack<Node> ();

/*    Traverse the complete tree in 
    postorder way till we find the key */

    while (1 == 1) 
    {

/*        Traverse the left side. While 
        traversing, push the nodes into 
        the stack so that their right 
        subtrees can be traversed later */

        while (root != null && root.data != key) 
        {

/*push current node */

st.Push(root);

/*move to next node */

root = root.left; 
        }

/*        If the node whose ancestors 
        are to be printed is found,
        then break the while loop. */

        if (root != null && root.data == key) 
            break;

/*        Check if right sub-tree exists
        for the node at top If not then
        pop that node because we don't 
        need this node any more. */

        if (st.Peek().right == null) 
        { 
            root = st.Peek(); 
            st.Pop();

/*            If the popped node is right child of top, 
            then remove the top as well. Left child of 
            the top must have processed before. */

            while (st.Count != 0 && st.Peek().right == root)
            { 
                root = st.Peek(); 
                st.Pop(); 
            } 
        }

/*        if stack is not empty then simply 
        set the root as right child of 
        top and start traversing right 
        sub-tree. */

        root = st.Count == 0 ? null : st.Peek().right; 
    }

/*    If stack is not empty, print contents of stack 
    Here assumption is that the key is there in tree */

    while (st.Count != 0)
    { 
        Console.Write(st.Peek().data + " "); 
        st.Pop(); 
    } 
}

/*Driver code */

public static void Main(String[] args) 
{

/*    Let us construct a binary tree */

    Node root = newNode(1); 
    root.left = newNode(2); 
    root.right = newNode(7); 
    root.left.left = newNode(3); 
    root.left.right = newNode(5); 
    root.right.left = newNode(8); 
    root.right.right = newNode(9); 
    root.left.left.left = newNode(4); 
    root.left.right.right = newNode(6); 
    root.right.right.left = newNode(10); 
    int key = 6; 
    printAncestors(root, key); 
}
}

/*C# program to keep track of maximum 
element in a stack */

using System;
using System.Collections.Generic;
class GfG 
{
public class StackWithMax 
{

/*    main stack */

    static Stack<int> mainStack = new Stack<int> ();

/*    tack to keep track of max element */

    static Stack<int> trackStack = new Stack<int> (); 
    public void push(int x) 
    { 
        mainStack.Push(x); 
        if (mainStack.Count == 1) 
        { 
            trackStack.Push(x); 
            return; 
        }

/*        If current element is greater than 
        the top element of track stack, push 
        the current element to track stack 
        otherwise push the element at top of 
        track stack again into it. */

        if (x > trackStack.Peek()) 
            trackStack.Push(x); 
        else
            trackStack.Push(trackStack.Peek()); 
    } 
    public int getMax() 
    { 
        return trackStack.Peek(); 
    } 
    public void pop() 
    { 
        mainStack.Pop(); 
        trackStack.Pop(); 
    } 
};

/*Driver code*/

public static void Main() 
{ 
    StackWithMax s = new StackWithMax(); 
    s.push(20); 
    Console.WriteLine(s.getMax()); 
    s.push(10); 
    Console.WriteLine(s.getMax()); 
    s.push(50); 
    Console.WriteLine(s.getMax()); 
}
}

/*C# program to reverse the number 
using a stack */

using System;
using System.Collections.Generic;
class GFG
{

/*Stack to maintain order of digits */

public static Stack<int> st = new Stack<int>();

/*Function to push digits into stack */

public static void push_digits(int number)
{
    while (number != 0)
    {
        st.Push(number % 10);
        number = number / 10;
    }
}

/*Function to reverse the number */

public static int reverse_number(int number)
{

/*    Function call to push number's 
    digits to stack */

    push_digits(number);
    int reverse = 0;
    int i = 1;

/*    Popping the digits and forming 
    the reversed number */

    while (st.Count > 0)
    {
        reverse = reverse + (st.Peek() * i);
        st.Pop();
        i = i * 10;
    }

/*    Return the reversed number formed */

    return reverse;
}

/*Driver Code*/

public static void Main(string[] args)
{
    int number = 39997;

/*    Function call to reverse number*/

    Console.WriteLine(reverse_number(number));
}
}

/*C# program to simplify algebraic string*/

using System;
using System.Collections.Generic;
class GfG 
{

/*Function to simplify the string */

static String simplify(String str) 
{ 
    int len = str.Length;

/*    resultant string of max length equal 
    to length of input string */

    char []res = new char[len]; 
    int index = 0, i = 0;

/*    create empty stack */

    Stack<int> s = new Stack<int> (); 
    s.Push(0); 
    while (i < len)
    { 
        if (str[i] == '+')
        {

/*            If top is 1, flip the operator */

            if (s.Peek() == 1) 
                res[index++] = '-';

/*            If top is 0, append the same operator */

            if (s.Peek() == 0) 
                res[index++] = '+'; 
        } 
        else if (str[i] == '-')
        { 
            if (s.Peek() == 1) 
                res[index++] = '+'; 
            else if (s.Peek() == 0) 
                res[index++] = '-'; 
        }
        else if (str[i] == '(' && i > 0) 
        { 
            if (str[i - 1] == '-') 
            {

/*                x is opposite to the top of stack */

                int x = (s.Peek() == 1) ? 0 : 1; 
                s.Push(x); 
            }

/*            push value equal to top of the stack */

            else if (str[i - 1] == '+') 
                s.Push(s.Peek()); 
        }

/*        If closing parentheses pop the stack once */

        else if (str[i]== ')') 
            s.Pop();

/*        copy the character to the result */

        else
            res[index++] = str[i]; 
        i++; 
    } 
    return new String(res); 
}

/*Driver code*/

public static void Main(String[] args) 
{ 
    String s1 = "a-(b+c)"; 
    String s2 = "a-(b-c-(d+e))-f"; 
    Console.WriteLine(simplify(s1)); 
    Console.WriteLine(simplify(s2));
}
}

/*C# Program to implement growable array based stack
using tight strategy*/

using System;
class GFG
{

/*constant amount at which stack is increased*/

static int BOUND = 4;

/*top of the stack*/

static int top = -1;

/*length of stack*/

static int length = 0;

/*function to create new stack*/

static int[] create_new(int[] a)
{

/*    allocate memory for new stack*/

    int[] new_a = new int[length + BOUND];

/*    copying the content of old stack*/

    for (int i = 0; i < length; i++)
        new_a[i] = a[i];

/*    re-sizing the length*/

    length += BOUND;
    return new_a;
}

/*function to push new element*/

static int[] push(int[] a, int element)
{

/*    if stack is full, create new one*/

    if (top == length - 1)
        a = create_new(a);

/*    insert element at top of the stack*/

    a[++top] = element;
    return a;
}

/*function to pop an element*/

static void pop(int[] a)
{
    top--;
}

/*function to display*/

static void display(int[] a)
{

/*    if top is -1, that means stack is empty*/

    if (top == -1)
        Console.WriteLine("Stack is Empty");
    else
    {
        Console.Write("Stack: ");
        for (int i = 0; i <= top; i++)
            Console.Write(a[i] + " ");
        Console.WriteLine();
    }
}

/*Driver Code*/

public static void Main(String []args)
{

/*    creating initial stack*/

    int []a = create_new(new int[length + BOUND]);

/*    pushing element to top of stack*/

    a = push(a, 1);
    a = push(a, 2);
    a = push(a, 3);
    a = push(a, 4);
    display(a);

/*    pushing more element when stack is full*/

    a = push(a, 5);
    a = push(a, 6);
    display(a);
    a = push(a, 7);
    a = push(a, 8);
    display(a);

/*    pushing more element so that stack can grow*/

    a = push(a, 9);
    display(a);
}
}

/*C# code to answer the query
in constant time*/

using System;
using System.Collections.Generic;
class GFG{

/*
    BOP[] stands for "Balanced open parentheses"
    BCP[] stands for "Balanced close parentheses"
    */

/*    Function for precomputation*/

    static void constructBlanceArray(int[] BOP, int[] BCP,
                                     String str, int n)
    {

/*        Create a stack and push -1
        as initial index to it.*/

        Stack<int> stk = new Stack<int>();;

/*        Traverse all characters of given String*/

        for (int i = 0; i < n; i++)
        {

/*            If opening bracket, push index of it*/

            if (str[i] == '(')
                stk.Push(i);

/*            If closing bracket, i.e., str[i] = ')'*/

            else
            {

/*                If closing bracket, i.e., str[i] = ')'
                && stack is not empty then mark both
                "open & close" bracket indexs as 1 .
                Pop the previous opening bracket's index*/

                if (stk.Count != 0)
                {
                    BCP[i] = 1;
                    BOP[stk.Peek()] = 1;
                    stk.Pop();
                }

/*                If stack is empty.*/

                else
                    BCP[i] = 0;
            }
        }
        for (int i = 1; i < n; i++)
        {
            BCP[i] += BCP[i - 1];
            BOP[i] += BOP[i - 1];
        }
    }

/*    Function return output of each query in O(1)*/

    static int query(int[] BOP, int[] BCP, int s, int e)
    {
        if (BOP[s - 1] == BOP[s])
        {
            return (BCP[e] - BOP[s]) * 2;
        }
        else
        {
            return (BCP[e] - BOP[s] + 1) * 2;
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        String str = "())(())(())(";
        int n = str.Length;
        int[] BCP = new int[n + 1];
        int[] BOP = new int[n + 1];
        constructBlanceArray(BOP, BCP, str, n);
        int startIndex = 5, endIndex = 11;
        Console.Write("Maximum Length Correct " +
                      "Bracket Subsequence between " +
                       startIndex + " and " + endIndex + " = " +
                       query(BOP, BCP, startIndex, endIndex) + "\n");
        startIndex = 4;
        endIndex = 5;
        Console.Write("Maximum Length Correct " +
                      "Bracket Subsequence between " +
                       startIndex + " and " + endIndex + " = " +
                       query(BOP, BCP, startIndex, endIndex) + "\n");
        startIndex = 1;
        endIndex = 5;
        Console.Write("Maximum Length Correct " +
                      "Bracket Subsequence between " +
                       startIndex + " and " + endIndex + " = " +
                       query(BOP, BCP, startIndex, endIndex) + "\n");
    }
}

/*C# program for implementation of Heap Sort*/

using System;
public class HeapSort {

/*    To heapify a subtree rooted with node i which is
    an index in arr[]. n is size of heap*/

    void heapify(int[] arr, int n, int i)
    {

/*Initialize largest as root*/

int largest = i;

/*left = 2*i + 1*/

int l = 2 * i + 1;

/*right = 2*i + 2*/

int r = 2 * i + 2;

/*        If left child is larger than root*/

        if (l < n && arr[l] > arr[largest])
            largest = l;

/*        If right child is larger than largest so far*/

        if (r < n && arr[r] > arr[largest])
            largest = r;

/*        If largest is not root*/

        if (largest != i) {
            int swap = arr[i];
            arr[i] = arr[largest];
            arr[largest] = swap;

/*            Recursively heapify the affected sub-tree*/

            heapify(arr, n, largest);
        }
    }

/*The main function to sort an array of given size*/

    public void sort(int[] arr)
    {
        int n = arr.Length;

/*        Build heap (rearrange array)*/

        for (int i = n / 2 - 1; i >= 0; i--)
            heapify(arr, n, i);

/*        One by one extract an element from heap*/

        for (int i = n - 1; i > 0; i--) {

/*            Move current root to end*/

            int temp = arr[0];
            arr[0] = arr[i];
            arr[i] = temp;

/*            call max heapify on the reduced heap*/

            heapify(arr, i, 0);
        }
    }

/* A utility function to print array of size n */

    static void printArray(int[] arr)
    {
        int n = arr.Length;
        for (int i = 0; i < n; ++i)
            Console.Write(arr[i] + " ");
        Console.Read();
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 12, 11, 13, 5, 6, 7 };
        int n = arr.Length;
        HeapSort ob = new HeapSort();
        ob.sort(arr);
        Console.WriteLine("Sorted array is");
        printArray(arr);
    }
}

/*C# implementation of Iterative Heap Sort */

using System;
class HeapSort 
{

/*function build Max Heap where value
of each child is always smaller
than value of their parent*/

static void buildMaxHeap(int []arr, int n)
{
    for (int i = 1; i < n; i++)
    {

/*        if child is bigger than parent*/

        if (arr[i] > arr[(i - 1) / 2])
        {
            int j = i;

/*            swap child and parent until
            parent is smaller*/

            while (arr[j] > arr[(j - 1) / 2])
            {
                swap(arr, j, (j - 1) / 2);
                j = (j - 1) / 2;
            }
        }
    }
}
static void heapSort(int []arr, int n)
{
    buildMaxHeap(arr, n);
    for (int i = n - 1; i > 0; i--)
    {

/*        swap value of first indexed
        with last indexed*/

        swap(arr, 0, i);

/*        maintaining heap property
        after each swapping*/

        int j = 0, index;
        do
        {
            index = (2 * j + 1);

/*            if left child is smaller than
            right child point index variable
            to right child*/

            if (index < (i - 1) && arr[index] < 
                                   arr[index + 1])
            index++;

/*            if parent is smaller than child
            then swapping parent with child
            having higher value*/

            if (index < i && arr[j] < arr[index])
                swap(arr, j, index);
            j = index;
        } while (index < i);
    }
}
public static void swap(int[] a, int i, int j) 
{
    int temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}

/* A utility function to print array of size n */

static void printArray(int []arr)
{
    int n = arr.Length;
    for (int i = 0; i < n; i++)
    Console.Write(arr[i] + " ");
    Console.WriteLine();
}

/*Driver Code*/

public static void Main(String []args)
{
    int []arr = {10, 20, 15, 17, 9, 21};
    int n = arr.Length;
    Console.Write("Given array: ");
    printArray(arr);
    heapSort(arr, n);
    Console.Write("Sorted array: ");
    printArray(arr);
}
}

/*C# program to checks if a
binary tree is max heap or not*/

using System;
using System.Collections.Generic;
public class GFG
{

/*  Tree node structure*/

 public
   class Node
  {
    public
 int data;
   public
  Node left;
   public
  Node right;
  };

/*  To add a new node*/

  static Node newNode(int k)
  {
    Node node = new Node();
    node.data = k;
    node.right = node.left = null;
    return node;
  }
  static bool isHeap(Node root)
  {
    Queue<Node> q = new Queue<Node>();
    q.Enqueue(root);
    bool nullish = false;
    while (q.Count!=0)
    {
      Node temp = q.Peek();
      q.Dequeue();
      if (temp.left != null)
      {
        if (nullish || temp.left.data
            >= temp.data)
        {
          return false;
        }
        q.Enqueue(temp.left);
      }
      else {
        nullish = true;
      }
      if (temp.right != null)
      {
        if (nullish || temp.right.data
            >= temp.data)
        {
          return false;
        }
        q.Enqueue(temp.right);
      }
      else
      {
        nullish = true;
      }
    }
    return true;
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    Node root = null;
    root = newNode(10);
    root.left = newNode(9);
    root.right = newNode(8);
    root.left.left = newNode(7);
    root.left.right = newNode(6);
    root.right.left = newNode(5);
    root.right.right = newNode(4);
    root.left.left.left = newNode(3);
    root.left.left.right = newNode(2);
    root.left.right.left = newNode(1);

/*    Function call*/

    if (isHeap(root))
      Console.Write("Given binary tree is a Heap\n");
    else
      Console.Write("Given binary tree is not a Heap\n");
  }
}

/*C# program to check whether a given 
array represents a max-heap or not*/

using System;
class GFG
{

/*Returns true if arr[i..n-1] represents a
max-heap*/

static bool isHeap(int []arr, int i, int n)
{

/*    If a leaf node*/

    if (i >= (n - 2) / 2)
    {
        return true;
    }

/*    If an internal node and is greater
    than its children, and same is
    recursively true for the children*/

    if (arr[i] >= arr[2 * i + 1] &&
        arr[i] >= arr[2 * i + 2] &&
        isHeap(arr, 2 * i + 1, n) &&
        isHeap(arr, 2 * i + 2, n))
    {
        return true;
    }
    return false;
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []arr = {90, 15, 10, 7, 12, 2, 7, 3};
    int n = arr.Length-1;
    if (isHeap(arr, 0, n))
    {
        Console.Write("Yes");
    }
    else
    {
        Console.Write("No");
    }
}
}

/*C# program to check whether a given array
represents a max-heap or not*/

using System;
class GFG
{

/*Returns true if arr[i..n-1]
represents a max-heap*/

static bool isHeap(int []arr, int n)
{

/*    Start from root and go till
    the last internal node*/

    for (int i = 0; i <= (n - 2) / 2; i++)
    {

/*        If left child is greater,
        return false*/

        if (arr[2 * i + 1] > arr[i])
        {
            return false;
        }

/*        If right child is greater,
        return false*/

        if (2 * i + 2 < n && arr[2 * i + 2] > arr[i])
        {
            return false;
        }
    }
    return true;
}

/*Driver Code*/

public static void Main()
{
    int []arr = {90, 15, 10, 7, 12, 2, 7, 3};
    int n = arr.Length;
    if (isHeap(arr, n))
    {
        Console.Write("Yes");
    }
    else
    {
        Console.Write("No");
    }
}
}

/*C# program to connect n ropes with minimum cost*/

using System;

/*A class for Min Heap*/

class MinHeap {

/*Array of elements in heap*/

int[] harr;

/*Current number of elements in min heap*/

int heap_size;

/*maximum possible size of min heap*/

int capacity;

/*    Constructor: Builds a heap from
    a given array a[] of given size*/

    public MinHeap(int[] a, int size)
    {
        heap_size = size;
        capacity = size;
        harr = a;
        int i = (heap_size - 1) / 2;
        while (i >= 0) {
            MinHeapify(i);
            i--;
        }
    }

/*    A recursive method to heapify a subtree
    with the root at given index
    This method assumes that the subtrees
    are already heapified*/

    void MinHeapify(int i)
    {
        int l = left(i);
        int r = right(i);
        int smallest = i;
        if (l < heap_size && harr[l] < harr[i])
            smallest = l;
        if (r < heap_size && harr[r] < harr[smallest])
            smallest = r;
        if (smallest != i) {
            swap(i, smallest);
            MinHeapify(smallest);
        }
    }
    int parent(int i) { return (i - 1) / 2; }

/*    to get index of left child of node at index i*/

    int left(int i) { return (2 * i + 1); }

/*    to get index of right child of node at index i*/

    int right(int i) { return (2 * i + 2); }

/*    Method to remove minimum element (or root) from min heap*/

    int extractMin()
    {
        if (heap_size <= 0)
            return int.MaxValue;
        if (heap_size == 1) {
            heap_size--;
            return harr[0];
        }

/*        Store the minimum value, and remove it from heap*/

        int root = harr[0];
        harr[0] = harr[heap_size - 1];
        heap_size--;
        MinHeapify(0);
        return root;
    }

/*    Inserts a new key 'k'*/

    void insertKey(int k)
    {
        if (heap_size == capacity) {
            Console.WriteLine("Overflow: Could not insertKey");
            return;
        }

/*        First insert the new key at the end*/

        heap_size++;
        int i = heap_size - 1;
        harr[i] = k;

/*        Fix the min heap property if it is violated*/

        while (i != 0 && harr[parent(i)] > harr[i]) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

/*    A utility function to check
    if size of heap is 1 or not*/

    Boolean isSizeOne()
    {
        return (heap_size == 1);
    }

/*    A utility function to swap two elements*/

    void swap(int x, int y)
    {
        int temp = harr[x];
        harr[x] = harr[y];
        harr[y] = temp;
    }

/*    The main function that returns the
    minimum cost to connect n ropes of
    lengths stored in len[0..n-1]*/

    static int minCost(int[] len, int n)
    {

/*Initialize result*/

int cost = 0;

/*        Create a min heap of capacity equal
        to n and put all ropes in it*/

        MinHeap minHeap = new MinHeap(len, n);

/*        Iterate while size of heap doesn't become 1*/

        while (!minHeap.isSizeOne()) {

/*            Extract two minimum length ropes from min heap*/

            int min = minHeap.extractMin();
            int sec_min = minHeap.extractMin();

/*Update total cost*/

cost += (min + sec_min);

/*            Insert a new rope in min heap with length equal to sum
            of two extracted minimum lengths*/

            minHeap.insertKey(min + sec_min);
        }

/*        Finally return total minimum
        cost for connecting all ropes*/

        return cost;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int[] len = { 4, 3, 2, 6 };
        int size = len.Length;
        Console.WriteLine("Total cost for connecting ropes is " + minCost(len, size));
    }
};

/*C# program to connect n
ropes with minimum cost*/

using System;
using System.Collections.Generic;
public class ConnectRopes
{
  static int minCost(int []arr, int n)
  {

/*    Create a priority queue*/

    List<int> pq = new List<int>();
    for (int i = 0; i < n; i++)
    {
      pq.Add(arr[i]);
    }

/*    Initialize result*/

    int res = 0;

/*    While size of priority queue
    is more than 1*/

    while (pq.Count > 1)
    {
      pq.Sort();

/*      Extract shortest two ropes from pq*/

      int first = pq[0];
      int second = pq[1];
      pq.RemoveRange(0, 2);

/*      Connect the ropes: update result
      and insert the new rope to pq*/

      res += first + second;
      pq.Add(first + second);
    }
    return res;
  }

/*  Driver program to test above function*/

  public static void Main(String []args)
  {
    int []len = { 4, 3, 2, 6 };
    int size = len.Length;
    Console.WriteLine("Total cost for connecting"
                      + " ropes is " + minCost(len, size));
  }
}

/*C# program to merge k sorted arrays of size n each.*/

using System;
public class GFG
{

/*  This function takes an array of arrays as an argument
  and
  All arrays are assumed to be sorted. It merges them
  together and prints the readonly sorted output.*/

  public static void mergeKArrays(int[,] arr, int a,
                                  int[] output)
  {
    int c = 0;

/*    traverse the matrix*/

    for (int i = 0; i < a; i++)
    {
      for (int j = 0; j < 4; j++)
        output[c++] = arr[i,j];
    }

/*    sort the array*/

    Array.Sort(output);
  }

/*  A utility function to print array elements*/

  public static void printArray(int[] arr, int size)
  {
    for (int i = 0; i < size; i++)
      Console.Write(arr[i] + " ");
  }

/*  Driver program to test above functions*/

  public static void Main(String[] args)
  {
    int[,] arr = { { 2, 6, 12, 34 },
                  { 1, 9, 20, 1000 },
                  { 23, 34, 90, 2000 } };
    int k = 4;
    int n = 3;
    int[] output = new int[n * k];
    mergeKArrays(arr, n, output);
    Console.WriteLine("Merged array is ");
    printArray(output, n * k);
  }
}

/*C# program to generate
smallest derangement
using priority queue.*/

using System;
using System.Collections.Generic;
class GFG{
static void generate_derangement(int N)
{

/*  Generate Sequence and insert
  into a priority queue.*/

  int []S = new int[N + 1];
  List<int> PQ = new List <int>();
  for(int i = 1; i <= N; i++)
  {
    S[i] = i;
    PQ.Add(S[i]);
  }

/*  Generate Least Derangement*/

  int []D = new int[N + 1];
  PQ.Sort();
  for(int i = 1; i <= N; i++)
  {
    PQ.Sort();
    int d = PQ[0];
    PQ.RemoveAt(0);
    if (d != S[i] || i == N)
    {
      D[i] = d;
    }
    else
    {
      PQ.Sort();
      D[i] = PQ[0];
      PQ.RemoveAt(0);
      PQ.Add(d);
    }
  }
  if (D[N] == S[N])
  {
    int t = D[N - 1];
    D[N - 1] = D[N];
    D[N] = t;
  }

/*  Print Derangement*/

  for(int i = 1; i <= N; i++)
    Console.Write(D[i] + " "); 
  Console.Write("\n");
}

/*Driver code*/

public static void Main(String[] args)
{
  generate_derangement(10);
}
}

/*Efficient C# program to find
smallest derangement.*/

using System;
class GFG
{
static void generate_derangement(int N)
{

/*    Generate Sequence S*/

    int[] S = new int[N + 1];
    for (int i = 1; i <= N; i++)
        S[i] = i;

/*    Generate Derangement*/

    int[] D = new int[N + 1];
    for (int i = 1; i <= N; i += 2)
    {
        if (i == N)
        {

/*            Only if i is odd
            Swap S[N-1] and S[N]*/

            D[N] = S[N - 1];
            D[N - 1] = S[N];
        }
        else
        {
            D[i] = i + 1;
            D[i + 1] = i;
        }
    }

/*    Print Derangement*/

    for (int i = 1; i <= N; i++)
        Console.Write(D[i] + " ");
    Console.WriteLine();
}

/*Driver Program*/

public static void Main()
{
    generate_derangement(10);
}
}

/*C# program to find the largest derangement*/

using System;
using System.Collections.Generic;
class GFG
{
    static void printLargest(int[] seq, int N)
    {

/*Stores result*/

int[] res = new int[N];

/*        Insert all elements into a priority queue*/

        List<int> pq = new List<int>();
        for (int i = 0; i < N; i++)
            pq.Add(seq[i]);

/*        Fill Up res[] from left to right*/

        for (int i = 0; i < N; i++)
        {
            pq.Sort();
            pq.Reverse();
            int d = pq[0];
            pq.RemoveAt(0);
            if (d != seq[i] || i == N - 1)
            {
                res[i] = d;
            }
          else
            {

/*                New Element poped equals the element
                in original sequence. Get the next
                largest element*/

                res[i] = pq[0];
                pq.RemoveAt(0);
                pq.Add(d);
            }
        }

/*        If given sequence is in descending order then
        we need to swap last two elements again*/

        if (res[N - 1] == seq[N - 1])
        {
            res[N - 1] = res[N - 2];
            res[N - 2] = seq[N - 1];
        }    
        Console.WriteLine("Largest Derangement");
        for (int i = 0; i < N; i++)
            Console.Write(res[i] + " ");
    }

/*  Driver code*/

  static void Main()
  {
    int[] seq = { 92, 3, 52, 13, 2, 31, 1 };
    int n = seq.Length;
    printLargest(seq, n);
  }
}

/*C# program for implementation of Heap Sort*/

using System;
class GFG {

/*    To heapify a subtree rooted with
    node i which is an index in arr[],
    n is size of heap*/

    static void heapify(int[] arr, int n, int i)
    {

/*Initialize smalles as root*/

int smallest = i;

/*left = 2*i + 1*/

int l = 2 * i + 1;

/*right = 2*i + 2*/

int r = 2 * i + 2;

/*        If left child is smaller than root*/

        if (l < n && arr[l] < arr[smallest])
            smallest = l;

/*        If right child is smaller than smallest so far*/

        if (r < n && arr[r] < arr[smallest])
            smallest = r;

/*        If smallest is not root*/

        if (smallest != i) {
            int temp = arr[i];
            arr[i] = arr[smallest];
            arr[smallest] = temp;

/*            Recursively heapify the affected sub-tree*/

            heapify(arr, n, smallest);
        }
    }

/*    main function to do heap sort*/

    static void heapSort(int[] arr, int n)
    {

/*        Build heap (rearrange array)*/

        for (int i = n / 2 - 1; i >= 0; i--)
            heapify(arr, n, i);

/*        One by one extract an element from heap*/

        for (int i = n - 1; i >= 0; i--) {

/*            Move current root to end*/

            int temp = arr[0];
            arr[0] = arr[i];
            arr[i] = temp;

/*            call max heapify on the reduced heap*/

            heapify(arr, i, 0);
        }
    }

/* A utility function to print array of size n */

    static void printArray(int[] arr, int n)
    {
        for (int i = 0; i < n; ++i)
            Console.Write(arr[i] + " ");
        Console.WriteLine();
    }

/*    Driver program*/

    public static void Main()
    {
        int[] arr = { 4, 6, 3, 2, 9 };
        int n = arr.Length;
        heapSort(arr, n);
        Console.WriteLine("Sorted array is ");
        printArray(arr, n);
    }
}

/*C# program to find sum of all element
between to K1'th and k2'th smallest
elements in array*/

using System;
class GFG {

/*    Returns sum between two kth smallest
    element of array*/

    static int sumBetweenTwoKth(int[] arr, int n,
                                int k1, int k2)
    {

/*        Sort the given array*/

        Array.Sort(arr);

/*        Below code is equivalent to*/

        int result = 0;
        for (int i = k1; i < k2 - 1; i++)
            result += arr[i];
        return result;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 20, 8, 22, 4, 12, 10, 14 };
        int k1 = 3, k2 = 6;
        int n = arr.Length;
        Console.Write(sumBetweenTwoKth(arr, n, k1, k2));
    }
}

/*C# implementation of above approach*/

using System;
class GFG
{
static int n = 7;
static void minheapify(int []a, int index)
{
    int small = index;
    int l = 2 * index + 1;
    int r = 2 * index + 2;
    if (l < n && a[l] < a[small])
        small = l;
    if (r < n && a[r] < a[small])
        small = r;
    if (small != index)
    {
        int t = a[small];
        a[small] = a[index];
        a[index] = t;
        minheapify(a, small);
    }
}

/*Driver code*/

static void Main()
{
    int i = 0;
    int k1 = 3;
    int k2 = 6;
    int []a = { 20, 8, 22, 4, 12, 10, 14 };
    int ans = 0;
    for (i = (n / 2) - 1; i >= 0; i--)
    {
        minheapify(a, i);
    }

/*    decreasing value by 1 because we want
    min heapifying k times and it starts
    from 0 so we have to decrease it 1 time*/

    k1--;
    k2--;

/*    Step 1: Do extract minimum k1 times
    (This step takes O(K1 Log n) time)*/

    for (i = 0; i <= k1; i++)
    {
        a[0] = a[n - 1];
        n--;
        minheapify(a, 0);
    }

/*Step 2: Do extract minimum k2 – k1 – 1 times
    and sum all extracted elements. (This step
    takes O ((K2 – k1) * Log n) time)*/

    for (i = k1 + 1; i < k2; i++)
    {
        ans += a[0];
        a[0] = a[n - 1];
        n--;
        minheapify(a, 0);
    }
    Console.Write(ans);
}
}

/*C# a program to find minimum sum of two numbers
formed from all digits in a given array.*/

using System;
public class GFG{

/*    Returns sum of two numbers formed
    from all digits in a[]*/

    static int minSum(int []a, int n){

/*    sort the elements*/

    Array.Sort(a);
    int num1 = 0;
    int num2 = 0;
    for(int i = 0;i<n;i++){
        if(i%2==0)
            num1 = num1*10+a[i];
        else num2 = num2*10+a[i];
    }
    return num2+num1;
    }

/*    Driver code*/

    static public void Main (){
        int []arr = {5, 3, 0, 7, 4};
        int n = arr.Length;
        Console.WriteLine("The required sum is " + minSum(arr, n));
    }

}

/*C# program to find number 
of siblings of a given node */

using System;
using System.Collections.Generic; 
class GFG
{

/*Represents a node of an n-ary tree */

public class Node 
{ 
    public int key; 
    public List<Node> child; 
    public Node(int data) 
    { 
        key = data; 
        child = new List<Node>();
    } 
};

/*Function to calculate number 
of siblings of a given node */

static int numberOfSiblings(Node root, int x) 
{ 
    if (root == null) 
        return 0;

/*    Creating a queue and 
    pushing the root */

    Queue<Node> q = new Queue<Node>(); 
    q.Enqueue(root); 
    while (q.Count > 0) 
    {

/*        Dequeue an item from queue and 
        check if it is equal to x If YES, 
        then return number of children */

        Node p = q.Peek(); 
        q.Dequeue();

/*        Enqueue all children of 
        the dequeued item */

        for (int i = 0; i < p.child.Count; i++) 
        {

/*            If the value of children 
            is equal to x, then return 
            the number of siblings */

            if (p.child[i].key == x) 
                return p.child.Count - 1; 
            q.Enqueue(p.child[i]); 
        } 
    } 
    return -1;
}

/*Driver code*/

public static void Main(String []args)
{

/*    Creating a generic tree
    as shown in above figure */

    Node root = new Node(50); 
    (root.child).Add(new Node(2)); 
    (root.child).Add(new Node(30)); 
    (root.child).Add(new Node(14)); 
    (root.child).Add(new Node(60)); 
    (root.child[0].child).Add(new Node(15)); 
    (root.child[0].child).Add(new Node(25)); 
    (root.child[0].child[1].child).Add(new Node(70)); 
    (root.child[0].child[1].child).Add(new Node(100)); 
    (root.child[1].child).Add(new Node(6)); 
    (root.child[1].child).Add(new Node(1)); 
    (root.child[2].child).Add(new Node(7)); 
    (root.child[2].child[0].child).Add(new Node(17)); 
    (root.child[2].child[0].child).Add(new Node(99)); 
    (root.child[2].child[0].child).Add(new Node(27)); 
    (root.child[3].child).Add(new Node(16));

/*    Node whose number of 
    siblings is to be calculated */

    int x = 100;

/*    Function calling */

    Console.WriteLine( numberOfSiblings(root, x)); 
}
}

/*C# program to demonstrate 
