    {
        disjoint1 dis = new disjoint1();
        int []set1 = { 12, 34, 11, 9, 3 };
        int []set2 = { 7, 2, 1, 5 };
        Boolean result = dis.aredisjoint(set1, set2);
        if (result)
            Console.WriteLine("YES");
