/*C# program to find Non-overlapping sum*/

using System;
using System.Collections.Generic; 
class GFG 
{

/*    function for calculating 
    Non-overlapping sum of two array */

    static int findSum(int[] A, int[] B, int n)
    {

/*        Insert elements of both arrays*/

        Dictionary<int, int> hash = new Dictionary<int, int>();
        for (int i = 0; i < n; i++)
        {
            if (hash.ContainsKey(A[i]))
            {
                var v = hash[A[i]];
                hash.Remove(A[i]);
                hash.Add(A[i], 1 + v);
            }
            else
                hash.Add(A[i], 1);
            if (hash.ContainsKey(B[i]))
            {
                var v = hash[B[i]];
                hash.Remove(B[i]);
                hash.Add(B[i], 1 + v);
            }
            else
                hash.Add(B[i], 1);
        }

/*        calculate non-overlapped sum */

        int sum = 0;
        foreach(KeyValuePair<int, int> entry in hash)
        {
            if ((entry.Value) == 1)
                sum += entry.Key;
        }
        return sum;
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        int[] A = { 5, 4, 9, 2, 3 }; 
        int[] B = { 2, 8, 7, 6, 3 };

/*        size of array */

        int n = A.Length;

/*        function call */

        Console.WriteLine(findSum(A, B, n));
    }
}

