/*C# program to find given two array
are equal or not*/

using System;
class GFG {

/*    Returns true if arr1[0..n-1] and
    arr2[0..m-1] contain same elements.*/

    public static bool areEqual(int[] arr1, int[] arr2)
    {
        int n = arr1.Length;
        int m = arr2.Length;

/*        If lengths of array are not
        equal means array are not equal*/

        if (n != m)
            return false;

/*        Sort both arrays*/

        Array.Sort(arr1);
        Array.Sort(arr2);

/*        Linearly compare elements*/

        for (int i = 0; i < n; i++)
            if (arr1[i] != arr2[i])
                return false;

/*        If all elements were same.*/

        return true;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr1 = { 3, 5, 2, 5, 2 };
        int[] arr2 = { 2, 3, 5, 5, 2 };
        if (areEqual(arr1, arr2))
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*C# code to find maximum shortest distance
from endpoints*/

using System;
using System.Collections.Generic;
class GFG
{
static void makePermutation(int []a, int n)
{

/*    Store counts of all elements.*/

    Dictionary<int,
               int> count = new Dictionary<int,
                                           int>();
    for (int i = 0; i < n; i++)
    {
        if(count.ContainsKey(a[i]))
        {
            count[a[i]] = count[a[i]] + 1;
        }
        else
        {
            count.Add(a[i], 1);
        }
    }
}

/*function to find maximum shortest distance*/

static int find_maximum(int []a, int n, int k)
{

/*    stores the shortest distance of every
    element in original array.*/

    Dictionary<int,
               int> b = new Dictionary<int,
                                       int>();
    for (int i = 0; i < n; i++)
    {
        int x = a[i];

/*        shortest distance from ends*/

        int d = Math.Min(1 + i, n - i);
        if (!b.ContainsKey(x))
            b.Add(x, d);
        else
        {

/* if duplicates are found, b[x]
            is replaced with minimum of the
            previous and current position's
            shortest distance*/

            b[x] = Math.Min(d, b[x]);
        }
    }
    int ans = int.MaxValue;
    for (int i = 0; i < n; i++)
    {
        int x = a[i];

/*        similar elements ignore them
        cause we need distinct elements*/

        if (x != k - x && b.ContainsKey(k - x))        
            ans = Math.Min(Math.Max(b[x],
                                    b[k - x]), ans);    
    }
    return ans;
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []a = { 3, 5, 8, 6, 7 };
    int K = 11;
    int n = a.Length;
    Console.WriteLine(find_maximum(a, n, K));
}
}

/*C# program to find
