using System;
class GFG
{

/*Returns true if there
is a pair in arr[0..n-1]
with product equal to x.*/

static bool isProduct(int []arr,
                      int n, int x)
{

/*    Consider all possible
    pairs and check for
    every pair.*/

    for (int i = 0; i < n - 1; i++)
        for (int j = i + 1; j < n; j++)
            if (arr[i] * arr[j] == x)
                return true;
    return false;
}

