/*C# program to find the largest product number*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Function to find greatest number*/

    static int findGreatest(int []arr, int n)
    {

/*        Store occurrences of all
        elements in hash array*/

        Dictionary<int,int> m = new Dictionary<int,int> ();
        for (int i = 0; i < n; i++)
        {
            if (m.ContainsKey(arr[i]))
            {
                var a = m[arr[i]] + 1;
                m.Add(arr[i], a);
            }
            else
            {
                m.Add(arr[i], arr[i]);
            }
        }

/*        m[arr[i]]++;
        Sort the array and traverse
        all elements from end.*/

        Array.Sort(arr);
        for (int i = n - 1; i > 1; i--)
        {

/*            For every element, check if there is another
            element which divides it.*/

            for (int j = 0; j < i &&
                arr[j] <= Math.Sqrt(arr[i]); j++)
            {
                if (arr[i] % arr[j] == 0)
                {
                    int result = arr[i] / arr[j];

/*                    Check if the result value exists in array
                    or not if yes the return arr[i]*/

                    if (result != arr[j] &&
                        m[result] == null|| m[result] > 0)
                    {
                        return arr[i];
                    }

/*                    To handle the case like arr[i] = 4
                    and arr[j] = 2*/

                    else if (result == arr[j] && m[result] > 1)
                    {
                        return arr[i];
                    }
                }
            }
        }
        return -1;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = {17, 2, 1, 15, 30};
        int n = arr.Length;
        Console.WriteLine(findGreatest(arr, n));
    }
}

/*A sorting based solution to find the
minimum number of subsets of a set
such that every subset contains distinct
elements.*/

using System;
public class GfG {

/*    Function to count subsets such that all
    subsets have distinct elements.*/

    public static int subset(int []ar, int n)
    {

/*        Take input and initialize res = 0*/

        int res = 0;

/*        Sort the array*/

        Array.Sort(ar);

/*        Traverse the input array and
        find maximum frequency*/

        for (int i = 0; i < n; i++) {
            int count = 1;

/*            For each number find its
            repetition / frequency*/

            for ( ; i < n - 1; i++) {
                if (ar[i] == ar[i + 1])
                    count++;
                else
                    break;
            }

/*            Update res*/

            res = Math.Max(res, count);
        }
        return res;
    }

/*    Driver function*/

    public static void Main()
    {
        int []arr = { 5, 6, 9, 3, 4, 3, 4 };
        int n = 7;
        Console.WriteLine(subset(arr, n));
    }
}

/*A hashing based solution to find the
minimum number of subsets of a set
such that every subset contains distinct
elements.*/

using System;
using System.Collections.Generic;
class GFG
{

/*Function to count subsets such that all
subsets have distinct elements.*/

static int subset(int []arr, int n)
{

/*    Traverse the input array and
    store frequencies of elements*/

    Dictionary<int,
               int> mp = new Dictionary<int,
                                        int>();
    for (int i = 0 ; i < n; i++)
    {
        if(mp.ContainsKey(arr[i]))
        {
            var val = mp[arr[i]];
            mp.Remove(arr[i]);
            mp.Add(arr[i], val + 1);
        }
        else
        {
            mp.Add(arr[i], 1);
        }
    }

/*    Find the maximum value in map.*/

    int res = 0;
    foreach(KeyValuePair<int, int> entry in mp)
        res = Math.Max(res, entry.Value);
    return res;
}

/*Driver code*/

public static void Main(String[] args)
{
    int []arr = { 5, 6, 9, 3, 4, 3, 4 };
    int n = arr.Length;
    Console.WriteLine(subset(arr, n));
}
}

/*C# Code to Remove minimum number of elements
such that no common element exist in both array*/

using System;
using System.Collections.Generic;
class GFG
{

/*    To find no elements to remove
    so no common element exist*/

    public static int minRemove(int []a, int []b, int n,
                                                int m)
    {

/*        To store count of array element*/

        Dictionary<int,int> countA = new Dictionary<int,int>();
        Dictionary<int,int>countB = new Dictionary<int,int>();

/*        Count elements of a*/

        for (int i = 0; i < n; i++)
        {
            if (countA.ContainsKey(a[i]))
            {
                var v = countA[a[i]];
                countA.Remove(countA[a[i]]);
                countA.Add(a[i], v + 1);
            }
            else countA.Add(a[i], 1);
        }

/*        Count elements of b*/

        for (int i = 0; i < m; i++)
        {
            if (countB.ContainsKey(b[i]))
            {
                var v = countB[b[i]];
                countB.Remove(countB[b[i]]);
                countB.Add(b[i], v + 1);
            }
            else countB.Add(b[i], 1);
        }

/*        Traverse through all common element, and
        pick minimum occurrence from two arrays*/

        int res = 0;
        foreach (int x in countA.Keys)
            if(countB.ContainsKey(x))
                res += Math.Min(countB[x],
                            countA[x]);

/*        To return count of minimum elements*/

        return res;
    }

/* Driver code */

    public static void Main(String[] args)
    {
            int []a = { 1, 2, 3, 4 };
            int []b = { 2, 3, 4, 5, 8 };
            int n = a.Length;
            int m = b.Length;
            Console.WriteLine(minRemove(a, b, n, m));
    }
}

