using System;
using System.Collections.Generic;
class GFG
{

/*Function to print common Strings with minimum index sum*/

static void find(List<String> list1, List<String> list2)
{

/*resultant list*/

List<String> res = new List<String>(); 
    int max_possible_sum = list1.Count + list2.Count - 2;

/*    iterating over sum in ascending order*/

    for (int sum = 0; sum <= max_possible_sum ; sum++)
    {

/*        iterating over one list and check index
        (Corresponding to given sum) in other list*/

        for (int i = 0; i <= sum; i++)

/*            put common Strings in resultant list*/

            if (i < list1.Count &&
                (sum - i) < list2.Count &&
                list1[i] == list2[sum - i])
                res.Add(list1[i]);

/*        if common String found then break as we are
        considering index sums in increasing order.*/

        if (res.Count > 0)
            break;
    }

/*    print the resultant list*/

    for (int i = 0; i < res.Count; i++)
        Console.Write(res[i]+" ");
}

/*Driver code*/

public static void Main(String[] args)
{

/*    Creating list1*/

    List<String> list1 = new List<String>();
    list1.Add("GeeksforGeeks");
    list1.Add("Udemy");
    list1.Add("Coursera");
    list1.Add("edX");

/*    Creating list2*/

    List<String> list2= new List<String>();
    list2.Add("Codecademy");
    list2.Add("Khan Academy");
    list2.Add("GeeksforGeeks");
    find(list1, list2);
}
}

/*Hashing based C# program to find common elements
with minimum index sum.*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Function to print common Strings with minimum index sum*/

    static void find(List<String> list1, List<String> list2)
    {

/*        mapping Strings to their indices*/

        Dictionary<String, int> map = new Dictionary<String, int>();
        for (int i = 0; i < list1.Count; i++)
            map.Add(list1[i], i);

/*resultant list*/

List<String> res = new List<String>(); 
        int minsum = int.MaxValue;
        for (int j = 0; j < list2.Count; j++)
        {
            if (map.ContainsKey(list2[j]))
            {

/*                If current sum is smaller than minsum*/

                int sum = j + map[list2[j]];
                if (sum < minsum)
                {
                    minsum = sum;
                    res.Clear();
                    res.Add(list2[j]);
                }

/*                if index sum is same then put this
                String in resultant list as well*/

                else if (sum == minsum)
                    res.Add(list2[j]);
            }
        }

/*        Print result*/

        for (int i = 0; i < res.Count; i++)
            Console.Write(res[i] + " ");
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/*        Creating list1*/

        List<String> list1 = new List<String>();
        list1.Add("GeeksforGeeks");
        list1.Add("Udemy");
        list1.Add("Coursera");
        list1.Add("edX");

/*        Creating list2*/

        List<String> list2 = new List<String>();
        list2.Add("Codecademy");
        list2.Add("Khan Academy");
        list2.Add("GeeksforGeeks");
        find(list1, list2);
    }
}

/*C# program to make a permutation of numbers
from 1 to n using minimum changes.*/

using System;
using System.Collections.Generic;
class GFG
{
static void makePermutation(int []a, int n)
{

/*    Store counts of all elements.*/

    Dictionary<int,
               int> count = new Dictionary<int,
                                           int>();
    for (int i = 0; i < n; i++)
    {
        if(count.ContainsKey(a[i]))
        {
            count[a[i]] = count[a[i]] + 1;
        }
        else
        {
            count.Add(a[i], 1);
        }
    }
    int next_missing = 1;
    for (int i = 0; i < n; i++)
    {
        if (count.ContainsKey(a[i]) &&
            count[a[i]] != 1 ||
            a[i] > n || a[i] < 1)
        {
            count[a[i]] = count[a[i]] - 1;

/*            Find next missing element to put
            in place of current element.*/

            while (count.ContainsKey(next_missing))
                next_missing++;

/*            Replace with next missing and insert
            the missing element in hash.*/

            a[i] = next_missing;
            count.Add(next_missing, 1);
        }
    }
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []A = { 2, 2, 3, 3 };
    int n = A.Length;
    makePermutation(A, n);
    for (int i = 0; i < n; i++)
        Console.Write(A[i] + " ");
}
}

/*C# implementation of simple
method to find count of
pairs with given sum.*/

using System;
class GFG {

/*    Prints number of pairs in arr[0..n-1] with sum equal
    to 'sum'*/
    public static void getPairsCount(int[] arr, int sum)
    {

/*Initialize result*/

int count = 0;

/*        Consider all possible pairs
        and check their sums*/

        for (int i = 0; i < arr.Length; i++)
            for (int j = i + 1; j < arr.Length; j++)
                if ((arr[i] + arr[j]) == sum)
                    count++;
        Console.WriteLine("Count of pairs is " + count);
    }

/*    Driver Code*/

    static public void Main()
    {
        int[] arr = { 1, 5, 7, -1, 5 };
        int sum = 6;
        getPairsCount(arr, sum);
    }
}

/*C# implementation of simple method to
find count of pairs with given sum*/

using System;
using System.Collections.Generic;
class GFG {
    public static int[] arr = new int[] { 1, 5, 7, -1, 5 };

/*    Returns number of pairs in arr[0..n-1]
    with sum equal to 'sum'*/

    public static int getPairsCount(int n, int sum)
    {
        Dictionary<int, int> hm
            = new Dictionary<int, int>();

/*        Store counts of all elements
        in map hm*/

        for (int i = 0; i < n; i++) {

/*            initializing value to 0,
            if key not found*/

            if (!hm.ContainsKey(arr[i])) {
                hm[arr[i]] = 0;
            }
            hm[arr[i]] = hm[arr[i]] + 1;
        }
        int twice_count = 0;

/*        iterate through each element and
        increment the count (Notice that
        every pair is counted twice)*/

        for (int i = 0; i < n; i++) {
            if (hm[sum - arr[i]] != 0) {
                twice_count += hm[sum - arr[i]];
            }

/*            if (arr[i], arr[i]) pair satisfies
            the condition, then we need to ensure
            that the count is decreased by one
            such that the (arr[i], arr[i])
            pair is not considered*/

            if (sum - arr[i] == arr[i]) {
                twice_count--;
            }
        }

/*        return the half of twice_count*/

        return twice_count / 2;
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        int sum = 6;
        Console.WriteLine("Count of pairs is "
                          + getPairsCount(arr.Length, sum));
    }
}

