/*C# implementation to count pairs from both
sorted arrays whose sum is equal to a given
value*/

using System;
class GFG {

/*    function to search 'value' in the given
    array 'arr[]' it uses binary search
    technique as 'arr[]' is sorted*/

    static bool isPresent(int []arr, int low,
                         int high, int value)
    {
        while (low <= high)
        {
            int mid = (low + high) / 2;

/*            value found*/

            if (arr[mid] == value)
                return true;    
            else if (arr[mid] > value)
                high = mid - 1;
            else
                low = mid + 1;
        }

/*        value not found*/

        return false;
    }

/*    function to count all pairs
    from both the sorted arrays
    whose sum is equal to a given
    value*/

    static int countPairs(int []arr1, int []arr2,
                             int m, int n, int x)
    {
        int count = 0;
        for (int i = 0; i < m; i++)
        {

/*            for each arr1[i]*/

            int value = x - arr1[i];

/*            check if the 'value'
            is present in 'arr2[]'*/

            if (isPresent(arr2, 0, n - 1, value))
                count++;
        }

/*        required count of pairs*/

        return count;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int []arr1 = {1, 3, 5, 7};
        int []arr2 = {2, 3, 5, 8};
        int m = arr1.Length;
        int n = arr2.Length;
        int x = 10;
        Console.WriteLine("Count = "
            + countPairs(arr1, arr2, m, n, x));
    }
}

/*C# implementation to count
pairs from both sorted arrays
whose sum is equal to a given
value*/

using System;
using System.Collections.Generic;
class GFG
{

/*function to count all pairs
from both the sorted arrays
whose sum is equal to a given
value*/

static int countPairs(int []arr1, int []arr2,
            int m, int n, int x)
{
    int count = 0;
    HashSet<int> us = new HashSet<int>();

/*    insert all the elements
    of 1st array in the hash
    table(unordered_set 'us')*/

    for (int i = 0; i < m; i++)
        us.Add(arr1[i]);

/*    for each element of 'arr2[]*/

    for (int j = 0; j < n; j++)

/*        find (x - arr2[j]) in 'us'*/

        if(us.Contains(x - arr2[j]))
            count++;

/*    required count of pairs*/

    return count;
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []arr1 = {1, 3, 5, 7};
    int []arr2 = {2, 3, 5, 8};
    int m = arr1.Length;
    int n = arr2.Length;
    int x = 10;
    Console.Write("Count = "
        + countPairs(arr1, arr2, m, n, x));
}
}

/*C# implementation to count
pairs from both sorted arrays
whose sum is equal to a given
value*/

using System;
class GFG {

/*    function to count all pairs
    from both the sorted arrays
    whose sum is equal to a given
    value*/

    static int countPairs(int []arr1,
        int []arr2, int m, int n, int x)
    {
        int count = 0;
        int l = 0, r = n - 1;

/*        traverse 'arr1[]' from
        left to right
        traverse 'arr2[]' from
        right to left*/

        while (l < m && r >= 0)
        {

/*            if this sum is equal
            to 'x', then increment 'l',
            decrement 'r' and
            increment 'count'*/

            if ((arr1[l] + arr2[r]) == x)
            {
                l++; r--;
                count++;        
            }

/*            if this sum is less
            than x, then increment l*/

            else if ((arr1[l] + arr2[r]) < x)
                l++;

/*            else decrement 'r'*/

            else
                r--;
        }

/*        required count of pairs*/

        return count;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int []arr1 = {1, 3, 5, 7};
        int []arr2 = {2, 3, 5, 8};
        int m = arr1.Length;
        int n = arr2.Length;
        int x = 10;
        Console.WriteLine( "Count = "
        + countPairs(arr1, arr2, m, n, x));
    }
}

/*C# implementation to count pairs from both linked
lists whose sum is equal to a given value
Note : here we use using System.Collections.Generic for
linked list implementation*/

using System;
using System.Collections.Generic;
class GFG
{

/*    method to count all pairs from both the linked lists
    whose sum is equal to a given value*/

    static int countPairs(List<int> head1, List<int> head2, int x)
    {
        int count = 0;

/*        traverse the 1st linked list*/

        foreach(int itr1 in head1)
        {

/*            for each node of 1st list
            traverse the 2nd list*/

            int t = itr1;
            foreach(int itr2 in head2)
            {

/*                if sum of pair is equal to 'x'
                increment count*/

                if ((t + itr2) == x)
                    count++;
            }
        }

/*        required count of pairs    */

        return count;
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        int []arr1 = {3, 1, 5, 7};
        int []arr2 = {8, 2, 5, 3};
        List<int> head1 = new List<int>(arr1);
        List<int> head2 = new List<int>(arr2);
        int x = 10;
    Console.WriteLine("Count = " + countPairs(head1, head2, x));
    }
}

/*C# implementation to count quadruples from
four sorted arrays whose sum is equal to a
given value x*/

using System;
class GFG
{

/*    find the 'value' in the given array 'arr[]'
    binary search technique is applied*/

    static bool isPresent(int[] arr, int low,
                            int high, int value)
    {
        while (low <= high)
        {
            int mid = (low + high) / 2;

/*            'value' found*/

            if (arr[mid] == value)
                return true;
            else if (arr[mid] > value)
                high = mid - 1;
            else
                low = mid + 1;
        }

/*        'value' not found*/

        return false;
    }

/*    function to count all quadruples from four
    sorted arrays whose sum is equal to a given value x*/

    static int countQuadruples(int[] arr1, int[] arr2,
                            int[] arr3, int[] arr4,
                            int n, int x)
    {
        int count = 0;

/*        generate all triplets from the 1st three arrays*/

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                for (int k = 0; k < n; k++)
                {

/*                    calculate the sum of elements in
                    the triplet so generated*/

                    int T = arr1[i] + arr2[j] + arr3[k];

/*                    check if 'x-T' is present in 4th
                    array or not*/

                    if (isPresent(arr4, 0, n-1, x - T))

/*                        increment count*/

                        count++;
                }

/*        required count of quadruples*/

        return count;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/*        four sorted arrays each of size 'n'*/

        int[] arr1 = { 1, 4, 5, 6 };
        int[] arr2 = { 2, 3, 7, 8 };
        int[] arr3 = { 1, 4, 6, 10 };
        int[] arr4 = { 2, 4, 7, 8 };
        int n = 4;
        int x = 30;
        Console.WriteLine( "Count = "
        + countQuadruples(arr1, arr2, arr3, arr4, n, x));
    }
}

/*C# implementation to count quadruples from
four sorted arrays whose sum is equal to a
given value x*/

 using System;
public class GFG {

/*    count pairs from the two sorted array whose sum
    is equal to the given 'value'*/

    static int countPairs(int []arr1, int []arr2, int n, int value)
    {
        int count = 0;
        int l = 0, r = n - 1;

/*        traverse 'arr1[]' from left to right
        traverse 'arr2[]' from right to left*/

        while (l < n & r >= 0) {
            int sum = arr1[l] + arr2[r];

/*            if the 'sum' is equal to 'value', then
            increment 'l', decrement 'r' and
            increment 'count'*/

            if (sum == value) {
                l++; r--;
                count++;
            }

/*            if the 'sum' is greater than 'value', then
            decrement r*/

            else if (sum > value)
                r--;

/*            else increment l*/

            else
                l++;
        }

/*        required count of pairs*/

        return count;
    }

/*    function to count all quadruples from four sorted arrays
    whose sum is equal to a given value x*/

    static int countQuadruples(int []arr1, int []arr2, int []arr3,
                        int []arr4, int n, int x)
    {
        int count = 0;

/*        generate all pairs from arr1[] and arr2[]*/

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {

/*                calculate the sum of elements in
                the pair so generated*/

                int p_sum = arr1[i] + arr2[j];

/*                count pairs in the 3rd and 4th array
                having value 'x-p_sum' and then
                accumulate it to 'count'*/

                count += countPairs(arr3, arr4, n, x - p_sum);
            }

/*        required count of quadruples*/

        return count;
    }

/*    Driver program to test above*/

    static public void Main() {

/*        four sorted arrays each of size 'n'*/

        int []arr1 = {1, 4, 5, 6};
        int []arr2 = {2, 3, 7, 8};
        int []arr3 = {1, 4, 6, 10};
        int []arr4 = {2, 4, 7, 8};
        int n = arr1.Length;
        int x = 30;
        Console.Write("Count = "
                + countQuadruples(arr1, arr2, arr3, arr4, n, x));
    }
}

/*C# implementation to count quadruples from
four sorted arrays whose sum is equal to a
given value x*/

using System;
using System.Collections.Generic;
class GFG
{

/*function to count all quadruples from four sorted
arrays whose sum is equal to a given value x*/

static int countQuadruples(int []arr1, int []arr2, int []arr3,
                                    int []arr4, int n, int x)
{
    int count = 0;

/*    unordered_map 'um' implemented as hash table
    for <sum, frequency> tuples*/

    Dictionary<int,int> m = new Dictionary<int,int>();

/*    count frequency of each sum obtained from the
    pairs of arr1[] and arr2[] and store them in 'um'*/

    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if(m.ContainsKey(arr1[i] + arr2[j])){
                var val = m[arr1[i] + arr2[j]];
                m.Remove(arr1[i] + arr2[j]);
                m.Add((arr1[i] + arr2[j]), val+1);
            }
            else
                m.Add((arr1[i] + arr2[j]), 1);

/*    generate pair from arr3[] and arr4[]*/

    for (int k = 0; k < n; k++)
        for (int l = 0; l < n; l++)
        {

/*            calculate the sum of elements in
            the pair so generated*/

            int p_sum = arr3[k] + arr4[l];

/*            if 'x-p_sum' is present in 'um' then
            add frequency of 'x-p_sum' to 'count'*/

            if (m.ContainsKey(x - p_sum))
                count += m[x - p_sum];
        }

/*    required count of quadruples*/

    return count;
}

/*Driver code*/

public static void Main(String[] args)
{

/*    four sorted arrays each of size 'n'*/

    int []arr1 = { 1, 4, 5, 6 };
    int []arr2 = { 2, 3, 7, 8 };
    int []arr3 = { 1, 4, 6, 10 };
    int []arr4 = { 2, 4, 7, 8 };
    int n = arr1.Length;
    int x = 30;
    Console.WriteLine("Count = "
        + countQuadruples(arr1, arr2, arr3, arr4, n, x));
}
}

