/*C# program to find number of subarrays
with sum exactly equal to k.*/

using System;
using System.Collections.Generic;
class GFG {

/*    Function to find number of subarrays
    with sum exactly equal to k.*/

    public static int findSubarraySum(int[] arr,
                                      int n, int sum)
    {

/*        HashMap to store number of subarrays
        starting from index zero having
        particular value of sum.*/

        Dictionary<int, int> prevSum = new Dictionary<int, int>();
        int res = 0;

/*        Sum of elements so far*/

        int currsum = 0;
        for (int i = 0; i < n; i++) {

/*            Add current element to sum so far.*/

            currsum += arr[i];

/*            If currsum is equal to desired sum,
            then a new subarray is found. So
            increase count of subarrays.*/

            if (currsum == sum)
                res++;

/*            currsum exceeds given sum by currsum
            - sum. Find number of subarrays having
            this sum and exclude those subarrays
            from currsum by increasing count by
            same amount.*/

            if (prevSum.ContainsKey(currsum - sum))
                res += prevSum[currsum - sum];

/*            Add currsum value to count of
            different values of sum.*/

            if (!prevSum.ContainsKey(currsum))
                prevSum.Add(currsum, 1);
            else {
                int count = prevSum[currsum];
                prevSum[currsum] = count + 1;
            }
        }
        return res;
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] arr = { 10, 2, -2, -20, 10 };
        int sum = -10;
        int n = arr.Length;
        Console.Write(findSubarraySum(arr, n, sum));
    }
}

/*C# program to count pairs
whose product exist in array*/

using System;
class GFG
{

/*Returns count of pairs
whose product exists in arr[]*/

public static int countPairs(int[] arr,
                             int n)
{
    int result = 0;
    for (int i = 0; i < n ; i++)
    {
        for (int j = i + 1 ; j < n ; j++)
        {
            int product = arr[i] * arr[j];

/*            find product in an array*/

            for (int k = 0; k < n; k++)
            {

/*                if product found
                increment counter*/

                if (arr[k] == product)
                {
                    result++;
                    break;
                }
            }
        }
    }

/*    return Count of all pair
    whose product exist in array*/

    return result;
}

/*Driver Code*/

public static void Main(string[] args)
{
    int[] arr = new int[] {6, 2, 4, 12, 5, 3};
    int n = arr.Length;
    Console.WriteLine(countPairs(arr, n));
}
}

/*A hashing based C# program to count pairs whose product
exists in arr[]*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Returns count of pairs whose product exists in arr[]*/

    static int countPairs(int []arr, int n)
    {
        int result = 0;

/*        Create an empty hash-set that store all array element*/

        HashSet<int> Hash = new HashSet<int>();

/*        Insert all array element into set*/

        for (int i = 0; i < n; i++)
        {
            Hash.Add(arr[i]);
        }

/*        Generate all pairs and check is exist in 'Hash' or not*/

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int product = arr[i] * arr[j];

/*                if product exists in set then we increment
                count by 1*/

                if (Hash.Contains(product))
                {
                    result++;
                }
            }
        }

/*        return count of pairs whose product exist in array*/

        return result;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = {6, 2, 4, 12, 5, 3};
        int n = arr.Length;
        Console.WriteLine(countPairs(arr, n));
    }
}

