/*C# program to find all pairs
such that a % b = k.*/

using System;
using System.Collections.Generic;
class GFG
{

/*Utility method to find the divisors
of n and store in vector v[]*/

public static List<int> findDivisors(int n)
{
    List<int> v = new List<int>();

/*    Vector is used to store
    the divisors*/

    for (int i = 1;
             i <= Math.Sqrt(n); i++)
    {
        if (n % i == 0)
        {

/*            If n is a square number,
            push only one occurrence*/

            if (n / i == i)
            {
                v.Add(i);
            }
            else
            {
                v.Add(i);
                v.Add(n / i);
            }
        }
    }
    return v;
}

/*method to find pairs such
that (a%b = k)*/

public static bool printPairs(int[] arr,
                              int n, int k)
{

/*    Store all the elements in the
    map to use map as hash for
    finding elements in O(1) time.*/

    Dictionary<int,
               bool> occ = new Dictionary<int,
                                          bool>();
    for (int i = 0; i < n; i++)
    {
        occ[arr[i]] = true;
    }
    bool isPairFound = false;
    for (int i = 0; i < n; i++)
    {

/*        Print all the pairs with (a, b) as
        (k, numbers greater than k) as
        k % (num (> k)) = k i.e. 2%4 = 2*/

        if (occ[k] && k < arr[i])
        {
            Console.Write("(" + k + ", " +
                           arr[i] + ") ");
            isPairFound = true;
        }

/*        Now check for the current element
        as 'a' how many b exists such that
        a%b = k*/

        if (arr[i] >= k)
        {

/*            find all the divisors of (arr[i]-k)*/

            List<int> v = findDivisors(arr[i] - k);

/*            Check for each divisor i.e.
            arr[i] % b = k or not, if
            yes then print that pair.*/

            for (int j = 0; j < v.Count; j++)
            {
                if (arr[i] % v[j] == k &&
                    arr[i] != v[j] && occ[v[j]])
                {
                    Console.Write("(" + arr[i] +
                                  ", " + v[j] + ") ");
                    isPairFound = true;
                }
            }

/*            Clear vector*/

            v.Clear();
        }
    }
    return isPairFound;
}

/*Driver Code*/

public static void Main(string[] args)
{
    int[] arr = new int[] {3, 1, 2, 5, 4};
    int k = 2;
    if (printPairs(arr, arr.Length, k) == false)
    {
        Console.WriteLine("No such pair exists");
    }
}
}

/*C# Program to convert an Array
to reduced form*/

using System;
using System.Collections.Generic;
using System.Linq;
class GFG
{
    public static void convert(int []arr, int n)
    {

/*        Create a temp array and copy contents
        of []arr to temp*/

        int []temp = new int[arr.Length];
        Array.Copy(arr, 0, temp, 0, arr.Length);

/*        Sort temp array*/

        Array.Sort(temp);

/*        Create a hash table.*/

        Dictionary<int, int> umap =
            new Dictionary<int, int>();

/*        One by one insert elements of sorted
        []temp and assign them values from 0
        to n - 1*/

        int val = 0;
        for (int i = 0; i < n; i++)
            if(umap.ContainsKey(temp[i]))
                umap[temp[i]] = val++;
            else
                umap.Add(temp[i], val++);

/*        Convert array by taking positions from
        umap*/

        for (int i = 0; i < n; i++)
            arr[i] = umap[arr[i]];
    }
    public static void printArr(int []arr, int n)
    {
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = {10, 20, 15, 12, 11, 50};
        int n = arr.Length;
        Console.WriteLine("Given Array is ");
        printArr(arr, n);
        convert(arr , n);
        Console.WriteLine("\n\nConverted Array is ");
        printArr(arr, n);
    }
}

/*C# program to output the maximum
occurring character in a string*/

using System;
class GFG
{
    static int ASCII_SIZE = 256;
    static char getMaxOccuringChar(String str)
    {

/*        Create array to keep the count of
        individual characters and
        initialize the array as 0*/

        int []count = new int[ASCII_SIZE];

/*        Construct character count array
        from the input string.*/

        int len = str.Length;
        for (int i = 0; i < len; i++)
            count[str[i]]++;

/*Initialize max count*/

int max = -1;

/*Initialize result*/

char result = ' ';

/*        Traversing through the string and
        maintaining the count of each character*/

        for (int i = 0; i < len; i++) {
            if (max < count[str[i]]) {
                max = count[str[i]];
                result = str[i];
            }
        }
        return result;
    }

/*    Driver Method*/

    public static void Main()
    {
        String str = "sample string";
        Console.Write("Max occurring character is " +
                            getMaxOccuringChar(str));
    }
}

/*C# program to print all words that
have the same unique character set*/

using System;
using System.Collections.Generic;
class GFG{
static readonly int MAX_CHAR = 26;

/*Generates a key from given string. The
key contains all unique characters of
given string in sorted order consisting
of only distinct elements.*/

static String getKey(String str)
{
    bool[] visited = new bool[MAX_CHAR];

/*    Store all unique characters of current
    word in key*/

    for(int j = 0; j < str.Length; j++)
        visited[str[j] - 'a'] = true;
    String key = "";
    for(int j = 0; j < MAX_CHAR; j++)
        if (visited[j])
            key = key + (char)('a' + j);
    return key;
}

/*Print all words together with same character sets.*/

static void wordsWithSameCharSet(String []words, int n)
{

/*    Stores indexes of all words that have same
    set of unique characters.
    unordered_map <string, vector <int> > Hash;*/

    Dictionary<String,
               List<int>> Hash = new Dictionary<String,
                                                List<int>>();

/*    Traverse all words*/

    for (int i = 0; i < n; i++)
    {
        String key = getKey(words[i]);

/*        If the key is already in the map
        then get its corresponding value
        and update the list and put it
        in the map*/

        if (Hash.ContainsKey(key))
        {
            List<int> get_al = Hash[key];
            get_al.Add(i);
            Hash[key]= get_al;
        }

/*        If key is not present in the map
        then create a new list and add
        both key and the list*/

        else
        {
            List<int> new_al = new List<int>();
            new_al.Add(i);
            Hash.Add(key, new_al);
        }
    }

/*    Print all words that have the
    same unique character set*/

    foreach(KeyValuePair<String, List<int>> it in Hash)
    {
        List<int> get =it.Value;
        foreach(int v in get)
            Console.Write( words[v] + ", ");
        Console.WriteLine();
    }
}

/*Driver code*/

public static void Main(String []args)
{
    String []words = { "may", "student", "students",
                       "dog", "studentssess", "god",
                       "cat", "act", "tab",
                       "bat", "flow", "wolf",
                       "lambs", "amy", "yam",
                       "balms", "looped", "poodle"};
    int n = words.Length;
    wordsWithSameCharSet(words, n);
}
}

/*C# program to find out the second
most repeated word*/

using System;
using System.Collections.Generic;
class GFG 
{

/*    Method to find the word*/

    static String secMostRepeated(List<String> seq)
    {

/*        Store all the words with its occurrence*/

        Dictionary<String, int> occ = 
        new Dictionary<String, int>();
        for (int i = 0; i < seq.Count; i++)
            if(occ.ContainsKey(seq[i]))
                occ[seq[i]] = occ[seq[i]] + 1;
            else
                occ.Add(seq[i], 1);

/*        find the second largest occurrence*/

        int first_max = int.MinValue, 
            sec_max = int.MinValue;
        foreach(KeyValuePair<String, int> entry in occ)
        {
            int v = entry.Value;
            if( v > first_max) 
            {
                sec_max = first_max;
                first_max = v;
            }
            else if (v > sec_max && 
                    v != first_max)
                sec_max = v;
        }

/*        Return string with occurrence equals
        to sec_max*/

        foreach(KeyValuePair<String, int> entry in occ)
        {
            int v = entry.Value;
            if (v == sec_max)
                return entry.Key;
        }
        return null;
    }

/*    Driver method*/

    public static void Main(String[] args) 
    {
        String []arr = { "ccc", "aaa", "ccc",
                        "ddd", "aaa", "aaa" };
        List<String> seq = new List<String>(arr);
        Console.WriteLine(secMostRepeated(seq));
    } 
}

/*C# program to find the smallest element
with frequency exactly k.*/

using System;
using System.Linq;
using System.Collections.Generic; 
class GFG 
{
    public static int smallestKFreq(int []a, int n, int k)
    {
        Dictionary<int,int> m = new Dictionary<int,int>();

/*        Map is used to store the count of
        elements present in the array*/

        for (int i = 0; i < n; i ++)
            if (m.ContainsKey(a[i]))
            {
                var v = m[a[i]];
                m.Remove(a[i]);
                m.Add(a[i],v + 1);
            }
        else m.Add(a[i], 1);

/*        Traverse the map and find minimum
        element with frequency k.*/

        int res = int.MaxValue;
        HashSet<int> s = new HashSet<int>(m.Keys.ToArray());
        foreach (int temp in s)
            if (m[temp] == k)
            res = Math.Min(res, temp);
        return (res != int.MaxValue)? res : -1;
    }

/* Driver code */

    public static void Main(String[] args) 
    {
        int []arr = { 2, 2, 1, 3, 1 };
        int k = 2;
        Console.WriteLine(smallestKFreq(arr, arr.Length, k));
    }
}

/* C# program to find first repeating element in arr[] */
using System;
using System.Collections.Generic;

public class GFG
{

/*    This function prints the first repeating element in arr[]*/

    public static void printFirstRepeating(int[] arr)
    {

/*        Initialize index of first repeating element*/

        int min = -1;

/*        Creates an empty hashset*/

        HashSet<int> set = new HashSet<int>();

/*        Traverse the input array from right to left*/

        for (int i = arr.Length - 1; i >= 0; i--)
        {

/*            If element is already in hash set, update min*/

            if (set.Contains(arr[i]))
            {
                min = i;
            }

/*Else add element to hash set*/

else 
            {
                set.Add(arr[i]);
            }
        }

/*        Print the result*/

        if (min != -1)
        {
          Console.WriteLine("The first repeating element is " + arr[min]);
        }
        else
        {
          Console.WriteLine("There are no repeating elements");
        }
    }

/*    Driver method to test above method*/

    public static void Main(string[] args)
    {
        int[] arr = new int[] {10, 5, 3, 4, 3, 5, 6};
        printFirstRepeating(arr);
    }
}

/* C# program to find first
repeating element in arr[] */

using System;
class GFG
{

/*    This function prints the
    first repeating element in arr[]*/

    static void printFirstRepeating(int[] arr, int n)
    {

/*        This will set k=1, if any
        repeating element found*/

        int k = 0;

/*        max = maximum from (all elements & n)*/

        int max = n;
        for (int i = 0; i < n; i++)
            if (max < arr[i])
                max = arr[i];

/*        Array a is for storing
        1st time occurence of element
        initialized by 0*/

        int[] a = new int[max + 1];

/*        Store 1 in array b
        if element is duplicate
        initialized by 0*/

        int[] b = new int[max + 1];
        for (int i = 0; i < n; i++)
        {

/*            Duplicate element found*/

            if (a[arr[i]] != 0)
            {
                b[arr[i]] = 1;
                k = 1;
                continue;
            }
            else

/*                storing 1st occurence of arr[i]*/

                a[arr[i]] = i;
        }
        if (k == 0)
            Console.WriteLine("No repeating element found");
        else
        {
            int min = max + 1;

/*            trace array a & find repeating element
            with min index*/

            for (int i = 0; i < max + 1; i++)
                if ((a[i] != 0) && min > a[i] && (b[i] != 0))
                    min = a[i];
            Console.Write(arr[min]);
        }
        Console.WriteLine();
    }

/*  Driver code*/

  static void Main()
  {
    int[] arr = { 10, 5, 3, 4, 3, 5, 6 };
    int n = arr.Length;
    printFirstRepeating(arr, n);
  }
}

/*C# Find the sum of all non-repeated
elements in an array*/

using System;
class GFG
{

/*    Find the sum of all non-repeated elements
    in an array*/

    static int findSum(int []arr, int n)
    {

/*        sort all elements of array*/

        Array.Sort(arr);
        int sum = arr[0];
        for (int i = 0; i < n - 1; i++)
        {
            if (arr[i] != arr[i + 1])
            {
                sum = sum + arr[i + 1];
            }
        }
        return sum;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = {1, 2, 3, 1, 1, 4, 5, 6};
        int n = arr.Length;
        Console.WriteLine(findSum(arr, n));
    }
}

/*C# Find the sum of all non- repeated
elements in an array*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Find the sum of all non-repeated elements
    in an array*/

    static int findSum(int []arr, int n)
    {
        int sum = 0;

/*        Hash to store all element of array*/

        HashSet<int> s = new HashSet<int>();
        for (int i = 0; i < n; i++)
        {
            if (!s.Contains(arr[i]))
            {
                sum += arr[i];
                s.Add(arr[i]);
            }
        }
        return sum;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = {1, 2, 3, 1, 1, 4, 5, 6};
        int n = arr.Length;
        Console.WriteLine(findSum(arr, n));
    }
}

/*C# program to find first non-
repeating element.*/

using System;
class GFG {
    static int firstNonRepeating(int[] arr, int n)
    {
        for (int i = 0; i < n; i++) {
            int j;
            for (j = 0; j < n; j++)
                if (i != j && arr[i] == arr[j])
                    break;
            if (j == n)
                return arr[i];
        }
        return -1;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 9, 4, 9, 6, 7, 4 };
        int n = arr.Length;
        Console.Write(firstNonRepeating(arr, n));
    }
}

/*Efficient C# program to find first non-
repeating element.*/

using System;
using System.Collections.Generic;
class GFG {
    static int firstNonRepeating(int[] arr, int n)
    {

/*        Insert all array elements in hash
        table*/

        Dictionary<int, int> m = new Dictionary<int, int>();
        for (int i = 0; i < n; i++) {
            if (m.ContainsKey(arr[i])) {
                var val = m[arr[i]];
                m.Remove(arr[i]);
                m.Add(arr[i], val + 1);
            }
            else {
                m.Add(arr[i], 1);
            }
        }

/*        Traverse array again and return
        first element with count 1.*/

        for (int i = 0; i < n; i++)
            if (m[arr[i]] == 1)
                return arr[i];
        return -1;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int[] arr = { 9, 4, 9, 6, 7, 4 };
        int n = arr.Length;
        Console.WriteLine(firstNonRepeating(arr, n));
    }
}

