        int n = arr.Length;
        printPairs(arr, n);
    }
}

/*C# program to check if arr[0..n-1]
can be divided in pairs such that
every pair is divisible by k.*/

using System.Collections.Generic;
using System;
class GFG {

/*    Returns true if arr[0..n-1] can be
    divided into pairs with sum
    divisible by k.*/

    static bool canPairs(int[] ar, int k)
    {

/*        An odd length array cannot
        be divided into pairs*/

        if (ar.Length % 2 == 1)
            return false;

/*        Create a frequency array to count
        occurrences of all remainders when
        divided by k.*/

        Dictionary<Double, int> hm
            = new Dictionary<Double, int>();

/*        Count occurrences of all remainders*/

        for (int i = 0; i < ar.Length; i++) {
            int rem = ((ar[i] % k) + k) % k;
            if (!hm.ContainsKey(rem)) {
                hm[rem] = 0;
            }
            hm[rem]++;
        }

/*        Traverse input array and use freq[]
        to decide if given array can be
        divided in pairs*/

        for (int i = 0; i < ar.Length; i++) {

/*            Remainder of current element*/

            int rem = ((ar[i] % k) + k) % k;

/*            If remainder with current element
            divides k into two halves.*/

            if (2 * rem == k) {

/*                Then there must be even occurrences
                of such remainder*/

                if (hm[rem] % 2 == 1)
                    return false;
            }

/*            If remainder is 0, then there
            must be two elements with 0
            remainder*/

            else if (rem == 0) {

/*                Then there must be even occurrences
                of such remainder*/

                if (hm[rem] % 2 == 1)
                    return false;
            }

/*            Else number of occurrences of remainder
            must be equal to number of occurrences of
            k - remainder*/

            else {
                if (hm[k - rem] != hm[rem])
                    return false;
            }
        }
        return true;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 92, 75, 65, 48, 45, 35 };
        int k = 10;

/*        Function call*/

        bool ans = canPairs(arr, k);
        if (ans)
            Console.WriteLine("True");
        else
            Console.WriteLine("False");
    }
}

/*C# Program to find the subarray with
no pair sum divisible by K*/

using System;
using System.Collections;
class GFG {

/*    function to find the subarray with
    no pair sum divisible by k*/

    static void subarrayDivisibleByK(int []arr, 
                                int n, int k)
    {

/*        hash table to store the remainders
        obtained on dividing by K*/

        int []mp = new int[1000];

/*        s : starting index of the
        current subarray, e : ending
        index of the current subarray, maxs :
        starting index of the maximum
        size subarray so far, maxe : ending
        index of the maximum size subarray
        so far*/

        int s = 0, e = 0, maxs = 0, maxe = 0;

/*        insert the first element in the set*/

        mp[arr[0] % k]++;
        for (int i = 1; i < n; i++)
        {
            int mod = arr[i] % k;

/*            Removing starting elements of current
            subarray while there is an element in
            set which makes a pair with mod[i] such
            that the pair sum is divisible.*/

            while (mp[k - mod] != 0 ||
                (mod == 0 && mp[mod] != 0))
            {
                mp[arr[s] % k]--;
                s++;
            }

/*            include the current element in
            the current subarray the ending
            index of the current subarray
            increments by one*/

            mp[mod]++;
            e++;

/*            compare the size of the current
            subarray with the maximum size so
            far*/

            if ((e - s) > (maxe - maxs))
            {
                maxe = e;
                maxs = s;
            }
        }
        Console.Write("The maximum size is " + 
                           (maxe - maxs + 1) + 
            " and the subarray is as follows\n");
        for (int i = maxs; i <= maxe; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver Code*/

    public static void Main()
    {
        int k = 3;
        int []arr = {5, 10, 15, 20, 25};
        int n = arr.Length;
        subarrayDivisibleByK(arr, n, k);
    }
}

/*C# program to find three element
from different three arrays such
that a + b + c is equal to
given sum*/

using System;
public class GFG
{

/*Function to check if there is an
element from each array such that
sum of the three elements is
equal to given sum.*/

static bool findTriplet(int []a1, int []a2,
                        int []a3, int n1,
                        int n2, int n3,
                        int sum)
{
    for (int i = 0; i < n1; i++)
        for (int j = 0; j < n2; j++)
            for (int k = 0; k < n3; k++)
            if (a1[i] + a2[j] + a3[k] == sum)
            return true;
    return false;
}

/*    Driver Code*/

    static public void Main ()
    {
        int []a1 = {1 , 2 , 3 , 4 , 5};
        int []a2 = {2 , 3 , 6 , 1 , 2};
        int []a3 = {3 , 2 , 4 , 5 , 6};
        int sum = 9;
        int n1 = a1.Length;
        int n2 = a2.Length;
        int n3 = a3.Length;
        if(findTriplet(a1, a2, a3, n1,
                       n2, n3, sum))
        Console.WriteLine("Yes");
        else
        Console.WriteLine("No");
    }
}

/*C# program to find three element
from different three arrays such
that a + b + c is equal to
given sum*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Function to check if there is
    an element from each array such
    that sum of the three elements is
    equal to given sum.*/

    static bool findTriplet(int []a1, int []a2, int []a3,
                                int n1, int n2, int n3,
                                int sum)
    {

/*        Store elements of
        first array in hash*/

        HashSet<int> s = new HashSet<int>();
        for (int i = 0; i < n1; i++)
        {
            s.Add(a1[i]);
        }

/*        sum last two arrays
        element one by one*/

        List<int> al = new List<int>(s);
        for (int i = 0; i < n2; i++)
        {
            for (int j = 0; j < n3; j++)
            {

/*                Consider current pair and
                find if there is an element
                in a1[] such that these three
                form a required triplet*/

                if (al.Contains(sum - a2[i] - a3[j]) &
                            al.IndexOf(sum - a2[i] - a3[j])
                            != al[al.Count - 1])
                {
                    return true;
                }
            }
        }
        return false;
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int []a1 = {1, 2, 3, 4, 5};
        int []a2 = {2, 3, 6, 1, 2};
        int []a3 = {3, 2, 4, 5, 6};
        int sum = 9;
        int n1 = a1.Length;
        int n2 = a2.Length;
        int n3 = a3.Length;
        if (findTriplet(a1, a2, a3, n1, n2, n3, sum))
        {
            Console.WriteLine("Yes");
        }
        else
        {
            Console.WriteLine("No");
        }
    }
}

/*C# Program to find four different elements a,b,c and d of 
array such that a+b = c+d */

using System;
using System.Collections.Generic;
public class ArrayElements
{

/*    Class to represent a pair */

    public class pair
    {
        private readonly ArrayElements outerInstance;
        public int first, second;
        public pair(ArrayElements outerInstance, int f, int s)
        {
            this.outerInstance = outerInstance;
            first = f;
            second = s;
        }
    }

/*function to find a, b, c, d such that
(a + b) = (c + d)*/

    public virtual bool findPairs(int[] arr)
    {

/*        Create an empty Hash to store mapping from sum to 
        pair indexes */

        Dictionary<int, pair> map = new Dictionary<int, pair>();
        int n = arr.Length;

/*        Traverse through all possible pairs of arr[] */

        for (int i = 0; i < n; ++i)
        {
            for (int j = i + 1; j < n; ++j)
            {

/*                If sum of current pair is not in hash, 
                then store it and continue to next pair */

                int sum = arr[i] + arr[j];
                if (!map.ContainsKey(sum))
                {
                    map[sum] = new pair(this, i,j);
                }
else 
                {
                    pair p = map[sum];
                    Console.WriteLine("(" + arr[p.first] + ", " + arr[p.second] + ") and (" + arr[i] + ", " + arr[j] + ")");
                    return true;
                }
            }
        }
        return false;
    }

/*    Testing program */

    public static void Main(string[] args)
    {
        int[] arr = new int[] {3, 4, 7, 1, 2, 9, 8};
        ArrayElements a = new ArrayElements();
        a.findPairs(arr);
    }
}

/*C# program to find maximum
length subarray with 0 sum*/

using System;
using System.Collections.Generic;
public class MaxLenZeroSumSub {

/*    Returns length of the maximum
    length subarray with 0 sum*/

    static int maxLen(int[] arr)
    {

/*        Creates an empty hashMap hM*/

        Dictionary<int, int> hM = new Dictionary<int, int>();

/*Initialize sum of elements*/

int sum = 0;

/*Initialize result*/

int max_len = 0;

/*        Traverse through the given array*/

        for (int i = 0; i < arr.GetLength(0); i++) {

/*            Add current element to sum*/

            sum += arr[i];
            if (arr[i] == 0 && max_len == 0)
                max_len = 1;
            if (sum == 0)
                max_len = i + 1;

/*            Look this sum in hash table*/

            int prev_i = 0;
            if (hM.ContainsKey(sum)) {
                prev_i = hM[sum];
            }
            if (hM.ContainsKey(sum))
                max_len = Math.Max(max_len, i - prev_i);

/*                Else put this sum in hash table*/
            else {
                if (hM.ContainsKey(sum))
                    hM.Remove(sum);
                hM.Add(sum, i);
            }
        }
        return max_len;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 15, -2, 2, -8, 1, 7, 10, 23 };
        Console.WriteLine("Length of the longest 0 sum subarray is "
                          + maxLen(arr));
    }
}

/*C# program to find length of the
longest increasing subsequence
whose adjacent element differ by 1*/

using System;
using System.Collections.Generic;
class GFG{

/*function that returns the length of the
longest increasing subsequence
whose adjacent element differ by 1*/

static int longIncrConseqSubseq(int []arr,
                                int n)
{

/*  Create hashmap to save
  latest consequent number
  as "key" and its length
  as "value"*/

  Dictionary<int,
             int> map = new Dictionary<int,
                                       int>();

/*  Put first element as "key"
  and its length as "value"*/

  map.Add(arr[0], 1);

/*    iterate for all element*/

  for (int i = 1; i < n; i++)
  {

/*    Check if last consequent
    of arr[i] exist or not*/

    if (map.ContainsKey(arr[i] - 1))
    {

/*      put the updated consequent number
      and increment its value(length)*/

      map.Add(arr[i], map[arr[i] - 1] + 1);

      map.Remove(arr[i] - 1);
    }
    else
    {
      if(!map.ContainsKey(arr[i]))
        map.Add(arr[i], 1);
    }
  }
  int max = int.MinValue;
  foreach(KeyValuePair<int,
                       int> entry in map)
  {
    if(entry.Value > max)
    {
      max = entry.Value;
    }
  }
  return max;
}

/*Driver code*/

public static void Main(String []args)
{
  int []arr = {3, 10, 3, 11,
               4, 5, 6, 7, 8, 12};
  int n = arr.Length;
  Console.WriteLine(longIncrConseqSubseq(arr, n));
}
}

/*C# implementation to find longest subsequence
such that difference between adjacents is one*/

using System;
using System.Collections.Generic;
class GFG
{

/*function to find longest subsequence such
that difference between adjacents is one*/

static int longLenSub(int []arr, int n)
{

/*    hash table to map the array element with the
    length of the longest subsequence of which
    it is a part of and is the last element of
    that subsequence*/

    Dictionary<int,
               int> um = new Dictionary<int,
                                        int>();

/*    to store the longest length subsequence*/

    int longLen = 0;

/*    traverse the array elements*/

    for (int i = 0; i < n; i++)
    {

/*        initialize current length
        for element arr[i] as 0*/

        int len = 0;

/*        if 'arr[i]-1' is in 'um' and its length
        of subsequence is greater than 'len'*/

        if (um.ContainsKey(arr[i] - 1) &&
            len < um[arr[i] - 1])
            len = um[arr[i] - 1];

/*        if 'arr[i]+1' is in 'um' and its length
        of subsequence is greater than 'len'    */

        if (um.ContainsKey(arr[i] + 1) &&
            len < um[arr[i] + 1])
            len = um[arr[i] + 1];

/*        update arr[i] subsequence length in 'um'*/

        um[arr[i]] = len + 1;

/*        update longest length*/

        if (longLen < um[arr[i]])
            longLen = um[arr[i]];
    }

/*    required longest length subsequence*/

    return longLen;    
}

/*Driver program to test above*/

static void Main()
{
    int[] arr = {1, 2, 3, 4, 5, 3, 2};
    int n = arr.Length;
    Console.Write("Longest length subsequence = " +
                               longLenSub(arr, n));
}
}

/*C# program to find longest
contiguous subsequence*/

using System;
using System.Collections.Generic;
class GFG{

/*Returns length of the longest
contiguous subsequence*/

static int findLongestConseqSubseq(int[] arr,
                                   int n)
{

/*    Sort the array*/

    Array.Sort(arr);
    int ans = 0, count = 0;
    List<int> v = new List<int>();
    v.Add(10);

/*    Insert repeated elements
    only once in the vector*/

    for(int i = 1; i < n; i++)
    {
        if (arr[i] != arr[i - 1])
            v.Add(arr[i]);
    }

/*    Find the maximum length
    by traversing the array*/

    for(int i = 0; i < v.Count; i++)
    {

/*        Check if the current element is
        equal to previous element +1*/

        if (i > 0 && v[i] == v[i - 1] + 1)
            count++;
        else
            count = 1;

/*        Update the maximum*/

        ans = Math.Max(ans, count);
    }
    return ans;
}

/*Driver code*/

static void Main()
{
    int[] arr = { 1, 9, 3, 10, 4, 20, 2 };
    int n = arr.Length;
    Console.WriteLine("Length of the Longest " +
                      "contiguous subsequence is " +
                      findLongestConseqSubseq(arr, n));
}
}

/*C# program to find longest consecutive subsequence*/

public class ArrayElements {

/*    Returns length of the
    longest consecutive subsequence*/

    public static int findLongestConseqSubseq(int[] arr,
                                              int n)
    {
        HashSet<int> S = new HashSet<int>();
        int ans = 0;

/*        Hash all the array elements*/

        for (int i = 0; i < n; ++i) {
            S.Add(arr[i]);
        }

/*        check each possible sequence from the start
        then update optimal length*/

        for (int i = 0; i < n; ++i)
        {

/*            if current element is the starting
            element of a sequence*/

            if (!S.Contains(arr[i] - 1))
            {

/*                Then check for next elements in the
                sequence*/

                int j = arr[i];
                while (S.Contains(j))
                {
                    j++;
                }

/*                update  optimal length if this length
                is more*/

                if (ans < j - arr[i])
                {
                    ans = j - arr[i];
                }
            }
        }
        return ans;
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        int[] arr = new int[] { 1, 9, 3, 10, 4, 20, 2 };
        int n = arr.Length;
        Console.WriteLine(
            "Length of the Longest consecutive subsequence is "
            + findLongestConseqSubseq(arr, n));
    }
}

/*C# implementation of longest continuous increasing
subsequence*/

using System;
using System.Collections.Generic; 
class GFG 
{

/*Function for LIS*/

static void findLIS(int []A, int n)
{
    Dictionary<int,int> hash = new Dictionary<int,int>();

/*    Initialize result*/

    int LIS_size = 1;
    int LIS_index = 0;
    hash.Add(A[0], 1);

/*    iterate through array and find
    end index of LIS and its Size*/

    for (int i = 1; i < n; i++) 
    {
        if(hash.ContainsKey(A[i]-1))
        {
            var val = hash[A[i]-1];
            hash.Remove(A[i]);
            hash.Add(A[i], val + 1); 
        }
        else
        {
            hash.Add(A[i], 1);
        }
        if (LIS_size < hash[A[i]]) 
        {
            LIS_size = hash[A[i]];
            LIS_index = A[i];
        }
    }

/*    print LIS size*/

    Console.WriteLine("LIS_size = " + LIS_size);

/*    print LIS after setting start element*/

    Console.Write("LIS : ");
    int start = LIS_index - LIS_size + 1;
    while (start <= LIS_index)
    {
        Console.Write(start + " ");
        start++;
    }
}

/*Driver code*/

public static void Main(String[] args)
{
    int []A = { 2, 5, 3, 7, 4, 8, 5, 13, 6 };
    int n = A.Length;
    findLIS(A, n);
}
}

/*C# implementation to count subsets having
even numbers only and all are distinct */

using System;
using System.Collections.Generic;
class GFG 
{

/*function to count the
required subsets*/

static int countSubsets(int []arr, int n)
{
    HashSet<int> us = new HashSet<int>();
    int even_count = 0;

/*    inserting even numbers in the set 'us'
    single copy of each number is retained*/

    for (int i = 0; i < n; i++)
        if (arr[i] % 2 == 0)
            us.Add(arr[i]);

/*    counting distinct even numbers*/

    even_count = us.Count;

/*    total count of required subsets*/

    return (int) (Math.Pow(2, even_count) - 1);
}

/*Driver code*/

public static void Main(String[] args) 
{
    int[] arr = {4, 2, 1, 9, 2, 6, 5, 3};
    int n = arr.Length;
    Console.WriteLine("Number of subsets = "
        + countSubsets(arr, n));
}
}

/*Simple C# program to count distinct
elements in every window of size k*/

using System;
using System.Collections.Generic;
class GFG {

/*    Counts distinct elements in
    window of size k*/

    static int countWindowDistinct(int[] win,
                                   int k)
    {
        int dist_count = 0;

/*        Traverse the window*/

        for (int i = 0; i < k; i++) {

/*            Check if element arr[i]
            exists in arr[0..i-1]*/

            int j;
            for (j = 0; j < i; j++)
                if (win[i] == win[j])
                    break;
            if (j == i)
                dist_count++;
        }
        return dist_count;
    }

/*    Counts distinct elements in
    all windows of size k*/

    static void countDistinct(int[] arr,
                              int n, int k)
    {

/*        Traverse through every window*/

        for (int i = 0; i <= n - k; i++) {
            int[] newArr = new int[k];
            Array.Copy(arr, i, newArr, 0, k);
            Console.WriteLine(countWindowDistinct(newArr, k));
        }
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] arr = { 1, 2, 1, 3, 4, 2, 3 };
        int k = 4;
        countDistinct(arr, arr.Length, k);
    }
}

/*C# program to find the maximum
possible sum of a window in one
array such that elements in same
window of other array are unique. */

using System;
using System.Collections.Generic;
public class MaxPossibleSuminWindow
{

/*    Function to return maximum sum of window
    in A[] according to given constraints.*/

    static int returnMaxSum(int []A, int []B, int n)
    {

/*        Map is used to store elements
        and their counts.*/

        HashSet<int> mp = new HashSet<int>();

/*Initialize result*/

int result = 0;

/*        calculating the maximum possible
        sum for each subarray containing
        unique elements.*/

        int curr_sum = 0, curr_begin = 0;
        for (int i = 0; i < n; ++i)
        {

/*            Remove all duplicate
            instances of A[i] in
            current window.*/

            while (mp.Contains(A[i]))
            {
                mp.Remove(A[curr_begin]);
                curr_sum -= B[curr_begin];
                curr_begin++;
            }

/*            Add current instance of A[i]
            to map and to current sum.*/

            mp.Add(A[i]);
            curr_sum += B[i];

/*            Update result if current
            sum is more.*/

            result = Math.Max(result, curr_sum);
        }
        return result;
    }

/*    Driver Code */

    public static void Main(String[] args)
    {
        int []A = { 0, 1, 2, 3, 0, 1, 4 };
        int []B = { 9, 8, 1, 2, 3, 4, 5 };
        int n = A.Length;
        Console.WriteLine(returnMaxSum(A, B, n));
    }
}

/*Sorting based C# implementation
to check whether the array
contains a set of contiguous
integers*/

using System;
class GFG {

/*    function to check whether
    the array contains a set
    of contiguous integers*/

    static bool areElementsContiguous(int []arr,
                                            int n)
    {

/*    Sort the array*/

    Array.Sort(arr);

/*    After sorting, check if
    current element is either
    same as previous or is
    one more.*/

    for (int i = 1; i < n; i++)
        if (arr[i] - arr[i - 1] > 1)
            return false;
    return true;
    }

/*    Driver program*/

