            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*C# implementation to check whether
the array contains a set of
contiguous integers*/

using System;
class GFG {

/*    function to check whether the
    array contains a set of
    contiguous integers*/

    static bool areElementsContiguous(
                        int []arr, int n)
    {

/*        Find maximum and
        minimum elements.*/

        int max = int.MinValue;
        int min = int.MaxValue;
        for(int i = 0; i < n; i++)
        {
            max = Math.Max(max, arr[i]);
            min = Math.Min(min, arr[i]);
        }
        int m = max - min + 1;

/*        There should be at least
        m elements in aaray to
        make them contiguous.*/

        if (m > n)
            return false;

/*        Create a visited array
        and initialize false.*/

        bool []visited = new bool[n];

/*        Mark elements as true.*/

        for (int i = 0; i < n; i++)
            visited[arr[i] - min] = true;

/*        If any element is not
        marked, all elements
        are not contiguous.*/

        for (int i = 0; i < m; i++)
            if (visited[i] == false)
                return false;
        return true;
    }

/* Driver program */

    public static void Main()
    {
        int []arr = { 5, 2, 3, 6,
                    4, 4, 6, 6 };
        int n = arr.Length;
        if (areElementsContiguous(arr, n))
            Console.Write("Yes");
        else
            Console.Write("No");
    }
}

/*c# implementation to check whether the array
contains a set of contiguous integers*/
using System;
using System.Collections.Generic;
public class GFG
{

/*    Function to check whether the array 
    contains a set of contiguous integers*/

    public static bool? areElementsContiguous(int[] arr, int n)
    {

/*        Storing elements of 'arr[]' in 
        a hash table 'us'*/

        HashSet<int> us = new HashSet<int>();
        for (int i = 0; i < n; i++)
        {
            us.Add(arr[i]);
        }

/*        As arr[0] is present in 'us'*/

        int count = 1;

/*        Starting with previous smaller 
        element of arr[0]*/

        int curr_ele = arr[0] - 1;

/*        If 'curr_ele' is present in 'us'*/

        while (us.Contains(curr_ele) == true)
        {

/*            increment count*/

            count++;

/*            update 'curr_ele"*/

            curr_ele--;
        }

/*        Starting with next greater 
        element of arr[0]*/

        curr_ele = arr[0] + 1;

/*        If 'curr_ele' is present in 'us'*/

        while (us.Contains(curr_ele) == true)
        {

/*            increment count*/

            count++;

/*            update 'curr_ele"*/

            curr_ele++;
        }

/*        Returns true if array contains a set of
        contiguous integers else returns false*/

        return (count == (us.Count));
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        int[] arr = new int[] {5, 2, 3, 6, 4, 4, 6, 6};
        int n = arr.Length;
        if (areElementsContiguous(arr, n).Value)
        {
            Console.WriteLine("Yes");
        }
        else
        {
            Console.WriteLine("No");
        }
    }
}

/*C# program to print subarray with sum as given sum*/
using System;
using System.Collections.Generic;
public class GFG
{

/*Function to print subarray with sum as given sum*/

    public static void subArraySum(int[] arr, int n, int sum)
    {

/*        cur_sum to keep track of cummulative sum till that point*/

        int cur_sum = 0;
        int start = 0;
        int end = -1;
        Dictionary<int, int> hashMap = new Dictionary<int, int>();
        for (int i = 0; i < n; i++)
        {
            cur_sum = cur_sum + arr[i];

/*            check whether cur_sum - sum = 0, if 0 it means
            the sub array is starting from index 0- so stop*/

            if (cur_sum - sum == 0)
            {
                start = 0;
                end = i;
                break;
            }

/*            if hashMap already has the value, means we already 
            have subarray with the sum - so stop*/

            if (hashMap.ContainsKey(cur_sum - sum))
            {
                start = hashMap[cur_sum - sum] + 1;
                end = i;
                break;
            }

/*            if value is not present then add to hashmap*/

            hashMap[cur_sum] = i;
        }

/*        if end is -1 : means we have reached end without the sum*/

        if (end == -1)
        {
            Console.WriteLine("No subarray with given sum exists");
        }
        else
        {
            Console.WriteLine("Sum found between indexes " + start + " to " + end);
        }
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        int[] arr = new int[] {10, 2, -2, -20, 10};
        int n = arr.Length;
        int sum = -10;
        subArraySum(arr, n, sum);
    }
}

/*C# program to find minimum number
of insertions to make a string
palindrome*/

using System;
public class GFG {

/*    Function will return number of
    characters to be added*/

    static int minInsertion(String str)
    {

/*        To store string length*/

        int n = str.Length;

/*        To store number of characters
        occurring odd number of times*/

        int res = 0;

/*        To store count of each
        character*/

        int[] count = new int[26];

/*        To store occurrence of each
        character*/

        for (int i = 0; i < n; i++)
            count[str[i] - 'a']++;

/*        To count characters with odd
        occurrence*/

        for (int i = 0; i < 26; i++) {
            if (count[i] % 2 == 1)
                res++;
        }

/*        As one character can be odd
        return res - 1 but if string
        is already palindrome
        return 0*/

        return (res == 0) ? 0 : res - 1;
    }

/*    Driver program*/

    public static void Main()
    {
        string str = "geeksforgeeks";
        Console.WriteLine(minInsertion(str));
    }
}

/*C# program to find maximum difference
between frequency of any two element
such that element with greater frequency
is also greater in value.*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Return the maximum difference between
    frequencies of any two elements such that
    element with greater frequency is also
    greater in value.*/

    static int maxdiff(int[] arr, int n)
    {
        Dictionary<int,
                   int> freq = new Dictionary<int,
                                              int>();

/*        Finding the frequency of each element.*/

        for (int i = 0; i < n; i++)
        {
            if (freq.ContainsKey(arr[i]))
                freq[arr[i]]++;
            else
                freq.Add(arr[i], 1);
        }
        int ans = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {

/*                finding difference such that element
                having greater frequency is also
                greater in value.*/

                if (freq[arr[i]] > freq[arr[j]] && arr[i] > arr[j])
                    ans = Math.Max(ans, freq[arr[i]] - freq[arr[i]]);
                else if (freq[arr[i]] < freq[arr[j]] && arr[i] < arr[j])
                    ans = Math.Max(ans, freq[arr[j]] - freq[arr[i]]);
            }
        }
        return ans;
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] arr = { 3, 1, 3, 2, 3, 2 };
        int n = arr.Length;
        Console.WriteLine(maxdiff(arr, n));
    }
}

/*Efficient C# program to find maximum
difference between frequency of any two
elements such that element with greater
frequency is also greater in value.*/

using System.Collections.Generic;
using System;
class GFG{

/*Return the maximum difference between
frequencies of any two elements such
that element with greater frequency
is also greater in value.*/

static int maxdiff(int []arr, int n)
{
    Dictionary<int,
               int> freq = new Dictionary<int,
                                          int>();
    List<int> dist = new List<int>();

/*    Finding the frequency of each element.*/

    int j = 0;
    for(int i = 0; i < n; i++)
    {
        if (freq.ContainsKey(arr[i]) == false)
        {
            dist.Add(arr[i]);
            j++;
        }
        if (freq.ContainsKey(arr[i]))
            freq[arr[i]]++;
        else
            freq[arr[i]]=1;
    }

/*    Sorting the distinct element*/

    dist.Sort();
    int min_freq = n + 1;

/*    Iterate through all sorted distinct elements.
    For each distinct element, maintaining the
    element with minimum frequency than that
    element and also finding the maximum
    frequency difference*/

    int ans = 0;
    for(int i = 0; i < j; i++)
    {
        int cur_freq = freq[dist[i]];
        ans = Math.Max(ans, cur_freq - min_freq);
        min_freq = Math.Min(min_freq, cur_freq);
    }
    return ans;
}

/*Driver code*/

public static void Main(String[] args)
{
    int []arr = { 3, 1, 3, 2, 3, 2 };
    int n = arr.Length;
    Console.WriteLine(maxdiff(arr, n));
}
}

/*C# Code for Difference between
highest and least frequencies
in an array*/

using System;
class GFG {
    static int findDiff(int[] arr, int n)
    {

/*        sort the array*/

        Array.Sort(arr);
        int count = 0, max_count = 0,
            min_count = n;
        for (int i = 0; i < (n - 1); i++) {

/*            checking consecutive elements*/

            if (arr[i] == arr[i + 1]) {
                count += 1;
                continue;
            }
            else {
                max_count = Math.Max(max_count,
                                    count);
                min_count = Math.Min(min_count,
                                    count);
                count = 0;
            }
        }
        return (max_count - min_count);
    }

/*    Driver program to test above function*/

    public static void Main()
    {
        int[] arr = { 7, 8, 4, 5, 4, 1,
                       1, 7, 7, 2, 5 };
        int n = arr.Length;
        Console.WriteLine(findDiff(arr, n));
    }
}

/*C# code to find the difference between highest
and least frequencies*/

using System;
using System.Collections.Generic;
class GFG
{
static int findDiff(int []arr, int n)
{

/*    Put all elements in a hash map*/

    Dictionary<int,int> mp = new Dictionary<int,int>();
    for (int i = 0 ; i < n; i++)
    {
        if(mp.ContainsKey(arr[i]))
        {
            var val = mp[arr[i]];
            mp.Remove(arr[i]);
            mp.Add(arr[i], val + 1);
        }
        else
        {
            mp.Add(arr[i], 1);
        }
    }

/*    Find counts of maximum and minimum
    frequent elements*/

    int max_count = 0, min_count = n;
    foreach(KeyValuePair<int, int> entry in mp)
    {
        max_count = Math.Max(max_count, entry.Value);
        min_count = Math.Min(min_count, entry.Value);
    }
    return (max_count - min_count);
}

/*Driver code*/

public static void Main(String[] args)
{
    int []arr = { 7, 8, 4, 5, 4, 1, 1, 7, 7, 2, 5 };
    int n = arr.Length;
    Console.WriteLine(findDiff(arr, n));
}
}

/*C# find maximum difference of
subset sum*/

using System;
public class GFG {

/*    function for maximum subset diff*/

    static int maxDiff(int []arr, int n)
    {
        int SubsetSum_1 = 0, SubsetSum_2 = 0;
        for (int i = 0; i <= n - 1; i++)
        {
            bool isSingleOccurance = true;
            for (int j = i + 1; j <= n - 1; j++)
            {

/*                if frequency of any element
                is two make both equal to
                zero*/

                if (arr[i] == arr[j])
                {
                    isSingleOccurance = false;
                    arr[i] = arr[j] = 0;
                    break;
                }
            }
            if (isSingleOccurance)
            {
                if (arr[i] > 0)
                    SubsetSum_1 += arr[i];
                else
                    SubsetSum_2 += arr[i];
            }
        }
        return Math.Abs(SubsetSum_1 - SubsetSum_2);
    }

/*    driver program*/

    static public void Main ()
    {
        int []arr = { 4, 2, -3, 3, -2, -2, 8 };
        int n = arr.Length;
        Console.WriteLine("Maximum Difference = "
                              + maxDiff(arr, n));
    }
}

/*C# find maximum difference
of subset sum*/

using System;
public class GFG {

/*    function for maximum subset diff*/

    static int maxDiff(int []arr, int n)
    {
        int result = 0;

/*        sort the array*/

        Array.Sort(arr);

/*        calculate the result*/

        for (int i = 0; i < n - 1; i++)
        {
            if (arr[i] != arr[i + 1])
                result += Math.Abs(arr[i]);
            else
                i++;
        }

/*        check for last element*/

        if (arr[n - 2] != arr[n - 1])
            result += Math.Abs(arr[n - 1]);

/*        return result*/

        return result;
    }

