/*C# program to count of index pairs with
equal elements in an array.*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Return the number of pairs with
    equal values.*/

    public static int countPairs(int []arr, int n)
    {
        Dictionary<int,
                   int> hm = new Dictionary<int,
                                            int>();

/*        Finding frequency of each number.*/

        for(int i = 0; i < n; i++)
        {
            if(hm.ContainsKey(arr[i]))
            {
                int a = hm[arr[i]];
                hm.Remove(arr[i]);
                hm.Add(arr[i], a + 1);
            }
            else
                hm.Add(arr[i], 1);
        }
        int ans = 0;

/*        Calculating count of pairs with
        equal values*/

        foreach(var it in hm)
        {
            int count = it.Value;
            ans += (count * (count - 1)) / 2;
        }
        return ans;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = new int[]{1, 2, 3, 1};
        Console.WriteLine(countPairs(arr,arr.Length));
    }
}

/* A C# program to answer queries to check whether 
the substrings are palindrome or not efficiently */

using System;
class GFG {
    static int p = 101;
    static int MOD = 1000000007;

/*    Structure to represent a query. A query consists
    of (L, R) and we have to answer whether the substring
    from index-L to R is a palindrome or not*/

    public class Query {
        public int L, R;
        public Query(int L, int R)
        {
            this.L = L;
            this.R = R;
        }
    };

/*    A function to check if a string str is palindrome
    in the ranfe L to R*/

    static Boolean isPalindrome(String str, int L, int R)
    {

/*        Keep comparing characters while they are same*/

        while (R > L) {
            if (str[L++] != str[R--]) {
                return (false);
            }
        }
        return (true);
    }

/*    A Function to find pow (base, exponent) % MOD
    in log (exponent) time*/

    static int modPow(int Base, int exponent)
    {
        if (exponent == 0) {
            return 1;
        }
        if (exponent == 1) {
            return Base;
        }
        int temp = modPow(Base, exponent / 2);
        if (exponent % 2 == 0) {
            return (temp % MOD * temp % MOD) % MOD;
        }
        else {
            return (((temp % MOD * temp % MOD) % MOD) * Base % MOD) % MOD;
        }
    }

/*    A Function to calculate Modulo Multiplicative Inverse of 'n'*/

    static int findMMI(int n)
    {
        return modPow(n, MOD - 2);
    }

/*    A Function to calculate the prefix hash*/

    static void computePrefixHash(String str, int n,
                                  int[] prefix, int[] power)
    {
        prefix[0] = 0;
        prefix[1] = str[0];
        for (int i = 2; i <= n; i++) {
            prefix[i] = (prefix[i - 1] % MOD
                         + (str[i - 1] % MOD * power[i - 1] % MOD) % MOD)
                        % MOD;
        }
        return;
    }

/*    A Function to calculate the suffix hash
    Suffix hash is nothing but the prefix hash of
    the reversed string*/

    static void computeSuffixHash(String str, int n,
                                  int[] suffix, int[] power)
    {
        suffix[0] = 0;
        suffix[1] = str[n - 1];
        for (int i = n - 2, j = 2; i >= 0 && j <= n; i--, j++) {
            suffix[j] = (suffix[j - 1] % MOD
                         + (str[i] % MOD * power[j - 1] % MOD) % MOD)
                        % MOD;
        }
        return;
    }

/*    A Function to answer the Queries*/

    static void queryResults(String str, Query[] q, int m, int n,
                             int[] prefix, int[] suffix, int[] power)
    {
        for (int i = 0; i <= m - 1; i++) {
            int L = q[i].L;
            int R = q[i].R;

/*            Hash Value of Substring [L, R]*/

            long hash_LR
                = ((prefix[R + 1] - prefix[L] + MOD) % MOD
                   * findMMI(power[L]) % MOD)
                  % MOD;

/*            Reverse Hash Value of Substring [L, R]*/

            long reverse_hash_LR
                = ((suffix[n - L] - suffix[n - R - 1] + MOD) % MOD
                   * findMMI(power[n - R - 1]) % MOD)
                  % MOD;

/*            If both are equal then the substring is a palindrome*/

            if (hash_LR == reverse_hash_LR) {
                if (isPalindrome(str, L, R) == true) {
                    Console.Write("The Substring [{0} {1}] is a "
                                      + "palindrome\n",
                                  L, R);
                }
                else {
                    Console.Write("The Substring [{0} {1}] is not a "
                                      + "palindrome\n",
                                  L, R);
                }
            }
            else {
                Console.Write("The Substring [{0} {1}] is not a "
                                  + "palindrome\n",
                              L, R);
            }
        }
        return;
    }

/*    A Dynamic Programming Based Approach to compute the
    powers of 101*/

    static void computePowers(int[] power, int n)
    {

/*        101^0 = 1*/

        power[0] = 1;
        for (int i = 1; i <= n; i++) {
            power[i] = (power[i - 1] % MOD * p % MOD) % MOD;
        }
        return;
    }

/* Driver code */

    public static void Main(String[] args)
    {
        String str = "abaaabaaaba";
        int n = str.Length;

/*        A Table to store the powers of 101*/

        int[] power = new int[n + 1];
        computePowers(power, n);

/*        Arrays to hold prefix and suffix hash values*/

        int[] prefix = new int[n + 1];
        int[] suffix = new int[n + 1];

/*        Compute Prefix Hash and Suffix Hash Arrays*/

        computePrefixHash(str, n, prefix, power);
        computeSuffixHash(str, n, suffix, power);
        Query[] q = { new Query(0, 10), new Query(5, 8),
                      new Query(2, 5), new Query(5, 9) };
        int m = q.Length;
        queryResults(str, q, m, n, prefix, suffix, power);
    }
}

/*C# program to finds out smallest
range that includes elements from
each of the given sorted lists.*/

using System;
class GFG {
    static int N = 5;

/*    array for storing the current index of list i*/

    static int[] ptr = new int[501];

/*    This function takes an k sorted
    lists in the form of 2D array as
    an argument. It finds out smallest range
    that includes elements from each of the k lists.*/

    static void findSmallestRange(int[, ] arr,
                                  int n, int k)
    {
        int i, minval, maxval, minrange,
            minel = 0, maxel = 0, flag, minind;

/*        initializing to 0 index;*/

        for (i = 0; i <= k; i++) {
            ptr[i] = 0;
        }
        minrange = int.MaxValue;
        while (true) {

/*            for maintining the index of
            list containing the minimum element*/

            minind = -1;
            minval = int.MaxValue;
            maxval = int.MinValue;
            flag = 0;

/*            iterating over all the list*/

            for (i = 0; i < k; i++) {

/*                if every element of list[i]
                is traversed then break the loop*/

                if (ptr[i] == n) {
                    flag = 1;
                    break;
                }

/*                find minimum value among all the
                list elements pointing by the ptr[] array*/

                if (ptr[i] < n && arr[i, ptr[i]] < minval) {

/*update the index of the list*/

minind = i; 
                    minval = arr[i, ptr[i]];
                }

/*                find maximum value among all the
                list elements pointing by the ptr[] array*/

                if (ptr[i] < n && arr[i, ptr[i]] > maxval) {
                    maxval = arr[i, ptr[i]];
                }
            }

/*            if any list exhaust we will
            not get any better answer,
            so break the while loop*/

            if (flag == 1) {
                break;
            }
            ptr[minind]++;

/*            updating the minrange*/

            if ((maxval - minval) < minrange) {
                minel = minval;
                maxel = maxval;
                minrange = maxel - minel;
            }
        }
        Console.WriteLine("The smallest range is"
                              + "[{0}, {1}]\n",
                          minel, maxel);
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int[, ] arr = {
            { 4, 7, 9, 12, 15 },
            { 0, 8, 10, 14, 20 },
            { 6, 12, 16, 30, 50 }
        };
        int k = arr.GetLength(0);
        findSmallestRange(arr, N, k);
    }
}

/*C# program for above implementation*/

using System;
public class GFG {

/*    Function to count numbers to be added*/

    static int countNum(int []arr, int n)
    {
        int count = 0;

/*        Sort the array*/

        Array.Sort(arr);

/*        Check if elements are consecutive
        or not. If not, update count*/

        for (int i = 0; i < n - 1; i++)
            if (arr[i] != arr[i+1] &&
                arr[i] != arr[i + 1] - 1)
                count += arr[i + 1] - arr[i] - 1;
        return count;
    }

/*    Drivers code*/

    static public void Main ()
    {
        int []arr = { 3, 5, 8, 6 };
        int n = arr.Length;
        Console.WriteLine(countNum(arr, n));
    }
}

/*C# implementation of the approach*/

using System;
using System.Collections.Generic;
class GFG
{

/*Function to count numbers to be added*/

static int countNum(int []arr, int n)
{
    HashSet<int> s = new HashSet<int>();
    int count = 0,
        maxm = int.MinValue,
        minm = int.MaxValue;

/*    Make a hash of elements
    and store minimum and maximum element*/

    for (int i = 0; i < n; i++)
    {
        s.Add(arr[i]);
        if (arr[i] < minm)
            minm = arr[i];
        if (arr[i] > maxm)
            maxm = arr[i];
    }

/*    Traverse all elements from minimum
    to maximum and count if it is not
    in the hash*/

    for (int i = minm; i <= maxm; i++)
        if (!s.Contains(i))
            count++;
    return count;
}

/*Drivers code*/

public static void Main(String[] args)
{
    int []arr = { 3, 5, 8, 6 };
    int n = arr.Length;
    Console.WriteLine(countNum(arr, n));
}
}

/*C# program to demonstrate working of
Cuckoo hashing.*/

using System;
class GFG
{

/*upper bound on number of
elements in our set*/

static int MAXN = 11;

/*choices for position*/

static int ver = 2;

/*Auxiliary space bounded by a small
multiple of MAXN, minimizing wastage*/

static int [,]hashtable = new int[ver, MAXN];

/*Array to store
possible positions for a key*/

static int []pos = new int[ver];

/* function to fill hash table
with dummy value
* dummy value: INT_MIN
* number of hashtables: ver */

static void initTable()
{
    for (int j = 0; j < MAXN; j++)
        for (int i = 0; i < ver; i++)
            hashtable[i, j] = int.MinValue;
}

/* return hashed value for a key
* function: ID of hash function
according to which key has to hashed
* key: item to be hashed */

static int hash(int function, int key)
{
    switch (function)
    {
        case 1: return key % MAXN;
        case 2: return (key / MAXN) % MAXN;
    }
    return int.MinValue;
}

/* function to place a key in one of
its possible positions
* tableID: table in which key
has to be placed, also equal to function
according to which key must be hashed
* cnt: number of times function has already
been called in order to place the first input key
* n: maximum number of times function
can be recursively called before stopping and
declaring presence of cycle */

static void place(int key, int tableID,
                  int cnt, int n)
{

/* if function has been recursively
    called max number of times,
    stop and declare cycle. Rehash. */

    if (cnt == n)
    {
        Console.Write("{0} unpositioned\n", key);
        Console.Write("Cycle present. REHASH.\n");
        return;
    }

/* calculate and store possible positions
    * for the key. Check if key already present
    at any of the positions. If YES, return. */

    for (int i = 0; i < ver; i++)
    {
        pos[i] = hash(i + 1, key);
        if (hashtable[i, pos[i]] == key)
        return;
    }

/* check if another key is already present
    at the position for the new key in the table
    * If YES: place the new key in its position
    * and place the older key in an alternate position
    for it in the next table */

    if (hashtable[tableID,
              pos[tableID]] != int.MinValue)
    {
        int dis = hashtable[tableID, pos[tableID]];
        hashtable[tableID, pos[tableID]] = key;
        place(dis, (tableID + 1) % ver, cnt + 1, n);
    }

/*else: place the new key in its position*/

else 
    hashtable[tableID, pos[tableID]] = key;
}

/* function to print hash table contents */

static void printTable()
{
    Console.Write("Final hash tables:\n");
    for (int i = 0; i < ver;
             i++, Console.Write("\n"))
        for (int j = 0; j < MAXN; j++)
            if(hashtable[i, j] == int.MinValue)
                Console.Write("- ");
            else
                Console.Write("{0} ",
                        hashtable[i, j]);
    Console.Write("\n");
}

/* function for Cuckoo-hashing keys
* keys[]: input array of keys
* n: size of input array */

static void cuckoo(int []keys, int n)
{

/*    initialize hash tables to a
    dummy value (INT-MIN)
    indicating empty position*/

    initTable();

/*    start with placing every key
    at its position in the first
    hash table according to first
    hash function*/

    for (int i = 0, cnt = 0;
             i < n; i++, cnt = 0)
        place(keys[i], 0, cnt, n);

/*    print the final hash tables*/

    printTable();
}

/*Driver Code*/

public static void Main(String[] args)
{

/* following array doesn't have
    any cycles and hence all keys
    will be inserted without any rehashing */

    int []keys_1 = {20, 50, 53, 75, 100,
                    67, 105, 3, 36, 39};
    int n = keys_1.Length;
    cuckoo(keys_1, n);

/* following array has a cycle and
    hence we will have to rehash to
    position every key */

    int []keys_2 = {20, 50, 53, 75, 100,
                    67, 105, 3, 36, 39, 6};
    int m = keys_2.Length;
    cuckoo(keys_2, m);
}
}

/*C# program to calculate sum of lengths of subarrays
of distinct elements*/

using System;
using System.Collections.Generic;
public class geeks
{

/*    Returns sum of lengths of all subarrays
    with distinct elements.*/

    public static int sumoflength(int[] arr, int n)
    {

/*        For maintaining distinct elements.*/

        HashSet<int> s = new HashSet<int>();

/*        Initialize ending point and result*/

        int j = 0, ans = 0;

/*        Fix starting point*/

        for (int i = 0; i < n; i++)
        {
            while (j < n && !s.Contains(arr[j]))
            {
                s.Add(arr[i]);
                j++;
            }

/*            Calculating and adding all possible length
            subarrays in arr[i..j]*/

            ans += ((j - i) * (j - i + 1)) / 2;

/*            Remove arr[i] as we pick new stating point
            from next*/

            s.Remove(arr[i]);
        }
        return ans;
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] arr = { 1, 2, 3, 4 };
        int n = arr.Length;
        Console.WriteLine(sumoflength(arr, n));
    }
}

/*C# program Count total number of sub-arrays
having total distinct elements same as that
original array.*/

using System;
using System.Collections.Generic;
class Test
{

/*    Method to calculate distinct sub-array*/

    static int countDistictSubarray(int []arr, int n)
    {

/*        Count distinct elements in whole array*/

        Dictionary<int, int> vis = new Dictionary<int,int>();
        for (int i = 0; i < n; ++i)
            if(!vis.ContainsKey(arr[i]))
                vis.Add(arr[i], 1);
        int k = vis.Count;

/*        Reset the container by removing all elements*/

        vis.Clear();

/*        Use sliding window concept to find
        count of subarrays having k distinct
        elements.*/

        int ans = 0, right = 0, window = 0;
        for (int left = 0; left < n; ++left)
        {
            while (right < n && window < k)
            {
                if(vis.ContainsKey(arr[right]))
                    vis[arr[right]] = vis[arr[right]] + 1;
                else
                    vis.Add(arr[right], 1);
                if (vis[arr[right]] == 1)
                    ++window;
                ++right;
            }

/*            If window size equals to array distinct
            element size, then update answer*/

            if (window == k)
                ans += (n - right + 1);

/*            Decrease the frequency of previous element
            for next sliding window*/

            if(vis.ContainsKey(arr[left]))
                    vis[arr[left]] = vis[arr[left]] - 1;

/*            If frequency is zero then decrease the
            window size*/

            if (vis[arr[left]] == 0)
                    --window;
        }
        return ans;
    }

/*    Driver method*/

    public static void Main(String []args)
    {
        int []arr = {2, 1, 3, 2, 3};
        Console.WriteLine(countDistictSubarray(arr, arr.Length));
    }
}

/*C# program to find total
number of even-odd subarrays
present in given array*/

using System;
class GFG
{

/*    function that returns the
    count of subarrays that
    contain equal number of
    odd as well as even numbers*/

    static int countSubarrays(int []arr,
                              int n)
    {

/*        initialize difference
        and answer with 0*/

        int difference = 0;
        int ans = 0;

/*        create two auxiliary hash
        arrays to count frequency
        of difference, one array
        for non-negative difference
        and other array for negative
        difference. Size of these
        two auxiliary arrays is 'n+1'
        because difference can
        reach maximum value 'n' as
        well as minimum value '-n'*/

        int []hash_positive = new int[n + 1];
        int []hash_negative = new int[n + 1];

/*        initialize these
        auxiliary arrays with 0*/

        Array.Clear(hash_positive, 0, n + 1);
        Array.Clear(hash_negative, 0, n + 1);

/*        since the difference is
        initially 0, we have to
        initialize hash_positive[0] with 1*/

        hash_positive[0] = 1;

/*        for loop to iterate
        through whole array
        (zero-based indexing is used)*/

        for (int i = 0; i < n ; i++)
        {

/*            incrementing or decrementing
            difference based on
            arr[i] being even or odd,
            check if arr[i] is odd*/

            if ((arr[i] & 1) == 1)
                difference++;
            else
                difference--;

/*            adding hash value of 'difference'
            to our answer as all the previous
            occurrences of the same difference
            value will make even-odd subarray
            ending at index 'i'. After that,
            we will increment hash array for
            that 'difference' value for its
            occurrence at index 'i'. if
            difference is negative then use
            hash_negative*/

            if (difference < 0)
            {
                ans += hash_negative[-difference];
                hash_negative[-difference]++;
            }

/*            else use hash_positive*/

            else
            {
                ans += hash_positive[difference];
                hash_positive[difference]++;
            }
        }

/*        return total number
        of even-odd subarrays*/

        return ans;
    }

/*    Driver code*/

    static void Main()
    {
        int []arr = new int[]{3, 4, 6, 8,
                              1, 10, 5, 7};
        int n = arr.Length;

/*        Printing total number
        of even-odd subarrays*/

        Console.Write("Total Number of Even-Odd" +
                               " subarrays are " +
                           countSubarrays(arr,n));
    }
}

/*C# program for Minimum number of
distinct elements after removing m items*/

using System;
using System.Collections.Generic; 
class GFG
{

/*  Function to find distintc id's*/

  static int distinctIds(int[] arr, int n, int mi)
  {
    Dictionary<int, int> m = new Dictionary<int, int>(); 
    int count = 0;
    int size = 0;

/*    Store the occurrence of ids*/

    for (int i = 0; i < n; i++)
    {
      if (m.ContainsKey(arr[i]) == false)
      {
        m[arr[i]] = 1;
        size++;
      }
      else
      {
        m[arr[i]]++;
      }
    }

/*    Start removing elements from the beginning*/

    foreach(KeyValuePair<int, int> mp in m)
    {

/*      Remove if current value is less than
      or equal to mi*/

      if (mp.Key <= mi)
      {
        mi -= mp.Key;
        count++;
      }
    }

/*            Return the remaining size*/

    return size - count;
  }

/*  Driver code*/

  static void Main()
  {
    int[] arr = {2, 3, 1, 2, 3, 3};
    int m = 3;
    Console.WriteLine(distinctIds(arr, arr.Length, m));
  }
}

/*C# program to find largest consecutive 
numbers present in arr[].*/

using System;
using System.Collections.Generic; public
class GFG
{
static int findLongestConseqSubseq(int []arr, int n)
{

/* We insert all the array elements into
    unordered set. */

    HashSet<int> S = new HashSet<int>();
    for (int i = 0; i < n; i++)
        S.Add(arr[i]);

/*    check each possible sequence from the start
    then update optimal length*/

    int ans = 0;
    for (int i = 0; i < n; i++) 
    {

/*        if current element is the starting
        element of a sequence*/

        if(S.Contains(arr[i])) 
        {

/*            Then check for next elements in the
            sequence*/

            int j = arr[i];

/*            increment the value of array element
            and repeat search in the set*/

            while (S.Contains(j))
                j++;

/*            Update optimal length if this length
            is more. To get the length as it is 
            incremented one by one*/

            ans = Math.Max(ans, j - arr[i]); 
        }
    }
    return ans;
}

/*Driver code*/

public static void Main(String[] args) 
{
    int []arr = {1, 94, 93, 1000, 5, 92, 78};
    int n = arr.Length;
    Console.WriteLine(findLongestConseqSubseq(arr, n));
}
}

/*C# Program to find the largest
such that d = a + b + c*/

using System;
class GFG
{

/*function to find largest d*/

static int findLargestd(int []S,
                        int n)
{
    bool found = false;

/*    sort the array
    in ascending order*/

    Array.Sort(S);

/*    iterating from backwards to
    find the required largest d*/

    for (int i = n - 1; i >= 0; i--)
    {
        for (int j = 0; j < n; j++)
        {

/*            since all four a, b, c,
            d should be distinct*/

            if (i == j)
                continue;
            for (int k = j + 1; k < n; k++)
            {
                if (i == k)
                    continue;
                for (int l = k + 1; l < n; l++)
                {
                    if (i == l)
                        continue;

/*                    if the current combination
                    of j, k, l in the set is
                    equal to S[i] return this
                    value as this would be the
                    largest dsince we are 
                    iterating in descending order*/

                    if (S[i] == S[j] + S[k] + S[l])
                    {
                        found = true;
                        return S[i];
                    }
                }
            }
        }
    }
    if (found == false)
        return int.MaxValue;
    return -1;
}

/*Driver Code*/

public static void Main()
{
    int []S = new int[]{ 2, 3, 5, 7, 12 };
    int n = S.Length;
    int ans = findLargestd(S, n);
    if (ans == int.MaxValue)
        Console.WriteLine( "No Solution");
    else
        Console.Write("Largest d such that a + " +
                          "b + c = d is " + ans );
}
}

/*A hashing based C# program to find
largest d such that a + b + c = d.*/

using System;
using System.Collections.Generic;

/*To store and retrieve
indices pair i & j*/

public class Indexes
{
    int i, j;
    public Indexes(int i, int j)
    {
        this.i = i;
        this.j = j;
    }
    public int getI()
    {
        return i;
    }
    public int getJ()
    {
        return j;
    }
}
public class GFG
{

/*    The function finds four elements
    with given sum X*/

    static int findFourElements(int[] arr, int n)
    {
        Dictionary<int, Indexes> map =
                    new Dictionary<int, Indexes>();

/*        Store sums (a+b) of all pairs
        (a,b) in a hash table*/

        for (int i = 0; i < n - 1; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                map.Add(arr[i] + arr[j],
                        new Indexes(i, j));
            }
        }
        int d = int.MinValue;

/*        Traverse through all pairs and
        find (d -c) is present in hash table*/

        for (int i = 0; i < n - 1; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int abs_diff = Math.Abs(arr[i] - arr[j]);

/*                If d - c is present in hash table,*/

                if (map.ContainsKey(abs_diff))
                {
                    Indexes indexes = map[abs_diff];

/*                    Making sure that all elements are
                    distinct array elements and an element
                    is not considered more than once.*/

                    if (indexes.getI() != i &&
                        indexes.getI() != j &&
                        indexes.getJ() != i &&
                        indexes.getJ() != j)
                    {
                        d = Math.Max(d, Math.Max(arr[i],
                                                 arr[j]));
                    }
                }
            }
        }
        return d;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = { 2, 3, 5, 7, 12 };
        int n = arr.Length;
        int res = findFourElements(arr, n);
        if (res == int.MinValue)
            Console.WriteLine("No Solution");
        else
            Console.WriteLine(res);
    }
}

/*C# for finding sum of all unique
subarray sum*/

using System;
using System.Collections.Generic;
class GFG{

/*Function for finding grandSum*/

static int findSubarraySum(int []arr,
                           int n)
{
  int i, j;

/*  Calculate cumulative sum
  of array cArray[0] will
  store sum of zero elements*/

  int []cArray = new int[n + 1];
  for(i = 0; i < n; i++)
    cArray[i + 1] = cArray[i] + arr[i];
  List<int> subArrSum = new List<int>();

/*  Store all subarray sum in vector*/

  for(i = 1; i <= n; i++)
    for(j = i; j <= n; j++)
      subArrSum.Add(cArray[j] -
                    cArray[i - 1]);

/*  Sort the vector*/

  subArrSum.Sort();

/*  Mark all duplicate
  sub-array sum to zero*/

  int totalSum = 0;
  for(i = 0; i < subArrSum.Count - 1; i++)
  {
    if (subArrSum[i] ==
        subArrSum[i + 1])
    {
      j = i + 1;
      while (subArrSum[j] ==
             subArrSum[i] &&
             j < subArrSum.Count)
      {
        subArrSum[j] = 0;
        j++;
      }
      subArrSum[i] = 0;
    }
  }

/*  Calculate total sum*/

  for(i = 0; i < subArrSum.Count; i++)
    totalSum += subArrSum[i];

/*  Return totalSum*/

  return totalSum;
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []arr = {3, 2, 3, 1, 4};
    int n = arr.Length;   
    Console.Write(findSubarraySum(arr, n));
}
}

/*C# for finding sum of all
unique subarray sum*/

using System;
using System.Collections.Generic;
class GFG
{

/*function for finding grandSum*/

static int findSubarraySum(int []arr, int n)
{
    int res = 0;

/*    Go through all subarrays, compute sums
    and count occurrences of sums.*/

    Dictionary<int,
               int> m = new Dictionary<int,
                                       int>();
    for (int i = 0; i < n; i++)
    {
        int sum = 0;
        for (int j = i; j < n; j++)
        {
            sum += arr[j];
            if (m.ContainsKey(sum))
            {
                m[sum] = m[sum] + 1;
            }
            else
            {
                m.Add(sum, 1);
            }
        }
    }

/*    Print all those sums that appear
    once.*/

    foreach(KeyValuePair<int, int> x in m)
        if (x.Value == 1)
            res += x.Key;
    return res;
}

/*Driver code*/

public static void Main(String[] args)
{
    int []arr = { 3, 2, 3, 1, 4 };
    int n = arr.Length;
    Console.WriteLine(findSubarraySum(arr, n));
}
}

/*C# program to print n-th number in Recaman's
sequence*/

using System;
class GFG {

/*    Prints first n terms of Recaman sequence*/

    static void recaman(int n)
    {

/*        Create an array to store terms*/

        int []arr = new int[n];

/*        First term of the sequence is always 0*/

        arr[0] = 0;
        Console.Write(arr[0]+" ,");

/*        Fill remaining terms using recursive
        formula.*/

        for (int i = 1; i < n; i++)
        {
            int curr = arr[i - 1] - i;
            int j;
            for (j = 0; j < i; j++)
            {

/*                If arr[i-1] - i is negative or
                already exists.*/

                if ((arr[j] == curr) || curr < 0)
                {
                    curr = arr[i - 1] + i;
                    break;
                }
            }
            arr[i] = curr;
        Console.Write(arr[i]+", ");
        }
    }

/*    Driver code*/

    public static void Main ()
    {
        int n = 17;
        recaman(n);
    }
}

/*C# program to print n-th number
in Recaman's sequence*/

using System;
using System.Collections.Generic;
class GFG
{

/*Prints first n terms of Recaman sequence*/

static void recaman(int n)
{
    if (n <= 0)
    return;

/*    Print first term and store it in a hash*/

    Console.Write("{0}, ", 0);
    HashSet<int> s = new HashSet<int>();
    s.Add(0);

/*    Print remaining terms using
    recursive formula.*/

    int prev = 0;
    for (int i = 1; i < n; i++)
    {
        int curr = prev - i;

/*        If arr[i-1] - i is negative or
        already exists.*/

        if (curr < 0 || s.Contains(curr))
            curr = prev + i;
        s.Add(curr);
        Console.Write("{0}, ", curr);
        prev = curr;
    }
}

/*Driver code*/

public static void Main(String[] args)
{
    int n = 17;
    recaman(n);
}
}

/*C# program to find 
largest Fibonacci subset*/

using System;
using System.Linq;
using System.Collections.Generic; 
class GFG
{

/*    Prints largest subset of an array whose
    all elements are fibonacci numbers*/

    public static void findFibSubset(int[] x)
    {

        List<int> fib = new List<int>(); 
        List<int> result = new List<int>();

/*    Find maximum element in arr[]*/

        int max = x.Max();

/*        Generate all Fibonacci numbers 
        till max and store them*/

        int a = 0;
        int b = 1;
        while (b < max)
        {
            int c = a + b;
            a = b;
            b = c;
            fib.Add(c);
        }

/*        Now iterate through all numbers and
        quickly check for Fibonacci*/

        for (int i = 0; i < x.Length; i++)
        {
            if(fib.Contains(x[i]))
            {
                result.Add(x[i]); 
            }     
        }
        foreach(int i in result)
            Console.Write(i + " ");
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        int[] a = {4, 2, 8, 5, 20, 1, 40, 13, 23};
        findFibSubset(a);
    }
}

/*Efficient C# program to count
Amicable pairs in an array.*/

using System;
using System.Collections.Generic;
class GFG
{

/*Calculate the sum
of proper divisors*/

static int sumOfDiv(int x)
{

/*    1 is a proper divisor*/

    int sum = 1;
    for (int i = 2; i <= Math.Sqrt(x); i++)
    {
        if (x % i == 0)
        {
            sum += i;

/*            To handle perfect squares*/

            if (x / i != i)
                sum += x / i;
        }
    }
    return sum;
}

/*Check if pair is amicable*/

static Boolean isAmicable(int a, int b)
{
    return (sumOfDiv(a) == b &&
            sumOfDiv(b) == a);
}

/*This function prints count
of amicable pairs present
in the input array*/

static int countPairs(int []arr, int n)
{

/*    Map to store the numbers*/

    HashSet<int> s = new HashSet<int>();
    int count = 0;
    for (int i = 0; i < n; i++)
        s.Add(arr[i]);

/*    Iterate through each number,
    and find the sum of proper
    divisors and check if it's
    also present in the array*/

    for (int i = 0; i < n; i++)
    {
        if (s.Contains(sumOfDiv(arr[i])))
        {

/*            It's sum of proper divisors*/

            int sum = sumOfDiv(arr[i]);
            if (isAmicable(arr[i], sum))
                count++;
        }
    }

/*    As the pairs are counted
    twice, thus divide by 2*/

    return count / 2;
}

/*Driver code*/

public static void Main(String[] args)
{
    int []arr1 = { 220, 284, 1184,
                   1210, 2, 5 };
    int n1 = arr1.Length;
    Console.WriteLine(countPairs(arr1, n1));
    int []arr2 = { 2620, 2924, 5020,
                   5564, 6232, 6368 };
    int n2 = arr2.Length;
    Console.WriteLine(countPairs(arr2, n2));
}
}

/*C# program for finding maximum area
possible of a rectangle*/

using System;
using System.Collections;
class GFG
{

/*function for finding max area*/

static int findArea(int []arr, int n)
{

/*    sort array in non-increasing order*/

    Array.Sort(arr);
    Array.Reverse(arr);

/*    Initialize two sides of rectangle*/

    int[] dimension = { 0, 0 };

/*    traverse through array*/

    for (int i = 0, j = 0;
             i < n - 1 && j < 2; i++)

/*        if any element occurs twice
        store that as dimension*/

        if (arr[i] == arr[i + 1])
            dimension[j++] = arr[i++];

/*    return the product of dimensions*/

    return (dimension[0] * dimension[1]);
}

/*Driver Code*/

public static void Main(String []args)
{
    int []arr = { 4, 2, 1, 4, 6, 6, 2, 5 };
    int n = arr.Length;
    Console.Write(findArea(arr, n));
}
}

/*c# program for finding maximum 
area possible of a rectangle*/

using System;
using System.Collections.Generic;
public class GFG
{

/*    function for finding max area*/

    public static int findArea(int[] arr, int n)
    {
        ISet<int> s = new HashSet<int>();

/*        traverse through array*/

        int first = 0, second = 0;
        for (int i = 0; i < n; i++)
        {

/*            If this is first occurrence of 
            arr[i], simply insert and continue*/

            if (!s.Contains(arr[i]))
            {
                s.Add(arr[i]);
                continue;
            }

/*            If this is second (or more) 
            occurrence, update first and 
            second maximum values.*/

            if (arr[i] > first)
            {
                second = first;
                first = arr[i];
            }
            else if (arr[i] > second)
            {
                second = arr[i];
            }
        }

/*        return the product of dimensions*/

        return (first * second);
    }

/*    driver function*/

    public static void Main(string[] args)
    {
        int[] arr = new int[] {4, 2, 1, 4, 6, 6, 2, 5};
        int n = arr.Length;
        Console.WriteLine(findArea(arr, n));
    }
}

/*C# program for Game of Replacement */

using System;
using System.Collections.Generic;
public class GameOfReplacingArrayElements 
{

/*    Function return which player win the game */

    public static int playGame(int []arr)
    {

/*        Create hash that will stores 
        all distinct element */

        HashSet<int> set = new HashSet<int>();

/*        Traverse an array element */

        foreach(int i in arr)
            set.Add(i);
        return (set.Count % 2 == 0) ? 1 : 2;
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        int []arr = { 1, 1, 2, 2, 2, 2 }; 
        Console.Write("Player " + playGame(arr) + " wins");
    }
}

/*C# implementation to find length of longest
strict bitonic subsequence*/

using System;
using System.Collections.Generic;
class GfG
{

/*    function to find length of longest
    strict bitonic subsequence*/

    static int longLenStrictBitonicSub(int []arr, int n)
    {

/*        hash table to map the array
        element with the length of
        the longest subsequence of
        which it is a part of and
        is the last/first element of
        that subsequence*/

        Dictionary<int, int> inc = new Dictionary<int, int> ();
        Dictionary<int, int> dcr = new Dictionary<int, int> ();

/*        arrays to store the length
        of increasing and decreasing
        subsequences which end at them
        or start from them*/

        int []len_inc = new int[n];
        int []len_dcr = new int[n];

/*        to store the length of longest strict
        bitonic subsequence*/

        int longLen = 0;

/*        traverse the array elements
        from left to right*/

        for (int i = 0; i < n; i++)
        {

/*            initialize current length
            for element arr[i] as 0*/

            int len = 0;

/*            if 'arr[i]-1' is in 'inc'*/

            if (inc.ContainsKey(arr[i] - 1))
                len = inc[arr[i] - 1];

/*            update arr[i] subsequence length     
            in 'inc' and in len_inc[]*/

            len_inc[i] = len + 1;
            if (inc.ContainsKey(arr[i]))
            {
                inc.Remove(arr[i]);
                inc.Add(arr[i], len_inc[i]);
            }
            else
                inc.Add(arr[i], len_inc[i]);
        }

/*        traverse the array elements
        from right to left*/

        for (int i = n - 1; i >= 0; i--)
        {

/*            initialize current length
            for element arr[i] as 0*/

            int len = 0;

/*            if 'arr[i]-1' is in 'dcr'*/

            if (dcr.ContainsKey(arr[i] - 1))
                len = dcr[arr[i] - 1];

/*            update arr[i] subsequence length in 'dcr'
            and in len_dcr[]*/

            len_dcr[i] = len + 1;
            if (dcr.ContainsKey(arr[i]))
            {
                dcr.Remove(arr[i]);
                dcr.Add(arr[i], len_dcr[i]);
            }
            else
                dcr.Add(arr[i], len_dcr[i]);
        }

/*        calculating the length of all the strict
        bitonic subsequence*/

        for (int i = 0; i < n; i++)
            if (longLen < (len_inc[i] + len_dcr[i] - 1))
                longLen = len_inc[i] + len_dcr[i] - 1;

/*        required longest length strict
        bitonic subsequence*/

        return longLen;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = {1, 5, 2, 3, 4, 5, 3, 2};
        int n = arr.Length;
        Console.WriteLine("Longest length strict " +
                            "bitonic subsequence = " +
                            longLenStrictBitonicSub(arr, n));
    }
}

/*C# program to find last seen element in 
an array. */

using System;
using System.Collections.Generic;
class GFG 
{

/*Returns last seen element in arr[]*/

static int lastSeenElement(int []a, int n)
{

/*    Store last occurrence index of 
    every element*/

    Dictionary<int, 
               int> hash = new Dictionary<int,
                                          int>();
    for (int i = 0; i < n; i++)
    {
        if(hash.ContainsKey(a[i]))
        {
            hash[a[i]] = i;
        }
        else
        {
            hash.Add(a[i], i);
        }
    }

/*    Find an element in hash with minimum 
    index value*/

    int res_ind = int.MaxValue, res = 0;
    foreach(KeyValuePair<int, int> x in hash)
    {
        if (x.Value < res_ind)
        {
            res_ind = x.Value;
            res = x.Key;
        } 
    }
    return res;
}

/*Driver Code*/

public static void Main(String[] args) 
{
    int []a = { 2, 1, 2, 2, 4, 1 };
    int n = a.Length;
    Console.WriteLine(lastSeenElement(a, n));
}
}

/*C# program for array rotation*/

using System;
class GFG {

/*Function to left Rotate arr[] of
  size n by 1*/

    static void leftRotatebyOne(int[] arr, int n)
    {
        int i, temp = arr[0];
        for (i = 0; i < n - 1; i++)
            arr[i] = arr[i + 1];
        arr[n-1] = temp;
    }

/* Function to left rotate arr[]
    of size n by d*/

    static void leftRotate(int[] arr, int d,
                           int n)
    {
        for (int i = 0; i < d; i++)
            leftRotatebyOne(arr, n);
    }

/* utility function to print an array */

    static void printArray(int[] arr, int size)
    {
        for (int i = 0; i < size; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 1, 2, 3, 4, 5, 6, 7 };
        leftRotate(arr, 2, 7);
        printArray(arr, 7);
    }
}

using System;
class GFG{

/*Wrapper over the recursive function
leftRotateRec()
It left rotates []arr by d.*/

public static void leftRotate(int []arr,
                              int d, int n)
{
    leftRotateRec(arr, 0, d, n);
}
public static void leftRotateRec(int []arr, int i,
                                 int d, int n)
{

/*    Return If number of elements
    to be rotated is zero or equal
    to array size*/

    if(d == 0 || d == n)
        return;

/*    If number of elements to be rotated
    is exactly half of array size*/

    if(n - d == d)
    {
        swap(arr, i, n - d + i, d);
        return;
    }

/*    If A is shorter*/

    if(d < n - d)
    {
        swap(arr, i, n - d + i, d);
        leftRotateRec(arr, i, d, n - d);    
    }

/*    If B is shorter*/

    else
    {
        swap(arr, i, d, n - d);
        leftRotateRec(arr, n - d + i,
                       2 * d - n, d);
    }
}

/*Function to print an array*/

public static void printArray(int []arr,
                              int size)
{
    int i;
    for(i = 0; i < size; i++)
        Console.Write(arr[i] + " ");
    Console.WriteLine();
}

/*This function swaps d elements
starting at index fi with d elements
starting at index si*/

public static void swap(int []arr, int fi,
                        int si, int d)
{
    int i, temp;
    for(i = 0; i < d; i++)
    {
        temp = arr[fi + i];
        arr[fi + i] = arr[si + i];
        arr[si + i] = temp;
    }
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []arr = { 1, 2, 3, 4, 5, 6, 7 };
    leftRotate(arr, 2, 7);
    printArray(arr, 7);    
}
}

/* C# program to search an element in
sorted and rotated array using
single pass of Binary Search*/

using System;
class GFG {

/*    Returns index of key in arr[l..h]
    if key is present, otherwise
    returns -1*/

    static int search(int[] arr, int l, int h,
                      int key)
    {
        if (l > h)
            return -1;
        int mid = (l + h) / 2;
        if (arr[mid] == key)
            return mid;

/* If arr[l...mid] is sorted */

        if (arr[l] <= arr[mid]) {

/* As this subarray is sorted, we
            can quickly check if key lies in
            half or other half */

            if (key >= arr[l] && key <= arr[mid])
                return search(arr, l, mid - 1, key);

/*If key not lies in first half subarray,
           Divide other half  into two subarrays,
           such that we can quickly check if key lies
           in other half */

            return search(arr, mid + 1, h, key);
        }

/* If arr[l..mid] is not sorted,
        then arr[mid... r] must be sorted*/

        if (key >= arr[mid] && key <= arr[h])
            return search(arr, mid + 1, h, key);
        return search(arr, l, mid - 1, key);
    }

/*    main function*/

    public static void Main()
    {
        int[] arr = { 4, 5, 6, 7, 8, 9, 1, 2, 3 };
        int n = arr.Length;
        int key = 6;
        int i = search(arr, 0, n - 1, key);
        if (i != -1)
            Console.WriteLine("Index: " + i);
        else
            Console.WriteLine("Key not found");
    }
}

/*C# program to find a pair with a given
sum in a sorted and rotated array*/

using System;
class PairInSortedRotated
{

/*    This function returns true if arr[0..n-1]
    has a pair with sum equals to x.*/

    static bool pairInSortedRotated(int []arr,
                                    int n, int x)
    {

/*        Find the pivot element*/

        int i;
        for (i = 0; i < n - 1; i++)
            if (arr[i] > arr[i + 1])
                break;

/*        l is now index of smallest element       */

        int l = (i + 1) % n;

/*        r is now index of largest element               */

        int r = i;

/*        Keep moving either l or r till they meet*/

        while (l != r)
        {

/*            If we find a pair with sum x, we
            return true*/

            if (arr[l] + arr[r] == x)
                return true;

/*            If current pair sum is less, 
            move to the higher sum*/

            if (arr[l] + arr[r] < x)
                l = (l + 1) % n;

/*            Move to the lower sum side   */

            else
                r = (n + r - 1) % n;
        }
        return false;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int []arr = {11, 15, 6, 8, 9, 10};
        int sum = 16;
        int n = arr.Length;
        if (pairInSortedRotated(arr, n, sum))
            Console.WriteLine("Array has two elements" +
                                       " with sum 16");
        else
        Console.WriteLine("Array doesn't have two" +
                            " elements with sum 16 ");
    }
}

/*C# program to find
number of pairs with
a given sum in a sorted
and rotated array.*/

using System;
class GFG
{

/*This function returns
count of number of pairs
with sum equals to x.*/

static int pairsInSortedRotated(int []arr,
                                int n, int x)
{

/*    Find the pivot element.
    Pivot element is largest
    element of array.*/

    int i;
    for (i = 0; i < n - 1; i++)
        if (arr[i] > arr[i + 1])
            break;

/*    l is index of
    smallest element.*/

    int l = (i + 1) % n;

/*    r is index of
    largest element.*/

    int r = i;

/*    Variable to store
    count of number
    of pairs.*/

    int cnt = 0;

/*    Find sum of pair
    formed by arr[l]
    and arr[r] and
    update l, r and
    cnt accordingly.*/

    while (l != r)
    {

/*        If we find a pair with
        sum x, then increment
        cnt, move l and r to
        next element.*/

        if (arr[l] + arr[r] == x)
        {
            cnt++;

/*            This condition is required
            to be checked, otherwise
            l and r will cross each
            other and loop will never
            terminate.*/

            if(l == (r - 1 + n) % n)
            {
                return cnt;
            }
            l = (l + 1) % n;
            r = (r - 1 + n) % n;
        }

/*        If current pair sum
        is less, move to
        the higher sum side.*/

        else if (arr[l] + arr[r] < x)
            l = (l + 1) % n;

/*        If current pair sum
        is greater, move
        to the lower sum side.*/

        else
            r = (n + r - 1) % n;
    }
    return cnt;
}

/*Driver Code*/

static public void Main ()
{
    int []arr = {11, 15, 6, 7, 9, 10};
    int sum = 16;
    int n = arr.Length;
    Console.WriteLine(
            pairsInSortedRotated(arr, n, sum));
}
}

/*C# program to find max value of i*arr[i]*/

using System;
class Test
{
    static int []arr = new int[]{10, 1, 2, 3, 4,
                                  5, 6, 7, 8, 9};

/*    Returns max possible value of i*arr[i]*/

    static int maxSum()
    {

/*        Find array sum and i*arr[i]
        with no rotation
Stores sum of arr[i]*/

int arrSum = 0;

/*Stores sum of i*arr[i]*/

int currVal = 0; 
        for (int i = 0; i < arr.Length; i++)
        {
            arrSum = arrSum + arr[i];
            currVal = currVal + (i * arr[i]);
        }

/*        Initialize result as 0 rotation sum*/

        int maxVal = currVal;

/*        Try all rotations one by one and find
        the maximum rotation sum.*/

        for (int j = 1; j < arr.Length; j++)
        {
            currVal = currVal + arrSum - arr.Length *
                                arr[arr.Length - j];
            if (currVal > maxVal)
                maxVal = currVal;
        }

/*        Return result*/

        return maxVal;
    }

/*    Driver Code*/

    public static void Main()
    {
        Console.WriteLine("Max sum is " + maxSum());
    }
}

/*A Naive C# program to find
maximum sum rotation*/

using System;
class GFG {

/*    Returns maximum value of i*arr[i]*/

    static int maxSum(int[] arr, int n)
    {

/*        Initialize result*/

        int res = int.MinValue;

/*        Consider rotation beginning with i
        for all possible values of i.*/

        for (int i = 0; i < n; i++) {

/*            Initialize sum of current rotation*/

            int curr_sum = 0;

/*            Compute sum of all values. We don't
            acutally rotation the array, but compute
            sum by finding ndexes when arr[i] is
            first element*/

            for (int j = 0; j < n; j++)
            {
                int index = (i + j) % n;
                curr_sum += j * arr[index];
            }

/*            Update result if required*/

            res = Math.Max(res, curr_sum);
        }
        return res;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 8, 3, 1, 2 };
        int n = arr.Length;
        Console.WriteLine(maxSum(arr, n));
    }
}

/*An efficient C# program to compute
maximum sum of i*arr[i]*/

using System;
class GFG {
    static int maxSum(int []arr, int n)
    {

/*        Compute sum of all array elements*/

        int cum_sum = 0;
        for (int i = 0; i < n; i++)
            cum_sum += arr[i];

/*        Compute sum of i*arr[i] for
        initial configuration.*/

        int curr_val = 0;
        for (int i = 0; i < n; i++)
            curr_val += i * arr[i];

/*        Initialize result*/

        int res = curr_val;

/*        Compute values for other iterations*/

        for (int i = 1; i < n; i++)
        {

/*            Compute next value using previous
            value in O(1) time*/

            int next_val = curr_val - (cum_sum -
                      arr[i - 1]) + arr[i - 1] *
                                        (n - 1);

/*            Update current value*/

            curr_val = next_val;

/*            Update result if required*/

            res = Math.Max(res, next_val);
        }
        return res;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = {8, 3, 1, 2};
        int n = arr.Length;
        Console.Write(maxSum(arr, n));
    }
}

/*c# program to find number of
rotations in a sorted and rotated
array.*/

using System;
class LinearSearch
{

/*    Returns count of rotations for an
    array which is first sorted in
    ascending order, then rotated*/

    static int countRotations(int []arr, int n)
    {

/*        We basically find index of minimum
        element*/

        int min = arr[0], min_index = -1;
        for (int i = 0; i < n; i++)
        {
            if (min > arr[i])
            {
                min = arr[i];
                min_index = i;
            }
        }
        return min_index;
    }

/*    Driver program to test above functions*/

    public static void Main ()
    {
        int []arr = {15, 18, 2, 3, 6, 12};
        int n = arr.Length;
    Console.WriteLine(countRotations(arr, n));
    }
}

/*C# program to find number of
rotations in a sorted and rotated
array.*/

using System;
class BinarySearch
{

/*    Returns count of rotations for an array
    which is first sorted in ascending order,
    then rotated*/

    static int countRotations(int []arr, int low, int high)
    {

/*        This condition is needed to handle
        the case when array is not rotated
        at all*/

        if (high < low)
            return 0;

/*        If there is only one element left*/

        if (high == low)
            return low;

/*        Find mid*/
        int mid = low + (high - low)/2;

/*        Check if element (mid+1) is minimum
        element. Consider the cases like
        {3, 4, 5, 1, 2}*/

        if (mid < high && arr[mid+1] < arr[mid])
            return (mid + 1);

/*        Check if mid itself is minimum element*/

        if (mid > low && arr[mid] < arr[mid - 1])
            return mid;

/*        Decide whether we need to go to left
        half or right half*/

        if (arr[high] > arr[mid])
            return countRotations(arr, low, mid - 1);
        return countRotations(arr, mid + 1, high);
    }

/*    Driver program to test above functions*/

    public static void Main ()
    {
        int []arr = {15, 18, 2, 3, 6, 12};
        int n = arr.Length;
    Console.WriteLine(countRotations(arr, 0, n-1));
    }
}

/*C# implementation of left rotation of
an array K number of times*/

using System;
class LeftRotate
{

/*    Fills temp[] with two copies of arr[]*/

    static void preprocess(int []arr, int n,
                                int[] temp)
    {

/*        Store arr[] elements at i and i + n*/

        for (int i = 0; i<n; i++)
            temp[i] = temp[i + n] = arr[i];
    }

/*    Function to left rotate an array k time*/

    static void leftRotate(int []arr, int n, int k,
                                    int []temp)
    {

/*        Starting position of array after k
        rotations in temp[] will be k % n*/

        int start = k % n;

/*        Print array after k rotations*/

        for (int i = start; i < start + n; i++)
        Console.Write(temp[i] + " ");
        Console.WriteLine();
    }

/*    Driver program*/

    public static void Main ()
    {
        int []arr = {1, 3, 5, 7, 9};
        int n = arr.Length;
        int []temp = new int[2*n];
        preprocess(arr, n, temp);
        int k = 2;
        leftRotate(arr, n, k, temp);
        k = 3;
        leftRotate(arr, n, k, temp);
        k = 4;
        leftRotate(arr, n, k, temp);
    }
}

