/*C# code to rotate an array
and answer the index query*/

using System;
class GFG
{

/*    Function to compute the
    element at given index*/

    static int findElement(int []arr, int [,]ranges,
                           int rotations, int index)
    {
        for (int i = rotations - 1; i >= 0; i--)
        {

/*            Range[left...right]*/

            int left = ranges[i, 0];
            int right = ranges[i, 1];

/*            Rotation will not
            have any effect*/

            if (left <= index &&
                right >= index)
            {
                if (index == left)
                    index = right;
                else
                    index--;
            }
        }

/*        Returning new element*/

        return arr[index];
    }

/*    Driver Code*/

    public static void Main ()
    {
        int []arr = { 1, 2, 3, 4, 5 };

/*        No. of rotations*/

        int rotations = 2;

/*        Ranges according
        to 0-based indexing*/

        int [,]ranges = { { 0, 2 },
                          { 0, 3 } };
        int index = 1;
        Console.Write(findElement(arr, ranges,
                                    rotations,
                                      index));
    }
}

/*C# program to split array
and move first part to end.*/

using System;
class GFG {
    public static void splitArr(int[] arr, int n,
                                int k)
    {
        for (int i = 0; i < k; i++)
        {

/*            Rotate array by 1.*/

            int x = arr[0];
            for (int j = 0; j < n - 1; ++j)
                arr[j] = arr[j + 1];
            arr[n - 1] = x;
        }
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = {12, 10, 5, 6, 52, 36};
        int n = arr.Length;
        int position = 2;
        splitArr(arr, 6, position);
        for (int i = 0; i < n; ++i)
            Console.Write(arr[i] + " ");
    }
}

/*C# program to split array
and move first part to end.*/

using System;
class GFG
{

/*    Function to spilt array and
    move first part to end*/

    public static void SplitAndAdd(int[] A,
                                   int length,
                                   int rotation)
    {

/*        make a temporary array with double the size*/

        int[] tmp = new int[length * 2];

/*        copy array element in to new array twice*/

        Array.Copy(A, 0, tmp, 0, length);
        Array.Copy(A, 0, tmp, length, length);
        for (int i = rotation; i < rotation + length; i++)
        {
            A[i - rotation] = tmp[i];
        }
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        int[] arr = new int[] {12, 10, 5, 6, 52, 36};
        int n = arr.Length;
        int position = 2;
        SplitAndAdd(arr, n, position);
        for (int i = 0; i < n; ++i)
        {
            Console.Write(arr[i] + " ");
        }
    }
}

/*C# program for above approach*/

using System;
class GFG {

/*    Function to tranform the array*/

    static void fixArray(int[] ar, int n)
    {
        int i, j, temp;

/*        Iterate over the array*/

        for(i = 0; i < n; i++)
        {
            for(j = 0; j < n; j++)
            {

/*                Checf is any ar[j]
                exists such that
                ar[j] is equal to i*/

                if (ar[j] == i)
                {
                    temp = ar[j];
                    ar[j] = ar[i];
                    ar[i] = temp;
                    break;
                }
            }
        }

/*        Iterate over array*/

        for(i = 0; i < n; i++)
        {

/*            If not present*/

            if (ar[i] != i)
            {
                ar[i] = -1;
            }
        }

/*        Print the output*/

        Console.WriteLine("Array after Rearranging");
        for(i = 0; i < n; i++)
        {
            Console.Write(ar[i] + " ");
        }
    }

/*      Driver Code*/

  static void Main() {
        int[] ar = { -1, -1, 6, 1, 9,
                     3, 2, -1, 4, -1 };
        int n = ar.Length;

/*        Function Call*/

        fixArray(ar, n);
  }
}

/*C# program to rearrange the array
as per the given condition*/

using System;
public class GfG {

/*    Function to rearrange the array*/

    public static void rearrangeArr(int []arr, int n)
    {

/*        total even positions*/

        int evenPos = n / 2;

/*        total odd positions*/

        int oddPos = n - evenPos;
        int[] tempArr = new int [n];

/*        copy original array in an
        auxiliary array*/

        for (int i = 0; i < n; i++)
            tempArr[i] = arr[i];

/*        sort the auxiliary array*/

        Array.Sort(tempArr);
        int j = oddPos - 1;

/*        Fill up odd position in
        original array*/

        for (int i = 0; i < n; i += 2) {
            arr[i] = tempArr[j];
            j--;
        }
        j = oddPos;

/*        Fill up even positions in
        original array*/

        for (int i = 1; i < n; i += 2) {
            arr[i] = tempArr[j];
            j++;
        }

/*        display array*/

        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] arr = new int []{ 1, 2, 3, 4, 5, 6, 7 };
        int size = 7;
        rearrangeArr(arr, size);
    }
}

