    {
        int[] arr = { 0, 1, 9, 8, 4, 0, 0, 2,
                    7, 0, 6, 0, 9 };
        int n = arr.Length;
        Console.Write("Original array: ");
        printArray(arr, n);
        moveZerosToEnd(arr, n);
        Console.Write("\nModified array: ");
        printArray(arr, n);
    }
}

/*C# program to find minimum 
swaps required to club all
elements less than or equals
to k together*/

using System;
class GFG {

/*    Utility function to find minimum swaps
    required to club all elements less than
    or equals to k together*/

    static int minSwap(int []arr, int n, int k) {

/*        Find count of elements which are
        less than equals to k*/

        int count = 0;
        for (int i = 0; i < n; ++i)
        if (arr[i] <= k)
            ++count;

/*        Find unwanted elements in current
        window of size 'count'*/

        int bad = 0;
        for (int i = 0; i < count; ++i)
        if (arr[i] > k)
            ++bad;

/*        Initialize answer with 'bad' value of
        current window*/

        int ans = bad;
        for (int i = 0, j = count; j < n; ++i, ++j) {

/*            Decrement count of previous window*/

            if (arr[i] > k)
                --bad;

/*            Increment count of current window*/

            if (arr[j] > k)
                ++bad;

/*            Update ans if count of 'bad'
            is less in current window*/

            ans = Math.Min(ans, bad);
        }
        return ans;
    }

/*    Driver code*/

    public static void Main() 
    {
        int []arr = {2, 1, 5, 6, 3};
        int n = arr.Length;
        int k = 3;
        Console.WriteLine(minSwap(arr, n, k));
        int []arr1 = {2, 7, 9, 5, 8, 7, 4};
        n = arr1.Length;
        k = 5;
        Console.WriteLine(minSwap(arr1, n, k));
    }
}

