    if(i < (length - 1))
      Console.Write(",");
    else
      Console.Write("]\n");
  }
}
static void reverse(int []array,
                    int start, int end)
{
  while(start < end)
  {
    int temp = array[start];
    array[start] = array[end];
    array[end] = temp;
    start++;
    end--;
  }
}

/*Rearrange the array with
all negative integers on left
and positive integers on right
use recursion to split the
array with first element
as one half and the rest
array as another and then
merge it with head of
the array in each step */

static void rearrange(int []array,
                      int start, int end)
{

/*  exit condition*/

  if(start == end)
    return;

/*  rearrange the array
  except the first element
  in each recursive call*/

  rearrange(array,
            (start + 1), end);

/*  If the first element of
  the array is positive,
  then right-rotate the
  array by one place first
  and then reverse the merged array.*/

  if(array[start] >= 0)
  {
    reverse(array, (start + 1), end);
    reverse(array, start, end);
  }
}

/*Driver code*/

public static void Main(string[] args)
{
  int []array = {-12, -11, -13,
                 -5, -6, 7, 5, 3, 6};
  int length = array.Length;
  int countNegative = 0;
  for(int i = 0; i < length; i++)
  {
    if(array[i] < 0)
      countNegative++;
  }
  Console.Write("array: ");
  printArray(array, length);
  rearrange(array, 0, (length - 1));
  reverse(array, countNegative, (length - 1));
  Console.Write("rearranged array: ");
  printArray(array, length);
}
}

/*C# implementation to rearrange the
array elements after modification*/

using System;
class GFG {

/*    function which pushes all
    zeros to end of an array.*/

    static void pushZerosToEnd(int[] arr, int n)
    {

/*        Count of non-zero elements*/

        int count = 0;

/*        Traverse the array. If element
        encountered is non-zero, then
        replace the element at index
        'count' with this element*/

        for (int i = 0; i < n; i++)
            if (arr[i] != 0)

/*                here count is incremented*/

                arr[count++] = arr[i];

/*        Now all non-zero elements
        have been shifted to front and
        'count' is set as index of first 0.
        Make all elements 0 from count to end.*/

        while (count < n)
            arr[count++] = 0;
    }

/*    function to rearrange the array
    elements after modification*/

    static void modifyAndRearrangeArr(int[] arr, int n)
    {

/*        if 'arr[]' contains a single element
        only*/

        if (n == 1)
            return;

/*        traverse the array*/

        for (int i = 0; i < n - 1; i++) {

/*            if true, perform the required modification*/

            if ((arr[i] != 0) && (arr[i] == arr[i + 1])) {

/*                double current index value*/

                arr[i] = 2 * arr[i];

/*                put 0 in the next index*/

                arr[i + 1] = 0;

/*                increment by 1 so as to move two
                indexes ahead during loop iteration*/

                i++;
            }
        }

/*        push all the zeros at
        the end of 'arr[]'*/

        pushZerosToEnd(arr, n);
    }

/*    function to print the array elements*/

    static void printArray(int[] arr, int n)
    {
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
        Console.WriteLine();
    }

/*    Driver program to test above*/

    public static void Main()
    {
        int[] arr = { 0, 2, 2, 2, 0, 6, 6, 0, 0, 8 };
        int n = arr.Length;
        Console.Write("Original array: ");
        printArray(arr, n);
        modifyAndRearrangeArr(arr, n);
        Console.Write("Modified array: ");
        printArray(arr, n);
    }
}

