/*A O(n) time and O(1) extra space C# program to
sort an array according to given indexes*/

using System;
public class Test
{
    static int []arr = new int[]{50, 40, 70, 60, 90};
    static int []index = new int[]{3,  0,  4,  1,  2};

/*    Method to reorder elements of arr[] according
    to index[]*/

    static void reorder()
    {

/*        Fix all elements one by one*/

        for (int i=0; i<arr.Length; i++)
        {

/*            While index[i] and arr[i] are not fixed*/

            while (index[i] != i)
            {

/*                Store values of the target (or correct)
                position before placing arr[i] there*/

                int  oldTargetI  = index[index[i]];
                char oldTargetE  = (char)arr[index[i]];

/*                Place arr[i] at its target (or correct)
                position. Also copy corrected index for
                new position*/

                arr[index[i]] = arr[i];
                index[index[i]] = index[i];

/*                Copy old target values to arr[i] and
                index[i]*/

                index[i] = oldTargetI;
                arr[i]   = oldTargetE;
            }
        }
    }

/*    Driver method to test the above function*/

    public static void Main()
    {
        reorder();
        Console.WriteLine("Reordered array is: ");
        Console.WriteLine(String.Join(" ",arr));
        Console.WriteLine("Modified Index array is:");
        Console.WriteLine(String.Join(" ",index));
    }
}

/*C# code to reorder an array
according to given indices*/

using System;
using System.Collections.Generic;
class GFG{
static int heapSize;
public static void heapify(int[] arr,
                           int[] index,
                           int i)
{
    int largest = i;

/*    left child in 0 based indexing*/

    int left = 2 * i + 1;

/*    right child in 1 based indexing*/

    int right = 2 * i + 2;

/*    Find largest index from root,
    left and right child*/

    if (left < heapSize &&
        index[left] > index[largest] )
    {
        largest = left;
    }
    if (right < heapSize &&
        index[right] > index[largest] )
    {
        largest = right;
    }
    if (largest != i)
    {

/*        Swap arr whenever index is swapped*/

        int temp = arr[largest];
        arr[largest] = arr[i];
        arr[i] = temp;
        temp = index[largest];
        index[largest] = index[i];
        index[i] = temp;
        heapify(arr, index, largest);
    }
}
public static void heapSort(int[] arr,
                            int[] index,
                            int n)
{

/*    Build heap*/

    for(int i = (n - 1) / 2 ; i >= 0 ; i--)
    {
        heapify(arr, index, i);
    }

/*    Swap the largest element of
    index(first element)
    with the last element*/

    for(int i = n - 1 ; i > 0 ; i--)
    {
        int temp = index[0];
        index[0] = index[i];
        index[i] = temp;

/*        Swap arr whenever index
        is swapped*/

        temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;
        heapSize--;
        heapify(arr, index, 0);
    }
}

/*Driver Code*/

static void Main()
{
    int[] arr = { 50, 40, 70, 60, 90 };
    int[] index = { 3, 0, 4, 1, 2 };
    int n = arr.Length;
    heapSize = n;
    heapSort(arr, index, n);
    Console.WriteLine("Reordered array is: ");
    for(int i = 0 ; i < n ; i++)
        Console.Write(arr[i] + " ");
    Console.WriteLine();
    Console.WriteLine("Modified Index array is: ");
    for(int i = 0; i < n; i++)
        Console.Write(index[i] + " ");
}
}

/*C# program to Rearrange positive
and negative numbers in a array*/

using System;
class GFG {

/*    A utility function to print
    an array of size n*/

    static void printArray(int[] arr, int n)
    {
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
        Console.WriteLine();
    }

/*    Function to Rearrange positive and negative
    numbers in a array*/

    static void RearrangePosNeg(int[] arr, int n)
    {
        int key, j;
        for (int i = 1; i < n; i++) {
            key = arr[i];

/*            if current element is positive
            do nothing*/

            if (key > 0)
                continue;

/* if current element is negative,
            shift positive elements of arr[0..i-1],
            to one position to their right */

            j = i - 1;
            while (j >= 0 && arr[j] > 0) {
                arr[j + 1] = arr[j];
                j = j - 1;
            }

/*            Put negative element at its right position*/

            arr[j + 1] = key;
        }
    }

/*    Driver program*/

    public static void Main()
    {
        int[] arr = { -12, 11, -13, -5, 6,
                      -7, 5, -3, -6 };
        int n = arr.Length;
        RearrangePosNeg(arr, n);
        printArray(arr, n);
    }
}

/*C# program to Rearrange positive and negative
numbers in a array*/

using System;
class GFG {

/* Function to print an array */

    static void printArray(int[] A, int size)
    {
        for (int i = 0; i < size; i++)
            Console.Write(A[i] + " ");
        Console.WriteLine("");
        ;
    }

/* Function to reverse an array. An array can be
reversed in O(n) time and O(1) space. */

    static void reverse(int[] arr, int l, int r)
    {
        if (l < r) {
            arr = swap(arr, l, r);
            reverse(arr, ++l, --r);
        }
    }

/*    Merges two subarrays of arr[].
    First subarray is arr[l..m]
    Second subarray is arr[m+1..r]*/

    static void merge(int[] arr, int l, int m, int r)
    {

/*Initial index of 1st subarray*/

int i = l;

/*Initial index of IInd*/

int j = m + 1; 
        while (i <= m && arr[i] < 0)
            i++;

/*        arr[i..m] is positive*/

        while (j <= r && arr[j] < 0)
            j++;

/*        arr[j..r] is positive
        reverse positive part of
        left sub-array (arr[i..m])*/

        reverse(arr, i, m);

/*        reverse negative part of
        right sub-array (arr[m+1..j-1])*/

        reverse(arr, m + 1, j - 1);

/*        reverse arr[i..j-1]*/

        reverse(arr, i, j - 1);
    }

/*    Function to Rearrange positive and negative
    numbers in a array*/

    static void RearrangePosNeg(int[] arr, int l, int r)
    {
        if (l < r) {

/*            Same as (l+r)/2, but avoids overflow for
            large l and h*/

            int m = l + (r - l) / 2;

/*            Sort first and second halves*/

            RearrangePosNeg(arr, l, m);
            RearrangePosNeg(arr, m + 1, r);
            merge(arr, l, m, r);
        }
    }
    static int[] swap(int[] arr, int i, int j)
    {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        return arr;
    }

/* Driver code*/

    public static void Main()
    {
        int[] arr = { -12, 11, -13, -5, 6, -7, 5, -3, -6 };
        int arr_size = arr.Length;
        RearrangePosNeg(arr, 0, arr_size - 1);
        printArray(arr, arr_size);
    }
}

/*C# implementation of the above approach*/

using System;
public class GFG
{
  public static void RearrangePosNeg(int[] arr)
  {
    int i = 0;
    int j = arr.Length - 1;
    while(true)
    {

/*      Loop until arr[i] < 0 and
      still inside the array*/

      while(arr[i]<0 && i<arr.Length)
        i++;

/*      Loop until arr[j] > 0 and
      still inside the array*/

      while(arr[j]>0 && j>=0)
        j--;

/*      if i is less than j*/

      if(i<j)
      {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
      else
        break;
    }
  }

/*  Driver Code*/

  static public void Main ()
  {
    int[] arr = {-12, 11, -13, -5, 6, -7, 5, -3, -6};
    RearrangePosNeg(arr);
    for(int i = 0; i < arr.Length; i++)
      Console.Write(arr[i] + " ");
  }
}

/*A simple C# program to rearrange contents of arr[]
such that arr[j] becomes j if arr[i] is j*/

using System;
class RearrangeArray {

/*    A simple method to rearrange 'arr[0..n-1]' so that 'arr[j]'
    becomes 'i' if 'arr[i]' is 'j'*/

    void rearrangeNaive(int[] arr, int n)
    {

/*        Create an auxiliary array of same size*/

        int[] temp = new int[n];
        int i;

/*        Store result in temp[]*/

        for (i = 0; i < n; i++)
            temp[arr[i]] = i;

/*        Copy temp back to arr[]*/

        for (i = 0; i < n; i++)
            arr[i] = temp[i];
    }

