    }
}

/*A simple C# program to rearrange
contents of arr[] such that arr[j]
becomes j if arr[i] is j*/

using System;
class GFG{

/*    A simple method to rearrange
    'arr[0..n-1]' so that 'arr[j]'
    becomes 'i' if 'arr[i]' is 'j'*/

    static void rearrange(int[] arr, int n)
    {
        for (int i = 0; i < n; i++) {

/*            retrieving old value and
            storing with the new one*/

            arr[arr[i] % n] += i * n;
        }
        for (int i = 0; i < n; i++) {

/*            retrieving new value*/

            arr[i] /= n;
        }
    }

/*    A utility function to print
    contents of arr[0..n-1]*/

    static void printArray(int[] arr, int n)
    {
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
        Console.WriteLine();
    }

/*    Driver program*/

    static public void Main ()
    {
        int[] arr = { 2, 0, 1, 4, 5, 3 };
        int n = arr.Length;
        Console.WriteLine("Given array is : ");
        printArray(arr, n);
        rearrange(arr, n);
        Console.WriteLine("Modified array is :");
        printArray(arr, n);
    }
}

/*C# program to rearrange
an array in minimum
maximum form*/

using System;
class GFG {

/*    Prints max at first position,
    min at second position second
    max at third position, second
    min at fourth position and so on.*/

    static void rearrage(int[] arr, int n)
    {

/*        Auxiliary array to
        hold modified array*/

        int[] temp = new int[n];

/*        Indexes of smallest
        and largest elements
        from remaining array.*/

        int small = 0, large = n - 1;

/*        To indicate whether we
        need to copy rmaining
        largest or remaining
        smallest at next position*/

        bool flag = true;

/*        Store result in temp[]*/

        for (int i = 0; i < n; i++) {
            if (flag)
                temp[i] = arr[large--];
            else
                temp[i] = arr[small++];
            flag = !flag;
        }

/*        Copy temp[] to arr[]*/

        for (int i = 0; i < n; i++)
            arr[i] = temp[i];
    }

/*    Driver Code*/

    static void Main()
    {
        int[] arr = { 1, 2, 3, 4, 5, 6 };
        Console.WriteLine("Original Array");
        for (int i = 0; i < arr.Length; i++)
            Console.Write(arr[i] + " ");
        rearrage(arr, arr.Length);
        Console.WriteLine("\nModified Array");
        for (int i = 0; i < arr.Length; i++)
            Console.Write(arr[i] + " ");
    }
}

/*C# program to rearrange an
array in minimum maximum form*/

using System;
class main {

/*    Prints max at first position, min at second
    position, second max at third position, second
    min at fourth position and so on.*/

    public static void rearrange(int[] arr, int n)
    {

/*        initialize index of first minimum
        and first maximum element*/

        int max_idx = n - 1, min_idx = 0;

/*        store maximum element of array*/

        int max_elem = arr[n - 1] + 1;

/*        traverse array elements*/

        for (int i = 0; i < n; i++) {

/*            at even index : we have to put
            maximum element*/

            if (i % 2 == 0) {
                arr[i] += (arr[max_idx] % max_elem) * max_elem;
                max_idx--;
            }

/*            at odd index : we have to
            put minimum element*/

            else {
                arr[i] += (arr[min_idx] % max_elem) * max_elem;
                min_idx++;
            }
        }

/*        array elements back to it's original form*/

        for (int i = 0; i < n; i++)
            arr[i] = arr[i] / max_elem;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
        int n = arr.Length;
        Console.WriteLine("Original Array");
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
        Console.WriteLine();
        rearrange(arr, n);
        Console.WriteLine("Modified Array");
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }
}

/*C# program to rearrange
an array in minimum
maximum form*/

using System;
class GFG
{

/*    Prints max at first
    position, min at second
    position second max at
    third position, second
    min at fourth position
    and so on.*/

    public static void rearrange(int []arr,
                                 int n)
    {

/*        initialize index of
        first minimum and
        first maximum element*/

        int max_ele = arr[n - 1];
        int min_ele = arr[0];

/*        traverse array elements*/

        for (int i = 0; i < n; i++)
        {

/*            at even index : we have
            to put maximum element*/

            if (i % 2 == 0)
            {
                arr[i] = max_ele;
                max_ele -= 1;
            }

/*            at odd index : we have
            to put minimum element*/

            else
            {
                arr[i] = min_ele;
                min_ele += 1;
            }
        }
    }

/*    Driver code*/

    static public void Main ()
    {
        int []arr = {1, 2, 3, 4,
                     5, 6, 7, 8, 9};
        int n = arr.Length;
        Console.WriteLine("Original Array");
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
        rearrange(arr, n);
        Console.Write("\nModified Array\n");
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }
}

