/*C# program to Move All -ve Element At End
Without changing order Of Array Element*/

using System;
class GFG {

/*    Moves all -ve element to
    end of array in same order.*/

    static void segregateElements(int[] arr, int n)
    {

/*        Create an empty array to store result*/

        int[] temp = new int[n];

/*        Traversal array and store +ve element in
        temp array
index of temp*/

int j = 0; 
        for (int i = 0; i < n; i++)
            if (arr[i] >= 0)
                temp[j++] = arr[i];

/*        If array contains all positive or all
        negative.*/

        if (j == n || j == 0)
            return;

/*        Store -ve element in temp array*/

        for (int i = 0; i < n; i++)
            if (arr[i] < 0)
                temp[j++] = arr[i];

/*        Copy contents of temp[] to arr[]*/

        for (int i = 0; i < n; i++)
            arr[i] = temp[i];
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 1, -1, -3, -2, 7, 5, 11, 6 };
        int n = arr.Length;
        segregateElements(arr, n);
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }
}

