{
    int []arr = { 2, -6, 3, 5, 1};
    int n = arr.Length;
    findElements(arr, n);
}
}

/*C# program to find mean
and median of an array*/

using System;
class GFG
{

/*    Function for
    calculating mean*/

    public static double findMean(int[] a, int n)
    {
        int sum = 0;
        for (int i = 0; i < n; i++)
            sum += a[i];
        return (double)sum / (double)n;
    }

/*    Function for
    calculating median*/

    public static double findMedian(int[] a, int n)
    {

/*        First we sort
        the array*/

        Array.Sort(a);

/*        check for
        even case*/

        if (n % 2 != 0)
            return (double)a[n / 2];
        return (double)(a[(n - 1) / 2] + a[n / 2]) / 2.0;
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] a = { 1, 3, 4, 2, 7, 5, 8, 6 };
        int n = a.Length;

/*        Function call*/

        Console.Write("Mean = " + findMean(a, n) + "\n");
        Console.Write("Median = " + findMedian(a, n)
                      + "\n");
    }
}

/*C# for printing smallest k numbers in order*/

using System;
public class GfG {

/*    Function to print smallest k numbers
    in arr[0..n-1]*/

    public static void printSmall(int []arr,
                                int n, int k)
    {

/*        For each arr[i] find whether
        it is a part of n-smallest
        with insertion sort concept*/

        for (int i = k; i < n; ++i) {

/*            Find largest from top n-element*/

            int max_var = arr[k - 1];
            int pos = k - 1;
            for (int j = k - 2; j >= 0; j--)
            {
                if (arr[j] > max_var)
                {
                    max_var = arr[j];
                    pos = j;
                }
            }

/*            If largest is greater than arr[i]
            shift all element one place left*/

            if (max_var > arr[i]) {
                int j = pos;
                while (j < k - 1) {
                    arr[j] = arr[j + 1];
                    j++;
                }

/*                make arr[k-1] = arr[i]*/

                arr[k - 1] = arr[i];
            }
        }

/*        print result*/

        for (int i = 0; i < k; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver function*/

    public static void Main()
    {
        int[] arr = { 1, 5, 8, 9, 6, 7, 3, 4, 2, 0 };
        int n = 10;
        int k = 5;
        printSmall(arr, n, k);
    }
}

/*C# code to print first k pairs with
least with least sum from two arrays.*/

using System;
class KSmallestPair
{

/*    Function to find k pairs with least
    sum such that one elemennt of a pair
    is from arr1[] and other element is
    from arr2[]*/

    static void kSmallestPair(int []arr1, int n1,
                        int []arr2, int n2, int k)
    {
        if (k > n1 * n2)
        {
            Console.Write("k pairs don't exist");
            return;
        }

/*        Stores current index in arr2[] for
        every element of arr1[]. Initially
        all values are considered 0. Here
        current index is the index before
        which all elements are considered
        as part of output.*/

        int []index2 = new int[n1];
        while (k > 0)
        {

/*            Initialize current pair sum as infinite*/

            int min_sum = int.MaxValue;
            int min_index = 0;

/*            To pick next pair, traverse for all
            elements of arr1[], for every element, 
            find corresponding current element in
            arr2[] and pick minimum of all formed pairs.*/

            for (int i1 = 0; i1 < n1; i1++)
            {

/*                Check if current element of arr1[]
                plus element of array2 to be used 
                gives minimum sum*/

                if (index2[i1] < n2 && arr1[i1] +
                    arr2[index2[i1]] < min_sum)
                {

/*                    Update index that gives minimum*/

                    min_index = i1;

/*                    update minimum sum*/

                    min_sum = arr1[i1] + arr2[index2[i1]];
                }
            }
        Console.Write("(" + arr1[min_index] + ", " +
                        arr2[index2[min_index]] + ") ");
            index2[min_index]++;
            k--;
        }
    }

/*    Driver code*/

    public static void Main (String[] args)
    {
        int []arr1 = {1, 3, 11};
        int n1 = arr1.Length;
        int []arr2 = {2, 4, 8};
        int n2 = arr2.Length;
        int k = 4;
        kSmallestPair( arr1, n1, arr2, n2, k);
    }
}

/*C# program to find k-th 
absolute difference
between two elements*/

using System;
class GFG{

/*returns number of pairs 
with absolute difference 
less than or equal to mid */

static int countPairs(int[] a, 
                      int n, 
                      int mid)
{
  int res = 0;
  for(int i = 0; i < n; i++)
  {

/*    Upper bound returns pointer 
    to position of next higher 
    number than a[i]+mid in
    a[i..n-1]. We subtract 
    (ub + i + 1) from
    this position to count */

    int ub = upperbound(a, n,
                        a[i] + mid);
    res += (ub - (i - 1));
  }
  return res;
}

/*returns the upper bound*/

static int upperbound(int []a, 
                      int n, 
                      int value)
{
  int low = 0;
  int high = n;
  while(low < high)
  {
    int mid = (low + high)/2;
    if(value >= a[mid])
      low = mid + 1;
    else
      high = mid;
  }
  return low;
}

/*Returns k-th absolute 
difference*/

static int kthDiff(int []a, 
                   int n, int k)
{

/*  Sort array*/

  Array.Sort(a);

/*  Minimum absolute 
  difference*/

  int low = a[1] - a[0];
  for (int i = 1; i <= n - 2; ++i)
    low = Math.Min(low, a[i + 1] - 
                   a[i]);

/*  Maximum absolute 
  difference*/

  int high = a[n - 1] - a[0];

/*  Do binary search for 
  k-th absolute difference*/

  while (low < high)
  {
    int mid = (low + high) >> 1;
    if (countPairs(a, n, mid) < k)
      low = mid + 1;
    else
      high = mid;
  }
  return low;
}

/*Driver code*/

public static void Main(String []args)
{
  int k = 3;
  int []a = {1, 2, 3, 4};
  int n = a.Length;
  Console.WriteLine(kthDiff(a, n, k));
}
}

/*C# program to find second largest
element in an array*/

using System;
class GFG{

/*Function to print the
second largest elements*/

static void print2largest(int []arr,
                          int arr_size)
{
  int i;

/*  There should be
  atleast two elements*/

  if (arr_size < 2)
  {
    Console.Write(" Invalid Input ");
    return;
  }

/*  Sort the array*/

  Array.Sort(arr);

/*  Start from second last element
  as the largest element is at last*/

  for(i = arr_size - 2; i >= 0; i--)
  {

/*    If the element is not
    equal to largest element*/

    if (arr[i] != arr[arr_size - 1])
    {
      Console.Write("The second largest " +
                    "element is {0}\n", arr[i]);
      return;
    }
  }
  Console.Write("There is no second " +
                "largest element\n");
}

