/*C# program to find the smallest
elements missing in a sorted array.*/

using System;
class GFG
{

/*function that returns
smallest elements missing
in a sorted array.*/

    static int findFirstMissing(int []array,
                            int start, int end)
    {
        if (start > end)
            return end + 1;
        if (start != array[start])
            return start;
        int mid = (start + end) / 2;

/*        Left half has all elements from 0 to mid*/

        if (array[mid] == mid)
            return findFirstMissing(array, mid+1, end);
        return findFirstMissing(array, start, mid);
    }

/*    Driver program to test the above function*/

    public static void Main()
    {
        int []arr = {0, 1, 2, 3, 4, 5, 6, 7, 10};
        int n = arr.Length;
        Console.Write("smallest Missing element is : "
                    + findFirstMissing(arr, 0, n - 1));
    }
}

/*C# program for above approach*/

using System;
class GFG{

/*Program to find missing element */

int findFirstMissing(int[] arr , int start , 
                     int end, int first) 
{
    if (start < end) 
    {
        int mid = (start + end) / 2;

/*Index matches with value 
        at that index, means missing
        element cannot be upto that point */

        if (arr[mid] != mid+first)
            return findFirstMissing(arr, start, 
                                    mid, first);
        else
            return findFirstMissing(arr, mid + 1, 
                                    end, first);
    }
    return start + first;
}

/*Program to find Smallest 
Missing in Sorted Array*/

int findSmallestMissinginSortedArray(int[] arr) 
{

/*    Check if 0 is missing 
    in the array*/

    if (arr[0] != 0)
        return 0;

/*    Check is all numbers 0 to n - 1 
    are prsent in array*/

    if (arr[arr.Length - 1] == arr.Length - 1)
        return arr.Length;
    int first = arr[0];
    return findFirstMissing(arr, 0,
           arr.Length - 1,first);
}

/*Driver code*/

static public void Main ()
{
    GFG small = new GFG();
    int[] arr = {0, 1, 2, 3, 4, 5, 7};
    int n = arr.Length;

/*    Function Call*/

    Console.WriteLine("First Missing element is : " +
    small.findSmallestMissinginSortedArray(arr));
}
}

/* Program to return max sum such that no
two elements are adjacent */

using System;
class GFG {

/* Function to return max sum such
    that no two elements are adjacent */

    static int FindMaxSum(int []arr, int n)
    {
        int incl = arr[0];
        int excl = 0;
        int excl_new;
        int i;
        for (i = 1; i < n; i++)
        {

/* current max excluding i */

            excl_new = (incl > excl) ?
                            incl : excl;

/* current max including i */

            incl = excl + arr[i];
            excl = excl_new;
        }

/* return max of incl and excl */

        return ((incl > excl) ?
                            incl : excl);
    }

/*    Driver program to test above
    functions*/

    public static void Main()
    {
        int []arr = new int[]{5, 5, 10,
                              100, 10, 5};
        Console.Write(
             FindMaxSum(arr, arr.Length));
    }
}

/*C# program of above implementation*/

using System;
class GFG
{

/* Class Pair is used to return
    two values from getMinMax() */

    class Pair
    {
        public int min;
        public int max;
    }
    static Pair getMinMax(int []arr, int n)
    {
        Pair minmax = new Pair();
        int i;

/* If there is only one element
        then return it as min and max both*/

        if (n == 1)
        {
            minmax.max = arr[0];
            minmax.min = arr[0];
            return minmax;
        }

/* If there are more than one elements,
        then initialize min and max*/

        if (arr[0] > arr[1])
        {
            minmax.max = arr[0];
            minmax.min = arr[1];
        }
        else
        {
            minmax.max = arr[1];
            minmax.min = arr[0];
        }
        for (i = 2; i < n; i++)
        {
            if (arr[i] > minmax.max)
            {
                minmax.max = arr[i];
            }
            else if (arr[i] < minmax.min)
            {
                minmax.min = arr[i];
            }
        }
        return minmax;
    }

/*    Driver Code*/

    public static void Main(String []args)
    {
        int []arr = {1000, 11, 445, 1, 330, 3000};
        int arr_size = 6;
        Pair minmax = getMinMax(arr, arr_size);
        Console.Write("Minimum element is {0}",
                                   minmax.min);
        Console.Write("\nMaximum element is {0}",
                                     minmax.max);
    }
}

/*C# program of above implementation*/

using System;
class GFG
{

/* Class Pair is used to return
       two values from getMinMax() */

    public class Pair
    {
        public int min;
        public int max;
    }
    static Pair getMinMax(int []arr, int n)
    {
        Pair minmax = new Pair();
        int i;

/* If array has even number of elements
        then initialize the first two elements
        as minimum and maximum */

        if (n % 2 == 0)
        {
            if (arr[0] > arr[1])
            {
                minmax.max = arr[0];
                minmax.min = arr[1];
            }
            else
            {
                minmax.min = arr[0];
                minmax.max = arr[1];
            }

/* set the starting index for loop */
            i = 2;
        }

/* If array has odd number of elements then
        initialize the first element as minimum and
        maximum */

        else
        {
            minmax.min = arr[0];
            minmax.max = arr[0];

/* set the starting index for loop */
            i = 1;
        }

/* In the while loop, pick elements in pair and
        compare the pair with max and min so far */

        while (i < n - 1)
        {
            if (arr[i] > arr[i + 1])
            {
                if (arr[i] > minmax.max)
                {
                    minmax.max = arr[i];
                }
                if (arr[i + 1] < minmax.min)
                {
                    minmax.min = arr[i + 1];
                }
            }
            else
            {
                if (arr[i + 1] > minmax.max)
                {
                    minmax.max = arr[i + 1];
                }
                if (arr[i] < minmax.min)
                {
                    minmax.min = arr[i];
                }
            }

/* Increment the index by 2 as two
            elements are processed in loop */
            i += 2;
        }
        return minmax;
    }

/*    Driver Code*/

    public static void Main(String []args)
    {
        int []arr = {1000, 11, 445, 1, 330, 3000};
        int arr_size = 6;
        Pair minmax = getMinMax(arr, arr_size);
        Console.Write("Minimum element is {0}",
                                   minmax.min);
        Console.Write("\nMaximum element is {0}",
                                     minmax.max);
    }
}

/*C# program to compute sum of ranges for
different range queries*/

using System;
using System.Collections;

/*Class to represent a query range*/

public class Query
{
    public int L;
    public int R;
    public Query(int L, int R)
    {
        this.L = L;
        this.R = R;
    }
}
class GFG{

/*Prints sum of all query ranges. m
is number of queries n is the size
of the array.*/

static void printQuerySums(int []a, int n,
                       ArrayList q, int m)
{

/*    One by one compute sum of all queries*/

    for(int i = 0; i < m; i++)
    {

/*        Left and right boundaries of
        current range*/

        int L = ((Query)q[i]).L,
            R = ((Query)q[i]).R;

/*        Compute sum of current query range*/

        int sum = 0;
        for(int j = L; j <= R; j++)
            sum += a[j];

/*        Print sum of current query range*/

        Console.Write("Sum of [" + L + ", " +
                      R + "] is " + sum + "\n");
    }
}

/*Driver code*/

public static void Main(string []argv)
{
    int []a = { 1, 1, 2, 1, 3, 4, 5, 2, 8 };
    int n = a.Length;
    ArrayList q = new ArrayList();
    q.Add(new Query(0, 4));
    q.Add(new Query(1, 3));
    q.Add(new Query(2, 4));
    int m = q.Count;
    printQuerySums(a, n, q, m);
}
}

/*C# program to demonstrate working of 
Square Root Decomposition. */

using System;
class GFG 
{
static int MAXN = 10000;
static int SQRSIZE = 100;

/*original array*/

static int []arr = new int[MAXN];

/*decomposed array*/

static int []block = new int[SQRSIZE];

/*block size*/

static int blk_sz;

/*Time Complexity : O(1)*/

static void update(int idx, int val)
{
    int blockNumber = idx / blk_sz;
    block[blockNumber] += val - arr[idx];
    arr[idx] = val;
}

/*Time Complexity : O(sqrt(n))*/

static int query(int l, int r)
{
    int sum = 0;
    while (l < r && l % blk_sz != 0 && l != 0)
    {

/*        traversing first block in range*/

        sum += arr[l];
        l++;
    }
    while (l + blk_sz <= r)
    {

/*        traversing completely
        overlapped blocks in range*/

        sum += block[l / blk_sz];
        l += blk_sz;
    }
    while (l <= r)
    {

/*        traversing last block in range*/

        sum += arr[l];
        l++;
    }
    return sum;
}

/*Fills values in input[]*/

static void preprocess(int []input, int n)
{

/*    initiating block pointer*/

    int blk_idx = -1;

/*    calculating size of block*/

    blk_sz = (int) Math.Sqrt(n);

/*    building the decomposed array*/

    for (int i = 0; i < n; i++)
    {
        arr[i] = input[i];
        if (i % blk_sz == 0)
        {

/*            entering next block
            incementing block pointer*/

            blk_idx++;
        }
        block[blk_idx] += arr[i];
    }
}

/*Driver code*/

public static void Main(String[] args) 
{

/*    We have used separate array for input because
    the purpose of this code is to explain SQRT
    decomposition in competitive programming where
    we have multiple inputs.*/

    int []input = {1, 5, 2, 4, 6, 1, 3, 5, 7, 10};
    int n = input.Length;
    preprocess(input, n);
    Console.WriteLine("query(3, 8) : " +
                       query(3, 8));
    Console.WriteLine("query(1, 6) : " +
                       query(1, 6));
    update(8, 0);
    Console.WriteLine("query(8, 8) : " + 
                       query(8, 8));
}
}

/*C# program to do range minimum query
using sparse table*/

using System;
public class GFG {
    static int MAX= 500;

/*    lookup[i][j] is going to store minimum
    value in arr[i..j]. Ideally lookup table
    size should not be fixed and should be
    determined using n Log n. It is kept
    constant to keep code simple.*/

    static int [,]lookup = new int[MAX, MAX];

/*    Fills lookup array lookup[][] in bottom up manner.*/

    static void buildSparseTable(int []arr, int n)
    {

/*        Initialize M for the intervals with length 1*/

        for (int i = 0; i < n; i++)
            lookup[i, 0] = arr[i];

/*        Compute values from smaller to bigger intervals*/

        for (int j = 1; (1 << j) <= n; j++) {

/*            Compute minimum value for all intervals with
            size 2^j*/

            for (int i = 0; (i + (1 << j) - 1) < n; i++) {

/*                For arr[2][10], we compare arr[lookup[0][7]]
                and arr[lookup[3][10]]*/

                if (lookup[i, j - 1] <
                            lookup[i + (1 << (j - 1)), j - 1])
                    lookup[i, j] = lookup[i, j - 1];
                else
                    lookup[i, j] =
                            lookup[i + (1 << (j - 1)), j - 1];
            }
        }
    }

/*    Returns minimum of arr[L..R]*/

    static int query(int L, int R)
    {

/*        Find highest power of 2 that is smaller
        than or equal to count of elements in given
        range. For [2, 10], j = 3*/

        int j = (int)Math.Log(R - L + 1);

/*        Compute minimum of last 2^j elements with first
        2^j elements in range.
        For [2, 10], we compare arr[lookup[0][3]] and
        arr[lookup[3][3]],*/

        if (lookup[L, j] <= lookup[R - (1 << j) + 1, j])
            return lookup[L, j];
        else
            return lookup[R - (1 << j) + 1, j];
    }

/*    Driver program*/

    static public void Main ()
    {
        int []a = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
        int n = a.Length;
        buildSparseTable(a, n);
        Console.WriteLine(query(0, 4));
        Console.WriteLine(query(4, 7));
        Console.WriteLine(query(7, 8));
    }
}

/*C# program to do range minimum query
using sparse table*/

using System;
class GFG
{
static readonly int MAX = 500;

/*lookup[i,j] is going to store GCD of
arr[i..j]. Ideally lookup table
size should not be fixed and should be
determined using n Log n. It is kept
constant to keep code simple.*/

static int [,]table = new int[MAX, MAX];

/*it builds sparse table.*/

static void buildSparseTable(int []arr,
                             int n)
{

/*    GCD of single element is
    element itself*/

    for (int i = 0; i < n; i++)
        table[i, 0] = arr[i];

/*    Build sparse table*/

    for (int j = 1; j <= n; j++)
        for (int i = 0; i <= n - (1 << j); i++)
            table[i, j] = __gcd(table[i, j - 1],
                                table[i + (1 << (j - 1)),
                                                 j - 1]);
}

/*Returns GCD of arr[L..R]*/

static int query(int L, int R)
{

/*    Find highest power of 2 that is
    smaller than or equal to count of
    elements in given range.
    For [2, 10], j = 3*/

    int j = (int)Math.Log(R - L + 1);

/*    Compute GCD of last 2^j elements
    with first 2^j elements in range.
    For [2, 10], we find GCD of
    arr[lookup[0,3]] and arr[lookup[3,3]],*/

    return __gcd(table[L, j],
                 table[R - (1 << j) + 1, j]);
}
static int __gcd(int a, int b)
{
    return b == 0 ? a : __gcd(b, a % b);    
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []a = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
    int n = a.Length;
    buildSparseTable(a, n);
    Console.Write(query(0, 2) + "\n");
    Console.Write(query(1, 3) + "\n");
    Console.Write(query(4, 5) + "\n");
}
}

/*C# program to do range minimum query
in O(1) time with O(n*n) extra space
and O(n*n) preprocessing time.*/

using System;
class GFG {
    static int MAX = 500;

/*    lookup[i][j] is going to store index of
    minimum value in arr[i..j]*/

    static int[, ] lookup = new int[MAX, MAX];

/*    Structure to represent a query range*/

    public class Query {
        public int L, R;
        public Query(int L, int R)
        {
            this.L = L;
            this.R = R;
        }
    };

/*    Fills lookup array lookup[n][n] for
    all possible values of query ranges*/

    static void preprocess(int[] arr, int n)
    {

/*        Initialize lookup[][] for
        the intervals with length 1*/

        for (int i = 0; i < n; i++)
            lookup[i, i] = i;

/*        Fill rest of the entries in bottom up manner*/

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)

/*                To find minimum of [0,4],
                we compare minimum of
                arr[lookup[0][3]] with arr[4].*/

                if (arr[lookup[i, j - 1]] < arr[j])
                    lookup[i, j] = lookup[i, j - 1];
                else
                    lookup[i, j] = j;
        }
    }

/*    Prints minimum of given m query
    ranges in arr[0..n-1]*/

    static void RMQ(int[] arr, int n, Query[] q, int m)
    {

/*        Fill lookup table for
        all possible input queries*/

        preprocess(arr, n);

/*        One by one compute sum of all queries*/

        for (int i = 0; i < m; i++) {

/*            Left and right boundaries
            of current range*/

            int L = q[i].L, R = q[i].R;

/*            Print sum of current query range*/

            Console.WriteLine("Minimum of [" + L + ", " + R
                              + "] is "
                              + arr[lookup[L, R]]);
        }
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] a = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
        int n = a.Length;
        Query[] q = { new Query(0, 4), new Query(4, 7),
                      new Query(7, 8) };
        int m = q.Length;
        RMQ(a, n, q, m);
    }
}

/*C# program to do range minimum query
in O(1) time with O(n Log n) extra space
and O(n Log n) preprocessing time*/

using System;
class GFG {
    static int MAX = 500;

/*    lookup[i,j] is going to store index
    of minimum value in arr[i..j].
    Ideally lookup table size should not be fixed
    and should be determined using n Log n.
    It is kept constant to keep code simple.*/

    static int[, ] lookup = new int[MAX, MAX];

/*    Structure to represent a query range*/

    public class Query {
        public int L, R;
        public Query(int L, int R)
        {
            this.L = L;
            this.R = R;
        }
    };

/*    Fills lookup array lookup[,]
    in bottom up manner.*/

    static void preprocess(int[] arr, int n)
    {

/*        Initialize M for the intervals
        with length 1*/

        for (int i = 0; i < n; i++)
            lookup[i, 0] = i;

/*        Compute values from smaller
        to bigger intervals*/

        for (int j = 1; (1 << j) <= n; j++)
        {

/*            Compute minimum value for
            all intervals with size 2^j*/

            for (int i = 0;
                 (i + (1 << j) - 1) < n;
                 i++)
            {

/*                For arr[2,10], we compare
                arr[lookup[0,3]] and arr[lookup[3,3]]*/

                if (arr[lookup[i, j - 1]]
                    < arr[lookup[i + (1 << (j - 1)),
                                 j - 1]])
                    lookup[i, j] = lookup[i, j - 1];
                else
                    lookup[i, j]
                        = lookup[i + (1 << (j - 1)), j - 1];
            }
        }
    }

/*    Returns minimum of arr[L..R]*/

    static int query(int[] arr, int L, int R)
    {

/*        For [2,10], j = 3*/

        int j = (int)Math.Log(R - L + 1);

/*        For [2,10], we compare arr[lookup[0,3]]
        and arr[lookup[3,3]],*/

        if (arr[lookup[L, j]]
            <= arr[lookup[R - (1 << j) + 1, j]])
            return arr[lookup[L, j]];
        else
            return arr[lookup[R - (1 << j) + 1, j]];
    }

/*    Prints minimum of given m
    query ranges in arr[0..n-1]*/

    static void RMQ(int[] arr,
                    int n, Query[] q, int m)
    {

/*        Fills table lookup[n,Log n]*/

        preprocess(arr, n);

/*        One by one compute sum of all queries*/

        for (int i = 0; i < m; i++)
        {

/*            Left and right
            boundaries of current range*/

            int L = q[i].L, R = q[i].R;

/*            Print sum of current query range*/

            Console.WriteLine("Minimum of [" + L + ", " + R
                              + "] is " + query(arr, L, R));
        }
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] a = { 7, 2, 3, 0, 5, 10, 3, 12, 18 };
        int n = a.Length;
        Query[] q = { new Query(0, 4), new Query(4, 7),
                      new Query(7, 8) };
        int m = q.Length;
        RMQ(a, n, q, m);
    }
}

/*C# program to get updated array after
many array range add operation*/

using System;
class GFG {

/*    Utility method to add value val,
    to range [lo, hi]*/

    static void add(int[] arr, int N, int lo, int hi,
                    int val)
    {
        arr[lo] += val;
        if (hi != N - 1)
            arr[hi + 1] -= val;
    }

/*    Utility method to get actual
    array from operation array*/

    static void updateArray(int[] arr, int N)
    {

/*        convert array into
        prefix sum array*/

        for (int i = 1; i < N; i++)
            arr[i] += arr[i - 1];
    }

/*    method to print final updated array*/

    static void printArr(int[] arr, int N)
    {
        updateArray(arr, N);
        for (int i = 0; i < N; i++)
            Console.Write("" + arr[i] + " ");
        Console.Write("\n");
    }

/*    Driver code*/

    public static void Main()
    {
        int N = 6;
        int[] arr = new int[N];

/*        Range add Queries*/

        add(arr, N, 0, 2, 100);
        add(arr, N, 1, 5, 100);
        add(arr, N, 2, 3, 100);
        printArr(arr, N);
    }
}

/*LCM of given range queries
using Segment Tree*/

using System;
using System.Collections.Generic;
class GFG
{
    static readonly int MAX = 1000;

/*    allocate space for tree*/

    static int []tree = new int[4 * MAX];

/*    declaring the array globally*/

    static int []arr = new int[MAX];

/*    Function to return gcd of a and b*/

    static int gcd(int a, int b)
    {
        if (a == 0)
        {
            return b;
        }
        return gcd(b % a, a);
    }

/*    utility function to find lcm*/

    static int lcm(int a, int b)
    {
        return a * b / gcd(a, b);
    }

/*    Function to build the segment tree
    Node starts beginning index
    of current subtree. start and end
    are indexes in []arr which is global*/

    static void build(int node, int start, int end)
    {

/*        If there is only one element
        in current subarray*/

        if (start == end)
        {
            tree[node] = arr[start];
            return;
        }
        int mid = (start + end) / 2;

/*        build left and right segments*/

        build(2 * node, start, mid);
        build(2 * node + 1, mid + 1, end);

/*        build the parent*/

        int left_lcm = tree[2 * node];
        int right_lcm = tree[2 * node + 1];
        tree[node] = lcm(left_lcm, right_lcm);
    }

/*    Function to make queries for
    array range )l, r). Node is index
    of root of current segment in segment
    tree (Note that indexes in segment
    tree begin with 1 for simplicity).
    start and end are indexes of subarray
    covered by root of current segment.*/

    static int query(int node, int start,
                     int end, int l, int r)
    {

/*        Completely outside the segment,
        returning 1 will not affect the lcm;*/

        if (end < l || start > r)
        {
            return 1;
        }

/*        completely inside the segment*/

        if (l <= start && r >= end)
        {
            return tree[node];
        }

/*        partially inside*/

        int mid = (start + end) / 2;
        int left_lcm = query(2 * node, start, mid, l, r);
        int right_lcm = query(2 * node + 1,
                              mid + 1, end, l, r);
        return lcm(left_lcm, right_lcm);
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/*        initialize the array*/

        arr[0] = 5;
        arr[1] = 7;
        arr[2] = 5;
        arr[3] = 2;
        arr[4] = 10;
        arr[5] = 12;
        arr[6] = 11;
        arr[7] = 17;
        arr[8] = 14;
        arr[9] = 1;
        arr[10] = 44;

/*        build the segment tree*/

        build(1, 0, 10);

/*        Now we can answer each query efficiently
        Print LCM of (2, 5)*/

        Console.WriteLine(query(1, 0, 10, 2, 5));

/*        Print LCM of (5, 10)*/

        Console.WriteLine(query(1, 0, 10, 5, 10));

/*        Print LCM of (0, 10)*/

        Console.WriteLine(query(1, 0, 10, 0, 10));
    }
}

/*C# Program to find GCD of a number in a given Range
using segment Trees*/

using System;
class GFG
{

/*Array to store segment tree*/

private static int[] st;

/*    A recursive function that constructs Segment
    Tree for array[ss..se]. si is index of current
    node in segment tree st*/

    public static int constructST(int[] arr, int ss,
                                int se, int si)
    {
        if (ss == se)
        {
            st[si] = arr[ss];
            return st[si];
        }
        int mid = ss + (se - ss) / 2;
        st[si] = gcd(constructST(arr, ss, mid, si * 2 + 1),
                    constructST(arr, mid + 1, se, si * 2 + 2));
        return st[si];
    }

/* Function to construct segment tree from given array.
    This function allocates memory for segment tree and
    calls constructSTUtil() to fill the allocated memory */

    public static int[] constructSegmentTree(int[] arr)
    {
        int height = (int)Math.Ceiling(Math.Log(arr.Length)/Math.Log(2));
        int size = 2*(int)Math.Pow(2, height) - 1;
        st = new int[size];
        constructST(arr, 0, arr.Length - 1, 0);
        return st;
    }

/*    Function to find gcd of 2 numbers.*/

    private static int gcd(int a, int b)
    {
        if (a < b)
        {

/*            If b greater than a swap a and b*/

            int temp = b;
            b = a;
            a = temp;
        }
        if (b == 0)
            return a;
        return gcd(b,a % b);
    }

/* A recursive function to get gcd of given
    range of array indexes. The following are parameters for
    this function.
    st --> Pointer to segment tree
    si --> Index of current node in the segment tree. Initially
            0 is passed as root is always at index 0
    ss & se --> Starting and ending indexes of the segment
                represented by current node, i.e., st[si]
    qs & qe --> Starting and ending indexes of query range */

    public static int findGcd(int ss, int se, int qs, int qe, int si)
    {
        if (ss > qe || se < qs)
            return 0;
        if (qs <= ss && qe >= se)
            return st[si];
        int mid = ss + (se - ss)/2;
        return gcd(findGcd(ss, mid, qs, qe, si * 2 + 1),
                findGcd(mid + 1, se, qs, qe, si * 2 + 2));
    }

/*    Finding The gcd of given Range*/

    public static int findRangeGcd(int ss, 
                        int se, int[] arr)
    {
        int n = arr.Length;
        if (ss < 0 || se > n-1 || ss > se)
        {
            Console.WriteLine("Invalid arguments");
            return int.MinValue;
        }
        return findGcd(0, n - 1, ss, se, 0);
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] a = {2, 3, 6, 9, 5};
        constructSegmentTree(a);

/*Starting index of range.*/

int l = 1;

/*Last index of range.*/

int r = 3; 
        Console.Write("GCD of the given range is: ");
        Console.Write(findRangeGcd(l, r, a));
    }
}

/*C# program for queries of GCD
excluding given range of elements.*/

using System;
class GFG {

/*Calculating GCD using
euclid algorithm*/

static int GCD(int a, int b)
{
    if (b == 0)
    return a;
    return GCD(b, a % b);
}

/*Filling the prefix and suffix array*/

static void FillPrefixSuffix(int []prefix,
                             int []arr,
                             int []suffix,
                             int n)
{

/*    Filling the prefix array following
    relation prefix(i) =
    GCD(prefix(i - 1), arr(i))*/

    prefix[0] = arr[0];
    for (int i = 1; i < n; i++)
    prefix[i] = GCD(prefix[i - 1], arr[i]);

/*    Filling the suffix array following
    the relation suffix(i) =
    GCD(suffix(i+1), arr(i))*/

    suffix[n - 1] = arr[n - 1];
    for (int i = n - 2; i >= 0; i--)
    suffix[i] = GCD(suffix[i + 1], arr[i]);
}

/*To calculate gcd of the numbers outside range*/

static int GCDoutsideRange(int l, int r,
                           int []prefix,
                           int []suffix,
                           int n)
    {

/*    If l=0, we need to tell
    GCD of numbers from r+1 to n*/

    if (l == 0)
    return suffix[r + 1];

/*    If r=n-1 we need to return the
    gcd of numbers from 1 to l*/

    if (r == n - 1)
    return prefix[l - 1];
    return GCD(prefix[l - 1], suffix[r + 1]);
}

/*Driver Code*/

public static void Main()
{
    int []arr = {2, 6, 9};
    int n = arr.Length;
    int []prefix = new int[n];
    int []suffix = new int[n];
    FillPrefixSuffix(prefix, arr, suffix, n);
    int l = 0, r = 0;
    Console.WriteLine(GCDoutsideRange
                     (l, r, prefix, suffix, n));
    l = 1;
    r = 1;
    Console.WriteLine(GCDoutsideRange
                        (l, r, prefix, suffix, n));
    l = 1;
    r = 2;
    Console.Write(GCDoutsideRange
                 (l, r, prefix, suffix, n));
}
}

/*Number of elements less than or equal
to a given number in a given subarray
and allowing update operations.*/

using System;
class GFG 
{
    static int MAX = 10001;

/*    updating the bit array of a valid block*/

    static void update(int idx, int blk, 
                    int val, int [,]bit)
    {
        for (; idx < MAX; idx += (idx&-idx))
            bit[blk, idx] += val;
    }

/*    answering the query*/

    static int query(int l, int r, int k, int []arr,
                             int blk_sz, int [,]bit)
    {

/*        traversing the first block in range*/

        int sum = 0;
        while (l < r && l % blk_sz != 0 && l != 0)
        {
            if (arr[l] <= k)
                sum++;
            l++;
        }

/*        Traversing completely overlapped blocks in
        range for such blocks bit array of that block
        is queried*/

        while (l + blk_sz <= r)
        {
            int idx = k;
            for (; idx > 0 ; idx -= idx&-idx)
                sum += bit[l/blk_sz,idx];
            l += blk_sz;
        }

/*        Traversing the last block*/

        while (l <= r)
        {
            if (arr[l] <= k)
                sum++;
            l++;
        }
        return sum;
    }

/*    Preprocessing the array*/

    static void preprocess(int []arr, int blk_sz,
                               int n, int [,]bit)
    {
        for (int i=0; i<n; i++)
            update(arr[i], i / blk_sz, 1, bit);
    }
    static void preprocessUpdate(int i, int v, int blk_sz,
                                    int []arr, int [,]bit)
    {

/*        updating the bit array at the original
        and new value of array*/

        update(arr[i], i/blk_sz, -1, bit);
        update(v, i/blk_sz, 1, bit);
        arr[i] = v;
    }

/*    Driver method*/

    public static void Main()
    {
        int []arr = {5, 1, 2, 3, 4};

/*        size of block size will be 
        equal to square root of n*/

        int blk_sz = (int) Math.Sqrt(arr.Length);

/*        initialising bit array of each block
        as elements of array cannot exceed 10^4 so size
        of bit array is accordingly*/

        int [,]bit = new int[blk_sz+1,MAX];
        preprocess(arr, blk_sz, arr.Length, bit);
        Console.WriteLine(query(1, 3, 1, arr, blk_sz, bit));
        preprocessUpdate(3, 10, blk_sz, arr, bit);
        Console.WriteLine(query(3, 3, 4, arr, blk_sz, bit));
        preprocessUpdate(2, 1, blk_sz, arr, bit);
        preprocessUpdate(0, 2, blk_sz, arr, bit);
        Console.WriteLine(query (0, 4, 5, arr, blk_sz, bit));
    }
}

/*Simple C# program to count
number of elements with
values in given range.*/

using System;
class GFG  {

/*    function to count elements
    within given range*/

    static int countInRange(int []arr, int n,
                            int x, int y)
    {

/*        initialize result*/

        int count = 0;
        for (int i = 0; i < n; i++) {

/*            check if element is in range*/

            if (arr[i] >= x && arr[i] <= y)
                count++;
        }
        return count;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int[]arr = {1, 3, 4, 9, 10, 3};
        int n = arr.Length;

