/*A Simple C# program to find
minimum average subarray*/

using System;
class Test {
    static int[] arr = new int[] { 3, 7, 90, 20, 10, 50, 40 };

/*    Prints beginning and ending indexes of subarray
    of size k with minimum average*/

    static void findMinAvgSubarray(int n, int k)
    {

/*        k must be smaller than or equal to n*/

        if (n < k)
            return;

/*        Initialize beginning index of result*/

        int res_index = 0;

/*        Compute sum of first subarray of size k*/

        int curr_sum = 0;
        for (int i = 0; i < k; i++)
            curr_sum += arr[i];

/*        Initialize minimum sum as current sum*/

        int min_sum = curr_sum;

/*        Traverse from (k+1)'th element to n'th element*/

        for (int i = k; i < n; i++)
        {

/*            Add current item and remove first item of
            previous subarray*/

            curr_sum += arr[i] - arr[i - k];

/*            Update result if needed*/

            if (curr_sum < min_sum) {
                min_sum = curr_sum;
                res_index = (i - k + 1);
            }
        }
        Console.Write("Subarray between [" + res_index + ", " +
                     (res_index + k - 1) +
                     "] has minimum average");
    }

/*    Driver method to test the above function*/

    public static void Main()
    {

/*Subarray size*/

int k = 3; 
        findMinAvgSubarray(arr.Length, k);
    }
}

/*C# program to find Minimum
number of jumps to reach end*/

using System;
class GFG {

/*    Returns minimum number of
    jumps to reach arr[h] from arr[l]*/

    static int minJumps(int[] arr, int l, int h)
    {

/*        Base case: when source
        and destination are same*/

        if (h == l)
            return 0;

/*        When nothing is reachable
        from the given source*/

        if (arr[l] == 0)
            return int.MaxValue;

/*        Traverse through all the points
        reachable from arr[l]. Recursively
        get the minimum number of jumps
        needed to reach arr[h] from these
        reachable points.*/

        int min = int.MaxValue;
        for (int i = l + 1; i <= h && i <= l + arr[l]; i++) {
            int jumps = minJumps(arr, i, h);
            if (jumps != int.MaxValue && jumps + 1 < min)
                min = jumps + 1;
        }
        return min;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 1, 3, 6, 3, 2, 3, 6, 8, 9, 5 };
        int n = arr.Length;
        Console.Write("Minimum number of jumps to reach end is "
                      + minJumps(arr, 0, n - 1));
    }
}

/*C# program to find Minimum
number of jumps to reach end*/

using System;
class GFG {

/*    Returns Minimum number
    of jumps to reach end*/

    public static int minJumps(int[] arr, int n)
    {

/*        jumps[0] will
        hold the result*/

        int[] jumps = new int[n];
        int min;

/*        Minimum number of jumps needed to
        reach last element from last elements
        itself is always 0*/

        jumps[n - 1] = 0;

/*        Start from the second element, move
        from right to left and construct the
        jumps[] array where jumps[i] represents
        minimum number of jumps needed to reach
        arr[m-1] from arr[i]*/

        for (int i = n - 2; i >= 0; i--) {

/*            If arr[i] is 0 then arr[n-1]
            can't be reached from here*/

            if (arr[i] == 0) {
                jumps[i] = int.MaxValue;
            }

/*            If we can direcly reach to the end
            point from here then jumps[i] is 1*/

            else if (arr[i] >= n - i - 1) {
                jumps[i] = 1;
            }

/*            Otherwise, to find out the minimum
            number of jumps needed to reach
            arr[n-1], check all the points
            reachable from here and jumps[] value
            for those points*/

            else {

/*                initialize min value*/

                min = int.MaxValue;

/*                following loop checks with all
                reachable points and takes the minimum*/

                for (int j = i + 1; j < n && j <= arr[i] + i; j++) {
                    if (min > jumps[j]) {
                        min = jumps[j];
                    }
                }

/*                Handle overflow*/

                if (min != int.MaxValue) {
                    jumps[i] = min + 1;
                }
                else {

/*or Integer.MAX_VALUE*/

jumps[i] = min; 
                }
            }
        }
        return jumps[0];
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        int[] arr = new int[] { 1, 3, 6, 1, 0, 9 };
        int size = arr.Length;
        Console.WriteLine("Minimum number of"
                          + " jumps to reach end is " + minJumps(arr, size));
    }
}

/*Dynamic Programming C# implementation
of Maximum Sum Increasing Subsequence
(MSIS) problem*/

using System;
class GFG {

/*    maxSumIS() returns the
    maximum sum of increasing
    subsequence in arr[] of size n*/

    static int maxSumIS( int []arr, int n )
    {
        int i, j, max = 0;
        int []msis = new int[n];

/* Initialize msis values
           for all indexes */

        for ( i = 0; i < n; i++ )
            msis[i] = arr[i];

/* Compute maximum sum values
           in bottom up manner */

        for ( i = 1; i < n; i++ )
            for ( j = 0; j < i; j++ )
                if ( arr[i] > arr[j] &&
                    msis[i] < msis[j] + arr[i])
                    msis[i] = msis[j] + arr[i];

/* Pick maximum of all
           msis values */

        for ( i = 0; i < n; i++ )
            if ( max < msis[i] )
                max = msis[i];
        return max;
    }

/*    Driver Code*/

    public static void Main()
    {
        int []arr = new int[]{1, 101, 2, 3, 100, 4, 5};
        int n = arr.Length;
        Console.WriteLine("Sum of maximum sum increasing "+
                                        " subsequence is "+
        maxSumIS(arr, n));
    }
}

/*C# program to find Smallest
subarray with sum greater
than a given value*/

using System;
class GFG
{

/*    Returns length of smallest
    subarray with sum greater
    than x. If there is no
    subarray with given sum,
    then returns n+1*/

    static int smallestSubWithSum(int []arr,
                                  int n, int x)
    {

/*        Initialize length of
        smallest subarray as n+1*/

        int min_len = n + 1;

/*        Pick every element
        as starting point*/

        for (int start = 0; start < n; start++)
        {

/*            Initialize sum starting
            with current start*/

            int curr_sum = arr[start];

/*            If first element
            itself is greater*/

            if (curr_sum > x)
                return 1;

/*            Try different ending
            points for curremt start*/

            for (int end = start + 1;
                     end < n; end++)
            {

/*                add last element
                to current sum*/

                curr_sum += arr[end];

/*                If sum becomes more than
                x and length of this
                subarray is smaller than
                current smallest length,
                update the smallest
                length (or result)*/

                if (curr_sum > x &&
                        (end - start + 1) < min_len)
                    min_len = (end - start + 1);
            }
        }
        return min_len;
    }

/*    Driver Code*/

    static public void Main ()
    {
        int []arr1 = {1, 4, 45,
                      6, 10, 19};
        int x = 51;
        int n1 = arr1.Length;
        int res1 = smallestSubWithSum(arr1,
                                      n1, x);
        if (res1 == n1 + 1)
        Console.WriteLine("Not Possible");
        else
        Console.WriteLine(res1);
        int []arr2 = {1, 10, 5, 2, 7};
        int n2 = arr2.Length;
        x = 9;
        int res2 = smallestSubWithSum(arr2,
                                      n2, x);
        if (res2 == n2 + 1)
        Console.WriteLine("Not Possible");
        else
        Console.WriteLine(res2);
        int []arr3 = {1, 11, 100, 1, 0,
                      200, 3, 2, 1, 250};
        int n3 = arr3.Length;
        x = 280;
        int res3 = smallestSubWithSum(arr3,
                                      n3, x);
        if (res3 == n3 + 1)
        Console.WriteLine("Not Possible");
        else
        Console.WriteLine(res3);
    }
}

/*O(n) solution for finding
smallest subarray with sum
greater than x*/

using System;
class GFG {

/*    Returns length of smallest
    subarray with sum greater
    than x. If there is no
    subarray with given sum,
    then returns n+1*/

    static int smallestSubWithSum(int[] arr, int n, int x)
    {

/*        Initialize current
        sum and minimum length*/

        int curr_sum = 0, min_len = n + 1;

/*        Initialize starting
        and ending indexes*/

        int start = 0, end = 0;
        while (end < n) {

/*            Keep adding array elements
            while current sum is smaller
            than or equal to x*/

            while (curr_sum <= x && end < n)
                curr_sum += arr[end++];

/*            If current sum becomes
            greater than x.*/

            while (curr_sum > x && start < n) {

/*                Update minimum
                length if needed*/

                if (end - start < min_len)
                    min_len = end - start;

/*                remove starting elements*/

                curr_sum -= arr[start++];
            }
        }
        return min_len;
    }

/*    Driver Code*/

    static public void Main()
    {
        int[] arr1 = { 1, 4, 45, 6, 10, 19 };
        int x = 51;
        int n1 = arr1.Length;
        int res1 = smallestSubWithSum(arr1, n1, x);
        if (res1 == n1 + 1)
            Console.WriteLine("Not Possible");
        else
            Console.WriteLine(res1);
        int[] arr2 = { 1, 10, 5, 2, 7 };
        int n2 = arr2.Length;
        x = 9;
        int res2 = smallestSubWithSum(arr2, n2, x);
        if (res2 == n2 + 1)
            Console.WriteLine("Not Possible");
        else
            Console.WriteLine(res2);
        int[] arr3
            = { 1, 11, 100, 1, 0, 200, 3, 2, 1, 250 };
        int n3 = arr3.Length;
        x = 280;
        int res3 = smallestSubWithSum(arr3, n3, x);
        if (res3 == n3 + 1)
            Console.WriteLine("Not Possible");
        else
            Console.WriteLine(res3);
    }
}

/*C# program to find maximum average
subarray of given length.*/

using System;
class GFG{

/*Returns beginning index
of maximum average
subarray of length 'k'*/

static int findMaxAverage(int []arr,
                       int n, int k)
{

/*    Check if 'k' is valid*/

    if (k > n)
        return -1;

/*    Create and fill array
    to store cumulative
    sum. csum[i] stores
    sum of arr[0] to arr[i]*/

    int []csum = new int[n];
    csum[0] = arr[0];
    for (int i = 1; i < n; i++)
    csum[i] = csum[i - 1] + arr[i];

/*    Initialize max_sm as
    sum of first subarray*/

    int max_sum = csum[k - 1],
              max_end = k - 1;

/*    Find sum of other
    subarrays and update
    max_sum if required.*/

    for (int i = k; i < n; i++)
    {
        int curr_sum = csum[i] -
                   csum[i - k];
        if (curr_sum > max_sum)
        {
            max_sum = curr_sum;
            max_end = i;
        }
    }

/*    Return starting index*/

    return max_end - k + 1;
}

/*    Driver Code*/

    static public void Main ()
    {
        int []arr = {1, 12, -5, -6, 50, 3};
        int k = 4;
        int n = arr.Length;
        Console.WriteLine("The maximum average subarray of "+
                            "length "+ k + " begins at index "
                                    + findMaxAverage(arr, n, k));
    }
}

/*C# program to find maximum average
subarray of given length.*/

using System;
class GFG {

/*    Returns beginning index of
    maximum average subarray of
    length 'k'*/

    static int findMaxAverage(int []arr,
                           int n, int k)
    {

/*        Check if 'k' is valid*/

        if (k > n)
            return -1;

/*        Compute sum of first 'k'
        elements*/

        int sum = arr[0];
        for (int i = 1; i < k; i++)
            sum += arr[i];
        int max_sum = sum;
        int max_end = k-1;

/*        Compute sum of remaining
        subarrays*/

        for (int i = k; i < n; i++)
        {
            sum = sum + arr[i] - arr[i-k];
            if (sum > max_sum)
            {
                max_sum = sum;
                max_end = i;
            }
        }

/*        Return starting index*/

        return max_end - k + 1;
    }

/*    Driver program*/

    public static void Main ()
    {
        int []arr = {1, 12, -5, -6, 50, 3};
        int k = 4;
        int n = arr.Length;
        Console.WriteLine( "The maximum "
          + "average subarray of length "
                + k + " begins at index "
            + findMaxAverage(arr, n, k));
    }
}

/*C# program to count minimum
number of operations to get
the given arr array */
*/
using System;
class GFG {
    static int []arr = new int[]{16, 16, 16} ;

/*    Returns count of minimum
    operations to convert a
    zero array to arr array
    with increment and
    doubling operations.
    This function computes
    count by doing reverse
    steps, i.e., convert arr
    to zero array.*/

    static int countMinOperations(int n)
    {

/*        Initialize result
        (Count of minimum moves)*/

        int result = 0;

/*        Keep looping while all
        elements of arr
        don't become 0.*/

        while (true)
        {

/*            To store count of zeroes
            in current arr array*/

            int zero_count = 0;

/*            To find first odd element*/

            int i;
            for (i = 0; i < n; i++)
            {

/*                If odd number found*/

                if (arr[i] % 2 == 1)
                    break;

/*                If 0, then increment
                zero_count*/

                else if (arr[i] == 0)
                    zero_count++;
            }

/*            All numbers are 0*/

            if (zero_count == n)
            return result;

/*            All numbers are even*/

            if (i == n)
            {

/*                Divide the whole array by 2
                and increment result*/

                for(int j = 0; j < n; j++)
                arr[j] = arr[j] / 2;
                result++;
            }

/*            Make all odd numbers
            even by subtracting
            one and increment result.*/

            for(int j = i; j < n; j++)
            {
                if (arr[j] %2 == 1)
                {
                    arr[j]--;
                    result++;
                }
            }
        }
    }

/*    Driver Code*/

    public static void Main()
    {
        Console.Write("Minimum number of steps required to \n" +
                            "get the given target array is "+
                                countMinOperations(arr.Length));
    }
}

/*C# program to find number of operations
to make an array palindrome*/

using System;
class GFG
{

/*    Returns minimum number of count operations
    required to make arr[] palindrome*/

    static int findMinOps(int []arr, int n)
    {

/*Initialize result*/

int ans = 0;

/*        Start from two corners*/

        for (int i = 0, j = n - 1; i <= j;)
        {

/*            If corner elements are same,
            problem reduces arr[i+1..j-1]*/

            if (arr[i] == arr[j])
            {
                i++;
                j--;
            }

/*            If left element is greater, then
            we merge right two elements*/

            else if (arr[i] > arr[j])
            {

/*                need to merge from tail.*/

                j--;
                arr[j] += arr[j + 1] ;
                ans++;
            }

/*            Else we merge left two elements*/

            else
            {
                i++;
                arr[i] += arr[i-1];
                ans++;
            }
        }
        return ans;
    }

/*    Driver Code*/

    public static void Main()
    {
        int []arr = new int[]{1, 4, 5, 9, 1} ;
        Console.Write("Count of minimum operations is " +
                            findMinOps(arr, arr.Length));
    }
}

/*C# program to find the smallest
positive value that cannot be
represented as sum of subsets
of a given sorted array*/

using System;
class GFG {

/*    Returns the smallest number that
    cannot be represented as sum
    of subset of elements from set
    represented by sorted array
    arr[0..n-1]*/

    static int findSmallest(int []arr, int n)
    {

/*         Initialize result*/

         int res = 1;

/*        Traverse the array and
        increment 'res' if arr[i] is
        smaller than or equal to 'res'.*/

        for (int i = 0; i < n &&
             arr[i] <= res; i++)
            res = res + arr[i];
        return res;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr1 = {1, 3, 4, 5};
        int n1 = arr1.Length;
        Console.WriteLine(findSmallest(arr1, n1));
        int []arr2 = {1, 2, 6, 10, 11, 15};
        int n2 = arr2.Length;
        Console.WriteLine(findSmallest(arr2, n2));
        int []arr3 = {1, 1, 1, 1};
        int n3 = arr3.Length;
        Console.WriteLine(findSmallest(arr3, n3));
        int []arr4 = {1, 1, 3, 4};
        int n4 = arr4.Length;
        Console.WriteLine(findSmallest(arr4, n4));
    }
}

