/*C# implementation of simple method to find
minimum difference between any pair*/

using System;
class GFG {

/*    Returns minimum difference between any pair*/

    static int findMinDiff(int []arr, int n)
    {

/*        Initialize difference as infinite*/

        int diff = int.MaxValue;

/*        Find the min diff by comparing difference
        of all possible pairs in given array*/

        for (int i = 0; i < n-1; i++)
            for (int j = i+1; j < n; j++)
                if (Math.Abs((arr[i] - arr[j]) ) < diff)
                    diff = Math.Abs((arr[i] - arr[j]));

/*        Return min diff*/

        return diff;
    }

/*    Driver method to test the above function*/

    public static void Main()
    {
        int []arr = new int[]{1, 5, 3, 19, 18, 25};
        Console.Write("Minimum difference is " +
                        findMinDiff(arr, arr.Length));
    }
}

/*C# program to find minimum
difference between any pair
in an unsorted array*/

using System;
class GFG
{

/*    Returns minimum difference
    between any pair*/

    static int findMinDiff(int[] arr,
                           int n)
    {

/*        Sort array in
        non-decreasing order*/

        Array.Sort(arr);

/*        Initialize difference
        as infinite*/

        int diff = int.MaxValue;

/*        Find the min diff by
        comparing adjacent pairs
        in sorted array*/

        for (int i = 0; i < n - 1; i++)
            if (arr[i + 1] - arr[i] < diff)
                diff = arr[i + 1] - arr[i];

/*        Return min diff*/

        return diff;
    }

/*    Driver Code*/

    public static void Main()
    {
        int []arr = new int[]{1, 5, 3, 19, 18, 25};
        Console.WriteLine("Minimum difference is " +
                           findMinDiff(arr, arr.Length));
    }
}

/*C# program to mark numbers as
multiple of 2 or 5*/

using System;
class GFG {

/*    Driver code*/

    static public void Main ()
    {
        int a = 2, b = 10;
        int size = Math.Abs(b - a) + 1;
        int[] array = new int[size];

/*        Iterate through a to b, If
        it is a multiple of 2 or 5
        Mark index in array as 1*/

        for (int i = a; i <= b; i++)
            if (i % 2 == 0 || i % 5 == 0)
                array[i - a] = 1;
