            if (array[i - a] == 1)
                Console.Write(i + " ");
    }
}

/*C# code to for marking multiples*/

using System;
class GFG
{

/*    index >> 5 corresponds to dividing index by 32
    index & 31 corresponds to modulo operation of
    index by 32
    Function to check value of bit position 
    whether it is zero or one*/

    static bool checkbit(int []array, int index)
    {
        int val = array[index >> 5] &
                 (1 << (index & 31));
        if (val == 0)
            return false;
        return true;
    }

/*    Sets value of bit for corresponding index*/

    static void setbit(int []array, int index)
    {
            array[index >> 5] |= (1 << (index & 31));
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        int a = 2, b = 10;
        int size = Math.Abs(b-a);

/*        Size that will be used is actual_size/32
        ceil is used to initialize the array with
        positive number*/

        size = (int)Math.Ceiling((double)size / 32);

/*        Array is dynamically initialized as
        we are calculating size at run time*/

        int[] array = new int[size];

/*        Iterate through every index from a to b and
        call setbit() if it is a multiple of 2 or 5*/

        for (int i = a; i <= b; i++)
            if (i % 2 == 0 || i % 5 == 0)
                setbit(array, i - a);
        Console.WriteLine("MULTIPLES of 2 and 5:");
        for (int i = a; i <= b; i++)
            if (checkbit(array, i - a))
                Console.Write(i + " ");
    }
}

/*A Simple C# program to find
longest common subarray of
two binary arrays with same sum*/

using System;
class GFG
{
static int[] arr1 = new int[]{0, 1, 0, 1, 1, 1, 1};
static int[] arr2 = new int[]{1, 1, 1, 1, 1, 0, 1};

/*Returns length of the longest
common sum in arr1[] and arr2[].
Both are of same size n.*/

static int longestCommonSum(int n)
{

/*    Initialize result*/

    int maxLen = 0;

/*    One by one pick all possible
    starting points of subarrays*/

    for (int i = 0; i < n; i++)
    {

/*    Initialize sums of current
    subarrays*/

    int sum1 = 0, sum2 = 0;

/*    Conider all points for
    starting with arr[i]*/

    for (int j = i; j < n; j++)
    {

/*        Update sums*/

        sum1 += arr1[j];
        sum2 += arr2[j];

/*        If sums are same and current
        length is more than maxLen,
        update maxLen*/

        if (sum1 == sum2)
        {
            int len = j - i + 1;
            if (len > maxLen)
                maxLen = len;
        }
    }
    }
    return maxLen;
}

/*Driver Code*/

public static void Main()
{
    Console.Write("Length of the longest " +
           "common span with same sum is ");
    Console.Write(longestCommonSum(arr1.Length));
}
}

/*C# program to find largest subarray
with equal number of 0's and 1's.*/

using System;
using System.Collections.Generic;
public class GFG
{

/*  Returns largest common subarray with equal
  number of 0s and 1s*/

  static int longestCommonSum(int[] arr1, int[] arr2, int n)
  {

/*    Find difference between the two*/

    int[] arr = new int[n];
    for (int i = 0; i < n; i++)
      arr[i] = arr1[i] - arr2[i];

/*    Creates an empty hashMap hM*/

    Dictionary<int,int> hM = new Dictionary<int,int>();

/*Initialize sum of elements*/

int sum = 0;

/*Initialize result*/

int max_len = 0;

/*    Traverse through the given array*/

    for (int i = 0; i < n; i++)
    {

/*      Add current element to sum*/

      sum += arr[i];

/*      To handle sum=0 at last index*/

      if (sum == 0)
        max_len = i + 1;

/*      If this sum is seen before,
      then update max_len if required*/

      if (hM.ContainsKey(sum))
        max_len = Math.Max(max_len, i - hM[sum]);

/*Else put this sum in hash table*/

else 
        hM[sum] = i;
    }
    return max_len;
  }

/*  Driver code*/

  static public void Main ()
  {
    int[] arr1 = {0, 1, 0, 1, 1, 1, 1};
    int[] arr2 = {1, 1, 1, 1, 1, 0, 1};
    int n = arr1.Length;
    Console.WriteLine(longestCommonSum(arr1, arr2, n));
  }
}

/*C# program to sort an array according absolute
difference with x.*/

using System;
using System.Collections.Generic;
public class GFG
{

/*  Function to sort an array according absolute
  difference with x.*/

  static void rearrange(int[] arr, int n, int x)
  {
    SortedDictionary<int,List<int>> m = new SortedDictionary<int,List<int>>();

/*    Store values in a map with the difference
    with X as key*/

    for (int i = 0; i < n; i++)
    {
      int diff = Math.Abs(x - arr[i]);
      if (m.ContainsKey(diff))
      {
        List<int> al = m;
        al.Add(arr[i]);
        m = al;
      }
      else
      {
        List<int> al = new  List<int>();
        al.Add(arr[i]);
        m.Add(diff, al);
      }
    }

/*    Update the values of array*/

    int index = 0;
    foreach(int entry in m.Keys)
    {
      List<int> al = m[entry];
      for (int i = 0; i < al.Count; i++)
        arr[index++] = al[i];
    }
  }

/*  Function to print the array*/

  static void printArray(int[] arr, int n)
  {
    for (int i = 0; i < n; i++)
      Console.Write(arr[i] + " ");
  }

/*  Driver code*/

  static public void Main (){
    int[] arr = {10, 5, 3, 9 ,2};
    int n = arr.Length;
    int x = 7;
    rearrange(arr, n, x);
    printArray(arr, n);
  }
}

/*C# implementation of naive method
for sorting an array in wave form.*/

using System;
class SortWave {

/*    A utility method to swap two numbers.*/

    void swap(int[] arr, int a, int b)
    {
        int temp = arr[a];
        arr[a] = arr[b];
        arr[b] = temp;
    }

/*    This function sorts arr[0..n-1] in wave form, i.e.,
    arr[0] >= arr[1] <= arr[2] >= arr[3] <= arr[4]..*/

    void sortInWave(int[] arr, int n)
    {

/*        Sort the input array*/

        Array.Sort(arr);

/*        Swap adjacent elements*/

        for (int i = 0; i < n - 1; i += 2)
            swap(arr, i, i + 1);
    }

/*    Driver method*/

    public static void Main()
    {
        SortWave ob = new SortWave();
        int[] arr = { 10, 90, 49, 2, 1, 5, 23 };
        int n = arr.Length;
        ob.sortInWave(arr, n);
        for (int i = 0; i < n; i++)
        Console.Write(arr[i] + " ");
    }
}

/*A O(n) C# program to sort an
input array in wave form*/

using System;
class SortWave {

/*    A utility method to swap two numbers.*/

    void swap(int[] arr, int a, int b)
    {
        int temp = arr[a];
        arr[a] = arr[b];
        arr[b] = temp;
    }

/*    This function sorts arr[0..n-1] in wave form, i.e.,
    arr[0] >= arr[1] <= arr[2] >= arr[3] <= arr[4]....*/

    void sortInWave(int[] arr, int n)
    {

/*        Traverse all even elements*/

        for (int i = 0; i < n; i += 2) {

/*            If current even element is smaller
            than previous*/

            if (i > 0 && arr[i - 1] > arr[i])
                swap(arr, i - 1, i);

/*            If current even element is smaller
            than next*/

            if (i < n - 1 && arr[i] < arr[i + 1])
                swap(arr, i, i + 1);
        }
    }

/*    Driver program to test above function*/

    public static void Main()
    {
        SortWave ob = new SortWave();
        int[] arr = { 10, 90, 49, 2, 1, 5, 23 };
        int n = arr.Length;
        ob.sortInWave(arr, n);
        for (int i = 0; i < n; i++)
        Console.Write(arr[i] + " ");
    }
}

/*C# program to Merge an array of
size n into another array of size m + n*/

using System;
class GFG {

/* Function to move m elements at
       the end of array mPlusN[] */

    public virtual void moveToEnd(int[] mPlusN, int size)
    {
        int i, j = size - 1;
        for (i = size - 1; i >= 0; i--)
        {
            if (mPlusN[i] != -1) {
                mPlusN[j] = mPlusN[i];
                j--;
            }
        }
    }

/* Merges array N[] of size n
       into array mPlusN[] of size m+n*/

    public virtual void merge(int[] mPlusN,
                              int[] N, int m,
                              int n)
    {
        int i = n;

/* Current index of i/p
           part of mPlusN[]*/

        int j = 0;

/* Current index of N[]*/

        int k = 0;

/* Current index of output mPlusN[]*/

        while (k < (m + n))
        {

/* Take an element from mPlusN[] if
            a) value of the picked element is smaller
               and we have not reached end of it
            b) We have reached end of N[] */

            if ((j == n)(i < (m + n)
                && mPlusN[i] <= N[j]))
            {
                mPlusN[k] = mPlusN[i];
                k++;
                i++;
            }

/*Otherwise take element from N[]*/

else 
            {
                mPlusN[k] = N[j];
                k++;
                j++;
            }
        }
    }

/* Utility that prints out
       an array on a line */

    public virtual void printArray(int[] arr, int size)
    {
        int i;
        for (i = 0; i < size; i++) {
            Console.Write(arr[i] + " ");
        }
        Console.WriteLine("");
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {
        GFG mergearray = new GFG();

/* Initialize arrays */

        int[] mPlusN = new int[] { 2,  8,  -1, -1, -1,
                                   13, -1, 15, 20 };
        int[] N = new int[] { 5, 7, 9, 25 };
        int n = N.Length;
        int m = mPlusN.Length - n;

/*Move the m elements at the
          end of mPlusN*/

        mergearray.moveToEnd(mPlusN, m + n);

/*Merge N[] into mPlusN[] */

        mergearray.merge(mPlusN, N, m, n);

/* Print the resultant mPlusN */

        mergearray.printArray(mPlusN, m + n);
    }
}

/*C# program to test whether array
can be sorted by swapping adjacent
elements using boolean array*/

using System;
class GFG {

/*    Return true if array can be
    sorted otherwise false*/

    static bool sortedAfterSwap(int[] A,
                                bool[] B,
                                int n)
    {
        int i, j;

/*        Check bool array B and sorts
        elements for continuous sequence of 1*/

        for (i = 0; i < n - 1; i++) {
            if (B[i]) {
                j = i;
                while (B[j]) {
                    j++;
                }

/*                Sort array A from i to j*/

                Array.Sort(A, i, 1 + j);
                i = j;
            }
        }

/*        Check if array is sorted or not*/

        for (i = 0; i < n; i++) {
            if (A[i] != i + 1) {
                return false;
            }
        }
        return true;
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] A = { 1, 2, 5, 3, 4, 6 };
        bool[] B = { false, true, true, true, false };
        int n = A.Length;
        if (sortedAfterSwap(A, B, n)) {
            Console.WriteLine("A can be sorted");
        }
        else {
            Console.WriteLine("A can not be sorted");
        }
    }
}

/*C# program to test whether array
can be sorted by swapping adjacent
elements using boolean array*/

using System;
class GFG
{

/*    Return true if array can be
    sorted otherwise false*/

    static int sortedAfterSwap(int[] A,
                               int[] B, int n)
    {
        int t = 0;
        for (int i = 0; i < n - 1; i++)
        {
            if (B[i] != 0)
            {
                if (A[i] != i + 1)
                    t = A[i];
                    A[i] = A[i + 1];
                    A[i + 1] = t;
            }
        }

/*        Check if array is sorted or not*/

        for (int i = 0; i < n; i++)
        {
            if (A[i] != i + 1)
                return 0;
        }
        return 1;
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] A = { 1, 2, 5, 3, 4, 6 };
        int[] B = { 0, 1, 1, 1, 0 };
        int n = A.Length;
        if (sortedAfterSwap(A, B, n) == 0)
            Console.WriteLine("A can be sorted");
        else
            Console.WriteLine("A can not be sorted");
    }
}

/*C# program to sort an array with two types
of values in one traversal.*/

using System;
class GFG {
    static void segregate0and1(int []arr, int n)
    {

/* Method for segregation 0 and 1
given input array */
        int type0 = 0;
        int type1 = n - 1;
        while (type0 < type1)
        {
            if (arr[type0] == 1)
            {
                arr[type0] = arr[type0] + arr[type1];
                arr[type1] = arr[type0]-arr[type1];
                arr[type0] = arr[type0]-arr[type1];
                type1--;
            }
            else {
                type0++;
            }
        }
    }

/*    Driver program*/

    public static void Main()
    {
        int []arr = { 1, 1, 1, 0, 1, 0, 0,
                             1, 1, 1, 1 };
        segregate0and1(arr, arr.Length);
        for (int i = 0; i < arr.Length; i++)
            Console.Write(arr[i] + " ");
    }
}

/*C# program to count inversions
in an array*/

using System;
using System.Collections.Generic;
class GFG {
    static int[] arr = new int[] { 1, 20, 6, 4, 5 };
    static int getInvCount(int n)
    {
        int inv_count = 0;
        for (int i = 0; i < n - 1; i++)
            for (int j = i + 1; j < n; j++)
                if (arr[i] > arr[j])
                    inv_count++;
        return inv_count;
    }

/*    Driver code*/

    public static void Main()
    {
        Console.WriteLine("Number of "
                          + "inversions are "
                          + getInvCount(arr.Length));
    }
}

/*C# code to find Two elements
whose sum is closest to zero*/

using System;
class GFG
{
static void minAbsSumPair(int []arr,
                        int arr_size)
    {
    int l, r, min_sum, sum, min_l, min_r;

/* Array should have at least two elements*/

    if (arr_size < 2)
    {
        Console.Write("Invalid Input");
        return;
    }

/* Initialization of values */

    min_l = 0;
    min_r = 1;
    min_sum = arr[0] + arr[1];
    for (l = 0; l < arr_size - 1; l++)
    {
        for (r = l+1; r < arr_size; r++)
        {
            sum = arr[l] + arr[r];
            if (Math.Abs(min_sum) > Math.Abs(sum))
            {
                min_sum = sum;
                min_l = l;
                min_r = r;
            }
        }
    }
    Console.Write(" The two elements whose "+
                        "sum is minimum are "+
                    arr[min_l]+ " and "+arr[min_r]);
    }

/*    main function*/

    public static void Main ()
    {
        int []arr = {1, 60, -10, 70, -80, 85};
        minAbsSumPair(arr, 6);
    }
}

/*C# implementation using STL*/

using System;
class GFG{

/*Modified to sort by abolute values*/

static void findMinSum(int[] arr, int n)
{
    for(int i = 1; i < n; i++)
    {
        if (!(Math.Abs(arr[i - 1]) <
              Math.Abs(arr[i])))
        {
            int temp = arr[i - 1];
            arr[i - 1] = arr[i];
            arr[i] = temp;
        }
    }
    int min = Int32.MaxValue;
    int x = 0, y = 0;
    for(int i = 1; i < n; i++)
    {

/*        Absolute value shows how close
        it is to zero*/

        if (Math.Abs(arr[i - 1] + arr[i]) <= min)
        {

/*            If found an even close value
            update min and store the index*/

            min = Math.Abs(arr[i - 1] + arr[i]);
            x = i - 1;
            y = i;
        }
    }
    Console.WriteLine("The two elements whose " +
                      "sum is minimum are " +
                      arr[x] + " and " + arr[y]);
}

/*Driver Code*/

static void Main()
{
    int[] arr = { 1, 60, -10, 70, -80, 85 };
    int n = arr.Length;
    findMinSum(arr, n);
}
}

/*Program to find the shortest
subarray which is unsorted.*/

using System;
class GFG {

/*    boolean function to check
    array elements are in the
    increasing order or not*/

    public static bool increasing(int[] a, int n)
    {
        for (int i = 0; i < n - 1; i++)
            if (a[i] >= a[i + 1])
                return false;
        return true;
    }

/*    boolean function to check
    array elements are in the
    decreasing order or not*/

    public static bool decreasing(int[] arr, int n)
    {
        for (int i = 0; i < n - 1; i++)
            if (arr[i] < arr[i + 1])
                return false;
        return true;
    }
    public static int shortestUnsorted(int[] a, int n)
    {

/*        increasing and decreasing are
        two functions. function return
        true value then print 0 else 3*/

         if (increasing(a, n) == true ||
             decreasing(a, n) == true)
            return 0;
        else
            return 3;
    }

/*    Driver program*/

    public static void Main()
    {
        int[] ar = new int[] { 7, 9, 10, 8, 11 };
        int n = ar.Length;
        Console.WriteLine(shortestUnsorted(ar, n));
    }
}

/*C# program to find
minimum number of swaps
required to sort an array*/

using System;
public class GFG
{

/*swap function*/

    static void swap(int[] arr, int i, int j)
    {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

/*indexOf function*/

    static int indexOf(int[] arr, int ele)
    {
        for (int i = 0; i < arr.Length; i++)
        {
            if (arr[i] == ele) {
                return i;
            }
        }
        return -1;
    }

/*    Return the minimum number
    of swaps required to sort the array*/

    static int minSwaps(int[] arr, int N)
    {
        int ans = 0;
        int[] temp = new int[N];
        Array.Copy(arr, temp, N);
        Array.Sort(temp);
        for (int i = 0; i < N; i++)
        {

/*            This is checking whether
            the current element is
            at the right place or not*/

            if (arr[i] != temp[i])
            {
                ans++;

/*                Swap the current element
                with the right index
                so that arr[0] to arr[i] is sorted*/

                swap(arr, i, indexOf(arr, temp[i]));
            }
        }
        return ans;
    }

/*    Driver program to test
    the above function*/

    static public void Main (){
        int[] a
            = { 101, 758, 315, 730, 472,
                         619, 460, 479 };
        int n = a.Length;

/*        Output will be 5*/

        Console.WriteLine(minSwaps(a, n));
    }
}

/*C# program to find union of
two sorted arrays*/

using System;
class GFG {

/* Function prints union of arr1[] and arr2[]
    m is the number of elements in arr1[]
    n is the number of elements in arr2[] */

    static int printUnion(int[] arr1,
                          int[] arr2, int m, int n)
    {
        int i = 0, j = 0;
        while (i < m && j < n) {
            if (arr1[i] < arr2[j])
                Console.Write(arr1[i++] + " ");
            else if (arr2[j] < arr1[i])
                Console.Write(arr2[j++] + " ");
            else {
                Console.Write(arr2[j++] + " ");
                i++;
            }
        }

/* Print remaining elements of
        the larger array */

        while (i < m)
            Console.Write(arr1[i++] + " ");
        while (j < n)
            Console.Write(arr2[j++] + " ");
        return 0;
    }

/* Driver program to test above function */

    public static void Main()
    {
        int[] arr1 = { 1, 2, 4, 5, 6 };
        int[] arr2 = { 2, 3, 5, 7 };
        int m = arr1.Length;
        int n = arr2.Length;
        printUnion(arr1, arr2, m, n);
    }
}

/*C# program to find union of two
sorted arrays (Handling Duplicates)*/

using System;
class GFG {
    static void UnionArray(int[] arr1,
                           int[] arr2)
    {

/*        Taking max element present
        in either array*/

        int m = arr1[arr1.Length - 1];
        int n = arr2[arr2.Length - 1];
        int ans = 0;
        if (m > n)
            ans = m;
        else
            ans = n;

/*        Finding elements from 1st array
        (non duplicates only). Using
        another array for storing union
        elements of both arrays
        Assuming max element present
        in array is not more than 10^7*/

        int[] newtable = new int[ans + 1];

/*        First element is always
        present in final answer*/

        Console.Write(arr1[0] + " ");

/*        Incrementing the First element's
        count in it's corresponding
        index in newtable*/

        ++newtable[arr1[0]];

/*        Starting traversing the first
        array from 1st index till last*/

        for (int i = 1; i < arr1.Length; i++) {

/*            Checking whether current
            element is not equal to
            it's previous element*/

            if (arr1[i] != arr1[i - 1]) {
                Console.Write(arr1[i] + " ");
                ++newtable[arr1[i]];
            }
        }

/*        Finding only non common
        elements from 2nd array*/

        for (int j = 0; j < arr2.Length; j++) {

/*            By checking whether it's already
            present in newtable or not*/

            if (newtable[arr2[j]] == 0) {
                Console.Write(arr2[j] + " ");
                ++newtable[arr2[j]];
            }
        }
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] arr1 = { 1, 2, 2, 2, 3 };
        int[] arr2 = { 2, 3, 4, 5 };
        UnionArray(arr1, arr2);
    }
}

/*C# program to find Intersection of
two sorted arrays*/

using System;
class GFG {

/* Function prints Intersection of arr1[]
    and arr2[] m is the number of elements in arr1[]
    n is the number of elements in arr2[] */

    static void printIntersection(int[] arr1,
                                  int[] arr2, int m, int n)
    {
        int i = 0, j = 0;
        while (i < m && j < n) {
            if (arr1[i] < arr2[j])
                i++;
            else if (arr2[j] < arr1[i])
                j++;
            else {
                Console.Write(arr2[j++] + " ");
                i++;
            }
        }
    }

