        printIntersection(arr1, arr2, m, n);
    }
}

/*A C# program to print union and
intersection of two unsorted arrays*/

using System;
class GFG {

/*    Prints union of arr1[0..m-1] and arr2[0..n-1]*/

    static void printUnion(int[] arr1, int[] arr2, int m,
                           int n)
    {

/*        Before finding union, make
        sure arr1[0..m-1] is smaller*/

        if (m > n) {
            int[] tempp = arr1;
            arr1 = arr2;
            arr2 = tempp;
            int temp = m;
            m = n;
            n = temp;
        }

/*        Now arr1[] is smaller
        Sort the first array and print
        its elements (these two steps can
        be swapped as order in output is
        not important)*/

        Array.Sort(arr1);
        for (int i = 0; i < m; i++)
            Console.Write(arr1[i] + " ");

/*        Search every element of bigger
        array in smaller array and print
        the element if not found*/

        for (int i = 0; i < n; i++) {
            if (binarySearch(arr1, 0, m - 1, arr2[i]) == -1)
                Console.Write(arr2[i] + " ");
        }
    }

/*    Prints intersection of arr1[0..m-1]
    and arr2[0..n-1]*/

    static void printIntersection(int[] arr1, int[] arr2,
                                  int m, int n)
    {

/*        Before finding intersection,
        make sure arr1[0..m-1] is smaller*/

        if (m > n) {
            int[] tempp = arr1;
            arr1 = arr2;
            arr2 = tempp;
            int temp = m;
            m = n;
            n = temp;
        }

/*        Now arr1[] is smaller
        Sort smaller array arr1[0..m-1]*/

        Array.Sort(arr1);

/*        Search every element of bigger array in
        smaller array and print the element if found*/

        for (int i = 0; i < n; i++) {
            if (binarySearch(arr1, 0, m - 1, arr2[i]) != -1)
                Console.Write(arr2[i] + " ");
        }
    }

/*    A recursive binary search function.
    It returns location of x in given
    array arr[l..r] is present, otherwise -1*/

    static int binarySearch(int[] arr, int l, int r, int x)
    {
        if (r >= l) {
            int mid = l + (r - l) / 2;

/*            If the element is present at
            the middle itself*/

            if (arr[mid] == x)
                return mid;

/*            If element is smaller than mid, then it
            can only be present in left subarray*/

            if (arr[mid] > x)
                return binarySearch(arr, l, mid - 1, x);

/*            Else the element can only be
            present in right subarray*/

            return binarySearch(arr, mid + 1, r, x);
        }

/*        We reach here when element is
        not present in array*/

        return -1;
    }

/*    Driver Code*/

    static public void Main()
    {
        int[] arr1 = { 7, 1, 5, 2, 3, 6 };
        int[] arr2 = { 3, 8, 6, 20, 7 };
        int m = arr1.Length;
        int n = arr2.Length;

/*        Function call*/

        Console.WriteLine("Union of two arrays is ");
        printUnion(arr1, arr2, m, n);
        Console.WriteLine("");
        Console.WriteLine("Intersection of two arrays is ");
        printIntersection(arr1, arr2, m, n);
    }
}

/*C# code to find intersection when
elements may not be distinct*/

using System;
class GFG {

/*    Function to find intersection*/

    static void intersection(int[] a, int[] b, int n, int m)
    {
        int i = 0, j = 0;
        while (i < n && j < m) {
            if (a[i] > b[j]) {
                j++;
            }
            else if (b[j] > a[i]) {
                i++;
            }
            else {

/*                when both are equal*/

                Console.Write(a[i] + " ");
                i++;
                j++;
            }
        }
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] a = { 1, 3, 2, 3, 4, 5, 5, 6 };
        int[] b = { 3, 3, 5 };
        int n = a.Length;
        int m = b.Length;

/*        sort*/

        Array.Sort(a);
        Array.Sort(b);

/*        Function call*/

        intersection(a, b, n, m);
    }
}

/*C# program to find union and intersection
using Hashing*/

using System;
using System.Linq;
using System.Collections.Generic;
class GFG
{

/*    Prints union of arr1[0..m-1] and arr2[0..n-1]*/

    static void printUnion(int []arr1, int []arr2)
    {
        HashSet<int> hs = new HashSet<int>();
        for (int i = 0; i < arr1.Length; i++)
            hs.Add(arr1[i]);    
        for (int i = 0; i < arr2.Length; i++)
            hs.Add(arr2[i]);
            Console.WriteLine(string.Join(", ", hs));    
    }

/*    Prints intersection of arr1[0..m-1] and arr2[0..n-1]*/

    static void printIntersection(int []arr1, int []arr2)
    {
        HashSet<int> hs = new HashSet<int>();
        for (int i = 0; i < arr1.Length; i++)
            hs.Add(arr1[i]);
        for (int i = 0; i < arr2.Length; i++)
            if (hs.Contains(arr2[i]))
            Console.Write(arr2[i] + " ");
    }

/*    Driver Code*/

    static void Main()
    {
        int []arr1 = {7, 1, 5, 2, 3, 6};
        int []arr2 = {3, 8, 6, 20, 7};

/*        Function call*/

        Console.WriteLine("Union of two arrays is : ");
        printUnion(arr1, arr2);
        Console.WriteLine("\nIntersection of two arrays is : ");
        printIntersection(arr1, arr2);
    }
}

/*C# program to find union and intersection
using similar Hashing Technique
without using any predefined Java Collections
Time Complexity best case & avg case = O(m+n)
Worst case = O(nlogn)
package com.arrays.math;*/

using System;
class UnsortedIntersectionUnion
{

/*        Prints intersection of arr1[0..n1-1] and
        arr2[0..n2-1]*/

    public void findPosition(int []a, int []b)
    {
        int v = (a.Length + b.Length);
        int []ans = new int[v];
        int zero1 = 0;
        int zero2 = 0;
        Console.Write("Intersection : ");

/*        Iterate first array*/

        for (int i = 0; i < a.Length; i++)
            zero1 = iterateArray(a, v, ans, i);

/*        Iterate second array*/

        for (int j = 0; j < b.Length; j++)
            zero2 = iterateArray(b, v, ans, j);
        int zero = zero1 + zero2;
        placeZeros(v, ans, zero);
        printUnion(v, ans, zero);
    }

/*    Prints union of arr1[0..n1-1]
    and arr2[0..n2-1]*/

    private void printUnion(int v, int[] ans, int zero)
    {
        int zero1 = 0;
        Console.Write("\nUnion : ");
        for (int i = 0; i < v; i++)
        {
            if ((zero == 0 && ans[i] == 0) ||
                    (ans[i] == 0 && zero1 > 0))
                continue;
            if (ans[i] == 0)
                zero1++;
            Console.Write(ans[i] + ",");
        }
    }

/*placeZeroes function*/

    private void placeZeros(int v, int[] ans, int zero)
    {
        if (zero == 2)
        {
            Console.WriteLine("0");
            int []d = { 0 };
            placeValue(d, ans, 0, 0, v);
        }
        if (zero == 1)
        {
            int []d = { 0 };
            placeValue(d, ans, 0, 0, v);
        }
    }

/*    Function to itreate array*/

    private int iterateArray(int[] a, int v,
                            int[] ans, int i)
    {
        if (a[i] != 0)
        {
            int p = a[i] % v;
            placeValue(a, ans, i, p, v);
        } else
            return 1;
        return 0;
    }

/*placeValue function*/

    private void placeValue(int[] a, int[] ans,
                                int i, int p, int v)
    {
        p = p % v;
        if (ans[p] == 0)
            ans[p] = a[i];
        else {
            if (ans[p] == a[i])
                Console.Write(a[i] + ",");
            else
            {

/*                Hashing collision happened increment
                position and do recursive call*/

                p = p + 1;
                placeValue(a, ans, i, p, v);
            }
        }
    }

/*    Driver code*/

    public static void Main()
    {
        int []a = { 7, 1, 5, 2, 3, 6 };
        int []b = { 3, 8, 6, 20, 7 };
        UnsortedIntersectionUnion uiu = new UnsortedIntersectionUnion();
        uiu.findPosition(a, b);
    }
}

/*C# program to sort an
array of 0, 1 and 2*/

using System;
class GFG {

/*    Sort the input array, the array is assumed to
    have values in {0, 1, 2}*/

    static void sort012(int[] a, int arr_size)
    {
        int lo = 0;
        int hi = arr_size - 1;
        int mid = 0, temp = 0;
        while (mid <= hi) {
            switch (a[mid]) {
            case 0: {
                temp = a[lo];
                a[lo] = a[mid];
                a[mid] = temp;
                lo++;
                mid++;
                break;
            }
            case 1:
                mid++;
                break;
            case 2: {
                temp = a[mid];
                a[mid] = a[hi];
                a[hi] = temp;
                hi--;
                break;
            }
            }
        }
    }

/* Utility function to print array arr[] */

    static void printArray(int[] arr, int arr_size)
    {
        int i;
        for (i = 0; i < arr_size; i++)
            Console.Write(arr[i] + " ");
        Console.WriteLine("");
    }

/*Driver function to check for above functions*/

    public static void Main()
    {
        int[] arr = { 0, 1, 1, 0, 1, 2, 1, 2, 0, 0, 0, 1 };
        int arr_size = arr.Length;
        sort012(arr, arr_size);
        Console.Write("Array after seggregation ");
        printArray(arr, arr_size);
    }
}

/*C# implementation of the approach*/

using System;
class GFG {

/*    Utility function to print the contents of an array*/

    static void printArr(int[] arr, int n)
    {
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }

/*    Function to sort the array of 0s, 1s and 2s*/

    static void sortArr(int[] arr, int n)
    {
        int i, cnt0 = 0, cnt1 = 0, cnt2 = 0;

/*        Count the number of 0s, 1s and 2s in the array*/

        for (i = 0; i < n; i++) {
            switch (arr[i]) {
            case 0:
                cnt0++;
                break;
            case 1:
                cnt1++;
                break;
            case 2:
                cnt2++;
                break;
            }
        }

/*        Update the array*/

        i = 0;

/*        Store all the 0s in the beginning*/

        while (cnt0 > 0) {
            arr[i++] = 0;
            cnt0--;
        }

/*        Then all the 1s*/

        while (cnt1 > 0) {
            arr[i++] = 1;
            cnt1--;
        }

/*        Finally all the 2s*/

        while (cnt2 > 0) {
            arr[i++] = 2;
            cnt2--;
        }

/*        Print the sorted array*/

        printArr(arr, n);
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 0, 1, 1, 0, 1, 2, 1, 2, 0, 0, 0, 1 };
        int n = arr.Length;
        sortArr(arr, n);
    }
}

/*C# program to find the Minimum length Unsorted Subarray,
sorting which makes the complete array sorted*/

using System;
class GFG
{
    static void printUnsorted(int []arr, int n)
    {
    int s = 0, e = n-1, i, max, min;

/*    step 1(a) of above algo*/

    for (s = 0; s < n-1; s++)
    {
        if (arr[s] > arr[s+1])
        break;
    }
    if (s == n-1)
    {
        Console.Write("The complete " +
                            "array is sorted");
        return;
    }

/*    step 1(b) of above algo*/

    for(e = n - 1; e > 0; e--)
    {
        if(arr[e] < arr[e-1])
        break;
    }

/*    step 2(a) of above algo*/

    max = arr[s]; min = arr[s];
    for(i = s + 1; i <= e; i++)
    {
        if(arr[i] > max)
            max = arr[i];
        if(arr[i] < min)
            min = arr[i];
    }

/*    step 2(b) of above algo*/

    for( i = 0; i < s; i++)
    {
        if(arr[i] > min)
        {
            s = i;
            break;
        }    
    }

/*    step 2(c) of above algo*/

    for( i = n -1; i >= e+1; i--)
    {
        if(arr[i] < max)
        {
            e = i;
            break;
        }
    }

/*    step 3 of above algo*/

    Console.Write(" The unsorted subarray which"+
            " makes the given array sorted lies \n"+
              " between the indices "+s+" and "+e);
    return;
    }
    public static void Main()
    {
        int []arr = {10, 12, 20, 30, 25, 40,
                                32, 31, 35, 50, 60};
        int arr_size = arr.Length;
        printUnsorted(arr, arr_size);
    }
}

/*C# code to count the number of
possible triangles using brute
force approach*/

using System;
class GFG{

/*    Function to count all possible
    triangles with arr[] elements*/

    static int findNumberOfTriangles(int[] arr, int n)
    {

/*        Count of triangles*/

        int count = 0;

/*        The three loops select three
        different values from array*/

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {

/*                The innermost loop checks for
                the triangle property*/

                for (int k = j + 1; k < n; k++)

/*                    Sum of two sides is greater
                    than the third*/

                    if (
                        arr[i] + arr[j] > arr[k]
                        && arr[i] + arr[k] > arr[j]
                        && arr[k] + arr[j] > arr[i])
                        count++;
            }
        }
        return count;
    }

/*    Driver code*/

    static public void Main ()
    {
        int[] arr = { 10, 21, 22, 100, 101, 200, 300 };
        int size = arr.Length;
        Console.WriteLine("Total number of triangles possible is "+findNumberOfTriangles(arr, size));
    }
}

/*C# program to count number
of triangles that can be
formed from given array*/

using System;
class GFG {

/*    Function to count all
    possible triangles
    with arr[] elements*/

    static int findNumberOfTriangles(int[] arr)
    {
        int n = arr.Length;

/*        Sort the array elements
        in non-decreasing order*/

        Array.Sort(arr);

/*        Initialize count
        of triangles*/

        int count = 0;

/*        Fix the first element. We
        need to run till n-3 as
        the other two elements are
        selected from arr[i+1...n-1]*/

        for (int i = 0; i < n - 2; ++i) {

/*            Initialize index of the
            rightmost third element*/

            int k = i + 2;

/*            Fix the second element*/

            for (int j = i + 1; j < n; ++j) {

/* Find the rightmost element
                which is smaller than the sum
                of two fixed elements. The
                important thing to note here
                is, we use the previous value
                of k. If value of arr[i] +
                arr[j-1] was greater than arr[k],
                then arr[i] + arr[j] must be
                greater than k, because the
                array is sorted. */

                while (k < n && arr[i] + arr[j] > arr[k])
                    ++k;

/* Total number of possible triangles
                that can be formed with the two
                fixed elements is k - j - 1. The
                two fixed elements are arr[i] and
                arr[j]. All elements between arr[j+1]
                to arr[k-1] can form a triangle with
                arr[i] and arr[j]. One is subtracted
                from k because k is incremented one
                extra in above while loop. k will
                always be greater than j. If j becomes
                equal to k, then above loop will
                increment k, because arr[k] + arr[i]
                is always/ greater than arr[k] */

                if (k > j)
                    count += k - j - 1;
            }
        }
        return count;
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] arr = { 10, 21, 22, 100,
                      101, 200, 300 };
        Console.WriteLine("Total number of triangles is " + findNumberOfTriangles(arr));
    }
}

/*C# implementation of the above approach*/

using System;
class GFG {

/*CountTriangles function*/

static void CountTriangles(int[] A)
    {
        int n = A.Length;
        Array.Sort(A);
        int count = 0;
        for (int i = n - 1; i >= 1; i--) {
            int l = 0, r = i - 1;
            while (l < r) {
                if (A[l] + A[r] > A[i]) {

/*                    If it is possible with a[l], a[r]
                    and a[i] then it is also possible
                    with a[l+1]..a[r-1], a[r] and a[i]*/

                    count += r - l;

/*                    checking for more possible solutions*/

                    r--;
                }

/*if not possible check for higher values of arr[l]*/

else 
                {
                    l++;
                }
            }
        }
        Console.Write("No of possible solutions: " + count);
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] A = { 4, 3, 5, 7, 6 };
        CountTriangles(A);
    }
}

/*C# program to finds number of pairs (x, y)
in an array such that x^y > y^x*/

using System;
class GFG {

/*    Function to return count of pairs
    with x as one element of the pair.
    It mainly looks for all values in Y[]
    where x ^ Y[i] > Y[i] ^ x*/

    static int count(int x, int[] Y, int n, int[] NoOfY)
    {

/*        If x is 0, then there cannot be any
        value in Y such that x^Y[i] > Y[i]^x*/

        if (x == 0)
            return 0;

/*        If x is 1, then the number of pais
        is equal to number of zeroes in Y[]*/

        if (x == 1)
            return NoOfY[0];

/*        Find number of elements in Y[] with
        values greater than x getting
        upperbound of x with binary search*/

        int idx = Array.BinarySearch(Y, x);
        int ans;
        if (idx < 0) {
            idx = Math.Abs(idx + 1);
            ans = Y.Length - idx;
        }
        else {
            while (idx < n && Y[idx] == x) {
                idx++;
            }
            ans = Y.Length - idx;
        }

/*        If we have reached here, then x
        must be greater than 1, increase
        number of pairs for y = 0 and y = 1*/

        ans += (NoOfY[0] + NoOfY[1]);

/*        Decrease number of pairs
        for x = 2 and (y = 4 or y = 3)*/

        if (x == 2)
            ans -= (NoOfY[3] + NoOfY[4]);

/*        Increase number of pairs for x = 3 and y = 2*/

        if (x == 3)
            ans += NoOfY[2];
        return ans;
    }

/*    Function to that returns count
    of pairs (x, y) such that x belongs
    to X[], y belongs to Y[] and x^y > y^x*/

    static int countPairs(int[] X, int[] Y, int m, int n)
    {

/*        To store counts of 0, 1, 2, 3 and 4 in array Y*/

        int[] NoOfY = new int[5];
        for (int i = 0; i < n; i++)
            if (Y[i] < 5)
                NoOfY[Y[i]]++;

/*        Sort Y[] so that we can do binary search in it*/

        Array.Sort(Y);

/*Initialize result*/

int total_pairs = 0;

/*        Take every element of X and count pairs with it*/

        for (int i = 0; i < m; i++)
            total_pairs += count(X[i], Y, n, NoOfY);
        return total_pairs;
    }

/*    Driver method*/

    public static void Main()
    {
        int[] X = { 2, 1, 6 };
        int[] Y = { 1, 5 };
        Console.Write(
            "Total pairs = "
            + countPairs(X, Y, X.Length, Y.Length));
    }
}

/*A simple C# program to count pairs with
difference k*/

using System;
class GFG {
    static int countPairsWithDiffK(int []arr,
                                int n, int k)
    {
        int count = 0;

/*        Pick all elements one by one*/

        for (int i = 0; i < n; i++)
        {

/*            See if there is a pair
            of this picked element*/

            for (int j = i + 1; j < n; j++)
                if (arr[i] - arr[j] == k ||
                      arr[j] - arr[i] == k)
                    count++;
        }
        return count;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = { 1, 5, 3, 4, 2 };
        int n = arr.Length;
        int k = 3;
        Console.WriteLine("Count of pairs with "
                             + " given diff is "
               + countPairsWithDiffK(arr, n, k));
    }
}

/*A sorting base C# program to
count pairs with difference k*/

using System;
class GFG {

/*    Standard binary search function*/

    static int binarySearch(int []arr, int low,
                            int high, int x)
    {
        if (high >= low)
        {
            int mid = low + (high - low) / 2;
            if (x == arr[mid])
                return mid;
            if (x > arr[mid])
                return binarySearch(arr, (mid + 1),
                                          high, x);
            else
                return binarySearch(arr, low,
                                     (mid - 1), x);
        }
        return -1;
    }

/*    Returns count of pairs with
    difference k in arr[] of size n.*/

    static int countPairsWithDiffK(int []arr,
                                   int n, int k)
    {
        int count = 0, i;

/*        Sort array elements*/

        Array.Sort(arr);

/*        code to remove duplicates from arr[]

/*       Pick a first element point*/

        for (i = 0; i < n - 1; i++)
            if (binarySearch(arr, i + 1, n - 1,
                            arr[i] + k) != -1)
                count++;
        return count;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = { 1, 5, 3, 4, 2 };
        int n = arr.Length;
        int k = 3;
        Console.WriteLine("Count of pairs with"
                            + " given diff is "
              + countPairsWithDiffK(arr, n, k));
    }
}

/*A sorting based C# program to count
pairs with difference k*/

using System;
class GFG {

/* Returns count of pairs with
    difference k in arr[] of size n. */

    static int countPairsWithDiffK(int []arr,
                                int n, int k)
    {
        int count = 0;

/*        Sort array elements*/

        Array.Sort(arr);
        int l = 0;
        int r = 0;
        while(r < n)
        {
            if(arr[r] - arr[l] == k)
            {
                count++;
                l++;
                r++;
            }
            else if(arr[r] - arr[l] > k)
                l++;

/*arr[r] - arr[l] < sum*/

else 
                r++;
        }
        return count;
    }

/*    Driver program to test above function*/

    public static void Main()
    {
        int []arr = {1, 5, 3, 4, 2};
        int n = arr.Length;
        int k = 3;
        Console.Write("Count of pairs with "
                        + "given diff is " +
            countPairsWithDiffK(arr, n, k));
    }
}

using System;
class GFG{

static int BS(int[] arr, int X, int low)
{
    int high = arr.Length - 1;
    int ans = arr.Length;
    while (low <= high)
    {
        int mid = low + (high - low) / 2;
        if (arr[mid] >= X)
        {
            ans = mid;
            high = mid - 1;
        }
        else low = mid + 1;
    }
    return ans;
}

static int countPairsWithDiffK(int[] arr, int N, int k)
{
    int count = 0;
    Array.Sort(arr);
    for(int i = 0 ; i < N ; ++i)
    {
        int X = BS(arr, arr[i] + k, i + 1);
        if (X != N)
        {
            int Y = BS(arr, arr[i] + k + 1, i + 1);
            count += Y - X;
        }
    }
    return count;
}

/*Driver code*/

public static void Main(string[] args)
{
    int []arr = { 1, 3, 5, 8, 6, 4, 6 };
    int n = arr.Length;
    int k = 2;
    Console.WriteLine("Count of pairs with given diff is " +
                      countPairsWithDiffK(arr, n, k));
}
}

/*C# program to construct an
array from its pair-sum array*/

using System;
class PairSum
{

/*    Fills element in arr[] from its
    pair sum array pair[].
    n is size of arr[]*/

    static void constructArr(int []arr, int []pair,
                                             int n)
    {
        arr[0] = (pair[0] + pair[1] - pair[n - 1]) / 2;
        for (int i = 1; i < n; i++)
            arr[i] = pair[i - 1] - arr[0];
    }

/*    Driver program to test above function*/

    public static void Main()
    {
        int []pair = {15, 13, 11, 10, 12,
                         10, 9, 8, 7, 5};
        int n = 5;
        int []arr = new int[n];
        constructArr(arr, pair, n);
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");    
    }
}

/*C# program program to merge two
sorted arrays with O(1) extra space.*/

using System;

/*Merge ar1[] and ar2[] with O(1) extra space*/

public class Test
{
    static int []arr1 = new int[]{1, 5, 9, 10, 15, 20};
    static int []arr2 = new int[]{2, 3, 8, 13};
    static void merge(int m, int n)
    {

/*        Iterate through all elements of ar2[] starting from
        the last element*/

        for (int i=n-1; i>=0; i--)
        {

/* Find the smallest element greater than ar2[i]. Move all
            elements one position ahead till the smallest greater
            element is not found */

            int j, last = arr1[m-1];
            for (j=m-2; j >= 0 && arr1[j] > arr2[i]; j--)
                arr1[j+1] = arr1[j];

/*            If there was a greater element*/

            if (j != m-2 || last > arr2[i])
            {
                arr1[j+1] = arr2[i];
                arr2[i] = last;
            }
        }
    }

/*    Driver method to test the above function*/

    public static void Main()
    {
        merge(arr1.Length,arr2.Length);
        Console.Write("After Merging \nFirst Array: ");
        for(int i =0; i< arr1.Length;i++){
            Console.Write(arr1[i]+" ");
        }
        Console.Write("\nSecond Array: ");
        for(int i =0; i< arr2.Length;i++){
