/*C# program to implement binary
search in a sorted array*/

using System;
public class GFG {

/*    function to implement
    binary search*/

    public static int binarySearch(int[] arr, int low,
                                   int high, int key)
    {
        if (high < low) {
            return -1;
        }

/*low + (high - low)/2;*/

        int mid = (low + high) / 2;
        if (key == arr[mid]) {
            return mid;
        }
        if (key > arr[mid]) {
            return binarySearch(arr, (mid + 1), high, key);
        }
        return binarySearch(arr, low, (mid - 1), key);
    }

/* Driver Code */

    public static void Main(string[] args)
    {
        int[] arr = new int[] { 5, 6, 7, 8, 9, 10 };
        int n, key;
        n = arr.Length;
        key = 10;
        Console.WriteLine("Index: "
                          + binarySearch(arr, 0, n-1, key));
    }
}

/*C# program to insert an
element in a sorted array*/

using System;
public class GFG {

/*    Inserts a key in arr[] of given
    capacity.  n is current size of arr[].
    This function returns n+1 if insertion
    is successful, else n.*/

    public static int insertSorted(int[] arr, int n, int key, int capacity)
    {

/*        Cannot insert more elements if n is already
        more than or equal to capcity*/

        if (n >= capacity) {
            return n;
        }
        int i;
        for (i = n - 1; (i >= 0 && arr[i] > key); i--) {
            arr[i + 1] = arr[i];
        }
        arr[i + 1] = key;
        return (n + 1);
    }

/* Driver program to test above function */

    public static void Main(string[] args)
    {
        int[] arr = new int[20];
        arr[0] = 12;
        arr[1] = 16;
        arr[2] = 20;
        arr[3] = 40;
        arr[4] = 50;
        arr[5] = 70;
        int capacity = arr.Length;
        int n = 6;
        int key = 26;
        Console.Write("\nBefore Insertion: ");
        for (int i = 0; i < n; i++) {
            Console.Write(arr[i] + " ");
        }

/*        Inserting key*/

        n = insertSorted(arr, n, key, capacity);
        Console.Write("\nAfter Insertion: ");
        for (int i = 0; i < n; i++) {
            Console.Write(arr[i] + " ");
        }
    }
}

/*C# program to delete an
element from a sorted array*/

using System;
public class GFG {

/*    binary search*/

    static int binarySearch(int[] arr, int low, int high, int key)
    {
        if (high < low)
            return -1;
        int mid = (low + high) / 2;
        if (key == arr[mid])
            return mid;
        if (key > arr[mid])
            return binarySearch(arr, (mid + 1), high, key);
        return binarySearch(arr, low, (mid - 1), key);
    }

/* Function to delete an element */

    static int deleteElement(int[] arr, int n, int key)
    {

/*        Find position of element to be deleted*/

        int pos = binarySearch(arr, 0, n - 1, key);
        if (pos == -1) {
            Console.WriteLine("Element not found");
            return n;
        }

/*        Deleting element*/

        int i;
        for (i = pos; i < n - 1; i++)
            arr[i] = arr[i + 1];
        return n - 1;
    }

/* Driver Code */

    public static void Main()
    {
        int i;
        int[] arr = { 10, 20, 30, 40, 50 };
        int n = arr.Length;
        int key = 30;
        Console.Write("Array before deletion:\n");
        for (i = 0; i < n; i++)
