        findMaxSubarraySum(A, B, n, m);
    }
}

/*C# Program implementation of the
above idea*/

using System;
using System.Collections.Generic;
class GFG {

/*  Function to calculate the max sum of contigous
  subarray of B whose elements are not present in A*/

  static int findMaxSubarraySum(int[] A, int[] B)
  {
    Dictionary<int, int> m = new Dictionary<int, int>();

/*    mark all the elements present in B*/

    for(int i = 0; i < B.Length; i++)
    {
      m[B[i]] = 1;
    }

/*    initialize max_so_far with INT_MIN*/

    int max_so_far = Int32.MinValue;
    int currmax = 0;

/*    traverse the array A*/

    for(int i = 0; i < A.Length; i++)
    {
      if(currmax<0 || (m.ContainsKey(A[i]) && m[A[i]] == 1))
      {
        currmax = 0;
        continue;
      }
      currmax = Math.Max(A[i],A[i]+currmax);

/*      if current max is greater than
      max so far then update max so far*/

      if(max_so_far<currmax)
      {
        max_so_far = currmax;
      }
    }
    return max_so_far;
  }

/*  Driver code.*/

  static void Main() {
    int[] a = { 3, 4, 5, -4, 6 };
    int[] b = { 1, 8, 5 };

/*    Function call*/

    Console.WriteLine(findMaxSubarraySum(a,b));
  }
}

/*C# program to find maximum
equilibrium sum.*/

using System;
class GFG {

/*    Function to find maximum
    equilibrium sum.*/

    static int findMaxSum(int []arr, int n)
    {
        int res = int.MinValue;
        for (int i = 0; i < n; i++)
        {
            int prefix_sum = arr[i];
            for (int j = 0; j < i; j++)
                prefix_sum += arr[j];
            int suffix_sum = arr[i];
            for (int j = n - 1; j > i; j--)
                suffix_sum += arr[j];
            if (prefix_sum == suffix_sum)
                res = Math.Max(res, prefix_sum);
        }
        return res;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int []arr = {-2, 5, 3, 1, 2, 6, -4, 2 };
        int n = arr.Length;
        Console.WriteLine(findMaxSum(arr, n));
    }
}

/*C# program to find maximum equilibrium sum.*/

using System;
public class GFG {

/*    Function to find maximum
    equilibrium sum.*/

    static int findMaxSum(int []arr, int n)
    {

/*        Array to store prefix sum.*/

        int []preSum = new int[n];

/*        Array to store suffix sum.*/

        int []suffSum = new int[n];

/*        Variable to store maximum sum.*/

        int ans = int.MinValue;

/*        Calculate prefix sum.*/

        preSum[0] = arr[0];
        for (int i = 1; i < n; i++)
            preSum[i] = preSum[i - 1] + arr[i];

/*        Calculate suffix sum and compare
        it with prefix sum. Update ans
        accordingly.*/

        suffSum[n - 1] = arr[n - 1];
        if (preSum[n - 1] == suffSum[n - 1])
            ans = Math.Max(ans, preSum[n - 1]);
        for (int i = n - 2; i >= 0; i--)
        {
            suffSum[i] = suffSum[i + 1] + arr[i];
            if (suffSum[i] == preSum[i])
                ans = Math.Max(ans, preSum[i]);
        }
        return ans;
    }

/*    Driver Code*/

    static public void Main ()
    {
        int []arr = { -2, 5, 3, 1, 2, 6, -4, 2 };
        int n = arr.Length;
        Console.WriteLine( findMaxSum(arr, n));
    }
}

/*C# program to find maximum equilibrium sum.*/

using System.Linq;
using System;
class GFG {
    static int Add(int x, int y) {
        return x + y;
    }

/*    Function to find maximum equilibrium
    sum.*/

    static int findMaxSum(int []arr, int n)
    {
        int sum = arr.Aggregate(func:Add);
        int prefix_sum = 0,
        res = int.MinValue;
        for (int i = 0; i < n; i++)
        {
            prefix_sum += arr[i];
            if (prefix_sum == sum)
                res = Math.Max(res, prefix_sum);
            sum -= arr[i];
        }
        return res;
    }

/*    Driver Code*/

    public static void Main()
    {
        int []arr = { -2, 5, 3, 1,
                    2, 6, -4, 2 };
        int n = arr.Length;
        Console.Write(findMaxSum(arr, n));
    }
}

/*C# program to find equilibrium
index of an array*/

using System;
class GFG {

/*function to find the equilibrium index*/

    static int equilibrium(int[] arr, int n)
    {
        int i, j;
        int leftsum, rightsum;

/* Check for indexes one by
         one until an equilibrium
        index is found */

        for (i = 0; i < n; ++i) {
            leftsum = 0;
            rightsum = 0;

/* get left sum */

            for (j = 0; j < i; j++)
                leftsum += arr[j];

/* get right sum */

            for (j = i + 1; j < n; j++)
                rightsum += arr[j];

/* if leftsum and rightsum are
             same, then we are done */

            if (leftsum == rightsum)
                return i;
        }

/* return -1 if no equilibrium
         index is found */

        return -1;
    }

/*    driver code*/

    public static void Main()
    {
        int[] arr = { -7, 1, 5, 2, -4, 3, 0 };
        int arr_size = arr.Length;
        Console.Write(equilibrium(arr, arr_size));
    }
}

/*C# program to find the equilibrium
index of an array*/

using System;
class GFG {

/* function to find the equilibrium index*/

static int equilibrium(int[] arr, int n)
    {

/*        initialize sum of whole array*/

        int sum = 0;

/*        initialize leftsum*/

        int leftsum = 0;

/* Find sum of the whole array */

        for (int i = 0; i < n; ++i)
            sum += arr[i];
        for (int i = 0; i < n; ++i) {

/*            sum is now right sum
            for index i*/

            sum -= arr[i];
            if (leftsum == sum)
                return i;
            leftsum += arr[i];
        }

/* If no equilibrium index found,
        then return 0 */

        return -1;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { -7, 1, 5, 2, -4, 3, 0 };
        int arr_size = arr.Length;
        Console.Write("First equilibrium index is " +
                        equilibrium(arr, arr_size));
    }
}

/*C# program to find equilibrium
index of an array*/

using System;
class GFG{
static int equilibrium(int[] a, int n)
{
    if (n == 1)
        return (0);
    int[] front = new int[n];
    int[] back = new int[n];

/*    Taking the prefixsum from front end array*/

    for(int i = 0; i < n; i++)
    {
        if (i != 0)
        {
            front[i] = front[i - 1] + a[i];
        }
        else
        {
            front[i] = a[i];
        }
    }

/*    Taking the prefixsum from back end of array*/

    for(int i = n - 1; i > 0; i--)
    {
        if (i <= n - 2)
        {
            back[i] = back[i + 1] + a[i];
        }
        else
        {
            back[i] = a[i];
        }
    }

/*    Checking for equilibrium index by
    compairing front and back sums*/

    for(int i = 0; i < n; i++)
    {
        if (front[i] == back[i])
        {
            return i;
        }
    }

/*    If no equilibrium index found,then return -1*/

    return -1;
}

/*Driver code*/

public static void Main(string[] args)
{
    int[] arr = { -7, 1, 5, 2, -4, 3, 0 };
    int arr_size = arr.Length;
    Console.WriteLine("First Point of equilibrium " +
                      "is at index " +
                      equilibrium(arr, arr_size));
}
}

