    }

}

/*C# program to demonstrate insert
operation in binary search tree.*/

using System;
public class Node
{
    public int key;
    public int c = 0;
    public Node left,right;
}
class GFG{
static int ma = 0;

/*A utility function to create a
new BST node*/

static Node newNode(int item)
{
    Node temp = new Node();
    temp.key = item;
    temp.c = 1;
    temp.left = temp.right = null;
    return temp;
}

/*A utility function to insert a new node
with given key in BST*/

static Node insert(Node node, int key)
{

/*    If the tree is empty,
    return a new node*/

    if (node == null)
    {
        if (ma == 0)
            ma = 1;
        return newNode(key);
    }

/*    Otherwise, recur down the tree*/

    if (key < node.key)
        node.left = insert(node.left, key);
    else if (key > node.key)
        node.right = insert(node.right, key);
    else
        node.c++;

/*    Find the max count*/

    ma = Math.Max(ma, node.c);

/*    Return the (unchanged) node pointer*/

    return node;
}

/*A utility function to do inorder
traversal of BST*/

static void inorder(Node root, int s)
{
    if (root != null)
    {
        inorder(root.left, s);
        if (root.c > (s / 2))
            Console.WriteLine(root.key + "\n");
        inorder(root.right, s);
    }
}

/*Driver Code*/

static public void Main()
{
    int[] a = { 1, 3, 3, 3, 2 };
    int size = a.Length;
    Node root = null;
    for(int i = 0; i < size; i++)
    {
        root = insert(root, a[i]);
    }

/*    Function call*/

    if (ma > (size / 2))
        inorder(root, size);
    else
        Console.WriteLine("No majority element\n");
}
}

/*C# Program for finding out majority element in an array*/

using System;
class GFG {

/* Function to find the candidate for Majority */

    static int findCandidate(int[] a, int size)
    {
        int maj_index = 0, count = 1;
        int i;
        for (i = 1; i < size; i++) {
            if (a[maj_index] == a[i])
                count++;
            else
                count--;
            if (count == 0) {
                maj_index = i;
                count = 1;
            }
        }
        return a[maj_index];
    }

/*    Function to check if the candidate
    occurs more than n/2 times*/

    static bool isMajority(int[] a, int size, int cand)
    {
        int i, count = 0;
        for (i = 0; i < size; i++) {
            if (a[i] == cand)
                count++;
        }
        if (count > size / 2)
            return true;
        else
            return false;
    }

/* Function to print Majority Element */

    static void printMajority(int[] a, int size)
    {

/* Find the candidate for Majority*/

        int cand = findCandidate(a, size);

/* Print the candidate if it is Majority*/

        if (isMajority(a, size, cand))
            Console.Write(" " + cand + " ");
        else
            Console.Write("No Majority Element");
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] a = { 1, 3, 3, 1, 2 };
        int size = a.Length;

/*        Function call*/

        printMajority(a, size);
    }
}

