/*Hashing based C# program
to find if there is a
majority element in input array.*/

using System;
using System.Collections.Generic;
class GFG
{

/*    Returns true if there is a
    majority element in a[]*/

    static Boolean isMajority(int []a, int n)
    {

/*        Insert all elements
        in a hash table*/

        Dictionary<int,
                   int> mp = new Dictionary<int,
                                            int>();
        for (int i = 0; i < n; i++)
        {
            if(mp.ContainsKey(a[i]))
            {
                var val = mp[a[i]];
                mp.Remove(a[i]);
                mp.Add(a[i], val + 1);
            }
            else
            {
                mp.Add(a[i], 1);
            }
        }

/*        Check if frequency of any
        element is n/2 or more.*/

        foreach(KeyValuePair<int, int> x in mp)
            if (x.Value >= n / 2)
                return true;
        return false;
    }

/*    Driver code*/

    public static void Main (String[] args)
    {
        int []a = { 2, 3, 9, 2, 2 };
        int n = a.Length;
        if (isMajority(a, n))
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*A C# program to find a peak element*/

using System;
public class GFG{

/*Find the peak element in the array*/

static int findPeak(int []arr, int n)
{

/*    First or last element is peak element*/

    if (n == 1)
      return 0;
    if (arr[0] >= arr[1])
        return 0;
    if (arr[n - 1] >= arr[n - 2])
        return n - 1;

/*    Check for every other element*/

    for(int i = 1; i < n - 1; i++)
    {

/*        Check if the neighbors are smaller*/

        if (arr[i] >= arr[i - 1] &&
            arr[i] >= arr[i + 1])
            return i;
    }
    return 0;
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []arr = { 1, 3, 20, 4, 1, 0 };
    int n = arr.Length;
    Console.Write("Index of a peak point is " +
                     findPeak(arr, n));
}
}

/*A C# program to find
a peak element element
using divide and conquer*/

using System;
class GFG {

/*    A binary search based
    function that returns
    index of a peak element*/

    static int findPeakUtil(int[] arr, int low,
                            int high, int n)
    {

/*        Find index of
        middle element*/

        int mid = low + (high - low) / 2;

/*        Compare middle element with
        its neighbours (if neighbours
        exist)*/

        if ((mid == 0 || arr[mid - 1] <= arr[mid]) && (mid == n - 1 || arr[mid + 1] <= arr[mid]))
            return mid;

/*        If middle element is not
        peak and its left neighbor
        is greater than it, then
        left half must have a
        peak element*/

        else if (mid > 0 && arr[mid - 1] > arr[mid])
            return findPeakUtil(arr, low,
                                (mid - 1), n);

/*        If middle element is not
        peak and its right neighbor
        is greater than it, then
        right half must have a peak
        element*/

        else
            return findPeakUtil(arr, (mid + 1),
                                high, n);
    }

/*    A wrapper over recursive
    function findPeakUtil()*/

    static int findPeak(int[] arr,
                        int n)
    {
        return findPeakUtil(arr, 0,
                            n - 1, n);
    }

/*    Driver Code*/

    static public void Main()
    {
        int[] arr = { 1, 3, 20,
                      4, 1, 0 };
        int n = arr.Length;
        Console.WriteLine("Index of a peak "
                          + "point is " + findPeak(arr, n));
    }
}

