using System;
class GFG
{

/* printRepeating function */

    static void printRepeating(int []arr, int size)
    {

/* S is for sum of elements in arr[] */

        int S = 0;

/* P is for product of elements in arr[] */

        int P = 1;

/* x and y are two repeating elements */

        int x, y;

/* D is for difference of x and y, i.e., x-y*/

        int D;
        int n = size - 2, i;

/* Calculate Sum and Product
         of all elements in arr[] */

        for (i = 0; i < size; i++)
        {
            S = S + arr[i];
            P = P * arr[i];
        }

/* S is x + y now */

        S = S - n * (n + 1) / 2;

/* P is x*y now */

        P = P / fact(n);

/* D is x - y now */

        D = (int) Math.Sqrt(S * S - 4 * P);
        x = (D + S) / 2;
        y = (S - D) / 2;
        Console.WriteLine("The two" +
                " repeating elements are :");
        Console.Write(x + " " + y);
    }

/*factorial of n*/

    static int fact(int n)
    {
        return (n == 0) ? 1 : n * fact(n - 1);
    }

/*    driver code*/

    public static void Main() {
        int []arr = {4, 2, 4, 5, 2, 3, 1};
        int arr_size = arr.Length;
        printRepeating(arr, arr_size);
    }
}

/*C# code to Find the
two repeating elements
in a given array*/

using System;
class GFG
{
    static void printRepeating(int []arr, int size)
    {

/* Will hold xor of all elements */

        int xor = arr[0];

/* Will have only single set bit of xor */

        int set_bit_no;
        int i;
        int n = size - 2;
        int x = 0, y = 0;

/* Get the xor of all elements
         in arr[] and {1, 2 .. n} */

        for (i = 1; i < size; i++)
            xor ^= arr[i];
        for (i = 1; i <= n; i++)
            xor ^= i;

/* Get the rightmost set bit in set_bit_no */

        set_bit_no = (xor & ~(xor - 1));

/* Now divide elements in two sets by
         comparing rightmost set bit of xor with bit
         at same position in each element. */

        for (i = 0; i < size; i++) {
            int a = arr[i] & set_bit_no;
            if (a != 0)
                x = x ^ arr[i];

/* XOR of first set in arr[] */


            else
                y = y ^ arr[i];
        }

/* XOR of second set in arr[] */


        for (i = 1; i <= n; i++)
        {
            int a = i & set_bit_no;
            if (a != 0)
                x = x ^ i;

/* XOR of first set in
                 arr[] and {1, 2, ...n }*/


            else
                y = y ^ i;
        }

/* XOR of second set in
                 arr[] and {1, 2, ...n } */


        Console.WriteLine("The two" +
            " reppeated elements are :");
        Console.Write(x + " " + y);
    }

/* Driver program to test the above function */

    public static void Main()
    {
        int []arr = {4, 2, 4, 5, 2, 3, 1};
        int arr_size = arr.Length;
        printRepeating(arr, arr_size);
    }
}

