in an array using linear search*/

using System;
class GFG
{
    static int linearSearch(int []arr, int n)
    {
        int i;
        for(i = 0; i < n; i++)
        {
            if(arr[i] == i)
                return i;
        }

/* If no fixed point present
        then return -1 */

        return -1;
    }

/*    Driver code*/

