/*C# program to check fixed point
in an array using binary search*/

using System;
class GFG
{
    static int binarySearch(int []arr, int low, int high)
    {
        if(high >= low)
        {

/*            low + (high - low)/2;*/

            int mid = (low + high)/2;
            if(mid == arr[mid])
                return mid;
            if(mid > arr[mid])
                return binarySearch(arr, (mid + 1), high);
            else
                return binarySearch(arr, low, (mid -1));
        }

/* Return -1 if there is
        no Fixed Point */

        return -1;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = {-10, -1, 0, 3 , 10, 11, 30, 50, 100};
        int n = arr.Length;
        Console.Write("Fixed Point is "+ binarySearch(arr,0, n-1));    
    }
}

/*C# code to Find subarray
with given sum*/

using System;
class GFG {

/*    Returns true if the there is a
    subarray of arr[] with sum
    equal to 'sum' otherwise returns
    false. Also, prints the result*/

    int subArraySum(int[] arr, int n,
                    int sum)
    {
        int curr_sum, i, j;

/*        Pick a starting point*/

        for (i = 0; i < n; i++) {
            curr_sum = arr[i];

/*            try all subarrays
            starting with 'i'*/

            for (j = i + 1; j <= n; j++) {
                if (curr_sum == sum) {
                    int p = j - 1;
                    Console.Write("Sum found between "
                                  + "indexes " + i + " and " + p);
                    return 1;
                }
                if (curr_sum > sum || j == n)
                    break;
                curr_sum = curr_sum + arr[j];
            }
        }
        Console.Write("No subarray found");
        return 0;
    }

/*    Driver Code*/

    public static void Main()
    {
        GFG arraysum = new GFG();
        int[] arr = { 15, 2, 4, 8, 9, 5, 10, 23 };
        int n = arr.Length;
        int sum = 23;
        arraysum.subArraySum(arr, n, sum);
    }
}

/*An efficient C# program to print
subarray with sum as given sum*/

using System;
class GFG {

/*    Returns true if the
    there is a subarray of
    arr[] with sum equal to
    'sum' otherwise returns false.
    Also, prints the result*/

    int subArraySum(int[] arr, int n,
                    int sum)
    {

/* Initialize curr_sum as
    value of first element
    and starting point as 0 */

        int curr_sum = arr[0],
            start = 0, i;

/*        Pick a starting point*/

        for (i = 1; i <= n; i++) {

/*            If curr_sum exceeds
            the sum, then remove
            the starting elements*/

            while (curr_sum > sum && start < i - 1) {
                curr_sum = curr_sum - arr[start];
                start++;
            }

/*            If curr_sum becomes equal to
            sum, then return true*/

            if (curr_sum == sum) {
                int p = i - 1;
                Console.WriteLine("Sum found between "
                                  + "indexes " + start + " and " + p);
                return 1;
            }

/*            Add this element to curr_sum*/

            if (i < n)
                curr_sum = curr_sum + arr[i];
        }

/*    If we reach here, then no subarray*/

        Console.WriteLine("No subarray found");
        return 0;
    }

/*    Driver code*/

    public static void Main()
    {
        GFG arraysum = new GFG();
        int[] arr = new int[] { 15, 2, 4, 8,
                                9, 5, 10, 23 };
        int n = arr.Length;
        int sum = 23;
        arraysum.subArraySum(arr, n, sum);
    }
}

