/*C# code to find maximum triplet sum*/

using System;
class GFG {

/*    This function assumes that there
    are at least three elements in arr[].*/

    static int maxTripletSum(int[] arr, int n)
    {

/*        Initialize Maximum, second maximum
        and third maximum element*/

        int maxA = -100000000, maxB = -100000000;
        int maxC = -100000000;
        for (int i = 0; i < n; i++) {

/*            Update Maximum, second maximum
            and third maximum element*/

            if (arr[i] > maxA) {
                maxC = maxB;
                maxB = maxA;
                maxA = arr[i];
            }

/*            Update second maximum and third
            maximum element*/

            else if (arr[i] > maxB) {
                maxC = maxB;
                maxB = arr[i];
            }

/*            Update third maximum element*/

            else if (arr[i] > maxC)
                maxC = arr[i];
        }
        return (maxA + maxB + maxC);
    }

/*    Driven code*/

    public static void Main()
    {
        int[] arr = { 1, 0, 8, 6, 4, 2 };
        int n = arr.Length;
        Console.WriteLine(maxTripletSum(arr, n));
    }
}

/*C# implementation of smallest
difference triplet*/

using System;
class GFG
{

/*    function to find
    maximum number*/

    static int maximum(int a, int b, int c)
    {
        return Math.Max(Math.Max(a, b), c);
    }

/*    function to find
    minimum number*/

    static int minimum(int a, int b, int c)
    {
        return Math.Min(Math.Min(a, b), c);
    }

/*    Finds and prints the
    smallest Difference Triplet*/

    static void smallestDifferenceTriplet(int []arr1,
                                          int []arr2,
                                          int []arr3,
                                          int n)
    {

/*        sorting all the
        three arrays*/

        Array.Sort(arr1);
        Array.Sort(arr2);
        Array.Sort(arr3);

/*        To store resultant
        three numbers*/

        int res_min = 0, res_max = 0, res_mid = 0;

/*        pointers to arr1, arr2,
        arr3 respectively*/

        int i = 0, j = 0, k = 0;

/*        Loop until one array
        reaches to its end
        Find the smallest difference.*/

        int diff = 2147483647;
        while (i < n && j < n && k < n)
        {
            int sum = arr1[i] +
                      arr2[j] + arr3[k];

/*            maximum number*/

            int max = maximum(arr1[i],
                              arr2[j], arr3[k]);

/*            Find minimum and
            increment its index.*/

            int min = minimum(arr1[i],
                              arr2[j], arr3[k]);
            if (min == arr1[i])
                i++;
            else if (min == arr2[j])
                j++;
            else
                k++;

/*            comparing new difference
            with the previous one and
            updating accordingly*/

            if (diff > (max - min))
            {
                diff = max - min;
                res_max = max;
                res_mid = sum - (max + min);
                res_min = min;
            }
        }

/*        Print result*/

        Console.WriteLine(res_max + ", " +
                          res_mid + ", " +
                          res_min);
    }

/*    Driver code*/

    static public void Main ()
    {
        int []arr1 = {5, 2, 8};
        int []arr2 = {10, 7, 12};
        int []arr3 = {9, 14, 6};
        int n = arr1.Length;
        smallestDifferenceTriplet(arr1, arr2,
                                  arr3, n);
    }
}

/*C# program to find a triplet
that sum to a given value*/

using System;
class GFG {

/*    returns true if there is
    triplet with sum equal
    to 'sum' present in A[].
    Also, prints the triplet*/

    static bool find3Numbers(int[] A,
                             int arr_size,
                             int sum)
    {

/*        Fix the first
        element as A[i]*/

        for (int i = 0;
             i < arr_size - 2; i++) {

/*            Fix the second
            element as A[j]*/

            for (int j = i + 1;
                 j < arr_size - 1; j++) {

/*                Now look for
                the third number*/

                for (int k = j + 1;
                     k < arr_size; k++) {
                    if (A[i] + A[j] + A[k] == sum) {
                        Console.WriteLine("Triplet is " + A[i] + ", " + A[j] + ", " + A[k]);
                        return true;
                    }
                }
            }
        }

/*        If we reach here,
        then no triplet was found*/

        return false;
    }

/*    Driver Code*/

    static public void Main()
    {
        int[] A = { 1, 4, 45, 6, 10, 8 };
        int sum = 22;
        int arr_size = A.Length;
        find3Numbers(A, arr_size, sum);
    }
}

/*C# program to find a triplet using Hashing*/

using System;
using System.Collections.Generic;
public class GFG {

/*    returns true if there is triplet
    with sum equal to 'sum' present
    in A[]. Also, prints the triplet*/

    static bool find3Numbers(int[] A,
                             int arr_size, int sum)
    {

/*        Fix the first element as A[i]*/

        for (int i = 0; i < arr_size - 2; i++) {

/*            Find pair in subarray A[i+1..n-1]
            with sum equal to sum - A[i]*/

            HashSet<int> s = new HashSet<int>();
            int curr_sum = sum - A[i];
            for (int j = i + 1; j < arr_size; j++) 
            {
                if (s.Contains(curr_sum - A[j])) 
                {
                    Console.Write("Triplet is {0}, {1}, {2}", A[i],
                                  A[j], curr_sum - A[j]);
                    return true;
                }
                s.Add(A[j]);
            }
        }

/*        If we reach here, then no triplet was found*/

        return false;
    }

/* Driver code */

    public static void Main()
    {
        int[] A = { 1, 4, 45, 6, 10, 8 };
        int sum = 22;
        int arr_size = A.Length;
        find3Numbers(A, arr_size, sum);
    }
}

/*C# implementation to
sort the given matrix*/

using System;
class GFG {
    static int SIZE = 10;

/*    function to sort the given matrix*/

    static void sortMat(int[, ] mat, int n)
    {

/*        temporary matrix of size n^2*/

        int[] temp = new int[n * n];
        int k = 0;

/*        copy the elements of matrix
        one by one into temp[]*/

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                temp[k++] = mat[i, j];

/*        sort temp[]*/

        Array.Sort(temp);

/*        copy the elements of temp[]
        one by one in mat[][]*/

        k = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
            mat[i, j] = temp[k++];
    }

/*    function to print the given matrix*/

    static void printMat(int[, ] mat, int n)
    {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++)
            Console.Write(mat[i, j] + " ");
            Console.WriteLine();
        }
    }

/*    Driver code*/

    public static void Main()
    {
        int[, ] mat = { { 5, 4, 7 },
                        { 1, 3, 8 },
                        { 2, 9, 6 } };
        int n = 3;
        Console.WriteLine("Original Matrix:");
        printMat(mat, n);
        sortMat(mat, n);
        Console.WriteLine("Matrix After Sorting:");
        printMat(mat, n);
    }
}

