/*C# code to generate all possible subsequences.
Time Complexity O(n * 2^n)*/

using System;
class GFG{
static void printSubsequences(int[] arr, int n)
{

/*    Number of subsequences is (2**n -1)*/

    int opsize = (int)Math.Pow(2, n);

/*    Run from counter 000..1 to 111..1*/

    for(int counter = 1; counter < opsize; counter++)
    {
        for(int j = 0; j < n; j++)
        {

/*            Check if jth bit in the counter is set
            If set then print jth element from arr[]*/

            if ((counter & (1 << j)) != 0)
                Console.Write(arr[j] + " ");
        }
        Console.WriteLine();
    }
}

/*Driver Code*/

static void Main()
{
    int[] arr = { 1, 2, 3, 4 };
    int n = arr.Length;
    Console.WriteLine("All Non-empty Subsequences");
    printSubsequences(arr, n);
}
}

using System;
class GFG {

/* Function to print product array
for a given array arr[] of size n */

    static void productArray(int[] arr, int n)
    {

/*        Base case*/

        if (n == 1) {
            Console.Write(0);
            return;
        }
        int i, temp = 1;

/* Allocate memory for the product
        array */

        int[] prod = new int[n];

/* Initialize the product array as 1 */

        for (int j = 0; j < n; j++)
            prod[j] = 1;

/* In this loop, temp variable contains
        product of elements on left side
        excluding arr[i] */

        for (i = 0; i < n; i++) {
            prod[i] = temp;
            temp *= arr[i];
        }

/* Initialize temp to 1 for product on
        right side */

        temp = 1;

/* In this loop, temp variable contains
        product of elements on right side
        excluding arr[i] */

        for (i = n - 1; i >= 0; i--) {
            prod[i] *= temp;
            temp *= arr[i];
        }

/* print the constructed prod array */

        for (i = 0; i < n; i++)
            Console.Write(prod[i] + " ");
        return;
    }

/* Driver program to test above functions */

    public static void Main()
    {
        int[] arr = { 10, 3, 5, 6, 2 };
        int n = arr.Length;
        Console.WriteLine("The product array is : ");
        productArray(arr, n);
    }
}

using System;
class GFG {

/* The function checks if the array elements
    are consecutive If elements are consecutive,
    then returns true, else returns    false */

    static bool areConsecutive(int []arr, int n)
    {
        if (n < 1)
            return false;

/* 1) Get the minimum element in array */

        int min = getMin(arr, n);

/* 2) Get the maximum element in array */

        int max = getMax(arr, n);

/* 3) max - min + 1 is equal to n, then
        only check all elements */

        if (max - min + 1 == n)
        {

/* Create a temp array to hold visited
            flag of all elements. Note that, calloc
            is used here so that all values are
            initialized as false */

            bool []visited = new bool[n];
            int i;
            for (i = 0; i < n; i++)
            {

/* If we see an element again, then
                return false */

                if (visited[arr[i] - min] != false)
                    return false;

/* If visited first time, then mark
                the element as visited */

                visited[arr[i] - min] = true;
            }

/* If all elements occur once, then
            return true */

            return true;
        }

/*if (max - min + 1 != n)*/

return false; 
    }

/* UTILITY FUNCTIONS */

    static int getMin(int []arr, int n)
    {
        int min = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] < min)
                min = arr[i];
        }
        return min;
    }
    static int getMax(int []arr, int n)
    {
        int max = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] > max)
                max = arr[i];
        }
        return max;
    }

/* Driver program to test above functions */

    public static void Main()
    {
        int []arr = {5, 4, 2, 3, 1, 6};
        int n = arr.Length;
        if (areConsecutive(arr, n) == true)
            Console.Write("Array elements are"
                              + " consecutive");
        else
            Console.Write("Array elements are"
                         + " not consecutive");
    }
}

using System;
class GFG {

/* The function checks if the array
    elements are consecutive If elements
    are consecutive, then returns true,
    else returns false */

    static bool areConsecutive(int []arr, int n)
    {
        if (n < 1)
            return false;

/* 1) Get the minimum element in
        array */

        int min = getMin(arr, n);

/* 2) Get the maximum element in
        array */

        int max = getMax(arr, n);

/* 3) max-min+1 is equal to n then
        only check all elements */

        if (max - min + 1 == n)
        {
            int i;
            for (i = 0; i < n; i++)
            {
                int j;
                if (arr[i] < 0)
                    j = -arr[i] - min;
                else
                    j = arr[i] - min;

/*                if the value at index j
                is negative then
                there is repitition*/

                if (arr[j] > 0)
                    arr[j] = -arr[j];
                else
                    return false;
            }

/* If we do not see a negative
            value then all elements
            are distinct */

            return true;
        }

/*        if (max-min+1 != n)*/

        return false;
    }

/* UTILITY FUNCTIONS */

    static int getMin(int []arr, int n)
    {
        int min = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] < min)
                min = arr[i];
        }
        return min;
    }
    static int getMax(int []arr, int n)
    {
        int max = arr[0];
        for (int i = 1; i < n; i++)
        {
            if (arr[i] > max)
                max = arr[i];
        }
        return max;
    }

/* Driver program to test above
    functions */

    public static void Main()
    {
        int []arr = {5, 4, 2, 3, 1, 6};
        int n = arr.Length;
