}

/*C# program for Finite Automata Pattern 
searching Algorithm */

using System;
class GFG
{
public static int NO_OF_CHARS = 256;
public static int getNextState(char[] pat, int M, 
                               int state, int x)
{

/*    If the character c is same as next 
    character in pattern,then simply 
    increment state */

    if (state < M && (char)x == pat[state])
    {
        return state + 1;
    }

/*    ns stores the result 
    which is next state */

    int ns, i;

/*    ns finally contains the longest 
    prefix which is also suffix in 
    "pat[0..state-1]c" 
    Start from the largest possible  
    value and stop when you find a 
    prefix which is also suffix */

    for (ns = state; ns > 0; ns--)
    {
        if (pat[ns - 1] == (char)x)
        {
            for (i = 0; i < ns - 1; i++)
            {
                if (pat[i] != pat[state - ns + 1 + i])
                {
                    break;
                }
            }
                if (i == ns - 1)
                {
                    return ns;
                }
        }
    }
        return 0;
}

/* This function builds the TF table which 
represents Finite Automata for a given pattern */

public static void computeTF(char[] pat, 
                             int M, int[][] TF)
{
    int state, x;
    for (state = 0; state <= M; ++state)
    {
        for (x = 0; x < NO_OF_CHARS; ++x)
        {
            TF[state][x] = getNextState(pat, M, 
                                        state, x);
        }
    }
}

/* Prints all occurrences of 
   pat in txt */

public static void search(char[] pat, 
                          char[] txt)
{
    int M = pat.Length;
    int N = txt.Length;
    int[][] TF = RectangularArrays.ReturnRectangularIntArray(M + 1, 
                                                      NO_OF_CHARS);
    computeTF(pat, M, TF);

/*    Process txt over FA. */

    int i, state = 0;
    for (i = 0; i < N; i++)
    {
        state = TF[state][txt[i]];
        if (state == M)
        {
            Console.WriteLine("Pattern found " + 
                              "at index " + (i - M + 1));
        }
    }
}
public static class RectangularArrays
{
public static int[][] ReturnRectangularIntArray(int size1, 
                                                int size2)
{
    int[][] newArray = new int[size1][];
    for (int array1 = 0; array1 < size1; array1++)
    {
        newArray[array1] = new int[size2];
    }
    return newArray;
}
}

/*Driver code */

public static void Main(string[] args)
{
    char[] pat = "AABAACAADAABAAABAA".ToCharArray();
    char[] txt = "AABA".ToCharArray();
    search(txt,pat);
}
}

/* C# Program for Bad Character Heuristic of Boyer
Moore String Matching Algorithm */

using System;
public class AWQ{
    static int NO_OF_CHARS = 256;

/*    A utility function to get maximum of two integers*/

    static int max (int a, int b) { return (a > b)? a: b; }

/*    The preprocessing function for Boyer Moore's
    bad character heuristic*/

    static void badCharHeuristic( char []str, int size,int []badchar)
    {
    int i;

/*    Initialize all occurrences as -1*/

    for (i = 0; i < NO_OF_CHARS; i++)
        badchar[i] = -1;

/*    Fill the actual value of last occurrence
    of a character*/

    for (i = 0; i < size; i++)
        badchar[(int) str[i]] = i;
    }

/* A pattern searching function that uses Bad
    Character Heuristic of Boyer Moore Algorithm */

    static void search( char []txt, char []pat)
    {
    int m = pat.Length;
    int n = txt.Length;
    int []badchar = new int[NO_OF_CHARS];

/* Fill the bad character array by calling
        the preprocessing function badCharHeuristic()
        for given pattern */

    badCharHeuristic(pat, m, badchar);

/*s is shift of the pattern with respect to text*/

int s = 0;

/*there are n-m+1 potential allignments*/              

    while(s <= (n - m))
    {
        int j = m-1;

/* Keep reducing index j of pattern while
            characters of pattern and text are
            matching at this shift s */

        while(j >= 0 && pat[j] == txt[s+j])
            j--;

/* If the pattern is present at current
            shift, then index j will become -1 after
            the above loop */

        if (j < 0)
        {
            Console.WriteLine("Patterns occur at shift = " + s);

/* Shift the pattern so that the next
                character in text aligns with the last
                occurrence of it in pattern.
                The condition s+m < n is necessary for
                the case when pattern occurs at the end
                of text */

            s += (s+m < n)? m-badchar[txt[s+m]] : 1;
        }
        else

/* Shift the pattern so that the bad character
                in text aligns with the last occurrence of
                it in pattern. The max function is used to
                make sure that we get a positive shift.
                We may get a negative shift if the last
                occurrence of bad character in pattern
                is on the right side of the current
                character. */

            s += max(1, j - badchar[txt[s+j]]);
    }
    }

/* Driver program to test above function */

    public static void Main() {
        char []txt = "ABAAABCD".ToCharArray();
        char []pat = "ABC".ToCharArray();
        search(txt, pat);
    }
}

/*C# program to search all anagrams 
of a pattern in a text */

using System;
class GFG
{
public const int MAX = 256;

/*This function returns true if  
contents of arr1[] and arr2[] 
are same, otherwise false. */

public static bool compare(char[] arr1, 
                           char[] arr2)
{
    for (int i = 0; i < MAX; i++)
    {
        if (arr1[i] != arr2[i])
        {
            return false;
        }
    }
    return true;
}

/*This function search for all 
permutations of pat[] in txt[] */

public static void search(string pat, 
                          string txt)
{
    int M = pat.Length;
    int N = txt.Length;

/*    countP[]: Store count of all 
    characters of pattern 
    countTW[]: Store count of current 
    window of text */

    char[] countP = new char[MAX];
    char[] countTW = new char[MAX];
    for (int i = 0; i < M; i++)
    {
        (countP[pat[i]])++;
        (countTW[txt[i]])++;
    }

/*    Traverse through remaining 
    characters of pattern */

    for (int i = M; i < N; i++)
    {

/*        Compare counts of current window 
        of text with counts of pattern[] */

        if (compare(countP, countTW))
        {
            Console.WriteLine("Found at Index " + 
                             (i - M));
        }

/*        Add current character to 
        current window */

        (countTW[txt[i]])++;

/*        Remove the first character of
        previous window */

        countTW[txt[i - M]]--;
    }

/*    Check for the last window in text */

    if (compare(countP, countTW))
    {
        Console.WriteLine("Found at Index " + 
                         (N - M));
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    string txt = "BACDGABCDA";
    string pat = "ABCD";
    search(pat, txt);
}
}

/*C# program to implement Manacher's Algorithm*/

using System;
class GFG 
{
    static void findLongestPalindromicString(String text) 
    {
        int N = text.Length;
        if (N == 0)
            return;

/*Position count*/

N = 2 * N + 1;

/*LPS Length Array*/

int[] L = new int[N + 1]; 
        L[0] = 0;
        L[1] = 1;

/*centerPosition*/

int C = 1;

/*centerRightPosition*/

int R = 2;

/*currentRightPosition*/

int i = 0;

/*currentLeftPosition*/

int iMirror; 
        int maxLPSLength = 0;
        int maxLPSCenterPosition = 0;
        int start = -1;
        int end = -1;
        int diff = -1;

/*        Uncomment it to print LPS Length array
        printf("%d %d ", L[0], L[1]);*/

        for (i = 2; i < N; i++) 
        {

/*            get currentLeftPosition iMirror 
            for currentRightPosition i*/

            iMirror = 2 * C - i;
            L[i] = 0;
            diff = R - i;

/*            If currentRightPosition i is within 
            centerRightPosition R*/

            if (diff > 0)
                L[i] = Math.Min(L[iMirror], diff);

/*            Attempt to expand palindrome centered at 
            currentRightPosition i. Here for odd positions, 
            we compare characters and if match then 
            increment LPS Length by ONE. If even position, 
            we just increment LPS by ONE without 
            any character comparison*/

            while (((i + L[i]) + 1 < N && (i - L[i]) > 0) && 
                               (((i + L[i] + 1) % 2 == 0) || 
                           (text[(i + L[i] + 1) / 2] == 
                            text[(i - L[i] - 1) / 2])))
            {
                L[i]++;
            }

/*Track maxLPSLength*/

if (L[i] > maxLPSLength) 
            {
                maxLPSLength = L[i];
                maxLPSCenterPosition = i;
            }

/*            If palindrome centered at currentRightPosition i
            expand beyond centerRightPosition R,
            adjust centerPosition C based on expanded palindrome.*/

            if (i + L[i] > R) 
            {
                C = i;
                R = i + L[i];
            }

/*            Uncomment it to print LPS Length array
            printf("%d ", L[i]);*/

        }
        start = (maxLPSCenterPosition - maxLPSLength) / 2;
        end = start + maxLPSLength - 1;
        Console.Write("LPS of string is {0} : ", text);
        for (i = start; i <= end; i++)
            Console.Write(text[i]);
        Console.WriteLine();
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        String text = "babcbabcbaccba";
        findLongestPalindromicString(text);
        text = "abaaba";
        findLongestPalindromicString(text);
        text = "abababa";
        findLongestPalindromicString(text);
        text = "abcbabcbabcba";
        findLongestPalindromicString(text);
        text = "forgeeksskeegfor";
        findLongestPalindromicString(text);
        text = "caba";
        findLongestPalindromicString(text);
        text = "abacdfgdcaba";
        findLongestPalindromicString(text);
        text = "abacdfgdcabba";
        findLongestPalindromicString(text);
        text = "abacdedcaba";
        findLongestPalindromicString(text);
    }
}

/*C# program to print permutations of a
given string with spaces*/

using System;
class GFG
{

/*    Function recursively prints the
    strings having space pattern
    i and j are indices in 'String
    str' and 'buf[]' respectively*/

    static void printPatternUtil(string str,
                                 char[] buf, int i,
                                 int j, int n)
    {
        if (i == n)
        {
            buf[j] = '\0';
            Console.WriteLine(buf);
            return;
        }

/*        Either put the character*/

        buf[j] = str[i];
        printPatternUtil(str, buf, i + 1,
                               j + 1, n);

/*        Or put a space followed by next
        character*/

        buf[j] = ' ';
        buf[j + 1] = str[i];
        printPatternUtil(str, buf, i + 1,
                               j + 2, n);
    }

/*    Function creates buf[] to store
    individual output string and uses
    printPatternUtil() to print all
    permutations*/

    static void printPattern(string str)
    {
        int len = str.Length;

/*        Buffer to hold the string containing
        spaces 2n-1 characters and 1 string
        terminator*/

        char[] buf = new char[2 * len];

/*        Copy the first character as it is,
        since it will be always at first
        position*/

        buf[0] = str[0];
        printPatternUtil(str, buf, 1, 1, len);
    }

/*    Driver program*/

    public static void Main()
    {
        string str = "ABCD";
        printPattern(str);
    }
}

/*C# program for above approach*/

using System;
class GFG {

/*  N is the size of the 2D matrix   N*N*/

  static int N = 9;

/* A utility function to print grid */

  static void print(int[,] grid)
  {
    for (int i = 0; i < N; i++) {
      for (int j = 0; j < N; j++)
        Console.Write(grid[i,j] + " ");
      Console.WriteLine();
    }
  }

/*  Check whether it will be legal
  to assign num to the
  given row, col*/

  static bool isSafe(int[,] grid, int row, int col,
                     int num)
  {

/*    Check if we find the same num
    in the similar row , we
    return false*/

    for (int x = 0; x <= 8; x++)
      if (grid[row,x] == num)
        return false;

/*    Check if we find the same num
    in the similar column ,
    we return false*/

    for (int x = 0; x <= 8; x++)
      if (grid[x,col] == num)
        return false;

/*    Check if we find the same num
    in the particular 3*3
    matrix, we return false*/

    int startRow = row - row % 3, startCol
      = col - col % 3;
    for (int i = 0; i < 3; i++)
      for (int j = 0; j < 3; j++)
        if (grid[i + startRow,j + startCol] == num)
          return false;
    return true;
  }

/* Takes a partially filled-in grid and attempts
    to assign values to all unassigned locations in
    such a way to meet the requirements for
    Sudoku solution (non-duplication across rows,
    columns, and boxes) */

  static bool solveSuduko(int[,] grid, int row,
                          int col)
  {

/*if we have reached the 8th
           row and 9th column (0
           indexed matrix) ,
           we are returning true to avoid further
           backtracking       */

    if (row == N - 1 && col == N)
      return true;

/*    Check if column value  becomes 9 ,
    we move to next row
    and column start from 0*/

    if (col == N) {
      row++;
      col = 0;
    }

/*    Check if the current position
    of the grid already
    contains value >0, we iterate
    for next column*/

    if (grid[row,col] != 0)
      return solveSuduko(grid, row, col + 1);
    for (int num = 1; num < 10; num++) {

/*      Check if it is safe to place
      the num (1-9)  in the
      given row ,col ->we move to next column*/

      if (isSafe(grid, row, col, num)) {

/*  assigning the num in the current
                (row,col)  position of the grid and
                assuming our assined num in the position
                is correct */

        grid[row,col] = num;

/*        Checking for next
        possibility with next column*/

        if (solveSuduko(grid, row, col + 1))
          return true;
      }

/* removing the assigned num , since our
               assumption was wrong , and we go for next
               assumption with diff num value   */

      grid[row,col] = 0;
    }
    return false;
  }

/*  Driver code*/

  static void Main() {
    int[,] grid = { { 3, 0, 6, 5, 0, 8, 4, 0, 0 },
                   { 5, 2, 0, 0, 0, 0, 0, 0, 0 },
                   { 0, 8, 7, 0, 0, 0, 0, 3, 1 },
                   { 0, 0, 3, 0, 1, 0, 0, 8, 0 },
                   { 9, 0, 0, 8, 6, 3, 0, 0, 5 },
                   { 0, 5, 0, 0, 9, 0, 6, 0, 0 },
                   { 1, 3, 0, 0, 0, 0, 2, 5, 0 },
                   { 0, 0, 0, 0, 0, 0, 0, 7, 4 },
                   { 0, 0, 5, 2, 0, 6, 3, 0, 0 } };
    if (solveSuduko(grid, 0, 0))
      print(grid);
    else
      Console.WriteLine("No Solution exists");
  }
}

using System;
public class GFG {

/*    Function to calculate x raised to the power y*/

    static int power(int x, int y)
    {
        if (y == 0)
            return 1;
        else if (y % 2 == 0)
            return power(x, y / 2) * power(x, y / 2);
        else
            return x * power(x, y / 2) * power(x, y / 2);
    }

/*    Program to test function power*/

    public static void Main()
    {
        int x = 2;
        int y = 3;
        Console.Write(power(x, y));
    }
}

/*C# code for extended version of power function
that can work for float x and negative y*/

using System;
public class GFG{
    static float power(float x, int y)
    {
        float temp;
        if( y == 0)
            return 1;
        temp = power(x, y/2);
        if (y % 2 == 0)
            return temp * temp;
        else
        {
            if(y > 0)
                return x * temp * temp;
            else
                return (temp * temp) / x;
        }
    }

/*    Program to test function power*/

    public static void Main()
    {
        float x = 2;
        int y = -3;
        Console.Write(power(x, y));
    }
}

/*C# program for the above approach*/

using System;
class GFG{
public static int power(int x, int y)
{

/*    If x^0 return 1*/

    if (y == 0)
        return 1;

/*    If we need to find of 0^y*/

    if (x == 0)
        return 0;

/*    For all other cases*/

    return x * power(x, y - 1);
}

