/*A Simple Merge based O(n) solution
to find median of two sorted arrays*/

using System;
class GFG
{

/*    function to calculate median*/

    static int getMedian(int []ar1,
                         int []ar2,
                         int n)
    {
        int i = 0;
        int j = 0;
        int count;
        int m1 = -1, m2 = -1;

/*        Since there are 2n elements,
        median will be average of
        elements at index n-1 and n in
        the array obtained after
        merging ar1 and ar2*/

        for (count = 0; count <= n; count++)
        {

/*            Below is to handle case
            where all elements of ar1[] 
            are smaller than smallest
            (or first) element of ar2[]*/

            if (i == n)
            {
                m1 = m2;
                m2 = ar2[0];
                break;
            }

/* Below is to handle case where all
            elements of ar2[] are smaller than
            smallest(or first) element of ar1[] */

            else if (j == n)
            {
                m1 = m2;
                m2 = ar1[0];
                break;
            }

/* equals sign because if two
            arrays have some common elements */

            if (ar1[i] <= ar2[j])
            {

/*                Store the prev median*/

                m1 = m2;
                m2 = ar1[i];
                i++;
            }
            else
            {

/*                Store the prev median*/

                m1 = m2;
                m2 = ar2[j];
                j++;
            }
        }
        return (m1 + m2)/2;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int []ar1 = {1, 12, 15, 26, 38};
        int []ar2 = {2, 13, 17, 30, 45};
        int n1 = ar1.Length;
        int n2 = ar2.Length;
        if (n1 == n2)
            Console.Write("Median is " +
                        getMedian(ar1, ar2, n1));
        else
            Console.Write("arrays are of unequal size");
    }
}

/*A C# program to divide and conquer based
efficient solution to find
median of two sorted arrays
of same size.*/

using System;
class GfG{

/* This function returns median
of ar1[] and ar2[].
Assumptions in this function:
Both ar1[] and ar2[] are
sorted arrays
Both have n elements */

static int getMedian(int[] a, int[] b,
                     int startA, int startB,
                     int endA, int endB)
{
  if (endA - startA == 1)
  {
    return (Math.Max(a[startA],
                     b[startB]) +
            Math.Min(a[endA], b[endB])) / 2;
  }

/* get the median of
    the first array */

  int m1 = median(a, startA, endA);

/* get the median of
    the second array */

  int m2 = median(b, startB, endB);

/* If medians are equal then
    return either m1 or m2 */

  if (m1 == m2)
  {
    return m1;
  }

/*if m1 < m2 then median must
    exist in ar1[m1....] and
    ar2[....m2] */

  else if (m1 < m2)
  {
    return getMedian(a, b,
                    (endA + startA + 1) / 2,
                     startB, endA,
                    (endB + startB + 1) / 2);
  }

/*if m1 > m2 then median must
    exist in ar1[....m1] and
    ar2[m2...] */

  else
  {
    return getMedian(a, b, startA,
                    (endB + startB + 1) / 2,
                    (endA + startA + 1) / 2, endB);
  }
}

/* Function to get median
of a sorted array */

static int median(int[] arr,
                  int start, int end)
{
  int n = end - start + 1;
  if (n % 2 == 0)
  {
    return (arr[start + (n / 2)] +
            arr[start + (n / 2 - 1)]) / 2;
  }
  else
  {
    return arr[start + n / 2];
  }
}

/*Driver code*/

public static void Main(String[] args)
{
  int []ar1 = {1, 2, 3, 6};
  int []ar2 = {4, 6, 8, 10};
  int n1 = ar1.Length;
  int n2 = ar2.Length;
  if (n1 != n2)
  {
    Console.WriteLine("Doesn't work for arrays " +
                      "of unequal size");
  }
  else if (n1 == 0)
  {
    Console.WriteLine("Arrays are empty.");
  }
  else if (n1 == 1)
  {
    Console.WriteLine((ar1[0] + ar2[0]) / 2);
  }
  else
  {
    Console.WriteLine("Median is " +
                       getMedian(ar1, ar2, 0, 0,
                                 ar1.Length - 1,
                                 ar2.Length - 1));
  }
}
}

using System;

public class GFG
{
  /* This function returns
    median of ar1[] and ar2[].
    Assumptions in this function:
    Both ar1[] and ar2[]
    are sorted arrays
    Both have n elements */

  public static int getMedian(int []ar1,
                              int []ar2, int n)
  {
    int j = 0;
    int i = n - 1;
    while (ar1[i] > ar2[j] && j < n && i > -1)
    {
      int temp = ar1[i];
      ar1[i] = ar2[j];
      ar2[j] = temp;
      i--; j++;
    }
    Array.Sort(ar1);
    Array.Sort(ar2);
    return (ar1[n - 1] + ar2[0]) / 2;
  }

/*  Driver code*/

  public static void Main(String[] args)
  {
    int []ar1 = { 1, 12, 15, 26, 38 };
    int []ar2 = { 2, 13, 17, 30, 45 };
    int n1 = 5;
    int n2 = 5;
    if (n1 == n2)
      Console.WriteLine("Median is "+ getMedian(ar1, ar2, n1));
    else
      Console.WriteLine("Doesn't work for arrays of unequal size");
  }
}

/*C# program to check if two given line segments intersect*/

using System;
using System.Collections.Generic; 
class GFG 
{
public class Point
{
    public int x;
    public int y;
    public Point(int x, int y) 
    {
        this.x = x;
        this.y = y;
    }
};

/*Given three colinear points p, q, r, the function checks if
point q lies on line segment 'pr'*/

static Boolean onSegment(Point p, Point q, Point r)
{
    if (q.x <= Math.Max(p.x, r.x) && q.x >= Math.Min(p.x, r.x) &&
        q.y <= Math.Max(p.y, r.y) && q.y >= Math.Min(p.y, r.y))
    return true;
    return false;
}

/*To find orientation of ordered triplet (p, q, r).
The function returns following values
0 --> p, q and r are colinear
1 --> Clockwise
2 --> Counterclockwise*/

static int orientation(Point p, Point q, Point r)
{

/*www.geeksforgeeks.org/orientation-3-ordered-points/
See https:
    for details of below formula.*/

    int val = (q.y - p.y) * (r.x - q.x) -
            (q.x - p.x) * (r.y - q.y);

/*colinear*/

if (val == 0) return 0;

/*clock or counterclock wise*/

return (val > 0)? 1: 2; 
}

/*The main function that returns true if line segment 'p1q1'
and 'p2q2' intersect.*/

static Boolean doIntersect(Point p1, Point q1, Point p2, Point q2)
{

/*    Find the four orientations needed for general and
    special cases*/

    int o1 = orientation(p1, q1, p2);
    int o2 = orientation(p1, q1, q2);
    int o3 = orientation(p2, q2, p1);
    int o4 = orientation(p2, q2, q1);

/*    General case*/

    if (o1 != o2 && o3 != o4)
        return true;

/*    Special Cases
    p1, q1 and p2 are colinear and p2 lies on segment p1q1*/

    if (o1 == 0 && onSegment(p1, p2, q1)) return true;

/*    p1, q1 and q2 are colinear and q2 lies on segment p1q1*/

    if (o2 == 0 && onSegment(p1, q2, q1)) return true;

/*    p2, q2 and p1 are colinear and p1 lies on segment p2q2*/

    if (o3 == 0 && onSegment(p2, p1, q2)) return true;

/*    p2, q2 and q1 are colinear and q1 lies on segment p2q2*/

    if (o4 == 0 && onSegment(p2, q1, q2)) return true;

/*Doesn't fall in any of the above cases*/

return false; 
}

/*Driver code*/

public static void Main(String[] args) 
{
    Point p1 = new Point(1, 1);
    Point q1 = new Point(10, 1);
    Point p2 = new Point(1, 2);
    Point q2 = new Point(10, 2);
    if(doIntersect(p1, q1, p2, q2))
        Console.WriteLine("Yes");
    else
        Console.WriteLine("No");
    p1 = new Point(10, 1); q1 = new Point(0, 10);
    p2 = new Point(0, 0); q2 = new Point(10, 10);
    if(doIntersect(p1, q1, p2, q2))
            Console.WriteLine("Yes");
    else
        Console.WriteLine("No");
    p1 = new Point(-5, -5); q1 = new Point(0, 0);
    p2 = new Point(1, 1); q2 = new Point(10, 10);;
    if(doIntersect(p1, q1, p2, q2))
        Console.WriteLine("Yes");
    else
        Console.WriteLine("No");
}
}

/*C# Code to Check whether a given point
lies inside a triangle or not*/

using System;
class GFG {

/* A utility function to calculate area of triangle
    formed by (x1, y1) (x2, y2) and (x3, y3) */

    static double area(int x1, int y1, int x2,
                       int y2, int x3, int y3)
    {
        return Math.Abs((x1 * (y2 - y3) +
                         x2 * (y3 - y1) +
                         x3 * (y1 - y2)) / 2.0);
    }

/* A function to check whether point P(x, y) lies
    inside the triangle formed by A(x1, y1),
    B(x2, y2) and C(x3, y3) */

    static bool isInside(int x1, int y1, int x2,
                         int y2, int x3, int y3,
                         int x, int y)
    {

/* Calculate area of triangle ABC */

        double A = area(x1, y1, x2, y2, x3, y3);

/* Calculate area of triangle PBC */

        double A1 = area(x, y, x2, y2, x3, y3);

/* Calculate area of triangle PAC */

        double A2 = area(x1, y1, x, y, x3, y3);

/* Calculate area of triangle PAB */

        double A3 = area(x1, y1, x2, y2, x, y);

/* Check if sum of A1, A2 and A3 is same as A */

        return (A == A1 + A2 + A3);
    }

/* Driver program to test above function */

public static void Main()
{

/* Let us check whether the point P(10, 15)
    lies inside the triangle formed by
    A(0, 0), B(20, 0) and C(10, 30) */

    if (isInside(0, 0, 20, 0, 10, 30, 10, 15))
        Console.WriteLine("Inside");
    else
        Console.WriteLine("Not Inside");
}
}

/*C# program to check Lucky Number*/

using System;
class GFG {
    public static int counter = 2;

/*    Returns 1 if n is a lucky no.
    ohterwise returns 0*/

    static bool isLucky(int n)
    {

/*        variable next_position is
        just for readability of
        the program we can remove
        it and use n only*/

        int next_position = n;
        if(counter > n)
            return true;
        if(n % counter == 0)
            return false;

/*        calculate next position of
        input no*/

        next_position -= next_position
                            / counter;
        counter++;
        return isLucky(next_position);
    }

/*    driver program*/

    public static void Main ()
    {
        int x = 5;
        if( isLucky(x) )
            Console.Write(x + " is a "
                         + "lucky no.");
        else
            Console.Write(x + " is not"
                      + " a lucky no.");
    }
}

/*C# Porgram for Babylonian
method of square root*/

using System;
class GFG {

/*    Returns the square root of n.
    Note that the function*/

    static float squareRoot(float n)
    {

/*        We are using n itself as
        initial approximation This
        can definitely be improved*/

        float x = n;
        float y = 1;

/*        e decides the
        accuracy level*/

        double e = 0.000001;
        while (x - y > e) {
            x = (x + y) / 2;
            y = n / x;
        }
        return x;
    }

/*    Driver Code*/

    public static void Main()
    {
        int n = 50;
        Console.Write("Square root of "
                      + n + " is " + squareRoot(n));
    }
}

/*Multiply two integers without
using multiplication, division
and bitwise operators, and no
loops*/

using System;
class GFG {

/*    function to multiply two numbers
    x and y*/

    static int multiply(int x, int y) {

/*        0 multiplied with anything gives 0*/

        if (y == 0)
            return 0;

/*        Add x one by one*/

        if (y > 0)
            return (x + multiply(x, y - 1));

/*        the case where y is negative*/

        if (y < 0)
            return -multiply(x, -y);
        return -1;
    }

/*    Driver code*/

    public static void Main() {
        Console.WriteLine(multiply(5, -11));
    }
}

using System;
class GFG
{

/* Works only if a >= 0 and b >= 0 */

    static int pow(int a, int b)
    {
        if (b == 0)
            return 1;
        int answer = a;
        int increment = a;
        int i, j;
        for (i = 1; i < b; i++) {
            for (j = 1; j < a; j++) {
                answer += increment;
            }
            increment = answer;
        }
        return answer;
    }

/*    driver program to test
    above function*/

    public static void Main()
    {
        Console.Write(pow(5, 3));
    }
}

using System;
class GFG
{

/* A recursive function to get x*y */

    static int multiply(int x, int y)
    {
        if (y > 0)
            return (x + multiply(x, y - 1));
        else
            return 0;
    }

/* A recursive function to get a^b
    Works only if a >= 0 and b >= 0 */

    static int pow(int a, int b)
    {
        if (b > 0)
            return multiply(a, pow(a, b - 1));
        else
            return 1;
    }

/* driver program to test above functions */

    public static void Main()
    {
        Console.Write(pow(5, 3));
    }
}

/*C# program to find average
of a stream of numbers*/

using System;
class GFG
{

/*    Returns the new average
    after including x*/

    static float getAvg(float prev_avg,
                        float x, int n)
    {
        return (prev_avg * n + x) / (n + 1);
    }

/*    Prints average of
    a stream of numbers*/

    static void streamAvg(float[] arr,
                          int n)
    {
        float avg = 0;
        for (int i = 0; i < n; i++)
        {
            avg = getAvg(avg, arr[i], i);
            Console.WriteLine("Average of {0} " +
                                "numbers is {1}",
                                     i + 1, avg);
        }
        return;
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        float[] arr = {10, 20, 30,
                       40, 50, 60};
        int n = arr.Length;
        streamAvg(arr, n);
    }
}

