/*C# program to count numbers that not
contain 3*/

using System;
class GFG {

/*    Function that returns count of
    numbers which are in range from
    1 to n and not contain 3 as a
    digit*/

    static int count(int n)
    {

/*        Base cases (Assuming n is
        not negative)*/

        if (n < 3)
            return n;
        if (n >= 3 && n < 10)
            return n-1;

/*        Calculate 10^(d-1) (10 raise
        to the power d-1) where d is
        number of digits in n. po will
        be 100 for n = 578*/

        int po = 1;
        while (n / po > 9)
            po = po * 10;

/*        find the most significant
        digit (msd is 5 for 578)*/

        int msd = n / po;
        if (msd != 3)

/*            For 578, total will be
            4*count(10^2 - 1) + 4 +
            count(78)*/

            return count(msd) * count(po - 1)
                + count(msd) + count(n % po);
        else

/*            For 35, total will be equal
            to count(29)*/

            return count(msd * po - 1);
    }

/*    Driver program*/

    public static void Main ()
    {
        int n = 578;
        Console.Write(count(n));
    }
}

/*C# program to print all primes
smaller than or equal to n
using Sieve of Eratosthenes*/

using System;
namespace prime {
public class GFG {
    public static void SieveOfEratosthenes(int n)
    {

/*        Create a boolean array
        "prime[0..n]" and
        initialize all entries
        it as true. A value in
        prime[i] will finally be
        false if i is Not a
        prime, else true.*/

        bool[] prime = new bool[n + 1];
        for (int i = 0; i < n; i++)
            prime[i] = true;
        for (int p = 2; p * p <= n; p++)
        {

/*            If prime[p] is not changed,
            then it is a prime*/

            if (prime[p] == true)
            {

/*                Update all multiples of p*/

                for (int i = p * p; i <= n; i += p)
                    prime[i] = false;
            }
        }

/*        Print all prime numbers*/

        for (int i = 2; i <= n; i++)
        {
            if (prime[i] == true)
                Console.Write(i + " ");
        }
    }

/*    Driver Code*/

    public static void Main()
    {
        int n = 30;
        Console.WriteLine(
            "Following are the prime numbers");
        Console.WriteLine("smaller than or equal to " + n);
        SieveOfEratosthenes(n);
    }
}
}

/*C# program to print the
Number which has the maximum
number of distinct prime
factors of numbers in range
m to n*/

using System;
class GFG
{

/*Function to return
the maximum number*/

static int maximumNumberDistinctPrimeRange(int m,
                                           int n)
{

/*    array to store the
    number of distinct primes*/

    long []factorCount = new long[n + 1];

/*    true if index 'i'
    is a prime*/

    bool []prime = new bool[n + 1];

/*    initializing the number
    of factors to 0 and*/

    for (int i = 0; i <= n; i++)
    {
        factorCount[i] = 0;

/*Used in Sieve*/

prime[i] = true; 
    }
    for (int i = 2; i <= n; i++)
    {

/*        condition works only x
        when 'i' is prime, hence
        for factors of all prime
        number, the prime status
        is changed to false*/

        if (prime[i] == true)
        {

/*            Number is prime*/

            factorCount[i] = 1;

/*            number of factor of
            a prime number is 1*/

            for (int j = i * 2;
                     j <= n; j += i)
            {

/*                incrementing factorCount
                all the factors of i*/

                factorCount[j]++;

/*                and changing prime
                status to false*/

                prime[j] = false;
            }
        }
    }

/*    Initialize the max and num*/

    int max = (int)factorCount[m];
    int num = m;

/*    Gets the maximum number*/

    for (int i = m; i <= n; i++)
    {

/*        Gets the maximum number*/

        if (factorCount[i] > max)
        {
            max = (int)factorCount[i];
            num = i;
        }
    }
    return num;
}

/*Driver code*/

public static void Main ()
{
int m = 4, n = 6;

/*Calling function*/

Console.WriteLine(
         maximumNumberDistinctPrimeRange(m, n));
}
}

/*C# program to find lexicographic rank
of a string*/

using System;
class GFG {

/*    A utility function to find factorial of n*/

    static int fact(int n)
    {
        return (n <= 1) ? 1 : n * fact(n - 1);
    }

/*    A utility function to count smaller
    characters on right of arr[low]*/

    static int findSmallerInRight(string str,
                                  int low, int high)
    {
        int countRight = 0, i;
        for (i = low + 1; i <= high; ++i)
            if (str[i] < str[low])
                ++countRight;
        return countRight;
    }

/*    A function to find rank of a string in
    all permutations of characters*/

    static int findRank(string str)
    {
        int len = str.Length;
        int mul = fact(len);
        int rank = 1;
        int countRight;
        for (int i = 0; i < len; ++i) {
            mul /= len - i;

/*            count number of chars smaller
            than str[i] from str[i+1] to
            str[len-1]*/

            countRight = findSmallerInRight(str,
                                            i, len - 1);
            rank += countRight * mul;
        }
        return rank;
    }

/*    Driver program to test above function*/

    public static void Main()
    {
        string str = "string";
        Console.Write(findRank(str));
    }
}

/*A O(n) solution for finding rank of string*/

using System;
class GFG {
    static int MAX_CHAR = 256;

/*        all elements of count[] are initialized with 0*/

        int[] count = new int[MAX_CHAR];

/*    A utility function to find factorial of n*/

    static int fact(int n)
    {
        return (n <= 1) ? 1 : n * fact(n - 1);
    }

/*    Construct a count array where value at every index
    contains count of smaller characters in whole string*/

    static void populateAndIncreaseCount(int[] count, char[] str)
    {
        int i;
        for (i = 0; i < str.Length; ++i)
            ++count[str[i]];
        for (i = 1; i < MAX_CHAR; ++i)
            count[i] += count[i - 1];
    }

/*    Removes a character ch from count[] array
    constructed by populateAndIncreaseCount()*/

    static void updatecount(int[] count, char ch)
    {
        int i;
        for (i = ch; i < MAX_CHAR; ++i)
            --count[i];
    }

/*    A function to find rank of a string in all permutations
    of characters*/

    static int findRank(char[] str)
    {
        int len = str.Length;
        int mul = fact(len);
        int rank = 1, i;

/*        Populate the count array such that count[i]
        contains count of characters which are present
        in str and are smaller than i*/

        populateAndIncreaseCount(count, str);
        for (i = 0; i < len; ++i) {
            mul /= len - i;

/*            count number of chars smaller than str[i]
            fron str[i+1] to str[len-1]*/

            rank += count[str[i] - 1] * mul;

/*            Reduce count of characters greater than str[i]*/

            updatecount(count, str[i]);
        }
        return rank;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        char[] str = "string".ToCharArray();
        Console.WriteLine(findRank(str));
    }
}

/*C# Program to calculate C(n, k)*/

using System;
class BinomialCoefficient {

/*    Returns value of Binomial
    Coefficient C(n, k)*/

    static int binomialCoeff(int n, int k)
    {
        int res = 1;

/*        Since C(n, k) = C(n, n-k)*/

        if (k > n - k)
            k = n - k;

/*        Calculate value of [n * ( n - 1) *---* (
        n - k + 1)] / [k * (k - 1) *----* 1]*/

        for (int i = 0; i < k; ++i) {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

/*    Driver Code*/

    public static void Main()
    {
        int n = 8;
        int k = 2;
        Console.Write("Value of C(" + n + ", " + k + ") "
                      + "is"
                      + " " + binomialCoeff(n, k));
    }
}

/*C# code for Pascal's Triangle*/

using System;
class GFG {

/*binomialCoeff*/


    static int binomialCoeff(int n, int k)
    {
        int res = 1;
        if (k > n - k)
        k = n - k;
        for (int i = 0; i < k; ++i)
        {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

/*    Function to print first
    n lines of Pascal's Triangle*/

    static void printPascal(int n)
    {

/*    Iterate through every line
    and print entries in it*/

    for (int line = 0; line < n; line++)
    {

/*        Every line has number of
        integers equal to line number*/

        for (int i = 0; i <= line; i++)
        Console.Write(binomialCoeff
                        (line, i)+" ");
        Console.WriteLine();
    }
    }

/*    Driver code*/

    public static void Main()
    {
    int n = 7;
    printPascal(n);
    }
}

/*C# program for Pascal's Triangle*/
using System;
class GFG
{

/*A O(n^2) time and O(n^2) extra
space method for Pascal's Triangle*/

public static void printPascal(int n)
{

/*An auxiliary array to store
generated pascal triangle values*/

int[,] arr = new int[n, n];

/*Iterate through every line
and print integer(s) in it*/

for (int line = 0; line < n; line++)
{

/*    Every line has number of
    integers equal to line number*/

    for (int i = 0; i <= line; i++)
