/*C# program for Pascal's Triangle
A O(n^2) time and O(1) extra
space method for Pascal's Triangle*/

using System;
class GFG
{
public static void printPascal(int n)
{
    for(int line = 1;
            line <= n; line++)
    {

/*used to represent C(line, i)*/

int C = 1;
    for(int i = 1; i <= line; i++)
    {

/*        The first value in a
        line is always 1*/

        Console.Write(C + " ");
        C = C * (line - i) / i;
    }
    Console.Write("\n") ;
    }
}

/*Driver code*/

public static void Main ()
{
    int n = 5;
    printPascal(n);
}
}

/*C# efficient program to calculate
e raise to the power x*/

using System;
class GFG
{

/*    Function returns approximate value of e^x
    using sum of first n terms of Taylor Series*/

    static float exponential(int n, float x)
    {

/*        initialize sum of series*/

        float sum = 1;
        for (int i = n - 1; i > 0; --i )
            sum = 1 + x * sum / i;
        return sum;
    }

/*    driver program*/

    public static void Main ()
    {
        int n = 10;
        float x = 1;
        Console.Write("e^x = " + exponential(n, x));
    }
}

/* Sample run of the Algo for V1 with capacity 3 and V2 with capacity 7
1. Fill V1:                             V1 = 3, V2 = 0
2. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 3
2. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 6
3. Transfer from V1 to V2, and empty V2: V1 = 2, V2 = 0
4. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 2
5. Transfer from V1 to V2, and fill V1: V1 = 3, V2 = 5
6. Transfer from V1 to V2, and empty V2: V1 = 1, V2 = 0
7. Stop as V1 now contains 1 litre.
Note that V2 was made empty in steps 3 and 6 because it became full */

using System;
class GFG
{

/*    A utility function to get GCD of two numbers*/

    static int gcd(int a, int b) 
    {
        return b > 0 ? gcd(b, a % b) : a;
    }

/*    Class to represent a Vessel*/

    class Vessel 
    {

/*        A vessel has capacity, and 
        current amount of water in it*/

        int capacity, current;

/*        Constructor: initializes capacity
        as given, and current as 0*/

        public Vessel(int capacity)
        {
            this.capacity = capacity;
            current = 0;
        }

/*        The main function to fill one litre 
        in this vessel. Capacity of V2 must be
        greater than this vessel and two capacities
        must be coprime*/

        public void makeOneLitre(Vessel V2)
        {

/*            solution exists iff a and b are co-prime*/

            if (gcd(capacity, V2.capacity) != 1)
                return;
            while (current != 1)
            {

/*                fill A (smaller vessel)*/

                if (current == 0)
                    current = capacity;
                Console.Write("Vessel 1: " + current + 
                            " Vessel 2: " + V2.current + "\n");

/*                Transfer water from V1 to V2 and 
                reduce current of V1 by
                the amount equal to transferred water*/

                current = current - V2.transfer(current);
            }

/*            Finally, there will be 1 litre in vessel 1*/

            Console.Write("Vessel 1: " + current + 
                        " Vessel 2: " + V2.current + "\n");
        }

/*        Fills vessel with given amount and 
        returns the amount of water
        transferred to it. If the vessel 
        becomes full, then the vessel
        is made empty*/

        int transfer(int amount)
        {

/*            If the vessel can accommodate the given amount*/

            if (current + amount < capacity) 
            {
                current += amount;
                return amount;
            }

/*            If the vessel cannot accommodate
            the given amount, then store
            the amount of water transferred*/

            int transferred = capacity - current;

/*            Since the vessel becomes full, make the vessel
            empty so that it can be filled again*/

            current = 0;
            return transferred;
        }
    }

/*    Driver program to test above function*/

    public static void Main(String[] args)
    {

/*a must be smaller than b*/

int a = 3, b = 7;

/*        Create two vessels of capacities a and b*/

        Vessel V1 = new Vessel(a);
        Vessel V2 = new Vessel(b);

/*        Get 1 litre in first vessel*/

        V1.makeOneLitre(V2);
    }
}

/*C# Program to print all prime factors*/

using System;
namespace prime
{
public class GFG
{

/*    A function to print all prime
    factors of a given number n*/

    public static void primeFactors(int n)
    {

/*        Print the number of 2s that divide n*/

        while (n % 2 == 0)
        {
            Console.Write(2 + " ");
            n /= 2;
        }

/*        n must be odd at this point. So we can
        skip one element (Note i = i +2)*/

        for (int i = 3; i <= Math.Sqrt(n); i+= 2)
        {

/*            While i divides n, print i and divide n*/

            while (n % i == 0)
            {
                Console.Write(i + " ");
                n /= i;
            }
        }

/*        This condition is to handle the case whien
        n is a prime number greater than 2*/

        if (n > 2)
            Console.Write(n);
    }

/*    Driver Code*/

    public static void Main()
    {
        int n = 315;
        primeFactors(n);
    }
}
}

/*C# program to print all
combination of size r
in an array of size n*/

using System;
class GFG
{

/*    The main function that prints
    all combinations of size r
    in arr[] of size n. This
    function mainly uses combinationUtil()*/

    static void printCombination(int []arr,
                                 int n, int r)
    {

/*        A temporary array to store
        all combination one by one*/

        int []data = new int[r];

/*        Print all combination
        using temprary array 'data[]'*/

        combinationUtil(arr, data, 0,
                        n - 1, 0, r);
    }

/* arr[] ---> Input Array
    data[] ---> Temporary array to
                store current combination
    start & end ---> Staring and Ending
                     indexes in arr[]
    index ---> Current index in data[]
    r ---> Size of a combination
            to be printed */

    static void combinationUtil(int []arr, int []data,
                                int start, int end,
                                int index, int r)
    {

/*        Current combination is
        ready to be printed,
        print it*/

        if (index == r)
        {
            for (int j = 0; j < r; j++)
                Console.Write(data[j] + " ");
            Console.WriteLine("");
            return;
        }

/*        replace index with all
        possible elements. The
        condition "end-i+1 >=
        r-index" makes sure that
        including one element
        at index will make a
        combination with remaining
        elements at remaining positions*/

        for (int i = start; i <= end &&
                  end - i + 1 >= r - index; i++)
        {
            data[index] = arr[i];
            combinationUtil(arr, data, i + 1,
                            end, index + 1, r);
        }
    }

/*    Driver Code*/

    static public void Main ()
    {
        int []arr = {1, 2, 3, 4, 5};
        int r = 3;
        int n = arr.Length;
        printCombination(arr, n, r);
    }
}

/*C# program to print all
combination of size r
in an array of size n*/

using System;
class GFG
{

/*    The main function that prints
    all combinations of size r
    in arr[] of size n. This
    function mainly uses combinationUtil()*/

    static void printCombination(int []arr,
                                 int n, int r)
    {

/*        A temporary array to store
        all combination one by one*/

        int []data = new int[r];

/*        Print all combination
        using temprary array 'data[]'*/

        combinationUtil(arr, n, r, 0, data, 0);
    }

/* arr[] ---> Input Array
    data[] ---> Temporary array to
                store current combination
    start & end ---> Staring and Ending
                     indexes in arr[]
    index ---> Current index in data[]
    r ---> Size of a combination
           to be printed */

    static void combinationUtil(int []arr, int n,
                                int r, int index,
                                int []data, int i)
    {

/*        Current combination is ready
        to be printed, print it*/

        if (index == r)
        {
            for (int j = 0; j < r; j++)
                Console.Write(data[j] + " ");
                Console.WriteLine("");
            return;
        }

/*        When no more elements are
        there to put in data[]*/

        if (i >= n)
        return;

/*        current is included, put
        next at next location*/

        data[index] = arr[i];
        combinationUtil(arr, n, r,
                        index + 1, data, i + 1);

/*        current is excluded, replace
        it with next (Note that
        i+1 is passed, but index
        is not changed)*/

        combinationUtil(arr, n, r, index,
                        data, i + 1);
    }

/*    Driver Code*/

    static public void Main ()
    {
        int []arr = {1, 2, 3, 4, 5};
        int r = 3;
        int n = arr.Length;
        printCombination(arr, n, r);
    }
}

/*C# program to generate random numbers
according to given frequency distribution*/

using System;
class GFG{

/*Utility function to find ceiling
of r in arr[l..h] */

static int findCeil(int[] arr, int r,
                    int l, int h) 
{ 
    int mid;
    while (l < h) 
    {

/*        Same as mid = (l+h)/2 */

        mid = l + ((h - l) >> 1);
        if (r > arr[mid]) 
            l = mid + 1;
        else
            h = mid; 
    } 
    return (arr[l] >= r) ? l : -1; 
}

/*The main function that returns a random number
from arr[] according to distribution array 
defined by freq[]. n is size of arrays. */

static int myRand(int[] arr, int[] freq, int n) 
{

/*    Create and fill prefix array */

    int[] prefix = new int[n];
    int i; 
    prefix[0] = freq[0]; 
    for(i = 1; i < n; ++i) 
        prefix[i] = prefix[i - 1] + freq[i];

/*    prefix[n-1] is sum of all frequencies.
    Generate a random number with 
    value from 1 to this sum*/

    Random rand = new Random();
    int r = ((int)(rand.Next() * (323567)) %
                      prefix[n - 1]) + 1;

/*    Find index of ceiling of r in prefix arrat */

    int indexc = findCeil(prefix, r, 0, n - 1); 
    return arr[indexc]; 
}

/*Driver Code*/

static void Main()
{
    int[] arr = { 1, 2, 3, 4 }; 
    int[] freq = { 10, 5, 20, 100 }; 
    int i, n = arr.Length;

/*    Let us generate 10 random numbers
    accroding to given distribution */

    for(i = 0; i < 5; i++) 
        Console.WriteLine(myRand(arr, freq, n)); 
}
}

/*C# program to check if
x is a perfect square*/

using System;
class GFG {

/*    A utility function that returns
    true if x is perfect square*/

    static bool isPerfectSquare(int x)
    {
        int s = (int)Math.Sqrt(x);
        return (s * s == x);
    }

/*    Returns true if n is a
    Fibonacci Number, else false*/

    static bool isFibonacci(int n)
    {

/*        n is Fibonacci if one of
        5*n*n + 4 or 5*n*n - 4 or
        both are a perfect square*/

        return isPerfectSquare(5 * n * n + 4) ||
               isPerfectSquare(5 * n * n - 4);
    }

/*    Driver method*/

    public static void Main()
    {
        for (int i = 1; i <= 10; i++)
            Console.WriteLine(isFibonacci(i) ? i +
                              " is a Fibonacci Number" : i +
                              " is a not Fibonacci Number");
    }
}

/*C# Program to count all possible
groups of size 2 or 3 that have
sum as multiple of 3*/

using System;
class FindGroups
{

/*    Returns count of all possible
    groups that can be formed
    from elements of a[].*/

    int findgroups(int []arr, int n)
    {

/*        Create an array C[3] to store
        counts of elements with remainder
        0, 1 and 2. c[i] would store
        count of elements with remainder i*/

        int [] c= new int[]{0, 0, 0};
        int i;

/*        To store the result*/

        int res = 0;

/*        Count elements with
        remainder 0, 1 and 2*/

        for (i = 0; i < n; i++)
            c[arr[i] % 3]++;

/*        Case 3.a: Count groups of size
        2 from 0 remainder elements*/

        res += ((c[0] * (c[0] - 1)) >> 1);

/*        Case 3.b: Count groups of size 2
        with one element with 1 remainder
        and other with 2 remainder*/

        res += c[1] * c[2];

/*        Case 4.a: Count groups of size 3
        with all 0 remainder elements*/

        res += (c[0] * (c[0] - 1) *
               (c[0] - 2)) / 6;

/*        Case 4.b: Count groups of size 3
        with all 1 remainder elements*/

        res += (c[1] * (c[1] - 1) *
               (c[1] - 2)) / 6;

/*        Case 4.c: Count groups of size 3
        with all 2 remainder elements*/

        res += ((c[2] * (c[2] - 1) *
                (c[2] - 2)) / 6);

/*        Case 4.c: Count groups of size 3
        with different remainders*/

        res += c[0] * c[1] * c[2];

/*        Return total count stored in res*/

        return res;
    }

/*    Driver Code*/

    public static void Main()
    {
        FindGroups groups = new FindGroups();
        int []arr = {3, 6, 7, 2, 9};
        int n = arr.Length;
        Console.Write("Required number of groups are "
                       + groups.findgroups(arr, n));
    }
}

/*C# program to count
trailing 0s in n!*/

using System;
class GFG
{

/*    Function to return trailing
    0s in factorial of n*/

    static int findTrailingZeros(int n)
    {

/*        Initialize result*/

        int count = 0;

/*        Keep dividing n by powers
        of 5 and update count*/

        for (int i = 5; n / i >= 1; i *= 5)
            count += n / i;
        return count;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int n = 100;
        Console.WriteLine("Count of trailing 0s in " +
                                           n +"! is "+
                                findTrailingZeros(n));
    }
}

/*A recursive C# program to find
nth catalan number*/

using System;
class GFG {

/*    A recursive function to find
    nth catalan number*/

    static int catalan(int n)
    {

/*        Base case*/

        if (n <= 1)
        {
            return 1;
        }

/*    catalan(n) is sum of
    catalan(i)*catalan(n-i-1)*/

        int res = 0;
        for (int i = 0; i < n; i++)
        {
            res += catalan(i)
                * catalan(n - i - 1);
        }
        return res;
    }

/*    Driver Code*/

    public static void Main()
    {
        for (int i = 0; i < 10; i++)
            Console.Write(catalan(i) + " ");
    }
}

/*    A dynamic programming based
    function to find nth
    Catalan number*/
using System;
class GFG {
    static uint catalanDP(uint n)
    {

/*        Table to store results of subproblems*/

        uint[] catalan = new uint[n + 2];

/*        Initialize first two values in table*/

        catalan[0] = catalan[1] = 1;

/*        Fill entries in catalan[]
        using recursive formula*/

        for (uint i = 2; i <= n; i++) {
            catalan[i] = 0;
            for (uint j = 0; j < i; j++)
                catalan[i]
                    += catalan[j] * catalan[i - j - 1];
        }

/*        Return last entry*/

        return catalan[n];
    }

/*    Driver code*/

    static void Main()
    {
        for (uint i = 0; i < 10; i++)
            Console.Write(catalanDP(i) + " ");
    }
}

/*C# program for nth Catalan Number*/

using System;
class GFG {

/*    Returns value of Binomial Coefficient C(n, k)*/

    static long binomialCoeff(int n, int k)
    {
        long res = 1;

/*        Since C(n, k) = C(n, n-k)*/

        if (k > n - k) {
            k = n - k;
        }

/*        Calculate value of [n*(n-1)*---*(n-k+1)] /
        [k*(k-1)*---*1]*/

        for (int i = 0; i < k; ++i) {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

/*    A Binomial coefficient based function to find nth
    catalan number in O(n) time*/

    static long catalan(int n)
    {

/*        Calculate value of 2nCn*/

        long c = binomialCoeff(2 * n, n);

/*        return 2nCn/(n+1)*/

        return c / (n + 1);
    }

/*    Driver code*/

    public static void Main()
    {
        for (int i = 0; i < 10; i++) {
            Console.Write(catalan(i) + " ");
        }
    }
}

