/*C# program to find Excel
column name from a given
column number*/

using System;
class GFG{

static String reverse(String input)
{
    char[] reversedString = input.ToCharArray();
    Array.Reverse(reversedString);
    return new String(reversedString);
}

/*Function to print Excel column
name for a given column number*/

private static void printString(int columnNumber)
{

/*    To store result (Excel column name)*/

    String columnName = "";
    while (columnNumber > 0)
    {

/*        Find remainder*/

        int rem = columnNumber % 26;

/*        If remainder is 0, then a
        'Z' must be there in output*/

        if (rem == 0)
        {
            columnName += "Z";
            columnNumber = (columnNumber / 26) - 1;
        }

/*        If remainder is non-zero*/

        else
        {
            columnName += (char)((rem - 1) + 'A');
            columnNumber = columnNumber / 26;
        }
    }

/*    Reverse the string and Print result*/

    columnName = reverse(columnName);
    Console.WriteLine(columnName.ToString());
}

/*Driver code*/

public static void Main(String[] args)
{
    printString(26);
    printString(51);
    printString(52);
    printString(80);
    printString(676);
    printString(702);
    printString(705);
}
}

using System;
class GFG{
static void printString(int n)
{
  int []arr = new int[10000];
  int i = 0;

/*  Step 1: Converting to
  number assuming 0 in
  number system*/

  while (n > 0)
  {
    arr[i] = n % 26;
    n = n / 26;
    i++;
  }

/*  Step 2: Getting rid of 0,
  as 0 is not part of number
  system*/

  for(int j = 0; j < i - 1; j++)
  {
    if (arr[j] <= 0)
    {
      arr[j] += 26;
      arr[j + 1] = arr[j + 1] - 1;
    }
  }
  for(int j = i; j >= 0; j--)
  {
    if (arr[j] > 0)
      Console.Write((char)('A' +
                     arr[j] - 1));
  }
  Console.WriteLine();
}

/*Driver code*/

public static void Main(String[] args)
{
  printString(26);
  printString(51);
  printString(52);
  printString(80);
  printString(676);
  printString(702);
  printString(705);
}
}

/*C# program to find angle between
hour and minute hands*/

using System;
class GFG {

/*    Function to calculate the angle*/

    static int calcAngle(double h, double m)
    {

/*        validate the input*/

        if (h < 0 || m < 0 ||
            h > 12 || m > 60)
            Console.Write("Wrong input");
        if (h == 12)
            h = 0;
       if (m == 60)
       {
        m = 0;
        h += 1;
        if(h>12)
          h = h-12;
       }

/*        Calculate the angles moved by hour and
        minute hands with reference to 12:00*/

        int hour_angle = (int)(0.5 * (h * 60 + m));
        int minute_angle = (int)(6 * m);

/*        Find the difference between two angles*/

        int angle = Math.Abs(hour_angle - minute_angle);

/*        smaller angle of two possible angles*/

        angle = Math.Min(360 - angle, angle);
        return angle;
    }

/*    Driver code*/

    public static void Main ()
    {
        Console.WriteLine(calcAngle(9, 60));
        Console.Write(calcAngle(3, 30));
    }
}

/*C# program to check if a given
instance of 8 puzzle is solvable or not*/

using System;
class GFG
{

/*A utility function to count
inversions in given array 'arr[]'*/

static int getInvCount(int[,] arr)
{
    int inv_count = 0;
    for (int i = 0; i < 3 - 1; i++)
        for (int j = i + 1; j < 3; j++)

/*            Value 0 is used for empty space*/

            if (arr[j, i] > 0 && arr[j, i] > arr[i, j])
                inv_count++;
    return inv_count;
}

/*This function returns true
if given 8 puzzle is solvable.*/

static bool isSolvable(int[,] puzzle)
{

/*    Count inversions in given 8 puzzle*/

    int invCount = getInvCount(puzzle);

/*    return true if inversion count is even.*/

    return (invCount % 2 == 0);
}

/* Driver code */

static void Main()
{
    int[,] puzzle = new int[3,3]{{1, 8, 2},
{0, 4, 3}, 
                            {7, 6, 5}};
    if(isSolvable(puzzle))
        Console.WriteLine("Solvable");
    else
       Console.WriteLine("Not Solvable");
}
}

