/*C# code to Count Distinct
Non-Negative Integer Pairs
(x, y) that Satisfy the
inequality x*x + y*y < n*/

using System;
class GFG {

/*    This function counts number
    of pairs (x, y) that satisfy
    the inequality x*x + y*y < n.*/

    static int countSolutions(int n)
    {
        int res = 0;
        for (int x = 0; x*x < n; x++)
            for (int y = 0; x*x + y*y < n; y++)
                res++;
        return res;
    }

/*    Driver program*/

    public static void Main()
    {
        Console.WriteLine( "Total Number of "
          + "distinct Non-Negative pairs is "
                        + countSolutions(6));
    }
}

/*An efficient C# program to
find different (x, y) pairs
that satisfy x*x + y*y < n.*/

using System;
class GFG {

/*    This function counts number
    of pairs (x, y) that satisfy
    the inequality x*x + y*y < n.*/

    static int countSolutions(int n)
    {
        int x = 0, yCount, res = 0;

/*        Find the count of different
        y values for x = 0.*/

        for (yCount = 0; yCount * yCount < n;
                                   yCount++) ;

/*        One by one increase value of x,
        and find yCount forcurrent x. If
        yCount becomes 0, then we have
        reached maximum possible value
        of x.*/

        while (yCount != 0)
        {

/*            Add yCount (count of different
            possible values of y for
            current x) to result*/

            res += yCount;

/*            Increment x*/

            x++;

/*            Update yCount for current x.
            Keep reducing yCount while the
            inequality is not satisfied.*/

            while (yCount != 0 && (x * x +
                            (yCount - 1) *
                         (yCount - 1) >= n))
            yCount--;
        }
        return res;
    }

/*    Driver program*/

    public static void Main()
    {
        Console.WriteLine( "Total Number of "
          + "distinct Non-Negative pairs is "
                       + countSolutions(6)) ;
    }
}

/*C# program for implementation
of Bisection Method for
solving equations*/

using System;
class GFG {
    static int MAX_ITER = 1000000;

/*    An example function whose
    solution is determined using
    Bisection Method. The function
    is x^3 - x^2 + 2*/

    static double func(double x)
    {
        return (x * x * x - x * x + 2);
    }

/*    Prints root of func(x)
    in interval [a, b]*/

    static void regulaFalsi(double a, double b)
    {
        if (func(a) * func(b) >= 0)
        {
            Console.WriteLine("You have not assumed right a and b");
        }

/*        Initialize result*/

        double c = a;
        for (int i = 0; i < MAX_ITER; i++)
        {

/*            Find the point that touches x axis*/

            c = (a * func(b) - b * func(a))
                / (func(b) - func(a));

/*            Check if the above found point is root*/

            if (func(c) == 0)
                break;

/*            Decide the side to repeat the steps*/

            else if (func(c) * func(a) < 0)
                b = c;
            else
                a = c;
        }
        Console.WriteLine("The value of root is : " + (int)c);
    }

/*    Driver program*/

    public static void Main(String []args)
    {

/*        Initial values assumed*/

        double a = -200, b = 300;
        regulaFalsi(a, b);
    }
}

/*C# program for implementation of
Newton Raphson Method for solving
equations*/

using System;
class GFG {
    static double EPSILON = 0.001;

/*    An example function whose solution
    is determined using Bisection Method.
    The function is x^3 - x^2 + 2*/

    static double func(double x)
    {
        return x * x * x - x * x + 2;
    }

/*    Derivative of the above function
    which is 3*x^x - 2*x*/

    static double derivFunc(double x)
    {
        return 3 * x * x - 2 * x;
    }

/*    Function to find the root*/

    static void newtonRaphson(double x)
    {
        double h = func(x) / derivFunc(x);
        while (Math.Abs(h) >= EPSILON)
        {
            h = func(x) / derivFunc(x);

/*            x(i+1) = x(i) - f(x) / f'(x)*/

            x = x - h;
        }
        Console.Write("The value of the"
                    + " root is : "
                    + Math.Round(x * 100.0) / 100.0);
    }

/*    Driver code*/

    public static void Main ()
    {

/*        Initial values assumed*/

        double x0 = -20;
        newtonRaphson(x0);
    }
}

/*C# code to find the element
that occur only once*/

using System;
class GFG {

/*    Method to find the element
    that occur only once*/

    static int getSingle(int[] arr, int n)
    {
        int ones = 0, twos = 0;
        int common_bit_mask;
        for (int i = 0; i < n; i++) {

/*            "one & arr[i]" gives the bits
            that are there in both 'ones'
            and new element from arr[].
            We add these bits to 'twos'
            using bitwise OR*/

            twos = twos | (ones & arr[i]);

/*            "one & arr[i]" gives the bits
            that are there in both 'ones'
            and new element from arr[].
            We add these bits to 'twos'
            using bitwise OR*/

            ones = ones ^ arr[i];

/*            The common bits are those bits
            which appear third time So these
            bits should not be there in both
            'ones' and 'twos'. common_bit_mask
            contains all these bits as 0,
            so that the bits can be removed
            from 'ones' and 'twos'*/

            common_bit_mask = ~(ones & twos);

/*            Remove common bits (the bits that
            appear third time) from 'ones'*/

            ones &= common_bit_mask;

/*            Remove common bits (the bits that
            appear third time) from 'twos'*/

            twos &= common_bit_mask;
        }
        return ones;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 3, 3, 2, 3 };
        int n = arr.Length;
        Console.WriteLine("The element with single"
                          + "occurrence is " + getSingle(arr, n));
    }
}

/*C# code to find the element
that occur only once*/

using System;
class GFG {
    static int INT_SIZE = 32;
    static int getSingle(int[] arr, int n)
    {

/*        Initialize result*/


        int result = 0;
        int x, sum;

/*        Iterate through every bit*/

        for (int i = 0; i < INT_SIZE; i++) {

/*            Find sum of set bits at ith
            position in all array elements*/

            sum = 0;
            x = (1 << i);
            for (int j = 0; j < n; j++) {
                if ((arr[j] & x) == 0)
                    sum++;
            }

/*            The bits with sum not multiple
            of 3, are the bits of element
            with single occurrence.*/

            if ((sum % 3) != 0)
                result |= x;
        }
        return result;
    }

/*    Driver Code*/

    public static void Main()
    {
        int[] arr = { 12, 1, 12, 3, 12, 1,
                      1, 2, 3, 2, 2, 3, 7 };
        int n = arr.Length;
        Console.WriteLine("The element with single "
                          + "occurrence is " + getSingle(arr, n));
    }
}

