to a given number*/

using System;
class GFG {
    static int addOne(int x)
    {
        int m = 1;

/*        Flip all the set bits
        until we find a 0*/

        while( (int)(x & m) == 1)
        {
            x = x ^ m;
            m <<= 1;
        }

/*        flip the rightmost 0 bit*/

        x = x ^ m;
        return x;
    }

