/*C# program to check
if given number is
power of 4 or not*/

using System;
class GFG{
static double logn(int n,
                   int r)
{
  return Math.Log(n) /
         Math.Log(r);
}
static bool isPowerOfFour(int n)
{

/*  0 is not considered
  as a power of 4*/

  if (n == 0)
    return false;
  return Math.Floor(logn(n, 4)) ==
         Math.Ceiling(logn(n, 4));
}

