/*C# program for the above approach*/

using System;
class GFG{

/*absbit32 function*/

public static int absbit32(int x, int y)
{
    int sub = x - y;
    int mask = (sub >> 31);
    return (sub ^ mask) - mask;        
}

/*max function*/

public static int max(int x, int y)
{
    int abs = absbit32(x, y);        
    return (x + y + abs) / 2;        
}

/*min function*/

public static int min(int x, int y)
{
    int abs = absbit32(x, y);        
    return (x + y - abs) / 2;
}

/*Driver code*/
public static void Main(String []args)
{

Console.WriteLine(max(2, 3)); 
Console.WriteLine(max(2, -3)); 
Console.WriteLine(max(-2, -3)); 
Console.WriteLine(min(2, 3)); 
Console.WriteLine(min(2, -3));
Console.WriteLine(min(-2, -3)); 
}
}

/*C# program for above approach*/

using System;
class GFG{

/*This function sets the values of
*x and *y to non-repeating elements
in an array arr[] of size n*/

static void UniqueNumbers2(int[] arr, int n)
{
    int sum = 0;
    for(int i = 0; i < n; i++)
    {

/*        Xor  all the elements of the array
        all the elements occuring twice will
        cancel out each other remaining
        two unnique numbers will be xored*/

        sum = (sum ^ arr[i]);
    }

/*    Bitwise & the sum with it's 2's Complement
    Bitwise & will give us the sum containing
    only the rightmost set bit*/

    sum = (sum & -sum);

/*    sum1 and sum2 will contains 2 unique
    elements elements initialized with 0 box
    number xored with 0 is number itself*/

    int sum1 = 0;
    int sum2 = 0;

/*    Traversing the array again*/

    for(int i = 0; i < arr.Length; i++)
    {

/*        Bitwise & the arr[i] with the sum
        Two possibilities either result == 0
        or result > 0*/

        if ((arr[i] & sum) > 0)
        {

/*            If result > 0 then arr[i] xored
            with the sum1*/

            sum1 = (sum1 ^ arr[i]);
        }
        else
        {

/*            If result == 0 then arr[i]
            xored with sum2*/

            sum2 = (sum2 ^ arr[i]);
        }
    }

/*    Print the the two unique numbers*/

    Console.WriteLine("The non-repeating " +
                      "elements are " + sum1 +
                      " and " + sum2);
}

/*Driver Code*/

static public void Main()
{
    int[] arr = { 2, 3, 7, 9, 11, 2, 3, 11 };
    int n = arr.Length;
    UniqueNumbers2(arr, n);
}
}

/*C# program to find the element
occurring odd number of times*/

using System;
class GFG
{

/*    Function to find the element
    occurring odd number of times*/

    static int getOddOccurrence(int []arr, int arr_size)
    {
        for (int i = 0; i < arr_size; i++) {
            int count = 0;
            for (int j = 0; j < arr_size; j++) {
                if (arr[i] == arr[j])
                    count++;
            }
            if (count % 2 != 0)
                return arr[i];
        }
        return -1;
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = { 2, 3, 5, 4, 5, 2, 4, 3, 5, 2, 4, 4, 2 };
        int n = arr.Length;

/*        Function calling*/

        Console.Write(getOddOccurrence(arr, n));
    }
}

/*C# program to find the element occurring odd
number of times*/

using System;
using System.Collections.Generic;
public class OddOccurrence
{

/*    function to find the element occurring odd
    number of times*/

    static int getOddOccurrence(int []arr, int n)
    {
        Dictionary<int,int> hmap = new Dictionary<int,int>();

/*        Putting all elements into the HashMap*/

        for(int i = 0; i < n; i++)
        {
            if(hmap.ContainsKey(arr[i]))
            {
                int val = hmap[arr[i]];

/*                If array element is already present then
                increase the count of that element.*/

                hmap.Remove(arr[i]);
                hmap.Add(arr[i], val + 1);
            }
            else

/*                if array element is not present then put
                element into the HashMap and initialize
                the count to one.*/

                hmap.Add(arr[i], 1);
        }

/*        Checking for odd occurrence of each element present
        in the HashMap*/

        foreach(KeyValuePair<int, int> entry in hmap)
        {
            if(entry.Value % 2 != 0)
            {
                return entry.Key;
            }
        }
        return -1;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = new int[]{2, 3, 5, 4, 5, 2, 4, 3, 5, 2, 4, 4, 2};
        int n = arr.Length;
        Console.WriteLine(getOddOccurrence(arr, n));
    }
}

