class GFG
{

/*    Finds next power of two
    for n. If n itself is a
    power of two then returns n*/

    static int nextPowerOf2(int n)
    {
        n--;
        n |= n >> 1;
        n |= n >> 2;
        n |= n >> 4;
        n |= n >> 8;
        n |= n >> 16;
        n++;
        return n;
    }

