using System;
class GFG {

/*Function to swap the numbers.*/

    static void swap(int a, int b)
    {

/*        same as a = a + b*/

        a = (a & b) + (a | b);

/*        same as b = a - b*/

        b = a + (~b) + 1;

/*        same as a = a - b*/

        a = a + (~b) + 1;
        Console.Write("After swapping: a = " + a
                      + ", b = " + b);
    }

