/*C# program to find maximum
element*/

using System;

class GFG
{
    static int findMaximum(int []arr, int low, int high)
    {

/* Base Case: Only one element is
        present in arr[low..high]*/

    if (low == high)
        return arr[low];

/* If there are two elements and
        first is greater then the first
        element is maximum */

    if ((high == low + 1) && arr[low] >= arr[high])
        return arr[low];

/* If there are two elements and
        second is greater then the second
        element is maximum */

    if ((high == low + 1) && arr[low] < arr[high])
        return arr[high];
    int mid = (low + high)/2;

/* If we reach a point where arr[mid]
        is greater than both of its adjacent
        elements arr[mid-1] and arr[mid+1],
        then arr[mid] is the maximum element*/

    if ( arr[mid] > arr[mid + 1] && arr[mid] > arr[mid - 1])
        return arr[mid];

/* If arr[mid] is greater than the next
        element and smaller than the previous
        element then maximum lies on left side
        of mid */

    if (arr[mid] > arr[mid + 1] && arr[mid] < arr[mid - 1])
        return findMaximum(arr, low, mid-1);

/*when arr[mid] is greater than arr[mid-1] and smaller than arr[mid+1]*/

    else
        return findMaximum(arr, mid + 1, high);
    }

/*    main function*/

    public static void Main()
    {
        int []arr = {1, 3, 50, 10, 9, 7, 6};
        int n = arr.Length;
        Console.Write("The maximum element is "+
                            findMaximum(arr, 0, n-1));
    }
}

using System;

class GFG {

    static void constructLowerArray(int []arr,
                    int []countSmaller, int n)
    {
        int i, j;

/*        initialize all the counts in
        countSmaller array as 0*/

        for (i = 0; i < n; i++)
            countSmaller[i] = 0;

        for (i = 0; i < n; i++)
        {
            for (j = i + 1; j < n; j++)
            {
                if (arr[j] < arr[i])
                    countSmaller[i]++;
            }
        }
    }

/* Utility function that prints out
    an array on a line */

