                            2, 20, 6, 1, 0, 2};
        int n = arr.Length;
        int []low = new int[n];

        constructLowerArray(arr, low, n);
        printArray(low, n);
    }
}

/*C# program to find the smallest
positive missing number*/

using System;

class main {

/*    Utility function that puts all
    non-positive (0 and negative)
    numbers on left side of arr[]
    and return count of such numbers*/

    static int segregate(int[] arr, int size)
    {
        int j = 0, i;
        for (i = 0; i < size; i++) {
            if (arr[i] <= 0) {
                int temp;
                temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;

/*                increment count of non-positive
                integers*/

                j++;
            }
        }

        return j;
    }

/*    Find the smallest positive missing
    number in an array that contains
    all positive integers*/

    static int findMissingPositive(int[] arr, int size)
    {
        int i;

/*        Mark arr[i] as visited by making
        arr[arr[i] - 1] negative. Note that
        1 is subtracted as index start from
        0 and positive numbers start from 1*/

        for (i = 0; i < size; i++) {
            if (Math.Abs(arr[i]) - 1 < size && arr[ Math.Abs(arr[i]) - 1] > 0)
                arr[ Math.Abs(arr[i]) - 1] = -arr[ Math.Abs(arr[i]) - 1];
        }

/*        Return the first index value at
        which is positive*/

        for (i = 0; i < size; i++)
            if (arr[i] > 0)
                return i + 1;

/*        1 is added becuase indexes
        start from 0*/

        return size + 1;
    }

/*    Find the smallest positive
    missing number in array that
    contains both positive and
    negative integers*/

    static int findMissing(int[] arr, int size)
    {

/*        First separate positive and
        negative numbers*/

        int shift = segregate(arr, size);
        int[] arr2 = new int[size - shift];
        int j = 0;

        for (int i = shift; i < size; i++) {
            arr2[j] = arr[i];
            j++;
        }

/*        Shift the array and call
        findMissingPositive for
        positive part*/

        return findMissingPositive(arr2, j);
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 0, 10, 2, -10, -20 };
        int arr_size = arr.Length;
        int missing = findMissing(arr, arr_size);
        Console.WriteLine("The smallest positive missing number is " + missing);
    }
}

/*C# program for the above approach*/

using System;
public class GFG{

/*  Function for finding the first
  missing positive number*/

  static int firstMissingPositive(int[] arr, int n)
  {

/*    Check if 1 is present in array or not*/

    for(int i = 0; i < n; i++)
    {

/*      Loop to check boundary
      condition and for swapping*/

      while (arr[i] >= 1 && arr[i] <= n
             && arr[i] != arr[arr[i] - 1]) {

        int temp = arr[arr[i] - 1];
        arr[arr[i] - 1] = arr[i];
        arr[i] = temp;
      }
    }

/*    Finding which index has value less than n*/

    for(int i = 0; i < n; i++)
      if (arr[i] != i + 1)
        return (i + 1);

/*    If array has values from 1 to n*/

    return (n + 1);
  }

/*  Driver Code*/


  static public void Main ()
  {

    int[] arr = {2, 3, -7, 6, 8, 1, -10, 15 };
    int n = arr.Length;
    int ans = firstMissingPositive(arr, n);

    Console.WriteLine(ans);
  }
}

/*C# program to find the maximum repeating
number*/

using System;

class GFG {

/*    Returns maximum repeating element
    in arr[0..n-1].
    The array elements are in range
    from 0 to k-1*/

    static int maxRepeating(int []arr,
                             int n, int k)
    {

/*        Iterate though input array, for
        every element arr[i], increment
        arr[arr[i]%k] by k*/

        for (int i = 0; i< n; i++)
            arr[(arr[i]%k)] += k;

/*        Find index of the maximum
        repeating element*/

        int max = arr[0], result = 0;

        for (int i = 1; i < n; i++)
        {
            if (arr[i] > max)
            {
                max = arr[i];
                result = i;
            }
        }

/*        Return index of the
        maximum element*/

        return result;
    }

/*Driver function to check for
     above function*/

    public static void Main ()
    {

        int []arr = {2, 3, 3, 5, 3, 4, 1, 7};
        int n = arr.Length;
        int k=8;

        Console.Write("Maximum repeating "
                          + "element is: "
                  + maxRepeating(arr,n,k));
    }
}

/*C# program for Maximum Sum Path in
Two Arrays*/

using System;

class GFG {

/*    Utility function to find maximum
    of two integers*/

    static int max(int x, int y) { return (x > y) ? x : y; }

/*    This function returns the sum of
    elements on maximum path from
    beginning to end*/

    static int maxPathSum(int[] ar1, int[] ar2, int m,
                          int n)
    {

/*        initialize indexes for ar1[]
        and ar2[]*/

        int i = 0, j = 0;

/*        Initialize result and current
        sum through ar1[] and ar2[].*/

        int result = 0, sum1 = 0, sum2 = 0;

/*        Below 3 loops are similar to
        merge in merge sort*/

        while (i < m && j < n) {

/*            Add elements of ar1[] to sum1*/

            if (ar1[i] < ar2[j])
                sum1 += ar1[i++];

/*            Add elements of ar2[] to sum2*/

            else if (ar1[i] > ar2[j])
                sum2 += ar2[j++];

/*            we reached a common point*/

            else {

/*                Take the maximum of two sums and add to
                result
                Also add the common element of array,
                once*/

                result += max(sum1, sum2) + ar1[i];

/*                Update sum1 and sum2 for elements after
                this intersection point*/

                sum1 = 0;
                sum2 = 0;

/*                update i and j to move to next element of
                each array*/

                i++;
                j++;
            }
        }

/*        Add remaining elements of ar1[]*/

        while (i < m)
            sum1 += ar1[i++];

/*        Add remaining elements of ar2[]*/

        while (j < n)
            sum2 += ar2[j++];

/*        Add maximum of two sums of
        remaining elements*/

        result += max(sum1, sum2);

        return result;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] ar1 = { 2, 3, 7, 10, 12, 15, 30, 34 };
        int[] ar2 = { 1, 5, 7, 8, 10, 15, 16, 19 };
        int m = ar1.Length;
        int n = ar2.Length;

/*        Function call*/

        Console.Write("Maximum sum path is :"
                      + maxPathSum(ar1, ar2, m, n));
    }
}

/*Simple C# program to find
smallest greater element in
whole array for every element.*/

using System;

class GFG
{
static void smallestGreater(int []arr,
                            int n)
{
    for (int i = 0; i < n; i++)
    {

/*        Find the closest greater
        element for arr[j] in
        the entire array.*/

        int diff = int.MaxValue;
        int closest = -1;
        for (int j = 0; j < n; j++)
        {
            if (arr[i] < arr[j] &&
                arr[j] - arr[i] < diff)
            {
                diff = arr[j] - arr[i];
                closest = j;        
            }
        }

/*        Check if arr[i] is largest*/

        if(closest == -1)
        Console.Write( "_ " );
        else
        Console.Write(arr[closest] + " ");
    }
}

/*Driver code*/

public static void Main()
{
    int []ar = {6, 3, 9, 8, 10,
                2, 1, 15, 7};
    int n = ar.Length;
    smallestGreater(ar, n);
}
}

/*Efficient C# program to
find smallest greater element
in whole array for every element.*/

using System;
using System.Collections.Generic;
class GFG{

static void smallestGreater(int[] arr,
                                int n)
{
  HashSet<int> s = new HashSet<int>();
  for (int i = 0; i < n; i++)
  {
    s.Add(arr[i]);
  }

  int[] newAr = new int[s.Count];
  int j = 0;
  foreach(int p in s)
  {
    newAr[j] = p;
    j++;
  }

  Array.Sort(newAr);

  for (int i = 0; i < n; i++)
  {
    int temp = lowerBound(newAr, 0,
                          newAr.GetLength(0),
                          arr[i]);
    if (temp < n)
      Console.Write(newAr[temp] + " ");
    else
      Console.Write("_ ");
  }
}

/*lowerbound function*/

static int lowerBound(int[] array, int low,
                      int high, int element)
{
  while (low < high)
  {
    int middle = low + (high -
                 low) / 2;

    if (element > array[middle])
    {
      low = middle + 1;
    }
    else
    {
      high = middle;
    }
  }
  return low + 1;
}

/*Driver code*/

public static void Main(String[] args)
{
  int[] ar = {6, 3, 9, 8,
              10, 2, 1, 15, 7};
  int n = ar.Length;
  smallestGreater(ar, n);
}
}

/*C# program for online algorithm for 
palindrome checking */

using System;

class GFG
{

/*d is the number of characters  
in input alphabet */

public const int d = 256;

/*q is a prime number used for 
evaluating Rabin Karp's Rolling hash */

public const int q = 103;

public static void checkPalindromes(string str)
{

/*    Length of input string */

    int N = str.Length;

/*    A single character is always
    a palindrome */

    Console.WriteLine(str[0] + " Yes");

/*    Return if string has only 
    one character */

    if (N == 1)
    {
        return;
    }

/*    Initialize first half reverse and second 
    half for as firstr and second characters */

    int firstr = str[0] % q;
    int second = str[1] % q;

    int h = 1, i, j;

/*    Now check for palindromes from 
    second character onward */

    for (i = 1; i < N; i++)
    {

/*        If the hash values of 'firstr' 
        and 'second' match, then only 
        check individual characters */

        if (firstr == second)
        {

/* Check if str[0..i] is palindrome 
            using simple character by character 
            match */

            for (j = 0; j < i / 2; j++)
            {
                if (str[j] != str[i - j])
                {
                    break;
                }
            }
            Console.WriteLine((j == i / 2) ? str[i] + 
                             " Yes": str[i] + " No");
        }
        else
        {
            Console.WriteLine(str[i] + " No");
        }

/*        Calculate hash values for next iteration. 
        Don't calculate hash for next characters 
        if this is the last character of string */

        if (i != N - 1)
        {

/*            If i is even (next i is odd) */

            if (i % 2 == 0)
            {

/*                Add next character after first 
                half at beginning of 'firstr' */

                h = (h * d) % q;
                firstr = (firstr + h * str[i / 2]) % q;

/*                Add next character after second 
                half at the end of second half. */

                second = (second * d + str[i + 1]) % q;
            }
            else
            {

/*                If next i is odd (next i is even) 
                then we need not to change firstr, 
                we need to remove first character 
                of second and append a character 
                to it. */

                second = (d * (second + q - str[(i + 1) / 2] *
                                   h) % q + str[i + 1]) % q;
            }
        }
    }
}

/*Driver Code*/

public static void Main(string[] args)
{
    string txt = "aabaacaabaa";
    checkPalindromes(txt);
}
}

/*C# to find positions of zeroes flipping which
produces maximum number of consecutive 1's*/

using System;

class Test
{
    static int []arr = new int[]{1, 0, 0, 1, 1,
                                0, 1, 0, 1, 1};

/*    m is maximum of number zeroes allowed to flip*/

    static void findZeroes(int m)
    {

/*        Left and right indexes of current window*/

        int wL = 0, wR = 0;

/*        Left index and size of the widest window*/

        int bestL = 0, bestWindow = 0;

/*        Count of zeroes in current window*/

        int zeroCount = 0;

/*        While right boundary of current
        window doesn't cross right end*/

        while (wR < arr.Length)
        {

/*            If zero count of current window is less
            than m, widen the window toward right*/

            if (zeroCount <= m)
            {
                if (arr[wR] == 0)
                zeroCount++;
                wR++;
            }

/*            If zero count of current window is more than m,
            reduce the window from left*/

            if (zeroCount > m)
            {
                if (arr[wL] == 0)
                zeroCount--;
                wL++;
            }

/*            Update widest window if this window size is more*/

            if ((wR-wL > bestWindow) && (zeroCount<=m))
            {
                bestWindow = wR-wL;
                bestL = wL;
            }
        }

/*        Print positions of zeroes in the widest window*/

        for (int i = 0; i < bestWindow; i++)
        {
            if (arr[bestL + i] == 0)
            Console.Write(bestL + i + " ");
        }
    }

/*    Driver method to test the above function*/

    public static void Main(String[] args)
    {
        int m = 2;
        Console.Write("Indexes of zeroes to be flipped are ");
        findZeroes(m);
    }
}

/*C# program to count number of
strictly increasing subarrays*/

using System;

class Test
{
    static int []arr = new int[]{1, 2, 2, 4};

    static int countIncreasing(int n)
    {

/*        Initialize count of subarrays as 0*/

        int cnt = 0;

/*        Pick starting point*/

        for (int i = 0; i < n; i++)
        {

/*            Pick ending point*/

            for (int j = i + 1; j < n; j++)
            {
                if (arr[j] > arr[j - 1])
                    cnt++;

/*                If subarray arr[i..j] is not strictly
                increasing, then subarrays after it ,
                i.e.,  arr[i..j+1], arr[i..j+2], ....
                cannot be strictly increasing*/

                else
                    break;
            }
        }
        return cnt;
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        Console.Write("Count of strictly increasing" +
            "subarrays is " + countIncreasing(arr.Length));
    }
}

