/*C# program to count number of strictly
increasing subarrays*/

using System;

class GFG {

    static int []arr = new int[]{1, 2, 2, 4};

    static int countIncreasing(int n)
    {

/*Initialize result*/

int cnt = 0;

/*        Initialize length of current
        increasing subarray*/

        int len = 1;

/*        Traverse through the array*/

        for (int i = 0; i < n-1; ++i)
        {

/*            If arr[i+1] is greater than
            arr[i], then increment length*/

            if (arr[i + 1] > arr[i])
                len++;

/*            Else Update count and reset
            length*/

            else
            {
                cnt += (((len - 1) * len) / 2);
                len = 1;
            }
        }

/*        If last length is more than 1*/

        if (len > 1)
            cnt += (((len - 1) * len) / 2);

        return cnt;
    }

/*    Driver method to test the
    above function*/

    public static void Main()
    {
        Console.WriteLine("Count of strictly "
                  + "increasing subarrays is "
               + countIncreasing(arr.Length));
    }
}

/*C# to find maximum group difference*/

using System;

public class GFG {

/*    utility function for array sum*/

    static long arraySum(int []arr, int n)
    {
        long sum = 0;
        for (int i = 0; i < n; i++)
            sum = sum + arr[i];

        return sum;
    }

/*    function for finding maximum group
    difference of array*/

    static long maxDiff (int []arr, int n, int k)
    {

/*        sort the array*/

        Array.Sort(arr);

/*        find array sum*/

        long arraysum = arraySum(arr, n);

/*        difference for k-smallest
        diff1 = (arraysum-k_smallest)-k_smallest*/

        long diff1 = Math.Abs(arraysum -
                             2 * arraySum(arr, k));

/*        reverse array for finding sum of
        1st k-largest*/

        Array.Reverse(arr);

/*        difference for k-largest
        diff2 = (arraysum-k_largest)-k_largest*/

        long diff2 = Math.Abs(arraysum -
                            2 * arraySum(arr, k));

/*        return maximum difference value*/

        return(Math.Max(diff1, diff2));

    }

/*    Driver program*/

    static public void Main ()
    {
        int []arr = {1, 7, 4, 8, -1, 5, 2, 1};
        int n = arr.Length;
        int k = 3;

        Console.WriteLine("Maximum Difference = "
                           + maxDiff(arr, n, k));
    }
}

/*C# program to find minimum number
of elements needs to add to the
array so that its median equals x.*/

using System;

class GFG
{

/*Returns count of elements to be
added to make median x. This function
assumes that a[] has enough extra space.*/

static int minNumber(int []a, int n, int x)
{

/*    to sort the array in increasing order.*/

    Array.Sort(a);

    int k;
    for (k = 0; a[(n) / 2] != x; k++)
    {
        a[n++] = x;
        Array.Sort(a);
    }
    return k;
}

/*Driver code*/

public static void Main(String[] args)
{
    int x = 10;
    int []a = { 10, 20, 30 };
    int n = 3;
    Console.WriteLine(minNumber(a, n-1, x));
}
}

/*C# program to find minimum
number of elements to add
so that its median equals x.*/

using System;

class GFG
{
public static int minNumber(int []a,
                            int n,
                            int x)
{
    int l = 0, h = 0, e = 0;
    for (int i = 0; i < n; i++)
    {

/*        no. of elements
        equals to x,
        that is, e.*/

        if (a[i] == x)
            e++;

/*        no. of elements
        greater than x,
        that is, h.*/

        else if (a[i] > x)
            h++;

/*        no. of elements smaller
        than x, that is, l.*/

        else if (a[i] < x)
            l++;
    }

    int ans = 0;
    if (l > h)
        ans = l - h;
    else if (l < h)
        ans = h - l - 1;

/*    subtract the no.
    of elements that
    are equal to x.*/

    return ans + 1 - e;
}

/*Driver Code*/

public static void Main()
{
    int x = 10;
    int []a = {10, 20, 30};
    int n = a.Length;
    Console.WriteLine(
                minNumber(a, n, x));
}
}

/*C# Program to solve range query on array
whose each element is XOR of index value
and previous element.*/

using System;

class GFG {

/*    function return derived formula value.*/

    static int fun(int x)
    {
        int y = (x / 4) * 4;

/*        finding xor value of range [y...x]*/

        int ans = 0;
        for (int i = y; i <= x; i++)
            ans ^= i;

        return ans;
    }

/*    function to solve query for l and r.*/

    static int query(int x)
    {

/*        if l or r is 0.*/

        if (x == 0)
            return 0;

        int k = (x + 1) / 2;

/*        finding x is divisible by 2 or not.*/

        return ((x %= 2)!=0) ? 2 * fun(k) :
                   ((fun(k - 1) * 2) ^ (k & 1));
    }

    static void allQueries(int q, int []l, int []r)
    {
        for (int i = 0; i < q; i++)
            Console.WriteLine((query(r[i])
                              ^ query(l[i] - 1))) ;
    }

/*    Driven Program*/

    public static void Main ()
    {
        int q = 3;
        int []l = { 2, 2, 5 };
        int []r = { 4, 8, 9 };

        allQueries(q, l, r);

    }
}

/*C# program to check whether
a subarray is in mountain
form or not*/

using System;

class GFG
{

/*    Utility method to construct
    left and right array*/

    static void preprocess(int []arr, int N,
                           int []left, int []right)
    {

/*        initialize first left
        index as that index only*/

        left[0] = 0;
        int lastIncr = 0;

        for (int i = 1; i < N; i++)
        {

/*            if current value is
            greater than previous,
            update last increasing*/

            if (arr[i] > arr[i - 1])
                    lastIncr = i;
            left[i] = lastIncr;
        }

/*        initialize last right
        index as that index only*/

        right[N - 1] = N - 1;
        int firstDecr = N - 1;

        for (int i = N - 2; i >= 0; i--)
        {

/*            if current value is
            greater than next,
            update first decreasing*/

            if (arr[i] > arr[i + 1])
                    firstDecr = i;
            right[i] = firstDecr;
        }
    }

/*    method returns true if
    arr[L..R] is in mountain form*/

    static bool isSubarrayMountainForm(int []arr, int []left,
                                       int []right, int L, int R)
    {

/*        return true only if right at
        starting range is greater
        than left at ending range*/

        return (right[L] >= left[R]);
    }

/*    Driver Code*/

    static public void Main ()
    {
        int []arr = {2, 3, 2, 4,
                     4, 6, 3, 2};
        int N = arr.Length;
        int []left = new int[N];
        int []right = new int[N];
        preprocess(arr, N, left, right);

        int L = 0;
        int R = 2;

        if (isSubarrayMountainForm(arr, left,
                                   right, L, R))
            Console.WriteLine("Subarray is in " +
                                "mountain form");
        else
            Console.WriteLine("Subarray is not " +
                              "in mountain form");

        L = 1;
        R = 3;

        if (isSubarrayMountainForm(arr, left,
                                   right, L, R))
            Console.WriteLine("Subarray is in " +
                                "mountain form");
        else
            Console.WriteLine("Subarray is not " +
                              "in mountain form");
    }
}

/*Program to find sum between two
indexes when there is no update.*/

using System;

class GFG {
    public static void preCompute(int[] arr, int n,
                                  int[] pre)
    {
        pre[0] = arr[0];
        for (int i = 1; i < n; i++)
            pre[i] = arr[i] + pre[i - 1];
    }

/*    Returns sum of elements in
    arr[i..j]
    It is assumed that i <= j*/

    public static int rangeSum(int i, int j, int[] pre)
    {
        if (i == 0)
            return pre[j];

        return pre[j] - pre[i - 1];
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 1, 2, 3, 4, 5 };
        int n = arr.Length;

        int[] pre = new int[n];

/*        Function call*/

        preCompute(arr, n, pre);
        Console.WriteLine(rangeSum(1, 3, pre));
        Console.WriteLine(rangeSum(2, 4, pre));
    }
}

