/*C# program to find floor value
of mean in range l to r*/

using System;

public class GFG {

/*    To find mean of range in l to r*/

    static int findMean(int []arr, int l, int r)
    {

/*        Both sum and count are
        initialize to 0*/

        int sum = 0, count = 0;

/*        To calculate sum and number
        of elements in range l to r*/

        for (int i = l; i <= r; i++) {
            sum += arr[i];
            count++;
        }

/*        Calculate floor value of mean*/

        int mean = (int)Math.Floor((double)sum / count);

/*        Returns mean of array
        in range l to r*/

        return mean;
    }

/*    Driver program to test findMean()*/

    public static void Main()
    {
        int []arr = { 1, 2, 3, 4, 5 };
        Console.WriteLine(findMean(arr, 0, 2));
        Console.WriteLine(findMean(arr, 1, 3));
        Console.WriteLine(findMean(arr, 0, 4));
    }
}

/*C# program to find floor value
of mean in range l to r*/

using System;

public class GFG {
public static readonly int MAX = 1000005;
    static int []prefixSum = new int[MAX];

/*    To calculate prefixSum of array*/

    static void calculatePrefixSum(int []arr, int n)
    {

/*        Calculate prefix sum of array*/

        prefixSum[0] = arr[0];
        for (int i = 1; i < n; i++)
            prefixSum[i] = prefixSum[i - 1] + arr[i];
    }

/*    To return floor of mean
    in range l to r*/

    static int findMean(int l, int r)
    {
        if (l == 0)
           return (int)Math.Floor((double)(prefixSum[r] / (r + 1)));

/*        Sum of elements in range l to
        r is prefixSum[r] - prefixSum[l-1]
        Number of elements in range
        l to r is r - l + 1*/

        return (int)Math.Floor((double)(prefixSum[r] -
                prefixSum[l - 1]) / (r - l + 1));
    }

/*    Driver program to test above functions*/

    public static void Main()
    {
        int []arr = { 1, 2, 3, 4, 5 };
        int n = arr.Length;
        calculatePrefixSum(arr, n);
        Console.WriteLine(findMean(1, 2));
        Console.WriteLine(findMean(1, 3));
        Console.WriteLine(findMean(1, 4));
    }
}

/*Program to find modified
array after executing
m commands/queries*/

using System;

class GFG {

/*    Update function for every command*/

    static void updateQuery(int[] arr, int n, int q,
                            int l, int r, int k)
    {

/*        If q == 0, add 'k' and '-k'
        to 'l-1' and 'r' index*/

        if (q == 0) {
            arr[l - 1] += k;
            arr[r] += -k;
        }

/*        If q == 1, add '-k' and 'k'
        to 'l-1' and 'r' index*/

        else {
            arr[l - 1] += -k;
            arr[r] += k;
        }
        return;
    }

/*    Function to generate final
    array after executing all
    commands*/

    static void generateArray(int[] arr, int n)
    {

/*        Generate final array with
        the help of DP concept*/

        for (int i = 1; i < n; ++i)
            arr[i] += arr[i - 1];
    }

/*    Driver code*/

    public static void Main()
    {
        int n = 5;
        int[] arr = new int[n + 1];
        for (int i = 0; i < arr.Length; i++)
            arr[i] = 0;

        int q = 0, l = 1, r = 3, k = 2;
        updateQuery(arr, n, q, l, r, k);

        q = 1;
        l = 3;
        r = 5;
        k = 3;
        updateQuery(arr, n, q, l, r, k);

        q = 0;
        l = 2;
        r = 5;
        k = 1;
        updateQuery(arr, n, q, l, r, k);

/*        Generate final array*/

        generateArray(arr, n);

/*        Printing the final modified array*/

        for (int i = 0; i < n; ++i)
            Console.Write(arr[i] + " ");
    }
}

/*Product in range Queries in O(N)*/

using System;

class GFG
{

/*    Function to calculate
    Product in the given range.*/

    static int calculateProduct(int []A, int L,    
                                int R, int P)
    {

/*        As our array is 0 based
        as and L and R are given
        as 1 based index.*/

        L = L - 1;
        R = R - 1;

        int ans = 1;
        for (int i = L; i <= R; i++)
        {
            ans = ans * A[i];
            ans = ans % P;
        }

        return ans;
    }

/*    Driver code*/

    static public void Main ()
    {
        int []A = { 1, 2, 3, 4, 5, 6 };
        int P = 229;
        int L = 2, R = 5;
        Console.WriteLine(
            calculateProduct(A, L, R, P));

        L = 1;
        R = 3;
        Console.WriteLine(
            calculateProduct(A, L, R, P));
    }
}

/*C# program to find Product
in range Queries in O(1)*/

using System;

class GFG
{

    static int MAX = 100;
    int []pre_product = new int[MAX];
    int []inverse_product = new int[MAX];

/*    Returns modulo inverse of
    a with respect to m using
    extended Euclid Algorithm
    Assumption: a and m are
    coprimes, i.e., gcd(a, m) = 1*/

    int modInverse(int a, int m)
    {
        int m0 = m, t, q;
        int x0 = 0, x1 = 1;

        if (m == 1)
            return 0;

        while (a > 1)
        {

/*            q is quotient*/

            q = a / m;
            t = m;

/*            m is remainder now, process
            same as Euclid's algo*/

            m = a % m;
            a = t;
            t = x0;
            x0 = x1 - q * x0;
            x1 = t;
        }

/*        Make x1 positive*/

        if (x1 < 0)
            x1 += m0;

        return x1;
    }

/*    calculating pre_product array*/

    void calculate_Pre_Product(int []A,
                               int N,
                               int P)
    {
        pre_product[0] = A[0];

        for (int i = 1; i < N; i++)
        {
            pre_product[i] =
                pre_product[i - 1] *
                               A[i];

            pre_product[i] =
                pre_product[i] % P;
        }
    }

/*    Cacluating inverse_product
    array.*/

    void calculate_inverse_product(int []A,
                                   int N,
                                   int P)
    {
        inverse_product[0] =
                modInverse(pre_product[0], P);

        for (int i = 1; i < N; i++)
            inverse_product[i] =
                modInverse(pre_product[i], P);
    }

/*    Function to calculate Product
    in the given range.*/

    int calculateProduct(int []A, int L,
                         int R, int P)
    {

/*        As our array is 0 based as
        and L and R are given as 1
        based index.*/

        L = L - 1;
        R = R - 1;
        int ans;

        if (L == 0)
            ans = pre_product[R];
        else
            ans = pre_product[R] *
                  inverse_product[L - 1];

        return ans;
    }

/*    Driver code*/

    public static void Main()
    {
        GFG d = new GFG();

/*        Array*/

        int []A = { 1, 2, 3, 4, 5, 6 };

/*        Prime P*/

        int P = 113;

/*        Calculating PreProduct and
        InverseProduct*/

        d.calculate_Pre_Product(A,
                        A.Length, P);

        d.calculate_inverse_product(A,
                        A.Length, P);

/*        Range [L, R] in 1 base index*/

        int L = 2, R = 5;
        Console.WriteLine(
            d.calculateProduct(A, L, R, P));

        L = 1;
        R = 3;
        Console.WriteLine(
            d.calculateProduct(A, L, R, P));
    }
}

/*C# program to answer
queries for count of
primes in given range.*/

using System;

class GFG
{
static int MAX = 10000;

/*prefix[i] is going
to store count of
primes till i (including i).*/

static int[] prefix = new int[MAX + 1];

static void buildPrefix()
{

/*    Create a boolean array
    "prime[0..n]". A value
    in prime[i] will finally
    be false if i is Not a
    prime, else true.*/

    bool[] prime = new bool[MAX + 1];

    for (int p = 2;
             p * p <= MAX; p++)
    {

/*    If prime[p] is
    not changed, then
    it is a prime*/

    if (prime[p] == false)
    {

/*        Update all
        multiples of p*/

        for (int i = p * 2;
                 i <= MAX; i += p)
        prime[i] = true;
    }
    }

/*    Build prefix array*/

    prefix[0] = prefix[1] = 0;
    for (int p = 2; p <= MAX; p++)
    {
        prefix[p] = prefix[p - 1];
        if (prime[p] == false)
            prefix[p]++;
    }
}

/*Returns count of primes
in range from L to R
(both inclusive).*/

static int query(int L, int R)
{
    return prefix[R] -
           prefix[L - 1];
}

/*Driver code*/

public static void Main()
{
    buildPrefix();
    int L = 5, R = 10;
    Console.WriteLine(query(L, R));

    L = 1; R = 10;
    Console.WriteLine(query(L, R));
}
}

/*C# program to find modified array
after m range toggle operations.*/

using System;

class GFG
{

/*function for toggle*/

static void command(bool[] arr,
                    int a, int b)
{
    arr[a] ^= true;
    arr[b + 1] ^= true;
}

/*function for final processing of array*/

static void process(bool[] arr, int n)
{
    for (int k = 1; k <= n; k++)
    {
        arr[k] ^= arr[k - 1];
    }
}

/*function for printing result*/

static void result(bool[] arr, int n)
{
    for (int k = 1; k <= n; k++)
    {
        if(arr[k] == true)
            Console.Write("1" + " ");
        else
            Console.Write("0" + " ");
    }
}

/*Driver Code*/

public static void Main()
{
    int n = 5, m = 3;
    bool[] arr = new bool[n + 2];

/*    function call for toggle*/

    command(arr, 1, 5);
    command(arr, 2, 5);
    command(arr, 3, 5);

/*    process array*/

    process(arr, n);

/*    print result*/

    result(arr, n);
}
}

/*C# program to check if
any two intervals overlap*/

using System;

class GFG
{

/*An interval has start time and end time*/

class Interval
{
    public int start;
    public int end;
    public Interval(int start, int end)
    {
        this.start = start;
        this.end = end;
    }
};

/*Function to check if
any two intervals overlap*/

static bool isIntersect(Interval []arr, int n)
{
    int max_ele = 0;

/*    Find the overall maximum element*/

    for (int i = 0; i < n; i++)
    {
        if (max_ele < arr[i].end)
            max_ele = arr[i].end;
    }

/*    Initialize an array of size max_ele*/

    int []aux = new int[max_ele + 1];
    for (int i = 0; i < n; i++)
    {

/*        starting point of the interval*/

        int x = arr[i].start;

/*        end point of the interval*/

        int y = arr[i].end;
        aux[x]++;
        aux[y ]--;
    }

    for (int i = 1; i <= max_ele; i++)
    {

/*        Calculating the prefix Sum*/

        aux[i] += aux[i - 1];

/*        Overlap*/

        if (aux[i] > 1)
            return true;
    }

/*    If we reach here, then no Overlap*/

    return false;
}

/*Driver Code*/

public static void Main(String[] args)
{
    Interval []arr1 = { new Interval(1, 3),
                        new Interval(7, 9),
                        new Interval(4, 6),
                        new Interval(10, 13) };
    int n1 = arr1.Length;

    if(isIntersect(arr1, n1))
        Console.Write("Yes\n");
    else
        Console.Write("No\n");

    Interval []arr2 = { new Interval(6, 8),
                        new Interval(1, 3),
                        new Interval(2, 4),
                        new Interval(4, 7) };
    int n2 = arr2.Length;
    if(isIntersect(arr2, n2))
        Console.Write("Yes\n");
    else
        Console.Write("No\n");
}
}

/*C# implementation to increment values in the
given range by a value d for multiple queries*/

using System;

class GFG
{

/*    structure to store the (start, end)
    index pair for each query*/

    public class query
    {
        public int start, end;

        public query(int start, int end)
        {
            this.start = start;
            this.end = end;
        }
    }

/*    function to increment values in the given range
    by a value d for multiple queries*/

    public static void incrementByD(int[] arr, query[] q_arr,
                                    int n, int m, int d)
    {
        int[] sum = new int[n];

/*        for each (start, end) index pair, perform
        the following operations on 'sum[]'*/

        for (int i = 0; i < m; i++)
        {

/*            increment the value at index 'start'
            by the given value 'd' in 'sum[]'*/

            sum[q_arr[i].start] += d;

/*            if the index '(end+1)' exists then
            decrement the value at index '(end+1)'
            by the given value 'd' in 'sum[]'*/

            if ((q_arr[i].end + 1) < n)
                sum[q_arr[i].end + 1] -= d;
        }

/*        Now, perform the following operations:
        accumulate values in the 'sum[]' array and
        then add them to the corresponding indexes
        in 'arr[]'*/

        arr[0] += sum[0];
        for (int i = 1; i < n; i++)
        {
            sum[i] += sum[i - 1];
            arr[i] += sum[i];
        }
    }

/*    function to print the elements of the given array*/

    public static void printArray(int[] arr, int n)
    {
        for (int i = 0; i < n; i++)
            Console.Write(arr[i] + " ");
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int[] arr = { 3, 5, 4, 8, 6, 1 };
        query[] q_arr = new query[5];
        q_arr[0] = new query(0, 3);
        q_arr[1] = new query(4, 5);
        q_arr[2] = new query(1, 4);
        q_arr[3] = new query(0, 1);
        q_arr[4] = new query(2, 5);
        int n = arr.Length;
        int m = q_arr.Length;
        int d = 2;
        Console.WriteLine("Original Array:");
        printArray(arr, n);

/*        modifying the array for multiple queries*/

        incrementByD(arr, q_arr, n, m, d);
        Console.WriteLine("\nModified Array:");
        printArray(arr, n);
    }
}

/*C# code Queries on XOR of
greatest odd divisor of the range*/

using System;

class GFG
{

/*    Precompute the prefix XOR of greatest
    odd divisor*/

    static void prefixXOR(int []arr,
                    int []preXOR, int n)
    {

/*        Finding the Greatest Odd divisor*/

        for (int i = 0; i < n; i++)
        {
            while (arr[i] % 2 != 1)
                arr[i] /= 2;

            preXOR[i] = arr[i];
        }

/*        Finding prefix XOR*/

        for (int i = 1; i < n; i++)
            preXOR[i] = preXOR[i - 1] ^ preXOR[i];
    }

/*    Return XOR of the range*/

    static int query(int [] preXOR, int l, int r)
    {
        if (l == 0)
            return preXOR[r];
        else
            return preXOR[r] ^ preXOR[l - 1];
    }

/*    Driven Program*/

    public static void Main ()
    {
        int []arr = { 3, 4, 5 };
        int n = arr.Length;

        int []preXOR = new int[n];
        prefixXOR(arr, preXOR, n);

        Console.WriteLine(query(preXOR, 0, 2)) ;
        Console.WriteLine (query(preXOR, 1, 2));
    }
}

/*C# program to implement toggle and
count queries on a binary array.*/

using System;

public class GFG{

    static readonly int MAX = 100000;

/*    segment tree to store count
    of 1's within range*/

    static int []tree = new int[MAX];

/*    bool type tree to collect the updates
    for toggling the values of 1 and 0 in
    given range*/

    static bool []lazy = new bool[MAX];

/*    function for collecting updates of toggling
    node --> index of current node in segment tree
    st --> starting index of current node
    en --> ending index of current node
    us --> starting index of range update query
    ue --> ending index of range update query*/

    static void toggle(int node, int st,
                    int en, int us, int ue)
    {

/*        If lazy value is non-zero for current
        node of segment tree, then there are
        some pending updates. So we need
        to make sure that the pending updates
        are done before making new updates.
        Because this value may be used by
        parent after recursive calls (See last
        line of this function)*/

        if (lazy[node])
        {

/*            Make pending updates using value
            stored in lazy nodes*/

            lazy[node] = false;
            tree[node] = en - st + 1 - tree[node];

/*            checking if it is not leaf node
            because if it is leaf node then
            we cannot go further*/

            if (st < en)
            {

/*                We can postpone updating children
                we don't need their new values now.
                Since we are not yet updating children
                of 'node', we need to set lazy flags
                for the children*/

                lazy[node << 1] = !lazy[node << 1];
                lazy[1 + (node << 1)] = !lazy[1 + (node << 1)];
            }
        }

/*        out of range*/

        if (st > en || us > en || ue < st)
        {
            return;
        }

/*        Current segment is fully in range*/

        if (us <= st && en <= ue)
        {

/*            Add the difference to current node*/

            tree[node] = en - st + 1 - tree[node];

/*            same logic for checking leaf node or not*/

            if (st < en)
            {

/*                This is where we store values in lazy nodes,
                rather than updating the segment tree itelf
                Since we don't need these updated values now
                we postpone updates by storing values in lazy[]*/

                lazy[node << 1] = !lazy[node << 1];
                lazy[1 + (node << 1)] = !lazy[1 + (node << 1)];
            }
            return;
        }

/*        If not completely in rang,
        but overlaps, recur for children,*/

        int mid = (st + en) / 2;
        toggle((node << 1), st, mid, us, ue);
        toggle((node << 1) + 1, mid + 1, en, us, ue);

/*        And use the result of children
        calls to update this node*/

        if (st < en)
        {
            tree[node] = tree[node << 1] +
                        tree[(node << 1) + 1];
        }
    }

/* node --> Index of current node in the segment tree.
        Initially 0 is passed as root is always at'
        index 0
    st & en --> Starting and ending indexes of the
                segment represented by current node,
                i.e., tree[node]
    qs & qe --> Starting and ending indexes of query
                range */

/*    function to count number of 1's
    within given range*/

    static int countQuery(int node, int st,
                        int en, int qs, int qe)
    {

/*        current node is out of range*/

        if (st > en || qs > en || qe < st)
        {
            return 0;
        }

/*        If lazy flag is set for current
        node of segment tree, then there
        are some pending updates. So we
        need to make sure that the pending
        updates are done before processing
        the sub sum query*/

        if (lazy[node])
        {

/*            Make pending updates to this node.
            Note that this node represents sum
            of elements in arr[st..en] and
            all these elements must be increased
            by lazy[node]*/

            lazy[node] = false;
            tree[node] = en - st + 1 - tree[node];

/*            checking if it is not leaf node because if
            it is leaf node then we cannot go further*/

            if (st < en)
            {

/*                Since we are not yet updating children os si,
                we need to set lazy values for the children*/

                lazy[node << 1] = !lazy[node << 1];
                lazy[(node << 1) + 1] = !lazy[(node << 1) + 1];
            }
        }

/*        At this point we are sure that pending
        lazy updates are done for current node.
        So we can return value If this segment
        lies in range*/

        if (qs <= st && en <= qe)
        {
            return tree[node];
        }

/*        If a part of this segment overlaps
        with the given range*/

        int mid = (st + en) / 2;
        return countQuery((node << 1), st, mid, qs, qe) +
            countQuery((node << 1) + 1, mid + 1, en, qs, qe);
    }

/*    Driver Code*/

    public static void Main()
    {
        int n = 5;

/*Toggle 1 2*/

toggle(1, 0, n - 1, 1, 2);

/*Toggle 2 4*/

toggle(1, 0, n - 1, 2, 4);

/*Count 2 3*/

Console.WriteLine(countQuery(1, 0, n - 1, 2, 3));

/*Toggle 2 4*/

toggle(1, 0, n - 1, 2, 4);

/*Count 1 4*/

Console.WriteLine(countQuery(1, 0, n - 1, 1, 4)); 
    }
}

/*C# program to calculate the number
pairs satisfying th condition*/

using System;

class GFG{

/*Function to calculate the number of pairs*/

static int countPairs(int[] a, int n,
                      int x, int k)
{
    Array.Sort(a);

/*    Traverse through all elements*/

    int ans = 0;
    for(int i = 0; i < n; i++)
    {

/*        Current number's divisor*/

        int d = (a[i] - 1) / x;

/*        Use binary search to find the element
        after k multiples of x*/

        int a1 = Math.Max((d + k) * x, a[i]);
        int it1 = Array.BinarySearch(a, a1);

/*        Use binary search to find the element
        after k+1 multiples of x so that we get
        the answer bu subtracting*/

        int a2 = Math.Max((d + k + 1) * x, a[i]);
        int it2 = Array.BinarySearch(a, a2);

/*        The difference of index will
        be the answer*/

        ans += Math.Abs(it2 - it1);
    }
    return ans;
}

/*Driver Code*/

static void Main()
{
    int[] a = { 1, 3, 5, 7 };
    int n = a.Length;
    int x = 2, k = 1;

/*    Function call to get the number of pairs*/

    Console.Write(countPairs(a, n, x, k));
}
}

/*C# program to find Probability of a random
pair being the maximum weighted pair*/

using System;

class GFG {

/*    Function to return probability*/

    static float probability(int []a, int []b,
                          int size1,int size2)
    {

/*        Count occurrences of maximum
        element in A[]*/

        int max1 = int.MinValue, count1 = 0;

        for (int i = 0; i < size1; i++) {
            if (a[i] > max1) {
                max1 = a[i];
                count1 = 1;
            }
            else if (a[i] == max1) {
                count1++;
            }
        }

/*        Count occurrences of maximum
        element in B[]*/

        int max2 = int.MinValue, count2 = 0;

        for (int i = 0; i < size2; i++) {
            if (b[i] > max2) {
                max2 = b[i];
                count2 = 1;
            }
            else if (b[i] == max2) {
                count2++;
            }
        }

/*        Returning probability*/

        return (float)(count1 * count2) /
                            (size1 * size2);
    }

/*    Driver code*/

    public static void Main()
    {
        int []a = { 1, 2, 3 };
        int []b = { 1, 3, 3 };

        int size1 = a.Length;
        int size2 = b.Length;

        Console.WriteLine(probability(a, b,
                            size1, size2));
    }
}

/*C# code for counting
minimum de-arrangements
present in an array.*/

using System;

class GFG
{

/*function to count
Dearrangement*/

public static int countDe(int[] arr,
                          int n)
{
    int[] v = new int[n];

/*    create a copy
    of original array*/

    for(int i = 0; i < n; i++)
        v[i] = arr[i];

/*    sort the array*/

    Array.Sort(arr);

/*    traverse sorted array for
    counting mismatches*/

    int count1 = 0;
    for (int i = 0; i < n; i++)
        if (arr[i] != v[i])
        count1++;

/*    reverse the sorted array*/

    Array.Reverse(arr);

/*    traverse reverse sorted array
    for counting mismatches*/

    int count2 = 0;
    for (int i = 0; i < n; i++)
        if (arr[i] != v[i])
            count2++;

/*    return minimum
    mismatch count*/

    return (Math.Min (count1, count2));
}

/*Driver code*/

public static void Main()
{
    int[] arr = new int[]{5, 9, 21, 17, 13};
    int n = 5;
    Console.WriteLine("Minimum Dearrangement = " +
                                 countDe(arr, n));
}
}

/*C# Program to find maximum value of
maximum of minimums of k segments.*/

using System;
using System.Linq;

public class GFG {

/*    function to calculate the max
    of all the minimum segments*/

    static int maxOfSegmentMins(int []a,
                             int n, int k)
    {

/*        if we have to divide it into 1
        segment then the min will be
        the answer*/

        if (k == 1)
            return a.Min();

        if (k == 2)
            return Math.Max(a[0], a[n - 1]);

/*        If k >= 3, return maximum of
        all elements.*/

        return a.Max();
    }

/*    Driver function*/

    static public void Main ()
    {
        int []a = { -10, -9, -8, 2, 7,
                                 -6, -5 };
        int n = a.Length;
        int k = 2;

        Console.WriteLine(
                  maxOfSegmentMins(a, n, k));
    }
}

/*C# program to calculate minimum
product of a pair*/

using System;

class GFG {

/*    Function to calculate minimum
    product of pair*/

    static int printMinimumProduct(int []arr,
                                       int n)
    {

/*        Initialize first and second
        minimums. It is assumed that
        the array has at least two
        elements.*/

        int first_min = Math.Min(arr[0],
                                    arr[1]);

        int second_min = Math.Max(arr[0],
                                    arr[1]);

/*        Traverse remaining array and
        keep track of two minimum
        elements (Note that the two
        minimum elements may be same
        if minimum element appears
        more than once)*/

        for (int i = 2; i < n; i++)
        {
            if (arr[i] < first_min)
            {
                second_min = first_min;
                first_min = arr[i];
            }
            else if (arr[i] < second_min)
                second_min = arr[i];
        }

        return first_min * second_min;
    }

/* Driver program to test above
    function */

    public static void Main()
    {
        int []a = { 11, 8 , 5 , 7 ,
                            5 , 100 };
        int n = a.Length;

        Console.WriteLine(
            printMinimumProduct(a, n));
    }
}

/*C# program to count number of ways
we can form triplets with minimum product.*/

using System;

class GFG {

/*function to calculate number of triples*/

static long noOfTriples(long []arr, int n)
{

/*    Sort the array*/

    Array.Sort(arr);

/*    Count occurrences of third element*/

    long count = 0;
    for (int i = 0; i < n; i++)
        if (arr[i] == arr[2])
            count++;

/*    If all three elements are same (minimum
    element appears at least 3 times). Answer
    is nC3.*/

    if (arr[0] == arr[2])
        return (count - 2) * (count - 1) * (count) / 6;

/*    If minimum element appears once. 
    Answer is nC2.*/

    else if (arr[1] == arr[2])
        return (count - 1) * (count) / 2;

/*    Minimum two elements are distinct.
    Answer is nC1.*/

    return count;
}

/*driver code*/

public static void Main()
{
    long []arr = { 1, 3, 3, 4 };
    int n = arr.Length;
    Console.Write(noOfTriples(arr, n));
}
}

/*C# program to check whether reversing a
sub array make the array sorted or not*/

using System;

class GFG
{

/*Return true, if reversing the
subarray will sort the array,
else return false.*/

static bool checkReverse(int []arr, int n)
{

/*    Copying the array.*/

    int []temp = new int[n];
    for (int i = 0; i < n; i++)
    {
        temp[i] = arr[i];
    }

/*    Sort the copied array.*/

    Array.Sort(temp);

/*    Finding the first mismatch.*/

    int front;
    for (front = 0; front < n; front++)
    {
        if (temp[front] != arr[front])
        {
            break;
        }
    }

/*    Finding the last mismatch.*/

    int back;
    for (back = n - 1; back >= 0; back--)
    {
        if (temp[back] != arr[back])
        {
            break;
        }
    }

/*    If whole array is sorted*/

    if (front >= back)
    {
        return true;
    }

/*    Checking subarray is decreasing
    or not.*/

    do
    {
        front++;
        if (arr[front - 1] < arr[front])
        {
            return false;
        }
    } while (front != back);

    return true;
}

/*Driven Program*/

public static void Main()
{
    int []arr = {1, 2, 5, 4, 3};
    int n = arr.Length;

    if (checkReverse(arr, n))
    {
        Console.Write("Yes");
    }
    else
    {
        Console.Write("No");
    }
}
}

/*C# program to check whether reversing a
sub array make the array sorted or not*/


using System;
public class GFG{

/*Return true, if reversing the subarray will sort t
he array, else return false.*/

    static bool checkReverse(int []arr, int n) {
        if (n == 1) {
            return true;
        }

/*        Find first increasing part*/

        int i;
        for (i = 1; arr[i - 1] < arr[i] && i < n; i++);
        if (i == n) {
            return true;
        }

/*        Find reversed part*/

        int j = i;
        while (j < n && arr[j] < arr[j - 1]) {
            if (i > 1 && arr[j] < arr[i - 2]) {
                return false;
            }
            j++;
        }

        if (j == n) {
            return true;
        }

/*        Find last increasing part*/

        int k = j;

/*        To handle cases like {1,2,3,4,20,9,16,17}*/

        if (arr[k] < arr[i - 1]) {
            return false;
        }

        while (k > 1 && k < n) {
            if (arr[k] < arr[k - 1]) {
                return false;
            }
            k++;
        }
        return true;
    }

/*Driven Program*/

    public static void Main() {

        int []arr = {1, 3, 4, 10, 9, 8};
        int n = arr.Length;

        if (checkReverse(arr, n)) {
            Console.Write("Yes");
        } else {
            Console.Write("No");
        }
    }
}

/*C# program to find minimum 
increment/decrement operations
to make array elements same.*/

using System;
public class GFG {

static int MinOperation(int []a,
                        int []b, 
                        int n)
{

/*    sorting both arrays 
    in ascending order*/

    Array.Sort(a);
    Array.Sort(b);

/*    variable to store 
    the final result*/

    int result = 0;

/*    After sorting both arrays
    Now each array is in non-
    decreasing order. Thus,
    we will now compare each
    element of the array and
    do the increment or decrement
    operation depending upon the
    value of array b[].*/

    for (int i = 0; i < n; ++i) 
    {
        if (a[i] > b[i])
            result = result +
                     Math.Abs(a[i] - b[i]);

        else if (a[i] < b[i])
            result = result + 
                     Math.Abs(a[i] - b[i]);
    }

    return result;
}

/*Driver code*/

public static void Main () 
{
    int []a = {3, 1, 1};
    int []b = {1, 2, 2};
    int n = a.Length;
    Console.WriteLine(MinOperation(a, b, n));
}
}

/*C# program to sort all elements except
given subarray.*/

using System;
using System.Collections.Generic;

class GFG {

/*    Sort whole array a[] except elements in
    range a[l..r]*/

    static void sortExceptUandL(int []a, int l,
                                 int u, int n)
    {

/*        Copy all those element that need
        to be sorted to an auxiliary
        array b[]*/

        int[] b = new int[n - (u-l+1)];

        for (int i = 0; i < l; i++)
            b[i] = a[i];

        for (int i = u+1; i < n; i++)
            b[l + (i - (u+1))] = a[i];

/*        sort the array b*/

        Array.Sort<int>(b, 0, n - (u - l + 1));

/*        Copy sorted elements back to a[]*/

        for (int i = 0; i < l; i++)
            a[i] = b[i];

        for (int i = u+1; i < n; i++)
            a[i] = b[l + (i - (u+1))];
    }

/*    Driver code*/

    public static void Main()
    {
        int []a = { 5, 4, 3, 12, 14, 9 };
        int n = a.Length;
        int l = 2, u = 4;

        sortExceptUandL(a, l, u, n);

        for (int i = 0; i < n; i++)
            Console.Write(a[i] + " ");
    }
}

/*C# program to sort all elements except
element at index k.*/

using System;

public class GFG {

    static int sortExceptK(int[] arr, int k, int n)
    {

/*        Move k-th element to end*/

        int temp = arr[k];
        arr[k] = arr[n - 1];
        arr[n - 1] = temp;

/*        Sort all elements except last*/

        Array.Sort(arr, 0, n - 1);

/*        Store last element (originally k-th)*/

        int last = arr[n - 1];

/*        Move all elements from k-th to one
        position ahead.*/

        for (int i = n - 1; i > k; i--)
            arr[i] = arr[i - 1];

/*        Restore k-th element*/

        arr[k] = last;

        return 0;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] a = { 10, 4, 11, 7, 6, 20 };
        int k = 2;
        int n = a.Length;

        sortExceptK(a, k, n);

        for (int i = 0; i < n; i++)
        Console.Write(a[i] + " ");
    }
}

/*C# code to find minimum number of
swaps to sort a binary array*/

using System;

class GFG {

/*Function to find minimum swaps to
sort an array of 0s and 1s.*/

    static int findMinSwaps(int []arr, int n)
    {

/*        Array to store count of zeroes*/

        int []noOfZeroes = new int[n];
        int i, count = 0;

/*        Count number of zeroes
        on right side of every one.*/

        noOfZeroes[n - 1] = 1 - arr[n - 1];
        for (i = n - 2; i >= 0; i--)
        {
            noOfZeroes[i] = noOfZeroes[i + 1];
            if (arr[i] == 0)
                noOfZeroes[i]++;
        }

/*        Count total number of swaps by
        adding number of zeroes on right
        side of every one.*/

        for (i = 0; i < n; i++)
        {
            if (arr[i] == 1)
                count += noOfZeroes[i];
        }

        return count;
    }

/*    Driver Code*/

    public static void Main()
    {
        int []ar = { 0, 0, 1, 0, 1,
                                0, 1, 1 };

        Console.WriteLine(
              findMinSwaps(ar, ar.Length));
    }
}

using System;
class GFG {

    static int minswaps(int[] arr, int n)
    {
        int count = 0;
        int num_unplaced_zeros = 0;

        for (int index = n - 2; index >= 0; index--)
        {
            if (arr[index] == 0)
                num_unplaced_zeros += 1;
            else
                count += num_unplaced_zeros;
        }
        return count;
    }

/*Driver Code*/


  static void Main() {
    int[] arr = { 0, 0, 1, 0, 1, 0, 1, 1 };
    Console.WriteLine(minswaps(arr, 9));
  }
}

/*Efficient C# program to sort given list in order
elements are appearing in an array*/

using System;
using System.Collections.Generic;

class GFG
{

/*Linked list node*/

public class Node
{
    public int data;
    public Node next;
};

/*Function to insert a node at the
beginning of the linked list*/

static Node push(Node head_ref, int new_data)
{
    Node new_node = new Node();
    new_node.data = new_data;
    new_node.next = head_ref;
    head_ref = new_node;
    return head_ref;
}

/*function to print the linked list*/

static void printList(Node head)
{
    while (head != null)
    {
        Console.Write(head.data + "->");
        head = head.next;
    }
}

/*Function that sort list in order of apperaing
elements in an array*/

static void sortlist(int []arr, int N, Node head)
{

/*    Store frequencies of elements in a
    hash table.*/

    Dictionary<int,
               int> hash = new Dictionary<int,
                                          int>();
    Node temp = head;
    while (temp != null)
    {
        if(hash.ContainsKey(temp.data))
            hash[temp.data] = hash[temp.data] + 1;
        else
            hash.Add(temp.data, 1);
        temp = temp.next;
    }
    temp = head;

/*    One by one put elements in lis according
    to their appearance in array*/

    for (int i = 0; i < N; i++)
    {

/*        Update 'frequency' nodes with value
        equal to arr[i]*/

        int frequency = hash[arr[i]];
        while (frequency-->0)
        {

/*            Modify list data as element
            appear in an array*/

            temp.data = arr[i];
            temp = temp.next;
        }
    }
}

/*Driver Code*/

public static void Main(String[] args)
{
    Node head = null;
    int []arr = { 5, 1, 3, 2, 8 };
    int N = arr.Length;

/*    creating the linked list*/

    head = push(head, 3);
    head = push(head, 2);
    head = push(head, 5);
    head = push(head, 8);
    head = push(head, 5);
    head = push(head, 2);
    head = push(head, 1);

/*    Function call to sort the list in order
    elements are apperaing in an array*/

    sortlist(arr, N, head);

/*    print the modified linked list*/

    Console.Write("Sorted List:" + "\n");
    printList(head);
}
}

