with difference less than K.*/

using System;

class GFG {
    static int countPairs(int []a, int n,
                          int k)
    {

/*        to sort the array.*/

        Array.Sort(a);

        int res = 0;
        for (int i = 0; i < n; i++)
        {

/*            Keep incrementing result while
            subsequent elements are within
            limits.*/

            int j = i + 1;
            while (j < n && a[j] - a[i] < k)
            {
                res++;
                j++;
            }
