}

/*C# Code for Merging two unsorted
arrays in sorted order*/

using System;

class GFG {

/*    Function to merge array in
    sorted order*/

    static void sortedMerge(int []a, int []b,
                     int []res, int n, int m)
    {

/*        Sorting a[] and b[]*/

        Array.Sort(a);
        Array.Sort(b);

/*        Merge two sorted arrays into res[]*/

        int i = 0, j = 0, k = 0;

        while (i < n && j < m)
        {
            if (a[i] <= b[j])
            {
                res[k] = a[i];
                i += 1;
                k += 1;
            }
            else
            {
                res[k] = b[j];
                j += 1;
                k += 1;
            }
        }

        while (i < n)
        {

/*            Merging remaining
            elements of a[] (if any)*/

            res[k] = a[i];
            i += 1;
            k += 1;
        }
        while (j < m)
        {

/*            Merging remaining
            elements of b[] (if any)*/

            res[k] = b[j];
            j += 1;
            k += 1;
        }
    }

/* Driver program to test
    above function */

    public static void Main()
    {
        int []a = { 10, 5, 15 };
        int []b = { 20, 3, 2, 12 };
        int n = a.Length;
        int m = b.Length;

/*        Final merge list*/

        int []res = new int[n + m];
        sortedMerge(a, b, res, n, m);

        Console.Write( "Sorted merged list :");
        for (int i = 0; i < n + m; i++)
            Console.Write(" " + res[i]);
    }
}

/*C# implementation of above approach*/

using System;

class GFG
{

/*    Returns count of maximum pairs that caan
    be formed from a[] and b[] under given
    constraints.*/

    static int findMaxPairs(int []a, int []b,
                                int n, int k)
    {

/*Sorting the first array.*/

Array.Sort(a);

/*Sorting the second array.*/

Array.Sort(b);

/*        To keep track of visited elements of b[]*/

        bool []flag = new bool[n];

/*        For every element of a[], find a pair
        for it and break as soon as a pair is
        found.*/

        int result = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (Math.Abs(a[i] - b[j]) <= k && flag[j] == false)
                {

/*                    Increasing the count if a pair is formed.*/

                    result++;

/* Making the corresponding flag array
                    element as 1 indicating the element
                    in the second array element has
                    been used. */

                    flag[j] = true;

/*                    We break the loop to make sure an
                    element of a[] is used only once.*/

                    break;
                }
            }
        }
        return result;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] a = {10, 15, 20};
        int[] b = {17, 12, 24};
        int n = a.Length;
        int k = 3;
        Console.WriteLine(findMaxPairs(a, b, n, k));
    }
}

/*C# program for Maximizing Unique Pairs
from two arrays*/

using System;

class GFG
{

/*Returns count of maximum pairs that caan
be formed from a[] and b[] under given
constraints.*/

static int findMaxPairs(int []a, int []b,
                        int n, int k)
{

/*Sorting the first array.*/

Array.Sort(a);

/*Sorting the second array.*/

Array.Sort(b); 

    int result = 0;
    for (int i = 0, j = 0; i < n && j < n;)
    {
        if (Math.Abs(a[i] - b[j]) <= k)
        {
            result++;

/*            Increasing array pointer of
            both the first and the second array.*/

            i++;
            j++;
        }

/*        Increasing array pointer
        of the second array.*/

        else if(a[i] > b[j])
            j++;

/*        Increasing array pointer
        of the first array.*/

        else
            i++;
    }
    return result;
}

/*Driver code*/

public static void Main(String []args)
{
    int []a = {10, 15, 20};
    int []b = {17, 12, 24};
    int n = a.Length;
    int k = 3;
    Console.WriteLine(findMaxPairs(a, b, n, k));
}
}

/*C# implementation to find the sum
of minimum absolute difference of
each array element*/

using System;

public class GFG {

/*    function to find the sum of
    minimum absolute difference*/

    static int sumOfMinAbsDifferences(
                         int []arr ,int n)
    {

/*        sort the given array*/

        Array.Sort(arr);

/*        initialize sum*/

        int sum = 0;

/*        min absolute difference for
        the 1st array element*/

        sum += Math.Abs(arr[0] - arr[1]);

/*        min absolute difference for
        the last array element*/

        sum += Math.Abs(arr[n-1] - arr[n-2]);

/*        find min absolute difference for
        rest of the array elements and
        add them to sum*/

        for (int i = 1; i < n - 1; i++)
            sum +=
            Math.Min(Math.Abs(arr[i] - arr[i-1]),
                    Math.Abs(arr[i] - arr[i+1]));

/*        required sum*/

        return sum;
    }

/*    Driver code*/

    public static void Main ()
    {
