/*C# Code to find Smallest
Difference between two Arrays*/

using System;

class GFG
{

/*    function to calculate Small
    result between two arrays*/

    static int findSmallestDifference(int []A, int []B,
                                      int m, int n)
    {

/*        Sort both arrays using
        sort function*/

        Array.Sort(A);
        Array.Sort(B);

        int a = 0, b = 0;

/*        Initialize result as max value*/

        int result = int.MaxValue;

/*        Scan Both Arrays upto
        sizeof of the Arrays*/

        while (a < m && b < n)
        {
            if (Math.Abs(A[a] - B[b]) < result)
                result = Math.Abs(A[a] - B[b]);

/*            Move Smaller Value*/

            if (A[a] < B[b])
                a++;

            else
                b++;
        }

/*        return final sma result*/

        return result;
    }

/*    Driver Code*/

    public static void Main()
    {

/*        Input given array A*/

        int []A = {1, 2, 11, 5};

/*        Input given array B*/

        int []B = {4, 12, 19, 23, 127, 235};

/*        Calculate size of Both arrays*/

        int m = A.Length;
        int n = B.Length;

/*        Call function to
        print smallest result*/

        Console.Write(findSmallestDifference
                              (A, B, m, n));

    }
}

/*Recursive approach to check if an
Array is sorted or not*/

using System;

class CkeckSorted {

/*    Function that returns 0 if a pair
    is found unsorted*/

    static int arraySortedOrNot(int[] arr, int n)
    {

/*        Array has one or no element or the
        rest are already checked and approved.*/

        if (n == 1 || n == 0)
            return 1;

/*        Unsorted pair found (Equal values allowed)*/

        if (arr[n - 1] < arr[n - 2])
            return 0;

/*        Last pair was sorted
        Keep on checking*/

        return arraySortedOrNot(arr, n - 1);
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] arr = { 20, 23, 23, 45, 78, 88 };
        int n = arr.Length;
        if (arraySortedOrNot(arr, n) != 0)
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*C# recursive approach to check if an
Array is sorted or not*/

using System;

class GFG{

/*Function that returns true if array is
sorted in non-decreasing order.*/

static bool arraySortedOrNot(int[] a, int n)
{

/*    Base case*/

    if (n == 1 || n == 0)
    {
        return true;
    }

/*    Check if present index and index
    previous to it are in correct order
    and rest of the array is also sorted
    if true then return true else return
    false*/

    return a[n - 1] >= a[n - 2] &&
     arraySortedOrNot(a, n - 1);
}

/*Driver code*/

static public void Main()
{
    int[] arr = { 20, 23, 23, 45, 78, 88 };
    int n = arr.Length;

/*    Function Call*/

    if (arraySortedOrNot(arr, n))
    {
        Console.WriteLine("Yes");
    }
    else
    {
        Console.WriteLine("No");
    }
}
}

