        Console.WriteLine(singleNumber(b,n));
    }
}

using System;
using System.Collections;

class GFG{

/*singleelement function*/

static int singleelement(int[] arr, int n)
{
    int low = 0, high = n - 2;
    int mid;

    while (low <= high)
    {
        mid = (low + high) / 2;

        if (arr[mid] == arr[mid ^ 1])
        {
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }
    return arr[low];
}

