{
    int[] arr = { 2, 3, 5, 4, 5, 3, 4 };
    int size = 7;
    Array.Sort(arr);

    Console.WriteLine(singleelement(arr, size));
}
}

/*A Simple C# program to count triplets with sum smaller
than a given value*/


using System;
class Test
{
    static int[] arr = new int[]{5, 1, 3, 4, 7};

    static int countTriplets(int n, int sum)
    {

/*        Initialize result*/

        int ans = 0;

/*        Fix the first element as A[i]*/

        for (int i = 0; i < n-2; i++)
        {

/*           Fix the second element as A[j]*/

           for (int j = i+1; j < n-1; j++)
           {

/*               Now look for the third number*/

               for (int k = j+1; k < n; k++)
                   if (arr[i] + arr[j] + arr[k] < sum)
                       ans++;
           }
        }

        return ans;
    }

/*    Driver method to test the above function*/

    public static void Main()
    {
        int sum = 12;
        Console.Write(countTriplets(arr.Length, sum));
    }
}

/*A Simple C# program to count
triplets with sum smaller
than a given value*/

using System;

class GFG
{
    static int []arr = new int[]{5, 1, 3, 4, 7};

    static int countTriplets(int n, int sum)
    {

/*        Sort input array*/

        Array.Sort(arr);

/*        Initialize result*/

        int ans = 0;

/*        Every iteration of loop
        counts triplet with
        first element as arr[i].*/

        for (int i = 0; i < n - 2; i++)
        {

/*            Initialize other two
            elements as corner elements
            of subarray arr[j+1..k]*/

            int j = i + 1, k = n - 1;

/*            Use Meet in the Middle concept*/

            while (j < k)
            {

/*                If sum of current triplet
                is more or equal, move right
                corner to look for smaller values*/

                if (arr[i] + arr[j] + arr[k] >= sum)
                    k--;

/*                Else move left corner*/

                else
                {

/*                    This is important. For
                    current i and j, there
                    can be total k-j third elements.*/

                    ans += (k - j);
                    j++;
                }
            }
        }
        return ans;
    }

/*    Driver Code*/

    public static void Main()
    {
        int sum = 12;
        Console.Write(countTriplets(arr.Length, sum));
    }
}

/*C# program to count
the number of unique
triplets whose XOR is 0*/

using System;
using System.Collections.Generic;

class GFG
{

/*    function to count the
    number of unique triplets
    whose xor is 0*/

    static int countTriplets(int []a,
                             int n)
    {

/*        To store values
        that are present*/

        List<int> s = new List<int>();
        for (int i = 0; i < n; i++)
            s.Add(a[i]);

/*        stores the count
        of unique triplets*/

        int count = 0;

/*        traverse for all i,
        j pairs such that j>i*/

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1;
                     j < n; j++)
            {

/*            xor of a[i] and a[j]*/

            int xr = a[i] ^ a[j];

/*            if xr of two numbers
            is present, then
            increase the count*/

            if (s.Exists(item => item == xr) &&
                   xr != a[i] && xr != a[j])
                count++;
            }
        }

/*        returns answer*/

        return count / 3;
    }

/*    Driver code*/

    static void Main()
    {
        int []a = new int[]{1, 3, 5,
                            10, 14, 15};
        int n = a.Length;
        Console.Write(countTriplets(a, n));
    }
}

