    }
}

/*C# program to count 1's in a sorted array*/

using System;

class GFG {

/* Returns counts of 1's in arr[low..high].
    The array is assumed to be sorted in
    non-increasing order */

    static int countOnes(int[] arr, int low, int high)
    {
        if (high >= low)
        {

/*            get the middle index*/

            int mid = low + (high - low) / 2;

/*            check if the element at middle
            index is last 1*/

            if ((mid == high || arr[mid + 1] == 0)
                && (arr[mid] == 1))
                return mid + 1;

/*            If element is not last 1, recur
            for right side*/

            if (arr[mid] == 1)
                return countOnes(arr, (mid + 1), high);

/*            else recur for left side*/

            return countOnes(arr, low, (mid - 1));
        }

        return 0;
    }

/* Driver code */

    public static void Main()
    {
        int[] arr = { 1, 1, 1, 1, 0, 0, 0 };
        int n = arr.Length;

        Console.WriteLine("Count of 1's in given "
                          + "array is "
                          + countOnes(arr, 0, n - 1));
    }
}

/*C# program to find missing element from
same arrays (except one missing element)*/

using System;

class GFG {

/* Function to find missing element based
    on binary search approach. arr1[] is of
    larger size and N is size of it.arr1[] and
    arr2[] are assumed to be in same order. */

    static int findMissingUtil(int []arr1,
                            int []arr2, int N)
    {

/*        special case, for only element
        which is missing in second array*/

        if (N == 1)
            return arr1[0];

/*        special case, for first
        element missing*/

        if (arr1[0] != arr2[0])
            return arr1[0];

/*        Initialize current corner points*/

        int lo = 0, hi = N - 1;

/*        loop until lo < hi*/

        while (lo < hi) {
            int mid = (lo + hi) / 2;

/*            If element at mid indices are
            equal then go to right subarray*/

            if (arr1[mid] == arr2[mid])
                lo = mid;
            else
                hi = mid;

/*            if lo, hi becomes
            contiguous, break*/

            if (lo == hi - 1)
                break;
        }

/*        missing element will be at hi
        index of bigger array*/

        return arr1[hi];
    }

/*    This function mainly does basic error
    checking and calls findMissingUtil*/

    static void findMissing(int []arr1, int []arr2,
                            int M, int N)
    {
        if (N == M - 1)
            Console.WriteLine("Missing Element is "
            + findMissingUtil(arr1, arr2, M) + "\n");
        else if (M == N - 1)
            Console.WriteLine("Missing Element is "
            + findMissingUtil(arr2, arr1, N) + "\n");
        else
            Console.WriteLine("Invalid Input");
    }

/*    Driver Code*/

    public static void Main()
    {
        int []arr1 = { 1, 4, 5, 7, 9 };
        int []arr2 = { 4, 5, 7, 9 };
        int M = arr1.Length;
        int N = arr2.Length;
        findMissing(arr1, arr2, M, N);
    }
}

/*C# program to find missing element
from one array such that it has all
elements of other array except one.
Elements in two arrays can be in
any order.*/

using System;
class GFG {

/*    This function mainly does XOR of
    all elements of arr1[] and arr2[]*/

    static void findMissing(int []arr1,
                            int []arr2,
                            int M, int N)
    {
        if (M != N - 1 && N != M - 1)
        {
            Console.WriteLine("Invalid Input");
            return;
        }

/*        Do XOR of all element*/

        int res = 0;
        for (int i = 0; i < M; i++)
            res = res ^ arr1[i];
        for (int i = 0; i < N; i++)
            res = res ^ arr2[i];

        Console.WriteLine("Missing element is "
                                        + res);
    }

/*    Driver Code*/

    public static void Main()
    {

        int []arr1 = {4, 1, 5, 9, 7};
        int []arr2 = {7, 5, 9, 4};
        int M = arr1.Length;
        int N = arr2.Length;
        findMissing(arr1, arr2, M, N);
    }
}

