/*C# program to Find the repeating
and missing elements*/


using System;

class GFG {
    static int x, y;

/* The output of this function is stored at
*x and *y */


    static void getTwoElements(int[] arr, int n)
    {

/* Will hold xor of all elements
        and numbers from 1 to n */

        int xor1;

/* Will have only single set bit of xor1 */

        int set_bit_no;

        int i;
        x = 0;
        y = 0;

        xor1 = arr[0];

/* Get the xor of all array elements */

        for (i = 1; i < n; i++)
            xor1 = xor1 ^ arr[i];

/* XOR the previous result with numbers from
        1 to n*/

        for (i = 1; i <= n; i++)
            xor1 = xor1 ^ i;

/* Get the rightmost set bit in set_bit_no */

        set_bit_no = xor1 & ~(xor1 - 1);

/* Now divide elements in two sets by comparing
        rightmost set bit of xor1 with bit at same
        position in each element. Also, get XORs of two
        sets. The two XORs are the output elements.The
        following two for loops serve the purpose */

        for (i = 0; i < n; i++) {
            if ((arr[i] & set_bit_no) != 0)

/* arr[i] belongs to first set */

                x = x ^ arr[i];

            else

/* arr[i] belongs to second set*/

                y = y ^ arr[i];
        }
        for (i = 1; i <= n; i++) {
            if ((i & set_bit_no) != 0)

/* i belongs to first set */

                x = x ^ i;

            else

/* i belongs to second set*/

                y = y ^ i;
        }

/* *x and *y hold the desired output elements */

    }

/*    Driver program*/

    public static void Main()
    {
        int[] arr = { 1, 3, 4, 5, 1, 6, 2 };

        int n = arr.Length;
        getTwoElements(arr, n);
        Console.Write(" The missing element is "
                      + x + "and the "
                      + "repeating number is "
                      + y);
    }
}

/*C# program to find the
repeating and missing elements
using Maps*/

using System;
using System.Collections.Generic;

class GFG
{
    public static void Main(String[] args)
    {
        int[] arr = { 4, 3, 6, 2, 1, 1 };

        Dictionary<int, Boolean> numberMap =
                   new Dictionary<int, Boolean>();

        int max = arr.Length;

        foreach (int i in arr)
        {
            if (!numberMap.ContainsKey(i))
            {
                numberMap.Add(i, true);
            }
            else
            {
                Console.WriteLine("Repeating = " + i);
            }
        }
        for (int i = 1; i <= max; i++)
        {
            if (!numberMap.ContainsKey(i))
            {
                Console.WriteLine("Missing = " + i);
            }
        }
    }
}

/*C# program to find two odd
occurring elements*/

using System;

class main
{

/*    Prints two numbers that occur
    odd number of times. Function
    assumes that array size is at
    least 2 and there are exactly
    two numbers occurring odd number
    of times.*/

    static void printTwoOdd(int []arr, int size) {

/*      Will hold XOR of two odd
      occurring elements  */

      int xor2 = arr[0];

/*      Will have only single set
      bit of xor2*/

      int set_bit_no; 
      int i;
      int n = size - 2;
      int x = 0, y = 0;

/*      Get the xor of all the elements
      in arr[].The xor will basically
      be xor of two odd occurring
      elements*/

      for(i = 1; i < size; i++)
        xor2 = xor2 ^ arr[i];

/*      Get one set bit in the xor2.
      We get rightmost set bit in
      the following line as it is
      to get.*/

         set_bit_no = xor2 & ~(xor2-1);

/*      divide elements in two sets:
      1) The elements having the
      corresponding bit as 1.
      2) The elements having the
      corresponding bit as 0.*/

      for(i = 0; i < size; i++)
      {

/*         XOR of first set is finally
         going to hold one odd
         occurring number x*/

            if((arr[i] & set_bit_no)>0)
            x = x ^ arr[i];

/*            XOR of second set is finally
            going to hold the other
            odd occurring number y*/

            else
            y = y ^ arr[i];
      }

      Console.WriteLine("The two ODD elements are "+
                                        x + " & " + y);
    }

/*    main function*/

    public static void Main()
    {
        int []arr = {4, 2, 4, 5, 2, 3, 3, 1};
        int arr_size = arr.Length;
        printTwoOdd(arr, arr_size);
    }
}

/*C# program to find a pair with the given difference*/

using System;

class GFG {

/*    The function assumes that the array is sorted*/

    static bool findPair(int []arr, int n)
    {
        int size = arr.Length;

/*        Initialize positions of two elements*/

        int i = 0, j = 1;

/*        Search for a pair*/

        while (i < size && j < size)
        {
            if (i != j && arr[j] - arr[i] == n)
            {
                Console.Write("Pair Found: "
                + "( " + arr[i] + ", " + arr[j] +" )");

                return true;
            }
            else if (arr[j] - arr[i] < n)
                j++;
            else
                i++;
        }

        Console.Write("No such pair");

        return false;
    }

/*    Driver program to test above function*/

    public static void Main ()
    {
        int []arr = {1, 8, 30, 40, 100};
        int n = 60;

        findPair(arr, n);
    }
}

/*C# program for naive solution to
print all combination of 4 elements
in A[] with sum equal to X*/

using System;

class FindFourElements
{

/* A naive solution to print all combination
of 4 elements in A[]with sum equal to X */

    void findFourElements(int []A, int n, int X)
    {

/*        Fix the first element and find other three*/

        for (int i = 0; i < n - 3; i++)
        {

/*            Fix the second element and find other two*/

            for (int j = i + 1; j < n - 2; j++)
            {

/*                Fix the third element and find the fourth*/

                for (int k = j + 1; k < n - 1; k++)
                {

/*                    find the fourth*/

                    for (int l = k + 1; l < n; l++)
                    {
                        if (A[i] + A[j] + A[k] + A[l] == X)
                        Console.Write(A[i] + " " + A[j] +
                                " " + A[k] + " " + A[l]);
                    }
                }
            }
        }
    }

/*    Driver program to test above functions*/

    public static void Main()
    {
        FindFourElements findfour = new FindFourElements();
        int []A = {10, 20, 30, 40, 1, 2};
        int n = A.Length;
        int X = 91;
        findfour.findFourElements(A, n, X);
    }
}

/*A hashing based C# program to find
if there are four elements with given sum.*/

using System;
using System.Collections.Generic;

class GFG {
    public class pair {
        public int first, second;
        public pair(int first, int second)
        {
            this.first = first;
            this.second = second;
        }
    }

/*    The function finds four elements
    with given sum X*/

    static void findFourElements(int[] arr, int n, int X)
    {

/*        Store sums of all pairs in a hash table*/

        Dictionary<int, pair> mp
            = new Dictionary<int, pair>();
        for (int i = 0; i < n - 1; i++)
            for (int j = i + 1; j < n; j++)
                if (mp.ContainsKey(arr[i] + arr[j]))
                    mp[arr[i] + arr[j]] = new pair(i, j);
                else
                    mp.Add(arr[i] + arr[j], new pair(i, j));

/*        Traverse through all pairs and search
        for X - (current pair sum).*/

        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                int sum = arr[i] + arr[j];

/*                If X - sum is present in hash table,*/

                if (mp.ContainsKey(X - sum)) {

/*                    Making sure that all elements are
                    distinct array elements and an
                    element is not considered more than
                    once.*/

                    pair p = mp[X - sum];
                    if (p.first != i && p.first != j
                        && p.second != i && p.second != j) {
                        Console.Write(arr[i] + ", " + arr[j]
                                      + ", " + arr[p.first]
                                      + ", "
                                      + arr[p.second]);
                        return;
                    }
                }
            }
        }
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        int[] arr = { 10, 20, 30, 40, 1, 2 };
        int n = arr.Length;
        int X = 91;

/*        Function call*/

        findFourElements(arr, n, X);
    }
}

/*C# program to find four 
elements with the given sum*/

using System;
using System.Collections.Generic; 
class GFG
{

/*    Function to find 4 elements that add up to
    given sum*/

    static void fourSum(int X, int[] arr, Dictionary<int,
                        Tuple<int, int>> Map, int N)
    {
        int[] temp = new int[N];

/*        Iterate from 0 to temp.length*/

        for (int i = 0; i < N; i++)
            temp[i] = 0;

/*        Iterate from 0 to arr.length*/

        for (int i = 0; i < N - 1; i++)
        {

/*            Iterate from i + 1 to arr.length*/

            for (int j = i + 1; j < N; j++)
            {

/*                Store curr_sum = arr[i] + arr[j]*/

                int curr_sum = arr[i] + arr[j];

/*                Check if X - curr_sum if present
                in map*/

                if (Map.ContainsKey(X - curr_sum))
                {

/*                    Store pair having map value
                    X - curr_sum*/

                    Tuple<int, int> p = Map[X - curr_sum];

                    if (p.Item1 != i && p.Item2 != i
                        && p.Item1 != j && p.Item2 != j
                        && temp[p.Item1] == 0
                        && temp[p.Item2] == 0 && temp[i] == 0
                        && temp[j] == 0)
                    {

/*                        Print the output*/

                        Console.Write(arr[i] + "," + arr[j] +
                                      "," + arr[p.Item1] + "," +
                                      arr[p.Item2]);
                        temp[p.Item2] = 1;
                        temp[i] = 1;
                        temp[j] = 1;
                        break;
                    }
                }
            }
        }
    }

/*    Program for two Sum*/

    static Dictionary<int, Tuple<int, int>> twoSum(int[] nums, int N)
    {
        Dictionary<int, Tuple<int, int>> Map =
          new Dictionary<int, Tuple<int, int>>();
        for (int i = 0; i < N - 1; i++)
        {
            for (int j = i + 1; j < N; j++)
            {
                Map[nums[i] + nums[j]] = new Tuple<int, int>(i, j);
            }
        }
        return Map;
    }

/*  Driver code*/

  static void Main()
  {
    int[] arr = { 10, 20, 30, 40, 1, 2 };
    int n = arr.Length;
    int X = 91;
    Dictionary<int, Tuple<int, int>> Map = twoSum(arr, n);

/*    Function call*/

    fourSum(X, arr, Map, n);
  }
}

/*C# program to search an element
in an array where difference
between all elements is 1*/

using System;

public class GFG
{

/*    in arr[0..n-1]*/

    static int search(int []arr, int n,
                      int x)
    {

/*        Traverse the given array starting
        from leftmost element*/

        int i = 0;
        while (i < n)
        {

/*            If x is found at index i*/

            if (arr[i] == x)
                return i;

/*            Jump the difference between
            current array element and x*/

            i = i + Math.Abs(arr[i] - x);
        }

        Console.WriteLine ("number is not" +
                           " present!");

        return -1;
    }

/*    Driver code*/

    public static void Main()
    {

        int []arr = {8 ,7, 6, 7, 6, 5,
                     4,3, 2, 3, 4, 3 };
        int n = arr.Length;
        int x = 3;
        Console.WriteLine("Element " + x +
                        " is present at index "
                        + search(arr, n, 3));
    }
}

/*C# program to find third
Largest element in an array
of distinct elements*/

using System;

class GFG
{
static void thirdLargest(int []arr,
                         int arr_size)
{

/* There should be
    atleast three elements */

    if (arr_size < 3)
    {
        Console.Write(" Invalid Input ");
        return;
    }

/*    Find first
    largest element*/

    int first = arr[0];
    for (int i = 1;
             i < arr_size ; i++)
        if (arr[i] > first)
            first = arr[i];

/*    Find second
    largest element*/

    int second = -int.MaxValue;
    for (int i = 0;
             i < arr_size ; i++)
        if (arr[i] > second &&
            arr[i] < first)
            second = arr[i];

/*    Find third
    largest element*/

    int third = -int.MaxValue;
    for (int i = 0;
             i < arr_size ; i++)
        if (arr[i] > third &&
            arr[i] < second)
            third = arr[i];

    Console.Write("The third Largest " +
                  "element is "+ third);
}

/*Driver code*/

public static void Main()
{
    int []arr = {12, 13, 1,    
                 10, 34, 16};
    int n = arr.Length;
    thirdLargest(arr, n);
}
}

/*C# program to find third Largest element in an array*/

using System;
class GFG {

static void thirdLargest(int[] arr, int arr_size)
{

/* There should be atleast three elements */

    if (arr_size < 3)
    {
        Console.Write(" Invalid Input ");
        return;

    }

/*    Initialize first, second and third Largest element*/

    int first = arr[0], second = int.MinValue,
                            third = int.MinValue;

/*    Traverse array elements to find the third Largest*/

    for (int i = 1; i < arr_size; i++)
    {

/* If current element is greater than first,
        then update first, second and third */

        if (arr[i] > first) {
            third = second;
            second = first;
            first = arr[i];
        }

/* If arr[i] is in between first and second */

        else if (arr[i] > second) {
            third = second;
            second = arr[i];
        }

/* If arr[i] is in between second and third */

        else if (arr[i] > third) {
            third = arr[i];
        }
    }

    Console.Write("The third Largest element is "+ third);
}

/* Driver program to test above function */

public static void Main() {
        int[] arr = {12, 13, 1, 10, 34, 16};
        int n = arr.Length;
        thirdLargest(arr, n);
    }
}

/*C# program to find whether two elements exist
whose sum is equal to sum of rest of the elements.*/

using System;
using System.Collections.Generic;

class GFG
{

/*    Function to check whether two elements exist
    whose sum is equal to sum of rest of the elements.*/

    static bool checkPair(int []arr, int n)
    {

/*        Find sum of whole array*/

        int sum = 0;
        for (int i = 0; i < n; i++)
        {
            sum += arr[i];
        }

/*        If sum of array is not even than we can not
        divide it into two part*/

        if (sum % 2 != 0)
        {
            return false;
        }

        sum = sum / 2;

/*        For each element arr[i], see if there is
        another element with vaalue sum - arr[i]*/

        HashSet<int> s = new HashSet<int>();
        for (int i = 0; i < n; i++)
        {
            int val = sum - arr[i];

/*            If element exist than return the pair*/

            if (s.Contains(val))
            {
                Console.Write("Pair elements are {0} and {1}\n",
                        arr[i], val);
                return true;
            }
            s.Add(arr[i]);
        }
        return false;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        int []arr = {2, 11, 5, 1, 4, 7};
        int n = arr.Length;
        if (checkPair(arr, n) == false)
        {
            Console.Write("No pair found");
        }
    }
}

/*C# implementation to search an 
element in the unsorted array 
using minimum number of comparisons*/

using System;

class GFG {

/*    Function to search an element in
    minimum number of comparisons*/

    static String search(int[] arr, int n, int x)
    {

/*        1st comparison*/

        if (arr[n - 1] == x)
            return "Found";

        int backup = arr[n - 1];
        arr[n - 1] = x;

/*        no termination condition and thus
        no comparison*/

        for (int i = 0;; i++) {

/*            this would be executed at-most n times
            and therefore at-most n comparisons*/

            if (arr[i] == x) {

/*                replace arr[n-1] with its actual element
                as in original 'arr[]'*/

                arr[n - 1] = backup;

/*                if 'x' is found before the '(n-1)th'
                index, then it is present in the array
                final comparison*/

                if (i < n - 1)
                    return "Found";

/*                else not present in the array*/

                return "Not Found";
            }
        }
    }

/*    driver program*/

    public static void Main()
    {
        int[] arr = { 4, 6, 1, 5, 8 };
        int n = arr.Length;
        int x = 1;
        Console.WriteLine(search(arr, n, x));
    }
}

/*C# program to find the only repeated element
and number of times it appears*/

using System;
using System.Collections.Generic;

public class Point
{
    public int first, second;

        public Point(int first, int second)
        {
            this.first = first;
            this.second = second;
        }


}
public class Test
{

/*    Assumptions : vector a is sorted, max-difference
    of two adjacent elements is 1*/

    static Point sequence(List<int> a)
    {
        if (a.Count == 0)
            return new Point(0, 0);

        int s = 0;
        int e = a.Count - 1;
        while (s < e)
        {
            int m = (s + e) / 2;

/*            if a[m] = m + a[0], there is no
            repeating character in [s..m]*/

            if (a[m] >= m + a[0])
                s = m + 1;

/*        if a[m] < m + a[0], there is a
        repeating character in [s..m]*/

            else
                e = m;
        }
        return new Point(a[s], a.Count - (a[a.Count - 1] - a[0]));
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        int []array = new int[]{1, 2, 3, 4, 4, 4, 5, 6};
        Point p = sequence(new List<int>(array));
        Console.WriteLine("Repeated element is " + p.first +
                        ", it appears " + p.second + " times");
    }
}

