        int []b = new int[]{10, 13, 14};
        int n = a.Length;
        int m = b.Length;

/*        we need to define the smaller
        array as the first parameter
        to make sure that the time
        complexity will be O(log(min(n,m)))*/

        if (n < m)
            Console.Write ("The median is: " +
                            findMedianSortedArrays(ref a, n,
                                                   ref b, m));
        else
            Console.Write ("The median is: " +
                            findMedianSortedArrays(ref b, m,
                                                   ref a, n));
    }
}

/*C# program to find uncommon elements
of two sorted arrays*/

using System;
class GFG {

static void printUncommon(int []arr1,
                          int []arr2,
                          int n1,
                          int n2)
    {

        int i = 0, j = 0, k = 0;
        while (i < n1 && j < n2)
        {

/*            If not common, print smaller*/

            if (arr1[i] < arr2[j])
            {
                Console.Write(arr1[i] + " ");
                i++;
                k++;
            }
            else if (arr2[j] < arr1[i])
            {
                Console.Write(arr2[j] + " ");
                k++;
                j++;
            }

/*            Skip common element*/

            else
            {
                i++;
                j++;
            }
        }

/*        printing remaining elements*/

        while (i < n1)
        {
            Console.Write(arr1[i] + " ");
            i++;
            k++;
        }
        while (j < n2)
        {
            Console.Write(arr2[j] + " ");
            j++;
            k++;
        }
    }

/*    Driver Code*/

    public static void Main()
    {
        int []arr1 = {10, 20, 30};
        int []arr2 = {20, 25, 30, 40, 50};

        int n1 = arr1.Length;
        int n2 = arr2.Length;

        printUncommon(arr1, arr2, n1, n2);
    }
}

/*C# program to find the least
frequent element in an array.*/

using System;

class GFG {

    static int leastFrequent(int[] arr, int n)
    {

/*        Sort the array*/

        Array.Sort(arr);

/*        find the min frequency
        using linear traversal*/

        int min_count = n + 1, res = -1;
        int curr_count = 1;

        for (int i = 1; i < n; i++)
        {
            if (arr[i] == arr[i - 1])
                curr_count++;
            else
            {
                if (curr_count < min_count)
                {
                    min_count = curr_count;
                    res = arr[i - 1];
                }

                curr_count = 1;
            }
        }

/*        If last element is least frequent*/

        if (curr_count < min_count)
        {
            min_count = curr_count;
            res = arr[n - 1];
        }

        return res;
    }

/*    Driver code*/

    static public void Main ()
    {
        int[] arr = {1, 3, 2, 1, 2, 2, 3, 1};
        int n = arr.Length;
        Console.Write(leastFrequent(arr, n));
    }
}

/*C# program to find the
least frequent element
in an array.*/

using System;
using System.Collections.Generic;

class GFG
{
    static int leastFrequent(int []arr,
                             int n)
    {

/*        Insert all elements in hash.*/

        Dictionary<int, int> count =
                        new Dictionary<int,
                                       int>();
        for (int i = 0; i < n; i++)
        {
            int key = arr[i];
            if(count.ContainsKey(key))
            {
                int freq = count[key];
                freq++;
                count[key] = freq;
            }
            else
                count.Add(key, 1);
        }

/*        find the min frequency*/

        int min_count = n + 1, res = -1;
        foreach (KeyValuePair<int,
                    int> pair in count)
        {
            if (min_count >= pair.Value)
            {
                res = pair.Key;
                min_count = pair.Value;
            }
        }
        return res;
    }

/*    Driver Code*/

    static void Main()
    {
        int []arr = new int[]{1, 3, 2, 1,
                              2, 2, 3, 1};
        int n = arr.Length;
        Console.Write(leastFrequent(arr, n));
    }
}

/*C# program to find maximum
sum by selecting a element
from n arrays*/

using System;

class GFG
{
    static int M = 4;

    static void sort(ref int[,] a,
                     int row, int n)
    {
        for (int i = 0; i < M-1; i++)
        {
            if(a[row, i] > a[row, i + 1])
            {
                int temp = a[row, i];
                a[row, i] = a[row, i + 1];
                a[row, i + 1] = temp;
            }
        }
    }

/*    To calculate maximum
    sum by selecting
    element from each array*/

    static int maximumSum(int[,] a,
                          int n)
    {

    int i = 0, j = 0;

/*    Sort each array*/

    for (i = 0; i < n; i++)
        sort(ref a, i, n);

/*    Store maximum element
    of last array*/

    int sum = a[n - 1, M - 1];
    int prev = a[n - 1, M - 1];

/*    Selecting maximum element
    from previoulsy selected
    element*/

    for (i = n - 2; i >= 0; i--)
    {
        for (j = M - 1; j >= 0; j--)
        {
        if (a[i, j] < prev)
        {
            prev = a[i, j];
            sum += prev;
            break;
        }
        }

/*        j = -1 means no element
        is found in a[i] so
        return 0*/

        if (j == -1)
        return 0;
    }

    return sum;
    }

/*    Driver Code*/

    static void Main()
    {
    int [,]arr = new int[,]{{1, 7, 3, 4},
                            {4, 2, 5, 1},
                            {9, 5, 1, 8}};
    int n = arr.GetLength(0);
    Console.Write(maximumSum(arr, n));
    }
}

/*C# program to find
maximum sum by selecting
a element from n arrays*/

using System;
class GFG
{
  static int M = 4;

/*  To calculate maximum sum
  by selecting element from
  each array*/

  static int maximumSum(int[,] a, int n)
  {

/*    Store maximum element
    of last array*/

    int prev = Math.Max(a[n - 1, 0],
                        a[n - 1, M - 1] + 1);

/*    Selecting maximum element from
    previoulsy selected element*/

    int sum = prev;
    for(int i = n - 2; i >= 0; i--)
    {
      int max_smaller = Int32.MinValue;
      for(int j = M - 1; j >= 0; j--)
      {
        if(a[i, j] < prev && a[i, j] > max_smaller)
        {
          max_smaller = a[i, j];
        }
      }

/*      max_smaller equals to
      INT_MIN means no element
      is found in a[i] so return 0*/

      if(max_smaller == Int32.MinValue)
      {
        return 0;
      }
      prev = max_smaller;
      sum += max_smaller;
    }
    return sum;
  }

/*  Driver code*/

  static public void Main ()
  {
    int[,] arr = {{1, 7, 3, 4},{4, 2, 5, 1},{9, 5, 1, 8}};
    int n = arr.GetLength(0);
    Console.Write(maximumSum(arr, n));
  }
}

/*C# program to find pairs count*/

using System;

class GFG {

/*    function to count the required pairs*/

    static int countPairs(int []A, int n, int k)
    {
        int ans = 0;

/*        sort the given array*/

        Array.Sort(A);

/*        for each A[i] traverse rest array*/

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {

/*                count Aj such that Ai*k^x = Aj*/

                int x = 0;

/*                increase x till Ai * k^x <= largest element*/

                while ((A[i] * Math.Pow(k, x)) <= A[j])
                {
                    if ((A[i] * Math.Pow(k, x)) == A[j])
                    {
                        ans++;
                        break;
                    }
                    x++;
                }
            }
        }
        return ans;
    }

/*    Driver program*/

    public static void Main ()
    {
        int []A = {3, 8, 9, 12, 18, 4, 24, 2, 6};
        int n = A.Length;
        int k = 3;
        Console.WriteLine(countPairs(A, n, k));

    }
}

/*C# program to find Min distance
of maximum element*/

using System;

class GFG {

/*    function to return min distance*/

    static int minDistance (int []arr, int n)
    {
        int maximum_element = arr[0];
        int min_dis = n;
        int index = 0;

        for (int i = 1; i < n; i++)
        {

/*            case a*/

            if (maximum_element == arr[i])
            {
                min_dis = Math.Min(min_dis,
                                (i - index));
                index = i;
            }

/*            case b*/

            else if (maximum_element < arr[i])
            {
                maximum_element = arr[i];
                min_dis = n;
                index = i;
            }

/*            case c*/

            else
                continue;
        }

        return min_dis;
    }

/*    Driver code*/

    public static void Main ()
    {
        int []arr = {6, 3, 1, 3, 6, 4, 6};
        int n = arr.Length;

        Console.WriteLine("Minimum distance = "
                        + minDistance(arr, n));
    }
}

/*C# program to find value
