using System.Collections.Generic;

class GFG
{

    static long calculate(long []a, int n)
    {

/*        Sorting the whole array.*/

        Array.Sort(a);
        int i, j;

/*        Generating sum groups.*/

        List<long> s = new List<long>();
        for (i = 0, j = n - 1; i < j; i++, j--)
            s.Add((a[i] + a[j]));

        long mini = s.Min();
        long maxi = s.Max();
        return Math.Abs(maxi - mini);
    }

