/*        Find maximum and second maximum
        elements. Also find their counts.*/

        int maxVal = a[0], maxCount = 1;
        int secondMax = int.MinValue;
        int secondMaxCount = 0;
        for (int i = 1; i < n; i++)
        {
            if (a[i] == maxVal)
                maxCount++;
            else if (a[i] > maxVal)
            {
                secondMax = maxVal;
                secondMaxCount = maxCount;
                maxVal = a[i];
                maxCount = 1;
            }
            else if (a[i] == secondMax)
            {
                secondMax = a[i];
                secondMaxCount++;
            }
            else if (a[i] > secondMax)
            {
                secondMax = a[i];
                secondMaxCount = 1;
            }
        }

/*        If maximum element appears
        more than once.*/

        if (maxCount > 1)
            return maxCount *
                       (maxCount - 1) / 2;

/*        If maximum element appears
        only once.*/

        return secondMaxCount;
    }

/*    driver program*/

    public static void Main()
    {
        int []array = { 1, 1, 1, 2,
                               2, 2, 3 };
        int n = array.Length;

        Console.WriteLine(sum(array, n));
    }
}

/*C# for printing smallest n number in order*/

using System;    

class GFG
{

/*Function to print smallest n numbers*/

static void printSmall(int []arr, int asize, int n)
{

/*    Make copy of array*/

    int []copy_arr = new int[asize];
    Array.Copy(arr, copy_arr, asize);

/*    Sort copy array*/

    Array.Sort(copy_arr);

/*    For each arr[i] find whether
    it is a part of n-smallest
    with binary search*/

    for (int i = 0; i < asize; ++i)
    {
        if (Array.BinarySearch(copy_arr, 0, n, arr[i])>-1)
            Console.Write(arr[i] + " ");
    }
}

/*Driver code*/

public static void Main(String[] args)
{
    int []arr = { 1, 5, 8, 9, 6, 7, 3, 4, 2, 0 };
    int asize = arr.Length;
    int n = 5;
    printSmall(arr, asize, n);
}
}

/*C# program to find missing
k numbers in an array.*/

using System;

class GFG {

/*    Prints first k natural numbers
    in arr[0..n-1]*/

    static void printKMissing(int[] arr,
                              int n,
                              int k)
    {
        Array.Sort(arr);

/*        Find first positive number*/

        int i = 0;
        while (i < n && arr[i] <= 0)
            i++;

/*        Now find missing numbers
        between array elements*/

        int count = 0, curr = 1;
        while (count < k && i < n) {
            if (arr[i] != curr) {
                Console.Write(curr + " ");
                count++;
            }
            else
                i++;
            curr++;
        }

/*        Find missing numbers
        after maximum.*/

        while (count < k) {
            Console.Write(curr + " ");
            curr++;
            count++;
        }
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = {2, 3, 4};
        int n = arr.Length;
        int k = 3;
        printKMissing(arr, n, k);
    }
}

/*C# code for
the above approach*/

using System;
using System.Collections.Generic;

public class GFG
{

/*  Program to print first k
  missing number*/

  static void printmissingk(int[] arr, int n, int k)
  {

/*    Creating a hashmap*/

    Dictionary<int,int> d = new Dictionary<int,int>();

/*    Iterate over array*/

    for (int i = 0; i < n; i++)
    {
      d.Add(arr[i], arr[i]);
    }
    int cnt = 1;
    int fl = 0;

/*    Iterate to find missing
    element*/

    for (int i = 0; i < (n + k); i++)
    {
      if (!d.ContainsKey(cnt))
      {
        fl += 1;
        Console.Write(cnt + " ");
        if (fl == k)
          break;
      }
      cnt += 1;
    }
  }

/*  Driver Code*/

  static public void Main (){
    int[] arr = { 1, 4, 3 };
    int n = arr.Length;
    int k = 3;
    printmissingk(arr, n, k);
  }
}

/*C# program to find Noble elements
in an array.*/

using System;

class GFG {

/*    Returns a Noble integer if present,
    else returns -1.*/

    public static int nobleInteger(int [] arr)
    {
        int size = arr.Length;
        for (int i = 0; i < size; i++ )
        {
            int count = 0;
            for (int j = 0; j < size; j++)
                if (arr[i] < arr[j])
                    count++;

/*            If count of greater elements
            is equal to arr[i]*/

            if (count == arr[i])
                return arr[i];
        }

        return -1;
    }

/*    Driver code*/

    public static void Main()
    {
        int [] arr = {10, 3, 20, 40, 2};
        int res = nobleInteger(arr);
        if (res != -1)
            Console.Write("The noble integer"
                              + " is "+ res);
        else
            Console.Write("No Noble Integer"
                                 + " Found");
    }
}

/*C# program to find Noble elements
in an array.*/

using System;

public class GFG {

/*Returns a Noble integer if present,
else returns -1.*/


    public static int nobleInteger(int[] arr)
    {
        Array.Sort(arr);

/*        Return a Noble element if present
        before last.*/

        int n = arr.Length;
        for (int i = 0; i < n-1; i++)
        {
            if (arr[i] == arr[i+1])
                continue;

/*            In case of duplicates, we
            reach last occurrence here.*/

            if (arr[i] == n-i-1)
                return arr[i];
        }

        if (arr[n-1] == 0)
            return arr[n-1];

        return -1;
    }

/*    Driver code*/

    static public void Main ()
    {
        int [] arr = {10, 3, 20, 40, 2};
        int res = nobleInteger(arr);
        if (res != -1)
        Console.Write("The noble integer is "
                                      + res);
        else
            Console.Write("No Noble Integer "
                                  + "Found");

    }
}

/*C# program to find minimum sum of
absolute differences of two arrays.*/

using System;

class MinSum {

/*    Returns minimum possible pairwise
    absolute difference of two arrays.*/

    static long findMinSum(long []a, long []b,
                           long n)
    {

/*        Sort both arrays*/

        Array.Sort(a);
        Array.Sort(b);

/*        Find sum of absolute differences*/

        long sum = 0 ;
        for (int i = 0; i < n; i++)
            sum = sum + Math.Abs(a[i] - b[i]);

        return sum;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/*        Both a[] and b[] must be of same size.*/

        long []a = {4, 1, 8, 7};
        long []b = {2, 3, 6, 5};
        int n = a.Length;
        Console.Write(findMinSum(a, b, n));
    }
}

/*C# program to check if a given array
can form arithmetic progression*/

using System;

class GFG {

/*    Returns true if a permutation of
    arr[0..n-1] can form arithmetic
    progression*/

    static bool checkIsAP(int []arr, int n)
    {
        if (n == 1)
            return true;

/*        Sort array*/

        Array.Sort(arr);

/*        After sorting, difference between
        consecutive elements must be same.*/

        int d = arr[1] - arr[0];
        for (int i = 2; i < n; i++)
            if (arr[i] - arr[i - 1] != d)
                return false;

        return true;
    }

/*    Driver Code*/

    public static void Main ()
    {
        int []arr = {20, 15, 5, 0, 10};
        int n = arr.Length;

        if(checkIsAP(arr, n))
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*C# program to find maximum product of
a subset.*/

using System;

public class GFG {

    static int minProductSubset(int[] a, int n)
    {
        if (n == 1)
            return a[0];

/*        Find count of negative numbers,
        count of zeros, maximum valued
        negative number, minimum valued
        positive number and product of
        non-zero numbers*/

        int negmax = int.MinValue;
        int posmin = int.MinValue;
        int count_neg = 0, count_zero = 0;
        int product = 1;

        for (int i = 0; i < n; i++) {

/*            if number is zero, count it
            but dont multiply*/

            if (a[i] == 0) {
                count_zero++;
                continue;
            }

/*            count the negative numbers
            and find the max negative number*/

            if (a[i] < 0) {
                count_neg++;
                negmax = Math.Max(negmax, a[i]);
            }

/*            find the minimum positive number*/

            if (a[i] > 0 && a[i] < posmin) {
                posmin = a[i];
            }

            product *= a[i];
        }

/*        if there are all zeroes
        or zero is present but no
        negative number is present*/

        if (count_zero == n
            || (count_neg == 0 && count_zero > 0))
            return 0;

/*        If there are all positive*/

        if (count_neg == 0)
            return posmin;

/*        If there are even number except
        zero of negative numbers*/

        if (count_neg % 2 == 0 && count_neg != 0) {

/*            Otherwise result is product of
            all non-zeros divided by maximum
            valued negative.*/

            product = product / negmax;
        }

        return product;
    }

/*    main function*/

    public static void Main()
    {

        int[] a = new int[] { -1, -1, -2, 4, 3 };
        int n = 5;

        Console.WriteLine(minProductSubset(a, n));
    }
}

/*C# Code to find no. of Ways of choosing
a pair with maximum difference*/

using System;

class GFG {

    static int countPairs(int[] a, int n)
    {

/*        To find minimum and maximum of
        the array*/

        int mn = int.MaxValue;
        int mx = int.MinValue;
        for (int i = 0; i < n; i++) {
            mn = Math.Min(mn, a[i]);
            mx = Math.Max(mx, a[i]);
        }

/*        to find the count of minimum and
        maximum elements*/

        int c1 = 0;

/*Count variables*/

int c2 = 0; 
        for (int i = 0; i < n; i++) {
            if (a[i] == mn)
                c1++;
            if (a[i] == mx)
                c2++;
        }

/*        condition for all elements equal*/

        if (mn == mx)
            return n * (n - 1) / 2;
        else
            return c1 * c2;
    }

/*    Driver code*/

    public static void Main()
    {

        int[] a = { 3, 2, 1, 1, 3 };
        int n = a.Length;

        Console.WriteLine(countPairs(a, n));
    }
}

/*C# program to repeatedly search an
element by doubling it after every
successful search*/

using System;

public class GFG {

    static int findElement(int[] a,
                           int n, int b)
    {

/*        Sort the given array so that
        binary search can be applied
        on it*/

        Array.Sort(a);

/*        Maximum array element*/

        int max = a[n - 1];

        while (b < max) {

/*            search for the element b
            present or not in array*/

            if (Array.BinarySearch(a, b) > -1)
                b *= 2;
            else
                return b;
        }

        return b;
    }

/*    Driver code*/

    public static void Main()
    {
        int[] a = { 1, 2, 3 };
        int n = a.Length;
        int b = 1;
        Console.WriteLine(findElement(a, n, b));
    }
}

/*C# program for above implementation*/

using System;

class GFG {

    static int Mod = 1000000007;

/*    Function to find the maximum sum*/

    static long findSum(int[] arr, int n)
    {
        long sum = 0;

/*        Sort the array first*/

        Array.Sort(arr);

/*        First multiply negative numbers
        pairwise and sum up from starting
        as to get maximum sum.*/

        int i = 0;
        while (i < n && arr[i] < 0) {
            if (i != n - 1 && arr[i + 1] <= 0) {
                sum = (sum + (arr[i] * arr[i + 1]) % Mod) % Mod;
                i += 2;
            }
            else
                break;
        }

/*        Second multiply positive numbers
        pairwise and summed up from the
        last as to get maximum sum.*/

        int j = n - 1;
        while (j >= 0 && arr[j] > 0) {
            if (j != 0 && arr[j - 1] > 0) {
                sum = (sum + (arr[j] * arr[j - 1]) % Mod) % Mod;
                j -= 2;
            }
            else
                break;
        }

/*        To handle case if positive and negative
        numbers both are odd in counts.*/

        if (j > i)
            sum = (sum + (arr[i] * arr[j]) % Mod) % Mod;

/*        If one of them occurs odd times*/

        else if (i == j)
            sum = (sum + arr[i]) % Mod;

        return sum;
    }

/*    Drivers code*/

    public static void Main()
    {
        int[] arr = { -1, 9, 4, 5, -4, 7 };
        int n = arr.Length;
        Console.WriteLine(findSum(arr, n));
    }
}

/*Recursive C# program to search
an element in linked list*/

using System;

/*Node class*/

public class Node
{
    public int data;
    public Node next;
    public Node(int d)
    {
        data = d;
        next = null;
    }
}

/*Linked list class*/

public class LinkedList
{

/*Head of list*/

Node head;

/*    Inserts a new node at the front of the list*/

    public void push(int new_data)
    {

/*        Allocate new node and putting data*/

        Node new_node = new Node(new_data);

/*        Make next of new node as head*/

        new_node.next = head;

/*        Move the head to point to new Node*/

        head = new_node;
    }

/*    Checks whether the value x is present
    in linked list*/

    public bool search(Node head, int x)
    {

/*        Base case*/

        if (head == null)
            return false;

/*        If key is present in current node,
        return true*/

        if (head.data == x)
            return true;

/*        Recur for remaining list*/

        return search(head.next, x);
    }

/*    Driver code*/

    public static void Main()
    {

/*        Start with the empty list*/

        LinkedList llist = new LinkedList();

/* Use push() to construct below list
        14->21->11->30->10 */

        llist.push(10);
        llist.push(30);
        llist.push(11);
        llist.push(21);
        llist.push(14);

        if (llist.search(llist.head, 21))
            Console.WriteLine("Yes");
        else
            Console.WriteLine("No");
    }
}

/*C# program to reverse a linked
list using two pointers.*/

using System;
using System.Collections;
using System.Collections.Generic;
class GFG
{

/*  Link list node*/

  class Node
  {
    public int data;
    public Node next;
  };

  static Node head_ref = null;

/*  Function to reverse the linked
  list using 2 pointers*/

  static void reverse()
  {
    Node prev = null;
    Node current = head_ref;

/*    At last prev points to new head*/

    while (current != null)
    {

/*      This expression evaluates from left to right
      current.next = prev, changes the link fron
      next to prev node
      prev = current, moves prev to current node for
      next reversal of node
      This example of list will clear it more 1.2.3.4
      initially prev = 1, current = 2
      Final expression will be current = 1^2^3^2^1,
      as we know that bitwise XOR of two same
      numbers will always be 0 i.e; 1^1 = 2^2 = 0
      After the evaluation of expression current = 3 that
      means it has been moved by one node from its
      previous position*/

      Node next = current.next;
      current.next = prev;
      prev = current;
      current = next;
    }
    head_ref = prev;
  }

/*  Function to push a node*/

  static void push(int new_data)
  {

/*    Allocate node*/

    Node new_node = new Node();

/*    Put in the data */

    new_node.data = new_data;

/*    Link the old list off the new node*/

    new_node.next = (head_ref);

/*    Move the head to point to the new node*/

    (head_ref) = new_node;
  }

/*  Function to print linked list*/

  static void printList()
  {
    Node temp = head_ref;
    while (temp != null)
    {
      Console.Write(temp.data + " ");
      temp = temp.next;
    }
  }

/*  Driver code*/

  public static void Main(string []args)
  {
    push(20);
    push(4);
    push(15);
    push(85);

    Console.Write("Given linked list\n");
    printList();
    reverse();
    Console.Write("\nReversed Linked list \n");
    printList();
  }
}

/*C# program to rearrange nodes
as alternate odd even nodes in
a Singly Linked List*/

using System;
using System.Collections.Generic;

class GFG
{

/*class node*/

public class Node
{
    public int data;
    public Node next;
}

/*A utility function to print
linked list*/

static void printList(Node node)
{
    while (node != null)
    {
        Console.Write(node.data +" ");
        node = node.next;
    }
    Console.WriteLine();
}

/*Function to create newNode
in a linkedlist*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/*Function to insert at beginning*/

static Node insertBeg(Node head, int val)
{
    Node temp = newNode(val);
    temp.next = head;
    head = temp;
    return head;
}

/*Function to rearrange the
odd and even nodes*/

static void rearrangeOddEven(Node head)
{
    Stack<Node> odd = new Stack<Node>();
    Stack<Node> even = new Stack<Node>();
    int i = 1;

    while (head != null)
    {

        if (head.data % 2 != 0 && i % 2 == 0)
        {

/*            Odd Value in Even Position
            Add pointer to current node
            in odd stack*/

            odd.Push(head);
        }

        else if (head.data % 2 == 0 && i % 2 != 0)
        {

/*            Even Value in Odd Position
            Add pointer to current node
            in even stack*/

            even.Push(head);
        }

        head = head.next;
        i++;
    }

    while (odd.Count > 0 && even.Count > 0)
    {

/*        Swap Data at the top of two stacks*/

        int k=odd.Peek().data;
        odd.Peek().data=even.Peek().data;
        even.Peek().data=k;
        odd.Pop();
        even.Pop();
    }
}

/*Driver code*/

public static void Main(String []args)
{
    Node head = newNode(8);
    head = insertBeg(head, 7);
    head = insertBeg(head, 6);
    head = insertBeg(head, 5);
    head = insertBeg(head, 3);
    head = insertBeg(head, 2);
    head = insertBeg(head, 1);

    Console.WriteLine( "Linked List:" );
    printList(head);
    rearrangeOddEven(head);

    Console.WriteLine( "Linked List after "+
                        "Rearranging:" );
    printList(head);
}
}

/*C# program to rearrange nodes
as alternate odd even nodes in
a Singly Linked List*/

using System;

class GFG
{

/*Structure node*/

public class Node
{
    public int data;
    public Node next;
};

/*A utility function to print
linked list*/

static void printList(Node node)
{
    while (node != null)
    {
        Console.Write(node.data + " ");
        node = node.next;
    }
    Console.WriteLine();
}

/*Function to create newNode
in a linkedlist*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/*Function to insert at beginning*/

static Node insertBeg(Node head, int val)
{
    Node temp = newNode(val);
    temp.next = head;
    head = temp;
    return head;
}

/*Function to rearrange the
odd and even nodes*/

static Node rearrange(Node head)
{

/*    Step 1: Segregate even and odd nodes
    Step 2: Split odd and even lists
    Step 3: Merge even list into odd list*/

    Node even;
    Node temp, prev_temp;
    Node i, j, k, l, ptr=null;

/*    Step 1: Segregate Odd and Even Nodes*/

    temp = (head).next;
    prev_temp = head;

    while (temp != null)
    {

/*        Backup next pointer of temp*/

        Node x = temp.next;

/*        If temp is odd move the node
        to beginning of list*/

        if (temp.data % 2 != 0)
        {
            prev_temp.next = x;
            temp.next = (head);
            (head) = temp;
        }
        else
        {
            prev_temp = temp;
        }

/*        Advance Temp Pointer*/

        temp = x;
    }

/*    Step 2
    Split the List into Odd and even*/

    temp = (head).next;
    prev_temp = (head);

    while (temp != null && temp.data % 2 != 0)
    {
        prev_temp = temp;
        temp = temp.next;
    }

    even = temp;

/*    End the odd List (Make last node null)*/

    prev_temp.next = null;

/*    Step 3:
    Merge Even List into odd*/

    i = head;
    j = even;

    while (j != null && i != null)
    {

/*        While both lists are not
        exhausted Backup next
        pointers of i and j*/

        k = i.next;
        l = j.next;

        i.next = j;
        j.next = k;

/*        ptr points to the latest node added*/

        ptr = j;

/*        Advance i and j pointers*/

        i = k;
        j = l;
    }

    if (i == null)
    {

/*        Odd list exhausts before even,
        append remainder of even list to odd.*/

        ptr.next = j;
    }

/*    The case where even list exhausts before
    odd list is automatically handled since we
    merge the even list into the odd list*/

    return head;
}

/*Driver Code*/

public static void Main(String []args)
{
    Node head = newNode(8);
    head = insertBeg(head, 7);
    head = insertBeg(head, 6);
    head = insertBeg(head, 3);
    head = insertBeg(head, 5);
    head = insertBeg(head, 1);
    head = insertBeg(head, 2);
    head = insertBeg(head, 10);

    Console.WriteLine("Linked List:" );
    printList(head);
    Console.WriteLine("Rearranged List" );
    head=rearrange(head);
    printList(head);
}
}

/*An iterative C# program to
check if two linked lists
are identical or not*/

using System;

/* Linked list Node*/

    public class Node
    {
        public int data;
        public Node next;
        public Node(int d)
        {
            data = d; next = null;
        }
    }

/*head of list*/
public class LinkedList
{
Node head;

/* Returns true if linked lists
    a and b are identical,
    otherwise false */

    bool areIdentical(LinkedList listb)
    {
        Node a = this.head, b = listb.head;
        while (a != null && b != null)
        {
            if (a.data != b.data)
                return false;

/* If we reach here, then a and b are not null
            and their data is same, so move to next nodes
            in both lists */

            a = a.next;
            b = b.next;
        }

/*        If linked lists are identical,
        then 'a' and 'b' must
        be null at this point.*/

        return (a == null && b == null);
    }

/* UTILITY FUNCTIONS TO TEST fun1() and fun2() */

/* Given a reference (pointer to pointer) to the head
        of a list and an int, push a new node on the front
        of the list. */


    void push(int new_data)
    {

/* 1 & 2: Allocate the Node &
                Put in the data*/

        Node new_node = new Node(new_data);

/* 3. Make next of new Node as head */

        new_node.next = head;

/* 4. Move the head to point to new Node */

        head = new_node;
    }

/* Driver code */

    public static void Main(String []args)
    {
        LinkedList llist1 = new LinkedList();
        LinkedList llist2 = new LinkedList();

/* The constructed linked lists are :
        llist1: 3->2->1
        llist2: 3->2->1 */


        llist1.push(1);
        llist1.push(2);
        llist1.push(3);

        llist2.push(1);
        llist2.push(2);
        llist2.push(3);

        if (llist1.areIdentical(llist2) == true)
            Console.WriteLine("Identical ");
        else
            Console.WriteLine("Not identical ");
    }
}

/*C# program to rotate
a linked list counter clock wise*/

using System;

class GFG{

/* Link list node */

public class Node {

    public int data;
    public Node next;
};
static  Node head = null;

/*This function rotates a linked list
counter-clockwise and updates the
head. The function assumes that k is
smaller than size of linked list.*/

static void rotate( int k)
{
    if (k == 0)
        return;

/*    Let us understand the below
    code for example k = 4 and
    list = 10.20.30.40.50.60.*/

    Node current = head;

/*    Traverse till the end.*/

    while (current.next != null)
        current = current.next;

    current.next = head;
    current = head;

/*    traverse the linked list to k-1 position which
    will be last element for rotated array.*/

    for (int i = 0; i < k - 1; i++)
        current = current.next;

/*    update the head_ref and last element pointer to null*/

    head = current.next;
    current.next = null;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

static void push(int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list off the new node */

    new_node.next = head;

/* move the head to point to the new node */

    head = new_node;
}

/* Function to print linked list */

static void printList(Node node)
{
    while (node != null)
    {
        Console.Write(node.data + " ");
        node = node.next;
    }
}

/* Driver code*/

public static void  Main(String[] args)
{

/* Start with the empty list */

/*    create a list 10.20.30.40.50.60*/

    for (int i = 60; i > 0; i -= 10)
        push( i);

    Console.Write("Given linked list \n");
    printList(head);
    rotate( 4);

    Console.Write("\nRotated Linked list \n");
    printList(head);
}
}

/*C# program for flattening a Linked List*/

using System;
public class List {

/*head of list*/

Node head;

/* Linked list Node */

    public


 class Node {
        public


 int data;
        public


 Node right, down;

        public


 Node(int data) {
            this.data = data;
            right = null;
            down = null;
        }
    }

/*    An utility function to merge two sorted linked lists*/

    Node merge(Node a, Node b) {

/*        if first linked list is empty then second
        is the answer*/

        if (a == null)
            return b;

/*        if second linked list is empty then first
        is the result*/

        if (b == null)
            return a;

/*        compare the data members of the two linked lists
        and put the larger one in the result*/

        Node result;

        if (a.data < b.data) {
            result = a;
            result.down = merge(a.down, b);
        }

        else {
            result = b;
            result.down = merge(a, b.down);
        }

        result.right = null;
        return result;
    }

    Node flatten(Node root) {

/*        Base Cases*/

        if (root == null || root.right == null)
            return root;

/*        recur for list on right*/

        root.right = flatten(root.right);

/*        now merge*/

        root = merge(root, root.right);

/*        return the root
        it will be in turn merged with its left*/

        return root;
    }

/*
     * Utility function to insert a node at beginning of the linked list
     */

    Node Push(Node head_ref, int data) {

/*
         * 1 & 2: Allocate the Node & Put in the data
         */

        Node new_node = new Node(data);

/* 3. Make next of new Node as head */

        new_node.down = head_ref;

/* 4. Move the head to point to new Node */

        head_ref = new_node;

/* 5. return to link it back */

        return head_ref;
    }

    void printList() {
        Node temp = head;
        while (temp != null) {
            Console.Write(temp.data + " ");
            temp = temp.down;
        }
        Console.WriteLine();
    }

/* Driver program to test above functions */

    public static void Main(String []args) {
        List L = new List();

/*
         * Let us create the following linked list 5 -> 10 -> 19 -> 28 | | | | V V V V 7
         * 20 22 35 | | | V V V 8 50 40 | | V V 30 45
         */


        L.head = L.Push(L.head, 30);
        L.head = L.Push(L.head, 8);
        L.head = L.Push(L.head, 7);
        L.head = L.Push(L.head, 5);

        L.head.right = L.Push(L.head.right, 20);
        L.head.right = L.Push(L.head.right, 10);

        L.head.right.right = L.Push(L.head.right.right, 50);
        L.head.right.right = L.Push(L.head.right.right, 22);
        L.head.right.right = L.Push(L.head.right.right, 19);

        L.head.right.right.right = L.Push(L.head.right.right.right, 45);
        L.head.right.right.right = L.Push(L.head.right.right.right, 40);
        L.head.right.right.right = L.Push(L.head.right.right.right, 35);
        L.head.right.right.right = L.Push(L.head.right.right.right, 20);

/*        flatten the list*/

        L.head = L.flatten(L.head);

        L.printList();
    }
}

/*C# program to sort a linked
list of 0, 1 and 2*/

using System;

public class LinkedList
{

/*head of list*/

Node head;

/* Linked list Node*/

    class Node
    {
        public int data;
        public Node next;
        public Node(int d)
        {
            data = d; next = null;
        }
    }

    void sortList()
    {

/*        initialise count of 0 1 and 2 as 0*/

        int []count = {0, 0, 0};

        Node ptr = head;

/* count total number of '0', '1' and '2'
        * count[0] will store total number of '0's
        * count[1] will store total number of '1's
        * count[2] will store total number of '2's */

        while (ptr != null)
        {
               count[ptr.data]++;
            ptr = ptr.next;
        }

        int i = 0;
        ptr = head;

/* Let say count[0] = n1, count[1] = n2 and count[2] = n3
        * now start traversing list from head node,
        * 1) fill the list with 0, till n1 > 0
        * 2) fill the list with 1, till n2 > 0
        * 3) fill the list with 2, till n3 > 0 */

        while (ptr != null)
        {
            if (count[i] == 0)
                i++;
            else
            {
                ptr.data= i;
                --count[i];
                ptr = ptr.next;
            }
        }
    }

/* Inserts a new Node at front of the list. */

    public void push(int new_data)
    {

/* 1 & 2: Allocate the Node &
                Put in the data*/

        Node new_node = new Node(new_data);

/* 3. Make next of new Node as head */

        new_node.next = head;

/* 4. Move the head to point to new Node */

        head = new_node;
    }

/* Function to print linked list */

    void printList()
    {
        Node temp = head;
        while (temp != null)
        {
            Console.Write(temp.data+" ");
            temp = temp.next;
        }
        Console.WriteLine();
    }

/* Driver code */

    public static void Main(String []args)
    {
        LinkedList llist = new LinkedList();

/* Constructed Linked List is 1->2->3->4->
        5->6->7->8->8->9->null */

        llist.push(0);
        llist.push(1);
        llist.push(0);
        llist.push(2);
        llist.push(1);
        llist.push(1);
        llist.push(2);
        llist.push(1);
        llist.push(2);

        Console.WriteLine("Linked List before sorting");
        llist.printList();

        llist.sortList();

        Console.WriteLine("Linked List after sorting");
        llist.printList();
    }
}

