/*C# code to rearrange linked list in place*/

using System;

class GFG {

    class Node {
        public int data;
        public Node next;
    }

/*    Function for rearranging a linked list
    with high and low value.*/

    static Node rearrange(Node head)
    {

/*        Base case*/

        if (head == null)
            return null;

/*        Two pointer variable.*/

        Node prev = head, curr = head.next;

        while (curr != null) {

/*            Swap function for swapping data.*/

            if (prev.data > curr.data) {
                int t = prev.data;
                prev.data = curr.data;
                curr.data = t;
            }

/*            Swap function for swapping data.*/

            if (curr.next != null
                && curr.next.data > curr.data) {
                int t = curr.next.data;
                curr.next.data = curr.data;
                curr.data = t;
            }

            prev = curr.next;

            if (curr.next == null)
                break;

            curr = curr.next.next;
        }
        return head;
    }

/*    Function to insert a Node in
    the linked list at the beginning.*/

    static Node push(Node head, int k)
    {
        Node tem = new Node();
        tem.data = k;
        tem.next = head;
        head = tem;
        return head;
    }

/*    Function to display Node of linked list.*/

    static void display(Node head)
    {
        Node curr = head;

        while (curr != null) {
            Console.Write(curr.data + " ");
            curr = curr.next;
        }
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        Node head = null;

/*        Let create a linked list.
        9 . 6 . 8 . 3 . 7*/

        head = push(head, 7);
        head = push(head, 3);
        head = push(head, 8);
        head = push(head, 6);
        head = push(head, 9);

        head = rearrange(head);

        display(head);
    }
}

/*C# implementation*/

using System;

/*Creating the structure for node*/

public class Node
{
    public int data;
    public Node next;
    public Node(int key)
    {
        data = key;
        next = null;
    }
}

class GFG{

Node left = null;

/*Function to print the list*/

void printlist(Node head)
{
    while (head != null)
    {
        Console.Write(head.data + " ");
        if (head.next != null)
        {
            Console.Write("->");
        }
        head = head.next;
    }
    Console.WriteLine();
}

/*Function to rearrange*/

void rearrange(Node head)
{

    if (head != null)
    {
        left = head;
        reorderListUtil(left);
    }
}

void reorderListUtil(Node right)
{

    if (right == null)
    {
        return;
    }

    reorderListUtil(right.next);

/*    We set left = null, when we reach stop
    condition, so no processing required
    after that*/

    if (left == null)
    {
        return;
    }

/*    Stop condition: odd case : left = right, even
    case : left.next = right*/

    if (left != right && left.next != right)
    {
        Node temp = left.next;
        left.next = right;
        right.next = temp;
        left = temp;
    }
    else
    {

/*        Stop condition , set null to left nodes*/

        if (left.next == right)
        {

/*            Even case*/

            left.next.next = null;
            left = null;
        }
        else
        {

/*            Odd case*/

            left.next = null;
            left = null;
        }
    }
}

