/*C# program to rearrange a linked list
in such a way that all odd positioned
node are stored before all even positioned nodes*/

using System;

class GfG
{

/*    Linked List Node*/

    class Node
    {
        public int data;
        public Node next;
    }

/*    A utility function to create a new node*/

    static Node newNode(int key)
    {
        Node temp = new Node();
        temp.data = key;
        temp.next = null;
        return temp;
    }

/*    Rearranges given linked list
    such that all even positioned
    nodes are before odd positioned.
    Returns new head of linked List.*/

    static Node rearrangeEvenOdd(Node head)
    {

/*        Corner case*/

        if (head == null)
            return null;

/*        Initialize first nodes of even and
        odd lists*/

        Node odd = head;
        Node even = head.next;

/*        Remember the first node of even list so
        that we can connect the even list at the
        end of odd list.*/

        Node evenFirst = even;

        while (1 == 1)
        {

/*            If there are no more nodes,
            then connect first node of even
            list to the last node of odd list*/

            if (odd == null || even == null ||
                            (even.next) == null)
            {
                odd.next = evenFirst;
                break;
            }

/*            Connecting odd nodes*/

            odd.next = even.next;
            odd = even.next;

/*            If there are NO more even nodes
            after current odd.*/

            if (odd.next == null)
            {
                even.next = null;
                odd.next = evenFirst;
                break;
            }

/*            Connecting even nodes*/

            even.next = odd.next;
            even = odd.next;
        }
        return head;
    }

/*    A utility function to print a linked list*/

    static void printlist(Node node)
    {
        while (node != null)
        {
            Console.Write(node.data + "->");
            node = node.next;
        }
        Console.WriteLine("NULL") ;
    }

/*    Driver code*/

    public static void Main()
    {
        Node head = newNode(1);
        head.next = newNode(2);
        head.next.next = newNode(3);
        head.next.next.next = newNode(4);
        head.next.next.next.next = newNode(5);

        Console.WriteLine("Given Linked List");
        printlist(head);

        head = rearrangeEvenOdd(head);

        Console.WriteLine("Modified Linked List");
        printlist(head);
    }
}

/*C# program for the above approach*/

 using System;

/*Node class*/

public
 class Node
 {
   public
  int data;
   public
  Node next;
   public

  Node(int data)
   {
     this.data = data;
   }
}


public class GFG {

    private Node head;

/*    Print Linked List*/

    public void printLL()
    {
        Node t = head;
        while (t != null) {
            Console.Write(t.data + " ->");
            t = t.next;
        }
        Console.WriteLine();
    }

/*    Swap both nodes*/

    public void swap(Node a, Node b)
    {
        if (a == null || b == null)
            return;
        int temp = a.data;
        a.data = b.data;
        b.data = temp;
    }

/*    Rearrange the linked list
    in zig zag way*/

    public Node zigZag(Node node, int flag)
    {
        if (node == null || node.next == null) {
            return node;
        }
        if (flag == 0) {
            if (node.data > node.next.data) {
                swap(node, node.next);
            }
            return zigZag(node.next, 1);
        }
        else {
            if (node.data < node.next.data) {
                swap(node, node.next);
            }
            return zigZag(node.next, 0);
        }
    }

/*    Driver Code*/

    public static void Main(String[] args)
    {
        GFG lobj = new GFG();
        lobj.head = new Node(11);
        lobj.head.next = new Node(15);
        lobj.head.next.next = new Node(20);
        lobj.head.next.next.next = new Node(5);
        lobj.head.next.next.next.next = new Node(10);
        lobj.printLL();

/*        0 means the current element
        should be smaller than the next*/

        int flag = 0;
        lobj.zigZag(lobj.head, flag);
        Console.WriteLine("LL in zig zag fashion : ");
        lobj.printLL();
    }
}

/*Recursive C# program to add 1 to a linked list*/

using System;

class GfG
{

/* Linked list node */

    public class Node
    {
        public int data;
        public Node next;
    }

/* Function to create a new node with given data */

    public static Node newNode(int data)
    {
        Node new_node = new Node();
        new_node.data = data;
        new_node.next = null;
        return new_node;
    }

/*    Recursively add 1 from end to beginning and returns
    carry after all nodes are processed.*/

    public static int addWithCarry(Node head)
    {

/*        If linked list is empty, then
        return carry*/

        if (head == null)
            return 1;

/*        Add carry returned be next node call*/

        int res = head.data + addWithCarry(head.next);

/*        Update data and return new carry*/

        head.data = (res) % 10;
        return (res) / 10;
    }

/*    This function mainly uses addWithCarry().*/

    public static Node addOne(Node head)
    {

/*        Add 1 to linked list from end to beginning*/

        int carry = addWithCarry(head);
        Node newNodes = null;

/*        If there is carry after processing all nodes,
        then we need to add a new node to linked list*/

        if (carry > 0)
        {
            newNodes = newNode(carry);
            newNodes.next = head;

/*New node becomes head now*/

return newNodes; 
        }

        return head;
    }

/*    A utility function to print a linked list*/

    public static void printList(Node node)
    {
        while (node != null)
        {
            Console.Write(node.data);
            node = node.next;
        }
        Console.WriteLine();
    }

/* Driver code */

    public static void Main(String[] args)
    {
        Node head = newNode(1);
        head.next = newNode(9);
        head.next.next = newNode(9);
        head.next.next.next = newNode(9);

        Console.Write("List is ");
        printList(head);

        head = addOne(head);
        Console.WriteLine();
        Console.Write("Resultant list is ");
        printList(head);
    }
}

/*C# program to point arbit pointers 
to highest value on its right*/

using System;

class GfG
{

/* Link list node */

    class Node
    {
        public int data;
        public Node next, arbit;
    }

/* Function to reverse the linked list */

    static Node reverse(Node head)
    {
        Node prev = null, current = head, next = null;
        while (current != null)
        {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }
        return prev;
    }

/*    This function populates arbit pointer in every
    node to the greatest value to its right.*/

    static Node populateArbit(Node head)
    {

/*        Reverse given linked list*/

        head = reverse(head);

/*        Initialize pointer to maximum value node*/

        Node max = head;

/*        Traverse the reversed list*/

        Node temp = head.next;
        while (temp != null)
        {

/*            Connect max through arbit pointer*/

            temp.arbit = max;

/*            Update max if required*/

            if (max.data < temp.data)
                max = temp;

/*            Move ahead in reversed list*/

            temp = temp.next;
        }

/*        Reverse modified linked list 
        and return head.*/

        return reverse(head);
    }

/*    Utility function to print result linked list*/

    static void printNextArbitPointers(Node node)
    {
        Console.WriteLine("Node\tNext Pointer\tArbit Pointer");
        while (node != null)
        {
            Console.Write(node.data + "\t\t");

            if (node.next != null)
                Console.Write(node.next.data + "\t\t");
            else
                Console.Write("NULL" +"\t\t");

            if (node.arbit != null)
                Console.Write(node.arbit.data);
            else
                Console.Write("NULL");

            Console.WriteLine();
            node = node.next;
        }
    }

/* Function to create a new node with given data */

    static Node newNode(int data)
    {
        Node new_node = new Node();
        new_node.data = data;
        new_node.next = null;
        return new_node;
    }

/* Driver code*/

    public static void Main(String[] args)
    {
        Node head = newNode(5);
        head.next = newNode(10);
        head.next.next = newNode(2);
        head.next.next.next = newNode(3);

        head = populateArbit(head);

        Console.WriteLine("Resultant Linked List is: ");
        printNextArbitPointers(head);
    }
}

/*C# program to point arbit pointers to highest
value on its right*/

using System;

class GfG
{

/* Link list node */

    public class Node
    {
        public int data;
        public Node next, arbit;
    }

    static Node maxNode;

/*    This function populates arbit pointer in every
    node to the greatest value to its right.*/

    static void populateArbit(Node head)
    {

/*        if head is null simply return the list*/

        if (head == null)
            return;

/* if head->next is null it means we reached at
        the last node just update the max and maxNode */

        if (head.next == null)
        {
            maxNode = head;
            return;
        }

/* Calling the populateArbit to the next node */

        populateArbit(head.next);

/* updating the arbit node of the current
        node with the maximum value on the right side */

        head.arbit = maxNode;

/* if current Node value id greater then
        the previous right node then update it */

        if (head.data > maxNode.data)
            maxNode = head;

        return;
    }

/*    Utility function to print result linked list*/

    static void printNextArbitPointers(Node node)
    {
        Console.WriteLine("Node\tNext Pointer\tArbit Pointer");
        while (node != null)
        {
            Console.Write(node.data + "\t\t\t");

            if (node.next != null)
                Console.Write(node.next.data + "\t\t\t\t");
            else
                Console.Write("NULL" +"\t\t\t");

            if (node.arbit != null)
                Console.Write(node.arbit.data);
            else
                Console.Write("NULL");

            Console.WriteLine();
            node = node.next;
        }
    }

/* Function to create a new node with given data */

    static Node newNode(int data)
    {
        Node new_node = new Node();
        new_node.data = data;
        new_node.next = null;
        return new_node;
    }

/* Driver code*/

    public static void Main(String[] args)
    {
        Node head = newNode(5);
        head.next = newNode(10);
        head.next.next = newNode(2);
        head.next.next.next = newNode(3);

        populateArbit(head);

        Console.WriteLine("Resultant Linked List is: ");
        printNextArbitPointers(head);

    }
}

/*C# Program to check if a given linked list 
of strings form a palindrome */

using System;

/*Linked List node */

class Node 
{ 
    public String data; 
    public Node next; 

    public Node(String d) 
    { 
        data = d; 
        next = null; 
    } 
}

public class LinkedList_Palindrome 
{ 
    Node head;

/*    A utility function to check if 
    str is palindrome or not */

    bool isPalidromeUtil(String str) 
    { 
        int length = str.Length;

/*        Match characters from beginning and 
        end. */

        for (int i = 0; i < length / 2; i++) 
            if (str[i] != str[length - i - 1]) 
                return false; 

        return true; 
    }

/*    Returns true if string formed by linked 
    list is palindrome */

    bool isPalindrome() 
    { 
        Node node = head;

/*        Append all nodes to form a string */

        String str = ""; 
        while (node != null) 
        { 
            str = str+(node.data); 
            node = node.next; 
        }

/*        Check if the formed string is palindrome */

        return isPalidromeUtil(str); 
    }

/* Driver code*/

    public static void Main(String[] args) 
    { 
        LinkedList_Palindrome list = new LinkedList_Palindrome(); 
        list.head = new Node("a"); 
        list.head.next = new Node("bc"); 
        list.head.next.next = new Node("d"); 
        list.head.next.next.next = new Node("dcb"); 
        list.head.next.next.next.next = new Node("a"); 

        Console.WriteLine(list.isPalindrome()); 
    } 
}

/*C# program to demonstrate deletion of last
Node in singly linked list*/

using System;

class GFG
{

/*A linked list Node*/

public class Node
{
    public int data;
    public Node next;
};

/*Function to delete the last occurrence*/

static void deleteLast(Node head, int x)
{
    Node temp = head, ptr = null;
    while (temp != null)
    {

/*        If found key, update*/

        if (temp.data == x)
            ptr = temp;    
        temp = temp.next;
    }

/*    If the last occurrence is the last node*/

    if (ptr != null && ptr.next == null)
    {
        temp = head;
        while (temp.next != ptr)
            temp = temp.next;
        temp.next = null;
    }

/*    If it is not the last node*/

    if (ptr != null && ptr.next != null)
    {
        ptr.data = ptr.next.data;
        temp = ptr.next;
        ptr.next = ptr.next.next;
    }
}

/* Utility function to create a new node with
given key */

static Node newNode(int x)
{
    Node node = new Node();
    node.data = x;
    node.next = null;
    return node;
}

/*This function prints contents of linked list
starting from the given Node*/

static void display(Node head)
{
    Node temp = head;
    if (head == null)
    {
        Console.Write("null\n");
        return;
    }
    while (temp != null)
    {
        Console.Write("{0} --> ", temp.data);
        temp = temp.next;
    }
    Console.Write("null\n");
}

/* Driver code*/

public static void Main(String[] args)
{
    Node head = newNode(1);
    head.next = newNode(2);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    head.next.next.next.next = newNode(5);
    head.next.next.next.next.next = newNode(4);
    head.next.next.next.next.next.next = newNode(4);
    Console.Write("Created Linked list: ");
    display(head);
    deleteLast(head, 4);
    Console.Write("List after deletion of 4: ");
    display(head);
}
}

/*C# program to subtract smaller valued
list from larger valued list and return
result as a list.*/

using System;

public class LinkedList {

/*head of list*/

static Node head; 
    bool borrow;

/* Node Class */

    public class Node {
        public int data;
        public Node next;
        public Node(int d)
        {
            data = d;
            next = null;
        }
    }

/* A utility function to get length of
    linked list */

    int getLength(Node node)
    {
        int size = 0;
        while (node != null) {
            node = node.next;
            size++;
        }
        return size;
    }

/* A Utility that padds zeros in front
    of the Node, with the given diff */

    Node paddZeros(Node sNode, int diff)
    {
        if (sNode == null)
            return null;

        Node zHead = new Node(0);
        diff--;
        Node temp = zHead;
        while ((diff--) != 0) {
            temp.next = new Node(0);
            temp = temp.next;
        }
        temp.next = sNode;
        return zHead;
    }

/* Subtract LinkedList Helper is a recursive
    function, move till the last Node, and
    subtract the digits and create the Node and
    return the Node. If d1 < d2, we borrow the
    number from previous digit. */

    Node subtractLinkedListHelper(Node l1, Node l2)
    {
        if (l1 == null && l2 == null && borrow == false)
            return null;

        Node previous = subtractLinkedListHelper((l1 != null) ? l1.next : null, (l2 != null) ? l2.next : null);

        int d1 = l1.data;
        int d2 = l2.data;
        int sub = 0;

/* if you have given the value value to
        next digit then reduce the d1 by 1 */

        if (borrow) {
            d1--;
            borrow = false;
        }

/* If d1 < d2, then borrow the number from
        previous digit. Add 10 to d1 and set
        borrow = true; */

        if (d1 < d2) {
            borrow = true;
            d1 = d1 + 10;
        }

/* subtract the digits */

        sub = d1 - d2;

/* Create a Node with sub value */

        Node current = new Node(sub);

/* Set the Next pointer as Previous */

        current.next = previous;

        return current;
    }

/* This API subtracts two linked lists and
    returns the linked list which shall have the
    subtracted result. */

    Node subtractLinkedList(Node l1, Node l2)
    {

/*        Base Case.*/

        if (l1 == null && l2 == null)
            return null;

/*        In either of the case, get the lengths
        of both Linked list.*/

        int len1 = getLength(l1);
        int len2 = getLength(l2);

        Node lNode = null, sNode = null;

        Node temp1 = l1;
        Node temp2 = l2;

/*        If lengths differ, calculate the smaller
        Node and padd zeros for smaller Node and
        ensure both larger Node and smaller Node
        has equal length.*/

        if (len1 != len2) {
            lNode = len1 > len2 ? l1 : l2;
            sNode = len1 > len2 ? l2 : l1;
            sNode = paddZeros(sNode, Math.Abs(len1 - len2));
        }

        else {

/*            If both list lengths are equal, then
            calculate the larger and smaller list.
            If 5-6-7 & 5-6-8 are linked list, then
            walk through linked list at last Node
            as 7 < 8, larger Node is 5-6-8 and
            smaller Node is 5-6-7.*/

            while (l1 != null && l2 != null) {
                if (l1.data != l2.data) {
                    lNode = l1.data > l2.data ? temp1 : temp2;
                    sNode = l1.data > l2.data ? temp2 : temp1;
                    break;
                }
                l1 = l1.next;
                l2 = l2.next;
            }
        }

/*        After calculating larger and smaller Node,
        call subtractLinkedListHelper which returns
        the subtracted linked list.*/

        borrow = false;
        return subtractLinkedListHelper(lNode, sNode);
    }

/*    function to display the linked list*/

    static void printList(Node head)
    {
        Node temp = head;
        while (temp != null) {
            Console.Write(temp.data + " ");
            temp = temp.next;
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node head = new Node(1);
        head.next = new Node(0);
        head.next.next = new Node(0);

        Node head2 = new Node(1);

        LinkedList ob = new LinkedList();
        Node result = ob.subtractLinkedList(head, head2);

        printList(result);
    }
}

/*C# program to partition a
linked list around a given value.*/

using System;

public class GfG
{

/* Link list Node */

public class Node
{
    public int data;
    public Node next;
}

/*A utility function to create a new node*/

static Node newNode(int data)
{
    Node new_node = new Node();
    new_node.data = data;
    new_node.next = null;
    return new_node;
}

/*Function to make two separate lists and return
head after concatenating*/

static Node partition(Node head, int x)
{

/* Let us initialize first and last nodes of
    three linked lists
        1) Linked list of values smaller than x.
        2) Linked list of values equal to x.
        3) Linked list of values greater than x.*/

    Node smallerHead = null, smallerLast = null;
    Node greaterLast = null, greaterHead = null;
    Node equalHead = null, equalLast =null;

/*    Now iterate original list and connect nodes
    of appropriate linked lists.*/

    while (head != null)
    {

/*        If current node is equal to x, append it
        to the list of x values*/

        if (head.data == x)
        {
            if (equalHead == null)
                equalHead = equalLast = head;
            else
            {
                equalLast.next = head;
                equalLast = equalLast.next;
            }
        }

/*        If current node is less than X, append
        it to the list of smaller values*/

        else if (head.data < x)
        {
            if (smallerHead == null)
                smallerLast = smallerHead = head;
            else
            {
                smallerLast.next = head;
                smallerLast = head;
            }
        }

/*Append to the list of greater values*/

else 
        {
            if (greaterHead == null)
                greaterLast = greaterHead = head;
            else
            {
                greaterLast.next = head;
                greaterLast = head;
            }
        }
        head = head.next;
    }

/*    Fix end of greater linked list to NULL if this
    list has some nodes*/

    if (greaterLast != null)
        greaterLast.next = null;

/*    Connect three lists*/

/*    If smaller list is empty*/

    if (smallerHead == null)
    {
        if (equalHead == null)
            return greaterHead;
        equalLast.next = greaterHead;
        return equalHead;
    }

/*    If smaller list is not empty
    and equal list is empty*/

    if (equalHead == null)
    {
        smallerLast.next = greaterHead;
        return smallerHead;
    }

/*    If both smaller and equal list
    are non-empty*/

    smallerLast.next = equalHead;
    equalLast.next = greaterHead;
    return smallerHead;
}

/* Function to print linked list */

static void printList(Node head)
{
    Node temp = head;
    while (temp != null)
    {
        Console.Write(temp.data + " ");
        temp = temp.next;
    }
}

/*Driver code*/

public static void Main()
{

/* Start with the empty list */

    Node head = newNode(10);
    head.next = newNode(4);
    head.next.next = newNode(5);
    head.next.next.next = newNode(30);
    head.next.next.next.next = newNode(2);
    head.next.next.next.next.next = newNode(50);

    int x = 3;
    head = partition(head, x);
    printList(head);
}
}

/*C# program to check if a linked list
with loop is palindrome or not.*/

using System;
using System.Collections.Generic;

class GfG
{

/* Link list node */

class Node
{
    public int data;
    public Node next;
}

/* Function to find loop starting node.
loop_node --> Pointer to one of
the loop nodes head --> Pointer to
the start node of the linked list */

static Node getLoopstart(Node loop_node,
                            Node head)
{
    Node ptr1 = loop_node;
    Node ptr2 = loop_node;

/*    Count the number of nodes in loop*/

    int k = 1, i;
    while (ptr1.next != ptr2)
    {
        ptr1 = ptr1.next;
        k++;
    }

/*    Fix one pointer to head*/

    ptr1 = head;

/*    And the other pointer to k
    nodes after head*/

    ptr2 = head;
    for (i = 0; i < k; i++)
        ptr2 = ptr2.next;

/* Move both pointers at the same pace,
    they will meet at loop starting node */

    while (ptr2 != ptr1)
    {
        ptr1 = ptr1.next;
        ptr2 = ptr2.next;
    }
    return ptr1;
}

/* This function detects and find
loop starting node in the list*/

static Node detectAndgetLoopstarting(Node head)
{
    Node slow_p = head, fast_p = head,loop_start = null;

/*    Start traversing list and detect loop*/

    while (slow_p != null && fast_p != null &&
            fast_p.next != null)
    {
        slow_p = slow_p.next;
        fast_p = fast_p.next.next;

/* If slow_p and fast_p meet then find
        the loop starting node*/

        if (slow_p == fast_p)
        {
            loop_start = getLoopstart(slow_p, head);
            break;
        }
    }

/*    Return starting node of loop*/

    return loop_start;
}

/*Utility function to check if
a linked list with loop is
palindrome with given starting point.*/

static bool isPalindromeUtil(Node head,
                            Node loop_start)
{
    Node ptr = head;
    Stack<int> s = new Stack<int> ();

/*    Traverse linked list until last node
    is equal to loop_start and store the
    elements till start in a stack*/

    int count = 0;
    while (ptr != loop_start || count != 1)
    {
        s.Push(ptr.data);
        if (ptr == loop_start)
            count = 1;
        ptr = ptr.next;
    }
    ptr = head;
    count = 0;

/*    Traverse linked list until last node is
    equal to loop_start second time*/

    while (ptr != loop_start || count != 1)
    {

/*        Compare data of node with the top of stack
        If equal then continue*/

        if (ptr.data == s.Peek())
            s.Pop();

/*        Else return false*/

        else
            return false;

        if (ptr == loop_start)
            count = 1;
        ptr = ptr.next;
    }

/*    Return true if linked list is palindrome*/

    return true;
}

/*Function to find if linked list
is palindrome or not*/

static bool isPalindrome(Node head)
{

/*    Find the loop starting node*/

    Node loop_start = detectAndgetLoopstarting(head);

/*    Check if linked list is palindrome*/

    return isPalindromeUtil(head, loop_start);
}

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/* Driver code*/

public static void Main(String[] args)
{
    Node head = newNode(50);
    head.next = newNode(20);
    head.next.next = newNode(15);
    head.next.next.next = newNode(20);
    head.next.next.next.next = newNode(50);

/* Create a loop for testing */

    head.next.next.next.next.next = head.next.next;

    if(isPalindrome(head) == true)
        Console.WriteLine("Palindrome");
    else
        Console.WriteLine("Not Palindrome");
}
}

/*C# program to find longest palindrome
sublist in a list in O(1) time.*/

using System;

class GfG
{

/*structure of the linked list*/

public class Node
{
    public int data;
    public Node next;
}

/*function for counting the common elements*/

static int countCommon(Node a, Node b)
{
    int count = 0;

/*    loop to count coomon in the list starting
    from node a and b*/

    for (; a != null && b != null;
            a = a.next, b = b.next)

/*        increment the count for same values*/

        if (a.data == b.data)
            ++count;
        else
            break;

    return count;
}

/*Returns length of the longest palindrome
sublist in given list*/

static int maxPalindrome(Node head)
{
    int result = 0;
    Node prev = null, curr = head;

/*    loop till the end of the linked list*/

    while (curr != null)
    {

/*        The sublist from head to current
        reversed.*/

        Node next = curr.next;
        curr.next = prev;

/*        check for odd length
        palindrome by finding
        longest common list elements
        beginning from prev and
        from next (We exclude curr)*/

        result = Math.Max(result,
                    2 * countCommon(prev, next)+1);

/*        check for even length palindrome
        by finding longest common list elements
        beginning from curr and from next*/

        result = Math.Max(result,
                    2*countCommon(curr, next));

/*        update prev and curr for next iteration*/

        prev = curr;
        curr = next;
    }
    return result;
}

/*Utility function to create a new list node*/

static Node newNode(int key)
{
    Node temp = new Node();
    temp.data = key;
    temp.next = null;
    return temp;
}

/* Driver code*/

public static void Main(String []args)
{

/* Let us create a linked lists to test
    the functions
    Created list is a: 2->4->3->4->2->15 */

    Node head = newNode(2);
    head.next = newNode(4);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    head.next.next.next.next = newNode(2);
    head.next.next.next.next.next = newNode(15);

    Console.WriteLine(maxPalindrome(head));
}
}

