/*C# program to move all occurrences of a
given key to end.*/

using System;

class GFG {

/*    A Linked list Node*/

    public class Node {
        public int data;
        public Node next;
    }

/*    A urility function to create a new node.*/

    static Node newNode(int x)
    {
        Node temp = new Node();
        temp.data = x;
        temp.next = null;
        return temp;
    }

/*    Utility function to print the elements
    in Linked list*/

    static void printList(Node head)
    {
        Node temp = head;
        while (temp != null) {
            Console.Write("{0} ", temp.data);
            temp = temp.next;
        }
        Console.Write("\n");
    }

/*    Moves all occurrences of given key to
    end of linked list.*/

    static void moveToEnd(Node head, int key)
    {

/*        Keeps track of locations where key
        is present.*/

        Node pKey = head;

/*        Traverse list*/

        Node pCrawl = head;
        while (pCrawl != null) {

/*            If current pointer is not same as pointer
            to a key location, then we must have found
            a key in linked list. We swap data of pCrawl
            and pKey and move pKey to next position.*/

            if (pCrawl != pKey && pCrawl.data != key) {
                pKey.data = pCrawl.data;
                pCrawl.data = key;
                pKey = pKey.next;
            }

/*            Find next position where key is present*/

            if (pKey.data != key)
                pKey = pKey.next;

/*            Moving to next Node*/

            pCrawl = pCrawl.next;
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node head = newNode(10);
        head.next = newNode(20);
        head.next.next = newNode(10);
        head.next.next.next = newNode(30);
        head.next.next.next.next = newNode(40);
        head.next.next.next.next.next = newNode(10);
        head.next.next.next.next.next.next = newNode(60);

        Console.Write("Before moveToEnd(), the Linked list is\n");
        printList(head);

        int key = 10;
        moveToEnd(head, key);

        Console.Write("\nAfter moveToEnd(), the Linked list is\n");
        printList(head);
    }
}

/*C# code to remove key
element to end of linked list*/

using System;

/*Node class*/

public class Node {
    public int data;
    public Node next;

    public Node(int data)
    {
        this.data = data;
        this.next = null;
    }
}

class GFG {

    static Node root;

/*    Function to remove key to end*/

    public static Node keyToEnd(Node head, int key)
    {

/*        Node to keep pointing to tail*/

        Node tail = head;

        if (head == null) {
            return null;
        }

        while (tail.next != null) {
            tail = tail.next;
        }

/*        Node to point to last of linked list*/

        Node last = tail;

        Node current = head;
        Node prev = null;

/*        Node prev2 to point to
        previous when head.data!=key*/

        Node prev2 = null;

/*        loop to perform operations
        to remove key to end*/

        while (current != tail) {
            if (current.data == key && prev2 == null) {
                prev = current;
                current = current.next;
                head = current;
                last.next = prev;
                last = last.next;
                last.next = null;
                prev = null;
            }
            else {
                if (current.data == key && prev2 != null) {
                    prev = current;
                    current = current.next;
                    prev2.next = current;
                    last.next = prev;
                    last = last.next;
                    last.next = null;
                }
                else if (current != tail) {
                    prev2 = current;
                    current = current.next;
                }
            }
        }
        return head;
    }

/*    Function to display linked list*/

    public static void display(Node root)
    {
        while (root != null) {
            Console.Write(root.data + " ");
            root = root.next;
        }
    }

/*    Driver Code*/

    public static void Main()
    {
        root = new Node(5);
        root.next = new Node(2);
        root.next.next = new Node(2);
        root.next.next.next = new Node(7);
        root.next.next.next.next = new Node(2);
        root.next.next.next.next.next = new Node(2);
        root.next.next.next.next.next.next = new Node(2);

        int key = 2;
        Console.WriteLine("Linked List before operations :");
        display(root);
        Console.WriteLine("\nLinked List after operations :");
        root = keyToEnd(root, key);
        display(root);
    }
}

/* C# program to remove all occurrences of
duplicates from a sorted linked list */


using System;

/* class to create Linked lIst */

public class LinkedList
{
    Node head = null; 
    class Node
    {
        public int val; 
        public Node next;
        public Node(int v)
        {
            val = v;
            next = null;
        }
    }

/* Function to insert data nodes into
    the Linked List at the front */

    public void insert(int data)
    {
        Node new_node = new Node(data);
        new_node.next = head;
        head = new_node;
    }

/* Function to remove all occurrences
    of duplicate elements */

    public void removeAllDuplicates()
    {

/* create a dummy node that acts like a fake
        head of list pointing to the original head*/

        Node dummy = new Node(0);

/* dummy node points to the original head*/

        dummy.next = head;
        Node prev = dummy;
        Node current = head;

        while (current != null)
        {

/* Until the current and previous values
            are same, keep updating current */

            while (current.next != null &&
                prev.next.val == current.next.val)
                current = current.next;

/* if current has unique value i.e current
                is not updated, Move the prev pointer
                to next node*/

            if (prev.next == current)
                prev = prev.next;

/* when current is updated to the last
            duplicate value of that segment, make
            prev the next of current*/

            else
                prev.next = current.next;

            current = current.next;
        }

/* update original head to the next of dummy
        node */

        head = dummy.next;
    }

/* Function to print the list elements */

    public void printList()
    {
        Node trav = head;
        if (head == null)
            Console.Write(" List is empty" );
        while (trav != null)
        {
            Console.Write(trav.val + " ");
            trav = trav.next;
        }
    }

/* Driver code */

    public static void Main(String[] args)
    {
        LinkedList ll = new LinkedList();
        ll.insert(53);
        ll.insert(53);
        ll.insert(49);
        ll.insert(49);
        ll.insert(35);
        ll.insert(28);
        ll.insert(28);
        ll.insert(23);
        Console.WriteLine("Before removal of duplicates");
        ll.printList();

        ll.removeAllDuplicates();

        Console.WriteLine("\nAfter removal of duplicates");
        ll.printList();
    }
}

/*C# program to delete every k-th Node
of a singly linked list.*/

using System;

class GFG
{

/* Linked list Node */

public class Node
{
    public int data;
    public Node next;
}

/*To remove complete list (Needed for
case when k is 1)*/

static Node freeList(Node node)
{
    while (node != null)
    {
        Node next = node.next;
        node = next;
    }
    return node;
}

/*Deletes every k-th node and
returns head of modified list.*/

static Node deleteKthNode(Node head, int k)
{

/*    If linked list is empty*/

    if (head == null)
        return null;

    if (k == 1)
    {
        head = freeList(head);
        return null;
    }

/*    Initialize ptr and prev before
    starting traversal.*/

    Node ptr = head, prev = null;

/*    Traverse list and delete
    every k-th node*/

    int count = 0;
    while (ptr != null)
    {

/*        increment Node count*/

        count++;

/*        check if count is equal to k
        if yes, then delete current Node*/

        if (k == count)
        {

/*            put the next of current Node in
            the next of previous Node*/

            prev.next = ptr.next;

/*            set count = 0 to reach further
            k-th Node*/

            count = 0;
        }

/*        update prev if count is not 0*/

        if (count != 0)
            prev = ptr;

        ptr = prev.next;
    }
    return head;
}

/* Function to print linked list */

static void displayList(Node head)
{
    Node temp = head;
    while (temp != null)
    {
        Console.Write(temp.data + " ");
        temp = temp.next;
    }
}

/*Utility function to create a new node.*/

static Node newNode(int x)
{
    Node temp = new Node();
    temp.data = x;
    temp.next = null;
    return temp;
}

/*Driver Code*/

public static void Main(String []args)
{

/* Start with the empty list */

    Node head = newNode(1);
    head.next = newNode(2);
    head.next.next = newNode(3);
    head.next.next.next = newNode(4);
    head.next.next.next.next = newNode(5);
    head.next.next.next.next.next = newNode(6);
    head.next.next.next.next.next.next = newNode(7);
    head.next.next.next.next.next.next.next = newNode(8);

    int k = 3;
    head = deleteKthNode(head, k);

    displayList(head);
}
}

/*C# program to check length
of a given linklist*/

using System;

class GfG
{

/*Defining structure*/

class Node
{
    public int data;
    public Node next;
}

/*Function to check the length of linklist*/

static int LinkedListLength(Node head)
{
    while (head != null && head.next != null)
    {
        head = head.next.next;
    }
    if (head == null)
        return 0;
    return 1;
}

/*Push function*/

static void push(Node head, int info)
{

/*    Allocating node*/

    Node node = new Node();

/*    Info into node*/

    node.data = info;

/*    Next of new node to head*/

    node.next = (head);

/*    head points to new node*/

    (head) = node;
}

/*Driver code*/

public static void Main()
{
    Node head = null;

/*    Adding elements to Linked List*/

    push(head, 4);
    push(head, 5);
    push(head, 7);
    push(head, 2);
    push(head, 9);
    push(head, 6);
    push(head, 1);
    push(head, 2);
    push(head, 0);
    push(head, 5);
    push(head, 5);
    int check = LinkedListLength(head);

/*    Checking for length of
    linklist*/

    if(check == 0)
    {
        Console.WriteLine("Odd");
    }
    else
    {
        Console.WriteLine("Even");
    }
}
}

/*C# implementation to find the sum of
last 'n' nodes of the Linked List*/

using System;

class GFG
{

/* A Linked list node */

public class Node
{
    public int data;
    public Node next;
};
static Node head;
static int n, sum;

/*function to insert a node at the
beginning of the linked list*/

static void push(Node head_ref, int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list to the new node */

    new_node.next = head_ref;

/* move the head to point to the new node */

    head_ref = new_node;
    head = head_ref;
}

/*function to recursively find the sum of last
'n' nodes of the given linked list*/

static void sumOfLastN_Nodes(Node head)
{

/*    if head = NULL*/

    if (head == null)
        return;

/*    recursively traverse the remaining nodes*/

    sumOfLastN_Nodes(head.next);

/*    if node count 'n' is greater than 0*/

    if (n > 0)
    {

/*        accumulate sum*/

        sum = sum + head.data;

/*        reduce node count 'n' by 1*/

        --n;
    }
}

/*utility function to find the sum of last 'n' nodes*/

static int sumOfLastN_NodesUtil(Node head, int n)
{

/*    if n == 0*/

    if (n <= 0)
        return 0;

    sum = 0;

/*    find the sum of last 'n' nodes*/

    sumOfLastN_Nodes(head);

/*    required sum*/

    return sum;
}

/*Driver Code*/

public static void Main(String[] args)
{
    head = null;

/*    create linked list 10.6.8.4.12*/

    push(head, 12);
    push(head, 4);
    push(head, 8);
    push(head, 6);
    push(head, 10);

    n = 2;
    Console.Write("Sum of last " + n +
                  " nodes = " +
                  sumOfLastN_NodesUtil(head, n));
}
}

/*C# implementation to find the sum of last
'n' nodes of the Linked List*/

using System;
using System.Collections.Generic;

class GFG
{

/* A Linked list node */

class Node
{
    public int data;
    public Node next;
};

/*function to insert a node at the
beginning of the linked list*/

static Node push(Node head_ref, int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list to the new node */

    new_node.next = head_ref;

/* move the head to point to the new node */

    head_ref = new_node;
    return head_ref;
}

/*utility function to find the sum of last 'n' nodes*/

static int sumOfLastN_NodesUtil(Node head, int n)
{

/*    if n == 0*/

    if (n <= 0)
        return 0;

    Stack<int> st = new Stack<int>();
    int sum = 0;

/*    traverses the list from left to right*/

    while (head != null)
    {

/*        push the node's data onto the stack 'st'*/

        st.Push(head.data);

/*        move to next node*/

        head = head.next;
    }

/*    pop 'n' nodes from 'st' and
    .Add them*/

    while (n-- >0)
    {
        sum += st.Peek();
        st.Pop();
    }

/*    required sum*/

    return sum;
}

/*Driver code*/

public static void Main(String[] args)
{
    Node head = null;

/*    create linked list 10.6.8.4.12*/

    head = push(head, 12);
    head = push(head, 4);
    head = push(head, 8);
    head = push(head, 6);
    head = push(head, 10);

    int n = 2;
    Console.Write("Sum of last " + n+ " nodes = "
        + sumOfLastN_NodesUtil(head, n));
}
}

/*C# implementation to find the sum of last
'n' nodes of the Linked List*/

using System;

class GFG
{

/* A Linked list node */

public class Node
{
    public int data;
    public Node next;
};
static Node head;

/*function to insert a node at the
beginning of the linked list*/

static void push(Node head_ref, int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list to the new node */

    new_node.next = head_ref;

/* move the head to point to the new node */

    head_ref = new_node;
    head=head_ref;
}

static void reverseList(Node head_ref)
{
    Node current, prev, next;
    current = head_ref;
    prev = null;

    while (current != null)
    {
        next = current.next;
        current.next = prev;
        prev = current;
        current = next;
    }

    head_ref = prev;
    head = head_ref;
}

/*utility function to find the sum of last 'n' nodes*/

static int sumOfLastN_NodesUtil(int n)
{

/*    if n == 0*/

    if (n <= 0)
        return 0;

/*    reverse the linked list*/

    reverseList(head);

    int sum = 0;
    Node current = head;

/*    traverse the 1st 'n' nodes of the reversed
    linked list and add them*/

    while (current != null && n-- >0)
    {

/*        accumulate node's data to 'sum'*/

        sum += current.data;

/*        move to next node*/

        current = current.next;
    }

/*    reverse back the linked list*/

    reverseList(head);

/*    required sum*/

    return sum;
}

/*Driver code*/

public static void Main(String[] args)
{

/*    create linked list 10->6->8->4->12*/

    push(head, 12);
    push(head, 4);
    push(head, 8);
    push(head, 6);
    push(head, 10);

    int n = 2;
    Console.WriteLine("Sum of last " + n + " nodes = "
        + sumOfLastN_NodesUtil(n));
}
}

/*C# implementation to find the sum of last
'n' nodes of the Linked List*/

using System;

class GFG
{

/* A Linked list node */

public class Node
{
    public int data;
    public Node next;
};
static Node head;

/*function to insert a node at the
beginning of the linked list*/

static void push(Node head_ref, int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list to the new node */

    new_node.next = head_ref;

/* move the head to point to the new node */

    head_ref = new_node;
        head = head_ref;
}

/*utility function to find the sum of last 'n' nodes*/

static int sumOfLastN_NodesUtil(Node head, int n)
{

/*    if n == 0*/

    if (n <= 0)
        return 0;

    int sum = 0, len = 0;
    Node temp = head;

/*    calculate the length of the linked list*/

    while (temp != null)
    {
        len++;
        temp = temp.next;
    }

/*    count of first (len - n) nodes*/

    int c = len - n;
    temp = head;

/*    just traverse the 1st 'c' nodes*/

    while (temp != null&&c-- >0)
    {

/*        move to next node*/

        temp = temp.next;
    }

/*    now traverse the last 'n' nodes and add them*/

    while (temp != null)
    {

/*        accumulate node's data to sum*/

        sum += temp.data;

/*        move to next node*/

        temp = temp.next;
    }

/*    required sum*/

    return sum;
}

/*Driver code*/

public static void Main(String[] args)
{

/*    create linked list 10.6.8.4.12*/

    push(head, 12);
    push(head, 4);
    push(head, 8);
    push(head, 6);
    push(head, 10);

    int n = 2;
    Console.WriteLine("Sum of last " + n + " nodes = "
        + sumOfLastN_NodesUtil(head, n));
}
}

/*C# program to merge k sorted
arrays of size n each*/

using System;

/*A Linked List node*/

public class Node
{
  public int data;
  public Node next;

/*  Utility function to create a new node.*/

  public Node(int key)
  {
    data = key;
    next = null;
  }
}

public class GFG
{
  static Node head;

/* Function to print nodes in
   a given linked list */

  static void printList(Node node)
  {
    while(node != null)
    {
      Console.Write(node.data + " ");
      node = node.next;
    }
    Console.WriteLine();
  }

/*  The main function that
  takes an array of lists
  arr[0..last] and generates
  the sorted output*/

  static Node mergeKLists(Node[] arr, int last)
  {

/*    Traverse form second list to last*/

    for (int i = 1; i <= last; i++)
    {
      while(true)
      {

/*        head of both the lists,
        0 and ith list. */

        Node head_0 = arr[0];
        Node head_i = arr[i];

/*        Break if list ended*/

        if (head_i == null)
          break;

/*        Smaller than first element*/

        if(head_0.data >= head_i.data)
        {
          arr[i] = head_i.next;
          head_i.next = head_0;
          arr[0] = head_i;
        }
        else
        {

/*          Traverse the first list*/

          while (head_0.next != null)
          {

/*            Smaller than next element*/

            if (head_0.next.data >= head_i.data)
            {
              arr[i] = head_i.next;
              head_i.next = head_0.next;
              head_0.next = head_i;
              break;
            }

/*            go to next node*/

            head_0 = head_0.next;

/*            if last node*/

            if (head_0.next == null)
            {
              arr[i] = head_i.next;
              head_i.next = null;
              head_0.next = head_i;
              head_0.next.next = null;
              break;
            }
          }
        }
      }
    }
    return arr[0];
  }

/*Driver program to test
above functions*/
  static public void Main ()
  {

/*    Number of linked lists*/

    int k = 3;

/*    an array of pointers storing the
    head nodes of the linked lists*/

    Node[] arr = new Node[k];

    arr[0] = new Node(1);
    arr[0].next = new Node(3);
    arr[0].next.next = new Node(5);
    arr[0].next.next.next = new Node(7);

    arr[1] = new Node(2);
    arr[1].next = new Node(4);
    arr[1].next.next = new Node(6);
    arr[1].next.next.next = new Node(8);

    arr[2] = new Node(0);
    arr[2].next = new Node(9);
    arr[2].next.next = new Node(10);
    arr[2].next.next.next = new Node(11);

/*    Merge all lists*/

    head = mergeKLists(arr, k - 1);
    printList(head);
  }
}

/*C# program to merge two sorted
linked lists in-place.*/

using System;

class GFG {

    public class Node {
        public int data;
        public Node next;
    };

/*    Function to create newNode in a linkedlist*/

    static Node newNode(int key)
    {
        Node temp = new Node();
        temp.data = key;
        temp.next = null;
        return temp;
    }

/*    A utility function to print linked list*/

    static void printList(Node node)
    {
        while (node != null) {
            Console.Write("{0} ", node.data);
            node = node.next;
        }
    }

/*    Merges two given lists in-place. This function
    mainly compares head nodes and calls mergeUtil()*/

    static Node merge(Node h1, Node h2)
    {
        if (h1 == null)
            return h2;
        if (h2 == null)
            return h1;

/*        start with the linked list
        whose head data is the least*/

        if (h1.data < h2.data) {
            h1.next = merge(h1.next, h2);
            return h1;
        }
        else {
            h2.next = merge(h1, h2.next);
            return h2;
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node head1 = newNode(1);
        head1.next = newNode(3);
        head1.next.next = newNode(5);

/*        1.3.5 LinkedList created*/


        Node head2 = newNode(0);
        head2.next = newNode(2);
        head2.next.next = newNode(4);

/*        0.2.4 LinkedList created*/


        Node mergedhead = merge(head1, head2);

        printList(mergedhead);
    }
}

/*C# program to merge two sorted
linked lists in-place.*/

using System;

class GfG {

/*Linked List node*/

    public class Node {
        public int data;
        public Node next;
    }

/*    Function to create newNode in a linkedlist*/

    static Node newNode(int key)
    {
        Node temp = new Node();
        temp.data = key;
        temp.next = null;
        return temp;
    }

/*    A utility function to print linked list*/

    static void printList(Node node)
    {
        while (node != null) {
            Console.Write(node.data + " ");
            node = node.next;
        }
    }

/*    Merges two lists with headers as h1 and h2.
    It assumes that h1's data is smaller than
    or equal to h2's data.*/

    static Node mergeUtil(Node h1, Node h2)
    {

/*        if only one node in first list
        simply point its head to second list*/

        if (h1.next == null) {
            h1.next = h2;
            return h1;
        }

/*        Initialize current and next pointers of
        both lists*/

        Node curr1 = h1, next1 = h1.next;
        Node curr2 = h2, next2 = h2.next;

        while (next1 != null && curr2 != null) {

/*            if curr2 lies in between curr1 and next1
            then do curr1->curr2->next1*/

            if ((curr2.data) >= (curr1.data)
                && (curr2.data) <= (next1.data)) {
                next2 = curr2.next;
                curr1.next = curr2;
                curr2.next = next1;

/*                now let curr1 and curr2 to point
                to their immediate next pointers*/

                curr1 = curr2;
                curr2 = next2;
            }
            else {

/*                if more nodes in first list*/

                if (next1.next != null) {
                    next1 = next1.next;
                    curr1 = curr1.next;
                }

/*                else point the last node of first list
                to the remaining nodes of second list*/

                else {
                    next1.next = curr2;
                    return h1;
                }
            }
        }
        return h1;
    }

/*    Merges two given lists in-place. This function
    mainly compares head nodes and calls mergeUtil()*/

    static Node merge(Node h1, Node h2)
    {
        if (h1 == null)
            return h2;
        if (h2 == null)
            return h1;

/*        start with the linked list
        whose head data is the least*/

        if (h1.data < h2.data)
            return mergeUtil(h1, h2);
        else
            return mergeUtil(h2, h1);
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Node head1 = newNode(1);
        head1.next = newNode(3);
        head1.next.next = newNode(5);

/*        1->3->5 LinkedList created*/


        Node head2 = newNode(0);
        head2.next = newNode(2);
        head2.next.next = newNode(4);

/*        0->2->4 LinkedList created*/


        Node mergedhead = merge(head1, head2);
        printList(mergedhead);
    }
}

/*C# code for Union and Intersection of two
Linked Lists*/

using System;
using System.Collections;
using System.Collections.Generic;

class LinkedList
{

/*head of list*/

public Node head;

/* Linked list Node*/

    public class Node
    {
        public int data;
        public Node next;
        public Node(int d)
        {
            data = d;
            next = null;
        }
    }

/* Utility function to print list */

    void printList()
    {
        Node temp = head;
        while (temp != null)
        {
            Console.Write(temp.data + " ");
            temp = temp.next;
        }
        Console.WriteLine();
    }

/* Inserts a node at start of linked list */

    void push(int new_data)
    {

/* 1 & 2: Allocate the Node &
        Put in the data*/

        Node new_node = new Node(new_data);

/* 3. Make next of new Node as head */

        new_node.next = head;

/* 4. Move the head to point to new Node */

        head = new_node;
    }

    public void append(int new_data)
    {
        if (this.head == null) {
            Node n = new Node(new_data);
            this.head = n;
            return;
        }
        Node n1 = this.head;
        Node n2 = new Node(new_data);
        while (n1.next != null) {
            n1 = n1.next;
        }
        n1.next = n2;
        n2.next = null;
    }

/* A utility function that returns true if data is
    present in linked list else return false */

    bool isPresent(Node head, int data)
    {
        Node t = head;
        while (t != null) {
            if (t.data == data)
                return true;
            t = t.next;
        }
        return false;
    }

    LinkedList getIntersection(Node head1, Node head2)
    {
        HashSet<int> hset = new HashSet<int>();
        Node n1 = head1;
        Node n2 = head2;
        LinkedList result = new LinkedList();

/*        loop stores all the elements of list1 in hset*/

        while (n1 != null) {
            if (hset.Contains(n1.data)) {
                hset.Add(n1.data);
            }
            else {
                hset.Add(n1.data);
            }
            n1 = n1.next;
        }

/*        For every element of list2 present in hset
        loop inserts the element into the result*/

        while (n2 != null) {
            if (hset.Contains(n2.data)) {
                result.push(n2.data);
            }
            n2 = n2.next;
        }
        return result;
    }

    LinkedList getUnion(Node head1, Node head2)
    {

/*        HashMap that will store the
        elements of the lists with their counts*/

        SortedDictionary<int, int> hmap = new SortedDictionary<int, int>();
        Node n1 = head1;
        Node n2 = head2;
        LinkedList result = new LinkedList();

/*        loop inserts the elements and the count of
        that element of list1 into the hmap*/

        while (n1 != null) {
            if (hmap.ContainsKey(n1.data)) {
                hmap[n1.data]++;
            }
            else {
                hmap[n1.data]= 1;
            }
            n1 = n1.next;
        }

/*        loop further adds the elements of list2 with
        their counts into the hmap*/

        while (n2 != null) {
            if (hmap.ContainsKey(n2.data)) {
                hmap[n2.data]++;
            }
            else {
                hmap[n2.data]= 1;
            }
            n2 = n2.next;
        }

/*        Eventually add all the elements
        into the result that are present in the hmap*/

        foreach(int a in hmap.Keys) {
            result.append(a);
        }
        return result;
    }

/* Driver program to test above functions */

    public static void Main(string []args)
    {
        LinkedList llist1 = new LinkedList();
        LinkedList llist2 = new LinkedList();
        LinkedList union = new LinkedList();
        LinkedList intersection = new LinkedList();

/*create a linked list 10->15->4->20 */

        llist1.push(20);
        llist1.push(4);
        llist1.push(15);
        llist1.push(10);

/*create a linked list 8->4->2->10 */

        llist2.push(10);
        llist2.push(2);
        llist2.push(4);
        llist2.push(8);
        intersection = intersection.getIntersection(llist1.head,
                                           llist2.head);
        union = union.getUnion(llist1.head, llist2.head);
        Console.WriteLine("First List is");
        llist1.printList();
        Console.WriteLine("Second List is");
        llist2.printList();
        Console.WriteLine("Intersection List is");
        intersection.printList();
        Console.WriteLine("Union List is");
        union.printList();
    }
}

/*C# implementation of recursive selection sort
for singly linked list | Swapping node links*/

using System;
public class GFG
{

/*A Linked list node*/

public class Node
{
    public int data;
    public Node next;
};

/*function to swap nodes 'currX' and 'currY' in a
linked list without swapping data*/

static Node swapNodes(Node head_ref, Node currX,
                      Node currY, Node prevY)
{

/*    make 'currY' as new head*/

    head_ref = currY;

/*    adjust links*/

    prevY.next = currX;

/*    Swap next pointers*/

    Node temp = currY.next;
    currY.next = currX.next;
    currX.next = temp;
    return head_ref;
}

/*function to sort the linked list using
recursive selection sort technique*/

static Node recurSelectionSort(Node head)
{

/*    if there is only a single node*/

    if (head.next == null)
        return head;

/*    'min' - pointer to store the node having
    minimum data value*/

    Node min = head;

/*    'beforeMin' - pointer to store node
    previous to 'min' node*/

    Node beforeMin = null;
    Node ptr;

/*    traverse the list till the last node*/

    for (ptr = head; ptr.next != null;
                     ptr = ptr.next)
    {

/*        if true, then update 'min' and 'beforeMin'*/

        if (ptr.next.data < min.data)
        {
            min = ptr.next;
            beforeMin = ptr;
        }
    }

/*    if 'min' and 'head' are not same,
    swap the head node with the 'min' node*/

    if (min != head)
        head = swapNodes(head, head, min, beforeMin);

/*    recursively sort the remaining list*/

    head.next = recurSelectionSort(head.next);

    return head;
}

/*function to sort the given linked list*/

static Node sort( Node head_ref)
{

/*    if list is empty*/

    if ((head_ref) == null)
        return null;

/*    sort the list using recursive selection
    sort technique*/

    head_ref = recurSelectionSort(head_ref);
    return head_ref;
}

/*function to insert a node at the
beginning of the linked list*/

static Node push(Node head_ref, int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    link the old list to the new node*/

    new_node.next = (head_ref);

/*    move the head to point to the new node*/

    (head_ref) = new_node;
    return head_ref;
}

/*function to print the linked list*/

static void printList( Node head)
{
    while (head != null)
    {
        Console.Write(head.data + " ");
        head = head.next;
    }
}

/*Driver code*/

public static void Main(String []args)
{
    Node head = null;

/*    create linked list 10->12->8->4->6*/

    head = push(head, 6);
    head = push(head, 4);
    head = push(head, 8);
    head = push(head, 12);
    head = push(head, 10);

    Console.WriteLine("Linked list before sorting:");
    printList(head);

/*    sort the linked list*/

    head = sort(head);

    Console.Write("\nLinked list after sorting:");
    printList(head);
}
}

/*C# implementation to insert node
at the middle of the linked list*/

using System;

public class LinkedList
{

/*head of list*/

static Node head;

/* Node Class */

    public class Node
    {
        public int data;
        public Node next;

/*        Constructor to create a new node*/

        public Node(int d)
        {
            data = d;
            next = null;
        }
    }

/*    function to insert node at the
    middle of the linked list*/

    static void insertAtMid(int x)
    {

/*        if list is empty*/

        if (head == null)
            head = new Node(x);
        else
        {

/*            get a new node*/

            Node newNode = new Node(x);

            Node ptr = head;
            int len = 0;

/*            calculate length of the linked list
            , i.e, the number of nodes*/

            while (ptr != null)
            {
                len++;
                ptr = ptr.next;
            }

/*            'count' the number of nodes after which
            the new node is to be inserted*/

            int count = ((len % 2) == 0) ? (len / 2) :
                                        (len + 1) / 2;
            ptr = head;

/*            'ptr' points to the node after which
            the new node is to be inserted*/

            while (count-- > 1)
                ptr = ptr.next;

/*            insert the 'newNode' and adjust
            the required links*/

            newNode.next = ptr.next;
            ptr.next = newNode;
        }
    }

/*    function to display the linked list*/

    static void display()
    {
        Node temp = head;
        while (temp != null)
        {
            Console.Write(temp.data + " ");
            temp = temp.next;
