/*C# implementation to insert node
at the middle of the linked list*/

using System;

public class LinkedList
{

/*head of list*/

static Node head;

/* Node Class */

    class Node
    {
        public int data;
        public Node next;
        public Node(int d)
        {
            data = d;
            next = null;
        }
    }

/*    function to insert node at the
    middle of the linked list*/

    static void insertAtMid(int x)
    {

/*        if list is empty*/

        if (head == null)
        head = new Node(x);

        else
        {

/*            get a new node*/

            Node newNode = new Node(x);

/*            assign values to the slow
            and fast pointers*/

            Node slow = head;
            Node fast = head.next;

            while (fast != null && fast.next
                                != null)
            {

/*                move slow pointer to next node*/

                slow = slow.next;

/*                move fast pointer two nodes
                at a time*/

                fast = fast.next.next;
            }

/*            insert the 'newNode' and adjust
            the required links*/

            newNode.next = slow.next;
            slow.next = newNode;
        }
    }

/*    function to display the linked list*/

    static void display()
    {
        Node temp = head;
        while (temp != null)
        {
            Console.Write(temp.data + " ");
            temp = temp.next;
        }
    }

/*    Driver code*/

    public static void Main (String[] args)
    {

/*        Creating the list 1.2.4.5*/

        head = null;
        head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(4);
        head.next.next.next = new Node(5);

        Console.WriteLine("Linked list before"+
                        " insertion: ");
        display();

        int x = 3;
        insertAtMid(x);

        Console.WriteLine("\nLinked list after"+
                        " insertion: ");
        display();
    }
}

/*C# implementation to insert a node after
the n-th node from the end*/

using System;

class GfG
{

/*structure of a node*/

public class Node
{
    public int data;
    public Node next;
}

/*function to get a new node*/

static Node getNode(int data)
{

/*    allocate memory for the node*/

    Node newNode = new Node();

/*    put in the data*/

    newNode.data = data;
    newNode.next = null;
    return newNode;
}

/*function to insert a node after the
nth node from the end*/

static void insertAfterNthNode(Node head, int n, int x)
{

/*    if list is empty*/

    if (head == null)
        return;

/*    get a new node for the value 'x'*/

    Node newNode = getNode(x);
    Node ptr = head;
    int len = 0, i;

/*    find length of the list, i.e, the
    number of nodes in the list*/

    while (ptr != null)
    {
        len++;
        ptr = ptr.next;
    }

/*    traverse up to the nth node from the end*/

    ptr = head;
    for (i = 1; i <= (len - n); i++)
        ptr = ptr.next;

/*    insert the 'newNode' by making the
    necessary adjustment in the links*/

    newNode.next = ptr.next;
    ptr.next = newNode;
}

/*function to print the list*/

static void printList(Node head)
{
    while (head != null)
    {
        Console.Write(head.data + " ");
        head = head.next;
    }
}

/*Driver code*/

public static void Main(String[] args)
{

/*    Creating list 1->3->4->5*/

    Node head = getNode(1);
    head.next = getNode(3);
    head.next.next = getNode(4);
    head.next.next.next = getNode(5);

    int n = 4, x = 2;

    Console.Write("Original Linked List: ");
    printList(head);

    insertAfterNthNode(head, n, x);
    Console.WriteLine();
    Console.Write("Linked List After Insertion: ");
    printList(head);
}
}

