/*C# program to rotate a linked list block wise*/

using System;
public class GFG
{

/* Link list node */

  public
    class Node
    {
      public
        int data;
      public
        Node next;
    };
  static Node tail;

/*  Recursive function to rotate one block*/

  static Node rotateHelper(Node blockHead,
                           Node blockTail,
                           int d,
                           int k)
  {
    if (d == 0)
      return blockHead;

/*    Rotate Clockwise*/

    if (d > 0)
    {
      Node temp = blockHead;
      for (int i = 1; temp.next.next != null &&
           i < k - 1; i++)
        temp = temp.next;
      blockTail.next = blockHead;
      tail = temp;
      return rotateHelper(blockTail, temp,
                          d - 1, k);
    }

/*    Rotate anti-Clockwise*/

    if (d < 0)
    {
      blockTail.next = blockHead;
      tail = blockHead;
      return rotateHelper(blockHead.next,
                          blockHead, d + 1,  k);
    }
    return blockHead;
  }

/*  Function to rotate the linked list block wise*/

  static Node rotateByBlocks(Node head,
                             int k, int d)
  {

/*    If length is 0 or 1 return head*/

    if (head == null || head.next == null)
      return head;

/*    if degree of rotation is 0, return head*/

    if (d == 0)
      return head;
    Node temp = head;
    tail = null;

/*    Traverse upto last element of this block*/

    int i;
    for (i = 1; temp.next != null && i < k; i++)
      temp = temp.next;

/*    storing the first node of next block*/

    Node nextBlock = temp.next;

/*    If nodes of this block are less than k.
    Rotate this block also*/

    if (i < k)
      head = rotateHelper(head, temp, d % k,
                          i);
    else
      head = rotateHelper(head, temp, d % k,
                          k);

/*    Append the new head of next block to
    the tail of this block*/

    tail.next = rotateByBlocks(nextBlock, k,
                               d % k);

/*    return head of updated Linked List*/

    return head;
  }

/* UTILITY FUNCTIONS */

/* Function to push a node */

  static Node push(Node head_ref, int new_data)
  {
    Node new_node = new Node();
    new_node.data = new_data;
    new_node.next = head_ref;
    head_ref = new_node;
    return head_ref;

  }

/* Function to print linked list */

  static void printList(Node node)
  {
    while (node != null)
    {
      Console.Write(node.data + " ");
      node = node.next;
    }
  }

/* Driver code*/

  public static void Main(String[] args)
  {

/* Start with the empty list */

    Node head = null;

/*    create a list 1.2.3.4.5.
    6.7.8.9.null*/

    for (int i = 9; i > 0; i -= 1)
      head = push(head, i);
    Console.Write("Given linked list \n");
    printList(head);

/*    k is block size and d is number of
    rotations in every block.*/

    int k = 3, d = 2;
    head = rotateByBlocks(head, k, d);
    Console.Write("\nRotated by blocks Linked list \n");
    printList(head);
  }
}

/*C# program to make middle node
as head of Linked list*/

using System;

public class GFG
{

/* Link list node */

    class Node
    {
        public int data;
        public Node next;
        public Node(int data)
        {
            this.data = data;
            next = null;
        }
    }

    static Node head;

/* Function to get the middle and
    set at beginning of the linked list*/

    static void setMiddleHead()
    {
        if (head == null)
            return;

/*        To traverse list nodes one
        by one*/

        Node one_node = head;

/*        To traverse list nodes by
        skipping one.*/

        Node two_node = head;

/*        To keep track of previous of middle*/

        Node prev = null;
        while (two_node != null &&
            two_node.next != null)
        {

/* for previous node of middle node */

            prev = one_node;

/* move one node each time*/

            two_node = two_node.next.next;

/* move two node each time*/

            one_node = one_node.next;
        }

/* set middle node at head */

        prev.next = prev.next.next;
        one_node.next = head;
        head = one_node;
    }

/*    To insert a node at the beginning of
    linked list.*/

    static void push(int new_data)
    {

/* allocate node */

        Node new_node = new Node(new_data);

/* link the old list off the new node */

        new_node.next = head;

/* move the head to point to the new node */

        head = new_node;
    }

/*    A function to print a given linked list*/

    static void printList(Node ptr)
    {
        while (ptr != null) {
            Console.Write(ptr.data + " ");
            ptr = ptr.next;
        }
        Console.WriteLine();
    }

/* Driver code*/

    public static void Main(String []args)
    {

/*        Create a list of 5 nodes*/

        head = null;
        int i;
        for (i = 5; i > 0; i--)
            push(i);

        Console.Write(" list before: ");
        printList(head);

        setMiddleHead();

        Console.Write(" list After: ");
        printList(head);
    }
}

/*C# implementation for Sorted merge of two
sorted doubly circular linked list*/

using System;

class GFG
{

public class Node
{
    public int data;
    public Node next, prev;
};

/*A utility function to insert a new node at the
beginning of doubly circular linked list*/

static Node insert(Node head_ref, int data)
{

/*    allocate space*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = data;

/*    if list is empty*/

    if (head_ref == null)
    {
        new_node.next = new_node;
        new_node.prev = new_node;
    }

    else
    {

/*        pointer points to last Node*/

        Node last = (head_ref).prev;

/*        setting up previous and next of new node*/

        new_node.next = head_ref;
        new_node.prev = last;

/*        update next and previous pointers of head_ref
        and last.*/

        last.next = (head_ref).prev = new_node;
    }

/*    update head_ref pointer*/

    head_ref = new_node;
    return head_ref;
}

/*function for Sorted merge of two
sorted doubly linked list*/

static Node merge(Node first, Node second)
{

/*    If first list is empty*/

    if (first == null)
        return second;

/*    If second list is empty*/

    if (second == null)
        return first;

/*    Pick the smaller value and adjust
    the links*/

    if (first.data < second.data)
    {
        first.next = merge(first.next, second);
        first.next.prev = first;
        first.prev = null;
        return first;
    }
    else
    {
        second.next = merge(first, second.next);
        second.next.prev = second;
        second.prev = null;
        return second;
    }
}

/*function for Sorted merge of two sorted
doubly circular linked list*/

static Node mergeUtil(Node head1, Node head2)
{

/*    if 1st list is empty*/

    if (head1 == null)
        return head2;

/*    if 2nd list is empty*/

    if (head2 == null)
        return head1;

/*    get pointer to the node which will be the
    last node of the final list*/

    Node last_node;
    if (head1.prev.data < head2.prev.data)
        last_node = head2.prev;
    else
        last_node = head1.prev;

/*    store null to the 'next' link of the last nodes
    of the two lists*/

    head1.prev.next = head2.prev.next = null;

/*    sorted merge of head1 and head2*/

    Node finalHead = merge(head1, head2);

/*    'prev' of 1st node pointing the last node
    'next' of last node pointing to 1st node*/

    finalHead.prev = last_node;
    last_node.next = finalHead;

    return finalHead;
}

/*function to print the list*/

static void printList(Node head)
{
    Node temp = head;

    while (temp.next != head)
    {
        Console.Write(temp.data + " ");
        temp = temp.next;
    }
    Console.Write(temp.data + " ");
}

/*Driver code*/

public static void Main()
{
    Node head1 = null, head2 = null;

/*    list 1:*/

    head1 = insert(head1, 8);
    head1 = insert(head1, 5);
    head1 = insert(head1, 3);
    head1 = insert(head1, 1);

/*    list 2:*/

    head2 = insert(head2, 11);
    head2 = insert(head2, 9);
    head2 = insert(head2, 7);
    head2 = insert(head2, 2);

    Node newHead = mergeUtil(head1, head2);

    Console.Write( "Final Sorted List: ");
    printList(newHead);
}
}

/*C# Program to Reverse a List using Data Swapping*/

using System;

class GFG
{

    public class Node
    {
        public int data;
        public Node prev, next;
    };

    static Node newNode(int val)
    {
        Node temp = new Node();
        temp.data = val;
        temp.prev = temp.next = null;
        return temp;
    }

    static void printList(Node head)
    {
        while (head.next != null)
        {
            Console.Write(head.data+ " <-> ");
            head = head.next;
        }
        Console.WriteLine( head.data );
    }

/*    Insert a new node at the head of the list*/

    static Node insert(Node head, int val)
    {
        Node temp = newNode(val);
        temp.next = head;
        (head).prev = temp;
        (head) = temp;
        return head;
    }

/*    Function to reverse the list*/

    static Node reverseList(Node head)
    {
        Node left = head, right = head;

/*        Traverse the list and set right pointer to
        end of list*/

        while (right.next != null)
            right = right.next;

/*        Swap data of left and right pointer and move
        them towards each other until they meet or
        cross each other*/

        while (left != right && left.prev != right)
        {

/*            Swap data of left and right pointer*/

            int t = left.data;
            left.data = right.data;
            right.data = t;

/*            Advance left pointer*/

            left = left.next;

/*            Advance right pointer*/

            right = right.prev;
        }
        return head;
    }

/*    Driver code*/

    public static void Main(String []args)
    {
        Node head = newNode(5);
        head = insert(head, 4);
        head = insert(head, 3);
        head = insert(head, 2);
        head = insert(head, 1);

        printList(head);
        Console.WriteLine("List After Reversing");
        head=reverseList(head);
        printList(head);

    }
}

/*C# implementation for insertion Sort
on a doubly linked list*/

using System;

class GFG
{

/*Node of a doubly linked list*/

public class Node
{
    public int data;
    public Node prev, next;
};

/*function to create and return a new node
of a doubly linked list*/

static Node getNode(int data)
{

/*    allocate node*/

    Node newNode = new Node();

/*    put in the data*/

    newNode.data = data;
    newNode.prev = newNode.next = null;
    return newNode;
}

/*function to insert a new node in sorted way
in a sorted doubly linked list*/

static Node sortedInsert(Node head_ref,
                         Node newNode)
{
    Node current;

/*    if list is empty*/

    if (head_ref == null)
        head_ref = newNode;

/*    if the node is to be inserted at the beginning
    of the doubly linked list*/

    else if ((head_ref).data >= newNode.data)
    {
        newNode.next = head_ref;
        newNode.next.prev = newNode;
        head_ref = newNode;
    }

    else
    {
        current = head_ref;

/*        locate the node after which
        the new node is to be inserted*/

        while (current.next != null &&
               current.next.data < newNode.data)
            current = current.next;

/*        Make the appropriate links*/


        newNode.next = current.next;

/*        if the new node is not inserted
        at the end of the list*/

        if (current.next != null)
            newNode.next.prev = newNode;

        current.next = newNode;
        newNode.prev = current;
    }
    return head_ref;
}

/*function to sort a doubly linked list
using insertion sort*/

static Node insertionSort(Node head_ref)
{

/*    Initialize 'sorted' - a sorted doubly linked list*/

    Node sorted = null;

/*    Traverse the given doubly linked list and
    insert every node to 'sorted'*/

    Node current = head_ref;
    while (current != null)
    {

/*        Store next for next iteration*/

        Node next = current.next;

/*        removing all the links so as to create
        'current' as a new node for insertion*/

        current.prev = current.next = null;

/*        insert current in 'sorted' doubly linked list*/

        sorted = sortedInsert(sorted, current);

/*        Update current*/

        current = next;
    }

/*    Update head_ref to point to
    sorted doubly linked list*/

    head_ref = sorted;

    return head_ref;
}

/*function to print the doubly linked list*/

static void printList(Node head)
{
    while (head != null)
    {
        Console.Write(head.data + " ");
        head = head.next;
    }
}

/*function to insert a node at the beginning of
the doubly linked list*/

static Node push(Node head_ref, int new_data)
{

/*    allocate node*/

    Node new_node = new Node();

/*    put in the data*/

    new_node.data = new_data;

/*    Make next of new node as head
    and previous as null*/

    new_node.next = (head_ref);
    new_node.prev = null;

/*    change prev of head node to new node*/

    if ((head_ref) != null)
        (head_ref).prev = new_node;

/*    move the head to point to the new node*/

    (head_ref) = new_node;

    return head_ref;
}

/*Driver code*/

public static void Main(String []args)
{

/*    start with the empty doubly linked list*/

    Node head = null;

/*    insert the following data*/

    head = push(head, 9);
    head = push(head, 3);
    head = push(head, 5);
    head = push(head, 10);
    head = push(head, 12);
    head = push(head, 8);

    Console.WriteLine("Doubly Linked List Before Sorting");
    printList(head);

    head = insertionSort(head);

    Console.WriteLine("\nDoubly Linked List After Sorting");
    printList(head);
}
}

/*C# program to check if doubly
linked list is palindrome or not*/

using System;

class GFG
{

/*Structure of node*/

public class Node
{
    public char data;
    public Node next;
    public Node prev;
};

/* Given a reference (pointer to pointer) to
the head of a list and an int, inserts a
new node on the front of the list. */

static Node push(Node head_ref, char new_data)
{
    Node new_node = new Node();
    new_node.data = new_data;
    new_node.next = head_ref;
    new_node.prev = null;
    if (head_ref != null)
    head_ref.prev = new_node ;
    head_ref = new_node;
    return head_ref;
}

/*Function to check if list is palindrome or not*/

static bool isPalindrome(Node left)
{
    if (left == null)
    return true;

/*    Find rightmost node*/

    Node right = left;
    while (right.next != null)
        right = right.next;

    while (left != right)
    {
        if (left.data != right.data)
            return false;

        left = left.next;
        right = right.prev;
    }

    return true;
}

/*Driver program*/

public static void Main(String[] args)
{
    Node head = null;
    head = push(head, 'l');
    head = push(head, 'e');
    head = push(head, 'v');
    head = push(head, 'e');
    head = push(head, 'l');

    if (isPalindrome(head))
        Console.Write("It is Palindrome");
    else
        Console.Write("Not Palindrome");
}
}

/*c# program to print Nodes level by level between given two levels*/
using System;
using System.Collections.Generic;

/* A binary tree Node has key, pointer to left and right children */

public class Node
{
    public int data;
    public Node left, right;

    public Node(int item)
    {
        data = item;
        left = right = null;
    }
}

public class BinaryTree
{
    public Node root;

/* Given a binary tree, print nodes from level number 'low' to level
       number 'high'*/

    public virtual void printLevels(Node node, int low, int high)
    {
        LinkedList<Node> Q = new LinkedList<Node>();

/*Marker node to indicate end of level*/

Node marker = new Node(4);

/*Initialize level number*/

int level = 1;

/*        Enqueue the only first level node and marker node for end of level*/

        Q.AddLast(node);
        Q.AddLast(marker);

/*        Simple level order traversal loop*/

        while (Q.Count > 0)
        {

/*            Remove the front item from queue*/

            Node n = Q.First.Value;
            Q.RemoveFirst();

/*            Check if end of level is reached*/

            if (n == marker)
            {

/*                print a new line and increment level number*/

                Console.WriteLine("");
                level++;

/*                Check if marker node was last node in queue or
                level number is beyond the given upper limit*/

                if (Q.Count == 0 || level > high)
                {
                    break;
                }

/*                Enqueue the marker for end of next level*/

                Q.AddLast(marker);

/*                If this is marker, then we don't need print it
                and enqueue its children*/

                continue;
            }

/*            If level is equal to or greater than given lower level,
            print it*/

            if (level >= low)
            {
                Console.Write(n.data + " ");
            }

/*            Enqueue children of non-marker node*/

            if (n.left != null)
            {
                Q.AddLast(n.left);
            }

            if (n.right != null)
            {
                Q.AddLast(n.right);
            }

        }
    }

/*    Driver program to test for above functions*/

    public static void Main(string[] args)
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(20);
        tree.root.left = new Node(8);
        tree.root.right = new Node(22);

        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(12);
        tree.root.left.right.left = new Node(10);
        tree.root.left.right.right = new Node(14);

        Console.Write("Level Order traversal between given two levels is ");
        tree.printLevels(tree.root, 2, 3);

    }
}

/*c# program to print nodes at k distance from root*/

 using System;

/* A binary tree node has data, pointer to left child
   and a pointer to right child */

public class Node
