/*C# program to print corner node 
at each level in a binary tree*/

using System;
using System.Collections.Generic;

/* A binary tree node has key, pointer to left
child and a pointer to right child */

public class Node 
{
    public int key;
    public Node left, right;

    public Node(int key) 
    {
        this.key = key;
        left = right = null;
    }
}

public class BinaryTree 
{
    Node root;

/* Function to print corner node at each level */

    void printCorner(Node root)
    {

/*        star node is for keeping track of levels*/

        Queue<Node> q = new Queue<Node>();

/*        pushing root node and star node*/

        q.Enqueue(root);

/*        Do level order traversal of Binary Tree*/

        while (q.Count != 0) 
        {

/*            n is the no of nodes in current Level*/

            int n = q.Count;
            for(int i = 0 ; i < n ; i++){
                Node temp = q.Peek();
                q.Dequeue();

/*                If it is leftmost corner value or rightmost corner value then print it*/

                if(i==0||i==n-1)
                    Console.Write(temp.key + " ");

/*            push the left and right children of the temp node*/

                if (temp.left != null) 
                    q.Enqueue(temp.left); 
                if (temp.right != null) 
                    q.Enqueue(temp.right); 

            }
        }

}

/*    Driver code*/

    public static void Main(String[] args) 
    {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(15);
        tree.root.left = new Node(10);
        tree.root.right = new Node(20);
        tree.root.left.left = new Node(8);
        tree.root.left.right = new Node(12);
        tree.root.right.left = new Node(16);
        tree.root.right.right = new Node(25);

        tree.printCorner(tree.root);
    }
}

/*C# Program to print binary tree in 2D*/

using System;

class GFG
{

static readonly int COUNT = 10;

/*A binary tree node*/

public class Node
{
    public int data;
    public Node left, right;

/* Constructor that allocates a new node with the
    given data and null left and right pointers. */

    public Node(int data)
    {
        this.data = data;
        this.left = null;
        this.right = null;
    }
};

/*Function to print binary tree in 2D
It does reverse inorder traversal*/

static void print2DUtil(Node root, int space)
{

/*    Base case*/

    if (root == null)
        return;

/*    Increase distance between levels*/

    space += COUNT;

/*    Process right child first*/

    print2DUtil(root.right, space);

/*    Print current node after space
    count*/

    Console.Write("\n");
    for (int i = COUNT; i < space; i++)
        Console.Write(" ");
    Console.Write(root.data + "\n");

/*    Process left child*/

    print2DUtil(root.left, space);
}

/*Wrapper over print2DUtil()*/

static void print2D(Node root)
{

/*    Pass initial space count as 0*/

    print2DUtil(root, 0);
}

