/*C# program to print left view
of Binary Tree*/

using System;
using System.Collections.Generic;

public class PrintRightView {

/*    Binary tree node*/

    private class Node {
        public int data;
        public Node left, right;

        public Node(int data)
        {
            this.data = data;
            this.left = null;
            this.right = null;
        }
    }

/*    function to print left view of binary tree*/

    private static void printRightView(Node root)
    {
        if (root == null)
            return;

        Queue<Node> queue = new Queue<Node>();
        queue.Enqueue(root);

        while (queue.Count != 0) {

/*            number of nodes at current level*/

            int n = queue.Count;

/*            Traverse all nodes of current level*/

            for (int i = 1; i <= n; i++) {
                Node temp = queue.Dequeue();

/*                Print the left most element at
                the level*/

                if (i == n)
                    Console.Write(temp.data + " ");

/*                Add left node to queue*/

                if (temp.left != null)
                    queue.Enqueue(temp.left);

/*                Add right node to queue*/

                if (temp.right != null)
                    queue.Enqueue(temp.right);
            }
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/*        construct binary tree as shown in
        above diagram*/

        Node root = new Node(10);
        root.left = new Node(2);
        root.right = new Node(3);
        root.left.left = new Node(7);
        root.left.right = new Node(8);
        root.right.right = new Node(15);
        root.right.left = new Node(12);
        root.right.right.left = new Node(14);
        printRightView(root);
    }
}

/*C# program for the above approach*/

using System;
using System.Collections.Generic;

class GFG{

/*Function to find the last element
left after performing N - 1 queries
of type X*/

static int rotate(int []arr, int N, int X)
{

/*    Stores the next power of 2*/

    int nextPower = 1;

/*    Iterate until nextPower is at most N*/

    while (nextPower <= N)
        nextPower *= 2;

/*    If X is equal to 1*/

    if (X == 1)
        return nextPower - N;

/*    Stores the power of 2 less than or
    equal to N*/

    int prevPower = nextPower / 2;

/*    Return the final value*/

    return 2 * (N - prevPower) + 1;
}

/*Driver Code*/

public static void Main()
{
    int []arr = { 1, 2, 3, 4, 5 };
    int X = 1;
    int N = arr.Length;

    Console.Write(rotate(arr, N, X));
}
}

/*C# program for the above approach*/

using System;
public class GFG {

/*    Function to print the matrix*/

    static void print(int[, ] mat)
    {

/*        Iterate over the rows*/

        for (int i = 0; i < mat.GetLength(0); i++) {

/*            Iterate over the columns*/

            for (int j = 0; j < mat.GetLength(1); j++)

/*                Print the value*/

                Console.Write(mat[i, j] + " ");

            Console.WriteLine();
        }
    }

/*    Function to perform the swapping of
    matrix elements in clockwise manner*/

    static void performSwap(int[, ] mat, int i, int j)
    {
        int N = mat.GetLength(0);

/*        Stores the last row*/

        int ei = N - 1 - i;

/*        Stores the last column*/

        int ej = N - 1 - j;

/*        Perform the swaps*/

        int temp = mat[i, j];
        mat[i, j] = mat[ej, i];
        mat[ej, i] = mat[ei, ej];
        mat[ei, ej] = mat[j, ei];
        mat[j, ei] = temp;
    }

/*    Function to rotate non - diagonal
    elements of the matrix K times in
    clockwise direction*/

    static void rotate(int[, ] mat, int N, int K)
    {

/*        Update K to K % 4*/

        K = K % 4;

/*        Iterate until K is positive*/

        while (K-- > 0) {

/*            Iterate each up to N/2-th row*/

            for (int i = 0; i < N / 2; i++) {

/*                Iterate each column
                from i to N - i - 1*/

                for (int j = i; j < N - i - 1; j++) {

/*                    Check if the element
                    at i, j is not a
                    diagonal element*/

                    if (i != j && (i + j) != N - 1) {

/*                        Perform the swapping*/

                        performSwap(mat, i, j);
                    }
                }
            }
        }

/*        Print the matrix*/

        print(mat);
    }

/*    Driver Code*/

    public static void Main(string[] args)
    {

        int K = 5;
        int[, ] mat = {
            { 1, 2, 3, 4 },
            { 6, 7, 8, 9 },
            { 11, 12, 13, 14 },
            { 16, 17, 18, 19 },
        };

        int N = mat.GetLength(0);
        rotate(mat, N, K);
    }
}

/*C# program for the above approach*/

using System;

class GFG{

/*Function to find the maximum sum of
consecutive 0s present at the start
and end of a string present in any
of the rotations of the given string*/

static void findMaximumZeros(string str, int n)
{

/*    Check if all the characters
    in the string are 0*/

    int c0 = 0;

/*    Iterate over characters
    of the string*/

    for(int i = 0; i < n; ++i)
    {
        if (str[i] == '0')
            c0++;
    }

/*    If the frequency of '1' is 0*/

    if (c0 == n)
    {

/*        Print n as the result*/

        Console.Write(n);
        return;
    }

/*    Concatenate the string
    with itself*/

    string s = str + str;

/*    Stores the required result*/

    int mx = 0;

/*    Generate all rotations of the string*/

    for(int i = 0; i < n; ++i)
    {

/*        Store the number of consecutive 0s
        at the start and end of the string*/

        int cs = 0;
        int ce = 0;

/*        Count 0s present at the start*/

        for(int j = i; j < i + n; ++j)
        {
            if (s[j] == '0')
                cs++;
            else
                break;
        }

/*        Count 0s present at the end*/

        for(int j = i + n - 1; j >= i; --j)
        {
            if (s[j] == '0')
                ce++;
            else
                break;
        }

/*        Calculate the sum*/

        int val = cs + ce;

/*        Update the overall
        maximum sum*/

        mx = Math.Max(val, mx);
    }

/*    Print the result*/

    Console.Write(mx);
}

/*Driver Code*/

public static void Main(string[] args)
{

/*    Given string*/

    string s = "1001";

/*    Store the size of the string*/

    int n = s.Length;

    findMaximumZeros(s, n);
}
}

/*C# program for the above approach*/

using System;

class GFG{

/*Function to find the maximum sum of
consecutive 0s present at the start
and end of any rotation of the string str*/

static void findMaximumZeros(string str, int n)
{

/*    Stores the count of 0s*/

    int c0 = 0;
    for(int i = 0; i < n; ++i)
    {
        if (str[i] == '0')
            c0++;
    }

/*    If the frequency of '1' is 0*/

    if (c0 == n)
    {

/*        Print n as the result*/

         Console.Write(n);
        return;
    }

/*    Stores the required sum*/

    int mx = 0;

/*    Find the maximum consecutive
    length of 0s present in the string*/

    int cnt = 0;

    for(int i = 0; i < n; i++)
    {
        if (str[i] == '0')
            cnt++;
        else
        {
            mx = Math.Max(mx, cnt);
            cnt = 0;
        }
    }

/*    Update the overall maximum sum*/

    mx = Math.Max(mx, cnt);

/*    Find the number of 0s present at
    the start and end of the string*/

    int start = 0, end = n - 1;
    cnt = 0;

/*    Update the count of 0s at the start*/

    while (str[start] != '1' && start < n)
    {
        cnt++;
        start++;
    }

/*    Update the count of 0s at the end*/

    while (str[end] != '1' && end >= 0)
    {
        cnt++;
        end--;
    }

/*    Update the maximum sum*/

    mx = Math.Max(mx, cnt);

/*    Print the result*/

    Console.Write(mx);
}

/*Driver Code*/

static public void Main ()
{

/*    Given string*/

    string s = "1001";

/*    Store the size of the string*/

    int n = s.Length;

    findMaximumZeros(s, n);
}
}

