using System;
using System.Collections;
class GFG{

/*Function to rotate
matrix by 45 degree*/

static void matrix(int n, int m,
                   int [,]li)
{

/*  Counter Variable*/

  int ctr = 0;

  while (ctr < 2 * n - 1)
  {
    for(int i = 0;
            i < Math.Abs(n - ctr - 1);
            i++)
    {
      Console.Write(" ");
    }

    ArrayList lst = new ArrayList();

/*    Iterate [0, m]*/

    for(int i = 0; i < m; i++)
    {

/*      Iterate [0, n]*/

      for(int j = 0; j < n; j++)
      {

/*        Diagonal Elements
        Condition*/

        if (i + j == ctr)
        {

/*          Appending the
          Diagonal Elements*/

          lst.Add(li[i, j]);
        }
      }
    }

/*    Printing reversed Diagonal
    Elements*/

    for(int i = lst.Count - 1;
            i >= 0; i--)
    {
      Console.Write((int)lst[i] + " ");
    }

    Console.Write("\n");
    ctr += 1;
  }
}

/*Driver code   */

