/*C# program to implement
the above approach*/

using System;

class GFG{

/*Function to left rotate*/

static void left_rotate(int[] arr)
{
    int last = arr[1];
    for(int i = 3;
            i < arr.Length;
            i = i + 2)
    {
        arr[i - 2] = arr[i];
    }
    arr[arr.Length - 1] = last;
}

/*Function to right rotate*/

static void right_rotate(int[] arr)
{
    int start = arr[arr.Length - 2];
    for(int i = arr.Length - 4;
            i >= 0; i = i - 2)
    {
        arr[i + 2] = arr[i];
    }
    arr[0] = start;
}

/*Function to rotate the array*/

public static void rotate(int[] arr)
{
    left_rotate(arr);
    right_rotate(arr);

    for(int i = 0; i < arr.Length; i++)
    {
        Console.Write(arr[i] + " ");
    }
}

/*Driver code*/

public static void Main()
{
    int[] arr = { 1, 2, 3, 4, 5, 6 };

    rotate(arr);
}
}

/*C# program for
the above approach*/

using System;
using System.Collections.Generic;
class GFG{

/*Function to maximize the matching
pairs between two permutation
using left and right rotation*/

static int maximumMatchingPairs(int []perm1,
                                int []perm2,
                                int n)
{

/*  Left array store distance of element
  from left side and right array store
  distance of element from right side*/

  int []left = new int[n];
  int []right = new int[n];

/*  Map to store index of elements*/

  Dictionary<int,
             int> mp1=new Dictionary<int,
                                     int>();
  Dictionary<int,
             int> mp2=new Dictionary<int,
                                     int>();

  for (int i = 0; i < n; i++)
  {
    mp1[perm1[i]] = i;
  }
  for (int j = 0; j < n; j++)
  {
    mp2[perm2[j]] = j;
  }

  for (int i = 0; i < n; i++)
  {

/*    idx1 is index of element
    in first permutation
    idx2 is index of element
    in second permutation*/

    int idx2 = mp2[perm1[i]];
    int idx1 = i;

    if (idx1 == idx2)
    {

/*      If element if present on same
      index on both permutations then
      distance is zero*/

      left[i] = 0;
      right[i] = 0;
    }
    else if (idx1 < idx2)
    {

/*      Calculate distance from left
      and right side*/

      left[i] = (n - (idx2 - idx1));
      right[i] = (idx2 - idx1);
    }
    else
    {

/*      Calculate distance from left
      and right side*/

      left[i] = (idx1 - idx2);
      right[i] = (n - (idx1 - idx2));
    }
  }

/*  Maps to store frequencies of elements
  present in left and right arrays*/

  Dictionary<int,
             int> freq1=new Dictionary <int,
                                        int>();
  Dictionary<int,
             int> freq2=new Dictionary <int,
                                        int>();

  for (int i = 0; i < n; i++)
  {
    if(freq1.ContainsKey(left[i]))
      freq1[left[i]]++;
    else
      freq1[left[i]] = 1;

    if(freq2.ContainsKey(right[i]))
      freq2[right[i]]++;
    else
      freq2[right[i]] = 1;
  }

  int ans = 0;

  for (int i = 0; i < n; i++)
  {

/*    Find maximum frequency*/

    ans = Math.Max(ans,
          Math.Max(freq1[left[i]],
                   freq2[right[i]]));
  }

/*  Return the result*/

  return ans;
}

/*Driver Code*/

public static void Main(string[] args)
{

/*  Given permutations P1 and P2*/

  int []P1 = {5, 4, 3, 2, 1};
  int []P2 = {1, 2, 3, 4, 5};
  int n = P1.Length;

/*  Function Call*/

  Console.Write(maximumMatchingPairs(P1, P2, n));
}
}

/*C# program to print
all possible rotations
of the given array*/

using System;
class GFG{

/*Global declaration of array*/

static int []arr = new int[10000];

/*Function to reverse array
between indices s and e*/

public static void reverse(int []arr,
                           int s, int e)
{
  while(s < e)
  {
    int tem = arr[s];
    arr[s] = arr[e];
    arr[e] = tem;
    s = s + 1;
    e = e - 1;
  }
}

/*Function to generate all
possible rotations of array*/

public static void fun(int []arr, int k)
{
  int n = 4 - 1;
  int v = n - k;

  if (v >= 0)
  {
    reverse(arr, 0, v);
    reverse(arr, v + 1, n);
    reverse(arr, 0, n);
  }
}

/*Driver code*/

public static void Main(String []args)
{
  arr[0] = 1;
  arr[1] = 2;
  arr[2] = 3;
  arr[3] = 4;

  for(int i = 0; i < 4; i++)
  {
    fun(arr, i);
    Console.Write("[");

    for(int j = 0; j < 4; j++)
    {
      Console.Write(arr[j] + ", ");
    }
    Console.Write("]");
  }
}
}

