/*C# program to implement
the above approach*/

using System;

class GFG{

/*Function to return the
count of rotations*/

public static int countRotation(int[] arr,
                                int low,
                                int high)
{

/*    If array is not rotated*/

    if (low > high)
    {
        return 0;
    }

    int mid = low + (high - low) / 2;

/*    Check if current element is
    greater than the next
    element*/

    if (mid < high &&
        arr[mid] > arr[mid + 1])
    {

/*        The next element is
        the smallest*/

        return mid + 1;
    }

/*    Check if current element is
    smaller than it's previous
    element*/

    if (mid > low &&
        arr[mid] < arr[mid - 1])
    {

/*        Current element is
        the smallest*/

        return mid;
    }

/*    Check if current element is
    greater than lower bound*/

    if (arr[mid] > arr[low])
    {

/*        The sequence is increasing
        so far
        Search for smallest
        element on the right
        subarray*/

        return countRotation(arr,
                             mid + 1,
                             high);
    }

    if (arr[mid] < arr[high])
    {

/*        Smallest element lies on the
        left subarray*/

        return countRotation(arr, low,
                             mid - 1);
    }

    else
    {

/*        Search for the smallest
        element on both subarrays*/

        int rightIndex = countRotation(arr,
                                       mid + 1,
                                       high);
        int leftIndex = countRotation(arr, low,
                                      mid - 1);

        if (rightIndex == 0)
        {
            return leftIndex;
        }
        return rightIndex;
    }
}

/*Driver code*/

public static void Main(String[] args)
{
    int[] arr1 = { 4, 5, 1, 2, 3 };

    Console.WriteLine(countRotation(arr1, 0,
                            arr1.Length - 1));
}
}

/*C# program to find Bitwise OR of two
equal halves of an array after performing
K right circular shifts*/

using System;
class GFG{

static int MAX = 100005;

/*Array for storing
the segment tree*/

static int []seg = new int[4 * MAX];

/*Function to build the segment tree*/

static void build(int node, int l,
                  int r, int []a)
{
    if (l == r)
        seg[node] = a[l];

    else
    {
        int mid = (l + r) / 2;

        build(2 * node, l, mid, a);
        build(2 * node + 1, mid + 1, r, a);

        seg[node] = (seg[2 * node] |
                     seg[2 * node + 1]);
    }
}

/*Function to return the OR
of elements in the range [l, r]*/

static int query(int node, int l, int r,
                 int start, int end, int []a)
{

/*    Check for out of bound condition*/

    if (l > end || r < start)
        return 0;

    if (start <= l && r <= end)
        return seg[node];

/*    Find middle of the range*/

    int mid = (l + r) / 2;

/*    Recurse for all the elements in array*/

    return ((query(2 * node, l, mid,
                      start, end, a)) |
            (query(2 * node + 1, mid + 1,
                   r, start, end, a)));
}

/*Function to find the OR sum*/

static void orsum(int []a, int n,
                  int q, int []k)
{

/*    Function to build the segment Tree*/

    build(1, 0, n - 1, a);

/*    Loop to handle q queries*/

    for(int j = 0; j < q; j++)
    {

/*        Effective number of
        right circular shifts*/

        int i = k[j] % (n / 2);

/*        Calculating the OR of
        the two halves of the
        array from the segment tree*/

/*        OR of second half of the
        array [n/2-i, n-1-i]*/

        int sec = query(1, 0, n - 1,
                        n / 2 - i,
                        n - i - 1, a);

/*        OR of first half of the array
        [n-i, n-1]OR[0, n/2-1-i]*/

        int first = (query(1, 0, n - 1, 0,
                         n / 2 - 1 - i, a) |
                    query(1, 0, n - 1,
                          n - i, n - 1, a));

        int temp = sec + first;

/*        Print readonly answer to the query*/

        Console.Write(temp + "\n");
    }
}

/*Driver Code*/

public static void Main(String[] args)
{
    int []a = { 7, 44, 19, 86, 65, 39, 75, 101 };
    int n = a.Length;
    int q = 2;

    int []k = { 4, 2 };

    orsum(a, n, q, k);
}
}

/*C# program of the above approach*/

using System;
class GFG{

/*Function that prints maximum
equal elements*/

static void maximumEqual(int[] a,
                         int[] b, int n)
{

/*    Vector to store the index
    of elements of array b*/

    int[] store = new int[(int) 1e5];

/*    Storing the positions of
    array B*/

    for(int i = 0; i < n; i++)
    {
       store[b[i]] = i + 1;
    }

/*    Frequency array to keep count
    of elements with similar
    difference in distances*/

    int[] ans = new int[(int) 1e5];

/*    Iterate through all element in arr1[]*/

    for(int i = 0; i < n; i++)
    {

/*       Calculate number of
       shift required to
       make current element
       equal*/

       int d = Math.Abs(store[a[i]] - (i + 1));

/*       If d is less than 0*/

       if (store[a[i]] < i + 1)
       {
           d = n - d;
       }

/*       Store the frequency
       of current diff*/

       ans[d]++;
    }

    int finalans = 0;

/*    Compute the maximum frequency
    stored*/

    for(int i = 0; i < 1e5; i++)
       finalans = Math.Max(finalans, ans[i]);

/*    Printing the maximum number
    of equal elements*/

    Console.Write(finalans + "\n");
}

/*Driver Code*/

public static void Main()
{

/*    Given two arrays*/

    int[]A = { 6, 7, 3, 9, 5 };
    int[]B = { 7, 3, 9, 5, 6 };

    int size = A.Length;

/*    Function Call*/

    maximumEqual(A, B, size);
}
}

/*C# program to calculate range sum
queries for anticlockwise
rotations of array by K*/

using System;

class GFG{

/*Function to execute the queries*/

static void rotatedSumQuery(int[] arr, int n,
                            int[,] query, int Q)
{

/*    Construct a new array
    of size 2*N to store
    prefix sum of every index*/

    int[] prefix = new int[2 * n];

/*    Copy elements to the new array*/

    for(int i = 0; i < n; i++)
    {
        prefix[i] = arr[i];
        prefix[i + n] = arr[i];
    }

/*    Calculate the prefix sum
    for every index*/

    for(int i = 1; i < 2 * n; i++)
        prefix[i] += prefix[i - 1];

/*    Set start pointer as 0*/

    int start = 0;

    for(int q = 0; q < Q; q++)
    {

/*        Query to perform
        anticlockwise rotation*/

        if (query[q, 0] == 1)
        {
            int k = query[q, 1];
            start = (start + k) % n;
        }

/*        Query to answer range sum*/

        else if (query[q, 0] == 2)
        {
            int L, R;
            L = query[q, 1];
            R = query[q, 2];

/*            If pointing to 1st index*/

            if (start + L == 0)

/*                Display the sum upto start + R*/

                Console.Write(prefix[start + R] + "\n");

            else

/*                Subtract sum upto start + L - 1
                from sum upto start + R*/

                Console.Write(prefix[start + R] -
                              prefix[start + L - 1] +
                              "\n");
        }
    }
}

/*Driver code*/

public static void Main()
{
    int[] arr = new int[] { 1, 2, 3, 4, 5, 6 };

/*    Number of query*/

    int Q = 5;

/*    Store all the queries*/

    int[,] query = new int[,] { { 2, 1, 3 },
                                { 1, 3, 0 },
                                { 2, 0, 3 },
                                { 1, 4, 0 },
                                { 2, 3, 5 } };

    int n = arr.Length;
    rotatedSumQuery(arr, n, query, Q);
}
}

/*C# implementation to check
that a given string can be
converted to another string
by circular clockwise shift
of each character by atmost
X times*/

using System;

class GFG{

/*Function to check that all
characters of s1 can be
converted to s2 by circular
clockwise shift atmost X times*/

static void isConversionPossible(String s1,
                                 String s2,
                                 int x)
{
    int diff = 0, n;
    n = s1.Length;

/*    Check for all characters of
    the strings whether the
    difference between their
    ascii values is less than
    X or not*/

    for(int i = 0; i < n; i++)
    {

/*        If both the characters
        are same*/

        if (s1[i] == s2[i])
            continue;

/*        Calculate the difference
        between the ASCII values
        of the characters*/

        diff = ((int)(s2[i] -
                      s1[i]) + 26) % 26;

/*        If difference exceeds X*/

        if (diff > x)
        {
            Console.Write("NO");
            return;
        }
    }
    Console.Write("YES");
}

/*Driver Code*/

public static void Main ()
{
    String s1 = "you";
    String s2 = "ara";

    int x = 6;

/*    Function call*/

    isConversionPossible(s1, s2, x);
}
}

