    {
        int n = 10203;
        Console.Write(countRotation(n));
    }
}

/*C# implementation of the approach*/

using System;

class GFG
{

/* Link list node */

public class Node
{
    public int data;
    public Node next;
}

/* A utility function to push a node */

static Node push(Node head_ref,
                 int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list off the new node */

    new_node.next = (head_ref);

/* move the head to point
    to the new node */

    (head_ref) = new_node;
    return head_ref;
}

/* A utility function to print linked list */

static void printList(Node node)
{
    while (node != null)
    {
        Console.Write(node.data + " -> ");
        node = node.next;
    }
    Console.Write("null");
}

/*Function that rotates the given linked list
clockwise by k and returns the updated
head pointer*/

static Node rightRotate(Node head, int k)
{

/*    If the linked list is empty*/

    if (head == null)
        return head;

/*    len is used to store length of
    the linked list, tmp will point
    to the last node after this loop*/

    Node tmp = head;
    int len = 1;
    while (tmp.next != null)
    {
        tmp = tmp.next;
        len++;
    }

/*    If k is greater than the size
    of the linked list*/

    if (k > len)
        k = k % len;

/*    Subtract from length to convert
    it into left rotation*/

    k = len - k;

/*    If no rotation needed then
    return the head node   */

    if (k == 0 || k == len)
        return head;

/*    current will either point to
    kth or null after this loop*/

    Node current = head;
    int cnt = 1;
    while (cnt < k && current != null)
    {
        current = current.next;
        cnt++;
    }

/*    If current is null then k is equal
    to the count of nodes in the list
    Don't change the list in this case*/

    if (current == null)
        return head;

/*    current points to the kth node*/

    Node kthnode = current;

/*    Change next of last node
    to previous head*/

    tmp.next = head;

/*    Change head to (k+1)th node*/

    head = kthnode.next;

/*    Change next of kth node to null*/

    kthnode.next = null;

/*    Return the updated head pointer*/

    return head;
}

/*Driver code*/

public static void Main(String []args)
{

/* The constructed linked list is:
    1.2.3.4.5 */

    Node head = null;
    head = push(head, 5);
    head = push(head, 4);
    head = push(head, 3);
    head = push(head, 2);
    head = push(head, 1);

    int k = 2;

/*    Rotate the linked list*/

    Node updated_head = rightRotate(head, k);

/*    Print the rotated linked list*/

    printList(updated_head);
}
}

/*C# implementation of the approach*/

using System;

class GFG
{

/*    Function that returns true if the array
    can be made increasing or decreasing
    after rotating it in any direction*/

    static bool isPossible(int []a, int n)
    {

/*        If size of the array is less than 3*/

        if (n <= 2)
            return true;

        int flag = 0;

/*        Check if the array is already decreasing*/

        for (int i = 0; i < n - 2; i++)
        {
            if (!(a[i] > a[i + 1] &&
                  a[i + 1] > a[i + 2]))
            {
                flag = 1;
                break;
            }
        }

/*        If the array is already decreasing*/

        if (flag == 0)
            return true;

        flag = 0;

/*        Check if the array is already increasing*/

        for (int i = 0; i < n - 2; i++)
        {
            if (!(a[i] < a[i + 1] &&
                  a[i + 1] < a[i + 2]))
            {
                flag = 1;
                break;
            }
        }

/*        If the array is already increasing*/

        if (flag == 0)
            return true;

/*        Find the indices of the minimum
        && the maximum value*/

        int val1 = int.MaxValue, mini = -1,
            val2 = int.MinValue, maxi = 0;
        for (int i = 0; i < n; i++)
        {
            if (a[i] < val1)
            {
                mini = i;
                val1 = a[i];
            }
            if (a[i] > val2)
            {
                maxi = i;
                val2 = a[i];
            }
        }

        flag = 1;

/*        Check if we can make array increasing*/

        for (int i = 0; i < maxi; i++)
        {
            if (a[i] > a[i + 1])
            {
                flag = 0;
                break;
            }
        }

/*        If the array is increasing upto max index
        && minimum element is right to maximum*/

        if (flag == 1 && maxi + 1 == mini)
        {
            flag = 1;

/*            Check if array increasing again or not*/

            for (int i = mini; i < n - 1; i++)
            {
                if (a[i] > a[i + 1])
                {
                    flag = 0;
                    break;
                }
            }
            if (flag == 1)
                return true;
        }

        flag = 1;

/*        Check if we can make array decreasing*/

        for (int i = 0; i < mini; i++)
        {
            if (a[i] < a[i + 1])
            {
                flag = 0;
                break;
            }
        }

/*        If the array is decreasing upto min index
        && minimum element is left to maximum*/

        if (flag == 1 && maxi - 1 == mini)
        {
            flag = 1;

/*            Check if array decreasing again or not*/

            for (int i = maxi; i < n - 1; i++)
            {
                if (a[i] < a[i + 1])
                {
                    flag = 0;
                    break;
                }
            }
            if (flag == 1)
                return true;
        }

/*        If it is not possible to make the
        array increasing or decreasing*/

        return false;
    }

/*    Driver code*/

    public static void Main()
    {
        int []a = { 4, 5, 6, 2, 3 };
        int n = a.Length;

        if (isPossible(a, n))
            Console.WriteLine( "Yes");
        else
            Console.WriteLine( "No");
    }
}

/*C# implementation of the approach*/

using System;

class GFG
{

/*    Function to return the count of rotated
    Strings which have more number of vowels in
    the first half than the second half*/

    static int cntRotations(string s, int n)
    {

/*        Create a new String*/

        string str = s + s;

/*        Pre array to store count of all vowels*/

        int []pre = new int[2 * n];

/*        Compute the prefix array*/

        for (int i = 0; i < 2 * n; i++)
        {
            if (i != 0)
                pre[i] += pre[i - 1];

            if (str[i] == 'a' || str[i] == 'e' ||
                str[i] == 'i' || str[i] == 'o' ||
                str[i] == 'u')
            {
                pre[i]++;
            }
        }

/*        To store the required answer*/

        int ans = 0;

/*        Find all rotated Strings*/

        for (int i = n - 1; i < 2 * n - 1; i++)
        {

/*            Right and left index of the String*/

            int r = i, l = i - n;

/*            x1 stores the number of vowels
            in the rotated String*/

            int x1 = pre[r];
            if (l >= 0)
                x1 -= pre[l];
            r = i - n / 2;

/*            Left stores the number of vowels
            in the first half of rotated String*/

            int left = pre[r];
            if (l >= 0)
                left -= pre[l];

/*            Right stores the number of vowels
            in the second half of rotated String*/

            int right = x1 - left;

/*            If the count of vowels in the first half
            is greater than the count in the second half*/

            if (left > right)
            {
                ans++;
            }
        }

/*        Return the required answer*/

        return ans;
    }

/*    Driver code*/

    public static void Main()
    {
        String s = "abecidft";
        int n = s.Length;

        Console.WriteLine( cntRotations(s, n));
    }
}

/*C# implementation of
the approach*/

using System;
class GFG
{

/*    Function to return the count of
    rotated strings which have more
    number of vowels in the first
    half than the second half*/

    static int cntRotations(char[] s, int n)
    {
      int lh = 0, rh = 0, i, ans = 0;

/*      Compute the number of
      vowels in first-half*/

      for (i = 0; i < n / 2; ++i)
        if (s[i] == 'a' || s[i] == 'e' ||
            s[i] == 'i' || s[i] == 'o' ||
            s[i] == 'u')
        {
          lh++;
        }

/*      Compute the number of
      vowels in second-half*/

      for (i = n / 2; i < n; ++i)
        if (s[i] == 'a' || s[i] == 'e' ||
            s[i] == 'i' || s[i] == 'o' ||
            s[i] == 'u')
        {
          rh++;
        }

/*      Check if first-half
      has more vowels*/

      if (lh > rh)
        ans++;

/*      Check for all possible
      rotations*/

      for (i = 1; i < n; ++i)
      {
        if (s[i - 1] == 'a' || s[i - 1] == 'e' ||
            s[i - 1] == 'i' || s[i - 1] == 'o' ||
            s[i - 1] == 'u')
        {
          rh++;
          lh--;
        }
        if (s[(i - 1 + n / 2) % n] == 'a' ||
            s[(i - 1 + n / 2) % n] == 'e' ||
            s[(i - 1 + n / 2) % n] == 'i' ||
            s[(i - 1 + n / 2) % n] == 'o' ||
            s[(i - 1 + n / 2) % n] == 'u')
        {
          rh--;
          lh++;
        }
        if (lh > rh)
          ans++;
      }

/*      Return the answer*/

      return ans;
    }

/*  Driver code    */

  static void Main()
  {
      char[] s = {'a','b','e','c',
              'i','d','f','t'};
      int n = s.Length;

/*      Function call*/

      Console.WriteLine(cntRotations(s, n));
  }
}

/*C# implementation of the approach*/

using System;

class GFG
{
static int size = 2;

/*Function to perform the required
queries on the given string*/

static void performQueries(String str, int n,
                           int [,]queries, int q)
{

/*    Pointer pointing to the current
    starting character of the string*/

    int ptr = 0;

/*    For every query*/

    for (int i = 0; i < q; i++)
    {

/*        If the query is to rotate the string*/

        if (queries[i, 0] == 1)
        {

/*            Update the pointer pointing to the
            starting character of the string*/

            ptr = (ptr + queries[i, 1]) % n;
        }
        else
        {
            int k = queries[i, 1];

/*            Index of the kth character in the
            current rotation of the string*/

            int index = (ptr + k - 1) % n;

/*            Print the kth character*/

            Console.WriteLine(str[index]);
        }
    }
}

/*Driver code*/

public static void Main(String[] args)
{
    String str = "abcdefgh";
    int n = str.Length;

    int [,]queries = { { 1, 2 }, { 2, 2 },
                       { 1, 4 }, { 2, 7 } };
    int q = queries.GetLength(0);

    performQueries(str, n, queries, q);
}
}

