using System;
class Solution {

/*    Function to count of all rotations
    which are odd and even*/

    static void countOddRotations(int n)
    {
        int odd_count = 0, even_count = 0;
        do {
            int digit = n % 10;
            if (digit % 2 == 1)
                odd_count++;
            else
                even_count++;
            n = n / 10;
        } while (n != 0);

        Console.WriteLine("Odd = " + odd_count);
        Console.WriteLine("Even = " + even_count);
    }

