/*C# implementation of the above approach*/

using System;

class GFG
{

/*Definition of node of linkedlist*/

public class ListNode
{
    public int data;
    public ListNode next;
}

/*This function take head pointer of list,
start and end points of sublist that is
to be rotated and the number k and rotate
the sublist to right by k places.*/

public static void rotateSubList(ListNode A, int m,
                                      int n, int k)
{
    int size = n - m + 1;

/*    If k is greater than size of sublist
    then we will take its modulo with
    size of sublist*/

    if (k > size)
    {
        k = k % size;
    }

/*    If k is zero or k is equal to size
    or k is a multiple of size of sublist
    then list remains intact*/

    if (k == 0 || k == size)
    {
        ListNode head = A;
        while (head != null)
        {
            Console.Write(head.data);
            head = head.next;
        }
        return;
    }

/*m-th node*/

ListNode link = null; 
    if (m == 1)
    {
        link = A;
    }

/*    This loop will traverse all node till
    end node of sublist.    
Current traversed node*/

ListNode c = A;

/*Count of traversed nodes*/

int count = 0;  
    ListNode end = null;

/*Previous of m-th node*/

ListNode pre = null; 
    while (c != null)
    {
        count++;

/*        We will save (m-1)th node and later
        make it point to (n-k+1)th node*/

        if (count == m - 1)
        {
            pre = c;
            link = c.next;
        }
        if (count == n - k)
        {
            if (m == 1)
            {
                end = c;
                A = c.next;
            }
            else
            {
                end = c;

/*                That is how we bring (n-k+1)th
                node to front of sublist.*/

                pre.next = c.next;
            }
        }

/*        This keeps rest part of list intact.*/

        if (count == n)
        {
            ListNode d = c.next;
            c.next = link;
            end.next = d;
            ListNode head = A;
            while (head != null)
            {
                Console.Write(head.data + " ");
                head = head.next;
            }
            return;
        }
        c = c.next;
    }
}

/*Function for creating and linking new nodes*/

public static ListNode push(ListNode head, int val)
{
    ListNode new_node = new ListNode();
    new_node.data = val;
    new_node.next = (head);
    (head) = new_node;
    return head;
}

/*Driver code*/

public static void Main(string[] args)
{
    ListNode head = null;
    head = push(head, 70);
    head = push(head, 60);
    head = push(head, 50);
    head = push(head, 40);
    head = push(head, 30);
    head = push(head, 20);
    head = push(head, 10);
    ListNode tmp = head;
    Console.Write("Given List: ");
    while (tmp != null)
    {
        Console.Write(tmp.data + " ");
        tmp = tmp.next;
    }
    Console.WriteLine();

    int m = 3, n = 6, k = 2;
    Console.Write("After rotation of sublist: ");
    rotateSubList(head, m, n, k);
}
}

/*C# program to Generating numbers that
are divisor of their right-rotations */


using System;
public class GFG{

/*    Function to check if N is a
    divisor of its right-rotation*/

    static bool rightRotationDivisor(int N)
    {
        int lastDigit = N % 10;
        int rightRotation = (int)(lastDigit * Math.Pow(10 ,(int)(Math.Log10(N)))
                        + Math.Floor((double)N/10));
        return (rightRotation % N == 0);
    }

/*    Function to generate m-digit
    numbers which are divisor of
    their right-rotation*/

    static void generateNumbers(int m)
    {
        for (int i= (int)Math.Pow(10,(m - 1)); i < Math.Pow(10 , m);i++)
            if (rightRotationDivisor(i))
                Console.WriteLine(i);
    }

/*    Driver code*/

    public static void Main()
    {
        int m = 3;
        generateNumbers(m);

    }
}

/*C# program to Generating numbers that
are divisor of their right-rotations*/

using System;
using System.Collections.Generic;

class GFG
{

/*Function to generate m-digit
numbers which are divisor of
their right-rotation*/

static void generateNumbers(int m)
{
    List<int> numbers = new List<int>();
    int k_max, x;

    for (int y = 0; y < 10; y++)
    {

        k_max = (int)(Math.Pow(10, m - 2) * (10 * y + 1)) /
                (int)(Math.Pow(10, m - 1) + y);

        for (int k = 1; k <= k_max; k++)
        {
            x = (int)(y * (Math.Pow(10, m - 1) - k)) /
                                   (10 * k - 1);

            if ((int)(y * (Math.Pow(10, m - 1) - k)) %
                                   (10 * k - 1) == 0)
                numbers.Add(10 * x + y);
        }
    }

    numbers.Sort();
    for (int i = 0; i < numbers.Count; i++)
        Console.WriteLine(numbers[i]);
}

/*Driver code*/

public static void Main(String []args)
{
    int m = 3;
    generateNumbers(m);
}
}

/*C# program to check if an
array is sorted and rotated
clockwise*/

using System;

class GFG {

/*    Function to check if an array is
    sorted and rotated clockwise*/

    static void checkIfSortRotated(int[] arr, int n)
    {
        int minEle = int.MaxValue;
        int maxEle = int.MinValue;
        int minIndex = -1;

/*        Find the minimum element
        and it's index*/

        for (int i = 0; i < n; i++) {
            if (arr[i] < minEle) {
                minEle = arr[i];
                minIndex = i;
            }
        }

        bool flag1 = true;

/*        Check if all elements before
        minIndex are in increasing order*/

        for (int i = 1; i < minIndex; i++) {
            if (arr[i] < arr[i - 1]) {
                flag1 = false;
                break;
            }
        }

        bool flag2 = true;

/*        Check if all elements after
        minIndex are in increasing order*/

        for (int i = minIndex + 1; i < n; i++) {
            if (arr[i] < arr[i - 1]) {
                flag2 = false;
                break;
            }
        }

/*        Check if last element of the array
        is smaller than the element just
        before the element at minIndex
        starting element of the array
        for arrays like [3,4,6,1,2,5] - not circular
        array*/

        if (flag1 && flag2 && (arr[n - 1] < arr[0]))
            Console.WriteLine("YES");
        else
            Console.WriteLine("NO");
    }

/*    Driver code*/

    public static void Main()
    {
        int[] arr = { 3, 4, 5, 1, 2 };

        int n = arr.Length;

/*          Function Call*/

        checkIfSortRotated(arr, n);
    }
}

