    {
      int[] arr = { 7, 7, 8, 8, 9, 1, 1, 4, 2, 2 };
      int n = arr.Length;
      occurredOnce(arr, n);
    }
}

/*C# implementation to find
elements that appeared only once*/

using System;

class GFG
{

/*Function to find the elements that
appeared only once in the array*/

static void occurredOnce(int[] arr, int n)
{
    int i = 1, len = n;

/*    Check if the first and last
    element is equal. If yes,
    remove those elements*/

    if (arr[0] == arr[len - 1])
    {
        i = 2;
        len--;
    }

/*    Start traversing the
    remaining elements*/

    for (; i < n; i++)

/*        Check if current element is
        equal to the element at
        immediate previous index
        If yes, check the same
        for next element*/

        if (arr[i] == arr[i - 1])
            i++;

/*        Else print the current element*/

        else
            Console.Write(arr[i - 1] + " ");

/*    Check for the last element*/

    if (arr[n - 1] != arr[0] &&
        arr[n - 1] != arr[n - 2])
        Console.Write(arr[n - 1]);
}

/*Driver code*/

public static void Main()
{
    int[] arr = {7, 7, 8, 8, 9,
                1, 1, 4, 2, 2};
    int n = arr.Length;

    occurredOnce(arr, n);
}
}

/*C# program to Split the array and
add the first part to the end*/

using System;
class GFG
{

/* Function to reverse arr[] from index start to end*/

static void rvereseArray(int[] arr, int start, int end)
{
    while (start < end)
    {
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

/*Function to print an array*/

static void printArray(int[] arr, int size)
{
    for (int i = 0; i < size; i++)
        Console.Write(arr[i] +" ");
}

/* Function to left rotate arr[] of size n by k */

static void splitArr(int[] arr, int k, int n)
{
    rvereseArray(arr, 0, n - 1);
    rvereseArray(arr, 0, n - k - 1);
    rvereseArray(arr, n - k, n - 1);
}

/*Driver code*/

public static void Main()
{
    int[] arr = { 12, 10, 5, 6, 52, 36 };
    int n = arr.Length;
    int k = 2;

/*    Function calling*/

    splitArr(arr, k, n);
    printArray(arr, n);
}
}

/*C# program to check if
two strings are rotations
of each other.*/

using System;

class GFG
{
public static bool isRotation(string a,
                              string b)
{
    int n = a.Length;
    int m = b.Length;
    if (n != m)
        return false;

/*    create lps[] that will
    hold the longest prefix
    suffix values for pattern*/

    int []lps = new int[n];

/*    length of the previous
    longest prefix suffix*/

    int len = 0;
    int i = 1;

/*    lps[0] is always 0*/

    lps[0] = 0;

/*    the loop calculates
    lps[i] for i = 1 to n-1*/

    while (i < n)
    {
        if (a[i] == b[len])
        {
            lps[i] = ++len;
            ++i;
        }
        else
        {
            if (len == 0)
            {
                lps[i] = 0;
                ++i;
            }
            else
            {
                len = lps[len - 1];
            }
        }
    }

    i = 0;

/*    match from that
    rotating point*/

    for (int k = lps[n - 1]; k < m; ++k)
    {
        if (b[k] != a[i++])
            return false;
    }
    return true;
}

/*Driver code*/

public static void Main()
{
    string s1 = "ABACD";
    string s2 = "CDABA";

    Console.WriteLine(isRotation(s1, s2) ?
                                     "1" : "0");
}
}

/*C# program to count all
rotations divisible by 8*/

using System;

class GFG {

/*    function to count of all
    rotations divisible by 8*/

    static int countRotationsDivBy8(String n)
    {
        int len = n.Length;
        int count = 0;

/*        For single digit number*/

        if (len == 1)
        {
            int oneDigit = n[0] - '0';
            if (oneDigit % 8 == 0)
                return 1;
            return 0;
        }

/*        For two-digit numbers
        (considering all pairs)*/

        if (len == 2)
        {

/*            first pair*/

            int first = (n[0] - '0') *
                         10 + (n[1] - '0');

/*            second pair*/

            int second = (n[1] - '0') *
                          10 + (n[0] - '0');

            if (first % 8 == 0)
                count++;
            if (second % 8 == 0)
                count++;
            return count;
        }

/*        considering all three -
        digit sequences*/

        int threeDigit;
        for (int i = 0; i < (len - 2); i++)
        {
            threeDigit = (n[i] - '0') * 100 +
                         (n[i + 1] - '0') * 10 +
                         (n[i + 2] - '0');
            if (threeDigit % 8 == 0)
                count++;
        }

/*        Considering the number formed by the
        last digit and the first two digits*/

        threeDigit = (n[len - 1] - '0') * 100 +
                     (n[0] - '0') * 10 +
                     (n[1] - '0');

        if (threeDigit % 8 == 0)
            count++;

/*        Considering the number formed
        by the last two digits and
        the first digit*/

        threeDigit = (n[len - 2] - '0') * 100 +
                     (n[len - 1] - '0') * 10 +
                     (n[0] - '0');
        if (threeDigit % 8 == 0)
            count++;

/*        required count of rotations*/

        return count;
    }

/*    Driver Code*/

    public static void Main ()
    {
        String n = "43262488612";
        Console.Write("Rotations: "
                      +countRotationsDivBy8(n));

    }
}

/*C# program to make all
strings same using move
to end operations.*/
using System;
public class GFG
{

/*Returns minimum number of
moves to end operations
to make all strings same.*/

public  static int minimunMoves(string[] arr, int n)
{
    int ans = int.MaxValue;
    for (int i = 0; i < n; i++)
    {
        int curr_count = 0;

/*        Consider s[i] as target
        string and count rotations
        required to make all other
        strings same as str[i].*/

        string tmp = "";
        for (int j = 0; j < n; j++)
        {
            tmp = arr[j] + arr[j];

/*            find function returns the
            index where we found arr[i]
            which is actually count of
            move-to-front operations.*/

            int index = tmp.IndexOf(arr[i], StringComparison.Ordinal);

/*            If any two strings are not
            rotations of each other,
            we can't make them same.*/

            if (index == arr[i].Length)
            {
                return -1;
            }

            curr_count += index;
        }

        ans = Math.Min(curr_count, ans);
    }

    return ans;
}

/*Driver code*/

public static void Main(string[] args)
{
    string[] arr = new string[] {"xzzwo", "zwoxz", "zzwox", "xzzwo"};
    int n = arr.Length;
    Console.WriteLine(minimunMoves(arr, n));
}
}

/*C# implementation for restoring original
sort in rotated sorted array*/

using System;

class GFG
{

/*Function to restore the Original Sort*/

static void restoreSortedArray(int []arr, int n)
{
    for (int i = 0; i < n; i++)
    {
        if (arr[i] > arr[i + 1])
        {

/*            In reverse(), the first parameter
            is iterator to beginning element
            and second parameter is iterator
            to last element plus one.*/

            reverse(arr,0,i);
            reverse(arr , i + 1, n);
            reverse(arr,0, n);
        }
    }
}

static void reverse(int[] arr, int i, int j)
{
    int temp;
    while(i < j)
    {
        temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

/*Function to print the Array*/

static void printArray(int []arr, int size)
{
    for (int i = 0; i < size; i++)
        Console.Write(arr[i] + " ");
}

/*Driver code*/

public static void Main(String[] args)
{
    int[] arr = { 3, 4, 5, 1, 2 };
    int n = arr.Length;
    restoreSortedArray(arr, n - 1);
    printArray(arr, n);
}
}

/*C# implementation for restoring original
sort in rotated sorted array using binary search*/

using System;

class GFG
{

/*    Function to find start index of array*/

    static int findStartIndexOfArray(int []arr,
                            int low, int high)
    {
        if (low > high)
        {
            return -1;
        }

        if (low == high)
        {
            return low;
        }

        int mid = low + (high - low) / 2;
        if (arr[mid] > arr[mid + 1])
        {
            return mid + 1;
        }

        if (arr[mid - 1] > arr[mid])
        {
            return mid;
        }

        if (arr[low] > arr[mid])
        {
            return findStartIndexOfArray(arr, low, mid - 1);
        }
        else
        {
            return findStartIndexOfArray(arr, mid + 1, high);
        }
    }

/*    Function to restore the Original Sort*/

    static void restoreSortedArray(int []arr, int n)
    {

/*        array is already sorted*/

        if (arr[0] < arr[n - 1])
        {
            return;
        }

        int start = findStartIndexOfArray(arr, 0, n - 1);

/*        In reverse(), the first parameter
        is iterator to beginning element
        and second parameter is iterator
        to last element plus one.*/

        Array.Sort(arr, 0, start);
        Array.Sort(arr, start, n);
        Array.Sort(arr);

    }

/*    Function to print the Array*/

    static void printArray(int []arr, int size)
    {
        for (int i = 0; i < size; i++)
        {
            Console.Write(arr[i] + " ");
        }
    }

/*    Driver code*/

    public static void Main()
    {
        int []arr = {1, 2, 3, 4, 5};
        int n = arr.Length;
        restoreSortedArray(arr, n);
        printArray(arr, n);
    }
}

/*C# program to rotate a linked list block wise*/

using System;
public class GFG
{

/* Link list node */

  public
    class Node
    {
      public
        int data;
      public
        Node next;
    };
  static Node tail;

/*  Recursive function to rotate one block*/

  static Node rotateHelper(Node blockHead,
                           Node blockTail,
                           int d,
                           int k)
  {
    if (d == 0)
      return blockHead;

/*    Rotate Clockwise*/

    if (d > 0)
    {
      Node temp = blockHead;
      for (int i = 1; temp.next.next != null &&
           i < k - 1; i++)
        temp = temp.next;
      blockTail.next = blockHead;
      tail = temp;
      return rotateHelper(blockTail, temp,
                          d - 1, k);
    }

/*    Rotate anti-Clockwise*/

    if (d < 0)
    {
      blockTail.next = blockHead;
      tail = blockHead;
      return rotateHelper(blockHead.next,
                          blockHead, d + 1,  k);
    }
    return blockHead;
  }

/*  Function to rotate the linked list block wise*/

  static Node rotateByBlocks(Node head,
                             int k, int d)
  {

/*    If length is 0 or 1 return head*/

    if (head == null || head.next == null)
      return head;

/*    if degree of rotation is 0, return head*/

    if (d == 0)
      return head;
    Node temp = head;
    tail = null;

/*    Traverse upto last element of this block*/

    int i;
    for (i = 1; temp.next != null && i < k; i++)
      temp = temp.next;

/*    storing the first node of next block*/

    Node nextBlock = temp.next;

/*    If nodes of this block are less than k.
    Rotate this block also*/

    if (i < k)
      head = rotateHelper(head, temp, d % k,
                          i);
    else
      head = rotateHelper(head, temp, d % k,
                          k);

/*    Append the new head of next block to
    the tail of this block*/

    tail.next = rotateByBlocks(nextBlock, k,
                               d % k);

/*    return head of updated Linked List*/

    return head;
  }

/* UTILITY FUNCTIONS */

/* Function to push a node */

  static Node push(Node head_ref, int new_data)
  {
    Node new_node = new Node();
    new_node.data = new_data;
    new_node.next = head_ref;
    head_ref = new_node;
    return head_ref;

  }

/* Function to print linked list */

  static void printList(Node node)
  {
    while (node != null)
    {
      Console.Write(node.data + " ");
      node = node.next;
    }
  }

/* Driver code*/

  public static void Main(String[] args)
  {

/* Start with the empty list */

    Node head = null;

/*    create a list 1.2.3.4.5.
    6.7.8.9.null*/

    for (int i = 9; i > 0; i -= 1)
      head = push(head, i);
    Console.Write("Given linked list \n");
    printList(head);

/*    k is block size and d is number of
    rotations in every block.*/

    int k = 3, d = 2;
    head = rotateByBlocks(head, k, d);
    Console.Write("\nRotated by blocks Linked list \n");
    printList(head);
  }
}

/*C# program to determine minimum number
of rotations required to yield same
string.*/

using System;

class GFG {

/*    Returns count of rotations to get
    the same string back.*/

    static int findRotations(String str)
    {

/*        tmp is the concatenated string.*/

        String tmp = str + str;
        int n = str.Length;

        for (int i = 1; i <= n; i++)
        {

/*            substring from i index of
            original string size.*/


            String substring = 
                 tmp.Substring(i, str.Length);

/*            if substring matches with
            original string then we will
            come out of the loop.*/

            if (str == substring)
                return i;
        }

        return n;
    }

/*    Driver Method*/

    public static void Main()
    {
        String str = "abc";

        Console.Write(findRotations(str));
    }
}

/*C# program to check if two numbers
are bit rotations of each other.*/

using System;

class GFG
{

/*function to check if two numbers
are equal after bit rotation*/

static bool isRotation(long x, long y)
{

/*    x64 has concatenation of
    x with itself.*/

    long x64 = x | (x << 32);

    while (x64 >= y)
    {

/*        comapring only last 32 bits*/

        if (x64 == y)
        {
            return true;
        }

/*        right shift by 1 unit*/

        x64 >>= 1;
    }
    return false;
}

/*Driver Code*/

public static void Main()
{
    long x = 122;
    long y = 2147483678L;

    if (isRotation(x, y) == false)
    {
        Console.Write("Yes");
    }
    else
    {
        Console.Write("No");
    }
}
}

