/*C# program to count all rotation
divisible by 4.*/

using System;

class GFG {

/*    Returns count of all
    rotations divisible
    by 4*/

    static int countRotations(String n)
    {
        int len = n.Length;

/*        For single digit number*/

        if (len == 1)
        {
            int oneDigit = n[0] - '0';

            if (oneDigit % 4 == 0)
                return 1;

            return 0;
        }

/*        At-least 2 digit
        number (considering all
        pairs)*/

        int twoDigit, count = 0;
        for (int i = 0; i < (len - 1); i++)
        {
            twoDigit = (n[i] - '0') * 10 +
                          (n[i + 1] - '0');

            if (twoDigit % 4 == 0)
                count++;
        }

/*        Considering the number
        formed by the pair of
        last digit and 1st digit*/

        twoDigit = (n[len - 1] - '0') * 10 +
                               (n[0] - '0');

        if (twoDigit % 4 == 0)
            count++;

        return count;
    }

/*    Driver program*/

    public static void Main()
    {
        String n = "4834";
        Console.Write("Rotations: " +
                    countRotations(n));
    }
}

/*C# program to check if a string is two time
rotation of another string.*/

using System;
public class Test {

/*    Method to check if string2 is obtained by
    string 1*/

    public static bool isRotated(string str1, string str2)
    {
        if (str1.Length != str2.Length) {
            return false;
        }

        if (str1.Length < 2) {
            return str1.Equals(str2);
        }

        string clock_rot = "";
        string anticlock_rot = "";
        int len = str2.Length;

/*        Initialize string as anti-clockwise rotation*/

        anticlock_rot
            = anticlock_rot
              + str2.Substring(len - 2, len - (len - 2))
              + str2.Substring(0, len - 2);

/*        Initialize string as clock wise rotation*/

        clock_rot = clock_rot + str2.Substring(2)
                    + str2.Substring(0, 2);

/*        check if any of them is equal to string1*/

        return (str1.Equals(clock_rot)
                || str1.Equals(anticlock_rot));
    }

/*    Driver code*/

    public static void Main(string[] args)
    {
        string str1 = "geeks";
        string str2 = "eksge";

        Console.WriteLine(isRotated(str1, str2) ? "Yes"
                                                : "No");
    }
}

/*A simple C# program to find
lexicographically minimum rotation
of a given String*/

using System;

class GFG
{

/*    This functionr return lexicographically
    minimum rotation of str*/

    static String minLexRotation(String str)
    {

/*        Find length of given String*/

        int n = str.Length;

/*        Create an array of strings
        to store all rotations*/

        String []arr = new String[n];

/*        Create a concatenation of
        String with itself*/

        String concat = str + str;

/*        One by one store all rotations
        of str in array. A rotation is
        obtained by getting a substring of concat*/

        for (int i = 0; i < n; i++)
        {
            arr[i] = concat.Substring(i, n);
        }

/*        Sort all rotations*/

        Array.Sort(arr);

/*        Return the first rotation
        from the sorted array*/

        return arr[0];
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        Console.WriteLine(minLexRotation("GEEKSFORGEEKS"));
        Console.WriteLine(minLexRotation("GEEKSQUIZ"));
        Console.WriteLine(minLexRotation("BCABDADAB"));
    }
}

/*C# program to rotate
a linked list counter clock wise*/

using System;

class GFG{

/* Link list node */

public class Node {

    public int data;
    public Node next;
};
static  Node head = null;

/*This function rotates a linked list
counter-clockwise and updates the
head. The function assumes that k is
smaller than size of linked list.*/

static void rotate( int k)
{
    if (k == 0)
        return;

/*    Let us understand the below
    code for example k = 4 and
    list = 10.20.30.40.50.60.*/

    Node current = head;

/*    Traverse till the end.*/

    while (current.next != null)
        current = current.next;

    current.next = head;
    current = head;

/*    traverse the linked list to k-1 position which
    will be last element for rotated array.*/

    for (int i = 0; i < k - 1; i++)
        current = current.next;

/*    update the head_ref and last element pointer to null*/

    head = current.next;
    current.next = null;
}

/* UTILITY FUNCTIONS */

/* Function to push a node */

static void push(int new_data)
{

/* allocate node */

    Node new_node = new Node();

/* put in the data */

    new_node.data = new_data;

/* link the old list off the new node */

    new_node.next = head;

/* move the head to point to the new node */

    head = new_node;
}

/* Function to print linked list */

static void printList(Node node)
{
    while (node != null)
    {
        Console.Write(node.data + " ");
        node = node.next;
    }
}

/* Driver code*/

public static void  Main(String[] args)
{

/* Start with the empty list */

/*    create a list 10.20.30.40.50.60*/

    for (int i = 60; i > 0; i -= 10)
        push( i);

    Console.Write("Given linked list \n");
    printList(head);
    rotate( 4);

    Console.Write("\nRotated Linked list \n");
    printList(head);
}
}

/*C# program for the above approach*/

using System;

/*Node structure of the circular
Linked list*/

class Node
{
    public int data;
    public Node next;

/*    Constructor*/

    public Node(int data)
    {
        this.data = data;
        this.next = null;
    }
}

class GFG{

static Node head;

/*Function to print the elements
of a Linked list*/

static void print(Node head)
{
    Node temp = head;

/*    Iterate the linked list*/

    while (temp != null)
    {

/*        Print the data*/

        Console.Write(temp.data + " ");
        temp = temp.next;
    }
}

/*Function to find the next
greater element for each node*/

static void NextGreaterElement(Node head)
{

/*    Stores the head of circular
    Linked list*/

    Node H = head;

/*    Stores the head of the
    resulting linked list*/

    Node res = null;

/*    Stores the temporary head of
    the resulting Linked list*/

    Node tempList = null;

/*    Iterate until head
    is not equal to H*/

    do{

/*        Used to iterate over the
        circular Linked List*/

        Node curr = head;

/*        Stores if there exist
        any next Greater element*/

        int Val = -1;

/*        Iterate until head is
        not equal to curr*/

        do{

/*            If the current node
            is smaller*/

            if (head.data < curr.data)
            {

/*                Update the value
                of Val*/

                Val = curr.data;
                break;
            }

/*            Update curr*/

            curr = curr.next;

        } while (curr != head);

/*        If res is Null*/

        if (res == null)
        {

/*            Create new Node with
            value curr.data*/

            res = new Node(Val);

/*            Assign address of
            res to tempList*/

            tempList = res;
        }
        else
        {

/*            Update tempList*/

            tempList.next = new Node(Val);

/*            Assign address of the
            next node to tempList*/

            tempList = tempList.next;
        }

/*        Update the value of
        head node*/

        head = head.next;
    } while (head != H);

/*    Print the resulting
    Linked list*/

    print(res);
}

/*Driver Code*/

static public void Main()
{
    head = new Node(1);
    head.next = new Node(5);
    head.next.next = new Node(12);
    head.next.next.next = new Node(10);

    head.next.next.next.next = new Node(0);
    head.next.next.next.next.next = head;

    NextGreaterElement(head);
}
}

