/*C# program to remove all
the Even Parity Nodes from a
circular singly linked list*/

using System;
class GFG{

/*Structure for a node*/

public class Node
{
  public int data;
  public Node next;
};

/*Function to insert a node at
the beginning of a Circular
linked list*/

static Node push(Node head_ref,
                 int data)
{

/*  Create a new node
  and make head as next
  of it.*/

  Node ptr1 = new Node();

  Node temp = head_ref;
  ptr1.data = data;
  ptr1.next = head_ref;

/*  If linked list is not
  null then set the next
  of last node*/

  if (head_ref != null)
  {

/*    Find the node before head
    and update next of it.*/

    while (temp.next != head_ref)
      temp = temp.next;

    temp.next = ptr1;
  }
  else

/*    Point for the first node*/

    ptr1.next = ptr1;

  head_ref = ptr1;
  return head_ref;
}

/*Function to delete the node
from a Circular Linked list*/

static void deleteNode(Node head_ref,
                       Node del)
{

/*  If node to be deleted is
  head node*/

  if (head_ref == del)
    head_ref = del.next;

  Node temp = head_ref;

/*  Traverse list till not
  found delete node*/

  while (temp.next != del)
  {
    temp = temp.next;
  }

/*  Copy the address of
  the node*/

  temp.next = del.next;

  return;
}

/*Function that returns true
if count of set bits in x
is even*/

static bool isEvenParity(int x)
{

/*  Parity will store the
  count of set bits*/

  int parity = 0;

  while (x != 0)
  {
    if ((x & 1) != 0)
      parity++;

    x = x >> 1;
  }

  if (parity % 2 == 0)
    return true;
  else
    return false;
}

/*Function to delete all the
Even Parity Nodes from the
singly circular linked list*/

static void deleteEvenParityNodes(Node head)
{
  if (head == null)
    return;

  if (head == head.next)
  {
    if (isEvenParity(head.data))
      head = null;

    return;
  }

  Node ptr = head;
  Node next;

/*  Traverse the list
  till the end*/

  do
  {
    next = ptr.next;

/*    If the node's data has
    even parity, delete node 'ptr'*/

    if (isEvenParity(ptr.data))
      deleteNode(head, ptr);

/*    Point to the next node*/

    ptr = next;

  } while (ptr != head);

  if (head == head.next)
  {
    if (isEvenParity(head.data))
      head = null;

    return;
  }
}

/*Function to print nodes in a
given Circular linked list*/

static void printList(Node head)
{
  if (head == null)
  {
    Console.Write("Empty List\n");
    return;
  }

  Node temp = head;
  if (head != null)
  {
    do
    {
      Console.Write(temp.data + " ");
      temp = temp.next;
    } while (temp != head);
  }
}

/*Driver code*/

public static void Main(String[] args)
{

/*  Initialize lists as empty*/

  Node head = null;

/*  Created linked list will be
  11.9.34.6.13.21*/

  head = push(head, 21);
  head = push(head, 13);
  head = push(head, 6);
  head = push(head, 34);
  head = push(head, 9);
  head = push(head, 11);

  deleteEvenParityNodes(head);
  printList(head);
}
}

/*C# program to remove all
the Even Digit Sum Nodes from a
circular singly linked list*/

using System;
class GFG{

/*Structure for a node*/

class Node
{
  public int data;
  public Node next;
};

/*Function to insert a node
at the beginning of a
Circular linked list*/

static Node push(Node head_ref,
                 int data)
{

/*  Create a new node and make head
  as next of it.*/

  Node ptr1 = new Node();

  Node temp = head_ref;
  ptr1.data = data;
  ptr1.next = head_ref;

/*  If linked list is not null then
  set the next of last node*/

  if (head_ref != null)
  {

/*    Find the node before head
    and update next of it.*/

    while (temp.next != head_ref)
      temp = temp.next;

    temp.next = ptr1;
  }
  else

/*    Point for the first node*/

    ptr1.next = ptr1;

  head_ref = ptr1;
  return head_ref;
}

/*Function to delete the node from a
Circular Linked list*/

static void deleteNode(Node head_ref,
                       Node del)
{
  Node temp = head_ref;

/*  If node to be deleted is head node*/

  if (head_ref == del)
    head_ref = del.next;

/*  Traverse list till not found
  delete node*/

  while (temp.next != del)
  {
    temp = temp.next;
  }

/*  Copy the address of the node*/

  temp.next = del.next;

/*  Finally, free the memory
  occupied by del*/

  del = null;

  return;
}

/*Function to find the digit sum
for a number*/

static int digitSum(int num)
{
  int sum = 0;

  while (num > 0)
  {
    sum += (num % 10);
    num /= 10;
  }
  return sum;
}

/*Function to delete all the Even Digit
Sum Nodes from the singly circular
linked list*/

static void deleteEvenDigitSumNodes(Node head)
{
  Node ptr = head;
  Node next;

/*  Traverse the list till the end*/

  do
  {

/*    If the node's data is Fibonacci,
    delete node 'ptr'*/

    if (!(digitSum(ptr.data) % 2 == 1))
      deleteNode(head, ptr);

/*    Point to the next node*/

    next = ptr.next;
    ptr = next;
  } while (ptr != head);
}

/*Function to print nodes in a
given Circular linked list*/

static void printList(Node head)
{
  Node temp = head;
  if (head != null)
  {
    do
    {
      Console.Write("{0} ",
                    temp.data);
      temp = temp.next;
    } while (temp != head);
  }
}

/*Driver code*/

public static void Main(String[] args)
{

/*  Initialize lists as empty*/

  Node head = null;

/*  Created linked list will be
  9.11.34.6.13.21*/

  head = push(head, 21);
  head = push(head, 13);
  head = push(head, 6);
  head = push(head, 34);
  head = push(head, 11);
  head = push(head, 9);

  deleteEvenDigitSumNodes(head);
  printList(head);
}
}

/*C# program to delete all the
Fibonacci nodes from the
circular singly linked list*/

using System;
using System.Collections.Generic;

class GFG{

/*Structure for a node*/

class Node {
    public int data;
    public Node next;
};

/*Function to insert a node at the beginning
of a Circular linked list*/

static Node push(Node head_ref, int data)
{

/*    Create a new node and make head as next
    of it.*/

    Node ptr1 = new Node();
    Node temp = head_ref;
    ptr1.data = data;
    ptr1.next = head_ref;

/*    If linked list is not null then
    set the next of last node*/

    if (head_ref != null) {

/*        Find the node before head
        and update next of it.*/

        while (temp.next != head_ref)
            temp = temp.next;

        temp.next = ptr1;
    }
    else

/*        Point for the first node*/

        ptr1.next = ptr1;

    head_ref = ptr1;
    return head_ref;
}

/*Delete the node from a Circular Linked list*/

static void deleteNode(Node head_ref, Node del)
{
    Node temp = head_ref;

/*    If node to be deleted is head node*/

    if (head_ref == del)
        head_ref = del.next;

/*    Traverse list till not found
    delete node*/

    while (temp.next != del) {
        temp = temp.next;
    }

/*    Copy the address of the node*/

    temp.next = del.next;

/*    Finally, free the memory
    occupied by del*/

    del = null;

    return;
}

/*Function to find the maximum
node of the circular linked list*/

static int largestElement(Node head_ref)
{

/*    Pointer for traversing*/

    Node current;

/*    Initialize head to the current pointer*/

    current = head_ref;

/*    Initialize min int value to max*/

    int maxEle = int.MinValue;

/*    While the last node is not reached*/

    do {

/*        If current node data is
        greater for max then replace it*/

        if (current.data > maxEle) {
            maxEle = current.data;
        }

        current = current.next;
    } while (current != head_ref);

    return maxEle;
}

/*Function to create hash table to
check Fibonacci numbers*/

static void createHash(HashSet<int> hash,
                int maxElement)
{
    int prev = 0, curr = 1;

/*    Adding the first two elements
    to the hash*/

    hash.Add(prev);
    hash.Add(curr);

/*    Inserting the Fibonacci numbers
    into the hash*/

    while (curr <= maxElement) {
        int temp = curr + prev;
        hash.Add(temp);
        prev = curr;
        curr = temp;
    }
}

/*Function to delete all the Fibonacci nodes
from the singly circular linked list*/

static void deleteFibonacciNodes(Node head)
{

/*    Find the largest node value
    in Circular Linked List*/

    int maxEle = largestElement(head);

/*    Creating a hash containing
    all the Fibonacci numbers
    upto the maximum data value
    in the circular linked list*/

    HashSet<int> hash = new HashSet<int>();
    createHash(hash, maxEle);

    Node ptr = head;

    Node next;

/*    Traverse the list till the end*/

    do {

/*        If the node's data is Fibonacci,
        delete node 'ptr'*/

        if (hash.Contains(ptr.data))
            deleteNode(head, ptr);

/*        Point to the next node*/

        next = ptr.next;
        ptr = next;

    } while (ptr != head);
}

/*Function to print nodes in a
given Circular linked list*/

static void printList(Node head)
{
    Node temp = head;
    if (head != null) {
        do {
            Console.Write("{0} ", temp.data);
            temp = temp.next;
        } while (temp != head);
    }
}

/*Driver code*/

public static void Main(String[] args)
{

/*    Initialize lists as empty*/

    Node head = null;

/*    Created linked list will be
    9.11.34.6.13.20*/

    head = push(head, 20);
    head = push(head, 13);
    head = push(head, 6);
    head = push(head, 34);
    head = push(head, 11);
    head = push(head, 9);

    deleteFibonacciNodes(head);

    printList(head);
}
}

/*C# program to delete all prime
node from a Circular singly linked list*/

using System;

class GFG {

/*    Structure for a node*/

    public class Node {
        public int data;
        public Node next;
    };

/*    Function to insert a node at the beginning
    of a Circular linked list*/

    static Node push(Node head_ref, int data)
    {
        Node ptr1 = new Node();
        Node temp = head_ref;
        ptr1.data = data;
        ptr1.next = head_ref;

/*        If linked list is not null then
        set the next of last node*/

        if (head_ref != null) {
            while (temp.next != head_ref)
                temp = temp.next;
            temp.next = ptr1;
            return head_ref;
        }
        else

/*            For the first node*/

            ptr1.next = ptr1;

        head_ref = ptr1;
        return head_ref;
    }

/*    Delete the node if it is odd*/

    static Node deleteNode(Node head_ref, Node del)
    {
        Node temp = head_ref;

/*        If node to be deleted is head node*/

        if (head_ref == del)
            head_ref = del.next;

/*        Traverse list till not found
        delete node*/

        while (temp.next != del) {
            temp = temp.next;
        }

/*        copy address of node*/

        temp.next = del.next;

        return head_ref;
    }

/*    Function to delete all odd nodes
    from the singly circular linked list*/

    static Node deleteoddNodes(Node head)
    {
        Node ptr = head;

        Node next;

/*        Traverse list till the end
        if the node is odd then delete it*/

        do {

/*            If node is odd*/

            if (ptr.data % 2 == 1)
                deleteNode(head, ptr);

/*            Point to next node*/

            next = ptr.next;
            ptr = next;
        } while (ptr != head);
        return head;
    }

/*    Function to print nodes*/

    static void printList(Node head)
    {
        Node temp = head;
        if (head != null) {
            do {
                Console.Write("{0} ", temp.data);
                temp = temp.next;
            } while (temp != head);
        }
    }

/*    Driver code*/

    public static void Main(String[] args)
    {

/*        Initialize lists as empty*/

        Node head = null;

/*        Created linked list will be 56->61->57->11->12->2*/

        head = push(head, 2);
        head = push(head, 12);
        head = push(head, 11);
        head = push(head, 57);
        head = push(head, 61);
        head = push(head, 56);

        Console.WriteLine("\nList after deletion : ");
        head = deleteoddNodes(head);
        printList(head);
    }
}

/*C# implementation of the approach*/

using System;

class GFG
{

/*Node structure*/

public class Node
{
    public Node next;
    public int data;
};

/*Function to create a node*/

static Node create()
{
    Node new_node = new Node();
    new_node.next = null;

    return new_node;
}

/*Function to find and return the head*/

static Node find_head(Node random)
{

/*    If the list is empty*/

    if (random == null)
        return null;

    Node var = random;

/*    Finding the last node of the linked list
    the last node must have the highest value
    if no such element is present then all the nodes
    of the linked list must be same*/

    while (!(var.data > var.next.data ||
                        var.next == random))
    {
        var = var.next;
    }

/*    Return the head*/

    return var.next;
}

/*Function to insert a new_node in the list
in sorted fashion. Note that this function
expects a pointer to head node as this can
modify the head of the input linked list*/

static Node sortedInsert(Node head_ref,
                        Node new_node)
{
    Node current = head_ref;

/*    If the list is empty*/

    if (current == null)
    {
        new_node.next = new_node;
        head_ref = new_node;
    }

/*    If the node to be inserted is the smallest
    then it has to be the new head*/

    else if (current.data >= new_node.data)
    {

/*        Find the last node of the list as it
        will be pointing to the head*/

        while (current.next != head_ref)
            current = current.next;
        current.next = new_node;
        new_node.next = head_ref;
        head_ref = new_node;
    }

    else
    {

/*        Locate the node before the point of insertion*/

        while (current.next != head_ref &&
            current.next.data < new_node.data)
        {
            current = current.next;
        }
        new_node.next = current.next;
        current.next = new_node;
    }

/*    Return the new head*/

    return head_ref;
}

/*Function to print the nodes of the linked list*/

static void printList(Node start)
{
    Node temp;

    if (start != null)
    {
        temp = start;
        do
        {
            Console.Write(temp.data + " ");
            temp = temp.next;
        } while (temp != start);
    }
}

/*Driver code*/

public static void Main(String []args)
{

    int []arr = { 12, 56, 2, 11, 1, 90 };
    int i;

/*    Start with an empty linked list*/

    Node start = null;
    Node temp;

/*    Create linked list from the given array*/

    for (i = 0; i < 6; i++)
    {

/*        Move to a random node if it exists*/

        if (start != null)
            for (int j = 0;
                    j < (new Random().Next() * 10); j++)
                start = start.next;

        temp = create();
        temp.data = arr[i];
        start = sortedInsert(find_head(start), temp);
    }

/*    Print the contents of the created list*/

    printList(find_head(start));
}
}

/*C# implementation of the approach*/

using System;

public class CircularLinkedList
{

    public Node last;

    public class Node
    {
        public int data;
        public Node next;
    };

/*    Function to add a node to the empty list*/

    public Node addToEmpty(int data)
    {

/*        If not empty*/

        if (this.last != null)
            return this.last;

/*        Creating a node dynamically*/

        Node temp = new Node();

/*        Assigning the data*/

        temp.data = data;
        this.last = temp;

/*        Creating the link*/

        this.last.next = this.last;

        return last;
    }

/*    Function to add a node to the
    beginning of the list*/

    public Node addBegin(int data)
    {

/*        If list is empty*/

        if (last == null)
            return addToEmpty(data);

/*        Create node*/

        Node temp = new Node();

/*        Assign data*/

        temp.data = data;
        temp.next = this.last.next;
        this.last.next = temp;

        return this.last;
    }

/*    Function to traverse and print the list*/

    public void traverse()
    {
        Node p;

/*        If list is empty*/

        if (this.last == null)
        {
            Console.WriteLine("List is empty.");
            return;
        }

/*        Pointing to the first Node of the list*/

        p = this.last.next;

/*        Traversing the list*/

        do
        {
            Console.Write(p.data + " ");
            p = p.next;
        } while (p != this.last.next);

        Console.WriteLine("");
    }

/*    Function to find the length of the CircularLinkedList*/

    public int length()
    {

/*        Stores the length*/

        int x = 0;

/*        List is empty*/

        if (this.last == null)
            return x;

/*        Iterator Node to traverse the List*/

        Node itr = this.last.next;
        while (itr.next != this.last.next)
        {
            x++;
            itr = itr.next;
        }

/*        Return the length of the list*/

        return (x + 1);
    }

/*    Function to split the first k nodes into
    a new CircularLinkedList and the remaining
    nodes stay in the original CircularLinkedList*/

    public Node split(int k)
    {

/*        Empty Node for reference*/

        Node pass = new Node();

/*        Check if the list is empty
        If yes, then return null*/

        if (this.last == null)
            return this.last;

/*        NewLast will contain the last node of
        the new split list
        itr to iterate the node till
        the required node*/

        Node newLast, itr = this.last;
        for (int i = 0; i < k; i++)
        {
            itr = itr.next;
        }

/*        Update NewLast to the required node and
        link the last to the start of rest of the list*/

        newLast = itr;
        pass.next = itr.next;
        newLast.next = this.last.next;
        this.last.next = pass.next;

/*        Return the last node of the required list*/

        return newLast;
    }

/*    Driver code*/

    public static void Main(String[] args)
    {
        CircularLinkedList clist = new CircularLinkedList();
        clist.last = null;

        clist.addToEmpty(12);
        clist.addBegin(10);
        clist.addBegin(8);
        clist.addBegin(6);
        clist.addBegin(4);
        clist.addBegin(2);
        Console.WriteLine("Original list:");
        clist.traverse();

        int k = 4;

/*        Create a new list for the starting k nodes*/

        CircularLinkedList clist2 = new CircularLinkedList();

/*        Append the new last node into the new list*/

        clist2.last = clist.split(k);

/*        Print the new lists*/

        Console.WriteLine("The new lists are:");
        clist2.traverse();
        clist.traverse();
    }
}

/*C# program for conversion
of Binary Tree to CDLL*/

using System;
using System.Collections.Generic;

class GFG
{

/*A binary tree node has data,
and left and right pointers*/

public class Node
{
    public int data;
    public Node left;
    public Node right;

    public Node(int x)
    {
        data = x;
        left = right = null;
    }
};

/*Function to perform In-Order traversal of the
tree and store the nodes in a vector*/

static void inorder(Node root, List<int> v)
{
    if (root == null)
        return;

/* first recur on left child */

    inorder(root.left, v);

/* append the data of node in vector */

    v.Add(root.data);

/* now recur on right child */

    inorder(root.right, v);
}

/*Function to convert Binary Tree to Circular
Doubly Linked list using the vector which stores
In-Order traversal of the Binary Tree*/

static Node bTreeToCList(Node root)
{

/*    Base cases*/

    if (root == null)
        return null;

/*    Vector to be used for storing the nodes
    of tree in In-order form*/

    List<int> v = new List<int>();

/*    Calling the In-Order traversal function*/

    inorder(root, v);

/*    Create the head of the linked list
    pointing to the root of the tree*/

    Node head_ref = new Node(v[0]);

/*    Create a current pointer
    to be used in traversal*/

    Node curr = head_ref;

/*    Traversing the nodes of the tree starting
    from the second elements*/

    for (int i = 1; i < v.Count; i++)
    {

/*        Create a temporary pointer
        pointing to current*/

        Node temp = curr;

/*        Current's right points to the current
        node in traversal*/

        curr.right = new Node(v[i]);

/*        Current points to its right*/

        curr = curr.right;

/*        Current's left points to temp*/

        curr.left = temp;
    }

/*    Current's right points to head of the list*/

    curr.right = head_ref;

/*    Head's left points to current*/

    head_ref.left = curr;

/*    Return head of the list*/

    return head_ref;
}

/*Display Circular Link List*/

static void displayCList(Node head)
{
    Console.WriteLine("Circular Doubly " +
                      "Linked List is :");

    Node itr = head;
    do
    {
        Console.Write(itr.data + " ");
        itr = itr.right;
    } while (head != itr);

    Console.WriteLine();
}

/*Driver Code*/

public static void Main(String[] args)
{
    Node root = new Node(10);
    root.left = new Node(12);
    root.right = new Node(15);
    root.left.left = new Node(25);
    root.left.right = new Node(30);
    root.right.left = new Node(36);

    Node head = bTreeToCList(root);
    displayCList(head);
}
}

/*C# program to delete all even and
odd position nodes from
Singly Circular Linked list*/

using System;

class GFG
{

/*structure for a node*/

class Node
{
    public int data;
    public Node next;
};

/*Function return number of nodes
present in list*/

static int Length(Node head)
{
    Node current = head;
    int count = 0;

/*    if list is empty simply return
    length zero*/

    if (head == null)
    {
        return 0;
    }

/*    traverse forst to last node*/

    else
    {
        do
        {
            current = current.next;
            count++;
        } while (current != head);
    }
    return count;
}

/*Function print data of list*/

static void Display( Node head)
{
    Node current = head;

/*    if list is empty simply show message*/

    if (head == null)
    {
        Console.Write("\nDisplay List is empty\n");
        return;
    }

/*    traverse forst to last node*/

    else
    {
        do
        {
            Console.Write("{0} ", current.data);
            current = current.next;
        } while (current != head);
    }
}

/* Function to insert a node at the end of
a Circular linked list */

static Node Insert(Node head, int data)
{
    Node current = head;

/*    Create a new node*/

    Node newNode = new Node();

/*    check node is created or not*/

    if (newNode == null)
    {
        Console.Write("\nMemory Error\n");
        return null;
    }

/*    insert data into newly created node*/

    newNode.data = data;

/*    check list is empty
    if not have any node then
    make first node it*/

    if (head == null)
    {
        newNode.next = newNode;
        head = newNode;
        return head;
    }

/*    if list have already some node*/

    else
    {

/*        move firt node to last node*/

        while (current.next != head)
        {
            current = current.next;
        }

/*        put first or head node address
        in new node link*/

        newNode.next = head;

/*        put new node address into
        last node link(next)*/

        current.next = newNode;
    }
    return head;
}

/*Utitlity function to delete a Node*/

static Node deleteNode(Node head_ref,
                       Node del)
{
    Node temp = head_ref;

/*    If node to be deleted is head node*/

    if (head_ref == del)
    {
        head_ref = del.next;
    }

/*    traverse list till not found
    delete node*/

    while (temp.next != del)
    {
        temp = temp.next;
    }

/*    copy address of node*/

    temp.next = del.next;
    return head_ref;
}

/*Function to delete First node of
Circular Linked List*/

static Node DeleteFirst(Node head)
{
    Node previous = head, next = head;

/*    check list have any node
    if not then return*/

    if (head == null)
    {
        Console.Write("\nList is empty\n");
        return head;
    }

/*    check list have single node
    if yes then delete it and return*/

    if (previous.next == previous)
    {
        head = null;
        return head;
    }

/*    traverse second to first*/

    while (previous.next != head)
    {
        previous = previous.next;
        next = previous.next;
    }

/*    now previous is last node and
    next is first node of list
    first node(next) link address
    put in last node(previous) link*/

    previous.next = next.next;

/*    make second node as head node*/

    head = previous.next;
    return head;
}

/*Function to delete odd position nodes*/

static Node DeleteAllOddNode(Node head)
{
    int len = Length(head);
    int count = 0;
    Node previous = head, next = head;

/*    check list have any node
    if not then return*/

    if (head == null)
    {
        Console.Write("\nDelete Last List is empty\n");
        return null;
    }

/*    if list have single node means
    odd position then delete it*/

    if (len == 1)
    {
        head = DeleteFirst(head);
        return head;
    }

/*    traverse first to last if
    list have more than one node*/

    while (len > 0)
    {

/*        delete first position node
        which is odd position*/

        if (count == 0)
        {

/*            Function to delete first node*/

            head = DeleteFirst(head);
        }

/*        check position is odd or not
        if yes then delete node
        Note: Considered 1 based indexing*/

        if (count % 2 == 0 && count != 0)
        {
            head = deleteNode(head, previous);
        }

        previous = previous.next;
        next = previous.next;

        len--;
        count++;
    }
    return head;
}

/*Function to delete all even position nodes*/

static Node DeleteAllEvenNode( Node head)
{

/*    Take size of list*/

    int len = Length(head);

    int count = 1;
    Node previous = head, next = head;

/*    Check list is empty
    if empty simply return*/

    if (head == null)
    {
        Console.Write("\nList is empty\n");
        return null;
    }

/*    if list have single node
    then return*/

    if (len < 2)
    {
        return null;
    }

/*    make first node is previous*/

    previous = head;

/*    make second node is current*/

    next = previous.next;

    while (len > 0)
    {

/*        check node number is even
        if node is even then
        delete that node*/

        if (count % 2 == 0)
        {
            previous.next = next.next;
            previous = next.next;
            next = previous.next;
        }

        len--;
        count++;
    }
    return head;
}

/*Driver Code*/

public static void Main(String []args)
{
    Node head = null;
    head = Insert(head, 99);
    head = Insert(head, 11);
    head = Insert(head, 22);
    head = Insert(head, 33);
    head = Insert(head, 44);
    head = Insert(head, 55);
    head = Insert(head, 66);

/*    Deleting Odd positioned nodes*/

    Console.Write("Initial List: ");
    Display(head);

    Console.Write("\nAfter deleting Odd position nodes: ");
    head = DeleteAllOddNode(head);
    Display(head);

/*    Deleting Even positioned nodes*/

    Console.Write("\n\nInitial List: ");
    Display(head);

    Console.Write("\nAfter deleting even position nodes: ");
    head = DeleteAllEvenNode(head);
    Display(head);
}
}

/*C# program to delete node at different
positions from a circular linked list*/

using System;

class GFG
{

/*structure for a node*/

class Node
{
    public int data;
    public Node next;
};

/*Function to insert a node at the end of
a Circular linked list*/

static Node Insert(Node head, int data)
{
    Node current = head;

/*    Create a new node*/

    Node newNode = new Node();

/*    check node is created or not*/

    if (newNode == null)
    {
        Console.Write("\nMemory Error\n");
        return null;
    }

/*    insert data into newly created node*/

    newNode.data = data;

/*    check list is empty
    if not have any node then
    make first node it*/

    if (head == null)
    {
        newNode.next = newNode;
        head = newNode;
        return head;
    }

/*    if list have already some node*/

    else
    {

/*        move first node to last node*/

        while (current.next != head)
        {
            current = current.next;
        }

/*        put first or head node address
        in new node link*/

        newNode.next = head;

/*        put new node address into last
        node link(next)*/

        current.next = newNode;
    }
    return head;
}

/*Function print data of list*/

static void Display( Node head)
{
    Node current = head;

/*    if list is empty, simply show message*/

    if (head == null)
    {
        Console.Write("\nDisplay List is empty\n");
        return;
    }

/*    traverse first to last node*/

    else
    {
        do
        {
            Console.Write("{0} ", current.data);
            current = current.next;
        } while (current != head);
    }
}

/*Function return number of nodes present in list*/

static int Length(Node head)
{
    Node current = head;
    int count = 0;

/*    if list is empty
    simply return length zero*/

    if (head == null)
    {
        return 0;
    }

/*    traverse forst to last node*/

    else
    {
        do
        {
            current = current.next;
            count++;
        } while (current != head);
    }
    return count;
}

/*Function delete First node of
Circular Linked List*/

static Node DeleteFirst(Node head)
{
    Node previous = head, next = head;

/*    check list have any node
    if not then return*/

    if (head == null)
    {
        Console.Write("\nList is empty\n");
        return null;
    }

/*    check list have single node
    if yes then delete it and return*/

    if (previous.next == previous)
    {
        head = null;
        return null;
    }

/*    traverse second to first*/

    while (previous.next != head)
    {
        previous = previous.next;
        next = previous.next;
    }

/*    now previous is last node and
    next is first node of list
    first node(next) link address
    put in last node(previous) link*/

    previous.next = next.next;

/*    make second node as head node*/

    head = previous.next;

    return head;
}

/*Function to delete last node of
Circular Linked List*/

static Node DeleteLast(Node head)
{
    Node current = head, temp = head, previous = null;

/*    check if list doesn't have any node
    if not then return*/

    if (head == null)
    {
        Console.Write("\nList is empty\n");
        return null;
    }

/*    check if list have single node
    if yes then delete it and return*/

    if (current.next == current)
    {
        head = null;
        return null;
    }

/*    move first node to last
    previous*/

    while (current.next != head)
    {
        previous = current;
        current = current.next;
    }

    previous.next = current.next;
    head = previous.next;

    return head;
}

/*Function delete node at a given poisition
of Circular Linked List*/

static Node DeleteAtPosition( Node head, int index)
{

/*    Find length of list*/

    int len = Length(head);
    int count = 1;
    Node previous = head, next = head;

/*    check list have any node
    if not then return*/

    if (head == null)
    {
        Console.Write("\nDelete Last List is empty\n");
        return null;
    }

/*    given index is in list or not*/

    if (index >= len || index < 0)
    {
        Console.Write("\nIndex is not Found\n");
        return null;
    }

/*    delete first node*/

    if (index == 0)
    {
        head = DeleteFirst(head);
        return head;
    }

/*    traverse first to last node*/

    while (len > 0)
    {

/*        if index found delete that node*/

        if (index == count)
        {
            previous.next = next.next;

            return head;
        }
        previous = previous.next;
        next = previous.next;
        len--;
        count++;
    }
    return head;
}

/*Driver Code*/

public static void Main(String []args)
{
    Node head = null;
    head = Insert(head, 99);
    head = Insert(head, 11);
    head = Insert(head, 22);
    head = Insert(head, 33);
    head = Insert(head, 44);
    head = Insert(head, 55);
    head = Insert(head, 66);

/*    Deleting Node at position*/

    Console.Write("Initial List: ");
    Display(head);
    Console.Write("\nAfter Deleting node at index 4: ");
    head = DeleteAtPosition(head, 4);
    Display(head);

/*    Deleting first Node*/

    Console.Write("\n\nInitial List: ");
    Display(head);
    Console.Write("\nAfter Deleting first node: ");
    head = DeleteFirst(head);
    Display(head);

/*    Deleting last Node*/

    Console.Write("\n\nInitial List: ");
    Display(head);
    Console.Write("\nAfter Deleting last node: ");
    head = DeleteLast(head);
    Display(head);
}
}

/*C# program to find minimum and maximum
value from singly circular linked list*/

using System;

class GFG
{

